import threading

#define MAX_PACKET_SIZE 1500
#define MIN_PACKET_SIZE 64
#define ALIGNMENT 4

typedef struct {
    unsigned int header_length;
    unsigned char* payload;
    unsigned int metadata[5];
} Packet;

typedef struct {
    Packet** packets;
    size_t count;
    size_t capacity;
    threading.Lock lock;
} PacketArray;

void initialize_packet_array(PacketArray* array, size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_PACKET_SIZE / sizeof(Packet*)) {
        fprintf(stderr, "Invalid initial capacity.\n");
        return;
    }

    array->packets = malloc(initial_capacity * sizeof(Packet*));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed for packet array.\n");
        exit(EXIT_FAILURE);
    }

    array->count = 0;
    array->capacity = initial_capacity;
    threading.Lock_init(&array->lock);

    for (size_t i = 0; i < initial_capacity; ++i) {
        array->packets[i] = NULL;
    }
}

int add_packet(PacketArray* array, unsigned int header_length, unsigned char* payload_data, size_t payload_size) {
    if (header_length + payload_size < MIN_PACKET_SIZE || header_length + payload_size > MAX_PACKET_SIZE) {
        fprintf(stderr, "Packet size out of bounds.\n");
        return -1;
    }

    // Padding for alignment
    size_t padding = (ALIGNMENT - (payload_size % ALIGNMENT)) % ALIGNMENT;
    size_t total_payload_size = payload_size + padding;

    Packet* packet = malloc(sizeof(Packet));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed for a new packet.\n");
        return -1;
    }

    packet->header_length = header_length;
    packet->payload = (unsigned char*)malloc(total_payload_size);
    if (!packet->payload) {
        free(packet);
        fprintf(stderr, "Memory allocation failed for payload.\n");
        return -1;
    }

    // Copy and align payload
    memcpy(packet->payload, payload_data, payload_size);
    memset(packet->payload + payload_size, 0, padding);

    // Fill in metadata as needed (e.g., timestamps, sequence numbers)
