    // Set other metadata fields...

    threading.Lock_acquire(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet** temp = realloc(array->packets, new_capacity * sizeof(Packet*));
        if (!temp) {
            free(packet->payload);
            free(packet);
            threading.Lock_release(&array->lock);
            fprintf(stderr, "Memory reallocation failed for packet array.\n");
            return -1;
