typedef enum { OFFSET_TYPE, KEY_TYPE } RecordType;

typedef struct {
    RecordType type;
    union {
        long offset;
        int key;
    } value;
} Record;

void log_memory_usage(size_t current_usage, size_t budget) {
    printf("Current Memory Usage: %zu bytes, Budget: %zu bytes\n", current_usage, budget);
}

size_t calculate_record_size(RecordType type) {
    return sizeof(Record); // Both types use the same structure size
}

Record* allocate_records(size_t *count, RecordType type, size_t budget, size_t record_size) {
    if (*count == 0 || budget < record_size) {
        return NULL;
    }

    size_t total_records = budget / record_size;
    if (total_records > *count) {
        total_records = *count;
    }

    Record *records = malloc(total_records * record_size);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < total_records; ++i) {
        records[i].type = type;

        if (type == OFFSET_TYPE) {
            // Simulate potential integer overflow
            records[i].value.offset = rand() % INT_MAX + 1;
        } else {
            records[i].value.key = rand() % INT_MAX + 1;
        }
    }

    *count = total_records;
    return records;
}

void free_records(Record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    srand(time(NULL));

    size_t budget = 1024 * 1024; // 1 MB budget
    size_t record_count = 1000;
    size_t record_size = calculate_record_size(OFFSET_TYPE);

    RecordType type = OFFSET_TYPE; // Can be changed to KEY_TYPE

    Record* records = allocate_records(&record_count, type, budget, record_size);

    if (records) {
        log_memory_usage(record_count * record_size, budget);

        // Use the allocated records...

        free_records(records);
    }

    return 0;
}
