#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define BUFFER_SIZE 1024

void print_usage() {
    printf("Usage: program [options] input_file\n"
           "Options:\n"
           "  -h, --help        Display this help message.\n"
           "  --manpage         Provide comprehensive documentation.\n"
           "  -cs               Apply a basic character substitution cipher.\n"
           "  -o output_file    Specify an output file for processed content.\n"
           "  -v                Enable verbose mode for detailed logs.\n");
}

void print_manpage() {
    printf("Program: Line Counter\n"
           "\n"
           "DESCRIPTION:\n"
           "This program reads a specified input file line by line and prints the number of lines.\n"
           "It supports various command-line options to modify its behavior.\n"
           "\n"
           "OPTIONS:\n"
           "  -h, --help        Display this help message.\n"
           "  --manpage         Provide comprehensive documentation.\n"
           "  -cs               Apply a basic character substitution cipher to each line.\n"
           "  -o output_file    Specify an output file for processed content.\n"
           "  -v                Enable verbose mode for detailed logs.\n");
}

void apply_cipher(char *line) {
    while (*line) {
        if (isalpha((unsigned char)*line))
            *line = ((*line - 'a' + 3) % 26) + 'a'; // Basic Caesar cipher
        line++;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    FILE *input_file = NULL, *output_file = NULL;
    char *output_filename = NULL;
    int verbose = 0, apply_cipher_flag = 0;
    size_t lines_count = 0;

    while ((opt = getopt(argc, argv, "hco:vs")) != -1) {
        switch (opt) {
            case 'h':
                print_usage();
                return 0;
            case 'c':
                apply_cipher_flag = 1;
                break;
            case 'o':
                output_filename = optarg;
                break;
            case 'v':
                verbose = 1;
                break;
            case '?':
                if (strcmp(argv[optind - 1], "--manpage") == 0) {
                    print_manpage();
                } else {
                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                }
                return 1;
        }
    }

    if (optind >= argc || argv[optind][0] == '-') {
        fprintf(stderr, "Error: No input file specified.\n");
        print_usage();
        return 1;
    }

    char *input_filename = argv[optind];
    input_file = fopen(input_filename, "r");

    if (!input_file) {
        perror("Error opening input file");
        return 1;
    }

    if (output_filename) {
        output_file = fopen(output_filename, "w");
        if (!output_file) {
            perror("Error creating output file");
            fclose(input_file);
            return 1;
        }
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, input_file)) {
        lines_count++;
        if (apply_cipher_flag) {
            apply_cipher(buffer);
        }
        if (output_file) {
            fputs(buffer, output_file);
        }
        if (verbose) {
            printf("Processed line: %s", buffer);
        }
    }

    if (input_file)
        fclose(input_file);

    if (output_file) {
        fprintf(output_file, "\nNumber of lines: %zu\n", lines_count);
        fclose(output_file);
    } else {
        printf("Number of lines: %zu\n", lines_count);
    }

    return 0;
}
