#include <stdio.h>
#include <stdlib.h>

// Function prototypes for sorting algorithm
void quicksort(int *arr, int low, int high);
int partition(int *arr, int low, int high);

// Median function prototype
double findMedian(int *arr, size_t n);

// Main processing function
void processInput() {
    char *line = NULL;
    size_t len = 0;

    // Read a line from stdin
    if (getline(&line, &len, stdin) == -1) {
        printf("Error reading input\n");
        free(line);
        return;
    }

    // Remove newline character at the end of the line
    for (size_t i = 0; i < len; ++i) {
        if (line[i] == '\n') {
            line[i] = '\0';
            break;
        }
    }

    // Handle empty input case
    if (len == 0 || (len == 1 && line[0] == '\0')) {
        printf("No data to process\n");
        free(line);
        return;
    }

    int *arr = NULL;
    size_t count = 0;

    // Parse integers from the input string
    char *token = strtok(line, " ");
    while (token != NULL) {
        arr = realloc(arr, sizeof(int) * (count + 1));
        if (!arr) {
            printf("Memory allocation error\n");
            free(line);
            return;
        }

        int num = atoi(token);
        arr[count++] = num;

        token = strtok(NULL, " ");
    }

    // Sort the array in descending order using quicksort
    quicksort(arr, 0, count - 1);

    // Find and print the median value
    double median = findMedian(arr, count);
    printf("Median: %.2f\n", median);

    // Free allocated memory
    free(arr);
    free(line);
}

// Quicksort implementation for sorting in descending order
void quicksort(int *arr, int low, int high) {
    if (low < high) {
        int pivotIndex = partition(arr, low, high);
        quicksort(arr, low, pivotIndex - 1);
        quicksort(arr, pivotIndex + 1, high);
    }
}

int partition(int *arr, int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] > pivot) { // Descending order
            i++;
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return (i + 1);
}

// Function to find the median of an array
double findMedian(int *arr, size_t n) {
    if (n % 2 == 0) {
        // Even number of elements, average the two middle values
        return ((double)arr[n / 2 - 1] + arr[n / 2]) / 2.0;
    } else {
        // Odd number of elements, return the middle value
        return (double)arr[n / 2];
    }
}

// Main function to invoke processInput
int main() {
    processInput();
    return 0;
}
