#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char *buffer;
    size_t head;
    size_t tail;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} CircularBuffer;

// Initialize the circular buffer with an initial capacity
void initCircularBuffer(CircularBuffer *cb, size_t initial_capacity) {
    cb->buffer = (char *)malloc(initial_capacity);
    if (!cb->buffer) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    cb->head = 0;
    cb->tail = 0;
    cb->capacity = initial_capacity;
    cb->size = 0;
    pthread_mutex_init(&cb->lock, NULL);
}

// Resize the buffer when necessary
void resizeBuffer(CircularBuffer *cb) {
    size_t new_capacity = cb->capacity * 2; // Exponential growth strategy
    char *new_buffer = (char *)realloc(cb->buffer, new_capacity);

    if (!new_buffer) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    // Copy existing data to the new buffer
    for (size_t i = 0; i < cb->size; ++i) {
        size_t index = (cb->head + i) % cb->capacity;
        new_buffer[i] = cb->buffer[index];
    }

    cb->buffer = new_buffer;
    cb->head = 0;
    cb->tail = cb->size;
    cb->capacity = new_capacity;
}

// Append a log entry to the buffer
void appendLog(CircularBuffer *cb, const char *log_entry) {
    size_t log_length = strlen(log_entry);

    pthread_mutex_lock(&cb->lock);

    // Check if we need to resize
    if (cb->size + log_length >= cb->capacity) {
        resizeBuffer(cb);
    }

    // Calculate the position to insert new data
    for (size_t i = 0; i < log_length; ++i) {
        size_t index = (cb->tail + i) % cb->capacity;
        cb->buffer[index] = log_entry[i];
    }

    cb->tail = (cb->tail + log_length) % cb->capacity;
    cb->size += log_length;

    pthread_mutex_unlock(&cb->lock);
}

// Clean up the circular buffer
void destroyCircularBuffer(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->lock);
}
```

This code implements a thread-safe circular buffer with dynamic resizing using an exponential growth strategy. It minimizes lock acquisition time by ensuring that critical sections are short, primarily locking only during the resize check and actual data modification operations. This reduces contention in write-heavy scenarios while maintaining efficient read access patterns due to the contiguous memory layout after resizing.']

