```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define KEY_SIZE_AES_128 16
#define KEY_SIZE_AES_256 32

typedef enum {
    MODE_HASH,
    MODE_HMAC
} HashMode;

typedef enum {
    HASH_SHA256,
    HASH_SHA512
} HashType;

typedef enum {
    ENCRYPTION_CBC,
    ENCRYPTION_GCM,
    ENCRYPTION_OFB
} EncryptionMode;

typedef struct KeyManager {
    unsigned char *key;
    size_t key_len;
} KeyManager;

KeyManager* generate_key(size_t key_size) {
    KeyManager *km = malloc(sizeof(KeyManager));
    if (!km || RAND_bytes(km->key = malloc(key_size), key_size) != 1) {
        free(km);
        return NULL;
    }
    km->key_len = key_size;
    return km;
}

void free_key_manager(KeyManager* km) {
    free(km->key);
    free(km);
}

int hash_data(const unsigned char *data, size_t data_len, HashType hash_type, 
              HashMode mode, const unsigned char *key, size_t key_len,
              unsigned char **out_hash, size_t *out_len) {

    EVP_MD_CTX *mdctx = NULL;
    int result = 0;

    if (mode == MODE_HASH) {
        mdctx = EVP_MD_CTX_new();
        if (!EVP_DigestInit_ex(mdctx, hash_type == HASH_SHA256 ? EVP_sha256() : EVP_sha512(), NULL)) goto end;
        if (!EVP_DigestUpdate(mdctx, data, data_len)) goto end;
    } else {
        mdctx = HMAC_CTX_new();
        if (!HMAC_Init_ex((HMAC_CTX *)mdctx, key, key_len, hash_type == HASH_SHA256 ? EVP_sha256() : EVP_sha512(), NULL)) goto end;
        if (!HMAC_Update((HMAC_CTX *)mdctx, data, data_len)) goto end;
    }

    *out_hash = malloc(EVP_MAX_MD_SIZE);
    if (!*out_hash) goto end;

    if (!EVP_DigestFinal_ex(mdctx, *out_hash, (unsigned int*)out_len)) goto end;

    result = 1;
end:
    if (mdctx) {
        EVP_MD_CTX_free(mdctx);
    }
    return result;
}

int encrypt_data(const unsigned char *plaintext, size_t plaintext_len,
                 const unsigned char *key, size_t key_len, EncryptionMode mode,
                 unsigned char **ciphertext, size_t *ciphertext_len) {

    EVP_CIPHER_CTX *ctx = NULL;
    int len, ciphertext_size = 0, tag_len = 16; // GCM/AES-GCM uses a 128-bit tag
    int result = 0;

    if (!RAND_bytes((unsigned char *)plaintext + plaintext_len, 12)) goto end; // GCM nonce

    ctx = EVP_CIPHER_CTX_new();
    if (mode == ENCRYPTION_GCM) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, plaintext + plaintext_len)) goto end;
    } else if (mode == ENCRYPTION_CBC || mode == ENCRYPTION_OFB) {
        int block_size = 16; // AES block size
        unsigned char iv[block_size];
        if (!RAND_bytes(iv, sizeof(iv))) goto end;

        if (mode == ENCRYPTION_CBC) {
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) goto end;
        } else {
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_128_ofb(), NULL, key, iv)) goto end;
        }
    }

    *ciphertext = malloc(plaintext_len + block_size);
    if (!*ciphertext) goto end;

    if (mode == ENCRYPTION_GCM) {
        ciphertext_size = plaintext_len + block_size; // Allocate space for GCM tag
    } else {
        ciphertext_size = plaintext_len;
    }

    if (!EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) goto end;
    ciphertext_size += len;

    if (mode == ENCRYPTION_GCM) {
        unsigned int tag_len_int;
        if (!EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, *ciphertext + ciphertext_size - block_size)) goto end;
        ciphertext_size += block_size; // Include the GCM tag in output
    } else {
        if (!EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len)) goto end;
        ciphertext_size += len;
    }

    *ciphertext_len = ciphertext_size;
    result = 1;

end:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    return result;
}

// Example usage
int main() {
    unsigned char data[] = "Sensitive data to encrypt and hash";
    size_t data_len = sizeof(data) - 1;

    KeyManager *km = generate_key(KEY_SIZE_AES_256);
    if (!km) {
        fprintf(stderr, "Failed to generate key\n");
        return EXIT_FAILURE;
    }

    unsigned char *hash_output;
    size_t hash_output_len;
    if (!hash_data(data, data_len, HASH_SHA512, MODE_HMAC, km->key, km->key_len,
                   &hash_output, &hash_output_len)) {
        fprintf(stderr, "Hashing failed\n");
        free_key_manager(km);
        return EXIT_FAILURE;
    }

    unsigned char *ciphertext;
    size_t ciphertext_len;
    if (!encrypt_data(data, data_len, km->key, KEY_SIZE_AES_256, ENCRYPTION_GCM,
                      &ciphertext, &ciphertext_len)) {
        fprintf(stderr, "Encryption failed\n");
        free_key_manager(km);
        return EXIT_FAILURE;
    }

    printf("Hash: ");
    for (size_t i = 0; i < hash_output_len; ++i) printf("%02x", hash_output[i]);
    printf("\n");

    printf("Encrypted data: ");
    for (size_t i = 0; i < ciphertext_len; ++i) printf("%02x", ciphertext[i]);
    printf("\n");

    free(hash_output);
    free(ciphertext);
    free_key_manager(km);

    return EXIT_SUCCESS;
}
```

### Key Features
- **Hashing and HMAC**: Supports SHA-256, SHA-512 for hashing and HMAC.
- **Symmetric Encryption**: Supports AES-128, AES-256 with CBC, GCM, OFB modes.
- **Key Management**: Secure key generation and management.
- **Error Handling**: Robust error handling in cryptographic operations.

### Documentation
To integrate this library into existing applications:
1. Include the necessary OpenSSL headers.
2. Link against OpenSSL libraries (`libssl`, `libcrypto`).
3. Initialize OpenSSL with `SSL_library_init()` if needed.
4. Use provided functions to perform hashing and encryption as per your requirements.
5. Handle any errors returned by cryptographic functions appropriately.

### Considerations
- Ensure OpenSSL is properly installed and configured on your system.
- This code assumes AES-256 for encryption; adjust key sizes for AES-128 as necessary.
- The library uses OpenSSL's EVP interfaces, which abstracts many platform-specific details, making it suitable for multiple platforms.']

