#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <dlfcn.h>
#include <errno.h>

// Define metadata and function pointer structures
typedef struct {
    char *name;
    size_t key_size;
    size_t block_size;
} CryptoMetadata;

typedef struct {
    CryptoMetadata meta;
    void *(*init)(void);
    int (*update)(void *, const uint8_t *, size_t, uint8_t *);
    int (*finalize)(void *, uint8_t *, size_t *);
    void (*cleanup)(void *);
} CryptoAlgorithm;

// Define a thread-safe hash table for storing algorithms
typedef struct {
    CryptoAlgorithm **algorithms;
    size_t count;
    pthread_mutex_t lock;
} AlgorithmTable;

// Function prototypes
AlgorithmTable *load_algorithms(const char *config_path);
int register_algorithm(AlgorithmTable *table, CryptoAlgorithm *algorithm);
CryptoAlgorithm *find_algorithm(AlgorithmTable *table, const char *name);
void free_algorithm_table(AlgorithmTable *table);

// Global algorithm table
static AlgorithmTable *global_table = NULL;
static pthread_once_t once_control = PTHREAD_ONCE_INIT;

#define INIT_ALGORITHM_TABLE() \
    do { \
        pthread_once(&once_control, initialize_algorithm_table); \
    } while (0)

void initialize_algorithm_table(void) {
    global_table = load_algorithms("config/path/to/your/config/file");
}

// Load algorithms from configuration
AlgorithmTable *load_algorithms(const char *config_path) {
    AlgorithmTable *table = malloc(sizeof(AlgorithmTable));
    pthread_mutex_init(&table->lock, NULL);
    table->count = 0;
    // Example: load configurations and dynamically load shared libraries
    // Add actual loading logic here based on configuration file
    return table;
}

// Register an algorithm in the global table
int register_algorithm(AlgorithmTable *table, CryptoAlgorithm *algorithm) {
    pthread_mutex_lock(&table->lock);
    if (table->count >= 10) { // Example limit
        pthread_mutex_unlock(&table->lock);
        return -1; // Table full or error condition
    }
    table->algorithms = realloc(table->algorithms, sizeof(CryptoAlgorithm *) * (table->count + 1));
    table->algorithms[table->count++] = algorithm;
    pthread_mutex_unlock(&table->lock);
    return 0;
}

// Find an algorithm by name in the global table
CryptoAlgorithm *find_algorithm(AlgorithmTable *table, const char *name) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->count; i++) {
        if (strcmp(table->algorithms[i]->meta.name, name) == 0) {
            pthread_mutex_unlock(&table->lock);
            return table->algorithms[i];
        }
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Free resources associated with the algorithm table
void free_algorithm_table(AlgorithmTable *table) {
    if (!table) return;
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->count; i++) {
        if (table->algorithms[i] && table->algorithms[i]->cleanup) {
            table->algorithms[i]->cleanup(table->algorithms[i]);
        }
    }
    free(table->algorithms);
    pthread_mutex_unlock(&table->lock);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Example usage
int main() {
    INIT_ALGORITHM_TABLE();

    // Example dynamic loading and registration of an algorithm
    void *handle = dlopen("path/to/shared/library.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return EXIT_FAILURE;
    }

    CryptoAlgorithm *algorithm = malloc(sizeof(CryptoAlgorithm));
    algorithm->meta.name = strdup("ExampleHash");
    algorithm->init = dlsym(handle, "example_init");
    algorithm->update = dlsym(handle, "example_update");
    algorithm->finalize = dlsym(handle, "example_finalize");
    algorithm->cleanup = dlsym(handle, "example_cleanup");

    if (!register_algorithm(global_table, algorithm)) {
        printf("Algorithm registered successfully.\n");
    } else {
        printf("Failed to register algorithm.\n");
    }

    // Example find and use
    CryptoAlgorithm *found_algo = find_algorithm(global_table, "ExampleHash");
    if (found_algo) {
        void *context = found_algo->init();
        uint8_t data[] = "sample";
        uint8_t output[64];
        size_t out_len;

        found_algo->update(context, data, sizeof(data), NULL);
        found_algo->finalize(context, output, &out_len);

        printf("Hash computed: ");
        for (size_t i = 0; i < out_len; ++i) {
            printf("%02x", output[i]);
        }
        printf("\n");

        found_algo->cleanup(context);
    }

    free_algorithm_table(global_table);
    dlclose(handle);
    return EXIT_SUCCESS;
}
```

