    void (*decrypt)(const uint8_t* data, size_t len, uint8_t* out, const uint8_t* key);
} encryption_algorithm_t;

// Example algorithm: Simple XOR (for demonstration purposes)
void xor_encrypt(const uint8_t* data, size_t len, uint8_t* out, const uint8_t* key) {
    for (size_t i = 0; i < len; ++i) {
        out[i] = data[i] ^ key[i % strlen((const char*)key)];
    }
}

void xor_decrypt(const uint8_t* data, size_t len, uint8_t* out, const uint8_t* key) {
    xor_encrypt(data, len, out, key); // Symmetric operation
}

encryption_algorithm_t xor_algorithm = {
    .encrypt = xor_encrypt,
    .decrypt = xor_decrypt
};

typedef struct {
    encryption_algorithm_t* algorithm;
    pthread_mutex_t lock;
} encryption_context_t;

// Initialize context for a specific algorithm
encryption_context_t* init_encryption_context(encryption_algorithm_t* algo) {
    encryption_context_t* ctx = (encryption_context_t*)malloc(sizeof(encryption_context_t));
    if (!ctx) return NULL;

    ctx->algorithm = algo;
    pthread_mutex_init(&ctx->lock, NULL);
    return ctx;
}

// Cleanup context
void cleanup_encryption_context(encryption_context_t* ctx) {
    if (ctx) {
        pthread_mutex_destroy(&ctx->lock);
        free(ctx);
    }
}

encryption_result_t encrypt_data(
    encryption_context_t* ctx,
    const uint8_t* data, size_t len,
    uint8_t** out, const uint8_t* key
) {
    *out = (uint8_t*)malloc(len);
    if (!*out) return ENCRYPTION_FAILURE;

    pthread_mutex_lock(&ctx->lock);
    ctx->algorithm->encrypt(data, len, *out, key);
    pthread_mutex_unlock(&ctx->lock);

    return ENCRYPTION_SUCCESS;
}

encryption_result_t decrypt_data(
    encryption_context_t* ctx,
    const uint8_t* data, size_t len,
    uint8_t** out, const uint8_t* key
) {
    *out = (uint8_t*)malloc(len);
    if (!*out) return DECRYPTION_FAILURE;

    pthread_mutex_lock(&ctx->lock);
    ctx->algorithm->decrypt(data, len, *out, key);
    pthread_mutex_unlock(&ctx->lock);

    return DECRYPTION_SUCCESS;
}

// Example usage
int main() {
    const char* data = "Hello World";
    uint8_t* encrypted_data;
    uint8_t* decrypted_data;

    encryption_context_t* ctx = init_encryption_context(&xor_algorithm);
    if (!ctx) {
        log_error("Failed to initialize context");
        return EXIT_FAILURE;
    }

    // Encryption
