        log_debug("Decryption successful");
        printf("Decrypted: %s\n", decrypted_data);
        free(decrypted_data);
    } else {
        log_error("Decryption failed");
    }

    cleanup_encryption_context(ctx);
    return EXIT_SUCCESS;
}
