['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <string.h>
#include <unistd.h>

typedef struct {
    sem_t *semaphores;
    int num_semaphores;
    pthread_mutex_t mutex;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int num_threads, int initial_values[], int num_semaphores) {
    if (num_threads <= 0 || num_semaphores <= 0 || !initial_values) return NULL;

    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) return NULL;

    manager->semaphores = malloc(num_semaphores * sizeof(sem_t));
    if (!manager->semaphores) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    for (int i = 0; i < num_semaphores; ++i) {
        sem_init(&manager->semaphores[i], 0, initial_values[i] > 0 ? initial_values[i] : 1);
    }

    manager->num_semaphores = num_semaphores;
    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (!manager) return;

    for (int i = 0; i < manager->num_semaphores; ++i) {
        sem_destroy(&manager->semaphores[i]);
    }

    free(manager->semaphores);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void adjust_semaphore(SemaphoreManager *manager, int semaphore_index, int adjustment) {
    if (!manager || semaphore_index < 0 || semaphore_index >= manager->num_semaphores) return;

    pthread_mutex_lock(&manager->mutex);
    sem_t *sem = &manager->semaphores[semaphore_index];
    int current_value;
    sem_getvalue(sem, &current_value);
    sem_init(sem, 0, current_value + adjustment);
    pthread_mutex_unlock(&manager->mutex);
}

void* worker_function(void *arg) {
    SemaphoreManager *manager = (SemaphoreManager*) arg;

    // Example operation using semaphore
    int index_to_use = rand() % manager->num_semaphores;
    sem_wait(&manager->semaphores[index_to_use]);

    // Perform work...

    sem_post(&manager->semaphores[index_to_use]);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <num_threads> <initial_values...>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_threads = atoi(argv[1]);
    int initial_values_count = argc - 2;
    int *initial_values = malloc(initial_values_count * sizeof(int));
    if (!initial_values) {
        fprintf(stderr, "Memory allocation error\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < initial_values_count; ++i) {
        initial_values[i] = atoi(argv[i + 2]);
    }

    SemaphoreManager *manager = create_semaphore_manager(num_threads, initial_values, initial_values_count);
    if (!manager) {
        fprintf(stderr, "Failed to create semaphore manager\n");
        free(initial_values);
        return EXIT_FAILURE;
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, worker_function, manager);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore_manager(manager);
    free(initial_values);

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a semaphore manager in C. It allows for dynamic creation and destruction of semaphores based on runtime configuration, with thread-safe access using mutexes. The `adjust_semaphore` function lets you modify the semaphore value during execution, demonstrating adaptive resource management. This setup aims to balance concurrency with resource utilization while ensuring proper cleanup in case of errors or termination.']

['```rust
use hyper::{Body, Request, Response, Server, service::{make_service_fn, service_fn}};
use hyper::header::{CONTENT_TYPE, LOCATION};
use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::sync::Mutex;
use url::form_urlencoded;
use log::{info, error};
use serde_json::json;

// Initialize a logging mechanism (e.g., env_logger or any other logging library)
#[tokio::main]
async fn main() {
    // Setup the logger
    env_logger::init();

    // Define the address to bind the server
    let addr = SocketAddr::from(([127, 0, 0, 1], 3000));

    // A shared state for metrics (e.g., request counts)
    let metrics = Arc::new(Mutex::new(HashMap::new()));

    info!("Listening on http://{}", addr);

    // Create a service to handle incoming requests
    let make_svc = make_service_fn(move |_| {
        let metrics = metrics.clone();
        async {
            Ok::<_, Infallible>(service_fn(move |req| handle_request(req, metrics.clone())))
        }
    });

    // Start the server with the service
    if let Err(e) = Server::bind(&addr).serve(make_svc).await {
        error!("Server error: {}", e);
    }
}

async fn handle_request(
    req: Request<Body>,
    metrics: Arc<Mutex<HashMap<String, usize>>>,
) -> Result<Response<Body>, Infallible> {
    // Parse the request URI and query parameters
    let uri = req.uri();
    let (path, params_query_string) = match uri.path_and_query() {
        Some((p, q)) => (p.to_string(), q.map(|q| q.as_str())),
        None => return Ok(Response::builder()
            .status(400)
            .body(Body::from("Bad Request"))
            .unwrap()),
    };

    // Parse query parameters
    let params = match params_query_string {
        Some(query) => form_urlencoded::parse(query.as_bytes()).into_owned().collect::<HashMap<String, String>>(),
        None => HashMap::new(),
    };

    // Log request details
    info!("Received request for {} with params: {:?}", path, params);

    // Update metrics
    let mut metrics_guard = metrics.lock().await;
    *metrics_guard.entry("total_requests".to_string()).or_insert(0) += 1;

    // Generate the response
    let response_body = format!(
        "<html><body><h1>Request for {}</h1><p>Query Params: {:?}</p></body></html>",
        path, params
    );

    Ok(Response::builder()
        .status(200)
        .header(CONTENT_TYPE, "text/html")
        .body(Body::from(response_body))
        .unwrap())
}

```

### Key Points:
- **HTTP Library:** Utilizes `hyper` for handling HTTP requests efficiently.
- **Asynchronous Processing:** Uses async/await to handle concurrent requests gracefully.
- **Query Parsing:** Parses query parameters using the `form_urlencoded` crate.
- **Logging and Metrics:** Incorporates logging with `log` crate, allowing easy integration of more sophisticated logging solutions later.
- **Error Handling:** Gracefully handles malformed URIs by returning a 400 Bad Request error.
