['```cpp
#include <iostream>
#include <queue>
#include <mutex>

// Custom linked list node for the queue
struct Node {
    int data;
    Node* next;

    Node(int val) : data(val), next(nullptr) {}
};

// Thread-safe linked queue class
class LinkedQueue {
private:
    Node* front;
    Node* rear;
    std::mutex mtx; // Mutex to protect concurrent access

public:
    LinkedQueue() : front(nullptr), rear(nullptr) {}

    ~LinkedQueue() {
        while (front != nullptr) {
            Node* temp = front;
            front = front->next;
            delete temp;
        }
    }

    void enqueue(int value) {
        std::lock_guard<std::mutex> lock(mtx);
        Node* newNode = new Node(value);
        if (rear == nullptr) {
            front = rear = newNode;
        } else {
            rear->next = newNode;
            rear = newNode;
        }
    }

    bool dequeue() {
        std::lock_guard<std::mutex> lock(mtx);
        if (front == nullptr) return false;
        Node* temp = front;
        front = front->next;
        delete temp;
        if (front == nullptr) rear = nullptr;
        return true;
    }

    int peek() const {
        std::lock_guard<std::mutex> lock(mtx);
        if (front == nullptr) throw std::runtime_error("Queue is empty");
        return front->data;
    }

    bool isEmpty() const {
        std::lock_guard<std::mutex> lock(mtx);
        return front == nullptr;
    }
};

void processQueue(LinkedQueue& q, int searchValue, int insertValue1, int insertValue2) {
    std::lock_guard<std::mutex> lock(q.mtx); // Lock the queue for safe access

    Node* current = q.front;
    Node* prev = nullptr;

    while (current != nullptr) {
        if (current->data == searchValue) {
            // Insert insertValue1 after the found node
            Node* newNode = new Node(insertValue1);
            newNode->next = current->next;
            current->next = newNode;

            if (current == q.rear) { // If it's at the end, update rear
                q.rear = newNode;
            }

            return; // Exit after insertion
        }
        prev = current;
        current = current->next;
    }

    // If searchValue is not found, append insertValue2 to the end of the queue
    Node* newEndNode = new Node(insertValue2);
    if (prev == nullptr) {
        q.front = q.rear = newEndNode; // Queue was empty
    } else {
        prev->next = newEndNode;
        q.rear = newEndNode;
    }
}

// Function to test the LinkedQueue and processQueue function
void testProcessQueue() {
    LinkedQueue q;

    // Enqueue some elements
    for (int i = 1; i <= 5; ++i) {
        q.enqueue(i);
    }

    // Test case: searchValue is present
    std::cout << "Test Case 1:" << std::endl;
    processQueue(q, 3, 99, -1);

    while (!q.isEmpty()) {
        std::cout << q.peek() << " ";
        q.dequeue();
    }
    std::cout << "\n";

    // Test case: searchValue is not present
    for (int i = 6; i <= 10; ++i) {
        q.enqueue(i);
    }

    std::cout << "Test Case 2:" << std::endl;
    processQueue(q, 11, 88, -1);

    while (!q.isEmpty()) {
        std::cout << q.peek() << " ";
        q.dequeue();
    }
    std::cout << "\n";
}

int main() {
    testProcessQueue();
    return 0;
}
```']

