    class CustomRandomGenerator {
    public:
        explicit CustomRandomGenerator(unsigned int seed) : generator_(seed) {}

        int generateInt(int min, int max) {
            std::lock_guard<std::mutex> lock(mutex_);
            Logger::log("Generating integer");
            std::uniform_int_distribution<int> dist(min, max);
            return dist(generator_);
        }

        double generateDouble(double min, double max) {
            std::lock_guard<std::mutex> lock(mutex_);
            Logger::log("Generating double");
            std::uniform_real_distribution<double> dist(min, max);
            return dist(generator_);
        }

        bool generateBool() {
            std::lock_guard<std::mutex> lock(mutex_);
            Logger::log("Generating boolean");
            std::bernoulli_distribution dist(0.5); // 50% chance
            return dist(generator_);
        }

        void resetSeed(unsigned int newSeed) {
            std::lock_guard<std::mutex> lock(mutex_);
            Logger::log("Resetting seed");
            generator_.seed(newSeed);
        }

    private:
        std::mt19937 generator_;
        mutable std::mutex mutex_; // Ensure thread-safe operations
    };

