using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class BatchUpdateOptimizer
{
    private readonly string _connectionString;
    private const int DefaultBatchSize = 100;
    private const int MaxRetryAttempts = 3;

    public BatchUpdateOptimizer(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<int> ExecuteBatchUpdatesAsync(List<UpdateOperation> operations)
    {
        int totalRowsAffected = 0;
        int batchSize = DefaultBatchSize;

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();

            foreach (var batch in SplitIntoBatches(operations, batchSize))
            {
                bool success = false;
                for (int attempt = 1; attempt <= MaxRetryAttempts && !success; attempt++)
                {
                    try
                    {
                        using (var transaction = connection.BeginTransaction())
                        {
                            int rowsAffected = await ExecuteBatchAsync(connection, batch, transaction);
                            transaction.Commit();
                            totalRowsAffected += rowsAffected;
                            success = true;
                        }
                    }
                    catch (SqlException ex) when (IsTransient(ex))
                    {
                        if (attempt == MaxRetryAttempts)
                        {
                            throw; // Rethrow the exception if max attempts reached
                        }

                        // Optionally log the error or adjust batch size
                        batchSize = Math.Max(1, batchSize / 2); // Reduce batch size on transient errors
                    }
                }
            }
        }

        return totalRowsAffected;
    }

    private async Task<int> ExecuteBatchAsync(SqlConnection connection, List<UpdateOperation> operations, SqlTransaction transaction)
    {
        int rowsAffected = 0;

        foreach (var operation in operations)
        {
            using (var command = new SqlCommand(operation.SqlQuery, connection, transaction))
            {
                foreach (var parameter in operation.Parameters)
                {
                    command.Parameters.AddWithValue(parameter.Key, parameter.Value);
                }

                rowsAffected += await command.ExecuteNonQueryAsync();
            }
        }

        return rowsAffected;
    }

    private IEnumerable<List<UpdateOperation>> SplitIntoBatches(List<UpdateOperation> operations, int batchSize)
    {
        for (int i = 0; i < operations.Count; i += batchSize)
        {
            yield return operations.GetRange(i, Math.Min(batchSize, operations.Count - i));
        }
    }

    private bool IsTransient(SqlException ex)
    {
        // Check for specific transient error numbers
        var transientErrorNumbers = new[] { 4060, 40197, 40501, 40613, 40143, 233, 64, 10053, 10054, 10060 };
        foreach (var number in transientErrorNumbers)
        {
            if (ex.Number == number || ex.Errors.Cast<SqlError>().Any(e => transientErrorNumbers.Contains(e.Number)))
            {
                return true;
            }
        }

        return false;
    }
}

public class UpdateOperation
{
    public string TableName { get; set; }
    public Dictionary<string, object> Parameters { get; set; } = new();
    public string PrimaryKeyColumnName { get; set; }
    public object PrimaryKeyValue { get; set; }

    public string SqlQuery => BuildSqlQuery();

    private string BuildSqlQuery()
    {
        var columns = new List<string>();
        foreach (var kvp in Parameters)
        {
            columns.Add($"{kvp.Key} = @{kvp.Key}");
        }

        return $"UPDATE {TableName} SET {string.Join(", ", columns)} WHERE {PrimaryKeyColumnName} = @{PrimaryKeyColumnName}";
    }
}
```

This implementation focuses on minimizing network round-trips by batching updates, with retry logic for transient failures. It dynamically adjusts batch sizes based on error conditions and uses a connection pool via `SqlConnection`.']

