using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using Newtonsoft.Json.Schema;

public class GameObjectConfig
{
    public string Name { get; set; }
    public float Width { get; set; }
    public float Height { get; set; }
    public float Mass { get; set; }
    public bool IsNetworked { get; set; }
}

public class GameConfigurationLoader
{
    private static readonly HttpClient client = new HttpClient();
    private const string ConfigApiUrl = "https://example.com/game-config";

    public async Task<List<GameObjectConfig>> LoadAndValidateConfigAsync()
    {
        try
        {
            var response = await FetchJsonConfigFromApiAsync();
            return ValidateAndParseConfig(response);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
            return new List<GameObjectConfig>();
        }
    }

    private async Task<string> FetchJsonConfigFromApiAsync()
    {
        HttpResponseMessage response = null;
        for (int retries = 0; retries < 3; retries++)
        {
            try
            {
                response = await client.GetAsync(ConfigApiUrl);
                if (response.IsSuccessStatusCode)
                {
                    return await response.Content.ReadAsStringAsync();
                }
            }
            catch (HttpRequestException ex) when (retries < 2)
            {
                Console.WriteLine($"Request failed. Retrying... ({ex.Message})");
                await Task.Delay(1000); // Wait before retrying
            }
        }

        if (response != null && !response.IsSuccessStatusCode)
        {
            throw new Exception("Failed to fetch configuration data.");
        }

        throw new HttpRequestException("Network error occurred while fetching configuration.");
    }

    private List<GameObjectConfig> ValidateAndParseConfig(string json)
    {
        string schemaJson = @"
        {
            'type': 'array',
            'items': {
                'type': 'object',
                'properties': {
                    'Name': {'type': 'string'},
                    'Width': {'type': 'number'},
                    'Height': {'type': 'number'},
                    'Mass': {'type': 'number', 'minimum': 0},
                    'IsNetworked': {'type': 'boolean'}
                },
                'required': ['Name', 'Width', 'Height', 'Mass']
            }
        }";

        JSchema schema = JsonSchema.Parse(schemaJson);
        JObject jsonObject = JsonConvert.DeserializeObject(json) as JObject;

        if (jsonObject == null)
        {
            throw new Exception("Invalid JSON format.");
        }

        IList<ValidationError> validationErrors;
        bool isValid = jsonObject.IsValid(schema, out validationErrors);

        if (!isValid)
        {
            foreach (var error in validationErrors)
            {
                Console.WriteLine($"Validation Error: {error.Message}");
            }
            throw new Exception("JSON configuration is invalid according to the schema.");
        }

        return JsonConvert.DeserializeObject<List<GameObjectConfig>>(json);
    }
}

public class GameEngine
{
    private readonly List<GameObjectConfig> _configurations;

    public GameEngine(List<GameObjectConfig> configurations)
    {
        _configurations = configurations ?? new List<GameObjectConfig>();
    }

    public void Initialize()
    {
        foreach (var config in _configurations)
        {
            Console.WriteLine($"Initializing GameObject: {config.Name}, Dimensions: ({config.Width}, {config.Height}), Mass: {config.Mass}");
            // Implement initialization logic based on configuration
        }
    }
}

class Program
{
    static async Task Main(string[] args)
    {
        var configLoader = new GameConfigurationLoader();
        var configurations = await configLoader.LoadAndValidateConfigAsync();

        if (configurations.Any())
        {
            var gameEngine = new GameEngine(configurations);
            gameEngine.Initialize();
        }
        else
        {
            Console.WriteLine("No valid configurations available. Exiting...");
        }
    }
}
```

