using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public object FindFirstXmlElement(string xmlContent, string elementName)
    {
        try
        {
            XmlDocument xmlDoc = new XmlDocument();
            xmlDoc.LoadXml(xmlContent);

            XPathNavigator navigator = xmlDoc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select(elementName);

            if (!nodes.MoveNext())
                return null;

            List<XPathNavigator> matchingElements = new List<XPathNavigator>();
            do
            {
                matchingElements.Add(nodes.Current.Clone());
            } while (nodes.MoveNext());

            return matchingElements.Count == 1 ? matchingElements[0] : matchingElements;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return null;
        }
    }
}
