use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use log::{warn, info};

pub fn create_directory_with_env(dir_name: &str, env_var: &str) -> Result<(), String> {
    let dir_path = PathBuf::from(dir_name);

    match fs::create_dir(&dir_path) {
        Ok(_) => {
            let current_value = env::var(env_var).ok();

            if let Some(value) = current_value {
                if value != dir_path.to_str().unwrap_or_default() {
                    warn!("Environment variable {:?} already set to a different path: {}", env_var, value);
                }
            }

            env::set_var(env_var, dir_path.to_str().unwrap());
            info!("Directory created and environment variable {} set to {:?}", env_var, dir_path);
        },
        Err(e) => return Err(format!("Failed to create directory: {}", e)),
    }

    Ok(())
}
