import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class StringHashProcessor {

    private static final Logger logger = Logger.getLogger(StringHashProcessor.class.getName());
    private static final Map<String, String> stringToMd5Map = new ConcurrentHashMap<>();
    private static final Map<String, Boolean> md5ExistsMap = new ConcurrentHashMap<>();

    public void processStrings(List<String> strings) {
        for (String str : strings) {
            if (str == null || str.isEmpty()) continue;

            String md5Hash = computeMD5(str);

            // Check and handle duplicates
            synchronized (md5ExistsMap) {
                if (md5ExistsMap.containsKey(md5Hash)) {
                    System.out.println("Duplicate found for MD5: " + md5Hash);
                    continue;
                }
                md5ExistsMap.put(md5Hash, true);
            }

            // Store the original string and its MD5 hash
            stringToMd5Map.put(str, md5Hash);
        }
    }

    private String computeMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.severe("MD5 algorithm not found: " + e.getMessage());
            throw new RuntimeException(e);
        }
    }

