<?php

class UserAccountManager {
    private $db;
    private $logger;

    public function __construct($db, $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function handleRequest($_REQUEST) {
        try {
            $action = $_REQUEST['action'] ?? '';
            if (!in_array($action, ['create', 'update', 'delete'])) {
                return json_encode(['status' => 'failure', 'message' => 'Invalid action']);
            }

            switch ($action) {
                case 'create':
                    return $this->createUser($_REQUEST);
                case 'update':
                    return $this->updateUser($_REQUEST);
                case 'delete':
                    return $this->deleteUser($_REQUEST);
            }
        } catch (Exception $e) {
            $this->logger->error($e->getMessage());
            return json_encode(['status' => 'failure', 'message' => 'An error occurred']);
        }
    }

    private function createUser($data) {
        $name = trim($data['name'] ?? '');
        $email = filter_var($data['email'] ?? '', FILTER_VALIDATE_EMAIL);
        $password = $data['password'] ?? '';

        if (empty($name) || !$email || empty($password)) {
            return json_encode(['status' => 'failure', 'message' => 'Invalid input']);
        }

        // Check for existing user with the same email
        $existingUser = $this->db->query("SELECT id FROM users WHERE email = ?", [$email])->fetch();

        if ($existingUser) {
            return json_encode(['status' => 'failure', 'message' => 'Email already exists']);
        }

        // Hash password
        $hashedPassword = password_hash($password, PASSWORD_BCRYPT);

        // Insert new user
        $this->db->beginTransaction();
        $userId = $this->db->query("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", [$name, $email, $hashedPassword]);
        $this->db->commit();

        return json_encode(['status' => 'success', 'message' => 'User created']);
    }

    private function updateUser($data) {
        $id = intval($data['id'] ?? 0);
        $name = trim($data['name'] ?? '');
        $email = filter_var($data['email'] ?? '', FILTER_VALIDATE_EMAIL);
        $password = $data['password'] ?? '';

        if (!$id || empty($name) || !$email) {
            return json_encode(['status' => 'failure', 'message' => 'Invalid input']);
        }

        // Check if user exists
        $user = $this->db->query("SELECT * FROM users WHERE id = ?", [$id])->fetch();

        if (!$user) {
            return json_encode(['status' => 'failure', 'message' => 'User not found']);
        }

        // Check permissions
        session_start();
        $currentUserRole = $_SESSION['role'] ?? '';
        $currentUserId = $_SESSION['user_id'] ?? 0;

        if ($id !== $currentUserId && $currentUserRole !== 'admin') {
            return json_encode(['status' => 'failure', 'message' => 'Permission denied']);
        }

        // Update user
        $this->db->beginTransaction();
        $updateData = ['name' => $name, 'email' => $email];
        if (!empty($password)) {
            $hashedPassword = password_hash($password, PASSWORD_BCRYPT);
            $updateData['password'] = $hashedPassword;
        }
        $this->db->query("UPDATE users SET " . implode(', ', array_map(fn($k) => "$k = ?", array_keys($updateData))) . " WHERE id = ?", array_values($updateData) + [$id]);
        $this->db->commit();

        return json_encode(['status' => 'success', 'message' => 'User updated']);
    }

    private function deleteUser($data) {
        $id = intval($data['id'] ?? 0);

        if (!$id) {
            return json_encode(['status' => 'failure', 'message' => 'Invalid input']);
        }

        // Check if user is inactive
        $user = $this->db->query("SELECT * FROM users WHERE id = ? AND active = 0", [$id])->fetch();

        if (!$user) {
            return json_encode(['status' => 'failure', 'message' => 'User not found or is active']);
        }

        // Delete user
        $this->db->beginTransaction();
        $this->db->query("DELETE FROM users WHERE id = ?", [$id]);
        $this->db->commit();

        return json_encode(['status' => 'success', 'message' => 'User deleted']);
    }
}

