// Middleware for enforcing multi-tenancy isolation
public class TenantMiddleware {
    private readonly RequestDelegate _next;

    public TenantMiddleware(RequestDelegate next) {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context, IMemoryCache cache) {
        var tenantId = context.Request.Headers["Tenant-ID"];

        if (string.IsNullOrEmpty(tenantId)) {
            context.Response.StatusCode = 400; // Bad Request
            await context.Response.WriteAsync("Tenant ID is required.");
            return;
        }

        // Retrieve tenant configuration from cache or database
        if (!cache.TryGetValue($"TenantConfig_{tenantId}", out TenantConfiguration config)) {
            context.Response.StatusCode = 404; // Not Found
            await context.Response.WriteAsync("Tenant not found.");
            return;
        }

        context.Items["TenantConfig"] = config;

        await _next(context);
    }
}

