(function() {
    'use strict';

    angular.module('app', [])
        .service('ResourceService', ['$http', '$q', '$cacheFactory', function($http, $q, $cacheFactory) {
            var cache = $cacheFactory('resourceCache');

            this.processForwardList = function(resourceId, url, forwardList) {
                return processStrings(url, forwardList)
                    .then(function(results) {
                        updateDialog(resourceId, results);
                    })
                    .catch(handleError);
            };

            function processStrings(url, strings) {
                var deferred = $q.defer();
                var promises = strings.map(function(str) {
                    if (cache.get(str)) {
                        return $q.resolve(cache.get(str));
                    } else {
                        return fetchData(url, str)
                            .then(function(data) {
                                cache.put(str, data);
                                return data;
                            });
                    }
                });

                $q.all(promises).then(deferred.resolve.bind(deferred)).catch(deferred.reject.bind(deferred));

                return deferred.promise;
            }

            function fetchData(url, str) {
                var deferred = $q.defer();
                $http.get(`${url}?query=${encodeURIComponent(str)}`)
                    .then(function(response) {
                        if (response.data && response.data.result) {
                            deferred.resolve(response.data.result);
                        } else {
                            deferred.reject('String not found');
                        }
                    })
                    .catch(function(error) {
                        deferred.reject(`Error fetching data: ${error.message}`);
                    });

                return deferred.promise;
            }

            function updateDialog(resourceId, results) {
                // Simulate dialog update
                console.log(`Resource ID: ${resourceId}, Results:`, results);
            }

            function handleError(error) {
                console.error('Processing error:', error);
                // Handle and display error to the user appropriately
            }
        }]);
})();
