fn handle_error(logger: &Logger, error_message: &str) {
    logger.log(error_message);
    logger.remote_log(error_message);
    eprintln!("{}", error_message);
}

fn compile_targets(targets: Vec<&str>) -> Vec<(ExitStatus, String)> {
    let mut results = vec![];
    let mut logger = Logger::new("build.log", 5, true);

    for target in targets {
        match run_compiler(target, &mut logger) {
            Ok(summary) => results.push((Ok(()), summary)),
            Err(err_code) => results.push((err_code, format!("Failed: {:?}", err_code))),
        }
    }

    results
}

fn run_compiler(target: &str, logger: &mut Logger) -> Result<String, ExitStatus> {
    let start_time = Instant::now();
    match Command::new("cargo").arg("build").arg("--target").arg(target).spawn() {
        Ok(mut child) => {
            let pid = child.id().expect("Failed to get process ID");
            while let Some(status) = child.try_wait() {
                if status.is_success() {
                    break;
                }
            }

            let exit_status = child.wait()?;
            let duration = start_time.elapsed();
            let rss = get_resident_set_size(pid).unwrap_or(0);

            let summary = format!(
                "Target: {}, Time: {:?}, RSS: {} bytes",
                target, duration, rss
            );

            logger.log(&summary);
            Ok(summary)
        }
        Err(e) => {
            handle_error(logger, &format!("Error running compiler for {}: {:?}", target, e));
            Err(ExitStatus::from_raw(1))
        }
    }
}

fn main() {
    let targets = vec!["x86_64-unknown-linux-gnu", "thumbv7em-none-eabi"];
    let results = compile_targets(targets);

    for (status, summary) in results {
        match status {
            Ok(_) => println!("Success: {}", summary),
            Err(status) => eprintln!("Failed with exit code {}: {:?}", status.code().unwrap_or(-1), summary),
        }
    }
}
```

