import requests
from time import sleep
import json
from cachetools import TTLCache, cached

# Define cache with a max size of 100 items and a TTL (time-to-live) of 300 seconds.
cache = TTLCache(maxsize=100, ttl=300)

def exponential_backoff_retry(func):
    def wrapper(*args, **kwargs):
        retries = 5
        delay = 1

        for attempt in range(retries):
            try:
                return func(*args, **kwargs)
            except requests.exceptions.RequestException as e:
                if attempt < retries - 1:
                    sleep(delay)
                    delay *= 2
                else:
                    raise Exception(f"API request failed after {retries} attempts: {e}")
    return wrapper

@exponential_backoff_retry
def get_api_data(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()

@cached(cache)
def fetch_patient_demographics(patient_id):
    url = f"https://api.healthcare.com/v1/demographics/{patient_id}"
    return get_api_data(url)

@cached(cache)
def fetch_recent_medical_history(patient_id):
    url = f"https://api.healthcare.com/v2/medical-history/{patient_id}"
    return get_api_data(url)

@cached(cache)
def fetch_medication_list(patient_id):
    url = f"https://api.healthcare.com/v1/medications/{patient_id}"
    return get_api_data(url)

def generate_health_report(patient_id):
    try:
        demographics = fetch_patient_demographics(patient_id)
        medical_history = fetch_recent_medical_history(patient_id)
        medications = fetch_medication_list(patient_id)

        report = {
            "demographics": demographics,
            "medical_history": medical_history,
            "medications": medications
        }

        return json.dumps(report), {"status": "success"}
    except Exception as e:
        return None, {"status": "failure", "message": str(e)}

# Example Usage
if __name__ == "__main__":
    patient_id = 12345
    report, status = generate_health_report(patient_id)
    print(json.dumps({"report": report, "status": status}, indent=2))
