import requests
from cachetools import TTLCache, cached
from concurrent.futures import ThreadPoolExecutor
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Cache configuration: 1000 items with a time-to-live of 600 seconds (10 minutes)
cache = TTLCache(maxsize=1000, ttl=600)

@cached(cache)
def fetch_products(category=None, sort_by='price'):
    try:
        # Construct the API URL
        api_url = "https://api.onlinestore.com/products"
        params = {}

        if category:
            params['category'] = category

        if sort_by == 'price':
            params['sort'] = 'price'

        response = requests.get(api_url, params=params)
        response.raise_for_status()

        products = response.json().get('products', [])
        return products

    except requests.exceptions.RequestException as e:
        logger.error(f"API request failed: {e}")
        return []

def process_user_input(user_inputs):
    # Use a thread pool to handle concurrent requests efficiently
    with ThreadPoolExecutor(max_workers=10) as executor:
        future_to_input = {
            executor.submit(fetch_products, **user_input): user_input 
            for user_input in user_inputs
        }

        results = {}
        for future in future_to_input:
            user_input = future_to_input[future]
            try:
                products = future.result()
                results[user_input['id']] = products
            except Exception as e:
                logger.error(f"Error processing input {user_input['id']}: {e}")
                results[user_input['id']] = []

        return results

# Example usage
if __name__ == "__main__":
    user_inputs = [
        {'id': 1, 'category': 'electronics', 'sort_by': 'price'},
        {'id': 2, 'category': 'books', 'sort_by': 'price'}
    ]

    products_list = process_user_input(user_inputs)
    for user_id, products in products_list.items():
        print(f"User {user_id} received: {products}")
