<?php

class TextProcessor {
    private $charSet;
    private $hashAlgorithm;

    public function __construct($charSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', $hashAlgorithm = 'sha256') {
        $this->setCharSet($charSet);
        $this->setHashAlgorithm($hashAlgorithm);
    }

    public function setCharSet($charSet) {
        if ($this->isValidCharacterSet($charSet)) {
            $this->charSet = $charSet;
        } else {
            throw new InvalidArgumentException("Invalid character set.");
        }
    }

    private function isValidCharacterSet($charSet) {
        return preg_match('/^[a-zA-Z0-9]+$/', $charSet);
    }

    public function generateRandomString($length) {
        if (!is_int($length) || $length <= 0) {
            throw new InvalidArgumentException("Length must be a positive integer.");
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomIndex = rand(0, strlen($this->charSet) - 1);
            $randomString .= $this->charSet[$randomIndex];
        }

        return $randomString;
    }

    public function setHashAlgorithm($algorithm) {
        if (in_array(strtolower($algorithm), hash_algos())) {
            $this->hashAlgorithm = strtolower($algorithm);
        } else {
            throw new InvalidArgumentException("Unsupported hash algorithm.");
        }
    }

    public function hashText($text, $salt = null) {
        if (!is_string($text)) {
            throw new InvalidArgumentException("Input text must be a string.");
        }

        if ($this->hashAlgorithm === 'bcrypt') {
            return password_hash($text . ($salt ?? ''), PASSWORD_BCRYPT);
        } else {
            return hash($this->hashAlgorithm, $text . ($salt ?? ''));
        }
    }
}

