// oauth-credentials.js
const { DefaultAzureCredential } = require('@azure/identity');
const fs = require('fs');

async function fetchCredentials() {
  const credential = new DefaultAzureCredential();
  const keyVaultName = process.env.KEY_VAULT_NAME;
  const keyVaultUri = `https://${keyVaultName}.vault.azure.net`;

  // Use Azure Key Vault SDK to get secrets
  const { SecretClient } = require('@azure/keyvault-secrets');
  const client = new SecretClient(keyVaultUri, credential);

  const privateKey = await client.getSecret('privateKey');
  const certificate = await client.getSecret('certificate');

  return {
    privateKey: privateKey.value,
    certificate: certificate.value
  };
}

module.exports = { fetchCredentials };

// stream-processor.js
const axios = require('axios');
const { Writable } = require('stream');
const os = require('os');

class StreamProcessor extends Writable {
  constructor(options) {
    super({ ...options, objectMode: true });
    this.concurrency = options.concurrency || 100;
    this.activeStreams = new Set();
    this.paused = false;
  }

  _write(chunk, encoding, callback) {
    if (this.paused) {
      process.nextTick(() => this._write(chunk, encoding, callback));
      return;
    }

    const streamId = chunk.streamId; // Assuming chunk has a unique identifier
    if (this.activeStreams.size >= this.concurrency && !this.paused) {
      process.nextTick(() => this._write(chunk, encoding, callback));
      return;
    }

    const handleStream = async () => {
      try {
        const response = await axios.get(`https://api.example.com/data/${streamId}`, {
          headers: { 'Authorization': `Bearer ${process.env.OAUTH_TOKEN}` }
        });

        this.emit('data', response.data);
        callback();
      } catch (error) {
        if (!this.paused && error.response?.status === 429) {
          this.pauseStream(error.config.url); // Implement logic to pause streams on throttling
          setTimeout(() => this.resumeStream(error.config.url), 1000); // Resume after delay
        }
        callback(error);
      } finally {
        this.activeStreams.delete(streamId);
      }
    };

    this.activeStreams.add(streamId);
    handleStream();
  }

  pauseStream(url) {
    if (!this.paused) {
      this.paused = true;
      console.log(`Pausing stream for ${url}`);
    }
  }

  resumeStream(url) {
    if (this.paused) {
      this.paused = false;
      console.log(`Resuming stream for ${url}`);
      this.activeStreams.forEach(streamId => this._write({ streamId }, null, () => {}));
    }
  }
}

module.exports = { StreamProcessor };

// main.js
const http = require('http');
const { fetchCredentials } = require('./oauth-credentials');
const { StreamProcessor } = require('./stream-processor');

async function startServer() {
  const credentials = await fetchCredentials();

  const server = http.createServer((req, res) => {
    if (req.url === '/start-stream') {
      const streamProcessor = new StreamProcessor({ concurrency: 100 });

      // Example: Simulate incoming stream data
      for (let i = 0; i < 500; i++) { 
        setTimeout(() => {
          streamProcessor.write({ streamId: i }, () => console.log(`Processed ${i}`));
        }, Math.random() * 10);
      }

      streamProcessor.on('data', data => res.end(JSON.stringify(data)));
    } else {
      res.statusCode = 404;
      res.end();
    }
  });

  server.listen(3000, () => {
    console.log('Server listening on port 3000');
  });
}

startServer().catch(console.error);
```

