    return value ? value : strdup(default_value);
}

// Main function to resolve hostname
u_char* resolve_hostname(const char *hostname) {
    int retries = 0;
    struct addrinfo hints, *res, *p;
    u_char ip[16]; // Supports both IPv4 and IPv6

    if (!validate_hostname_with_api(hostname)) {
        log_status("API validation failed for hostname");
        return NULL;
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    while (retries < MAX_RETRIES) {
        if (!getaddrinfo(hostname, NULL, &hints, &res)) {
            for (p = res; p != NULL; p = p->ai_next) {
                void *addr;
                if (p->ai_family == AF_INET) { // IPv4
                    struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                    addr = &(ipv4->sin_addr);
                } else { // IPv6
                    struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                    addr = &(ipv6->sin6_addr);
                }
                inet_ntop(p->ai_family, addr, ip, sizeof(ip));
                freeaddrinfo(res); // Free the linked list
                return strdup((const char*)ip);
            }
        }

        log_status("DNS query failed, retrying...");
        freeaddrinfo(res);
        retries++;
        sleep(DNS_TIMEOUT);

        if (retries < MAX_RETRIES) {
            sleep(API_RATE_LIMIT_DELAY); // Respect API rate limits
        }
    }

    log_status("All retries exhausted");
    return NULL;
}

