// Function to update sliding window with new sensor data
void update_sliding_window(SlidingWindow *sw, double value) {
    pthread_mutex_lock(&sw->lock);

    time_t now = time(NULL);
    if (sw->count < sw->size) {
        sw->window[sw->count].value = value;
        sw->window[sw->count].timestamp = now;
        sw->count++;
    } else {
        memmove(sw->window, sw->window + 1, (sw->size - 1) * sizeof(SensorData));
        sw->window[sw->size - 1].value = value;
        sw->window[sw->size - 1].timestamp = now;
    }

    // Update max signal strength
    if (value > sw->max_signal.value) {
        sw->max_signal.value = value;
        sw->max_signal.timestamp = now;
