#include <iostream>
#include <vector>
#include <map>
#include <chrono>
#include <random>
#include <thread>

class Character {
public:
    Character() : stamina(3), lastAttackTime(0) {}

    void selectAndExecuteAttack();

private:
    static const int MaxAttacksPerMinute = 3;
    std::map<int, int> attackCooldowns; // Attack ID mapped to cooldown duration in milliseconds
    std::vector<int> attacksAvailable{1, 2, 3};
    int stamina;
    std::chrono::milliseconds lastAttackTime;

    void logAttackAttempt(int attackId, bool success);
    bool canPerformAttack(int attackId);

    void replenishStamina();
};

void Character::selectAndExecuteAttack() {
    if (stamina <= 0) {
        std::cout << "Insufficient stamina for any attacks." << std::endl;
        return;
    }

    auto now = std::chrono::system_clock::now().time_since_epoch();

    // Check which attacks are available
    std::vector<int> validAttacks;
    for (int attackId : attacksAvailable) {
        if (canPerformAttack(attackId)) {
            validAttacks.push_back(attackId);
        }
    }

    if (validAttacks.empty()) {
        std::cout << "No attacks available due to cooldowns." << std::endl;
        return;
    }

    // Randomly select an attack from the available ones
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, validAttacks.size() - 1);
    int selectedAttack = validAttacks[dis(gen)];

    bool success = true;
    if (canPerformAttack(selectedAttack)) {
        // Execute attack
        lastAttackTime = std::chrono::system_clock::now().time_since_epoch();
        stamina--;
        logAttackAttempt(selectedAttack, success);
    } else {
        success = false;
        logAttackAttempt(selectedAttack, success);
    }

    if (!success) {
        std::cout << "Insufficient stamina or cooldown for attack " << selectedAttack << "." << std::endl;
    }
}

bool Character::canPerformAttack(int attackId) {
    auto now = std::chrono::system_clock::now().time_since_epoch();
    return (stamina > 0 && (lastAttackTime + attackCooldowns[attackId] <= now ||
                            std::chrono::duration_cast<std::chrono::minutes>(now - lastAttackTime).count() >= MaxAttacksPerMinute));
}

void Character::logAttackAttempt(int attackId, bool success) {
    // Placeholder for logging mechanism
    if (success) {
        std::cout << "Successfully performed attack: " << attackId << std::endl;
    } else {
        std::cout << "Failed to perform attack: " << attackId << ". Reason: Insufficient stamina or cooldown." << std::endl;
    }
}

void Character::replenishStamina() {
    auto now = std::chrono::system_clock::now().time_since_epoch();
    if (std::chrono::duration_cast<std::chrono::minutes>(now - lastAttackTime).count() >= 1) {
        stamina = std::min(stamina + 3, MaxAttacksPerMinute);
        lastAttackTime = now; // Reset for the next cycle
    }
}

int main() {
    Character character;
    character.attackCooldowns[1] = std::chrono::milliseconds(5000); // Example cooldown of 5 seconds
    character.attackCooldowns[2] = std::chrono::milliseconds(3000);
    character.attackCooldowns[3] = std::chrono::milliseconds(7000);

    while (true) {
        character.replenishStamina();
        character.selectAndExecuteAttack();
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Simulate time passing
    }

    return 0;
}
```

