['```csharp
using System;
using System.Collections.Generic;

public class DynamicValueGenerator
{
    private Random _random = new Random();
    private List<float> _floatHistory = new List<float>();
    private List<int> _intHistory = new List<int>();

    private float _minFloat, _maxFloat;
    private bool _isFloatInclusive;
    private int _minInt, _maxInt;
    private bool _isIntInclusive;

    public DynamicValueGenerator(float minFloat, float maxFloat, bool isFloatInclusive,
                                 int minInt, int maxInt, bool isIntInclusive)
    {
        SetRange(minFloat, maxFloat, isFloatInclusive, minInt, maxInt, isIntInclusive);
    }

    private void ValidateRange<T>(T min, T max, bool isInclusive) where T : IComparable
    {
        if (min.CompareTo(max) > 0)
            throw new ArgumentException("Minimum cannot be greater than maximum.");
        if (!isInclusive && min.Equals(max))
            throw new ArgumentException("For exclusive ranges, minimum and maximum must differ.");
    }

    public void SetRange(float minFloat, float maxFloat, bool isFloatInclusive,
                         int minInt, int maxInt, bool isIntInclusive)
    {
        ValidateRange(minFloat, maxFloat, isFloatInclusive);
        ValidateRange((object)minInt, (object)maxInt, isIntInclusive);

        _minFloat = minFloat;
        _maxFloat = maxFloat;
        _isFloatInclusive = isFloatInclusive;

        _minInt = minInt;
        _maxInt = maxInt;
        _isIntInclusive = isIntInclusive;
    }

    public float GenerateRandomFloat()
    {
        double scale = 1.0 / ((double)_random.NextDouble() + 1);
        if (_isFloatInclusive)
            return (float)(_minFloat + scale * (_maxFloat - _minFloat));
        else
            return (float)(_minFloat + (scale - double.Epsilon) * (_maxFloat - _minFloat));
    }

    public int GenerateRandomInt()
    {
        long range = _isIntInclusive ? _maxInt - _minInt + 1 : _maxInt - _minInt;
        if (range < 0)
            throw new InvalidOperationException("Invalid integer range.");

        return (int)(_random.NextDouble() * range) + _minInt;
    }

    public void ClearHistory()
    {
        _floatHistory.Clear();
        _intHistory.Clear();
    }

    public int GetFloatValueCount() => _floatHistory.Count;
    public float? GetMaxFloatValue() => _floatHistory.Count > 0 ? (float?)_floatHistory.Max() : null;
    public float? GetMinFloatValue() => _floatHistory.Count > 0 ? (float?)_floatHistory.Min() : null;
    public double? GetAverageFloatValue() => _floatHistory.Count > 0 ? _floatHistory.Average() : (double?)null;

    public int GetIntValueCount() => _intHistory.Count;
    public int? GetMaxIntValue() => _intHistory.Count > 0 ? (int?)_intHistory.Max() : null;
    public int? GetMinIntValue() => _intHistory.Count > 0 ? (int?)_intHistory.Min() : null;
    public double? GetAverageIntValue() => _intHistory.Count > 0 ? _intHistory.Average() : (double?)null;

    public void AddToHistory(float value)
    {
        if ((value >= _minFloat && value <= _maxFloat) || (_isFloatInclusive &&
            (value > _minFloat && value < _maxFloat)))
        {
            _floatHistory.Add(value);
        }
        else
        {
            throw new ArgumentOutOfRangeException(nameof(value), "Value out of bounds.");
        }
    }

    public void AddToIntHistory(int value)
    {
        if ((value >= _minInt && value <= _maxInt) || (_isIntInclusive &&
            (value > _minInt && value < _maxInt)))
        {
            _intHistory.Add(value);
        }
        else
        {
            throw new ArgumentOutOfRangeException(nameof(value), "Value out of bounds.");
        }
    }

    public override string ToString()
    {
        return $"Float Range: [{_minFloat}, {_maxFloat}] (Inclusive: {_isFloatInclusive}), " +
               $"Generated: {_floatHistory.Count}\n" +
               $"Integer Range: [{_minInt}, {_maxInt}] (Inclusive: {_isIntInclusive}), " +
               $"Generated: {_intHistory.Count}\n" +
               $"Float Stats - Min: {GetMinFloatValue()}, Max: {GetMaxFloatValue()}, Avg: {GetAverageFloatValue()}\n" +
               $"Integer Stats - Min: {GetMinIntValue()}, Max: {GetMaxIntValue()}, Avg: {GetAverageIntValue()}";
    }
}
