["```javascript
function findUniquePaths(selector, rootElement = document.documentElement, callback, options = {}) {
    const { maxDepth = Infinity, maxPathLength = Infinity } = options;
    const pathsSet = new Set();

    function traverse(element, currentPath = [], depth = 0) {
        if (depth > maxDepth || currentPath.length > maxPathLength) return;

        const children = element.children;
        for (let i = 0; i < children.length; i++) {
            traverse(children[i], [...currentPath, children[i]], depth + 1);
        }

        if (element.matches(selector)) {
            const pathString = currentPath.map(e => e.tagName.toLowerCase()).join(' > ');
            if (callback(element) && !pathsSet.has(pathString)) {
                pathsSet.add(pathString);
            }
        }
    }

    traverse(rootElement);

    return Array.from(pathsSet);
}

// Usage example:
const uniquePaths = findUniquePaths('.my-class', document.body, element => element.id !== '', { maxDepth: 10 });
console.log(uniquePaths);
```

This function `findUniquePaths` recursively traverses the DOM tree from a specified root element (defaulting to the entire document) and collects paths to elements that match a given CSS selector. It uses a callback to validate each path and ensures paths are unique by storing them in a set. The function supports configurable depth and path length limits for performance tuning."]

