#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Define the cache size and structure
#define CACHE_SIZE 10

typedef struct CacheNode {
    char *line;
    double average;
    struct CacheNode *prev, *next;
} CacheNode;

CacheNode *cacheHead = NULL, *cacheTail = NULL;
int cacheSize = 0;

void add_to_cache(char *line, double average) {
    CacheNode *newNode = (CacheNode *)malloc(sizeof(CacheNode));
    newNode->line = strdup(line);
    newNode->average = average;
    newNode->next = NULL;

    if (!cacheHead || !cacheTail) {
        cacheHead = cacheTail = newNode;
    } else {
        cacheTail->next = newNode;
        newNode->prev = cacheTail;
        cacheTail = newNode;
    }
    cacheSize++;

    // Evict the least recently used node if cache size exceeds limit
    if (cacheSize > CACHE_SIZE) {
        CacheNode *nodeToRemove = cacheHead;
        cacheHead = cacheHead->next;
        free(nodeToRemove->line);
        free(nodeToRemove);
        cacheSize--;
        if (cacheHead) cacheHead->prev = NULL;
    }
}

CacheNode* find_in_cache(const char *line) {
    CacheNode *current = cacheHead;
    while (current) {
        if (strcmp(current->line, line) == 0) {
            // Move accessed node to the end of the list
            if (current != cacheTail) {
                if (current->prev) current->prev->next = current->next;
                if (current->next) current->next->prev = current->prev;

                if (current == cacheHead) cacheHead = current->next;

                current->next = NULL;
                current->prev = cacheTail;
                cacheTail->next = current;
                cacheTail = current;
            }
            return current;
        }
        current = current->next;
    }
    return NULL;
}

double calculate_average(const char *line) {
    const char *token = strtok((char *)line, " ,\t\n");
    double sum = 0.0, count = 0.0;

    while (token) {
        char *endPtr;
        double num = strtod(token, &endPtr);

        if (*endPtr == '\0' && !isspace(*endPtr)) { // Ensure entire token is a valid number
            sum += num;
            count++;
        }
        token = strtok(NULL, " ,\t\n");
    }

    return (count > 0) ? sum / count : 0.0;
}

void process_line(const char *line) {
    CacheNode *cachedLine = find_in_cache(line);
    double average;

    if (cachedLine) {
        printf("%s,%f\n", line, cachedLine->average);
        return;
    }

    average = calculate_average((char *)line);
    add_to_cache((char *)line, average);

    // Output the processed line
    printf("%s,%f\n", line, average);
}

void process_log_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    size_t bufferSize = 256;
    char *buffer = malloc(bufferSize);
    if (!buffer) {
        perror("Failed to allocate buffer");
        fclose(file);
        return;
    }

    while (fgets(buffer, bufferSize, file)) {
        process_line(buffer);
    }

    free(buffer);
    fclose(file);
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    process_log_file(argv[1]);

    // Free remaining cache
    while (cacheHead) {
        CacheNode *node = cacheHead;
        cacheHead = cacheHead->next;
        free(node->line);
        free(node);
    }

    return EXIT_SUCCESS;
}
```']

