#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_FILES 1000

// Function to count vowels in a filename
int countVowels(const char *filename) {
    int vowelCount = 0;
    for (size_t i = 0; filename[i] != '\0'; ++i) {
        char c = tolower(filename[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowelCount++;
        }
    }
    return vowelCount;
}

// Function to determine new file extension
const char *determineExtension(const char *filename) {
    for (size_t i = 0; filename[i] != '\0'; ++i) {
        if (strchr("aeiou", tolower(filename[i])) != NULL) {
            return "txt";
        }
    }
    return "csv";
}

// Function to process filenames
void processFilenames(const char *filenames[], size_t numFiles, char processedFilenames[][MAX_FILENAME_LENGTH]) {
    for (size_t i = 0; i < numFiles; ++i) {
        const char *originalFilename = filenames[i];

        // Count vowels and determine suffix
        int vowelCount = countVowels(originalFilename);
        int numericSuffix = (vowelCount > 0) ? vowelCount : 1;

        // Determine new extension
        const char *newExtension = determineExtension(originalFilename);

        // Process original filename to strip out non-alphanumeric characters except periods and underscores
        char cleanedFilename[MAX_FILENAME_LENGTH] = {0};
        size_t j = 0;
        for (size_t k = 0; originalFilename[k] != '\0' && j < MAX_FILENAME_LENGTH - 20; ++k) {
            if (isalnum(originalFilename[k]) || originalFilename[k] == '.' || originalFilename[k] == '_') {
                cleanedFilename[j++] = originalFilename[k];
            }
        }

        // Generate new filename
        snprintf(processedFilenames[i], MAX_FILENAME_LENGTH, "%s_%d.%s", cleanedFilename, numericSuffix, newExtension);
    }
}

int main() {
    const char *filenames[MAX_FILES] = {"example1.txt", "testfile.csv", "another_test_file.doc"};
    size_t numFiles = 3;
    char processedFilenames[MAX_FILES][MAX_FILENAME_LENGTH];

    processFilenames(filenames, numFiles, processedFilenames);

    for (size_t i = 0; i < numFiles; ++i) {
        printf("Original: %s -> Processed: %s\n", filenames[i], processedFilenames[i]);
    }

    return 0;
}
