#define DEFAULT_THEME_DIR "/default/theme/directory"
#define Fallback_Theme "fallback_theme.png"

typedef struct {
    EVP_CIPHER_CTX *ctx;
} AES256_CBC_Context;

AES256_CBC_Context* initialize_aes_cipher(const char* password) {
    if (!password || strlen(password) == 0) return NULL;

    // Derive key using SHA-256
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), hash);

    AES256_CBC_Context *aes_context = malloc(sizeof(AES256_CBC_Context));
    if (!aes_context) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    aes_context->ctx = EVP_CIPHER_CTX_new();
    if (!aes_context->ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        free(aes_context);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(aes_context->ctx,
                                EVP_aes_256_cbc(),
                                NULL,
                                hash,
                                NULL)) { // IV will be set later
        fprintf(stderr, "Cipher initialization failed\n");
        EVP_CIPHER_CTX_free(aes_context->ctx);
        free(aes_context);
        return NULL;
    }

    return aes_context;
}

void cleanup_cipher(AES256_CBC_Context* context) {
    if (context && context->ctx) {
        EVP_CIPHER_CTX_free(context->ctx);
        free(context);
    }
}

// Theme Cache Management Functions
typedef struct {
    char *bitmap_data;
    int is_loaded;
} ThemeCacheEntry;

ThemeCacheEntry theme_cache = { .bitmap_data = NULL, .is_loaded = 0 };

char* get_theme_directory() {
    static char default_dir[256] = DEFAULT_THEME_DIR;

    if (!access(default_dir, F_OK | R_OK) == 0) {
        fprintf(stderr, "Access to the default theme directory failed: %s\n", strerror(errno));
        strncpy(default_dir, ".", sizeof(default_dir)); // Fallback
    }

    return default_dir;
}

char* load_theme_bitmap(const char *filename) {
    if (theme_cache.is_loaded && theme_cache.bitmap_data != NULL)
        return theme_cache.bitmap_data;

    char *dir = get_theme_directory();
    char path[512];
    snprintf(path, sizeof(path), "%s/%s", dir, filename);

    FILE* file = fopen(path, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open theme bitmap: %s\n", strerror(errno));
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fsize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = malloc(fsize + 1);
    if (!buffer) {
        fclose(file);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    fread(buffer, 1, fsize, file);
    buffer[fsize] = '\0';
    fclose(file);

    // Placeholder for PNG validation (e.g., libpng functions)
    int valid_png = 1; // Assume it's a valid PNG
    if (!valid_png) {
        fprintf(stderr, "Invalid PNG format\n");
        free(buffer);
        return NULL;
    }

    theme_cache.bitmap_data = buffer;
    theme_cache.is_loaded = 1;

    return buffer;
}

void recycle_theme_bitmap() {
    if (theme_cache.is_loaded && theme_cache.bitmap_data != NULL) {
        free(theme_cache.bitmap_data);
        theme_cache.is_loaded = 0;
        theme_cache.bitmap_data = NULL;
    }
}

int main() {
    // Example usage
    AES256_CBC_Context* cipher_context = initialize_aes_cipher("securepassword123");
    if (cipher_context) {
        char *bitmap_path = load_theme_bitmap("theme.png");
        if (!bitmap_path) {
            bitmap_path = load_theme_bitmap(Fallback_Theme);
        }

        cleanup_cipher(cipher_context);

        // Further processing with the theme bitmap...
        if (bitmap_path && strcmp(bitmap_path, Fallback_Theme)) {
            recycle_theme_bitmap(); // Clean up when done
        }
    }

    return 0;
}
```

This code includes:
- AES-256-CBC cipher initialization using OpenSSL.
- Theme caching logic to manage PNG theme bitmaps with fallback and error handling.
- Thread safety is achieved by encapsulating the data in structures, but further synchronization might be needed based on your specific use case.']

