import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.*;

public class ShellCommandExecutor {
    private static final Logger logger = Logger.getLogger(ShellCommandExecutor.class.getName());
    private static final String SCRIPT_PATH = "path/to/script.sh";
    private static final long THRESHOLD_MS = 24 * 60 * 60 * 1000; // 1 day in milliseconds
    private ExecutorService executor = Executors.newCachedThreadPool();

    public ShellCommandExecutor() {
        setupLogger();
    }

    private void setupLogger() {
        try {
            FileHandler fileHandler = new FileHandler("ShellCommandExecutor.log", true);
            fileHandler.setFormatter(new SimpleFormatter());
            logger.addHandler(fileHandler);
        } catch (IOException e) {
            System.err.println("Failed to set up logger: " + e.getMessage());
        }
    }

    public void execute(String userInput) {
        executor.submit(() -> {
            try {
                Path scriptPath = Paths.get(SCRIPT_PATH);
                if (!isScriptUpToDate(scriptPath)) {
                    fetchOrUpdateScript();
                }

                ProcessBuilder processBuilder = new ProcessBuilder("bash", scriptPath.toString(), userInput);
                processBuilder.redirectErrorStream(true);

                logger.info("Executing command: " + String.join(" ", processBuilder.command()));
                Process process = processBuilder.start();

                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.info(line);
                }
                int exitCode = process.waitFor();
                if (exitCode == 0) {
                    logger.info("Command executed successfully.");
                } else {
                    logger.severe("Command execution failed with exit code: " + exitCode);
                }
            } catch (IOException | InterruptedException e) {
                logger.severe("Error executing command: " + e.getMessage());
            }
        });
    }

    private boolean isScriptUpToDate(Path scriptPath) throws IOException {
        long currentTime = Instant.now().toEpochMilli();
        return Files.exists(scriptPath) && 
               (currentTime - Files.getLastModifiedTime(scriptPath).toEpochMilli() < THRESHOLD_MS);
    }

    private void fetchOrUpdateScript() {
        try {
            logger.info("Fetching or updating script...");
            // Simulate fetching the script from an external source
            String scriptContent = "echo 'Hello, World!'";
            Files.write(Paths.get(SCRIPT_PATH), scriptContent.getBytes());
            logger.info("Script updated successfully.");
        } catch (IOException e) {
            logger.severe("Failed to fetch or update script: " + e.getMessage());
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(800, java.util.concurrent.TimeUnit.MILLISECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        ShellCommandExecutor executor = new ShellCommandExecutor();
        executor.execute("sample input");
        Runtime.getRuntime().addShutdownHook(new Thread(executor::shutdown));
    }
}
```

