}

int processSecureMessage(sessionContext_t *sessionContext,
                         const char *encrypted_message,
                         int (*onProcessComplete)(void*, int, const char*),
                         uint32_t timeout) {
    if (!sessionContext || !encrypted_message || !onProcessComplete || strlen(encrypted_message) == 0 || timeout <= 0) {
        return -1; // Error code
    }

    pthread_t thread;
    processSecureMessageArgs *args = malloc(sizeof(processSecureMessageArgs));
    if (!args) {
        return -2; // Out of memory error
    }

    args->sessionContext = sessionContext;
    args->encrypted_message = strdup(encrypted_message);
    args->onProcessComplete = onProcessComplete;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (pthread_create(&thread, NULL, worker_thread, args)) {
            free(args->encrypted_message);
            free(args);
            return -3; // Thread creation failed
        }

        void *status;
        if (pthread_join(thread, &status)) {
            continue; // Retry if join fails
        }

        // Break the loop if successful
        break;
    }

    if (attempt == MAX_RETRIES) {
        free(args->encrypted_message);
        free(args);
        return -4; // Failed after retries
    }

    return 0; // Success
}

typedef struct {
    sessionContext_t *sessionContext;
    const char *encrypted_message;
    int (*onProcessComplete)(void*, int, const char*);
