using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public interface IDataStore<T>
{
    Task StoreValueAsync(T value);
    Task<IEnumerable<T>> RetrieveValuesAsync();
}

public class DynamicValueGenerator
{
    private readonly Random _random = new Random();
    private readonly ConcurrentQueue<float> _floatHistory = new ConcurrentQueue<float>();
    private readonly ConcurrentQueue<int> _intHistory = new ConcurrentQueue<int>();

    private float? _minFloat, _maxFloat;
    private bool _inclusiveFloatMin, _inclusiveFloatMax;

    private int? _minInt, _maxInt;
    private bool _inclusiveIntMin, _inclusiveIntMax;

    private readonly IDataStore<float> _floatDataStore;
    private readonly IDataStore<int> _intDataStore;

    private readonly int _maxStoredValues;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

    public DynamicValueGenerator(IDataStore<float> floatDataStore, 
                                 IDataStore<int> intDataStore,
                                 int maxStoredValues)
    {
        _floatDataStore = floatDataStore ?? throw new ArgumentNullException(nameof(floatDataStore));
        _intDataStore = intDataStore ?? throw new ArgumentNullException(nameof(intDataStore));
        _maxStoredValues = maxStoredValues;
    }

    public void ConfigureFloatRange(float? min, float? max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException("Minimum cannot be greater than maximum.");

        _minFloat = min;
        _maxFloat = max;
        _inclusiveFloatMin = inclusiveMin;
        _inclusiveFloatMax = inclusiveMax;
    }

    public void ConfigureIntRange(int? min, int? max, bool inclusiveMin = true, bool inclusiveMax = true)
    {
        if (min > max)
            throw new ArgumentOutOfRangeException("Minimum cannot be greater than maximum.");

        _minInt = min;
        _maxInt = max;
        _inclusiveIntMin = inclusiveMin;
        _inclusiveIntMax = inclusiveMax;
    }

    public async Task<float> GenerateFloatAsync()
    {
        var value = GenerateRandomValue(_minFloat, _maxFloat, _inclusiveFloatMin, _inclusiveFloatMax, typeof(float));
        await StoreAndManageHistoryAsync(value);
        return value;
    }

    public async Task<int> GenerateIntAsync()
    {
        var value = GenerateRandomValue(_minInt, _maxInt, _inclusiveIntMin, _inclusiveIntMax, typeof(int));
        await StoreAndManageHistoryAsync(value);
        return value;
    }

    private T GenerateRandomValue<T>(T? min, T? max, bool inclusiveMin, bool inclusiveMax) where T : struct
    {
        if (!min.HasValue || !max.HasValue)
            throw new InvalidOperationException("Range is not set.");

        var range = (IConvertible)max - (IConvertible)min;

        object randomValue;

        if (typeof(T) == typeof(float))
        {
            randomValue = _random.NextDouble() * ((double)range + (inclusiveMax ? 0.0 : double.Epsilon)) 
                          + (double)(IConvertible)min;
        }
        else
        {
            randomValue = _random.Next((int)(IConvertible)min, ((int)(IConvertible)max + (inclusiveMax ? 1 : 0)));
        }

        return (T)Convert.ChangeType(randomValue, typeof(T));
    }

    private async Task StoreAndManageHistoryAsync<T>(T value)
    {
        await _semaphore.WaitAsync();
        try
        {
            if (_floatDataStore is IDataStore<float> floatStore && value is float floatValue)
                await floatStore.StoreValueAsync(floatValue);
            else if (_intDataStore is IDataStore<int> intStore && value is int intValue)
                await intStore.StoreValueAsync(intValue);

            var queue = typeof(T) == typeof(float) ? _floatHistory : (ConcurrentQueue<T>)_intHistory;
            queue.Enqueue((T)(object)value);

            while (queue.Count > _maxStoredValues)
                queue.TryDequeue(out _);
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public int GetGeneratedCount()
    {
        return _floatHistory.Count + _intHistory.Count;
    }

    public float? GetMaxFloat() => _floatHistory.Any() ? (float?)_floatHistory.Max() : null;

    public float? GetMinFloat() => _floatHistory.Any() ? (float?)_floatHistory.Min() : null;

    public double? GetAverageFloat()
    {
        return _floatHistory.Count > 0 
            ? ((double)_floatHistory.Sum(f => (double)f)) / _floatHistory.Count
            : (double?)null;
    }

    public int? GetMaxInt() => _intHistory.Any() ? (int?)_intHistory.Max() : null;

    public int? GetMinInt() => _intHistory.Any() ? (int?)_intHistory.Min() : null;

    public double? GetAverageInt()
    {
        return _intHistory.Count > 0 
            ? ((double)_intHistory.Sum(i => i)) / _intHistory.Count
            : (double?)null;
    }

    public void ClearHistory()
    {
        _floatHistory.Clear();
        _intHistory.Clear();
    }

    public override string ToString()
    {
        var floatRange = $"Float range: [{_minFloat} - {_maxFloat}, Inclusive Min: {_inclusiveFloatMin}, Inclusive Max: {_inclusiveFloatMax}]";
        var intRange = $"Int range: [{_minInt} - {_maxInt}, Inclusive Min: {_inclusiveIntMin}, Inclusive Max: {_inclusiveIntMax}]";

        return $"{floatRange}\n{intRange}\nTotal generated values: {GetGeneratedCount()}\n" +
               $"{(GetAverageFloat() != null ? $"Average Float: {GetAverageFloat()}, Max: {GetMaxFloat()}, Min: {GetMinFloat()}" : "No float history")}\n" +
               $"{(GetAverageInt() != null ? $"Average Int: {GetAverageInt()}, Max: {GetMaxInt()}, Min: {GetMinInt()}" : "No int history")}";
    }
}
