using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class BatchMessageProcessor
{
    private const int MaxBatchSize = 100;

    public static string[] ProcessMessages(string key, string iv, params string[] base64EncodedMessages)
    {
        if (base64EncodedMessages.Length > MaxBatchSize)
            throw new ArgumentException($"The batch size should not exceed {MaxBatchSize} messages.");

        string[] decryptedMessages = new string[base64EncodedMessages.Length];

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = Convert.FromBase64String(key);
            tdes.IV = Convert.FromBase64String(iv);

            for (int i = 0; i < base64EncodedMessages.Length; i++)
            {
                try
                {
                    string message = base64EncodedMessages[i];

                    // Validate Base64 encoding
                    if (!IsValidBase64(message))
                    {
                        LogError($"Invalid Base64 encoding at index {i}.");
                        continue;
                    }

                    byte[] data = Convert.FromBase64String(message);
                    decryptedMessages[i] = DecryptMessage(tdes, data);

                }
                catch (Exception ex)
                {
                    LogError($"Decryption failed for message at index {i}: {ex.Message}");
                }
            }
        }

        return decryptedMessages;
    }

    private static bool IsValidBase64(string base64EncodedData)
    {
        try
        {
            Convert.FromBase64String(base64EncodedData);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private static string DecryptMessage(TripleDESCryptoServiceProvider tdes, byte[] encryptedData)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, tdes.CreateDecryptor(), CryptoStreamMode.Write))
            {
                cs.Write(encryptedData, 0, encryptedData.Length);
                cs.Close();
            }

            return Encoding.UTF8.GetString(ms.ToArray());
        }
    }

    private static void LogError(string message)
    {
        // Implementation of logging error, e.g., Console.Error.WriteLine or any other logging mechanism
        Console.Error.WriteLine(message);
    }
}
```

