        {
            var iv = await DistributedClockService.GetUniqueIVAsync();

            using (var aes = Aes.Create())
            {
                aes.Key = Encoding.UTF8.GetBytes(encryptionKey);
                aes.IV = iv;

                // Decrypt the message.
                var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

                byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
                byte[] decryptedBytes = await Task.Run(() => decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length));

                string decryptedText = Encoding.UTF8.GetString(decryptedBytes);

                // Validate checksum
                if (!ValidateChecksum(decryptedText, messageChecksum))
                {
                    logger.LogWarning("Checksum validation failed.");
                    throw new CryptographicException("Decryption verification failed: Checksum mismatch.");
                }

                logger.Log($"Message decrypted successfully. IV: {BitConverter.ToString(iv)}");
                return decryptedText;
            }
        }
        catch (Exception ex)
        {
            logger.LogError("Failed to decrypt message.", ex);
            throw;
        }
