        SUCCESS,
        MISSING_DEPENDENCIES,
        INVALID_CONFIGURATION,
        UNKNOWN_ERROR
    }

    public static class LoadResult {
        private final LoadError error;
        private final String errorMessage;
        private final CustomConfig config;

        private LoadResult(LoadError error, String errorMessage, CustomConfig config) {
            this.error = error;
            this.errorMessage = errorMessage;
            this.config = config;
        }

        public static LoadResult success(CustomConfig config) {
            return new LoadResult(LoadError.SUCCESS, null, config);
        }

        public static LoadResult failure(LoadError error, String message) {
            return new LoadResult(error, message, null);
        }

        public LoadError getError() {
            return error;
        }

        public String getErrorMessage() {
            return errorMessage;
        }

        public CustomConfig getConfig() {
            return config;
        }
    }

    public static LoadResult loadConfiguration(byte[] serializedData) {
        if (serializedData == null || serializedData.length == 0) {
            return LoadResult.failure(LoadError.INVALID_CONFIGURATION, "Serialized data is empty or null.");
        }

        try {
            // Simulate dependency check
            if (!dependenciesAvailable()) {
                return LoadResult.failure(LoadError.MISSING_DEPENDENCIES, "Required dependencies are missing.");
            }

            CustomConfig config = deserialize(serializedData);

            if (config == null || !config.isValid()) {
                return LoadResult.failure(LoadError.INVALID_CONFIGURATION, "Configuration is invalid.");
            }

            // Cache the configuration for future use
            cache.put(config.getId(), config);
            return LoadResult.success(config);

        } catch (IOException | ClassNotFoundException e) {
            return LoadResult.failure(LoadError.UNKNOWN_ERROR, "Failed to load configuration: " + e.getMessage());
        }
    }

    private static boolean dependenciesAvailable() {
