// Define IEEE 802.17 standard alignment requirements
#define HEADER_SIZE 24   // Example header size in bytes
#define MAX_PAYLOAD_SIZE 1500  // Maximum payload size per packet
#define MIN_PACKET_SIZE (HEADER_SIZE + 8)  // Minimum packet size with padding

