// Function to align the payload according to IEEE 802.17 standard
size_t calculate_aligned_payload_size(size_t size) {
    return (size + 7) & ~7; // Aligns to next multiple of 8 bytes
}

// Function to initialize and populate an array of NetworkPacket structures
NetworkPacket* init_network_packets(int count, int *actual_count) {
    if (count <= 0 || actual_count == NULL) {
        fprintf(stderr, "Invalid packet count\n");
        return NULL;
    }

    NetworkPacket *packets = malloc(count * sizeof(NetworkPacket));
    if (!packets) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        return NULL;
    }

    pthread_mutex_lock(&packet_mutex);

    for (int i = 0; i < count; ++i) {
        size_t payload_size = rand() % MAX_PAYLOAD_SIZE + MIN_PACKET_SIZE - HEADER_SIZE;

        // Calculate aligned payload size
