        packets[i].header = malloc(HEADER_SIZE);
        if (!packets[i].header) {
            fprintf(stderr, "Memory allocation failed for header\n");
            pthread_mutex_unlock(&packet_mutex);
            free(packets);
            return NULL;
        }

