use tokio::runtime::{Builder, Runtime};
use std::sync::{Arc, Mutex};
use std::fs::OpenOptions;
use std::io::{self, Write};
use std::env;

#[tokio::main]
async fn main() -> io::Result<()> {
    let rt = Builder::new_multi_thread()
        .worker_threads(4)
        .enable_all()
        .build()
        .unwrap();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <task>", args[0]);
        std::process::exit(1);
    }

    let task_name = &args[1];
    let log_file = Arc::new(Mutex::new(
        OpenOptions::new()
            .create(true)
            .append(true)
            .open("error.log")
            .unwrap(),
    ));

    match task_name.as_str() {
        "task1" => rt.block_on(async {
            execute_task1(log_file.clone()).await;
        }),
        "task2" => rt.block_on(async {
            execute_task2(log_file.clone(), args.get(2).map(|s| s == "--check")).await;
        }),
        _ => eprintln!("Unknown task: {}", task_name),
    }

    Ok(())
}

async fn execute_task1(log_file: Arc<Mutex<tokio::fs::File>>) {
    let result = retry(|| async { perform_task1().await }, 3, 1000).await;
    if let Err(e) = &result {
        log_error(log_file.clone(), e.to_string()).await;
    }
}

async fn execute_task2(log_file: Arc<Mutex<tokio::fs::File>>, check_flag: Option<bool>) {
    let result = retry(|| async { perform_task2().await }, 3, 1000).await;
    if *check_flag.unwrap_or(false) && is_condition_met() {
        log_error(log_file.clone(), "Condition met in task2".to_string()).await;
    }
    if let Err(e) = &result {
        log_error(log_file.clone(), e.to_string()).await;
    }
}

async fn perform_task1() -> Result<(), String> {
    // Simulate a task, e.g., database operation
    tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;
    Ok(())
}

async fn perform_task2() -> Result<(), String> {
    // Simulate another task, e.g., API call
    tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;
    Err("Failed to complete task2".to_string())
}

fn is_condition_met() -> bool {
    // Dummy condition check
    false
}

async fn retry<F, Fut, T>(f: F, attempts: u32, delay_ms: u64) -> Result<T, String>
where
    F: FnOnce() -> Fut,
    Fut: std::future::Future<Output = Result<T, String>>,
{
    let mut last_err = None;
    for _ in 0..attempts {
        match f().await {
            Ok(val) => return Ok(val),
            Err(err) => last_err = Some(err),
        }
        tokio::time::sleep(tokio::time::Duration::from_millis(delay_ms)).await;
    }
    last_err.unwrap_or_else(|| "Unknown error".to_string()).into()
}

async fn log_error(log_file: Arc<Mutex<tokio::fs::File>>, message: String) {
    let mut file = log_file.lock().unwrap();
    if writeln!(file, "{}", message).is_err() {
        eprintln!("Failed to write to log file");
    }
}
```

### Key Points:
- **Tokio Runtime**: Configured with multiple threads for concurrent task execution.
- **Command Line Arguments**: Used to determine which task to execute.
- **Retry Logic**: Implemented using a retry function that handles transient failures.
- **Logging**: Uses an `Arc<Mutex<>>` to ensure thread-safe logging without blocking the main flow.
- **Conditional Check**: Demonstrated in `execute_task2` with a flag.

