#define MAX_ELEMENTS 10000

typedef struct {
    uint8_t crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t rnti;
    int rx_UE_information_tag_valid;
    // Add other fields as necessary
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

uint32_t findLargestInteger(int* array, int size) {
    if (size == 0) return -1; // Assuming all integers are positive for simplicity
    uint32_t largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

struct Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    if (!newNode) return NULL;
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void appendToLinkedList(struct Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node* newNode = createNode(data);
    if (!newNode) return;

    if (*head == NULL) {
        *head = newNode;
    } else {
        struct Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeLinkedList(struct Node* head) {
    struct Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void processInputAndCreateNFAPIList() {
    int size, i;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    if (size <= 0 || size > MAX_ELEMENTS) {
        printf("Invalid input size.\n");
        return;
    }

    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        printf("Memory allocation failed.\n");
        return;
    }

    printf("Enter the elements:\n");
    for (i = 0; i < size; ++i) {
        scanf("%d", &array[i]);
    }

    uint32_t largest = findLargestInteger(array, size);
    printf("The largest integer is: %u\n", largest);

    free(array);

    struct Node* head = NULL;
    for (i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag.rnti = i + 1; // Example RNTI
        pdu.rx_ue_information_tag.rx_UE_information_tag_valid = 1; // Assume valid for simplicity
        pdu.crc_indication_rel8_tag.crcFlag = rand() % 2; // Random CRC flag

        appendToLinkedList(&head, pdu);
    }

    struct Node* current = head;
    while (current != NULL) {
        printf("RNTI: %u, CRC Flag: %d\n", current->data.rx_ue_information_tag.rnti,
               current->data.crc_indication_rel8_tag.crcFlag);
        current = current->next;
    }

    freeLinkedList(head);
}
