['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <openssl/evp.h>

#define BUFFER_SIZE 4096

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int create_socket(int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) handle_error("Socket creation failed");

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0)
        handle_error("Connection failed");

    return sockfd;
}

void send_data(int sockfd, const unsigned char *data, size_t len) {
    int total = 0;
    while (total < len) {
        int bytes_sent = send(sockfd, data + total, len - total, 0);
        if (bytes_sent < 0) handle_error("Send failed");
        total += bytes_sent;
    }
}

int receive_data(int sockfd, unsigned char *buffer, size_t buffer_size) {
    int total = 0;
    while (total < buffer_size) {
        int bytes_received = recv(sockfd, buffer + total, buffer_size - total, 0);
        if (bytes_received <= 0) handle_error("Receive failed");
        total += bytes_received;
    }
    return total;
}

void encrypt_decrypt(unsigned char *input, size_t input_len, unsigned char *output,
                     const EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_error("EVP_CIPHER_CTX allocation failed");

    int len;
    int ciphertext_len;

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv))
        handle_error("Encryption initialization failed");

    if (1 != EVP_EncryptUpdate(ctx, output, &len, input, input_len))
        handle_error("Encryption update failed");
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, output + len, &len)) handle_error("Encryption finalization failed");
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
}

void process_data(int sockfd, const char *mode, size_t data_size) {
    unsigned char key[32] = {0};  // Example key
    unsigned char iv[16] = {0};   // Example IV

    EVP_CIPHER *cipher;
    if (strcmp(mode, "ECB") == 0)
        cipher = EVP_aes_256_ecb();
    else if (strcmp(mode, "CFB") == 0)
        cipher = EVP_aes_256_cfb128();
    else
        handle_error("Unsupported mode");

    unsigned char *data = malloc(data_size);
    unsigned char *encrypted_data = malloc(data_size + EVP_MAX_BLOCK_LENGTH);

    // Simulate data reading
    memset(data, 'A', data_size);

    encrypt_decrypt(data, data_size, encrypted_data, cipher, key, iv);

    send_data(sockfd, encrypted_data, data_size + EVP_MAX_BLOCK_LENGTH);

    unsigned char *received_data = malloc(data_size + EVP_MAX_BLOCK_LENGTH);
    receive_data(sockfd, received_data, data_size + EVP_MAX_BLOCK_LENGTH);

    free(data);
    free(encrypted_data);
    free(received_data);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <port> <mode>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int port = atoi(argv[1]);
    const char *mode = argv[2];

    int sockfd = create_socket(port);

    process_data(sockfd, mode, BUFFER_SIZE);

    close(sockfd);
    return 0;
}
```

