        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Simulate RX_UE_INFORMATION_TAG and RNTI setup
        pdu.rxUeInformationTag.someValue = static_cast<int>(randomGenerator.getRandomUInt32() % 1000);
