import org.apache.http.HttpHost;
import org.apache.http.client.config.RequestConfig;
import org.apache.http.conn.ssl.NoopHostnameVerifier;
import org.apache.http.conn.ssl.SSLConnectionSocketFactory;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.ssl.SSLContextBuilder;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.net.ssl.HostnameVerifier;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;

public class HttpRequestBuilder {

    private static final Logger logger = LoggerFactory.getLogger(HttpRequestBuilder.class);

    public static CloseableHttpClient buildHttpClient(String url, boolean disableCertificateValidation) {
        try {
            SSLContextBuilder sslContextBuilder = new SSLContextBuilder();
            if (disableCertificateValidation) {
                sslContextBuilder.loadTrustMaterial(null, (chain, authType) -> true);
                HostnameVerifier verifier = NoopHostnameVerifier.INSTANCE;
                logger.info("Certificate validation is disabled.");
            } else {
                HostnameVerifier verifier = null; // Use default
            }

            SSLConnectionSocketFactory socketFactory = new SSLConnectionSocketFactory(
                    sslContextBuilder.build(), 
                    new String[]{"TLSv1.2"}, 
                    null, 
                    verifier
            );

            RequestConfig requestConfig = RequestConfig.custom()
                    .setConnectTimeout(5000)
                    .setResponseTimeout(5000)
                    .build();

            return HttpClients.custom()
                    .setSSLSocketFactory(socketFactory)
                    .setDefaultRequestConfig(requestConfig)
                    .build();
        } catch (Exception e) {
            logger.error("Error creating HTTP client: ", e);
            throw new RuntimeException("Failed to create HTTP client", e);
        }
    }

    public static String generateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            return Base64.getEncoder().encodeToString(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            logger.error("MD5 algorithm not found: ", e);
            return null;
        }
    }

    public static void main(String[] args) {
        String url = "https://example.com";
        boolean disableCertValidation = true;

        CloseableHttpClient httpClient = buildHttpClient(url, disableCertValidation);

        // Example usage of MD5 hash generation
        String inputString = "Sample Input";
        String md5Hash = generateMD5Hash(inputString);
        logger.info("Generated MD5 Hash: {}", md5Hash);
    }
}
