['```java
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

public class TextAndArrayProcessor {

    private static final List<String> OLD_TESTAMENT_BOOKS = Arrays.asList(
        "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
        "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel",
        "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles",
        "Ezra", "Nehemiah", "Esther", "Job", "Psalms",
        "Proverbs", "Ecclesiastes", "Song of Solomon", "Isaiah",
        "Jeremiah", "Lamentations", "Ezekiel", "Daniel",
        "Hosea", "Joel", "Amos", "Obadiah", "Jonah",
        "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai",
        "Zechariah", "Malachi"
    );

    private static final Pattern BOOK_PATTERN = buildPattern(OLD_TESTAMENT_BOOKS);

    public static class Result {
        int disjointPairCount;
        long timeTakenForDisjointPairs; // in milliseconds
        Map<String, Integer> bookFrequencyMap;

        public Result(int disjointPairCount, long timeTakenForDisjointPairs, Map<String, Integer> bookFrequencyMap) {
            this.disjointPairCount = disjointPairCount;
            this.timeTakenForDisjointPairs = timeTakenForDisjointPairs;
            this.bookFrequencyMap = bookFrequencyMap;
        }
    }

    public static Result processArrayAndText(int[] array, Path textFilePath) throws IOException {
        // Disjoint pair count using Union-Find
        long startTime = System.currentTimeMillis();
        int disjointPairCount = countDisjointPairs(array);
        long endTime = System.currentTimeMillis();

        // Book frequency map from large text file
        Map<String, Integer> bookFrequencyMap = processTextFile(textFilePath);

        return new Result(disjointPairCount, endTime - startTime, bookFrequencyMap);
    }

    private static int[] parent;
    private static int[] rank;

    private static void initializeUnionFind(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    private static int find(int p) {
        if (parent[p] != p) {
            parent[p] = find(parent[p]);
        }
        return parent[p];
    }

    private static void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP == rootQ) return;

        if (rank[rootP] < rank[rootQ]) {
            parent[rootP] = rootQ;
        } else if (rank[rootP] > rank[rootQ]) {
            parent[rootQ] = rootP;
        } else {
            parent[rootQ] = rootP;
            rank[rootP]++;
        }
    }

    private static int countDisjointPairs(int[] array) {
        Map<Integer, Integer> indexMap = new HashMap<>();
        for (int i = 0; i < array.length; i++) {
            indexMap.put(array[i], i);
        }

        initializeUnionFind(array.length);

        for (Integer value : indexMap.keySet()) {
            int idx1 = indexMap.get(value);
            Integer nextValueIdx = getNextValue(indexMap, value);
            if (nextValueIdx != null) {
                int idx2 = indexMap.get(nextValueIdx);
                union(idx1, idx2);
            }
        }

        Set<Integer> uniqueRoots = new HashSet<>();
        for (int i = 0; i < array.length; i++) {
            uniqueRoots.add(find(i));
        }

        return uniqueRoots.size();
    }

    private static Integer getNextValue(Map<Integer, Integer> indexMap, int value) {
        Integer nextKey = null;
        for (Integer key : indexMap.keySet()) {
            if (key > value) {
                nextKey = key;
                break;
            }
        }
        return nextKey != null ? indexMap.get(nextKey) : null;
    }

    private static Map<String, Integer> processTextFile(Path filePath) throws IOException {
        Map<String, Integer> frequencyMap = new HashMap<>();
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                Matcher matcher = BOOK_PATTERN.matcher(line);
                while (matcher.find()) {
                    String bookTitle = matcher.group();
                    frequencyMap.merge(bookTitle, 1, Integer::sum);
                }
            }
        }
        return frequencyMap;
    }

    private static Pattern buildPattern(List<String> books) {
        List<String> escapedBooks = new ArrayList<>();
        for (String book : books) {
            escapedBooks.add(Pattern.quote(book));
        }
        String patternString = "\\b(" + String.join("|", escapedBooks) + ")\\b";
        return Pattern.compile(patternString, Pattern.CASE_INSENSITIVE);
    }

    public static void main(String[] args) throws IOException {
        int[] array = {1, 2, 3, 4, 5, 6};
        Path textFilePath = Paths.get("path/to/large/text/file.txt");
        Result result = processArrayAndText(array, textFilePath);

        System.out.println("Disjoint Pair Count: " + result.disjointPairCount);
        System.out.println("Time Taken for Disjoint Pairs (ms): " + result.timeTakenForDisjointPairs);
        System.out.println("Book Frequency Map: " + result.bookFrequencyMap);
    }
}
