Packet process_packets(Packet** packets, int num_packets) {
    static Packet highest_priority_packet = {0, 0, -1.0};
    time_t current_time;
    double max_score = -1.0;
    uint64_t high_priority_id = 0;

    // Update packet window based on the current timestamp
    time(&current_time);
    if (difftime(current_time, packet_window.timestamp) >= 1.0) {
        packet_window.timestamp = current_time;
        packet_window.packet_count = 0;
    }

    for (int i = 0; i < num_packets; ++i) {
