        if (score == -1.0) { // Simulating failure in external dependency
            log_packet_stats("External source unavailable for priority calculation");
            continue;
        }

        // Update rolling packet count
        window->packet_count++;

        // Check and update highest priority score
        if (score > max_score) {
            max_score = score;
            high_priority_id = packets[i]->packet_id;
        }
    }

    // Log packet statistics
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Processed %d packets in the last second", packet_window.packet_count);
    log_packet_stats(log_message);

    highest_priority_packet.priority_score = max_score;
    highest_priority_packet.packet_id = high_priority_id;

    return highest_priority_packet;
}

// Example logging function integration
