// Logging utility
void logMessage(const std::string& message) {
    std::cout << "[LOG] " << message << std::endl;
}

// Function to initialize OpenSSL
void initializeOpenSSL() {
    SSL_load_error_strings();
    OpenSSL_add_all_algorithms();
}

// Function to clean up OpenSSL
void cleanupOpenSSL() {
    EVP_cleanup();
}

// Function to perform cryptographic operations
bool performCryptoOperations() {
    // Add AES and Camellia ciphers
    if (!EVP_add_cipher(EVP_aes_256_cbc()) || !EVP_add_cipher(EVP_camellia_128_ecb())) {
        logMessage("Failed to add ciphers");
        return false;
    }

