['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// System-defined limits
#define MAX_SYSTEM_POOL_SIZE 15000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    FILE *log_file;
    int successful_allocations;
    int failed_attempts;
    clock_t total_allocation_time;
} CRCIndicationPool;

// Global configuration
size_t max_pool_size = 10000;
pthread_mutex_t config_lock;

void log_message(const char* message) {
    static pthread_once_t once = PTHREAD_ONCE_INIT;
    static FILE *log_file = NULL;

    pthread_once(&once, []() { log_file = fopen("nfa_crc_log.txt", "a"); });

    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

void init_pool(CRCIndicationPool* pool, size_t initial_size) {
    pthread_mutex_lock(&config_lock);
    if (initial_size > max_pool_size || initial_size > MAX_SYSTEM_POOL_SIZE) {
        log_message("Configuration error: Pool size exceeds limits.");
        pthread_mutex_unlock(&config_lock);
        return;
    }
    pthread_mutex_unlock(&config_lock);

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);

    pool->size = initial_size;
    pool->count = 0;
    pool->successful_allocations = 0;
    pool->failed_attempts = 0;
    pool->total_allocation_time = 0;

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        log_message("Allocation error: Failed to allocate memory for the pool.");
    }
}

int allocate_struct(CRCIndicationPool* pool) {
    pthread_mutex_lock(&pool->lock);
    clock_t start_time = clock();

    if (pool->count >= pool->size) {
        pthread_mutex_unlock(&pool->lock);
        log_message("Allocation error: Pool is full.");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &pool->pool[pool->count];

    // Simulate fetching RX_UE_INFORMATION_TAG
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;

    // Ensure RNTI is unique and non-repetitive
    int new_rnti;
    do {
        new_rnti = rand() % 10000;
    } while (new_rnti == ((pool->count > 0) ? pool->pool[pool->count - 1].RNTI : -1));

    pdu->RNTI = new_rnti;

    // Probabilistic CRCFLAG assignment
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);

    pool->count++;
    clock_t end_time = clock();
    pool->successful_allocations++;
    pool->total_allocation_time += (end_time - start_time);

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void free_pool(CRCIndicationPool* pool) {
    if (pool->pool) {
        free(pool->pool);
        pool->pool = NULL;
    }
    pthread_mutex_destroy(&pool->lock);
    pthread_cond_destroy(&pool->cond);
}

size_t get_statistics(const CRCIndicationPool *pool, int* successful_allocations,
                      int* failed_attempts, double* average_allocation_time) {
    pthread_mutex_lock(&config_lock);

    if (successful_allocations) *successful_allocations = pool->successful_allocations;
    if (failed_attempts) *failed_attempts = pool->failed_attempts;

    if (average_allocation_time && pool->successful_allocations > 0) {
        double avg_time = ((double)pool->total_allocation_time) / CLOCKS_PER_SEC /
                          pool->successful_allocations;
        *average_allocation_time = avg_time;
    }

    pthread_mutex_unlock(&config_lock);
}

void set_max_pool_size(size_t new_size) {
    pthread_mutex_lock(&config_lock);

    if (new_size > MAX_SYSTEM_POOL_SIZE || new_size < 1) {
        log_message("Configuration error: Invalid max pool size.");
    } else {
        max_pool_size = new_size;
    }

    pthread_mutex_unlock(&config_lock);
}

int main() {
    CRCIndicationPool crcPool;
    init_pool(&crcPool, 1000);

    for (int i = 0; i < 1050; ++i) {
        allocate_struct(&crcPool);
    }

    int successful_allocs, failed_attempts;
    double avg_time;

    get_statistics(&crcPool, &successful_allocs, &failed_attempts, &avg_time);
    printf("Successful Allocations: %d\n", successful_allocs);
    printf("Failed Attempts: %d\n", failed_attempts);
    if (avg_time) {
        printf("Average Allocation Time: %.6f seconds\n", avg_time);
    }

    free_pool(&crcPool);
    return 0;
}
```

