#define NONCE_SIZE 12

typedef struct {
    unsigned char key[MAX_KEY_LENGTH];
    size_t key_len;
} Key;

typedef enum {
    SHA256,
    SHA384,
    AES_GCM,
    AES_CFB
} CryptoMode;

// Function prototypes
void generate_key(Key *key, size_t len);
int compute_hash(CryptoMode mode, const unsigned char *data, size_t data_len, unsigned char **hash_out, size_t *hash_len);
int encrypt_data(CryptoMode mode, const Key *key, const unsigned char *plaintext, size_t plaintext_len,
                 unsigned char **ciphertext_out, size_t *ciphertext_len, unsigned char *nonce_out);
int decrypt_data(CryptoMode mode, const Key *key, const unsigned char *ciphertext, size_t ciphertext_len,
                 unsigned char **plaintext_out, size_t *plaintext_len, const unsigned char *nonce);

// Thread-safe critical section for key management
pthread_mutex_t key_management_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_key(Key *key, size_t len) {
    if (len > MAX_KEY_LENGTH) return;
    RAND_bytes(key->key, len);
    key->key_len = len;
}

int compute_hash(CryptoMode mode, const unsigned char *data, size_t data_len, unsigned char **hash_out, size_t *hash_len) {
    EVP_MD_CTX *mdctx;
    const EVP_MD *md;

    switch (mode) {
        case SHA256: md = EVP_sha256(); break;
        case SHA384: md = EVP_sha384(); break;
        default: return -1; // Unsupported hash mode
    }

    mdctx = EVP_MD_CTX_new();
    if (!mdctx) return -1;

    if (EVP_DigestInit_ex(mdctx, md, NULL) <= 0) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    if (EVP_DigestUpdate(mdctx, data, data_len) <= 0) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    *hash_len = EVP_MD_size(md);
    *hash_out = malloc(*hash_len);
    if (*hash_out == NULL) {
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    if (EVP_DigestFinal_ex(mdctx, *hash_out, hash_len) <= 0) {
        free(*hash_out);
        EVP_MD_CTX_free(mdctx);
        return -1;
    }

    EVP_MD_CTX_free(mdctx);
    return 0;
}

