// Semaphore wrapper for cross-platform compatibility
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int count;
} semaphore_t;

// Function to create a semaphore
void init_semaphore(semaphore_t *sem, int initial_count) {
    sem->count = initial_count;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

// Wait on the semaphore
void wait_semaphore(semaphore_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->count == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);
}

// Signal the semaphore
void signal_semaphore(semaphore_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

