// Function to read integers from a file stream and process them.
void processIntegersFromFile(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    int *numbers = NULL;
    size_t capacity = 0, count = 0;
    int number;

    // Read integers from the file
    while (fscanf(file, "%d", &number) == 1) {
        if (count >= capacity) {
            capacity = capacity ? capacity * 2 : 4; // Double capacity or start at 4
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                perror("Memory allocation error");
                fclose(file);
                return;
            }
        }
        numbers[count++] = number;
    }

    if (ferror(file)) {
        fprintf(stderr, "Error reading file\n");
        free(numbers);
        fclose(file);
        return;
    }

    fclose(file);

    if (count == 0) {
        printf("No valid integers found.\n");
        free(numbers);
        return;
    }

    // Find the largest integer
    int max = numbers[0];
    for (size_t i = 1; i < count; ++i) {
        if (numbers[i] > max) {
            max = numbers[i];
        }
    }

    // Compute the average
    double sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    double average = sum / count;

    // Determine the median value
    qsort(numbers, count, sizeof(int), compareIntegers);
    double median;
    if (count % 2 == 0) {
        median = (numbers[count / 2 - 1] + numbers[count / 2]) / 2.0;
    } else {
        median = numbers[count / 2];
    }

    // Print results
    printf("Largest integer: %d\n", max);
    printf("Average: %.2f\n", average);
    printf("Median: %.2f\n", median);

    free(numbers);
}

// Comparison function for qsort
int compareIntegers(const void *a, const void *b) {
    int intA = *(const int *)a;
    int intB = *(const int *)b;
    return (intA > intB) - (intA < intB);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processIntegersFromFile(argv[1]);

    return EXIT_SUCCESS;
}
