['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define STRING_LENGTH 10

typedef struct Node {
    char str[STRING_LENGTH];
    int value;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t lock; // For thread safety
} LinkedList;

unsigned int hash_function(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash % (STRING_LENGTH * sizeof(Node));
}

LinkedList* create_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_node(LinkedList* list, const char* str) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    strncpy(new_node->str, str, STRING_LENGTH - 1);
    new_node->str[STRING_LENGTH - 1] = '\0';
    new_node->value = hash_function(str);
    new_node->next = list->head;
    list->head = new_node;

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

Node* get_node_by_index(LinkedList* list, size_t index) {
    if (index >= list->size) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }

    Node* result = current;
    pthread_mutex_unlock(&list->lock);
    return result;
}

void delete_node(LinkedList* list, size_t index) {
    if (index >= list->size || !list->head) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    for (size_t i = 0; i < index && current != NULL; i++) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (!prev) { // Deleting the head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    list->size--;
    pthread_mutex_unlock(&list->lock);
}

void traverse_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        printf("String: %s, Value: %d\n", current->str, current->value);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* list = create_list();
    add_node(list, "example");
    add_node(list, "testnode");

    Node* node = get_node_by_index(list, 1);
    if (node) {
        printf("Retrieved Node: String: %s, Value: %d\n", node->str, node->value);
    }

    delete_node(list, 0);

    traverse_list(list);

    free_list(list);
    return 0;
}
