#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// AES Initialization with SHA-1 derived key
void initialize_aes(const char *password, unsigned char **key, unsigned char **iv) {
    const EVP_CIPHER *cipher;
    cipher = EVP_aes_256_cbc();

    // Derive key using SHA-1
    unsigned char sha1_digest[SHA_DIGEST_LENGTH];
    SHA1((unsigned char *)password, strlen(password), sha1_digest);

    // Set the encryption key and IV
    if (key) *key = malloc(cipher->key_len);
    memcpy(*key, sha1_digest, cipher->key_len);

    if (iv) {
        static unsigned char iv_value[AES_BLOCK_SIZE];
        memset(iv_value, 0, AES_BLOCK_SIZE); // Example IV setup
        *iv = iv_value;
    }
}

// Secure cleanup routine for the cipher
void cleanup_aes(unsigned char *key) {
    if (key) {
        OPENSSL_cleanse(key, EVP_MAX_KEY_LENGTH);
        free(key);
    }
}

// Theme caching and management
typedef struct {
    FILE **theme_cache;
    size_t cache_size;
} ThemeCache;

void initialize_theme_cache(ThemeCache *cache, const char *directory, size_t size) {
    cache->theme_cache = malloc(size * sizeof(FILE *));
    cache->cache_size = 0;

    for (size_t i = 0; i < size && cache->cache_size < size; ++i) {
        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/theme%d.png", directory, i);
        FILE *file = fopen(filepath, "rb");
        if (file) {
            cache->theme_cache[cache->cache_size++] = file;
        }
    }
}

void recycle_unused_theme(ThemeCache *cache, size_t index) {
    if (index < cache->cache_size && cache->theme_cache[index]) {
        fclose(cache->theme_cache[index]);
        cache->theme_cache[index] = NULL;
    }
}

// Graph database operations
typedef struct Vertex {
    int id;
    char properties[256];
} Vertex;

typedef struct Edge {
    int src_id, dst_id;
    char properties[256];
} Edge;

void add_vertices_and_edges(size_t num_vertices, size_t num_edges) {
    Vertex *vertices = malloc(num_vertices * sizeof(Vertex));
    Edge *edges = malloc(num_edges * sizeof(Edge));

    // Initialize vertices and edges with random data
    for (size_t i = 0; i < num_vertices; ++i) {
        vertices[i].id = rand() % 10000;
        snprintf(vertices[i].properties, sizeof(vertices[i].properties), "prop-%zu", i);
    }

    for (size_t i = 0; i < num_edges; ++i) {
        edges[i].src_id = rand() % num_vertices;
        edges[i].dst_id = rand() % num_vertices;
        snprintf(edges[i].properties, sizeof(edges[i].properties), "edge-prop-%zu", i);
    }

    // Simulate storing or processing the graph
    for (size_t i = 0; i < num_edges; ++i) {
        printf("Edge from Vertex %d to Vertex %d with properties: %s\n",
               edges[i].src_id, edges[i].dst_id, edges[i].properties);
    }

    free(vertices);
    free(edges);
}

int main() {
    const char *password = "strongpassword";
    unsigned char *key, *iv;

    // Initialize AES
    initialize_aes(password, &key, &iv);

    // Theme cache management
    ThemeCache theme_cache;
    initialize_theme_cache(&theme_cache, "/path/to/themes", 10);
    recycle_unused_theme(&theme_cache, 2); // Example of recycling

    // Add vertices and edges to graph database
    add_vertices_and_edges(1000, 5000);

    // Cleanup AES resources
    cleanup_aes(key);

    // Free theme cache files
    for (size_t i = 0; i < theme_cache.cache_size; ++i) {
        if (theme_cache.theme_cache[i]) {
            fclose(theme_cache.theme_cache[i]);
        }
    }
    free(theme_cache.theme_cache);

    return 0;
}
```

### Key Points:
- **AES Initialization**: Uses SHA-1 to derive a key from the password and sets up an AES-256-CBC cipher.
- **Secure Cleanup**: Ensures sensitive data is securely erased using `OPENSSL_cleanse`.
- **Theme Cache Management**: Initializes and manages theme cache files, recycling unused entries.
- **Graph Database Operations**: Adds vertices and edges with random properties, simulating a graph database operation.
- **Separation of Concerns**: Cryptographic operations are distinct from graph database logic, ensuring maintainability.']

