    int capacity;
    struct Edge* next;
} Edge;

typedef struct Node {
    int id;
    Edge* edges;
} Node;

#define MAX_NODES 1000000

Node* nodes = NULL;
int current_node_count = 0;
const size_t max_memory_usage = 1024 * 1024 * 1024; // Example memory limit, adjust as needed
size_t current_memory_usage = 0;

void log(const char* message) {
    printf("%s\n", message); // Replace with actual logging mechanism
}

Node* create_node(int id) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        log("Memory allocation failed for node");
        return NULL;
    }
    node->id = id;
    node->edges = NULL;
    current_memory_usage += sizeof(Node);
    return node;
}

Edge* create_edge(int node_id, int weight, int capacity) {
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    if (!edge) {
        log("Memory allocation failed for edge");
        return NULL;
    }
    edge->node_id = node_id;
    edge->weight = weight;
    edge->capacity = capacity;
    edge->next = NULL;
    current_memory_usage += sizeof(Edge);
    return edge;
}

int add_edge(Node* node, int node_id, int weight, int capacity) {
    if (current_memory_usage + sizeof(Edge) > max_memory_usage) {
        log("Memory limit approached, degrading performance");
        return 0;
    }

    Edge* new_edge = create_edge(node_id, weight, capacity);
    if (!new_edge) return 0;

    new_edge->next = node->edges;
    node->edges = new_edge;
    return 1;
}

void initialize_network(int adjacency_matrix[MAX_NODES][MAX_NODES], int num_nodes) {
    nodes = (Node*)malloc(num_nodes * sizeof(Node));
    if (!nodes) {
        log("Memory allocation failed for nodes array");
        return;
    }
    current_memory_usage += num_nodes * sizeof(Node);

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = *(create_node(i)); // Initialize node
        for (int j = 0; j < num_nodes; ++j) {
            if (adjacency_matrix[i][j] > 0 && i != j) { // Avoid self-loops
                add_edge(&nodes[i], j, adjacency_matrix[i][j], 100); // Example capacity
            }
        }
    }

    log("Network initialized successfully");
}

void free_network() {
    for (int i = 0; i < current_node_count; ++i) {
        Edge* edge = nodes[i].edges;
        while (edge) {
            Edge* temp = edge;
            edge = edge->next;
            free(temp);
            current_memory_usage -= sizeof(Edge);
        }
    }
    free(nodes);
    log("Network memory freed");
}

int main() {
    int adjacency_matrix[MAX_NODES][MAX_NODES] = {0}; // Example initialization
    int num_nodes = 100; // Example node count

    initialize_network(adjacency_matrix, num_nodes);

    // Perform operations...

    free_network();
    return 0;
}
