['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

typedef struct MetadataEntry {
    int value;
    struct MetadataEntry *next;
} MetadataEntry;

typedef struct Metadata {
    bool flag;
    time_t timestamp;
    MetadataEntry *entries;
} Metadata;

typedef struct Node {
    char str[11];
    int integer_value;
    Metadata metadata;
    struct Node *next;
} Node;

unsigned int hash_function(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return (unsigned int)(hash & 0xFFFFFFFF);
}

int initialize_nodes(int num_nodes, int min_val, int max_val) {
    if (num_nodes <= 0 || min_val > max_val)
        return -1;

    Node *head = NULL;
    Node **tail = &head;
    srand(time(NULL));

    for (int i = 0; i < num_nodes; ++i) {
        Node *node = (Node *)malloc(sizeof(Node));
        if (!node) return -1;

        snprintf(node->str, sizeof(node->str), "String_%d", i);
        node->integer_value = hash_function(node->str);

        node->metadata.flag = rand() % 2 == 0;
        node->metadata.timestamp = time(NULL);

        MetadataEntry *entry_head = NULL;
        MetadataEntry **entry_tail = &entry_head;

        for (int j = 0; j < 5; ++j) {
            MetadataEntry *entry = (MetadataEntry *)malloc(sizeof(MetadataEntry));
            if (!entry) return -1;

            entry->value = min_val + rand() % (max_val - min_val + 1);
            entry->next = NULL;
            *entry_tail = entry;
            entry_tail = &entry->next;
        }

        node->metadata.entries = entry_head;
        *tail = node;
        tail = &node->next;
    }
    *tail = NULL;

    Node *current_node = head;
    while (current_node) {
        printf("Node String: %s, Integer Value: %d\n", current_node->str, current_node->integer_value);
        printf("Metadata Flag: %s, Timestamp: %ld\n", current_node->metadata.flag ? "true" : "false", current_node->metadata.timestamp);

        MetadataEntry *current_entry = current_node->metadata.entries;
        while (current_entry) {
            printf("  Metadata Entry Value: %d\n", current_entry->value);
            MetadataEntry *temp_entry = current_entry;
            current_entry = current_entry->next;
            free(temp_entry);
        }

        Node *node_to_free = current_node;
        current_node = current_node->next;
        free(node_to_free);
    }

    return 0;
}

int main() {
    int num_nodes = 10;
    int min_val = 1, max_val = 100;

    if (initialize_nodes(num_nodes, min_val, max_val) != 0) {
        fprintf(stderr, "Memory allocation failed or invalid parameters\n");
        return -1;
    }

    return 0;
}
