        temp->data.RNTI = rand() % 1000 + 1;
        temp->data.RX_UE_INFORMATION_TAG = rand() % 256;
        temp->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_lock(mutex);
        temp->next = head;
        head = temp;
        pthread_mutex_unlock(mutex);
    }

    return head;
}

void free_linked_list(Node *head) {
    Node *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void manage_memory_and_initialize() {
    const int MAX_INPUT_SIZE = 10000;
    const int RECORD_POOL_SIZE = 100;

    long *offsets = malloc(sizeof(long) * MAX_INPUT_SIZE);
    if (!offsets) return;

    int *keys = malloc(sizeof(int) * MAX_INPUT_SIZE);
    if (!keys) {
        free(offsets);
        return;
