    int record_count = rand() % RECORD_POOL_SIZE + 1;
    struct Record {
        int value;
    };

    struct Record *records = malloc(sizeof(struct Record) * record_count);
    if (!records) {
        free(keys);
        free(offsets);
        return;
    }

    for (int i = 0; i < record_count; ++i) {
        records[i].value = rand() % 100 + 1;
    }

    int input_size = 0;
    int input[MAX_INPUT_SIZE];

    printf("Enter integers (up to %d): ", MAX_INPUT_SIZE);
    while (input_size < MAX_INPUT_SIZE && scanf("%d", &input[input_size]) == 1) {
        ++input_size;
    }

    print_largest(input, input_size);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    Node *linked_list = create_linked_list(record_count, &mutex);

    free_linked_list(linked_list);

    free(records);
    free(keys);
    free(offsets);
}
