void read_and_process_integers() {
    char *line = NULL;
    size_t len = 0;
    ssize_t nread;

    // Read input
    if ((nread = getline(&line, &len, stdin)) == -1) {
        fprintf(stderr, "Error reading input\n");
        exit(EXIT_FAILURE);
    }
    free(line);

    int *numbers = NULL;
    size_t count = 0;

    line = NULL; len = 0;
    if ((nread = getline(&line, &len, stdin)) == -1) {
        fprintf(stderr, "Error reading input\n");
        exit(EXIT_FAILURE);
    }

    char *token = strtok(line, " \t\n");
    while (token != NULL) {
        numbers = realloc(numbers, sizeof(int) * (count + 1));
        if (!numbers) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        numbers[count++] = atoi(token);
        token = strtok(NULL, " \t\n");
    }

    free(line);

    // Edge case: No integers provided
    if (count == 0) {
        printf("No input provided.\n");
        return;
    }

    // Sort the array in descending order
    for (size_t i = 0; i < count - 1; ++i) {
        for (size_t j = i + 1; j < count; ++j) {
            if (numbers[i] < numbers[j]) {
                int temp = numbers[i];
                numbers[i] = numbers[j];
                numbers[j] = temp;
            }
        }
    }

    // Calculate the median
    int median;
    if (count % 2 == 1) {
        median = numbers[count / 2];
    } else {
        median = numbers[(count - 1) / 2];
    }

    printf("Median: %d\n", median);

    // Interact with external API for employee details
    int cache_capacity = count * 2;  // Assume a simple cache that can store twice the number of IDs
    char **cache = calloc(cache_capacity, sizeof(char *));
    if (!cache) {
        perror("Failed to allocate memory");
        free(numbers);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        EmployeeDetails *details = get_employee_details(numbers[i], cache);

        print_employee_details(details);

        // Free individual details if not cached
        if (!cache[numbers[i]]) {
            free(details->name);
            free(details->city);
            free(details->address);
            free(details);
        }
    }

    free_employee_details_cache(cache, cache_capacity);
    free(numbers);
}

int main() {
    read_and_process_integers();
    return 0;
}
