} Record;

typedef struct {
    pthread_mutex_t *offset_locks;
    long *offset_values;
    pthread_mutex_t *key_locks;
    int *keys;
    size_t num_records;
} SharedData;

// Mock function to simulate fetching external configuration
int fetch_external_configuration(size_t *num_records, int *value_range) {
    // Simulate successful fetch with dummy values
    *num_records = 10; // Example number of records
    *value_range = 100; // Example value range for random numbers
    return 0; // Return 0 on success
}

int initialize_shared_data(SharedData **data, size_t num_records) {
    if (!data || num_records == 0) return -1;

    *data = malloc(sizeof(SharedData));
    if (*data == NULL) return -2;

    pthread_mutex_t *offset_locks = calloc(num_records, sizeof(pthread_mutex_t));
    pthread_mutex_t *key_locks = calloc(num_records, sizeof(pthread_mutex_t));
    long *offset_values = calloc(num_records, sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    if (!offset_locks || !key_locks || !offset_values || !keys) {
        free(offset_locks);
        free(key_locks);
        free(offset_values);
        free(keys);
        free(*data);
        return -3;
    }

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_init(&offset_locks[i], NULL);
        pthread_mutex_init(&key_locks[i], NULL);
    }

    (*data)->offset_locks = offset_locks;
    (*data)->keys = keys;
    (*data)->key_locks = key_locks;
    (*data)->offset_values = offset_values;
    (*data)->num_records = num_records;

    return 0; // Success
}

int initialize_records(Record **records, size_t num_records, int value_range) {
    if (!records || num_records == 0) return -1;

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) return -2;

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&offset_locks[i]);
        (*records)[i].value = rand() % value_range;
        pthread_mutex_unlock(&offset_locks[i]);
    }

    return 0; // Success
}

int main() {
    size_t num_records;
    int value_range;

    if (fetch_external_configuration(&num_records, &value_range) != 0) {
        fprintf(stderr, "Failed to fetch configuration.\n");
        return -1;
    }

    SharedData *shared_data = NULL;
    Record *records = NULL;

    if (initialize_shared_data(&shared_data, num_records) != 0) {
        fprintf(stderr, "Failed to initialize shared data.\n");
        return -2;
    }

    if (initialize_records(&records, num_records, value_range) != 0) {
        fprintf(stderr, "Failed to initialize records.\n");
        free(shared_data->offset_locks);
        free(shared_data->key_locks);
        free(shared_data->offset_values);
        free(shared_data->keys);
        free(shared_data);
        return -3;
    }

    // Further operations with shared_data and records...

