        pthread_mutex_destroy(&shared_data->offset_locks[i]);
        pthread_mutex_destroy(&shared_data->key_locks[i]);
    }
    free(shared_data->offset_locks);
    free(shared_data->key_locks);
    free(shared_data->offset_values);
    free(shared_data->keys);
    free(shared_data);
    free(records);

    return 0;
}
