['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <errno.h>
#include <netdb.h>

#define MAX_SERVICES 100
#define DEFAULT_INTERVAL 10
#define DEFAULT_THRESHOLD 200 // in milliseconds

typedef struct {
    char *name;
    char *address;
    int port;
    int interval; // in seconds
    int threshold; // in milliseconds
} Service;

typedef struct {
    Service services[MAX_SERVICES];
    int count;
} MonitoringConfig;

// External logging function (placeholder)
void log_status(const char *message) {
    printf("%s\n", message);
}

// Function to send a ping and measure response time
int ping_service(Service *service, long *response_time) {
    struct addrinfo hints, *res, *p;
    int sockfd, status, rv;
    socklen_t len;
    char buf[1024];
    struct timeval start, end;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(service->address, NULL, &hints, &res)) != 0) {
        log_status("Failed to resolve address");
        return -1;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd == -1) continue;

        if (connect(sockfd, p->ai_addr, p->ai_addrlen) == 0) break;
        close(sockfd);
    }

    freeaddrinfo(res);

    if (p == NULL) {
        log_status("Failed to connect");
        return -1;
    }

    gettimeofday(&start, NULL);
    len = sizeof(buf);
    rv = recv(sockfd, buf, len, MSG_PEEK | MSG_DONTWAIT);
    if (rv < 0 && errno != EWOULDBLOCK) {
        close(sockfd);
        log_status("Failed to receive data");
        return -1;
    }

    gettimeofday(&end, NULL);

    *response_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000;

    close(sockfd);

    return rv >= 0 ? 0 : -1;
}

// Worker thread function
void* monitor_service(void *arg) {
    Service *service = (Service *)arg;
    long response_time;

    while (1) {
        if (ping_service(service, &response_time) == 0) {
            char status[256];
            snprintf(status, sizeof(status), "Service %s responded in %ld ms", service->name, response_time);
            log_status(status);

            if (response_time > service->threshold) {
                snprintf(status, sizeof(status), "ALERT: Service %s exceeded threshold with %ld ms", service->name, response_time);
                log_status(status);
            }
        } else {
            char status[256];
            snprintf(status, sizeof(status), "Service %s is unreachable", service->name);
            log_status(status);
        }

        sleep(service->interval);
    }

    return NULL;
}

// Main monitoring function
void start_network_monitoring(MonitoringConfig *config) {
    pthread_t threads[MAX_SERVICES];

    for (int i = 0; i < config->count; ++i) {
        if (pthread_create(&threads[i], NULL, monitor_service, &config->services[i])) {
            log_status("Failed to create thread");
            exit(1);
        }
    }

    for (int i = 0; i < config->count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Example usage
int main() {
    MonitoringConfig config;
    memset(&config, 0, sizeof(MonitoringConfig));

    Service service1 = {"Service1", "192.168.1.1", 80, DEFAULT_INTERVAL, DEFAULT_THRESHOLD};
    Service service2 = {"Service2", "example.com", 443, DEFAULT_INTERVAL, DEFAULT_THRESHOLD};

    config.services[0] = service1;
    config.services[1] = service2;
    config.count = 2;

    start_network_monitoring(&config);

    return 0;
}
```

This C code snippet demonstrates a scalable network monitoring tool that continuously assesses the health of network services by sending periodic pings and evaluating their responsiveness. It includes error handling, logging, and concurrent operations using threads for efficiency. The function allows customizable ping intervals and health alert thresholds, making it flexible for various configurations.']

['```javascript
const { exec } = require('child_process');
const NodeCache = require("node-cache");
const cache = new NodeCache({ stdTTL: 100, checkperiod: 120 });
const rateLimit = require('express-rate-limit');
const express = require('express');
const app = express();
const os = require('os');

// Middleware for rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: "Too many requests from this IP, please try again later."
});

app.use(limiter);

// Execute shell command with timeout and caching
function executeCommand(command, envVars = {}, timeout = 5000) {
    return new Promise((resolve, reject) => {
        const startTime = Date.now();

        // Check cache first
        const cacheKey = `${command}_${JSON.stringify(envVars)}`;
        if (cache.has(cacheKey)) {
            resolve({
                data: cache.get(cacheKey),
                executionTime: Date.now() - startTime,
                success: true
            });
            return;
        }

        exec(command, { env: { ...process.env, ...envVars } }, (error, stdout, stderr) => {
            const endTime = Date.now();
            if (error) {
                reject({ error: error.message, executionTime: endTime - startTime, success: false });
                return;
            }

            // Store in cache
            cache.set(cacheKey, { stdout, stderr });

            resolve({
                data: { stdout, stderr },
                executionTime: endTime - startTime,
                success: true
            });
        });
    }).timeout(timeout); // Add timeout handling if using a library like Bluebird
}

// Middleware for logging metrics
function logMetrics(req, res, next) {
    const start = process.hrtime();
    res.on('finish', () => {
        const executionTime = process.hrtime(start);
        console.log(`Execution time: ${executionTime[0] * 1e3 + executionTime[1] / 1e6} ms`);
    });
    next();
}

app.use(logMetrics);

// Endpoint for executing commands
app.post('/execute', express.json(), async (req, res) => {
    const { command, envVars = {}, timeout } = req.body;

    try {
        const result = await executeCommand(command, envVars, timeout || 5000);
        res.json({
            ...result,
            message: 'Command executed successfully'
        });
    } catch (error) {
        res.status(500).json({
            error: error.error,
            executionTime: error.executionTime,
            success: false,
            message: 'Error executing command'
        });
    }
});

// Horizontal scaling setup
const port = process.env.PORT || 3000;
const numCPUs = os.cpus().length;

app.listen(port * numCPUs, () => {
    console.log(`Server running on ports ${port} - ${(port + numCPUs)}`);
});
```

