// AES-256-CBC Initialization Function using OpenSSL

#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>
#include <stdlib.h>

#define SHA256_DIGEST_LENGTH 32
#define AES_KEYLEN 32
#define IV_LEN 16

EVP_CIPHER_CTX* initialize_aes_cipher(const char* password, unsigned char* iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using SHA-256 hash of the password
    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);

    // Initialize cipher context for AES-256-CBC
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
