    threading.Lock lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    threading.Lock_init(&list->lock);
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    threading.Lock_destroy(&list->lock);
    free(list);
}

