import os
import hashlib
import sqlite3
from concurrent.futures import ThreadPoolExecutor
import requests

# Configuration
DATABASE_PATH = 'file_hashes.db'
API_ENDPOINT = "https://api.example.com/log"
CHUNK_SIZE = 4096  # Adjust as necessary for optimal performance


def create_database():
    conn = sqlite3.connect(DATABASE_PATH)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS file_hashes (
            filename TEXT PRIMARY KEY,
            hash TEXT,
            last_modified INTEGER
        )
    ''')
    conn.commit()
    conn.close()


def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(CHUNK_SIZE), b""):
                md5_hash.update(chunk)
        return md5_hash.hexdigest()
    except Exception as e:
        log_error(f"Error calculating hash for {file_path}: {str(e)}")
        raise


def update_database(file_path, file_hash):
    conn = sqlite3.connect(DATABASE_PATH)
    cursor = conn.cursor()
    last_modified = os.path.getmtime(file_path)

    try:
        cursor.execute('''
            INSERT OR REPLACE INTO file_hashes (filename, hash, last_modified)
            VALUES (?, ?, ?)
        ''', (file_path, file_hash, last_modified))
        conn.commit()
    except Exception as e:
        log_error(f"Error updating database for {file_path}: {str(e)}")
        raise
    finally:
        conn.close()


def process_file(file_path):
    try:
        file_hash = calculate_md5(file_path)
        update_database(file_path, file_hash)
    except Exception as e:
        handle_retryable_exception(e)


def log_error(message):
    # Example error logging with API integration
    response = requests.post(API_ENDPOINT, json={"error": message})
    if not response.ok:
        print(f"Failed to log error: {message}")


def handle_retryable_exception(exception, retries=3, delay=2):
    for attempt in range(retries):
        try:
            # Attempt operation again
            pass  # Placeholder for retry logic (e.g., process_file call)
        except Exception as e:
            if attempt < retries - 1:
                time.sleep(delay)
            else:
                log_error(f"Persistent error after {retries} attempts: {str(e)}")


def scan_directory(directory_path):
    with ThreadPoolExecutor() as executor:
        for root, _, files in os.walk(directory_path):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                executor.submit(process_file, file_path)


if __name__ == "__main__":
    create_database()
    directory_to_scan = "/path/to/your/directory"
    scan_directory(directory_to_scan)
