                datetime.fromisoformat(session['start_time'])).total_seconds()
    return validate_session(session) and duration >= criteria.get('min_duration', 0)

def process_sessions(file_path, config):
    user_sessions = defaultdict(list)

    for chunk in read_jsonl_in_chunks(file_path):
        for session in chunk:
            if filter_session(session, config['filter_criteria']):
                user_id = session['user_id']
                start_time = datetime.fromisoformat(session['start_time'])
                end_time = datetime.fromisoformat(session['end_time'])
                duration = (end_time - start_time).total_seconds()

                user_sessions[user_id].append(duration)

    all_durations = [duration for durations in user_sessions.values() for duration in durations]

    if all_durations:
        return median(all_durations)
    return 0.0

def main(file_path, config):
    try:
        median_duration = process_sessions(file_path, config)
        print(f"Median session duration: {median_duration:.2f} seconds")
    except Exception as e:
        # Implement logging logic
        print(f"Error processing file: {e}")

if __name__ == "__main__":
    config = {
        'filter_criteria': {'min_duration': 60},  # Example criteria
    }

    # Example usage with a single file path; for scalability, this can be adapted to process multiple files.
    file_path = "path/to/large/jsonl/file.jsonl"
    main(file_path, config)
```

