typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI 65535

typedef enum { SYNC_MODE, ASYNC_MODE } OperationMode;

typedef void (*Callback)(NFAPI_CRC_INDICATION_PDU_T *pdu);

typedef struct {
    pthread_mutex_t lock;
    bool is_valid[MAX_RNTI + 1];
} RntiManager;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    Callback callback;
} AsyncQueue;

// Global variables
RntiManager rnti_manager = { .lock = PTHREAD_MUTEX_INITIALIZER, .is_valid = {0} };
AsyncQueue async_queue = { .head = NULL, .lock = PTHREAD_MUTEX_INITIALIZER, .callback = NULL };

bool fetch_RX_UE_INFORMATION_TAG(uint16_t *tag) {
    // Simulate fetching from external data source with potential latency
    sleep(1);  // Simulating delay
    if (rand() % 10 < 2) {  // Simulate connection failure with 20% probability
        return false;
    }
    *tag = rand() % MAX_RNTI + 1;  // Return a valid tag
    return true;
}

void process_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, OperationMode mode) {
    if (mode == SYNC_MODE) {
        printf("Processing PDU in sync mode: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    } else {
        pthread_mutex_lock(&async_queue.lock);
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed!\n");
            return;
        }
        new_node->data = *pdu;
        new_node->next = async_queue.head;
        async_queue.head = new_node;
        pthread_mutex_unlock(&async_queue.lock);

        // Trigger callback if set
        if (async_queue.callback) {
            async_queue.callback(pdu);
        }
    }
}

void manage_pdus(uint16_t num_pdus, OperationMode mode, Callback callback) {
    srand(time(NULL));

    for (uint16_t i = 0; i < num_pdus; ++i) {
        uint16_t rnti;
        if (!fetch_RX_UE_INFORMATION_TAG(&rnti)) {
            fprintf(stderr, "Failed to fetch RX_UE_INFORMATION_TAG\n");
            continue;
        }

        pthread_mutex_lock(&rnti_manager.lock);
        while (rnti_manager.is_valid[rnti]) {
            rnti = rand() % MAX_RNTI + 1;  // Try another RNTI
        }
        rnti_manager.is_valid[rnti] = true;
        pthread_mutex_unlock(&rnti_manager.lock);

        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rnti,
            .RNTI = rand() % MAX_RNTI + 1,
            .CRC_INDICATION_REL8_TAG = rand() % 256,
            .CRCFLAG = rand() % 2
        };

        process_pdu(&pdu, mode);
    }

    if (mode == ASYNC_MODE && callback) {
        async_queue.callback = callback;
    }
}

void cleanup_async_queue() {
    Node* current = async_queue.head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    async_queue.head = NULL;
}

// Example callback function
void example_callback(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Async Callback: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
}
