#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdalign.h>

typedef struct {
    int packetID;
    char sourceAddress[16];
    char destinationAddress[16];
} PacketHeader;

typedef struct {
    void* buffer;
    size_t bufferSize;
} BufferPoolEntry;

typedef struct {
    PacketHeader** headers;
    BufferPoolEntry* buffers;
    pthread_mutex_t lock;
    size_t headerCount;
    size_t bufferCount;
    size_t payloadSize;
} NetworkProtocolStack;

// External function to get dynamic payload size
size_t getDynamicPayloadSize();

NetworkProtocolStack* allocateAndInitializeBuffers(size_t headerCount, size_t initialBufferCount) {
    // Allocate memory for the stack structure
    NetworkProtocolStack* stack = (NetworkProtocolStack*)malloc(sizeof(NetworkProtocolStack));
    if (!stack) {
        fprintf(stderr, "Failed to allocate NetworkProtocolStack\n");
        return NULL;
    }

    // Initialize synchronization primitives
    pthread_mutex_init(&stack->lock, NULL);

    // Allocate memory for packet headers
    stack->headers = (PacketHeader**)malloc(headerCount * sizeof(PacketHeader*));
    if (!stack->headers) {
        fprintf(stderr, "Failed to allocate packet headers\n");
        free(stack);
        return NULL;
    }

    for (size_t i = 0; i < headerCount; ++i) {
        stack->headers[i] = (PacketHeader*)malloc(sizeof(PacketHeader));
        if (!stack->headers[i]) {
            fprintf(stderr, "Failed to allocate packet header\n");
            // Free previously allocated headers
            while (i > 0) {
                free(stack->headers[--i]);
            }
            free(stack->headers);
            free(stack);
            return NULL;
        }
    }

    // Initialize buffers with dynamic payload size
    stack->bufferCount = initialBufferCount;
    stack->payloadSize = getDynamicPayloadSize();

    // Allocate aligned memory for buffer pool
    stack->buffers = (BufferPoolEntry*)aligned_alloc(64, stack->bufferCount * sizeof(BufferPoolEntry));
    if (!stack->buffers) {
        fprintf(stderr, "Failed to allocate buffer pool\n");
        // Free previously allocated headers
        for (size_t i = 0; i < headerCount; ++i) {
            free(stack->headers[i]);
        }
        free(stack->headers);
        free(stack);
        return NULL;
    }

    for (size_t i = 0; i < stack->bufferCount; ++i) {
        stack->buffers[i].bufferSize = stack->payloadSize + sizeof(PacketHeader);
        stack->buffers[i].buffer = malloc(stack->buffers[i].bufferSize);
        if (!stack->buffers[i].buffer) {
            fprintf(stderr, "Failed to allocate buffer\n");
            // Free previously allocated buffers
            while (i > 0) {
                free(stack->buffers[--i].buffer);
            }
            free(stack->buffers);
            // Free previously allocated headers
            for (size_t j = 0; j < headerCount; ++j) {
                free(stack->headers[j]);
            }
            free(stack->headers);
            free(stack);
            return NULL;
        }
    }

    stack->headerCount = headerCount;

    // Logging for debugging and monitoring purposes
    printf("NetworkProtocolStack initialized with %zu headers and %zu buffers\n", headerCount, initialBufferCount);

    return stack;
}

void releaseBuffers(NetworkProtocolStack* stack) {
    if (!stack) return;

    pthread_mutex_destroy(&stack->lock);

    // Free packet headers
    for (size_t i = 0; i < stack->headerCount; ++i) {
        free(stack->headers[i]);
    }
    free(stack->headers);

    // Free buffers
    for (size_t i = 0; i < stack->bufferCount; ++i) {
        free(stack->buffers[i].buffer);
    }
    free(stack->buffers);

    free(stack);
}
