```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// External logging service placeholder
void log_operation(const char *message) {
    // Implement logging logic here
}

// Memory pool management
typedef struct {
    void **pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->capacity = initial_capacity;
    mp->used = 0;
    mp->pool = calloc(initial_capacity, sizeof(void *));
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* pool_alloc(MemoryPool *mp, size_t size) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used < mp->capacity) {
        void *ptr = malloc(size);
        mp->pool[mp->used++] = ptr;
        pthread_mutex_unlock(&mp->lock);
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Handle reallocation or failure
}

void pool_free(MemoryPool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->used; ++i) {
        if (mp->pool[i] == ptr) {
            free(ptr);
            memmove(&mp->pool[i], &mp->pool[i + 1], (mp->used - i - 1) * sizeof(void *));
            --mp->used;
            pthread_mutex_unlock(&mp->lock);
            return;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

void destroy_memory_pool(MemoryPool *mp) {
    for (size_t i = 0; i < mp->used; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

// Key management
typedef struct {
    unsigned char *key;
    size_t key_len;
} CryptoKey;

CryptoKey* generate_key(size_t key_length) {
    CryptoKey *key = pool_alloc(global_memory_pool, sizeof(CryptoKey));
    if (!key) return NULL;

    key->key = malloc(key_length);
    RAND_bytes(key->key, key_length);
    key->key_len = key_length;
    log_operation("Generated new cryptographic key");
    return key;
}

void free_key(CryptoKey *key) {
    if (key) {
        free(key->key);
        pool_free(global_memory_pool, key);
    }
}

// Encryption/Decryption functions
int encrypt_data(const unsigned char *plaintext, int plaintext_len,
                 const CryptoKey *key, unsigned char **ciphertext, size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, NULL) != 1)
        goto cleanup;

    int len;
    *ciphertext_len = plaintext_len + EVP_CIPHER_block_size(EVP_aes_256_cbc());
    *ciphertext = malloc(*ciphertext_len);
    if (!*ciphertext) {
        log_operation("Memory allocation failed during encryption");
        goto cleanup;
    }

    if (EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len) != 1)
        goto cleanup;

    int ciphertext_len_temp = len;
    if (EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len) != 1)
        goto cleanup;

    ciphertext_len_temp += len;
    EVP_CIPHER_CTX_free(ctx);
    log_operation("Data encrypted successfully");
    return ciphertext_len_temp;
cleanup:
    EVP_CIPHER_CTX_free(ctx);
    if (*ciphertext) free(*ciphertext);
    log_operation("Encryption failed");
    return -1;
}

int decrypt_data(const unsigned char *ciphertext, int ciphertext_len,
                 const CryptoKey *key, unsigned char **plaintext, size_t *plaintext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, NULL) != 1)
        goto cleanup;

    int len;
    *plaintext_len = ciphertext_len;
    *plaintext = malloc(*plaintext_len);
    if (!*plaintext) {
        log_operation("Memory allocation failed during decryption");
        goto cleanup;
    }

    if (EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len) != 1)
        goto cleanup;

    int plaintext_len_temp = len;
    if (EVP_DecryptFinal_ex(ctx, *plaintext + len, &len) != 1)
        goto cleanup;

    plaintext_len_temp += len;
    EVP_CIPHER_CTX_free(ctx);
    log_operation("Data decrypted successfully");
    return plaintext_len_temp;
cleanup:
    EVP_CIPHER_CTX_free(ctx);
    if (*plaintext) free(*plaintext);
    log_operation("Decryption failed");
    return -1;
}

// Main function to handle command line options
int main(int argc, char *argv[]) {
    // Initialize OpenSSL and memory pool
    OpenSSL_add_all_algorithms();
    global_memory_pool = create_memory_pool(1024);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <operation> [options]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *operation = argv[1];
    if (strcmp(operation, "encrypt") == 0) {
        // Handle encryption
    } else if (strcmp(operation, "decrypt") == 0) {
        // Handle decryption
    } else if (strcmp(operation, "keygen") == 0) {
        CryptoKey *key = generate_key(32); // Example key size for AES-256
        if (!key) {
            fprintf(stderr, "Failed to generate key\n");
            return EXIT_FAILURE;
        }
        printf("Generated Key: ");
        for (size_t i = 0; i < key->key_len; ++i)
            printf("%02x", key->key[i]);
        printf("\n");
        free_key(key);
    } else {
        fprintf(stderr, "Unknown operation\n");
        return EXIT_FAILURE;
    }

    // Clean up
    EVP_cleanup();
    destroy_memory_pool(global_memory_pool);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Memory Management**: A simple memory pool is implemented for efficient allocation and deallocation.
- **Key Management**: Keys are generated using OpenSSL's `RAND_bytes` function and managed within the memory pool.
