['```c
// record_manager.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void initialize() {
    pthread_mutex_init(&lock, NULL);
}

Record* find_record(int key) {
    pthread_mutex_lock(&lock);

    Node *current = head;
    while (current != NULL) {
        if (current->record->key == key) {
            pthread_mutex_unlock(&lock);
            return current->record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}

void add_record(int key, long offset) {
    pthread_mutex_lock(&lock);

    Record *existing = find_record(key);
    if (existing != NULL) {
        existing->offset = offset;
        existing->timestamp = time(NULL);
    } else {
        Record *new_record = malloc(sizeof(Record));
        new_record->key = key;
        new_record->offset = offset;
        new_record->timestamp = time(NULL);

        Node *new_node = malloc(sizeof(Node));
        new_node->record = new_record;
        new_node->next = head;
        head = new_node;
    }

    pthread_mutex_unlock(&lock);
}

void clear_outdated_records(time_t threshold) {
    pthread_mutex_lock(&lock);

    Node **current = &head;
    while (*current != NULL) {
        if (time(NULL) - (*current)->record->timestamp > threshold) {
            Node *to_delete = *current;
            *current = to_delete->next;
            free(to_delete->record);
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&lock);
}

void cleanup() {
    while (head != NULL) {
        Node *to_free = head;
        head = head->next;
        free(to_free->record);
        free(to_free);
    }
    pthread_mutex_destroy(&lock);
}
```

