// main.c

#include "record_manager.h"

void* periodic_cleanup(void* arg) {
    time_t threshold = *(time_t*)arg;

    while (1) {
        clear_outdated_records(threshold);
        sleep(60);  // Run cleanup every minute
    }

    return NULL;
}

int main() {
    initialize();

    pthread_t thread_id;
    time_t threshold = 3600;  // Example: remove records older than an hour

    pthread_create(&thread_id, NULL, periodic_cleanup, &threshold);

    add_record(1, 100);
    Record *record = find_record(1);
    if (record) {
        printf("Key: %d, Offset: %ld\n", record->key, record->offset);
    }

    // Simulate some operation time
    sleep(65);  

    cleanup();
    pthread_cancel(thread_id);
    return 0;
}
