import pthread.h
import time.h
import sqlite3

#define MAX_ENTRIES 1000
#define CHECK_INTERVAL 60 // seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to simulate CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDIGATION_PDU_T *entries;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_Collection;

NFAPI_Collection nfaCollection = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void randomizeCRCFLAG(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

int addEntry(NFAPI_Collection *collection, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= MAX_ENTRIES) return -1;

    collection->entries = realloc(collection->entries, (collection->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->entries) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    entry.CRCFLAG = rand() % 2; // Set CRCFLAG randomly
    collection->entries[collection->count++] = entry;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void serializeToFile(const char *filename, NFAPI_Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&collection->lock);
        perror("File open failed");
        return;
    }

    fwrite(collection->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T), collection->count, file);
    fclose(file);

    pthread_mutex_unlock(&collection->lock);
}

void serializeToDatabase(sqlite3 *db, const char *table_name, NFAPI_Collection *collection) {
    pthread_mutex_lock(&collection->lock);

    sqlite3_stmt *stmt;
    const char *sql = "INSERT INTO crc_table (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (?, ?, ?, ?)";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        pthread_mutex_unlock(&collection->lock);
        perror("SQLite prepare failed");
        return;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        sqlite3_bind_int(stmt, 1, collection->entries[i].RX_UE_INFORMATION_TAG);
        sqlite3_bind_int(stmt, 2, collection->entries[i].RNTI);
        sqlite3_bind_int(stmt, 3, collection->entries[i].CRC_INDICATION_REL8_TAG);
        sqlite3_bind_int(stmt, 4, collection->entries[i].CRCFLAG);

        if (sqlite3_step(stmt) != SQLITE_DONE) {
            perror("SQLite step failed");
        }
        sqlite3_reset(stmt);
    }

    sqlite3_finalize(stmt);
    pthread_mutex_unlock(&collection->lock);
}

void *integrityCheck(void *arg) {
    while (1) {
        time_t next_check = time(NULL) + CHECK_INTERVAL;

        // Simulate integrity check
        pthread_mutex_lock(&nfaCollection.lock);
        for (size_t i = 0; i < nfaCollection.count; ++i) {
            // Perform checks here, e.g., CRCFLAG validation
        }
        pthread_mutex_unlock(&nfaCollection.lock);

        // Serialize again if needed
        serializeToFile("crc_data.bin", &nfaCollection);
        serializeToDatabase(NULL, "crc_table", &nfaCollection); // Replace NULL with your db connection

        while (time(NULL) < next_check);
    }
}

void startBackgroundIntegrityCheck() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, integrityCheck, NULL)) {
        perror("Thread creation failed");
        exit(EXIT_FAILURE);
    }
}

int main() {
    srand(time(NULL));

    nfaCollection.entries = malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaCollection.entries) {
        perror("Memory allocation failed");
        return EXIT_FAILURE;
    }

    // Example usage
