['Below is a modular C program that provides encryption, decryption, and key generation functionalities using the OpenSSL library. It includes file I/O operations, optional dependency management, logging, and extensibility considerations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <getopt.h>

#define KEY_SIZE 32 // AES-256 key size

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

// Error handling function
void handle_error(const char *error_message) {
    perror(error_message);
    exit(EXIT_FAILURE);
}

// Generate a random key and IV
int generate_key_iv(unsigned char **key, unsigned char **iv) {
    if (!RAND_bytes(*key = malloc(KEY_SIZE), KEY_SIZE)) {
        return 0;
    }
    if (!RAND_bytes(*iv = malloc(EVP_MAX_IV_LENGTH), EVP_MAX_IV_LENGTH)) {
        free(*key);
        return 0;
    }
    return 1;
}

// Encrypt or decrypt file
int process_file(const char *input_path, const char *output_path, 
                 unsigned char *key, unsigned char *iv, int encrypt) {
    FILE *fin = fopen(input_path, "rb");
    if (!fin) handle_error("Error opening input file");

    FILE *fout = fopen(output_path, "wb");
    if (!fout) {
        fclose(fin);
        handle_error("Error opening output file");
    }

    unsigned char buffer[1024];
    int len;
    EVP_CIPHER_CTX *ctx;

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) handle_error("EVP_CIPHER_CTX_new failed");

    if (encrypt) {
        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            handle_error("EVP_EncryptInit_ex failed");
        }
    } else {
        if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            handle_error("EVP_DecryptInit_ex failed");
        }
    }

    while ((len = fread(buffer, 1, sizeof(buffer), fin)) > 0) {
        unsigned char outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
        int outlen;

        if (encrypt) {
            if (!EVP_EncryptUpdate(ctx, outbuf, &outlen, buffer, len)) {
                handle_error("EVP_EncryptUpdate failed");
            }
        } else {
            if (!EVP_DecryptUpdate(ctx, outbuf, &outlen, buffer, len)) {
                handle_error("EVP_DecryptUpdate failed");
            }
        }

        fwrite(outbuf, 1, outlen, fout);
    }

    unsigned char outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    int final_len;

    if (encrypt) {
        if (!EVP_EncryptFinal_ex(ctx, outbuf, &final_len)) {
            handle_error("EVP_EncryptFinal_ex failed");
        }
    } else {
        if (!EVP_DecryptFinal_ex(ctx, outbuf, &final_len)) {
            handle_error("EVP_DecryptFinal_ex failed");
        }
    }

    fwrite(outbuf, 1, final_len, fout);

    fclose(fin);
    fclose(fout);
    EVP_CIPHER_CTX_free(ctx);
    return 1;
}

// Handle command-line options
void parse_options(int argc, char *argv[], int *mode, char **input_path, 
                   char **output_path) {
    static struct option long_options[] = {
        {"encrypt", no_argument, NULL, 'e'},
        {"decrypt", no_argument, NULL, 'd'},
        {"keygen", no_argument, NULL, 'k'},
        {"input", required_argument, NULL, 'i'},
        {"output", required_argument, NULL, 'o'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "edki:o:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'e':
                *mode = 1; // Encrypt
                break;
            case 'd':
                *mode = 2; // Decrypt
                break;
            case 'k':
                *mode = 3; // Key generation
                break;
            case 'i':
                *input_path = optarg;
                break;
            case 'o':
                *output_path = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s --encrypt|--decrypt|--keygen --input <file> --output <file>\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    int mode = 0;
    char *input_path = NULL;
    char *output_path = NULL;

    parse_options(argc, argv, &mode, &input_path, &output_path);

    if (mode == 3) { // Key generation
        unsigned char *key, *iv;
        log_message("Generating key and IV...");
        if (!generate_key_iv(&key, &iv)) {
            handle_error("Key or IV generation failed");
        }
        fwrite(key, 1, KEY_SIZE, stdout);
        fwrite(iv, 1, EVP_MAX_IV_LENGTH, stdout);
        free(key);
        free(iv);
    } else if (mode == 1 || mode == 2) { // Encryption/Decryption
        if (!input_path || !output_path) {
            fprintf(stderr, "Input and output paths are required for encryption/decryption\n");
            exit(EXIT_FAILURE);
        }

        unsigned char key[KEY_SIZE];
        unsigned char iv[EVP_MAX_IV_LENGTH];

        // In a real application, you would securely provide the key and IV
        log_message("Using hardcoded key and IV for demonstration purposes.");
        memset(key, 0x00, KEY_SIZE); // Replace with actual key retrieval logic
        memset(iv, 0x00, EVP_MAX_IV_LENGTH); // Replace with actual IV retrieval logic

        if (mode == 1) {
            log_message("Encrypting file...");
            process_file(input_path, output_path, key, iv, 1);
            log_message("Encryption complete.");
        } else {
            log_message("Decrypting file...");
            process_file(input_path, output_path, key, iv, 0);
            log_message("Decryption complete.");
        }
    } else {
        fprintf(stderr, "Mode not specified. Use --encrypt, --decrypt, or --keygen.\n");
        exit(EXIT_FAILURE);
    }

    return 0;
}
```

### Key Points:
- **Modular Design**: Functions are separated for key generation, encryption/decryption, and command-line parsing.
