#define MAX_ENTRIES 10000

typedef struct {
    float amount;
} transaction;

typedef struct CUSTOMER_TRANSACTION {
    int transaction_id;
    char transaction_tag[10];
    float amount;
    int status_flag; // Randomly set status flag
    struct CUSTOMER_TRANSACTION *prev, *next;
} CUSTOMER_TRANSACTION;

double calculate_mean(double *arr, size_t n) {
    double sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        sum += arr[i];
    }
    return sum / n;
}

double calculate_std_deviation(double *arr, size_t n, double mean) {
    double variance = 0.0;
    for (size_t i = 0; i < n; ++i) {
        variance += pow(arr[i] - mean, 2);
    }
    return sqrt(variance / n);
}

void print_statistics(double *arr, size_t n) {
    double mean = calculate_mean(arr, n);
    double std_deviation = calculate_std_deviation(arr, n, mean);
    printf("Mean: %lf\n", mean);
    printf("Standard Deviation: %lf\n", std_deviation);
}

void process_inputs(double *float_numbers, char keys[MAX_ENTRIES], transaction *trans_array) {
    CUSTOMER_TRANSACTION *head = NULL;
    CUSTOMER_TRANSACTION *tail = NULL;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        float min_val = 10.0f, max_val = 100.0f;
        trans_array[i].amount = ((float)rand() / RAND_MAX) * (max_val - min_val) + min_val;

        CUSTOMER_TRANSACTION *new_node = malloc(sizeof(CUSTOMER_TRANSACTION));
        if (!new_node) {
            perror("Failed to allocate memory for CUSTOMER_TRANSACTION");
            exit(EXIT_FAILURE);
        }

        new_node->transaction_id = i;
        snprintf(new_node->transaction_tag, sizeof(new_node->transaction_tag), "TAG%04d", rand() % 10000);
        new_node->amount = trans_array[i].amount;
        new_node->status_flag = rand() % 2; // Randomly set to 0 or 1

        new_node->prev = tail;
        new_node->next = NULL;

        if (tail) {
            tail->next = new_node;
        } else {
            head = new_node;
        }

        tail = new_node;
    }

    print_statistics(float_numbers, MAX_ENTRIES);

    // Freeing the doubly linked list
    CUSTOMER_TRANSACTION *current = head;
    while (current) {
        CUSTOMER_TRANSACTION *next = current->next;
        free(current);
        current = next;
    }
}

void manage_memory_and_initialize() {
    double *float_numbers = malloc(MAX_ENTRIES * sizeof(double));
    if (!float_numbers) {
        perror("Failed to allocate memory for float numbers");
        exit(EXIT_FAILURE);
    }

    char keys[MAX_ENTRIES][10];
    transaction trans_array[MAX_ENTRIES];

    size_t count = 0;
    while (count < MAX_ENTRIES && scanf("%lf", &float_numbers[count]) == 1) {
        snprintf(keys[count], sizeof(keys[0]), "KEY%04d", count);
        ++count;
    }

    process_inputs(float_numbers, keys, trans_array);

    free(float_numbers);
}
