```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define LOG(msg, ...) fprintf(stderr, msg "\n", ##__VA_ARGS__)

typedef struct {
    int value;
    void *key;
    size_t offset;
} Record;

typedef struct {
    Record *records;
    size_t num_records;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(size_t num_records) {
    if (num_records == 0) return NULL;

    Dataset *dataset = malloc(sizeof(Dataset));
    if (!dataset) {
        LOG("Memory allocation failed for dataset");
        return NULL;
    }

    dataset->records = calloc(num_records, sizeof(Record));
    if (!dataset->records) {
        free(dataset);
        LOG("Memory allocation failed for records array");
        return NULL;
    }

    dataset->num_records = num_records;
    pthread_mutex_init(&dataset->lock, NULL);

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        int value = rand() % 100 + 1; // Random integer between 1 and 100
        void *key = malloc(sizeof(int));
        if (!key) {
            LOG("Memory allocation failed for key");
            return NULL;
        }
        *(int *)key = (int)i;

        dataset->records[i].value = value;
        dataset->records[i].key = key;
        dataset->records[i].offset = i * sizeof(Record); // Example offset
    }

    LOG("Dataset created successfully with %zu records", num_records);
    return dataset;
}

void free_dataset(Dataset *dataset) {
    if (!dataset) return;

    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->num_records; ++i) {
        free(dataset->records[i].key);
    }

    free(dataset->records);
    pthread_mutex_unlock(&dataset->lock);
    pthread_mutex_destroy(&dataset->lock);

    free(dataset);
    LOG("Dataset freed successfully");
}

int main() {
    size_t num_records = 1000; // Configurable dataset size
    Dataset *dataset = create_dataset(num_records);

    if (dataset) {
        // Example usage of the dataset
        for (size_t i = 0; i < dataset->num_records; ++i) {
            LOG("Record %zu: value=%d, key=%p, offset=%zu", 
                i, dataset->records[i].value, dataset->records[i].key, dataset->records[i].offset);
        }

        free_dataset(dataset);
    }

    return 0;
}
```

### Key Features:

1. **Thread Safety**: Uses `pthread_mutex_t` to ensure concurrent access is managed without race conditions.
2. **Memory Management**: Allocates memory for records and keys, with checks to handle allocation failures gracefully.
3. **Logging**: Provides logging capabilities via a simple macro for debugging and monitoring purposes.
4. **Random Number Generation**: Populates the record values with random integers in a specified range.
5. **Error Handling**: Incorporates error handling for null pointers and memory exhaustion scenarios.

### Considerations:
- Ensure that `rand()` is suitable for your use case; consider using more sophisticated random number generators if needed.
- Adjust logging as per requirements (e.g., using a dedicated logging library).
- Test under concurrent access conditions to ensure thread safety in multi-threaded environments.']

