['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

// Define constants for supported algorithms and modes
typedef enum { AES_128, AES_256, CHACHA20, XCHACHA20 } Algorithm;
typedef enum { GCM, CTR } Mode;

// Structure to hold encryption parameters
typedef struct {
    Algorithm algorithm;
    Mode mode;
    unsigned char *key;
    size_t key_len;
    unsigned char *nonce; // For stream modes
    size_t nonce_len;
    EVP_CIPHER_CTX *ctx;
} EncryptionParams;

// Function prototypes
int derive_key(const char *password, int iterations, const Algorithm algo, 
               unsigned char **derived_key, size_t *key_len);
int initialize_encryption(EncryptionParams *params);
int encrypt(const EncryptionParams *params, const unsigned char *plaintext, 
            size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len);
int decrypt(const EncryptionParams *params, const unsigned char *ciphertext, 
            size_t ciphertext_len, unsigned char **plaintext);

// Key derivation function using PBKDF2
int derive_key(const char *password, int iterations, const Algorithm algo, 
               unsigned char **derived_key, size_t *key_len) {
    const EVP_MD *md = NULL;
    switch (algo) {
        case AES_128: md = EVP_sha256(); break;
        case AES_256: md = EVP_sha512(); break;
        case CHACHA20:
        case XCHACHA20: md = EVP_blake2b512(); break;
    }

    if (!md) return 0;

    *key_len = (algo == AES_128) ? 16 : (algo == AES_256) ? 32 : 32; // Default to 32 for ChaCha
    *derived_key = malloc(*key_len);
    if (*derived_key == NULL) return 0;

    PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, md,
                      *key_len, *derived_key);

    return 1;
}

// Initialize encryption context
int initialize_encryption(EncryptionParams *params) {
    const EVP_CIPHER *cipher = NULL;
    switch (params->algorithm) {
        case AES_128: cipher = EVP_aes_128_gcm(); break;
        case AES_256: cipher = EVP_aes_256_gcm(); break;
        case CHACHA20: cipher = EVP_chacha20(); break;
        case XCHACHA20: cipher = EVP_xchacha20_poly1305(); break;
    }

    if (!cipher) return 0;

    params->ctx = EVP_CIPHER_CTX_new();
    if (!params->ctx) return 0;

    int mode_flag = (params->mode == GCM) ? EVP_CIPH_GCM_MODE : 0;
    int ret = EVP_EncryptInit_ex(params->ctx, cipher, NULL, params->key, params->nonce);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(params->ctx);
        return 0;
    }

    if (params->mode == GCM) {
        EVP_CIPHER_CTX_ctrl(params->ctx, EVP_CTRL_GCM_SET_IVLEN, params->nonce_len, NULL);
    } else if (params->mode == CTR) {
        EVP_CIPHER_CTX_ctrl(params->ctx, EVP_CTRL_CRYPTINIT_MODE, 1, NULL); // Enable counter mode
    }

    return 1;
}

// Encrypt data
int encrypt(const EncryptionParams *params, const unsigned char *plaintext, 
            size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len) {
    int len;
    *ciphertext = malloc(plaintext_len + EVP_CIPHER_CTX_block_size(params->ctx));
    if (*ciphertext == NULL) return 0;

    int ret = EVP_EncryptUpdate(params->ctx, *ciphertext, &len, plaintext, plaintext_len);
    if (ret != 1) return 0;

    *ciphertext_len = len;
    ret = EVP_EncryptFinal_ex(params->ctx, *ciphertext + len, &len);
    if (ret == 1) (*ciphertext_len) += len;

    return (ret == 1) ? 1 : 0;
}

// Decrypt data
int decrypt(const EncryptionParams *params, const unsigned char *ciphertext, 
            size_t ciphertext_len, unsigned char **plaintext) {
    int len;
    *plaintext = malloc(ciphertext_len);
    if (*plaintext == NULL) return 0;

    int ret = EVP_DecryptUpdate(params->ctx, *plaintext, &len, ciphertext, ciphertext_len);
    if (ret != 1) return 0;

    int plaintext_len = len;
    ret = EVP_DecryptFinal_ex(params->ctx, *plaintext + len, &len);
    if (ret == 1) plaintext_len += len;

    if (ret != 1) {
        free(*plaintext);
        return 0;
    }

    return 1;
}

// Example usage
int main() {
    const char *password = "secure_password";
    EncryptionParams params;
    unsigned char *key, *nonce;
    size_t key_len;

    // Derive a key
    if (!derive_key(password, 10000, AES_256, &key, &key_len)) {
        fprintf(stderr, "Key derivation failed\n");
        return 1;
    }

    // Generate a nonce
    if (RAND_bytes(nonce, 12) != 1) { // Example nonce size for GCM/CTR
        fprintf(stderr, "Nonce generation failed\n");
        free(key);
        return 1;
    }

    params.algorithm = AES_256;
    params.mode = GCM;
    params.key = key;
    params.key_len = key_len;
    params.nonce = nonce;
    params.nonce_len = 12;

    if (!initialize_encryption(&params)) {
        fprintf(stderr, "Encryption initialization failed\n");
        free(key);
        free(nonce);
        return 1;
    }

    const unsigned char *plaintext = (unsigned char *)"This is a secret message.";
    size_t plaintext_len = strlen((char *)plaintext);

    unsigned char *ciphertext;
    size_t ciphertext_len;

    if (!encrypt(&params, plaintext, plaintext_len, &ciphertext, &ciphertext_len)) {
        fprintf(stderr, "Encryption failed\n");
        free(key);
        free(nonce);
        EVP_CIPHER_CTX_free(params.ctx);
        return 1;
    }

    unsigned char *decrypted_text;
    if (!decrypt(&params, ciphertext, ciphertext_len, &decrypted_text)) {
        fprintf(stderr, "Decryption failed\n");
        free(ciphertext);
        free(key);
        free(nonce);
        EVP_CIPHER_CTX_free(params.ctx);
        return 1;
    }

    printf("Decrypted text: %s\n", decrypted_text);

    // Clean up
    free(ciphertext);
    free(decrypted_text);
    free(key);
    free(nonce);
    EVP_CIPHER_CTX_free(params.ctx);

    return 0;
}
