['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <ctype.h>

#define MAX_PAYLOAD_SIZE 1024

// Structure for request context
typedef struct {
    char id[MAX_PAYLOAD_SIZE];
    char method[10]; // "PUT" or "DELETE"
    char body[MAX_PAYLOAD_SIZE];
    int status_code;
} RequestContext;

// Global variables for caching and logging
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned char cache_data[MAX_PAYLOAD_SIZE];
static size_t cache_size = 0;

void log_message(const char *message) {
    printf("%s\n", message);
}

int handle_request(RequestContext *ctx, const char *operation) {
    if (strcmp(ctx->method, "PUT") != 0 && strcmp(ctx->method, "DELETE") != 0) {
        ctx->status_code = 405; // Method Not Allowed
        log_message("Invalid HTTP method.");
        return -1;
    }

    pthread_mutex_lock(&cache_lock);
    if (operation == NULL || strlen(operation) != 3 || strncasecmp(operation, "AES", 3)) {
        pthread_mutex_unlock(&cache_lock);
        ctx->status_code = 400; // Bad Request
        log_message("Invalid operation specified.");
        return -1;
    }

    EVP_CIPHER_CTX *ctx_cipher = EVP_CIPHER_CTX_new();
    if (!ctx_cipher) {
        pthread_mutex_unlock(&cache_lock);
        ctx->status_code = 500; // Internal Server Error
        log_message("Failed to create cipher context.");
        return -1;
    }

    unsigned char key[32], iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, EVP_CIPHER_iv_length(EVP_aes_256_cbc()));

    if (strcmp(ctx->method, "PUT") == 0) {
        int len;
        int ciphertext_len;

        // Encrypt the request body
        if (!EVP_EncryptInit_ex(ctx_cipher, EVP_aes_256_cbc(), NULL, key, iv)) {
            log_message("Encryption initialization failed.");
            ctx->status_code = 500;
            goto cleanup;
        }

        unsigned char ciphertext[MAX_PAYLOAD_SIZE];
        if (!EVP_EncryptUpdate(ctx_cipher, ciphertext, &len, (unsigned char *)ctx->body, strlen(ctx->body))) {
            log_message("Encryption update failed.");
            ctx->status_code = 500;
            goto cleanup;
        }
        ciphertext_len = len;

        if (!EVP_EncryptFinal_ex(ctx_cipher, ciphertext + len, &len)) {
            log_message("Encryption finalization failed.");
            ctx->status_code = 500;
            goto cleanup;
        }
        ciphertext_len += len;

        // Cache the encrypted data
        memcpy(cache_data, iv, sizeof(iv));
        memcpy(cache_data + EVP_CIPHER_iv_length(EVP_aes_256_cbc()), ciphertext, ciphertext_len);
        cache_size = EVP_CIPHER_iv_length(EVP_aes_256_cbc()) + ciphertext_len;
    } else if (strcmp(ctx->method, "DELETE") == 0) {
        // Invalidate the cached data
        memset(cache_data, 0, sizeof(cache_data));
        cache_size = 0;

        ctx->status_code = 204; // No Content
    }

cleanup:
    EVP_CIPHER_CTX_free(ctx_cipher);
    pthread_mutex_unlock(&cache_lock);
    log_message("Request processed successfully.");
    return 0;
}
```']

