// Define the structure for a packet header.
typedef struct {
    uint32_t packetID;
    char sourceAddress[16];
    char destinationAddress[16];
} PacketHeader;

// Define the buffer structure.
typedef struct {
    void* data;
    size_t payloadSize;
} Buffer;

#define MAX_PACKETS 1024
#define INITIAL_PAYLOAD_SIZE 512

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t payloadSize = INITIAL_PAYLOAD_SIZE;
PacketHeader packetHeaders[MAX_PACKETS];
Buffer* buffers = NULL;
int numBuffers = 0;

// Function to allocate and initialize buffers.
void* allocateAndInitializeBuffers(size_t bufferCount) {
    pthread_mutex_lock(&lock);

    // Allocate memory for packet headers
    for (int i = 0; i < MAX_PACKETS; ++i) {
        packetHeaders[i].packetID = i;
        snprintf(packetHeaders[i].sourceAddress, sizeof(packetHeaders[i].sourceAddress), "Src%d", i);
        snprintf(packetHeaders[i].destinationAddress, sizeof(packetHeaders[i].destinationAddress), "Dst%d", i);
    }

    // Allocate and initialize buffers
    buffers = malloc(bufferCount * sizeof(Buffer));
    if (!buffers) {
        fprintf(stderr, "Failed to allocate memory for buffers\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    numBuffers = bufferCount;
    for (int i = 0; i < bufferCount; ++i) {
        // Allocate aligned memory for each buffer
        buffers[i].data = aligned_alloc(alignof(max_align_t), payloadSize);
        if (!buffers[i].data) {
            fprintf(stderr, "Failed to allocate aligned memory for buffer %d\n", i);
            for (int j = 0; j < i; ++j) {
                free(buffers[j].data); // Clean up previously allocated buffers
            }
            free(buffers);
            buffers = NULL;
            numBuffers = 0;
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        buffers[i].payloadSize = payloadSize;
    }

    pthread_mutex_unlock(&lock);

    return buffers;
}

// Function to modify the payload size dynamically.
void adjustPayloadSize(size_t newSize) {
    pthread_mutex_lock(&lock);
    if (newSize != payloadSize) {
        for (int i = 0; i < numBuffers; ++i) {
            free(buffers[i].data); // Free old buffer data
            buffers[i].data = aligned_alloc(alignof(max_align_t), newSize); // Allocate new buffer size
            if (!buffers[i].data) {
                fprintf(stderr, "Failed to reallocate memory for buffer %d\n", i);
                for (int j = 0; j < i; ++j) {
                    free(buffers[j].data); // Clean up previously allocated buffers
                }
                free(buffers);
                buffers = NULL;
                numBuffers = 0;
            } else {
                buffers[i].payloadSize = newSize;
            }
        }
        payloadSize = newSize;
    }
    pthread_mutex_unlock(&lock);
}

// Function to free the allocated resources.
void freeResources() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numBuffers; ++i) {
        if (buffers[i].data) {
            free(buffers[i].data);
        }
    }

    if (buffers) {
        free(buffers);
    }

    pthread_mutex_unlock(&lock);
}

// Main function to handle command-line arguments and demonstrate usage.
int main(int argc, char* argv[]) {
    int option;
    char* output_file = NULL;

    while ((option = getopt(argc, argv, "m:cs:o:")) != -1) {
        switch (option) {
            case 'm':
                // Handle manpage printing if needed
                break;
            case 'c':
                // Handle specific command-line functionality for -c
                break;
            case 's':
                // Handle source file reading if provided
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-m] [-cs] [-o output_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    size_t bufferCount = 10; // Example buffer count
    allocateAndInitializeBuffers(bufferCount);

    if (output_file) {
        FILE* file = fopen(output_file, "w");
        if (!file) {
            perror("Error opening output file");
            freeResources();
            return EXIT_FAILURE;
        }

        fprintf(file, "Allocated %d buffers with payload size of %zu bytes\n", bufferCount, payloadSize);
        fclose(file);
    } else {
        printf("No input file provided. Usage information printed.\n");
    }

    // Example: Adjusting the payload size
    adjustPayloadSize(1024);

    freeResources();
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
