#define DEFAULT_LOG_LIMIT 100

typedef enum {
    INFO,
    ERROR,
} LogLevel;

typedef struct LogEntry {
    LogLevel level;
    char message[256];
    struct LogEntry* next;
} LogEntry;

typedef struct LoggingFramework {
    pthread_mutex_t lock;
    LogEntry* head;
    int count;
    int log_limit;
} LoggingFramework;

LoggingFramework* create_logging_framework(int log_limit) {
    LoggingFramework* lf = (LoggingFramework*)malloc(sizeof(LoggingFramework));
    lf->log_limit = log_limit ? log_limit : DEFAULT_LOG_LIMIT;
    lf->count = 0;
    lf->head = NULL;
    pthread_mutex_init(&lf->lock, NULL);
    return lf;
}

void destroy_logging_framework(LoggingFramework* lf) {
    LogEntry* current = lf->head;
    while (current) {
        LogEntry* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&lf->lock);
    free(lf);
}

int is_network_available() { 
    // Dummy function for network availability check
    return 1; 
}

void log_message(LoggingFramework* lf, LogLevel level, const char *format, ...) {
    if (!lf) return;

    pthread_mutex_lock(&lf->lock);

    if (lf->count >= lf->log_limit) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        snprintf(entry->message, sizeof(entry->message), "Log limit exceeded");
        entry->level = level;
        entry->next = NULL;

        // Prepend to the list
        entry->next = lf->head;
        lf->head = entry;
    } else {
        if (!is_network_available()) {
            printf("Network unavailable, logging locally\n");
        }

        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        va_list args;
        va_start(args, format);
        vsnprintf(entry->message, sizeof(entry->message), format, args);
        va_end(args);

        entry->level = level;
        entry->next = lf->head;
        lf->head = entry;

        lf->count++;
    }

    pthread_mutex_unlock(&lf->lock);
}

void extend_logging_framework(LoggingFramework* lf) {
    // Placeholder for future extensibility
}

// Unit tests (basic example)
void test_logging() {
    LoggingFramework* lf = create_logging_framework(5);

    log_message(lf, INFO, "Test message %d", 1);
    log_message(lf, ERROR, "Error occurred");

    for (int i = 0; i < 6; ++i) {
        log_message(lf, INFO, "Log entry number: %d", i + 1);
    }

    LogEntry* current = lf->head;
    while (current != NULL) {
        printf("[%s] %s\n", current->level == INFO ? "INFO" : "ERROR", current->message);
        current = current->next;
    }

    destroy_logging_framework(lf);
}

int main() {
    test_logging();
    return 0;
}
```

This code sets up a basic modular logging framework in C that supports both informational and error-level logs. It ensures thread safety using `pthread_mutex_t` for mutual exclusion, manages memory efficiently by dynamically allocating entries, and handles variable-length messages with the use of `vsnprintf`. The log limit is enforced by appending a "Log limit exceeded" message when reached without incrementing the count. The example includes a basic unit test function to simulate logging operations under stress conditions.']

