#include <forward_list>
#include <string>

std::forward_list<std::string> insertOrAppendAfter(std::forward_list<std::string>& list,
                                                   const std::string& firstString,
                                                   const std::string& secondString,
                                                   bool dryRun) {
    if (dryRun) {
        auto tempList = list;
        for (auto it = tempList.begin(); it != tempList.end(); ++it) {
            if (*it == firstString) {
                tempList.insert_after(it, secondString);
                return tempList;
            }
        }
        tempList.push_front(secondString);
        return tempList;
    } else {
        for (auto it = list.begin(); it != list.end(); ++it) {
            if (*it == firstString) {
                list.insert_after(it, secondString);
                return;  // Exit after the first insertion
            }
        }
        list.push_front(secondString);  // Append at the front to optimize for forward_list's nature
    }
}
