#include <random>
#include <nlohmann/json.hpp> // JSON library for configuration
#include <spdlog/spdlog.h>   // Logging library

// Use namespace to modularize the code structure.
namespace SimulationFramework {

    class RandomNumberGenerator {
    private:
        static std::mt19937 mt_engine;
        int seed;

        void initializeEngine(int s) {
            if (s <= 0)
                throw std::invalid_argument("Seed must be a positive integer.");
            seed = s;
            mt_engine.seed(seed);
        }

    public:
        RandomNumberGenerator() : seed(1) {
            spdlog::info("Creating RandomNumberGenerator with default seed.");
            initializeEngine(seed);
        }

        explicit RandomNumberGenerator(int s) {
            spdlog::info("Creating RandomNumberGenerator with custom seed: {}", s);
            initializeEngine(s);
        }

        ~RandomNumberGenerator() {
            spdlog::info("Destroying RandomNumberGenerator.");
            // Destructor primarily logs the destruction; no dynamic resources are used.
        }

        double generateUniform(double min = 0.0, double max = 1.0) {
            std::uniform_real_distribution<> dis(min, max);
            return dis(mt_engine);
        }

        double generateNormal(double mean = 0.0, double stddev = 1.0) {
            std::normal_distribution<> dis(mean, stddev);
            return dis(mt_engine);
        }
    };

    // Initialize static member variable.
    std::mt19937 RandomNumberGenerator::mt_engine;

    class Configuration {
    private:
        nlohmann::json config_data;

    public:
        void loadConfiguration(const std::string& file_path) {
            std::ifstream i(file_path);
            if (!i.is_open()) {
                throw std::runtime_error("Failed to open configuration file.");
            }
            i >> config_data;
        }

        int getSeed() const {
            return config_data.value("seed", 1); // Default seed is 1
        }

        double getMinUniform() const {
            return config_data.value("uniform.min", 0.0);
        }

        double getMaxUniform() const {
            return config_data.value("uniform.max", 1.0);
        }
    };

} // namespace SimulationFramework

int main(int argc, char* argv[]) {
    try {
        spdlog::set_level(spdlog::level::info); // Set log level
        std::string config_file = "config.json";

        if (argc > 1) {
            config_file = argv[1];
        }

        SimulationFramework::Configuration config;
        config.loadConfiguration(config_file);

        int seed = config.getSeed();
        double min_uniform = config.getMinUniform();
        double max_uniform = config.getMaxUniform();

        SimulationFramework::RandomNumberGenerator rng(seed);

        spdlog::info("Generating random numbers...");
        for (int i = 0; i < 5; ++i) {
            std::cout << "Uniform: " << rng.generateUniform(min_uniform, max_uniform) << '\n';
            std::cout << "Normal : " << rng.generateNormal() << '\n';
        }
    } catch (const std::exception& e) {
        spdlog::error("Exception caught: {}", e.what());
        return 1;
    }

    return 0;
}
