using System;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;

[ApiController]
[Route("api/[controller]")]
public class ResourceController : ControllerBase
{
    private readonly string _connectionString;

    public ResourceController(string connectionString)
    {
        _connectionString = connectionString;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(int id, [FromBody] JsonElement requestBody)
    {
        try
        {
            var parameters = ExtractParameters(requestBody);
            if (!parameters.Any())
                return BadRequest("No valid data provided.");

            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                var resourceExists = await CheckResourceExists(connection, id);
                if (!resourceExists)
                    return NotFound($"Resource with ID {id} not found.");

                var query = BuildUpdateQuery(parameters);
                var cmd = new SqlCommand(query, connection);

                AddParameters(cmd, parameters, id);

                int rowsAffected = await cmd.ExecuteNonQueryAsync();
                if (rowsAffected == 0)
                    return BadRequest("No changes made to the resource.");

                return Ok(await GetUpdatedResource(connection, id));
            }
        }
        catch (SqlException ex) when (ex.Number == -2 || ex.Number == 53)
        {
            // Handle timeout or connection failure
            return StatusCode(500, "Database connection error.");
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(int id)
    {
        try
        {
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();

                var resourceExists = await CheckResourceExists(connection, id);
                if (!resourceExists)
                    return NotFound($"Resource with ID {id} not found.");

                var query = "DELETE FROM Resources WHERE Id = @Id;"; // Adjust as necessary for cascading/deletion logic
                var cmd = new SqlCommand(query, connection);

                AddParameter(cmd, "@Id", id);

                int rowsAffected = await cmd.ExecuteNonQueryAsync();
                if (rowsAffected == 0)
                    return BadRequest("No resource was deleted.");

                LogDeletion(id);
                return Ok($"Resource with ID {id} successfully deleted.");
            }
        }
        catch (SqlException ex) when (ex.Number == -2 || ex.Number == 53)
        {
            // Handle timeout or connection failure
            return StatusCode(500, "Database connection error.");
        }
        catch (Exception ex)
        {
            return StatusCode(500, $"Internal server error: {ex.Message}");
        }
    }

    private Dictionary<string, object> ExtractParameters(JsonElement requestBody)
    {
        var parameters = new Dictionary<string, object>();

        foreach (var property in requestBody.EnumerateObject())
        {
            if (property.Value.ValueKind != JsonValueKind.Undefined)
                parameters[property.Name] = property.Value.ToObject<object>();
        }

        return parameters;
    }

    private string BuildUpdateQuery(Dictionary<string, object> parameters)
    {
        var setClauses = parameters.Select(kv => $"{kv.Key} = @{kv.Key}");
        return $"UPDATE Resources SET {string.Join(", ", setClauses)} WHERE Id = @Id;";
    }

    private void AddParameters(SqlCommand cmd, Dictionary<string, object> parameters, int id)
    {
        foreach (var param in parameters)
            AddParameter(cmd, $"@{param.Key}", param.Value);

        AddParameter(cmd, "@Id", id);
    }

    private async Task<bool> CheckResourceExists(SqlConnection connection, int id)
    {
        var query = "SELECT COUNT(1) FROM Resources WHERE Id = @Id;";
        using (var cmd = new SqlCommand(query, connection))
            AddParameter(cmd, "@Id", id);

        return (int)(await cmd.ExecuteScalarAsync()) > 0;
    }

    private async Task<object> GetUpdatedResource(SqlConnection connection, int id)
    {
        var query = "SELECT * FROM Resources WHERE Id = @Id;";
        using (var cmd = new SqlCommand(query, connection))
            AddParameter(cmd, "@Id", id);

        using (var reader = await cmd.ExecuteReaderAsync())
        {
            if (await reader.ReadAsync())
                return JsonReaderToDictionary(reader);
        }

        return null;
    }

    private void LogDeletion(int resourceId)
    {
        // Implement logging logic here
    }

    private void AddParameter(SqlCommand cmd, string name, object value)
    {
        var parameter = new SqlParameter(name, value ?? DBNull.Value) { SqlDbType = GetSqlDbType(value) };
        cmd.Parameters.Add(parameter);
    }

    private static System.Data.SqlDbType? GetSqlDbType(object value)
    {
        if (value == null) return null;

        switch (value)
        {
            case int _:
            case long _:
                return System.Data.SqlDbType.Int;
            case string s:
                return s.Length > 4000 ? System.Data.SqlDbType.NVarChar : System.Data.SqlDbType.NVarChar(4000);
            case bool b:
                return System.Data.SqlDbType.Bit;
            // Add more type mappings as needed
            default:
                return null;
        }
    }

    private Dictionary<string, object> JsonReaderToDictionary(SqlDataReader reader)
    {
        var dict = new Dictionary<string, object>();
        for (int i = 0; i < reader.FieldCount; i++)
        {
            dict[reader.GetName(i)] = reader.GetValue(i);
        }
        return dict;
    }
}
```

This C# code provides methods to update and delete resources in a web API using SQL Server. It handles optional fields, input validation, error handling, and ensures idempotency for the HTTP PUT and DELETE operations. Logging is stubbed out for deletions for auditability.']

