This example covers essential aspects of loading configurations dynamically, processing cryptographic operations asynchronously, ensuring thread safety, logging events, and handling errors efficiently.']

['Below is a code implementation for an example web API in Python using Flask that fulfills the described tasks, including resource update with optimistic concurrency control and soft deletion:

```python
from flask import Flask, request, jsonify
from datetime import datetime
import threading
from functools import wraps

app = Flask(__name__)

# Mock database
resources_db = {}
soft_deleted_resources = {}

# External logging mock function
def log_operation(operation_type, resource_id, user_id):
    print(f"Log: {operation_type} on resource {resource_id} by user {user_id}")

# Caching decorator
def cache_response(func):
    cache = {}

    @wraps(func)
    def wrapper(*args, **kwargs):
        key = f"{func.__name__}_{args[0]}"
        if key in cache:
            return jsonify(cache[key])
        result = func(*args, **kwargs)
        cache[key] = result.get_json()
        return result

    return wrapper

# Token validation decorator
def token_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Example of simple token validation (in real scenarios use a secure method)
        auth_header = request.headers.get('Authorization')
        if not auth_header or 'Bearer' not in auth_header:
            return jsonify({"error": "Unauthorized"}), 401
        user_id = auth_header.split(" ")[1]
        g.user_id = user_id
        return f(*args, **kwargs)

    return decorated_function

# Optimistic concurrency control update function
@app.route('/resource/<resource_id>', methods=['PUT'])
@token_required
def update_resource(resource_id):
    request_data = request.get_json()
    current_version = request.headers.get('If-Match')

    with threading.Lock():
        resource = resources_db.get(resource_id)

        if not resource:
            return jsonify({"error": "Resource not found"}), 404

        # Check for concurrency control
        if resource['last_modified'] != current_version:
            return jsonify({"error": "Conflict, resource has been modified"}), 409

        resource.update(request_data)
        resource['last_modified'] = str(datetime.utcnow())

        log_operation("UPDATE", resource_id, g.user_id)

    # Return updated resource
    return jsonify(resource)

# Soft delete function with configurable soft deletion
@app.route('/resource/<resource_id>', methods=['DELETE'])
@token_required
def delete_resource(resource_id):
    enable_soft_delete = request.args.get('soft-delete', 'true').lower() == 'true'
    user_id = g.user_id

    resource = resources_db.pop(resource_id, None)

    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    # Log the delete operation
    log_operation("DELETE", resource_id, user_id)

    if enable_soft_delete:
        soft_deleted_resources[resource_id] = {
            'data': resource,
            'deleted_at': str(datetime.utcnow())
        }
        return jsonify({'message': 'Resource marked as deleted', 'default_values': {}})
    else:
        # Hard delete (not implemented for mock)
        return jsonify({'message': 'Resource permanently deleted'})

# Example route to demonstrate caching
@app.route('/resource/<resource_id>', methods=['GET'])
@cache_response
def get_resource(resource_id):
    resource = resources_db.get(resource_id) or soft_deleted_resources.get(resource_id, None)

    if not resource:
        return jsonify({"error": "Resource not found"}), 404

    return jsonify(resource)

if __name__ == '__main__':
    app.run(debug=True)
```

### Key Features Explained:

- **Optimistic Concurrency Control**: Implemented by checking the `last_modified` timestamp in headers before updating resources.
- **Soft Deletion**: Configurable via query parameter, stored with a deletion timestamp.
- **Logging**: Simplified logging function to simulate tracking updates and deletions.
- **Caching**: Basic caching mechanism applied using a decorator for GET requests.
- **Token Authentication**: Simple token-based authentication system.

This implementation provides a foundational framework that can be extended with database integration, secure token handling, and more robust caching strategies based on specific needs.']

