using System;
using System.Threading;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        WebPageManager manager = new WebPageManager();

        // Start background process to randomly start/stop the manager
        Thread backgroundThread = new Thread(() => StartStopBackgroundProcess(manager));
        backgroundThread.Start();

        Console.WriteLine("Service started. Press any key to exit...");
        Console.ReadKey();
    }

    static void StartStopBackgroundProcess(WebPageManager manager)
    {
        Random random = new Random();
        bool isRunning = false;

        while (true)
        {
            Thread.Sleep(TimeSpan.FromSeconds(random.Next(5, 16)));

            if (!isRunning)
            {
                Console.WriteLine("Starting WebPageManager...");
                manager.Start();
                isRunning = true;
            }
            else
            {
                Console.WriteLine($"Stopping WebPageManager at {DateTime.UtcNow}");
                manager.Stop();
                isRunning = false;
            }
        }
    }
}

class WebPageManager : IDisposable
{
    private bool _isDisposed = false;

    public void Start()
    {
        // Simulate starting the service (e.g., opening connections, initializing resources)
        Console.WriteLine("WebPageManager started.");
    }

    public void Stop()
    {
        // Simulate stopping the service (e.g., closing connections, cleaning up resources)
        Console.WriteLine("WebPageManager stopped.");
    }

    public async Task HandlePostRequestAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (_isDisposed) throw new ObjectDisposedException(nameof(WebPageManager));

        // Simulate rendering the HTML content
        await RenderHtmlContentAsync(pageSectionId, elementId, htmlContent);

        // Simulate sending a notification to refresh the page
        await SendRefreshNotificationAsync();
    }

    private async Task RenderHtmlContentAsync(string pageSectionId, string elementId, string htmlContent)
    {
