    private async Task SendRefreshNotificationAsync()
    {
        Console.WriteLine("Sending refresh notification...");

        // Simulate potential network latency and timeouts
        try
        {
            await Task.Delay(TimeSpan.FromSeconds(1));
            Console.WriteLine("Refresh notification sent.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error sending refresh notification: {ex.Message}");
        }
    }

    public void Dispose()
