using Microsoft.AspNetCore.Identity;
using System.Threading.Tasks;

namespace UserAccountManagementApp
{
    public class CustomUserValidator<TUser> : UserValidator<TUser>
        where TUser : class, IdentityUser
    {
        public CustomUserValidator(UserManager<TUser> manager) : base(manager)
        {
        }

        protected override async Task<IdentityResult> ValidateAsync(UserManager<TUser> manager, TUser user)
        {
            var result = await base.ValidateAsync(manager, user);

            // Additional validation logic
            if (user.UserName.Length < 5)
            {
                return IdentityResult.Failed("Username must be at least 5 characters long.");
            }

            return result;
        }
    }

// CustomPasswordValidator.cs

using Microsoft.AspNetCore.Identity;
using System.Threading.Tasks;

namespace UserAccountManagementApp
{
    public class CustomPasswordValidator : IPasswordValidator<string>
    {
        public Task<IdentityResult> ValidateAsync(UserManager<string> manager, string password)
        {
            var result = new IdentityResult();

            if (password.Length < 8)
            {
                result.Errors.Add("Password must be at least 8 characters long.");
            }

            // Additional complexity checks
            if (!System.Text.RegularExpressions.Regex.IsMatch(password, @"\d"))
            {
                result.Errors.Add("Password must contain a digit.");
            }

            return Task.FromResult(result);
        }
    }

// AccountController.cs

using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using System.Threading.Tasks;

namespace UserAccountManagementApp.Controllers
{
    public class AccountController : Controller
    {
        private readonly UserManager<ApplicationUser> _userManager;

        public AccountController(UserManager<ApplicationUser> userManager)
        {
            _userManager = userManager;
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<IActionResult> Register(string username, string password)
        {
            var user = new ApplicationUser { UserName = username };
            var result = await _userManager.CreateAsync(user, password);

            if (result.Succeeded)
            {
                // Redirect to login page or another appropriate action
                return RedirectToAction("Login");
            }

            foreach (var error in result.Errors)
            {
                ModelState.AddModelError(string.Empty, error.Description);
            }

            return View();
        }
    }
