typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    return list;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = NULL;
    return new_node;
}

int exists_in_list(LinkedList* list, uint32_t tag, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == tag && 
            current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

void add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!exists_in_list(list, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI)) {
        Node* new_node = create_node(pdu);
        new_node->next = list->head;
        list->head = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T read_pdu_from_file(FILE* file) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    return pdu;
}

void merge_files(const char** filenames, int num_files) {
    LinkedList* merged_list = create_list();

    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(filenames[i], "rb");
        if (!file) {
            perror("Error opening file");
            continue;
        }

        while (!feof(file)) {
            NFAPI_CRC_INDICATION_PDU_T pdu = read_pdu_from_file(file);
            // Validate CRCFLAG or other logic here if needed
            add_to_list(merged_list, pdu);
        }

        fclose(file);
    }

    // Process the merged list as needed

    Node* current = merged_list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(merged_list);
}

int main() {
    const char* files[] = {"file1.bin", "file2.bin", "file3.bin"};
    int num_files = sizeof(files) / sizeof(files[0]);
    merge_files(files, num_files);
    return 0;
}
