class DOMTraverser {
  constructor(selector) {
    this.selector = selector;
    this.cleanupInterval = 5000; // time in milliseconds to run cleanup
    this.cleanup();
  }

  traverse() {
    const observer = new MutationObserver(this.handleMutations.bind(this));
    observer.observe(document, { childList: true, subtree: true });

    return this._traverseDOM(document);
  }

  _traverseDOM(node) {
    const results = [];
    if (!node || typeof node.matches !== 'function') return results;

    try {
      const elements = Array.from(node.querySelectorAll(this.selector));
      results.push(...elements);

      for (const child of node.childNodes) {
        results.push(...this._traverseDOM(child));
      }
    } catch (error) {
      console.error(`Error traversing DOM: ${error.message}`);
    }

    return results;
  }

  handleMutations(mutationsList) {
    mutationsList.forEach(mutation => {
      if (mutation.type === 'childList') {
        mutation.addedNodes.forEach(node =>
          this._traverseDOM(node)
        );
        mutation.removedNodes.forEach(node => 
          this.cleanupOrphanedNode(node)
        );
      }
    });
  }

  cleanupOrphanedNode(node) {
    // Implement logic to check if node is orphaned and can be safely cleaned
    const isOrphaned = !node.isConnected;
    if (isOrphaned) {
      node.remove(); // Example cleanup action
    }
  }

  cleanup() {
    setInterval(() => this._cleanupTask(), this.cleanupInterval);
  }

  _cleanupTask() {
    // Placeholder for periodic resource management logic
    console.log('Running periodic cleanup task');
    // Implement logic to manage memory and clean up unnecessary nodes
  }
}

// Usage Example:
const traverser = new DOMTraverser('.target-class');
const matchingElements = traverser.traverse();
console.log(matchingElements);
```

### Explanation of Key Features:

- **Performance Optimization**: The `traverse` method uses `querySelectorAll` for efficient element matching and a `MutationObserver` to handle dynamic updates without constant polling.

- **Resource Management**: Periodic cleanup is implemented using `setInterval`. `_cleanupTask` can be extended with logic to clean up orphaned nodes efficiently.

- **Concurrency Handling**: The use of `MutationObserver` ensures that the DOM changes are tracked asynchronously, minimizing race conditions during traversal and updates.

- **Scalability**: The recursive `_traverseDOM` function processes child nodes one by one. The approach is designed for scalability in large DOM trees through efficient querying and mutation handling.

- **Usability**: The class-based design allows easy integration and extension, providing a flexible API (`constructor`, `traverse`) that can be customized as needed.

- **Error Handling**: Errors during traversal are caught and logged with informative messages to aid debugging without disrupting the application flow."]

