class ModuleLoader {
  constructor(apiEndpoint) {
    this.apiEndpoint = apiEndpoint;
    this.modules = new Map();
    this.loadedModules = new Set();
    this.loadingQueue = [];
    this.dependencyGraph = new Map();

    // Start monitoring for dynamic module updates
    setInterval(() => this.checkForUpdates(), 5000);
  }

  async loadModule(moduleId, dependencies = []) {
    if (this.loadedModules.has(moduleId)) return Promise.resolve();

    const { loadedDependencies } = await this.loadDependencies(dependencies);

    try {
      const response = await fetch(`${this.apiEndpoint}/${moduleId}.js`);
      if (!response.ok) throw new Error(`Failed to load module: ${moduleId}`);

      const moduleCode = await response.text();
      const moduleFunc = new Function('exports', 'require', moduleCode);
      const moduleExports = {};
      moduleFunc(moduleExports, (depId) => this.requireModule(depId));

      this.modules.set(moduleId, moduleExports);
      this.loadedModules.add(moduleId);

      return moduleExports;
    } catch (error) {
      console.error(`Error loading module ${moduleId}:`, error);
      throw error; // Propagate the error to handle it at a higher level
    }
  }

  async loadDependencies(dependencies) {
    const promises = dependencies.map(dep => this.loadModule(dep));
    return Promise.all(promises).then(results => ({
      loadedDependencies: results,
    }));
  }

  requireModule(moduleId) {
    if (!this.modules.has(moduleId)) throw new Error(`Module ${moduleId} not loaded.`);
    return this.modules.get(moduleId);
  }

  async checkForUpdates() {
    try {
      const response = await fetch(`${this.apiEndpoint}/updates`);
      if (!response.ok) return;

      const { updatedModules } = await response.json();

      for (const moduleId of updatedModules) {
        this.loadedModules.delete(moduleId); // Mark for reload
        this.loadModule(moduleId);
      }
    } catch (error) {
      console.error('Error checking for updates:', error);
    }
  }

  async executeModules(startModuleId) {
    const sortedModules = await this.topologicalSort(startModuleId);

    for (const moduleId of sortedModules) {
      try {
        await this.loadModule(moduleId, this.dependencyGraph.get(moduleId) || []);
      } catch (error) {
        console.error(`Execution error in module ${moduleId}:`, error);
        // Implement recovery or fallback logic if necessary
      }
    }

    console.log('All modules loaded and executed successfully.');
  }

  addDependency(moduleId, dependency) {
    if (!this.dependencyGraph.has(moduleId)) this.dependencyGraph.set(moduleId, []);
    this.dependencyGraph.get(moduleId).push(dependency);
  }

  async topologicalSort(startModuleId) {
    const visited = new Set();
    const stack = [];
    const order = [];

    const visit = async (node) => {
      if (!visited.has(node)) {
        visited.add(node);

        const dependencies = this.dependencyGraph.get(node) || [];
        for (const dep of dependencies) {
          await visit(dep);
        }

        stack.push(node);
      }
    };

    await visit(startModuleId);
    while (stack.length > 0) order.push(stack.pop());
    return order;
  }
}

// Usage example:
(async () => {
  const apiEndpoint = 'https://api.example.com/modules';
  const loader = new ModuleLoader(apiEndpoint);

  // Define dependencies
  loader.addDependency('moduleA', ['moduleB', 'moduleC']);
  loader.addDependency('moduleB', ['moduleD']);
  loader.addDependency('moduleC', []);

  try {
    await loader.executeModules('moduleA');
  } catch (error) {
    console.error('Failed to execute modules:', error);
  }
})();
