import java.io.FileWriter;
import java.io.IOException;
import java.util.Arrays;
import java.util.Date;

public class DisjointPairsCounter {

    private static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]);
            }
            return parent[p];
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);

            if (rootP == rootQ) return;

            if (rank[rootP] < rank[rootQ]) {
                parent[rootP] = rootQ;
            } else if (rank[rootP] > rank[rootQ]) {
                parent[rootQ] = rootP;
            } else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }

    public static int processDisjointPairs(int[] array) throws IOException {
        if (array == null || array.length < 2) {
            logRuntimeInformation(array, 0);
            return 0;
        }

        long startTime = System.currentTimeMillis();

        UnionFind uf = new UnionFind(array.length);

        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] != array[i + 1]) {
                uf.union(i, i + 1);
            }
        }

        int disjointPairs = 0;
        int[] seenRoots = new int[array.length];
        Arrays.fill(seenRoots, -1);

        for (int i = 0; i < array.length; i++) {
            int root = uf.find(i);
            if (seenRoots[root] == -1) {
                disjointPairs++;
                seenRoots[root] = root;
            }
        }

        long endTime = System.currentTimeMillis();

        logRuntimeInformation(array, disjointPairs, startTime, endTime);

        return disjointPairs;
    }

    private static void logRuntimeInformation(int[] array, int disjointPairs, long startTime, long endTime) throws IOException {
        long duration = endTime - startTime;

        try (FileWriter writer = new FileWriter("runtime_log.txt", true)) {
            writer.append(String.format(
                "Timestamp: %s\nSize of input array: %d\nDisjoint pairs found: %d\nTime taken (ms): %d\n",
                new Date(), array == null ? 0 : array.length, disjointPairs, duration
            ));
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            int[] exampleArray = {1, 2, 3, 4, 5};
            System.out.println(processDisjointPairs(exampleArray));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```']

