import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.*;
import java.util.concurrent.*;

public class ConnectionPoolService {

    private final int maxConnectionsPerAddress;
    private final ExecutorService executorService;
    private final Map<String, AddressConnectionPool> addressPools;
    private final ScheduledExecutorService scheduler;

    public ConnectionPoolService(int maxConnectionsPerAddress) {
        this.maxConnectionsPerAddress = maxConnectionsPerAddress;
        this.executorService = Executors.newCachedThreadPool();
        this.addressPools = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void addConnection(String address, InetSocketAddress socketAddress) throws IOException {
        AddressConnectionPool pool = addressPools.computeIfAbsent(address, k -> new AddressConnectionPool(maxConnectionsPerAddress));
        executorService.submit(() -> {
            try (SocketChannel channel = SocketChannel.open()) {
                channel.configureBlocking(false);
                channel.connect(socketAddress);

                if (!channel.finishConnect()) {
                    // Handle connection failure
                    return;
                }

                pool.add(channel);
            } catch (IOException e) {
                e.printStackTrace();
                // Handle exception, possibly with retry logic or error handling
            }
        });
    }

    public void removeConnection(String address) {
        AddressConnectionPool pool = addressPools.get(address);
        if (pool != null) {
            pool.clear();
            addressPools.remove(address);
        }
    }

    public int resizePool(String address, int newSize) {
        AddressConnectionPool pool = addressPools.get(address);
        if (pool == null) return 0;

        return pool.resize(newSize);
    }

    public void monitorAndAdjust() {
        scheduler.scheduleAtFixedRate(() -> {
            for (AddressConnectionPool pool : addressPools.values()) {
                // Adjust size based on load metrics
                int optimalSize = calculateOptimalSize(pool); 
                pool.resize(optimalSize);
            }
        }, 0, 1, TimeUnit.MINUTES);
    }

    private int calculateOptimalSize(AddressConnectionPool pool) {
        // Placeholder for logic to determine optimal pool size based on real-time conditions
        return Math.min(maxConnectionsPerAddress, pool.getActiveChannels() * 2);
    }

    public void shutdown() {
        executorService.shutdown();
        scheduler.shutdownNow();
        addressPools.values().forEach(AddressConnectionPool::clear);
    }

    private static class AddressConnectionPool {
        private final int maxSize;
        private final Queue<SocketChannel> idleChannels = new ConcurrentLinkedQueue<>();
        private final Set<SocketChannel> activeChannels = ConcurrentHashMap.newKeySet();

        public AddressConnectionPool(int maxSize) {
            this.maxSize = maxSize;
        }

        public void add(SocketChannel channel) throws IOException {
            if (activeChannels.size() < maxSize && !idleChannels.contains(channel)) {
                activeChannels.add(channel);
                idleChannels.offer(channel);
            } else {
                channel.close();
            }
        }

        public void clear() {
            for (SocketChannel channel : new HashSet<>(idleChannels)) {
                try {
                    channel.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            idleChannels.clear();
            activeChannels.clear();
        }

        public int getActiveChannels() {
            return activeChannels.size();
        }

        public int resize(int newSize) {
            int excess = Math.max(0, activeChannels.size() + idleChannels.size() - newSize);
            for (int i = 0; i < excess && !idleChannels.isEmpty(); i++) {
                SocketChannel channel = idleChannels.poll();
                if (channel != null) {
                    activeChannels.remove(channel);
                    try {
                        channel.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }
            return activeChannels.size() + idleChannels.size();
        }
    }

    public static void main(String[] args) throws IOException {
        ConnectionPoolService service = new ConnectionPoolService(100);
        // Example usage
        service.addConnection("example.com", new InetSocketAddress("example.com", 80));
        service.monitorAndAdjust();

        // Ensure proper shutdown on application exit
        Runtime.getRuntime().addShutdownHook(new Thread(service::shutdown));
    }
}
