<?php

class ConfigLoader {
    private $environment;
    private $cache = [];
    private $maxRetries = 5;

    public function __construct($environment) {
        $this->environment = $environment;
    }

    public function loadConfig() {
        if (isset($this->cache[$this->environment])) {
            return $this->cache[$this->environment];
        }

        $configFile = "config/{$this->environment}.json";

        // Load configuration with retry mechanism
        for ($attempt = 0; $attempt < $this->maxRetries; $attempt++) {
            try {
                if (!file_exists($configFile)) {
                    throw new Exception("Config file not found: {$configFile}");
                }

                $configData = json_decode(file_get_contents($configFile), true);

                // Validate configuration integrity
                if (!$this->validateConfig($configData)) {
                    throw new Exception("Invalid config data");
                }

                $this->cache[$this->environment] = $configData;
                return $configData;

            } catch (Exception $e) {
                sleep(pow(2, $attempt)); // Exponential backoff
                if ($attempt == $this->maxRetries - 1) {
                    throw new Exception("Failed to load configuration: " . $e->getMessage());
                }
            }
        }
    }

    private function validateConfig($configData) {
        return isset($configData['db']['host']) && 
               isset($configData['api_keys']) &&
               isset($configData['server_settings']);
    }
}

function printUsage() {
    echo "Usage: php init.php <environment>\n";
    echo "Available environments: development, testing, production\n";
}

if ($argc !== 2) {
    printUsage();
    exit(1);
}

$environment = $argv[1];
$validEnvironments = ['development', 'testing', 'production'];

if (!in_array($environment, $validEnvironments)) {
    echo "Invalid environment. Please choose from: development, testing, production\n";
    exit(1);
}

$configLoader = new ConfigLoader($environment);

try {
    $config = $configLoader->loadConfig();
    // Use the loaded configuration as needed
    print_r($config);
} catch (Exception $e) {
    echo "Error: " . $e->getMessage() . "\n";
}
```

### Justification for Centralized Configuration Management

**Pros:**
- **Consistency:** Ensures uniformity across all environments.
- **Simplified Maintenance:** Easier to manage and update configurations in a single location.
- **Version Control Integration:** Facilitates tracking changes and rollback if necessary.

**Cons:**
- **Single Point of Failure:** If the centralized repository is unavailable, it can disrupt all environments.
- **Complexity:** Requires robust error handling and retry mechanisms.

The choice for a centralized configuration management system in this script is justified by its ability to maintain consistency and simplify maintenance across multiple environments. The implementation includes caching and retry mechanisms to mitigate potential network failures and optimize performance.']

['Below is a Rust implementation of an HTTP client library that meets the specified requirements:

```rust
use std::time::Duration;
use tokio::time::{sleep as async_sleep};
use reqwest::{Client, Error as ReqwestError, header::HeaderMap, Url, Response, StatusCode};
use log::{info, error};

pub struct HttpClientConfig {
    pub max_retries: u32,
    pub backoff_factor: f64,
    pub timeout: Duration,
    pub insecure: bool,
}

impl Default for HttpClientConfig {
    fn default() -> Self {
        Self {
            max_retries: 3,
            backoff_factor: 2.0,
            timeout: Duration::from_secs(10),
            insecure: false,
        }
    }
}

pub struct HttpClient {
    config: HttpClientConfig,
}

impl HttpClient {
    pub fn new(config: HttpClientConfig) -> Self {
        Self { config }
    }

    pub async fn send_request_async(&self, url: &str, headers: HeaderMap) -> Result<Response, ReqwestError> {
        let client = Client::builder()
            .timeout(self.config.timeout)
            .danger_accept_invalid_certs(self.config.insecure)
            .build()?;

        self.send_with_retry(client, url, headers).await
    }

    pub fn send_request_sync(&self, url: &str, headers: HeaderMap) -> Result<Response, ReqwestError> {
        let client = reqwest::blocking::Client::builder()
            .timeout(self.config.timeout)
            .danger_accept_invalid_certs(self.config.insecure)
            .build()?;

        self.send_with_retry_sync(client, url, headers)
    }

    async fn send_with_retry(&self, mut client: Client, url: &str, headers: HeaderMap) -> Result<Response, ReqwestError> {
        let mut attempts = 0;
        loop {
            match client.get(url).headers(headers.clone()).send().await {
                Ok(response) => return self.handle_response(response),
                Err(err) if attempts < self.config.max_retries => {
                    attempts += 1;
                    let backoff_time = (self.config.backoff_factor.powi(attempts as i32)) as u64;
                    info!("Retrying in {} seconds...", backoff_time);
                    async_sleep(Duration::from_secs(backoff_time)).await;
                }
                Err(err) => return Err(err),
            }
        }
    }

    fn send_with_retry_sync(&self, mut client: reqwest::blocking::Client, url: &str, headers: HeaderMap) -> Result<Response, ReqwestError> {
        let mut attempts = 0;
        loop {
            match client.get(url).headers(headers.clone()).send() {
                Ok(response) => return self.handle_response_sync(response),
                Err(err) if attempts < self.config.max_retries => {
                    attempts += 1;
                    let backoff_time = (self.config.backoff_factor.powi(attempts as i32)) as u64;
                    info!("Retrying in {} seconds...", backoff_time);
                    std::thread::sleep(Duration::from_secs(backoff_time));
                }
                Err(err) => return Err(err),
            }
        }
    }

    fn handle_response(&self, response: Response) -> Result<Response, ReqwestError> {
        match response.status() {
            StatusCode::OK | StatusCode::CREATED | StatusCode::ACCEPTED => Ok(response),
            _ => Err(ReqwestError::new(reqwest::StatusCode::INTERNAL_SERVER_ERROR, false)),
        }
    }

    fn handle_response_sync(&self, response: reqwest::blocking::Response) -> Result<Response, ReqwestError> {
        match response.status() {
            StatusCode::OK | StatusCode::CREATED | StatusCode::ACCEPTED => Ok(response),
            _ => Err(ReqwestError::new(reqwest::StatusCode::INTERNAL_SERVER_ERROR, false)),
        }
    }
}

#[tokio::main]
async fn main() {
    let config = HttpClientConfig {
        max_retries: 3,
        backoff_factor: 2.0,
        timeout: Duration::from_secs(10),
        insecure: true, // Use with caution; only in trusted environments.
    };

    let client = HttpClient::new(config);
    let headers = HeaderMap::new();

    match client.send_request_async("https://example.com", headers).await {
        Ok(response) => info!("Response: {:?}", response.status()),
        Err(e) => error!("Request failed: {:?}", e),
    }
}
```

### Key Features:
- **Synchronous and Asynchronous Support**: Uses `reqwest` for both sync (`blocking`) and async requests.
- **Retry Logic with Exponential Backoff**: Configurable max retries and backoff intervals.
- **Connection Pooling**: Leveraged by `reqwest`.
- **Custom Headers & Timeout**: Supports custom headers and request timeouts.
- **Logging Integration**: Uses the `log` crate for logging retry attempts and responses.
- **Insecure Connections**: Option to disable certificate validation, with caution advised.']

