#define MAX_INPUTS 10000

void readFloatingPointNumbers(double *arr) {
    printf("Enter up to %d floating-point numbers:\n", MAX_INPUTS);
    for (int i = 0; i < MAX_INPUTS; ++i) {
        if (scanf("%lf", &arr[i]) != 1) break;
    }
}

void calculateAndPrintStatistics(const double *arr, int size) {
    double sum = 0.0, mean, variance = 0.0, stddev;

    for (int i = 0; i < size; ++i) {
        sum += arr[i];
    }

    mean = sum / size;

    for (int i = 0; i < size; ++i) {
        variance += pow(arr[i] - mean, 2);
    }

    stddev = sqrt(variance / size);

    printf("Mean: %f\n", mean);
