    CUSTOMER_TRANSACTION *head = NULL, *tail = NULL;

    for (int i = 0; i < MAX_INPUTS; ++i) {
        CUSTOMER_TRANSACTION *newNode = malloc(sizeof(CUSTOMER_TRANSACTION));
        if (!newNode) exit(EXIT_FAILURE);

        snprintf(newNode->transactionID, sizeof(newNode->transactionID), "TXN%d", i);
        newNode->TRANSACTION_TAG = transactions[i].amount;
        newNode->amount = transactions[i].amount;
        newNode->statusFlag = rand() % 2; // Random status flag
        newNode->prev = tail;
        newNode->next = NULL;

        if (tail) {
            tail->next = newNode;
        } else {
            head = newNode;
        }

        tail = newNode;
    }

    // Print linked list transactions for demonstration
    CUSTOMER_TRANSACTION *current = head;
    while (current != NULL) {
        printf("Transaction ID: %s, Amount: %.2f, Status: %d\n", current->transactionID, current->amount, current->statusFlag);
        current = current->next;
    }

    // Free allocated memory
    free(transactions);

    CUSTOMER_TRANSACTION *temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    double inputNumbers[MAX_INPUTS];
    readFloatingPointNumbers(inputNumbers);

    int validCount = 0;
    for (int i = 0; i < MAX_INPUTS; ++i) {
        if (inputNumbers[i] != 0.0 || validCount == 0) { // Assuming non-zero entries are valid
            validCount++;
        } else {
            break;
        }
    }

    calculateAndPrintStatistics(inputNumbers, validCount);

    manageDataStructures(1, "user", "pass");

    return 0;
}
