<?php

function generateRandomStringAndHashPassword($length, $password) {
    if (!is_int($length) || $length < 8 || $length > 128) {
        throw new InvalidArgumentException('Length must be an integer between 8 and 128.');
    }

    $uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $lowercase = 'abcdefghijklmnopqrstuvwxyz';
    $digits = '0123456789';
    $specialChars = '!@#$%^&*()-_=+[]{}|;:,.<>?';

    if (strlen($password) < 1) {
        throw new InvalidArgumentException('Password must not be empty.');
    }

    // Ensuring at least one of each required character type
    $randomString = [
        random_int(0, strlen($uppercase) - 1),
        random_int(0, strlen($lowercase) - 1),
        random_int(0, strlen($digits) - 1),
        random_int(0, strlen($specialChars) - 1)
    ];

    // Filling the rest of the length with a mix of all characters
    $allChars = $uppercase . $lowercase . $digits . $specialChars;
    for ($i = 4; $i < $length; $i++) {
        $randomString[] = random_int(0, strlen($allChars) - 1);
    }

    // Shuffle to ensure randomness
    shuffle($randomString);

    // Build the final string
    $finalRandomString = '';
    foreach ($randomString as $index) {
        if (strpos($uppercase, $allChars[$index]) !== false) {
            $finalRandomString .= $uppercase[$index];
        } elseif (strpos($lowercase, $allChars[$index]) !== false) {
            $finalRandomString .= $lowercase[$index];
        } elseif (strpos($digits, $allChars[$index]) !== false) {
            $finalRandomString .= $digits[$index];
        } else {
            $finalRandomString .= $specialChars[$index];
        }
    }

    // Hash the password using a secure algorithm
    $options = ['cost' => 12];
    $hashedPassword = password_hash($password, PASSWORD_BCRYPT, $options);

    return [
        'random_string' => $finalRandomString,
        'hashed_password' => $hashedPassword
    ];
}

// Example usage:
try {
    $result = generateRandomStringAndHashPassword(16, 'YourSecurePassword123!');
    echo "Random String: " . $result['random_string'] . "\n";
    echo "Hashed Password: " . $result['hashed_password'] . "\n";
} catch (InvalidArgumentException $e) {
    echo "Error: " . $e->getMessage();
}
?>
```

### Key Considerations:

1. **Security**: The function ensures the random string contains at least one character from each required category.
2. **Password Hashing**: Uses `password_hash` with Bcrypt, a secure and widely accepted hashing algorithm.
3. **Input Validation**: Validates input length and password content to prevent errors and misuse.
4. **Concurrency & Performance**: Designed for efficiency by using PHP's native functions like `random_int`, which are both fast and cryptographically secure.
5. **Scalability**: The function is stateless, making it suitable for horizontal scaling in distributed environments.']

