['```c
#include <stdlib.h>
#include <stdio.h>

typedef struct State {
    int state_id;
    int next_state;  // -1 if no transition
} State;

typedef struct FSA {
    int num_states;
    State* states;
} FSA;

State* create_state_list(FSA* fsa, int last_state, State* current_head) {
    if (!fsa || !fsa->states || last_state < 0 || last_state >= fsa->num_states) {
        return NULL;
    }

    int visited[fsa->num_states] = {0};
    State** stack = (State**)malloc(fsa->num_states * sizeof(State*));
    if (!stack) return NULL;

    int top = -1;
    stack[++top] = &fsa->states[last_state];
    visited[last_state] = 1;

    State* new_head = NULL;
    State* tail = NULL;

    while (top >= 0) {
        State* current = *stack[top--];

        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) {
            free(stack);
            while (new_head != NULL) {
                State* temp = new_head;
                new_head = new_head->next_state;
                free(temp);
            }
            return NULL;
        }

        *new_state = *current;

        if (new_head == NULL) {
            new_head = new_state;
            tail = new_state;
        } else {
            tail->next_state = new_state;
            tail = new_state;
        }

        int next_id = current->next_state;
        while (next_id != -1 && !visited[next_id]) {
            if (top >= fsa->num_states) {
                free(stack);
                while (new_head != NULL) {
                    State* temp = new_head;
                    new_head = new_head->next_state;
                    free(temp);
                }
                return NULL;
            }

            stack[++top] = &fsa->states[next_id];
            visited[next_id] = 1;

            next_id = fsa->states[next_id].next_state;
        }
    }

    free(stack);

    if (current_head != NULL) {
        State* temp = current_head;
        while (temp->next_state != NULL) {
            temp = temp->next_state;
        }
        temp->next_state = new_head;
    } else {
        current_head = new_head;
    }

    return current_head;
}

void free_state_list(State* head) {
    State* temp;
    while (head != NULL) {
        temp = head;
        head = head->next_state;
        free(temp);
    }
}
