#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <pthread.h>

// Data structure for each processed number
typedef struct {
    int id;
    double value;
    pthread_mutex_t ref_count_lock;
    unsigned int ref_count;
} Number;

// Custom data structure for efficient traversal and access
typedef struct Node {
    Number *number;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_rwlock_t list_lock;
} NumberList;

NumberList* create_number_list() {
    NumberList *list = malloc(sizeof(NumberList));
    list->head = NULL;
    pthread_rwlock_init(&list->list_lock, NULL);
    return list;
}

void insert_number(NumberList *list, Number *number) {
    Node *new_node = malloc(sizeof(Node));
    new_node->number = number;
    new_node->next = NULL;

    pthread_rwlock_wrlock(&list->list_lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_rwlock_unlock(&list->list_lock);
}

void free_number_list(NumberList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->number);
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&list->list_lock);
    free(list);
}

void increment_ref_count(Number *number) {
    pthread_mutex_lock(&number->ref_count_lock);
    number->ref_count++;
    pthread_mutex_unlock(&number->ref_count_lock);
}

void decrement_ref_count(Number *number) {
    pthread_mutex_lock(&number->ref_count_lock);
    if (number->ref_count > 0) {
        number->ref_count--;
    }
    pthread_mutex_unlock(&number->ref_count_lock);
}

double read_and_process_file(const char* filename, NumberList *list) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NAN;

    double value;
    int id = 0;
    size_t count = 0;
    double sum = 0.0, sq_sum = 0.0;

    while (fread(&value, sizeof(double), 1, file)) {
        Number *number = malloc(sizeof(Number));
        if (!number) break;

        number->id = id++;
        number->value = value;
        pthread_mutex_init(&number->ref_count_lock, NULL);
        number->ref_count = 1;

        insert_number(list, number);

        sum += value;
        sq_sum += value * value;
        count++;

        // Free memory to manage large datasets
        decrement_ref_count(number);
        free(number);
    }

    fclose(file);

    if (count == 0) return NAN;

    double mean = sum / count;
    double variance = (sq_sum / count) - (mean * mean);
    double stddev = sqrt(variance);

    printf("Mean: %f, Standard Deviation: %f\n", mean, stddev);

    return mean; // or stddev if needed
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    NumberList *list = create_number_list();
    read_and_process_file(argv[1], list);
    free_number_list(list);

    return EXIT_SUCCESS;
}
