#include <iostream>
#include <vector>
#include <memory>

class OctreeNode {
public:
    std::vector<std::unique_ptr<OctreeNode>> children;
    bool isLeaf = true;

    ~OctreeNode() = default; // Destructor to manage dynamic memory

    void initializeChildren() {
        if (!isLeaf) return;
        for (auto& child : children) {
            child.reset(new OctreeNode());
        }
        isLeaf = false;
    }
};

class Octree {
private:
    std::unique_ptr<OctreeNode> root;
    size_t featureSize, dataCapacity;

public:
    Octree(size_t fs, size_t numLeaves, size_t dc, size_t memoryLimit)
        : featureSize(fs), dataCapacity(dc) {

        if (fs <= 0 || numLeaves <= 0 || dc <= 0 || memoryLimit <= 0) {
            throw std::invalid_argument("Invalid input parameters");
        }

        root = std::make_unique<OctreeNode>();
        size_t estimatedMemoryUsage = calculateMemoryUsage(numLeaves);

        if (estimatedMemoryUsage > memoryLimit) {
            throw std::runtime_error("Memory limit exceeded");
        }

        initializeTree(root.get(), numLeaves);
    }

private:
    void initializeTree(OctreeNode* node, size_t remainingNodes) {
        if (remainingNodes == 0 || node->children.size() == 8) {
            return;
        }

        node->initializeChildren();
        for (auto& child : node->children) {
            initializeTree(child.get(), remainingNodes - 1);
        }
    }

    size_t calculateMemoryUsage(size_t numLeaves) {
        // Simplified memory usage estimation; adjust as necessary
        return sizeof(OctreeNode) * numLeaves;
    }
};

// Example of how to use the Octree class
int main() {
    try {
        size_t featureSize = 10;
        size_t numLeafNodes = 1000;
        size_t dataCapacity = 500;
        size_t memoryLimit = 1024 * 1024 * 50; // 50 MB

        Octree octree(featureSize, numLeafNodes, dataCapacity, memoryLimit);
        std::cout << "Octree initialized successfully!" << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error initializing Octree: " << e.what() << std::endl;
    }

    return 0;
}
