['```cpp
#include <iostream>
#include <string>
#include <vector>
#include <ctime>
#include <cstdlib>

class StrategyManager {
public:
    StrategyManager() {
        initializeCooldowns();
        srand(static_cast<unsigned int>(time(0)));
        for (int i = 0; i < 7; ++i) history.push_back("N"); // "N" for no strategy
    }

    void selectStrategy() {
        if (shouldSkipNext()) {
            skipNext();
            return;
        }

        updateCooldowns();

        int currentTime = static_cast<int>(time(0));
        std::string nextStrategy;

        // Determine available strategies based on cooldown
        if (currentTime >= aggressiveCooldown) {
            nextStrategy = "Aggressive";
        } else if (currentTime >= balancedCooldown) {
            nextStrategy = "Balanced";
        } else if (currentTime >= defensiveCooldown) {
            nextStrategy = "Defensive";
        }

        // If all strategies are on cooldown, choose a random strategy from available ones
        if (nextStrategy.empty()) {
            int roll = rand() % 3;
            switch (roll) {
                case 0: if (currentTime >= aggressiveCooldown) nextStrategy = "Aggressive"; break;
                case 1: if (currentTime >= balancedCooldown) nextStrategy = "Balanced"; break;
                case 2: if (currentTime >= defensiveCooldown) nextStrategy = "Defensive"; break;
            }
        }

        // If no strategy is available, wait
        if (nextStrategy.empty()) {
            std::cout << "0" << std::endl; // Indicate waiting for cooldowns to expire
            return;
        }

        applyStrategy(nextStrategy);
    }

private:
    struct CooldownInfo {
        int time;
        const char strategyChar;
        int duration;

        bool isReady(int currentTime) const {
            return currentTime >= time;
        }
    };

    void initializeCooldowns() {
        aggressiveCooldown = {0, 'A', 10};
        balancedCooldown = {0, 'B', 8};
        defensiveCooldown = {0, 'D', 12};
    }

    void updateCooldowns() {
        int currentTime = static_cast<int>(time(0));
        if (aggressiveCooldown.isReady(currentTime)) {
            aggressiveCooldown.time = currentTime + aggressiveCooldown.duration;
        }
        if (balancedCooldown.isReady(currentTime)) {
            balancedCooldown.time = currentTime + balancedCooldown.duration;
        }
        if (defensiveCooldown.isReady(currentTime)) {
            defensiveCooldown.time = currentTime + defensiveCooldown.duration;
        }
    }

    void applyStrategy(const std::string& strategy) {
        int currentTime = static_cast<int>(time(0));
        if (strategy == "Aggressive") aggressiveCooldown.time = currentTime;
        else if (strategy == "Balanced") balancedCooldown.time = currentTime;
        else if (strategy == "Defensive") defensiveCooldown.time = currentTime;

        history.push_back(strategy);
        if (history.size() > 7) {
            history.erase(history.begin());
        }

        // Print strategy number
        std::cout << (strategy[0] - 'A' + 1) << std::endl;
    }

    bool shouldSkipNext() const {
        return !history.empty() && checkABBSequence();
    }

    void skipNext() {
        // Skip the next strategy by simulating cooldowns
        aggressiveCooldown.time = static_cast<int>(time(0)) + aggressiveCooldown.duration;
        balancedCooldown.time = static_cast<int>(time(0)) + balancedCooldown.duration;
        defensiveCooldown.time = static_cast<int>(time(0)) + defensiveCooldown.duration;
    }

    bool checkABBSequence() const {
        std::string recent = "";
        for (int i = history.size() - 1; i >= history.size() - 3 && i >= 0; --i) {
            if (!history[i].empty()) recent = history[i] + recent;
        }
        return recent == "ABB";
    }

    CooldownInfo aggressiveCooldown, balancedCooldown, defensiveCooldown;
    std::vector<std::string> history;
};

int main() {
    StrategyManager manager;
    while (true) {
        manager.selectStrategy();
        // Sleep or delay to simulate game loop time step
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
    return 0;
}
