class AsyncReducer {
  constructor(concurrencyLimit = 5, timeoutMs = 5000) {
    this.concurrencyLimit = concurrencyLimit;
    this.timeoutMs = timeoutMs;
  }

  async reduce(array, reducerFn, initialValue) {
    const promises = array.map(item => 
      this._processItemAsync(item, reducerFn).catch(err => ({ error: err }))
    );

    let activeCount = 0;
    let result = initialValue;

    for (let i = 0; i < Math.min(this.concurrencyLimit, promises.length); i++) {
      activeCount++;
      await this._runWithTimeout(promises[i](), async (value) => {
        if (!value.error && typeof value !== 'undefined') {
          result = reducerFn(result, value);
        }
        activeCount--;
        if (i + 1 < promises.length) {
          activeCount++;
          await this._runWithTimeout(promises[i + 1](), async (nextValue) => {
            if (!nextValue.error && typeof nextValue !== 'undefined') {
              result = reducerFn(result, nextValue);
            }
            activeCount--;
            if (i + 2 < promises.length) {
              await this._manageConcurrency(i + 2);
            }
          });
        } else if (activeCount === 0) {
          return;
        }
      });
    }

    while (activeCount > 0) {
      await new Promise(resolve => setTimeout(resolve, 10));
    }

    const errors = promises.map(p => p().then(value => value.error)).filter(Boolean);
    if (errors.length > 0) {
      throw new Error(`Encountered ${errors.length} errors during reduction.`);
    }

    return result;
  }

  _processItemAsync(item, reducerFn) {
    return async () => {
      await this._simulateNetworkLatency();
      if (typeof item === 'number' && !isNaN(item)) {
        return item;
      } else {
        throw new Error(`Invalid data: ${item}`);
      }
    };
  }

  _runWithTimeout(promise, timeout) {
    let timeoutId;
    const timeoutPromise = new Promise((_, reject) =>
      timeoutId = setTimeout(() => reject(new Error('Operation timed out')), this.timeoutMs)
    );

    return Promise.race([
      promise(),
      timeoutPromise
    ]).finally(() => clearTimeout(timeoutId));
  }

  _simulateNetworkLatency() {
    return new Promise(resolve => setTimeout(resolve, Math.random() * 1000));
  }

  async _manageConcurrency(index) {
    while (activeCount >= this.concurrencyLimit && index < promises.length) {
      await new Promise(resolve => setTimeout(resolve, 10));
    }
    if (index < promises.length) {
      activeCount++;
      await this._runWithTimeout(promises[index](), async (value) => {
        if (!value.error && typeof value !== 'undefined') {
          result = reducerFn(result, value);
        }
        activeCount--;
      });
    }
  }
}

// Example usage
const array = [1, 2, null, 'a', 3, 4];
const asyncReducer = new AsyncReducer(3, 10000);

async function runExample() {
  try {
    const result = await asyncReducer.reduce(array, (acc, curr) => acc + curr, 0);
    console.log('Final reduced value:', result);
  } catch (error) {
    console.error('Error occurred during reduction:', error.message);
  }
}

runExample();
```"]

