#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Assuming a resource bundle structure
typedef struct {
    char **items;
    size_t count;
} ResourceBundle;

// Global mutex for thread safety
static pthread_mutex_t bundle_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically load a resource bundle from a specified path
size_t load_resource_bundle(const char *path, ResourceBundle **bundle) {
    if (path == NULL || bundle == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return 0;
    }

    pthread_mutex_lock(&bundle_mutex);

    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open resource file");
        pthread_mutex_unlock(&bundle_mutex);
        return 0;
    }

    ResourceBundle *new_bundle = malloc(sizeof(ResourceBundle));
    if (!new_bundle) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        pthread_mutex_unlock(&bundle_mutex);
        return 0;
    }
    new_bundle->items = NULL;
    new_bundle->count = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t len = strlen(line);
        if (line[len - 1] == '\n') {
            line[--len] = '\0';
        }

        char *item = strdup(line);
        if (!item) {
            fprintf(stderr, "Memory allocation failed for item\n");
            break;
        }

        new_bundle->items = realloc(new_bundle->items, (new_bundle->count + 1) * sizeof(char *));
        if (!new_bundle->items) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(item);
            break;
        }
        new_bundle->items[new_bundle->count++] = item;
    }

    fclose(file);

    if (new_bundle->count == 0) {
        fprintf(stderr, "Failed to load any items from resource file\n");
        free(new_bundle->items);
        free(new_bundle);
        *bundle = NULL;
    } else {
        *bundle = new_bundle;
    }

    pthread_mutex_unlock(&bundle_mutex);

    return new_bundle->count;
}

// Function to free the loaded resource bundle
void free_resource_bundle(ResourceBundle *bundle) {
    if (bundle) {
        for (size_t i = 0; i < bundle->count; ++i) {
            free(bundle->items[i]);
        }
        free(bundle->items);
        free(bundle);
    }
}

int main() {
    ResourceBundle *bundle = NULL;
    size_t count = load_resource_bundle("path/to/resource/file.txt", &bundle);

    if (count > 0) {
        printf("Loaded %zu items from the resource bundle.\n", count);
        for (size_t i = 0; i < count; ++i) {
            printf("%s\n", bundle->items[i]);
        }
    }

    free_resource_bundle(bundle);
    return 0;
}
```

This code defines a C function `load_resource_bundle` that loads a resource bundle from a specified file path and returns the number of items in it. It ensures thread safety using a mutex, handles memory allocation errors, and supports concurrent access. The function also includes basic error logging for critical events and errors.']

