char* process_string(const char *input, size_t size_limit, int padding_flag, char pad_char) {
    if (input == NULL || size_limit == 0) return NULL;

    size_t input_len = strlen(input);
    size_t new_length;
    char *result;

    if (input_len <= size_limit) {
        // If we need to append a slash
        new_length = input_len + 2; // for '/' and '\0'

        result = (char *)malloc(new_length);
        if (!result) return NULL; // Handle malloc failure

        strncpy(result, input, input_len);
        strcat(result, "/");

    } else {
        size_t truncated_length = size_limit;
        new_length = padding_flag ? size_limit + 2 : size_limit + 1; // for '/' and '\0'

        result = (char *)malloc(new_length);
        if (!result) return NULL; // Handle malloc failure

        strncpy(result, input, truncated_length);

        if (padding_flag) {
            memset(result + truncated_length, pad_char, size_limit - truncated_length);
        }

        strcat(result, "/");
    }

    return result;
}

int main() {
    const char *input = "example";
    size_t size_limit = 5;
    int padding_flag = 1;
    char pad_char = 'x';

    char *processed = process_string(input, size_limit, padding_flag, pad_char);
    if (processed) {
        printf("Processed string: %s\n", processed);
        free(processed); // Free allocated memory to avoid leaks
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
