#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILES 100
#define BUFFER_SIZE 1024

void handle_error(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

double calculate_average_of_last_three(double last_three[3]) {
    return (last_three[0] + last_three[1] + last_three[2]) / 3.0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [file2 ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_files = argc - 1;
    if (num_files > MAX_FILES) {
        handle_error("Too many files specified");
    }

    double global_average_sum = 0.0;
    int global_count = 0;

    for (int file_index = 1; file_index <= num_files; ++file_index) {
        FILE *file = fopen(argv[file_index], "r");
        if (!file) {
            fprintf(stderr, "Error opening file %s\n", argv[file_index]);
            continue;
        }

        char buffer[BUFFER_SIZE];
        double last_three[3] = {0.0, 0.0, 0.0};
        int count = 0;
        double line_average_sum = 0.0;

        while (fgets(buffer, sizeof(buffer), file)) {
            char *token = strtok(buffer, " \t\n");
            int local_count = 0;
            double current_values[3] = {0.0, 0.0, 0.0};

            while (token) {
                if (local_count < 3) {
                    current_values[local_count++] = atof(token);
                }
                token = strtok(NULL, " \t\n");
            }

            for (int i = 0; i < 3; ++i) {
                last_three[i] = current_values[i % 3];
            }

            if (local_count >= 3) {
                double avg = calculate_average_of_last_three(last_three);
                line_average_sum += avg;
                count++;
            }
        }

        if (count > 0) {
            double file_average = line_average_sum / count;
            global_average_sum += file_average;
            global_count++;
        }

        fclose(file);
    }

    if (global_count > 0) {
        double overall_average = global_average_sum / global_count;
        printf("Overall Average of Averages: %.6f\n", overall_average);
    } else {
        fprintf(stderr, "No valid data found in files.\n");
    }

    return EXIT_SUCCESS;
}
