```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <stdint.h>

// Define the structure to hold TIFF metadata
typedef struct {
    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint16_t extraSamples;
    char *extraSampleNames[4]; // Possible names for extra samples
} TiffMetadata;

// Function prototypes
int isValidTiffHeader(const unsigned char *buffer);
TiffMetadata* parseTiffFile(const char *filePath, int *error);

void processDirectory(const char *directoryPath) {
    DIR *dir;
    struct dirent *entry;
    if ((dir = opendir(directoryPath)) == NULL) {
        perror("opendir");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".tif") || strstr(entry->d_name, ".tiff")) {
            int error = 0;
            TiffMetadata *metadata = parseTiffFile(entry->d_path, &error);

            if (error) {
                printf("Error processing %s\n", entry->d_name);
                continue;
            }

            // Print extracted metadata
            printf("File: %s\n", entry->d_name);
            printf("Bits Per Sample: %u\n", metadata->bitsPerSample);
            printf("Samples Per Pixel: %u\n", metadata->samplesPerPixel);
            printf("Extra Samples: %u\n", metadata->extraSamples);

            for (int i = 0; i < metadata->extraSamples && metadata->extraSampleNames[i] != NULL; ++i) {
                printf("Extra Sample %d: %s\n", i + 1, metadata->extraSampleNames[i]);
            }

            free(metadata); // Free allocated memory
        }
    }

    closedir(dir);
}

// Helper function to check TIFF header validity
int isValidTiffHeader(const unsigned char *buffer) {
    return buffer[0] == 'I' && buffer[1] == 'I' || buffer[0] == 'M' && buffer[1] == 'M';
}

// Main parsing function for a single TIFF file
TiffMetadata* parseTiffFile(const char *filePath, int *error) {
    FILE *file = fopen(filePath, "rb");
    if (!file) {
        perror("fopen");
        *error = 1;
        return NULL;
    }

    unsigned char buffer[4];
    fread(buffer, sizeof(unsigned char), 2, file);

    if (!isValidTiffHeader(buffer)) {
        fclose(file);
        *error = 1;
        return NULL;
    }

    uint16_t tiffEndianness = buffer[0] == 'I' ? 0x4949 : 0x4D4D;
    // Read the offset to the first IFD
    fseek(file, 4, SEEK_SET);
    uint32_t firstIFDOffset;
    fread(&firstIFDOffset, sizeof(firstIFDOffset), 1, file);

    if (tiffEndianness == 0x4949) {
        // Little-endian swap
        firstIFDOffset = ((firstIFDOffset & 0xFF000000) >> 24) |
                         ((firstIFDOffset & 0x00FF0000) >> 8) |
                         ((firstIFDOffset & 0x0000FF00) << 8) |
                         ((firstIFDOffset & 0x000000FF) << 24);
    }

    fseek(file, firstIFDOffset, SEEK_SET);

    TiffMetadata *metadata = (TiffMetadata *)malloc(sizeof(TiffMetadata));
    if (!metadata) {
        fclose(file);
        *error = 1;
        return NULL;
    }
    memset(metadata, 0, sizeof(TiffMetadata));

    uint16_t numEntries;
    fread(&numEntries, sizeof(numEntries), 1, file);

    for (uint16_t i = 0; i < numEntries; ++i) {
        uint32_t tag, type, count;
        uint32_t valueOffset;
        fread(&tag, sizeof(tag), 1, file);
        fread(&type, sizeof(type), 1, file);
        fread(&count, sizeof(count), 1, file);

        if (tiffEndianness == 0x4949) {
            tag = __builtin_bswap16(tag);
            type = __builtin_bswap16(type);
            count = __builtin_bswap32(count);
        }

        if (tag == 258) { // BitsPerSample
            fread(&metadata->bitsPerSample, sizeof(metadata->bitsPerSample), 1, file);
            if (tiffEndianness == 0x4949) {
                metadata->bitsPerSample = __builtin_bswap16(metadata->bitsPerSample);
            }
        } else if (tag == 277) { // SamplesPerPixel
            fread(&metadata->samplesPerPixel, sizeof(metadata->samplesPerPixel), 1, file);
            if (tiffEndianness == 0x4949) {
                metadata->samplesPerPixel = __builtin_bswap16(metadata->samplesPerPixel);
            }
        } else if (tag == 33872) { // ExtraSamples
            fread(&metadata->extraSamples, sizeof(metadata->extraSamples), 1, file);
            if (tiffEndianness == 0x4949) {
                metadata->extraSamples = __builtin_bswap16(metadata->extraSamples);
            }
        } else {
            // Read value or offset based on type and count
            if (type == 4 && count > 4) { // If value is more than 4 bytes, it's an offset
                fread(&valueOffset, sizeof(valueOffset), 1, file);
                fseek(file, valueOffset, SEEK_SET); // Seek to the actual data location

                char *sampleNames[] = {"None", "Unassociated Alpha", "Associated Alpha", "Vignette Mask"};
                for (int j = 0; j < metadata->extraSamples && j < 4; ++j) {
                    metadata->extraSampleNames[j] = strdup(sampleNames[valueOffset - 1]);
                }
            } else {
                fread(&valueOffset, sizeof(valueOffset), 1, file); // Just read the value
            }
        }
    }

    fclose(file);
    *error = 0;
    return metadata;
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    processDirectory(argv[1]);

    return EXIT_SUCCESS;
}
```

### Key Points:
- The function `processDirectory` iterates over a directory to find TIFF files and processes each one.
- `parseTiffFile` reads metadata from the TIFF file, handling endianness and reading relevant tags like `BitsPerSample`, `SamplesPerPixel`, and `ExtraSamples`.
- Memory allocation is carefully managed, with allocations checked for success and memory freed after use to prevent leaks.
- The function handles errors gracefully by setting an error flag and printing appropriate messages without crashing.']

