public class WebsiteCreator
{
    private readonly ILogger<WebsiteCreator> _logger;

    public WebsiteCreator(ILogger<WebsiteCreator> logger)
    {
        _logger = logger;
    }

    public string AddAndStartWebsite(string baseDirectoryPath, string siteName, int targetPlatformVersion)
    {
        try
        {
            // Step 1: Validate the base directory path
            if (string.IsNullOrEmpty(baseDirectoryPath) || !Directory.Exists(baseDirectoryPath))
            {
                _logger.LogError("Base directory path is invalid or does not exist.");
                return null;
            }

            var writePermission = new FileInfo(baseDirectoryPath).Attributes.HasFlag(FileAttributes.ReadOnly);
            if (writePermission)
            {
                _logger.LogError("The base directory is read-only.");
                return null;
            }

            // Step 2: Check for web.config
            string webConfigPath = Path.Combine(baseDirectoryPath, "web.config");
            if (File.Exists(webConfigPath))
            {
                _logger.LogWarning("A web.config file already exists. Skipping project generation to avoid overwriting.");
                return null;
            }

            // Step 3: Determine directory structure based on target platform version
            string framework = GetFramework(targetPlatformVersion);
            string siteDirectoryPath = Path.Combine(baseDirectoryPath, siteName);

            // Step 4: Create a new directory for the site
            if (!Directory.Exists(siteDirectoryPath))
            {
                Directory.CreateDirectory(siteDirectoryPath);
                _logger.LogInformation($"Created directory at {siteDirectoryPath}.");
            }

            // Step 5: Generate ASP.NET Core project structure
            InitializeProjectFiles(siteDirectoryPath, framework);

            // Step 6: Ensure the project can be started with dotnet run
            StartSite(siteDirectoryPath);

            return siteDirectoryPath;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while adding and starting the website.");
            return null;
        }
    }

    private string GetFramework(int targetPlatformVersion)
    {
        // Example logic for determining framework based on version
        if (targetPlatformVersion >= 5) return ".NET 5.0";
        else if (targetPlatformVersion == 3) return ".NET Core 3.1";
        else return "ASP.NET Core 2.1"; // Fallback option
    }

    private void InitializeProjectFiles(string siteDirectoryPath, string framework)
    {
        string programCs = $@"
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Hosting;

namespace {siteDirectoryPath}
{{
    public class Program
    {{
        public static void Main(string[] args) => CreateHostBuilder(args).Build().Run();

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                    webBuilder.UseStartup<Startup>());
    }}
}}";

        string startupCs = $@"
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;

namespace {siteDirectoryPath}
{{
    public class Startup
    {{
        public void ConfigureServices(IServiceCollection services) {{ }}

        public void Configure(IApplicationBuilder app)
        {{
            app.Run(async (context) => await context.Response.WriteAsync(""Hello, World!""));
        }}
    }}
}}";

        string appSettingsJson = "{ \"Logging\": { \"LogLevel\": { \"Default\": \"Information\" } } }";

        File.WriteAllText(Path.Combine(siteDirectoryPath, "Program.cs"), programCs);
        File.WriteAllText(Path.Combine(siteDirectoryPath, "Startup.cs"), startupCs);
        File.WriteAllText(Path.Combine(siteDirectoryPath, "appsettings.json"), appSettingsJson);

        _logger.LogInformation("Project files initialized.");
    }

    private void StartSite(string siteDirectoryPath)
    {
        try
        {
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName = "dotnet",
                Arguments = "run",
                WorkingDirectory = siteDirectoryPath,
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true
            });

            _logger.LogInformation("Site started successfully.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to start the site.");
            throw; // Rethrow to handle in calling function if necessary.
        }
    }
}
