import java.io.*;
import java.util.HashMap;
import java.util.Map;

public class CommandExecutor {

    private static final Map<String, String> commandCache = new HashMap<>();

    public static void executeCommand(String fileName, String command) {
        if (deleteFileIfExists(fileName)) {
            System.out.println("File " + fileName + " deleted successfully.");
        }

        String cachedResult = commandCache.get(command);
        if (cachedResult != null) {
            sendToAngularJS(cachedResult, true);
            return;
        }

        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
            BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

            String line;
            StringBuilder output = new StringBuilder();
            while ((line = stdInput.readLine()) != null) {
                output.append(line).append("\n");
            }
            String errorOutput = "";
            while ((line = stdError.readLine()) != null) {
                errorOutput += line + "\n";
            }

            int exitVal = process.waitFor();
            logCommandExecution(command, exitVal, output.toString(), errorOutput);

            if (exitVal == 0) {
                commandCache.put(command, output.toString());
                sendToAngularJS(output.toString(), false);
            } else {
                sendToAngularJS("Error: " + errorOutput, true);
            }
        } catch (IOException | InterruptedException e) {
            logCommandExecution(command, -1, "", e.getMessage());
            sendToAngularJS("Exception occurred: " + e.getMessage(), true);
        }
    }

    private static boolean deleteFileIfExists(String fileName) {
        File file = new File(fileName);
        return file.exists() && file.delete();
    }

    private static void logCommandExecution(String command, int exitVal, String output, String errorOutput) {
        // Log start time, duration, and outcome
        System.out.println("Command: " + command);
        System.out.println("Exit Value: " + exitVal);
        System.out.println("Output: " + output);
        System.out.println("Error Output: " + errorOutput);
    }

    private static void sendToAngularJS(String message, boolean isError) {
        // Simulate sending a message to AngularJS
        System.out.println("Sending to AngularJS: " + (isError ? "Error" : "Success") + " - " + message);
    }

    public static void refreshDialogFields(String[] fieldNames) {
        // Example of refreshing specific dialog fields in an AngularJS application
        for (String fieldName : fieldNames) {
            if (fieldName.equals("targetField")) { // Replace with actual condition
                sendToAngularJS(fieldName, false);
            }
        }
    }

    public static void main(String[] args) {
        executeCommand("test.txt", "echo Hello World");
        refreshDialogFields(new String[]{"field1", "targetField"});
    }
}
```

