typedef struct CacheNode {
    char* userId;
    struct CacheNode* next;
} CacheNode;

CacheNode* cache = NULL;  // Simple LRU Cache
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;

// Simulated external service validation function.
int validate_with_external_service(const JWTClaims* claims) {
    // Mock the behavior of an external token validation service call.
    // This would typically involve network operations, handling retries and timeouts.

    return 1;  // Assume successful validation for demonstration purposes.
}

// Function to check cache presence
int is_user_in_cache(const char* userId) {
    CacheNode* current = cache;
    while (current != NULL) {
        if (strcmp(current->userId, userId) == 0) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

// Function to update the LRU Cache
void update_cache(const char* userId) {
    pthread_mutex_lock(&cacheMutex);

    // Check if already in cache
    CacheNode *current, *prev = NULL;
    for (current = cache; current != NULL; prev = current, current = current->next) {
        if (strcmp(current->userId, userId) == 0) {
            break;
        }
    }

    if (current == NULL) {  // Not found in cache
        CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
        newNode->userId = strdup(userId);
        newNode->next = cache;
        cache = newNode;

        // Simulate a fixed size cache by removing the last element.
        if (prev == NULL) {
            current = cache->next;
            free(cache->userId);
            free(cache);
            cache = current;
        }
    } else if (current != cache && prev != NULL) {  // Move to front
        prev->next = current->next;
        current->next = cache;
        cache = current;
    }

    pthread_mutex_unlock(&cacheMutex);
}

// Function to parse and validate JWT claims.
int is_jwt_valid(const char* jwt, time_t currentTime) {
    if (!jwt || strlen(jwt) == 0) return 0;

    // Mocked: Parse the JWT string into JWTClaims
