public class UserProcessor
{
    private readonly string _directoryPath;
    private readonly int _maxProfiles;

    public UserProcessor(string directoryPath, int maxProfiles)
    {
        _directoryPath = directoryPath;
        _maxProfiles = maxProfiles;
    }

    public void ProcessUserProfiles()
    {
        var files = Directory.GetFiles(_directoryPath, "user_data_*.bin");

        var processingTasks = new List<Task>();
        using (var semaphore = new SemaphoreSlim(Environment.ProcessorCount))
        {
            foreach (var file in files)
            {
                processingTasks.Add(ProcessFileAsync(file, semaphore));
            }
        }

        Task.WhenAll(processingTasks).Wait();
    }

