use std::env;
use std::fs::{self, DirEntry};
use std::io;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use log::{info, warn, error};

lazy_static! {
    static ref WS_PATH_LOCK: Mutex<()> = Mutex::new(());
}

fn initialize_workspace() -> io::Result<()> {
    let ws_path = env::var("WS_PATH").map(PathBuf::from).ok();

    if let Some(path) = ws_path {
        if is_valid_project_directory(&path) {
            info!("WS_PATH is set and valid: {}", path.display());
            return Ok(());
        } else {
            error!("Invalid WS_PATH directory structure at: {}", path.display());
            return Err(io::Error::new(io::ErrorKind::Other, "Invalid workspace path"));
        }
    }

    let mut _guard = WS_PATH_LOCK.lock().unwrap();

    if let Some(path) = ws_path {
        info!("Rechecking WS_PATH after acquiring lock: {:?}", path);
    }

    let home_dir = dirs::home_dir().ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "Home directory not found"))?;
    let workspace_dir = home_dir.join("workspace");

    if !workspace_dir.exists() {
        fs::create_dir(&workspace_dir)?;
        env::set_var("WS_PATH", workspace_dir.to_str().unwrap().to_string());
        info!("Created new workspace at: {}", workspace_dir.display());
    } else {
        info!("Workspace directory already exists: {}", workspace_dir.display());
        if let Some(path) = ws_path {
            if path != &workspace_dir {
                warn!(
                    "Existing WS_PATH does not match newly created workspace: {:?} vs {:?}",
                    path, &workspace_dir
                );
            }
        } else {
            env::set_var("WS_PATH", workspace_dir.to_str().unwrap().to_string());
        }
    }

    Ok(())
}

fn is_valid_project_directory(path: &Path) -> bool {
    // Implement the logic to check if the directory matches the expected project structure.
    // This could involve checking for specific files or subdirectories.
    path.read_dir()
        .ok()
        .map_or(false, |entries| entries.filter(|entry| entry.is_ok()).count() > 0)
}

fn cleanup_workspace() -> io::Result<()> {
    if let Some(ws_path) = env::var("WS_PATH").ok().and_then(PathBuf::from) {
        if ws_path.exists() {
            fs::remove_dir_all(&ws_path)?;
            info!("Cleaned up workspace at: {}", ws_path.display());
        }
    }
    Ok(())
}

fn main() -> io::Result<()> {
    env_logger::init();

    match initialize_workspace() {
        Ok(_) => info!("Workspace initialized successfully."),
        Err(e) => error!("Failed to initialize workspace: {:?}", e),
    }

    // Example usage of cleanup function
    if let Err(e) = cleanup_workspace() {
        error!("Failed to clean up workspace: {:?}", e);
    }

    Ok(())
}
```

