        node->data.RNTI = rand() & 0xFFFF;          // Simulated RNTI, adjust as needed
        node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2);
        node->next = NULL;

        *current = node;
        current = &node->next;
    }

    return head;
}

// Free the linked list
void free_linked_list(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

// Update CRCFLAG in array for a given range of RX_UE_INFORMATION_TAG values
void update_crcflags(NFAPI_CRC_INDICATION_PDU_T* array, size_t n, uint32_t start_tag, uint32_t end_tag) {
    if (!array) return;

    for (size_t i = 0; i < n; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG >= start_tag && array[i].RX_UE_INFORMATION_TAG <= end_tag) {
            array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = !array[i].CRC_INDICATION_REL8_TAG.CRCFLAG;
        }
    }
}

// Update CRCFLAG in linked list for a given range of RX_UE_INFORMATION_TAG values
void update_crcflags_in_list(ListNode* head, uint32_t start_tag, uint32_t end_tag) {
    if (!head) return;

    ListNode* current = head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG >= start_tag && current->data.RX_UE_INFORMATION_TAG <= end_tag) {
            current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = !current->data.CRC_INDICATION_REL8_TAG.CRCFLAG;
        }
        current = current->next;
    }
}

int main() {
    // Example usage
    size_t n = 1000;  // Adjust as needed
    NFAPI_CRC_INDICATION_PDU_T* array = initialize_array(n);
    if (!array) return EXIT_FAILURE;

    update_crcflags(array, n, 100, 200);  // Example range

    free_array(array, n);

    ListNode* list = initialize_linked_list(n);
    if (!list) return EXIT_FAILURE;

    update_crcflags_in_list(list, 100, 200);  // Example range

    free_linked_list(list);

    return EXIT_SUCCESS;
}
