} TX_CELL_CONFIG;

// Global variables and synchronization primitives
TX_CELL_CONFIG* txCellConfigs = NULL;
size_t configCount = 0;
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;

// Function prototypes
void initConfigManager();
void cleanupConfigManager();
int addConfig(TX_CELL_CONFIG newConfig);
int removeConfig(size_t index);
int validateConfig(const TX_CELL_CONFIG* config);
TX_CELL_CONFIG* getConfig(size_t index);

