    free(txCellConfigs);
    // Close and clean up LevelDB or other caching library here
}

// Add a new configuration to the array
int addConfig(TX_CELL_CONFIG newConfig) {
    if (!validateConfig(&newConfig)) return -1;

    pthread_rwlock_wrlock(&rwlock);

    TX_CELL_CONFIG* temp = realloc(txCellConfigs, (configCount + 1) * sizeof(TX_CELL_CONFIG));
    if (!temp) {
        pthread_rwlock_unlock(&rwlock);
        return -1;
    }

    txCellConfigs = temp;
    txCellConfigs[configCount++] = newConfig;

    // Update cache with the new configuration

    pthread_rwlock_unlock(&rwlock);
    return 0;
}

// Remove a configuration from the array
int removeConfig(size_t index) {
    if (index >= configCount) return -1;

    pthread_rwlock_wrlock(&rwlock);

    memmove(&txCellConfigs[index], &txCellConfigs[index + 1], (configCount - index - 1) * sizeof(TX_CELL_CONFIG));
    configCount--;

    TX_CELL_CONFIG* temp = realloc(txCellConfigs, configCount * sizeof(TX_CELL_CONFIG));
    if (!temp && configCount > 0) {
        pthread_rwlock_unlock(&rwlock);
        return -1;
    }

    txCellConfigs = temp;

    // Update cache to remove the configuration

    pthread_rwlock_unlock(&rwlock);
    return 0;
}

// Validate a configuration for compatibility
int validateConfig(const TX_CELL_CONFIG* config) {
    // Implement validation logic here
    if (config->phy_params.modulation_scheme < 1 || 
        config->phy_params.antenna_config < 1 ||
        config->phy_params.power_level <= 0.0f) {
        return 0;
    }
    return 1;
}

// Get a configuration by index
TX_CELL_CONFIG* getConfig(size_t index) {
    if (index >= configCount) return NULL;

    pthread_rwlock_rdlock(&rwlock);
    TX_CELL_CONFIG* config = &txCellConfigs[index];
    // Check cache for the configuration

    pthread_rwlock_unlock(&rwlock);
    return config;
}

// Serialization and deserialization functions
int serializeConfigurations(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_rwlock_rdlock(&rwlock);

    fwrite(&configCount, sizeof(size_t), 1, file);
    fwrite(txCellConfigs, sizeof(TX_CELL_CONFIG), configCount, file);

    fclose(file);
    pthread_rwlock_unlock(&rwlock);
    return 0;
}

int deserializeConfigurations(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t newCount;
    fread(&newCount, sizeof(size_t), 1, file);

    TX_CELL_CONFIG* temp = malloc(newCount * sizeof(TX_CELL_CONFIG));
    if (!temp) {
        fclose(file);
        return -1;
    }

    fread(temp, sizeof(TX_CELL_CONFIG), newCount, file);
    fclose(file);

    pthread_rwlock_wrlock(&rwlock);

    free(txCellConfigs);
    txCellConfigs = temp;
    configCount = newCount;

    // Update cache with the deserialized configurations

    pthread_rwlock_unlock(&rwlock);
    return 0;
}

// Main function to demonstrate usage
int main() {
    initConfigManager();

    TX_CELL_CONFIG config1 = {{1, 2, 30.5}};
    addConfig(config1);

    serializeConfigurations("config_backup.bin");

    cleanupConfigManager();
    return 0;
}
