void initializeMemoryPool(MemoryPool *pool, size_t blockSize, size_t initialSize) {
    pool->blockSize = blockSize;
    pool->freeCount = initialSize;
    pool->freeList = malloc(initialSize * blockSize);
}

void* allocateFromPool(MemoryPool *pool) {
    if (pool->freeCount == 0) {
        return NULL; // Pool exhausted
    }
    void *ptr = pool->freeList;
    pool->freeList += pool->blockSize;
    --pool->freeCount;
    return ptr;
}

void freeToPool(MemoryPool *pool, void *ptr, size_t count) {
    if (count == 0 || pool->freeCount + count > initialMemoryPoolSize / pool->blockSize) {
        // Exceeds the capacity of the pool
        return;
    }
    pool->freeList = ptr - count * pool->blockSize;
    pool->freeCount += count;
}

