- **Concurrency Control**: Uses mutexes and semaphores to handle task assignment safely across multiple threads.
- **Error Handling & Logging**: Basic error checks are included; extend with logging for robustness in production environments.
- **Resource Management**: Allocates and deallocates memory efficiently, reducing fragmentation risk by using a single pool reallocation strategy.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_TASKS 1024
#define TASK_PAYLOAD_SIZE 256
#define METADATA_SIZE 64
#define LOG_INTERVAL_SEC 10

typedef struct {
    char payload[TASK_PAYLOAD_SIZE];
    char metadata[METADATA_SIZE];
    int priority;
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    size_t count;
    pthread_mutex_t lock;
    double task_rate_limit; // tasks per second
    time_t last_log_time;
    int processed_count;
    double total_latency;
    int error_count;
} TaskQueue;

TaskQueue queue = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void align_and_pad(char *data, size_t data_len) {
    // Ensure payload is aligned and padded according to ISO/IEC 23091
    size_t padding = (sizeof(Task) - data_len) % sizeof(long);
    memset(data + data_len, 0, padding);
}

int add_task(const char* payload, const char* metadata, int priority) {
    pthread_mutex_lock(&queue.lock);

    if (queue.count >= MAX_TASKS) {
        printf("Queue is full.\n");
        pthread_mutex_unlock(&queue.lock);
        return -1;
    }

    Task *task = &queue.tasks[queue.count++];
    strncpy(task->payload, payload, TASK_PAYLOAD_SIZE);
    align_and_pad((char*)task->payload, strlen(payload));

    strncpy(task->metadata, metadata, METADATA_SIZE);
    task->priority = priority;

    pthread_mutex_unlock(&queue.lock);
    return 0;
}

void* process_tasks(void *arg) {
    while (1) {
        pthread_mutex_lock(&queue.lock);

        if (queue.count == 0) {
            pthread_mutex_unlock(&queue.lock);
            continue; // No tasks to process
        }

        Task task = queue.tasks[0];
        memmove(queue.tasks, queue.tasks + 1, sizeof(Task) * (--queue.count));

        pthread_mutex_unlock(&queue.lock);

        // Simulate processing
        time_t start_time = time(NULL);
        sleep(1); // Example delay for processing a task
        double latency = difftime(time(NULL), start_time);

        pthread_mutex_lock(&queue.lock);
        queue.processed_count++;
        queue.total_latency += latency;
        if (latency > 2.0) { // Simulated error condition
            queue.error_count++;
        }
        pthread_mutex_unlock(&queue.lock);

        if ((time(NULL) - queue.last_log_time) >= LOG_INTERVAL_SEC) {
            double tasks_per_sec = queue.processed_count / LOG_INTERVAL_SEC;
            double avg_latency = queue.total_latency / queue.processed_count;

            printf("Tasks processed/sec: %.2f, Avg latency: %.2fs, Errors: %d\n",
                   tasks_per_sec, avg_latency, queue.error_count);

            pthread_mutex_lock(&queue.lock);
            queue.last_log_time = time(NULL);
            queue.processed_count = 0;
            queue.total_latency = 0.0;
            pthread_mutex_unlock(&queue.lock);
        }
    }
}

void set_rate_limit(double tasks_per_second) {
    pthread_mutex_lock(&queue.lock);
    queue.task_rate_limit = tasks_per_second;
    pthread_mutex_unlock(&queue.lock);
}

int main() {
    pthread_t worker_thread;
    if (pthread_create(&worker_thread, NULL, process_tasks, NULL)) {
        perror("Failed to create thread");
        return 1;
    }

    // Simulate adding tasks
    for (int i = 0; i < MAX_TASKS * 2; ++i) {
        char payload[TASK_PAYLOAD_SIZE] = "example";
        char metadata[METADATA_SIZE] = "metadata";
        add_task(payload, metadata, i % 10);
        if (i % 100 == 0) sleep(1); // Simulate delay
    }

    set_rate_limit(50.0);

    pthread_join(worker_thread, NULL);
    return 0;
}
