#define MAX_RECORDS 1024

typedef struct {
    int value;
} record;

void initialize_crypto_library() {
    const EVP_CIPHER *aes_cipher = EVP_aes_256_cbc();
    const EVP_CIPHER *camellia_cipher = EVP_camellia_256_cbc();

    if (EVP_add_cipher(aes_cipher) == 0 || EVP_add_cipher(camellia_cipher) == 0) {
        fprintf(stderr, "Failed to add ciphers.\n");
        exit(EXIT_FAILURE);
    }

    const EVP_MD *md5_digest = EVP_md5();
    const EVP_MD *sha1_digest = EVP_sha1();

    if (EVP_add_digest(md5_digest) == 0 || EVP_add_digest(sha1_digest) == 0) {
        fprintf(stderr, "Failed to add digests.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    if (!RAND_load_file("/dev/urandom", 32)) {
        fprintf(stderr, "Failed to seed RNG.\n");
        exit(EXIT_FAILURE);
    }
}

void handle_memory_allocation(record **records, size_t num_records) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Exceeded maximum number of records.\n");
        exit(EXIT_FAILURE);
    }

    *records = malloc(num_records * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }
}

void ensure_unique_values(record *records, size_t num_records, int min_value, int max_value) {
    int values[max_value - min_value + 1];
    memset(values, 0, sizeof(values));

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            if (!RAND_bytes((unsigned char *)&value, sizeof(value))) {
                fprintf(stderr, "Failed to generate random number.\n");
                exit(EXIT_FAILURE);
            }
            value = value % (max_value - min_value + 1) + min_value;

        } while (values[value - min_value]);

        records[i].value = value;
        values[value - min_value] = 1;
    }
}

void setup_records() {
    size_t num_records = 256; // Example number of records
    record *records = NULL;

    handle_memory_allocation(&records, num_records);
    ensure_unique_values(records, num_records, 1, MAX_RECORDS);

    free(records);
}

int main() {
    initialize_crypto_library();
    setup_records();

    return 0;
}
