#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000000 // Example system limit

typedef struct {
    int value;
} record;

// Function prototypes for helper functions
void cleanup(long* offsets, int* keys, record* records);

record* allocate_data(int offset_size, int num_records, unsigned long user_seed) {
    if (offset_size <= 0 || num_records <= 0 ||
        offset_size > MAX_SIZE || num_records > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds system-defined limits.\n");
        return NULL;
    }

    // Seed for reproducibility
    srand(user_seed);

    long* offsets = (long*)calloc(offset_size, sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        cleanup(offsets, keys, NULL);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize offsets with random values
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = rand();
    }

    // Generate unique keys
    int key = 1;
    for (int i = 0; i < num_records; ++i) {
        keys[i] = key++;
    }

    // Initialize records with random values in a specific range, e.g., [10, 100]
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 91 + 10;
    }

    return records;
}

void cleanup(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
```

