#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CRF_FLAG 0xFF
#define MIN_CRF_FLAG 0x01

typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_pdu(CRCList* list, uint16_t rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    CRC_INDICATION_REL8_TAG tag;
    srand((unsigned int)time(NULL));
    tag.CRCFLAG = (rand() % (MAX_CRF_FLAG - MIN_CRF_FLAG + 1)) + MIN_CRF_FLAG;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    RX_UE_INFORMATION_TAG rxInfoTag = {rnti, tag};
    NFAPI_CRC_INDICATION_PDU_T pdu = {rxInfoTag};

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void filter_and_log_crc_pdus(CRCList* list, uint16_t min_rnti, uint16_t max_rnti) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.rxUeInformationTag.RNTI >= min_rnti &&
            current->data.rxUeInformationTag.RNTI <= max_rnti) {

            printf("RNTI: %u, CRCFLAG: %u\n",
                   current->data.rxUeInformationTag.RNTI,
                   current->data.rxUeInformationTag.CRC_INDICATION_REL8_TAG.CRCFLAG);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    CRCList* list = create_crc_list();
    if (!list) {
        fprintf(stderr, "Failed to initialize CRC list.\n");
        return -1;
    }

    add_crc_pdu(list, 1000);
    add_crc_pdu(list, 2000);

    printf("Filtered PDU Entries:\n");
    filter_and_log_crc_pdus(list, 500, 2500);

    destroy_crc_list(list);
    return 0;
}
```

