#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int unique_id;
    unsigned char crcFlag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU;

// Global variables for the linked list and its management
NFAPI_CRC_INDICATION_PDU* head = NULL;
pthread_mutex_t lock;
int max_unique_id = 0;

// Function to create a new node with random crcFlag
NFAPI_CRC_INDICATION_PDU* create_node() {
    NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    static int next_unique_id = 1;
    pthread_mutex_lock(&lock);
    new_node->unique_id = next_unique_id++;
    pthread_mutex_unlock(&lock);

    srand(time(NULL) ^ (unsigned)getpid());
    new_node->crcFlag = rand() % 256; // Random crcFlag between 0 and 255
    new_node->next = NULL;

    return new_node;
}

// Function to add a node to the linked list in a thread-safe manner
void add_to_list(NFAPI_CRC_INDICATION_PDU* new_node) {
    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU* temp = head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

// Function to find the maximum unique_id in the linked list
int get_max_unique_id() {
    int max_id = 0;
    NFAPI_CRC_INDICATION_PDU* current = head;

    while (current != NULL) {
        if (current->unique_id > max_id) {
            max_id = current->unique_id;
        }
        current = current->next;
    }

    return max_id;
}

// Function to print the linked list (for debugging purposes)
void print_list() {
    NFAPI_CRC_INDICATION_PDU* current = head;

    while (current != NULL) {
        printf("Unique ID: %d, CRC Flag: %d\n", current->unique_id, current->crcFlag);
        current = current->next;
    }
}

// Function to free the linked list
void free_list() {
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU* next_node = current->next;
        free(current);
        current = next_node;
    }
}

int main() {
    pthread_mutex_init(&lock, NULL);

    // Simulate adding nodes to the list
    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU* new_node = create_node();
        add_to_list(new_node);
    }

    printf("Maximum Unique ID: %d\n", get_max_unique_id());

    // Free the linked list
    free_list();

    pthread_mutex_destroy(&lock);

    return 0;
}
```

### Design Document

#### Overview
The program implements a dynamically growing linked list of `NFAPI_CRC_INDICATION_PDU_T` structures, designed to handle up to 10,000 entries efficiently. The linked list supports concurrent read operations and is thread-safe for write operations.

#### Key Components

1. **Data Structure**: 
   - Each node in the linked list contains a `unique_id`, a `crcFlag`, and a pointer to the next node.
   - The `unique_id` starts at 1 and increments sequentially with each new node.

2. **Thread Safety**:
   - A mutex (`pthread_mutex_t lock`) is used to ensure thread safety during write operations (node creation and addition).
   - Read operations are inherently safe as they do not modify the list structure.

3. **Random `crcFlag` Generation**:
   - The `crcFlag` is generated using a random number between 0 and 255.
   - The seed for randomness is derived from the current time combined with the process ID to ensure variability across different runs.

4. **Efficiency Considerations**:
   - Memory allocation is handled carefully, checking for failures and exiting gracefully if memory cannot be allocated.
   - The program minimizes memory fragmentation by allocating nodes one at a time and freeing them in sequence.
   - The `get_max_unique_id` function iterates through the list once to find the maximum ID, ensuring O(n) complexity.

5. **Robustness**:
   - The program includes error handling for memory allocation failures.
   - Mutex initialization and destruction are handled properly to avoid resource leaks.

6. **Performance**:
   - The linked list allows efficient appending of nodes with minimal overhead.
   - Sequential `unique_id` assignment ensures easy tracking and retrieval of the maximum ID.

7. **Scalability**:
   - The design supports scaling up to 10,000 entries with minimal performance degradation due to its linear complexity in operations.

8. **Maintenance**:
   - Functions are modular, allowing for easy maintenance and updates.
   - Debugging is facilitated by a `print_list` function that can be used to verify the list's state during development.

This design balances ease of use, performance, and robustness, ensuring efficient management of large datasets with concurrent access.']

