import stdlib.h

#define INITIAL_PACKET_ARRAY_SIZE 100
#define MAX_PACKETS 10000

typedef struct {
    uint32_t packet_id;
    char *header;
    size_t header_length;
    char *payload;
    size_t payload_length;
    uint16_t metadata; // Placeholder for additional metadata fields
} NetworkPacket;

typedef struct {
    NetworkPacket *packets;
    size_t capacity;
    size_t count;
} PacketArray;

void log_info(const char *message, ...);

// Function to calculate alignment padding based on IEEE 802.17 standard
size_t calculate_padding(size_t current_length) {
    const size_t alignment = 8; // Example alignment requirement (modify as needed)
    return (alignment - (current_length % alignment)) % alignment;
}

// Thread-safe dynamic array initialization and population function
PacketArray* initialize_packet_array() {
    PacketArray *pa = malloc(sizeof(PacketArray));
    if (!pa) {
        log_info("Memory allocation failed for packet array");
        return NULL;
    }

    pa->capacity = INITIAL_PACKET_ARRAY_SIZE;
    pa->count = 0;
    pa->packets = calloc(pa->capacity, sizeof(NetworkPacket));
    if (!pa->packets) {
        free(pa);
        log_info("Memory allocation failed for packets array");
        return NULL;
    }

    return pa;
}

int add_packet(PacketArray *pa, const char *header, size_t header_length,
               const char *payload, size_t payload_length) {
    if (pa->count >= pa->capacity) {
        size_t new_capacity = pa->capacity * 2;
        NetworkPacket *new_packets = realloc(pa->packets, new_capacity * sizeof(NetworkPacket));

        if (!new_packets) {
            log_info("Memory allocation failed during resize");
            return -1; // Memory allocation error
        }

        pa->packets = new_packets;
        pa->capacity = new_capacity;
    }

    NetworkPacket *packet = &pa->packets[pa->count++];
    packet->header = malloc(header_length + calculate_padding(header_length));

    if (!packet->header) {
        log_info("Memory allocation failed for header");
        return -1; // Memory allocation error
    }

    memcpy(packet->header, header, header_length);
    packet->header_length = header_length;

    size_t payload_aligned_length = payload_length + calculate_padding(payload_length);
    packet->payload = malloc(payload_aligned_length);

    if (!packet->payload) {
        free(packet->header);
        log_info("Memory allocation failed for payload");
        return -1; // Memory allocation error
    }

    memcpy(packet->payload, payload, payload_length);
    packet->payload_length = payload_length;
    packet->metadata = 0; // Initialize metadata as needed

    packet->packet_id = pa->count;

    log_info("Packet %u added with header size %zu and payload size %zu", 
             packet->packet_id, packet->header_length, packet->payload_length);

    return 0;
}

void cleanup_packet_array(PacketArray *pa) {
    for (size_t i = 0; i < pa->count; ++i) {
        free(pa->packets[i].header);
        free(pa->packets[i].payload);
    }
    free(pa->packets);
    free(pa);
}

// Logging function implementation
void log_info(const char *message, ...) {
    va_list args;
    va_start(args, message);
    vprintf(message, args);
    printf("\n");
    va_end(args);
}
