        config_list[i].radio_resource_parameters.cell_specific_reference_signal_power =
            fetch_real_time_data();

        pthread_mutex_unlock(&config_mutex);

        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate and log time taken for each initialization
        double elapsed_ns = (end.tv_sec - start.tv_sec) * 1e9 + (end.tv_nsec - start.tv_nsec);
        printf("Time to initialize connection %d: %.2f ns\n", i + 1, elapsed_ns);

    }

    *initialized_count = num_connections;
    return config_list;
}

// Cleanup function
void free_network_interface_configuration(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T* config_list) {
    if (config_list != NULL) {
        free(config_list);
    }
}
```

