#include <errno.h>

#define BUFFER_SIZE 4096

typedef struct {
    char *file_path;
    char *output_file;
    int verbose;
    int apply_cipher;
    pthread_mutex_t lock;
} FileContext;

void display_usage() {
    printf("Usage: prog [options] input_files\n"
           "Options:\n"
           "  -h, --help      Display this help message.\n"
           "  --manpage       Output comprehensive documentation.\n"
           "  -cs             Apply a character substitution cipher.\n"
           "  -o output_file  Specify an output file.\n"
           "  -v              Enable verbose mode.\n");
}

void display_manpage() {
    printf("Comprehensive Documentation:\n"
           "This program processes input files with various options...\n");
}

void log_message(const char *level, const char *message) {
    FILE *log_file = fopen("program.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", level, message);
        fclose(log_file);
    }
}

void process_line(char *line, FileContext *ctx, int is_compressed) {
    // Apply character substitution cipher if enabled
    if (ctx->apply_cipher) {
        for (int i = 0; line[i]; i++) {
            line[i] = (line[i] + 1) % 256;
        }
    }

    // Output processed line to file or stdout
    FILE *output_file = ctx->output_file ? fopen(ctx->output_file, "a") : stdout;
    if (output_file != NULL) {
        fprintf(output_file, "%s", line);
        fclose(output_file);
    } else {
        log_message("ERROR", "Failed to open output file.");
    }
}

void process_file(const char *file_path, FileContext *ctx) {
    FILE *input_file = fopen(file_path, "rb");
    if (!input_file) {
        log_message("ERROR", strerror(errno));
        return;
    }

    char buffer[BUFFER_SIZE];
    size_t bytes_read;
    int lines_processed = 0;

    while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, input_file)) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (buffer[i] == '\n') {
                buffer[i] = '\0';
                process_line(&buffer[lines_processed], ctx, 0);
                lines_processed++;
                log_message(ctx->verbose ? "INFO" : "DEBUG", "Processed a line.");
            }
        }
        lines_processed += bytes_read;
    }

    fclose(input_file);

    if (ctx->output_file) {
        FILE *count_file = fopen("line_count.txt", "a");
        if (count_file != NULL) {
            fprintf(count_file, "%s: %zu lines\n", file_path, lines_processed);
            fclose(count_file);
        }
    }

    log_message("INFO", "File processing completed.");
}

void* process_wrapper(void *arg) {
    FileContext *ctx = (FileContext *)arg;
    pthread_mutex_lock(&ctx->lock);
    process_file(ctx->file_path, ctx);
    pthread_mutex_unlock(&ctx->lock);
    return NULL;
}

int main(int argc, char *argv[]) {
    int opt;
    char *output_file = NULL;
    int verbose = 0, apply_cipher = 0;

    while ((opt = getopt(argc, argv, "hvo:cs")) != -1) {
        switch (opt) {
            case 'h':
                display_usage();
                return 0;
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'c':
                apply_cipher = 1;
                break;
            case 's':
                // Placeholder for future implementation
                break;
            default:
                display_usage();
                return 1;
        }
    }

    if (strcmp(argv[optind], "--manpage") == 0) {
        display_manpage();
        return 0;
    }

    int num_files = argc - optind;
    pthread_t threads[num_files];
    FileContext contexts[num_files];

    for (int i = 0; i < num_files; ++i) {
        contexts[i].file_path = argv[optind + i];
        contexts[i].output_file = output_file;
        contexts[i].verbose = verbose;
        contexts[i].apply_cipher = apply_cipher;
        pthread_mutex_init(&contexts[i].lock, NULL);

        if (pthread_create(&threads[i], NULL, process_wrapper, &contexts[i])) {
            log_message("ERROR", "Failed to create thread.");
            return 1;
        }
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < num_files; ++i) {
        pthread_mutex_destroy(&contexts[i].lock);
    }

    return 0;
}
```

