#include <sys/stat.h>
#include <dirent.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 1000
#define BUFFER_SIZE 1024 * 64

typedef struct {
    uint32_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG[16];
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char filename[256];
    unsigned char md5hash[MD5_DIGEST_LENGTH];
} FileHashEntry;

// Database simulation
FileHashEntry db[MAX_FILES];

// Logging function (stub for external logging API)
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// MD5 hashing utility
int calculate_md5(FILE *file, unsigned char *result) {
    unsigned char data[BUFFER_SIZE];
    size_t bytesRead;
    MD5_CTX mdContext;

    if (!MD5_Init(&mdContext)) return -1;

    while ((bytesRead = fread(data, 1, BUFFER_SIZE, file))) {
        if (!MD5_Update(&mdContext, data, bytesRead))
            return -1;
    }

    if (!MD5_Final(result, &mdContext))
        return -1;

    fclose(file);
    return 0;
}

// Thread function to process files
void* process_files(void *arg) {
    char *dir = (char *)arg;
    DIR *d;
    struct dirent *dir_entry;
    int db_index = 0;

    if ((d = opendir(dir)) == NULL) {
        log_error("Failed to open directory");
        pthread_exit(NULL);
    }

    while ((dir_entry = readdir(d)) != NULL && db_index < MAX_FILES) {
        if (strcmp(dir_entry->d_name, ".") == 0 || strcmp(dir_entry->d_name, "..") == 0)
            continue;

        FILE *file = fopen(dir_entry->d_name, "rb");
        if (!file) {
            log_error("Failed to open file");
            continue;
        }

        unsigned char md5hash[MD5_DIGEST_LENGTH];
        if (calculate_md5(file, md5hash) == 0) {
            strncpy(db[db_index].filename, dir_entry->d_name, sizeof(db[db_index].filename));
            memcpy(db[db_index].md5hash, md5hash, MD5_DIGEST_LENGTH);
            db_index++;
        }
    }

    closedir(d);
    pthread_exit(NULL);
}

// Utility to generate NFAPI_CRC_INDICATION_PDU_T structures
void generate_nfa_structs(NFAPI_CRC_INDICATION_PDU_T *nfa_array, int n) {
    for (int i = 0; i < n; ++i) {
        nfa_array[i].RNTI = rand() % 65536;
        memset(nfa_array[i].RX_UE_INFORMATION_TAG, rand() % 256, sizeof(nfa_array[i].RX_UE_INFORMATION_TAG));
        nfa_array[i].CRC_INDICATION_REL8_TAG = (rand() % 2 == 0) ? 1 : 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int nfa_count = 10; // Example count
    NFAPI_CRC_INDICATION_PDU_T *nfas = malloc(nfa_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfas) {
        log_error("Failed to allocate memory for NFAs");
        return EXIT_FAILURE;
    }

    generate_nfa_structs(nfas, nfa_count);
    free(nfas);

    pthread_t threads[2];
    int rc;

    // Processing files in directory
    rc = pthread_create(&threads[0], NULL, process_files, (void *)argv[1]);
    if (rc) {
        log_error("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Additional processing or logging can be added here

    rc = pthread_join(threads[0], NULL);
    if (rc) {
        log_error("Failed to join thread");
        return EXIT_FAILURE;
    }

    // Add more threads for larger directories
    return 0;
}
