        // Ensure no two consecutive CRC flags are the same
        int current_crc_flag = rand() % 2;
        while (current_crc_flag == last_crc_flag) {
            current_crc_flag = rand() % 2;
        }
        list[i].crc_flag = current_crc_flag;
        last_crc_flag = current_crc_flag;

        // Check time limit constraint
        if ((time(NULL) - start_time) > TIME_LIMIT_SECONDS) {
            fprintf(stderr, "Time limit exceeded\n");
            free(list);
            return NULL;
        }
    }

