// Define constants for IEEE 802.17 standard alignment.
#define PAYLOAD_ALIGNMENT 4
#define MAX_PACKETS 1024

typedef struct {
    uint32_t header;
    char *payload; // Aligned to PAYLOAD_ALIGNMENT bytes.
    uint64_t metadata;
} NetworkPacket;

typedef struct {
    size_t packet_count;
    size_t total_size;
    NetworkPacket *packets;
} PacketArray;

static pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// Helper function to align memory size.
size_t aligned_size(size_t size, size_t alignment) {
    return (size + alignment - 1) & ~(alignment - 1);
}

int initialize_packet_array(PacketArray *array, size_t packet_count) {
    pthread_mutex_lock(&array_lock);

    if (!array || packet_count > MAX_PACKETS) {
        pthread_mutex_unlock(&array_lock);
        return -1; // Invalid parameters.
    }

    size_t total_payload_size = 0;
    for (size_t i = 0; i < packet_count; ++i) {
        size_t payload_size = /* Fetch dynamic payload size for each packet */;
        if (payload_size == 0) { 
            pthread_mutex_unlock(&array_lock);
            return -1; // Invalid payload size.
        }
        total_payload_size += aligned_size(payload_size, PAYLOAD_ALIGNMENT);
    }

    array->packet_count = packet_count;
    array->total_size = sizeof(NetworkPacket) * packet_count + total_payload_size;

    network_packet* packets = (NetworkPacket *)malloc(array->total_size);
    if (!packets) {
        pthread_mutex_unlock(&array_lock);
        return -2; // Memory allocation failure.
    }

    char *payload_ptr = (char *)(packets + packet_count); // Start after the NetworkPacket array.
    for (size_t i = 0; i < packet_count; ++i) {
        size_t payload_size = /* Fetch dynamic payload size for each packet */;

        packets[i].header = /* Initialize header */;
        packets[i].payload = payload_ptr;
        packets[i].metadata = /* Initialize metadata */;

        payload_ptr += aligned_size(payload_size, PAYLOAD_ALIGNMENT);
    }

    array->packets = packets;
    pthread_mutex_unlock(&array_lock);

    return 0; // Success.
}

void free_packet_array(PacketArray *array) {
    if (!array || !array->packets) return;

