typedef enum {
    L3_TYPE_A,
    L3_TYPE_B,
    // Add more types as needed
} L3_PDU_TYPE;

typedef struct {
    L3_PDU_TYPE type;
    size_t payload_size;
    int error_indicator; // 1 if out-of-sequence, 0 otherwise
} LAYER3_HEADER_T;

typedef struct {
    LAYER3_HEADER_T header;
    void *payload;
} MAC_PDCP_PDU_T;

typedef struct {
    MAC_PDCP_PDU_T **array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PDCP_PDU_Manager;

// Initialize the manager
int init_pdp_manager(PDCP_PDU_Manager *manager) {
    if (!manager) return -1;

    manager->capacity = 10; // Initial capacity, adjust as needed
    manager->count = 0;

    pthread_mutex_init(&manager->mutex, NULL);
    manager->array = (MAC_PDCP_PDU_T **)calloc(manager->capacity, sizeof(MAC_PDCP_PDU_T *));
    if (!manager->array) return -1;

    return 0;
}

// Add a PDU
int add_pdu(PDCP_PDU_Manager *manager, MAC_PDCP_PDU_T *pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        MAC_PDCP_PDU_T **new_array = (MAC_PDCP_PDU_T **)realloc(manager->array, new_capacity * sizeof(MAC_PDCP_PDU_T *));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Remove a PDU by index
int remove_pdu(PDCP_PDU_Manager *manager, size_t index) {
    pthread_mutex_lock(&manager->mutex);

    if (index >= manager->count) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    free(manager->array[index]->payload);
    free(manager->array[index]);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->count--;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Retrieve a PDU by index
MAC_PDCP_PDU_T *get_pdu(PDCP_PDU_Manager *manager, size_t index) {
    if (!manager || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->mutex);
    MAC_PDCP_PDU_T *pdu = manager->array[index];
    pthread_mutex_unlock(&manager->mutex);

    return pdu;
}

// Free all resources
void free_pdp_manager(PDCP_PDU_Manager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]->payload);
        free(manager->array[i]);
    }

    free(manager->array);

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}
```

