void log_error(const char *message);
int random_int(int min, int max);

typedef struct {
    unsigned short CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_array(int count, const char *hostname) {
    if (count <= 0 || count > MAX_STRUCTURES) {
        log_error("Invalid number of structures requested");
        return NULL;
    }

    // DNS resolution with caching
    static struct in_addr cached_dns_result = {0};
    static int dns_cache_valid = 0;

    struct hostent *host_info;
    if (!dns_cache_valid) {
        host_info = gethostbyname(hostname);
        if (host_info == NULL) {
            log_error("DNS resolution failed");
            return NULL;
        }
        memcpy(&cached_dns_result, host_info->h_addr_list[0], sizeof(struct in_addr));
        dns_cache_valid = 1;
    }

    u_char ip_address[4];
    memcpy(ip_address, &cached_dns_result.s_addr, sizeof(ip_address));

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_error("Memory allocation failed");
        return NULL;
    }

    unsigned long last_rnti = 0;
    for (int i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = random_int(1, UINT_MAX);
        do {
            array[i].RNTI = random_int(1, UINT_MAX);
        } while (array[i].RNTI == last_rnti);

        last_rnti = array[i].RNTI;

        // Probabilistic CRCFLAG determination
        array[i].TAG.CRCFLAG = random_int(0, 1) ? 1 : 0;
    }

    return array;
}

void free_nfa_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
