unsigned int hash(int RX_UE_INFORMATION_TAG, int RNTI) {
    return (RX_UE_INFORMATION_TAG * 31 + RNTI) % 10007; // Simple hash function
}

HashTable* create_table() {
    HashTable* table = malloc(sizeof(HashTable));
    table->head = NULL;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

Node* find_node(Node* head, int RX_UE_INFORMATION_TAG, int RNTI) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->data.RNTI == RNTI) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void insert_node(HashTable* table, NFAPI_CRC_INDICATION_PDU_T data) {
    unsigned int index = hash(data.RX_UE_INFORMATION_TAG, data.RNTI);
    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = table->head[index].head;
