    while (fread(&pdu, sizeof(pdu), 1, file)) {
        if (!validate_data(&pdu)) continue;

        pthread_mutex_lock(&table->lock);
        unsigned int index = hash(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
        Node* existing_node = find_node(table->head[index].head, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);

        if (existing_node == NULL) {
            insert_node(table, pdu);
        } else if (existing_node->data.CRCFLAG != pdu.CRCFLAG) {
            log_error("CRCFLAG inconsistency detected for existing entry");
        }
