#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int transmissionPower;
    int bandwidthPartCarrierFrequency;
    int cellSpecificReferenceSignalPower;
} RadioResourceParameters;

typedef struct {
    int rrcConfigurationUpdate;
    int cellID;
    RadioResourceParameters radioResources;
} NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T;

typedef struct ConfigNode {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T config;
    struct ConfigNode* next;
} ConfigNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

ConfigNode* createConfig(int rrcUpdate, int cellID, RadioResourceParameters radioResources) {
    ConfigNode* node = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for new configuration.\n");
        return NULL;
    }
    node->config.rrcConfigurationUpdate = rrcUpdate;
    node->config.cellID = cellID;
    node->config.radioResources = radioResources;
    node->next = NULL;
    return node;
}

void addConfig(ConfigNode** head, int rrcUpdate, int cellID, RadioResourceParameters radioResources) {
    pthread_mutex_lock(&lock);
    ConfigNode* newConfig = createConfig(rrcUpdate, cellID, radioResources);
    if (!newConfig) {
        fprintf(stderr, "Failed to add configuration.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    newConfig->next = *head;
    *head = newConfig;
    printf("Configuration added: RRC Update %d, Cell ID %d\n", rrcUpdate, cellID);
    pthread_mutex_unlock(&lock);
}

void removeConfig(ConfigNode** head, int cellID) {
    pthread_mutex_lock(&lock);
    ConfigNode *current = *head, *prev = NULL;
    while (current != NULL && current->config.cellID != cellID) {
        prev = current;
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Configuration with Cell ID %d not found.\n", cellID);
    } else {
        if (prev == NULL) {
            *head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
        printf("Configuration removed: Cell ID %d\n", cellID);
    }
    pthread_mutex_unlock(&lock);
}

void switchConfig(ConfigNode* head, int targetCellID) {
    pthread_mutex_lock(&lock);
    ConfigNode* current = head;
    while (current != NULL && current->config.cellID != targetCellID) {
        current = current->next;
    }
    if (current == NULL) {
        fprintf(stderr, "Configuration with Cell ID %d not found for switching.\n", targetCellID);
    } else {
        printf("Switched to configuration: Cell ID %d\n", targetCellID);
    }
    pthread_mutex_unlock(&lock);
}

void freeConfigs(ConfigNode* head) {
    ConfigNode* current = head;
    while (current != NULL) {
        ConfigNode* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    ConfigNode* configList = NULL;

    RadioResourceParameters params1 = {20, 3500, 10};
    addConfig(&configList, 1, 1001, params1);

    RadioResourceParameters params2 = {25, 3600, 15};
    addConfig(&configList, 2, 1002, params2);

    switchConfig(configList, 1001);
    removeConfig(&configList, 1001);

    freeConfigs(configList);
    pthread_mutex_destroy(&lock);

    return 0;
}
```

