#include <stdint.h>

// Define the structure as per your requirements.
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    union {
        struct {
            int CRCFLAG; // Example field
        } CRC_INDICATION_REL8_TAG;
    };
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10

// Structure to manage the dynamic list.
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} PDULIST;

void init_pdl(PDULIST *pdl) {
    pdl->capacity = INITIAL_SIZE;
    pdl->count = 0;
    pdl->pdus = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(16, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdl->capacity);
    if (!pdl->pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&pdl->lock, NULL);
}

void resize_pdl(PDULIST *pdl) {
    size_t new_capacity = pdl->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(16, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(new_pdus, pdl->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdl->count);
    free(pdl->pdus);
    pdl->pdus = new_pdus;
    pdl->capacity = new_capacity;
}

void insert_pdu(PDULIST *pdl, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pdl->lock);

    if (pdl->count == pdl->capacity) {
        resize_pdl(pdl);
    }

    pdl->pdus[pdl->count++] = pdu;

    pthread_mutex_unlock(&pdl->lock);
}

void free_pdl(PDULIST *pdl) {
    pthread_mutex_destroy(&pdl->lock);
    if (pdl->pdus) {
        free(pdl->pdus);
        pdl->pdus = NULL;
    }
    pdl->capacity = 0;
    pdl->count = 0;
}

void process_pdu_batch(PDULIST *pdl, NFAPI_CRC_INDICATION_PDU_T *batch, size_t batch_size) {
    for (size_t i = 0; i < batch_size; ++i) {
        // Simulate processing with random CRCFLAG
        batch[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        insert_pdu(pdl, batch[i]);

        // Simulating processing delay
        usleep(100000); // 100 ms per PDU to meet performance constraints
    }
}

int main() {
    PDULIST pdl;
    init_pdl(&pdl);

    size_t num_pdus = 5000; // Example number of PDUs for batch processing
    NFAPI_CRC_INDICATION_PDU_T *batch = (NFAPI_CRC_INDICATION_PDU_T *)aligned_alloc(16, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);

    if (!batch) {
        fprintf(stderr, "Memory allocation failed\n");
        free_pdl(&pdl);
        return EXIT_FAILURE;
    }

    // Simulate batch processing of PDUs
    process_pdu_batch(&pdl, batch, num_pdus);

    // Free dynamically allocated resources
    free(batch);
    free_pdl(&pdl);

    return 0;
}
```

### Key Points:
- **Alignment**: Memory is aligned to 16 bytes using `aligned_alloc` for compatibility with the network stack.
- **Dynamic Resizing**: The list doubles its capacity when needed, optimizing memory usage and minimizing fragmentation.
- **Thread Safety**: A mutex lock ensures thread-safe operations on the dynamic list.
- **Graceful Handling of Failures**: Error handling is implemented for memory allocation failures to prevent crashes.
- **Resource Management**: All dynamically allocated resources are freed appropriately to avoid leaks.']

