typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Assume this is 1 byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_SIZE 10
#define MAX_RNTI 65535

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
    int invalid_rnti_count;
} PDUList;

PDUList* create_pdu_list() {
    PDUList *list = (PDUList*)malloc(sizeof(PDUList));
    list->count = 0;
    list->capacity = INITIAL_SIZE;
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }
    list->invalid_rnti_count = 0;
    return list;
}

void resize_pdu_list(PDUList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdus) {
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
}

int is_valid_rnti(int rnti) {
    return rnti >= 0 && rnti <= MAX_RNTI;
}

void insert_pdu(PDUList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid_rnti(pdu.RNTI)) {
        list->invalid_rnti_count++;
        printf("Invalid RNTI: %d\n", pdu.RNTI);
        return;
    }

    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        resize_pdu_list(list, new_capacity);
    }

    // Insert the PDU
    list->pdus[list->count++] = pdu;
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    srand((unsigned int)time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example range
    pdu->RNTI = rand() % (MAX_RNTI + 1);
    pdu->CRC_INDICATION_REL8_TAG = rand() % 100; // Example range
    pdu->CRCFLAG = rand() & 0x01; // Random CRC flag: 0 or 1
}

void process_pdus(PDUList *list, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        insert_pdu(list, pdu);

#ifdef PREFETCH
        __builtin_prefetch(&(list->pdus[i + 1]));
#endif

#if UNROLL_LOOP == 4
        if ((i + 3) < num_pdus) {
            NFAPI_CRC_INDICATION_PDU_T pdu2, pdu3, pdu4;
            generate_random_pdu(&pdu2);
            generate_random_pdu(&pdu3);
            generate_random_pdu(&pdu4);

            insert_pdu(list, pdu2);
            insert_pdu(list, pdu3);
            insert_pdu(list, pdu4);

#ifdef PREFETCH
            __builtin_prefetch(&(list->pdus[i + 5]));
#endif

            i += 3; // Account for the unrolled loop
        }
#endif
    }
}

void report(PDUList *list) {
    printf("Total PDUs: %zu\n", list->count);
    printf("Invalid RNTI count: %d\n", list->invalid_rnti_count);
    printf("Current capacity: %zu\n", list->capacity);
}

int main() {
    PDUList *list = create_pdu_list();
    if (!list) {
        fprintf(stderr, "Failed to create PDU list.\n");
        return EXIT_FAILURE;
    }

    size_t num_pdus_to_process = 1000; // Example number
    clock_t start_time = clock();

    process_pdus(list, num_pdus_to_process);

    clock_t end_time = clock();
    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;

    printf("Average processing time per PDU: %f seconds\n", time_taken / num_pdus_to_process);
    report(list);

    free(list->pdus);
    free(list);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Dynamic Resizing**: Starts with an initial capacity and doubles when full.
- **Validation**: Checks if `RNTI` is within the valid range; logs and ignores invalid ones.
- **Optimization Techniques**:
  - Loop unrolling for performance.
  - Data prefetching to improve cache efficiency.
- **Diagnostics**: Reports on memory usage, processing time, and insertion success/failure counts.']

