typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

CipherContext* init_cipher(const char *mode, const unsigned char *key, int key_length, int rounds) {
    if (!mode || !key) return NULL;

    CipherContext *cipher_ctx = (CipherContext *)malloc(sizeof(CipherContext));
    if (!cipher_ctx) {
        LOG_ERROR("Memory allocation failed for cipher context");
        return NULL;
    }

    cipher_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx->ctx) {
        LOG_ERROR("Failed to create cipher context");
        free(cipher_ctx);
        return NULL;
    }

    int iv_len = 0, cipher_type = -1;

    if (strcmp(mode, "ECB") == 0) {
        cipher_type = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher_type = EVP_des_ede3(); // Using EDE3 as a fallback for EDE
        if (key_length != 24 && key_length != 16) { // Check for 112-bit or 168-bit keys
            LOG_ERROR("Invalid key length for EDE mode");
            goto cleanup;
        }
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher_type = EVP_des_ede3();
        if (key_length != 24) { // Check for 168-bit key
            LOG_ERROR("Invalid key length for EDE3 mode");
            goto cleanup;
        }
    } else if (strcmp(mode, "CFB") == 0) {
        cipher_type = EVP_des_cfb64(); // Using DES CFB64 as a base
        iv_len = EVP_CIPHER_iv_length(cipher_type);
        if (!RAND_bytes(cipher_ctx->iv, iv_len)) { // Secure IV generation
            LOG_ERROR("IV generation failed");
            goto cleanup;
        }
    } else if (strcmp(mode, "NULL") == 0) {
        cipher_type = NULL; // No encryption
    } else {
        LOG_ERROR("Unsupported encryption mode: %s", mode);
        goto cleanup;
    }

    int result = EVP_CIPHER_CTX_init(cipher_ctx->ctx);
    if (!result || !EVP_EncryptInit_ex(cipher_ctx->ctx, cipher_type, NULL, key, NULL)) {
        LOG_ERROR("Cipher initialization failed for mode: %s", mode);
        goto cleanup;
    }

    // Set rounds for EDE and EDE3
    if (cipher_type == EVP_des_ede3()) {
        result = EVP_CIPHER_CTX_set_key_length(cipher_ctx->ctx, key_length);
        if (!result) {
            LOG_ERROR("Failed to set key length");
            goto cleanup;
        }
    }

    return cipher_ctx;

cleanup:
    free_cipher_context(cipher_ctx);
    return NULL;
}

void free_cipher_context(CipherContext *cipher_ctx) {
    if (cipher_ctx) {
        if (cipher_ctx->ctx) {
            EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        }
        free(cipher_ctx);
    }
}

int main() {
    // Example usage
    const char *mode = "CFB";
    unsigned char key[] = { /* 16, 24 or 8 bytes depending on the mode and key length */ };
    int key_length = sizeof(key);

    CipherContext *ctx = init_cipher(mode, key, key_length, -1);
    if (!ctx) {
        LOG_ERROR("Cipher initialization failed");
        return EXIT_FAILURE;
    }

    // Use ctx for encryption/decryption...

    free_cipher_context(ctx);
    return EXIT_SUCCESS;
}
```

### Key Points:
