#define MAX_TOKENS 100

typedef struct {
    char rnti[16];
    int crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    char rx_ue_information_tag[256];
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    char oauth_access_token[512];
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    int count;
    pthread_mutex_t session_lock;
    char cached_tokens[MAX_TOKENS][512];
    int token_count;
} SessionManager;

void initialize_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus, int n) {
    for (int i = 0; i < n; ++i) {
        snprintf(pdus[i].rnti, sizeof(pdus[i].rnti), "RNTI_%d", rand());
        pdus[i].crc_indication_rel8_tag.crcflag = rand() % 2;
        snprintf(pdus[i].rx_ue_information_tag, sizeof(pdus[i].rx_ue_information_tag), "UE_INFO_TAG_%d", i);
        pthread_mutex_init(&pdus[i].lock, NULL);
    }
}

void retrieve_user_info(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate network API call to get OAuth access token
    snprintf(pdu->oauth_access_token, sizeof(pdu->oauth_access_token), "access_token_%d", rand());
}

int get_cached_token(SessionManager *manager, const char *rnti, char *token) {
    pthread_mutex_lock(&manager->session_lock);
    for (int i = 0; i < manager->token_count; ++i) {
        if (strncmp(manager->cached_tokens[i], rnti, strlen(rnti)) == 0) {
            strncpy(token, manager->cached_tokens[i] + strlen(rnti) + 1, sizeof(token));
            pthread_mutex_unlock(&manager->session_lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&manager->session_lock);
    return 0;
}

void cache_token(SessionManager *manager, const char *rnti, const char *token) {
    pthread_mutex_lock(&manager->session_lock);
    if (manager->token_count < MAX_TOKENS) {
        snprintf(manager->cached_tokens[manager->token_count], sizeof(manager->cached_tokens[0]),
                 "%s|%s", rnti, token);
        manager->token_count++;
    }
    pthread_mutex_unlock(&manager->session_lock);
}

void populate_pdu_with_token(NFAPI_CRC_INDICATION_PDU_T *pdu, SessionManager *manager) {
    char cached_token[512];
    if (get_cached_token(manager, pdu->rnti, cached_token)) {
        strncpy(pdu->oauth_access_token, cached_token, sizeof(pdu->oauth_access_token));
    } else {
        retrieve_user_info(pdu);
        cache_token(manager, pdu->rnti, pdu->oauth_access_token);
    }
}

void *populate_pdu(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    SessionManager *manager = (SessionManager *)malloc(sizeof(SessionManager));
    pthread_mutex_init(&manager->session_lock, NULL);
    manager->token_count = 0;

    populate_pdu_with_token(pdu, manager);

    pthread_mutex_destroy(&manager->session_lock);
    free(manager);
    return NULL;
}

void initialize_session_manager(SessionManager *manager) {
    pthread_mutex_init(&manager->session_lock, NULL);
    manager->token_count = 0;
}

void finalize_session_manager(SessionManager *manager) {
    pthread_mutex_destroy(&manager->session_lock);
}

int main() {
    srand(time(NULL));
    int n = 10; // Number of PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    initialize_pdus(pdus, n);

    SessionManager manager;
    initialize_session_manager(&manager);

    pthread_t threads[n];
    for (int i = 0; i < n; ++i) {
        pthread_create(&threads[i], NULL, populate_pdu, &pdus[i]);
    }

    for (int i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    finalize_session_manager(&manager);
    free(pdus);

    return 0;
}
