// Prototype for a function to retrieve the CRC flag threshold
int get_crc_threshold();

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_list(size_t n) {
    if (n > MAX_ENTRIES) {
        fprintf(stderr, "Error: Request exceeds maximum allowed entries.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **current = &head;

    int crcThreshold = get_crc_threshold();

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed.\n");
            // Free previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        newNode->ueInfoTag.RNTI = i;  // Simulating RNTI assignment
        newNode->ueInfoTag.crcTag.CRCFLAG = (i % crcThreshold == 0) ? 1 : 0;

        *current = newNode;
        current = &newNode->next;
    }

    *current = NULL;  // Mark end of list
    return head;
}

// Placeholder implementation for demonstration purposes.
