            User_Info *cached_user_info = malloc(sizeof(User_Info));
            memcpy(cached_user_info, &user_cache[i], sizeof(User_Info));
            pthread_mutex_unlock(&cache_lock);
            return cached_user_info;
        }
    }

    // If not in cache, fetch from service
    User_Info *new_user_info = fetch_user_info_from_service(user_id);

    if (new_user_info) {
        user_cache = realloc(user_cache, (cache_size + 1) * sizeof(User_Info));
        if (user_cache) {
            memcpy(&user_cache[cache_size], new_user_info, sizeof(User_Info));
            ++cache_size;
        } else {
            free(new_user_info);
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&cache_lock);
    return new_user_info;
}

int main() {
    int num_pdus = 10; // Example usage
    NFAPI_CRC_INDICATION_PDU_T *pdus = generate_nfaapi_crc_pdu_list(num_pdus);

    if (pdus) {
        for (int i = 0; i < num_pdus; ++i) {
            free(pdus[i].rx_ue_info_tag);
        }
        free(pdus);
    }

    return 0;
}
