using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Logging;

public class PageUpdateService
{
    private readonly IElementService _elementService;
    private readonly IMemoryCache _cache;
    private readonly ILogger<PageUpdateService> _logger;
    private readonly HttpClient _httpClient;
    private readonly string[] _trustedOrigins = { "https://trusted-source.com", "https://another-trusted-source.com" };

    public PageUpdateService(IElementService elementService, IMemoryCache cache, ILogger<PageUpdateService> logger)
    {
        _elementService = elementService ?? throw new ArgumentNullException(nameof(elementService));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _httpClient = new HttpClient();
    }

    public async Task<HttpResponseMessage> UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        try
        {
            if (!IsRequestTrusted())
            {
                return new HttpResponseMessage(System.Net.HttpStatusCode.Forbidden) { Content = new StringContent("Unauthorized request origin.") };
            }

            var cacheKey = $"PageSection_{pageSectionId}_Element_{elementId}";
            bool isCacheUpdated = false;

            string cachedHtml = _cache.Get<string>(cacheKey);
            if (string.Equals(cachedHtml, htmlContent, StringComparison.Ordinal))
            {
                return new HttpResponseMessage(System.Net.HttpStatusCode.NoContent) { Content = new StringContent("No update needed.") };
            }

            await UpdateElementAsyncWithRetry(pageSectionId, elementId, htmlContent);

            _cache.Set(cacheKey, htmlContent);
            isCacheUpdated = true;

            var metadata = new
            {
                Timestamp = DateTime.UtcNow,
                CacheUpdated = isCacheUpdated
            };

            _logger.LogInformation("Element updated at {Timestamp}. Cache Updated: {CacheUpdated}", metadata.Timestamp, metadata.CacheUpdated);

            return new HttpResponseMessage(System.Net.HttpStatusCode.OK)
            {
                Content = new StringContent($"Page should be refreshed. Metadata: {JsonConvert.SerializeObject(metadata)}")
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating the element.");
            return new HttpResponseMessage(System.Net.HttpStatusCode.InternalServerError) { Content = new StringContent("An error occurred.") };
        }
    }

    private bool IsRequestTrusted()
    {
        var requestOrigin = HttpContext.Current.Request.Headers["Origin"];
        return Array.Exists(_trustedOrigins, origin => string.Equals(origin, requestOrigin, StringComparison.OrdinalIgnoreCase));
    }

    private async Task UpdateElementAsyncWithRetry(string pageSectionId, string elementId, string htmlContent)
    {
        int retryCount = 3;
        for (int attempt = 0; attempt < retryCount; attempt++)
        {
            try
            {
                await _elementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
                return;
            }
            catch (HttpRequestException ex) when (attempt < retryCount - 1)
            {
                _logger.LogWarning(ex, "Request to external service failed. Retrying ({Attempt}/{MaxAttempts}).", attempt + 1, retryCount);
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
            }
        }

        throw new Exception("Failed to update element after multiple retries.");
    }
}

public interface IElementService
{
    Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent);
}
