```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_ENTRIES 10000
#define MAX_ALLOC_PER_SECOND 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_rel8_tag;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRC_List;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

bool initialize_list(CRC_List *list, size_t initial_capacity) {
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->entries) {
        log_error("Failed to allocate memory for CRC list.");
        return false;
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return true;
}

bool resize_list(CRC_List *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entries) {
        log_error("Failed to resize memory for CRC list.");
        return false;
    }
    list->entries = new_entries;
    list->capacity = new_capacity;
    return true;
}

bool populate_entry(NFAPI_CRC_INDICATION_PDU_T *entry, int ue_tag, int rnti, bool crc_flag) {
    entry->crc_rel8_tag.RX_UE_INFORMATION_TAG = ue_tag;
    entry->crc_rel8_tag.RNTI = rnti;
    entry->CRCFLAG = crc_flag;
    return true; // Assume successful population
}

bool validate_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (entry->crc_rel8_tag.RX_UE_INFORMATION_TAG <= 0 || entry->crc_rel8_tag.RNTI <= 0) {
        log_error("Invalid RX_UE_INFORMATION_TAG or RNTI.");
        return false;
    }
    // Additional validation checks can be added here
    return true;
}

bool add_entry(CRC_List *list, int ue_tag, int rnti, bool crc_flag) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (!resize_list(list, new_capacity)) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[list->count];
    if (!populate_entry(entry, ue_tag, rnti, crc_flag) || !validate_entry(entry)) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->count++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool create_and_populate_list(CRC_List *list, size_t num_entries) {
    if (!initialize_list(list, 1000)) {
        return false;
    }

    for (size_t i = 0; i < num_entries && i < MAX_ENTRIES; ++i) {
        int ue_tag = rand() % 1000 + 1; // Example random value
        int rnti = rand() % 1000 + 1;   // Example random value
        bool crc_flag = rand() % 2;

        if (!add_entry(list, ue_tag, rnti, crc_flag)) {
            log_error("Failed to add entry.");
            return false;
        }
    }

    return true;
}

void free_list(CRC_List *list) {
    pthread_mutex_lock(&list->lock);
    free(list->entries);
    list->entries = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    CRC_List list;
    if (create_and_populate_list(&list, MAX_ENTRIES)) {
        printf("List created and populated successfully with %zu entries.\n", list.count);
    } else {
        log_error("Failed to create and populate the list.");
    }

    free_list(&list);
    return 0;
}
