#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int threshold;
} Config;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void load_config(const char *path, Config *config) {
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        perror("Failed to open config file");
        exit(EXIT_FAILURE);
    }
    fscanf(file, "%d", &config->threshold);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* create_list_entry(int rx_ue_tag, int rnti, Config *config) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->RNTI = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = (rx_ue_tag % 100 < config->threshold) ? 1 : 0;
    new_node->next = NULL;
    return new_node;
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_list(int N, const char *config_path) {
    if (N > MAX_ENTRIES) {
        fprintf(stderr, "Exceeded maximum number of entries.\n");
        exit(EXIT_FAILURE);
    }

    Config config;
    load_config(config_path, &config);

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, **last = &head;

    for (int i = 0; i < N; ++i) {
        *last = create_list_entry(i, rand(), &config);
        last = &((*last)->next);
    }

    pthread_mutex_unlock(&list_mutex);

    return head;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    pthread_mutex_lock(&list_mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list_mutex);
}

int main() {
    const char *config_path = "path/to/config.txt";
    int number_of_entries = 1000;

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = generate_nfa_list(number_of_entries, config_path);

    // Process the list...

    free_nfa_list(nfa_list);
    return 0;
}
