// Function to add an element at a specific position.
int add_element(DynamicArray* arr, size_t index, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (index > arr->size || arr->size == arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2);
    }

    // Shift elements to the right.
    memmove(&arr->data[index + 1], &arr->data[index], (arr->size - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!is_unique(arr, element)) {
        return -1; // Duplicate found
    }

    arr->data[index] = *element;
    arr->size++;
    return 0;
}

// Function to remove an element at a specific position.
int remove_element(DynamicArray* arr, size_t index) {
    if (index >= arr->size) {
        return -1; // Index out of bounds
    }

    memmove(&arr->data[index], &arr->data[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size--;

    if (arr->size < arr->capacity / 4 && arr->capacity > 16) {
        resize_dynamic_array(arr, arr->capacity / 2);
    }

    return 0;
}

// Function to update an element at a specific position.
int update_element(DynamicArray* arr, size_t index, const NFAPI_CRC_INDICATION_PDU_T* new_value) {
    if (index >= arr->size || !is_unique(arr, new_value)) {
        return -1; // Index out of bounds or duplicate found
    }

    arr->data[index] = *new_value;
    return 0;
}

// Helper function to check uniqueness in the array.
int is_unique(DynamicArray* arr, const NFAPI_CRC_INDICATION_PDU_T* element) {
    for (size_t i = 0; i < arr->size; ++i) {
