```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 1024
#define MAX_PAYLOAD_SIZE 16384 // 16KB

typedef struct {
    uint8_t l2_header[14]; // Assuming Ethernet II header size
    uint8_t mac_control_pdu[8]; // Example fixed size
    uint8_t *payload;
    size_t payload_size;
} MAC_PDU;

typedef struct {
    MAC_PDU *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} PDU_Array;

// Function prototypes
PDU_Array* init_pdu_array();
int add_pdu(PDU_Array *array, MAC_PDU pdu);
int delete_pdu(PDU_Array *array, int index);
MAC_PDU get_pdu(const PDU_Array *array, int index);
void resize_pdu_array(PDU_Array *array);

// Initialize the dynamic array of PDUs
PDU_Array* init_pdu_array() {
    PDU_Array *array = (PDU_Array*)malloc(sizeof(PDU_Array));
    if (!array) return NULL;

    pthread_mutex_init(&array->mutex, NULL);
    array->capacity = INITIAL_SIZE;
    array->count = 0;
    array->pdus = (MAC_PDU*)calloc(array->capacity, sizeof(MAC_PDU));
    if (!array->pdus) {
        free(array);
        return NULL;
    }
    return array;
}

// Add a new PDU to the dynamic array
int add_pdu(PDU_Array *array, MAC_PDU pdu) {
    pthread_mutex_lock(&array->mutex);

    // Resize if necessary
    if (array->count >= array->capacity) {
        resize_pdu_array(array);
    }

    // Allocate payload memory
    array->pdus[array->count].payload = malloc(pdu.payload_size);
    if (!array->pdus[array->count].payload) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }

    memcpy(array->pdus[array->count].l2_header, pdu.l2_header, sizeof(pdu.l2_header));
    memcpy(array->pdus[array->count].mac_control_pdu, pdu.mac_control_pdu, sizeof(pdu.mac_control_pdu));
    memcpy(array->pdus[array->count].payload, pdu.payload, pdu.payload_size);
    array->pdus[array->count].payload_size = pdu.payload_size;

    array->count++;
    pthread_mutex_unlock(&array->mutex);

    return 0;
}

// Delete a PDU from the dynamic array
int delete_pdu(PDU_Array *array, int index) {
    if (index < 0 || index >= array->count) return -1;

    pthread_mutex_lock(&array->mutex);

    free(array->pdus[index].payload);
    memmove(&array->pdus[index], &array->pdus[index + 1], 
            sizeof(MAC_PDU) * (array->count - index - 1));
    array->count--;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

// Retrieve a PDU from the dynamic array
MAC_PDU get_pdu(const PDU_Array *array, int index) {
    if (index < 0 || index >= array->count) {
        MAC_PDU empty = { .payload_size = 0 };
        return empty;
    }

    pthread_mutex_lock(&(array->mutex));

    MAC_PDU pdu = array->pdus[index];

    pthread_mutex_unlock(&(array->mutex));
    return pdu;
}

// Resize the dynamic array to increase its capacity
void resize_pdu_array(PDU_Array *array) {
    size_t new_capacity = array->capacity + INITIAL_SIZE;
    MAC_PDU *new_pdus = (MAC_PDU*)realloc(array->pdus, sizeof(MAC_PDU) * new_capacity);
    if (!new_pdus) return;

    array->pdus = new_pdus;
    array->capacity = new_capacity;
}

// Free the dynamic array resources
void free_pdu_array(PDU_Array *array) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i].payload);
    }

    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array->pdus);
    free(array);
}
```

This implementation covers initialization, concurrent access protection using a mutex, dynamic resizing of the array when needed, and error checking for memory allocation failures. It uses `pthread` for thread safety to handle concurrency issues effectively without significant performance overhead.']

