#define MAX_RNTI 65535

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int rnti_count[MAX_RNTI + 1] = {0};
int total_processed = 0;
int duplicate_errors = 0;

void log_message(const char* message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

int is_rnti_unique(uint32_t rnti) {
    pthread_mutex_lock(&lock);
    int unique = (rnti_count[rnti] == 0);
    if (unique) {
        rnti_count[rnti]++;
    } else {
        duplicate_errors++;
    }
    pthread_mutex_unlock(&lock);
    return unique;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for node.");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

Node* create_nfaapi_crc_indication_pdu_list(int N) {
    if (N <= 0) return NULL;

    Node* head = NULL;
    Node** tail_ref = &head;
    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        uint32_t RNTI = rand() % (MAX_RNTI + 1);

        if (!is_rnti_unique(RNTI)) {
            log_message("Duplicate RNTI detected. Skipping node creation.");
            continue;
        }

        NFAPI_CRC_INDICATION_PDU_T pdu_data;
        pdu_data.RNTI = RNTI;
        pdu_data.CRCFLAG = rand() % 2; // Random CRCFLAG

        Node* new_node = create_node(pdu_data);

        *tail_ref = new_node;
        tail_ref = &new_node->next;

        log_message("Created NFAPI_CRC_INDICATION_PDU_T with RNTI and CRCFLAG.");

        total_processed++;
    }

    return head;
}

void report_statistics() {
    pthread_mutex_lock(&lock);
    printf("Total CRC indications processed: %d\n", total_processed);
    printf("Duplicate RNTI errors encountered: %d\n", duplicate_errors);
    pthread_mutex_unlock(&lock);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_structures>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int N = atoi(argv[1]);
    Node* list = create_nfaapi_crc_indication_pdu_list(N);

    // Simulate processing and clean-up
    free_list(list);
    report_statistics();

    pthread_mutex_destroy(&lock);
    return 0;
}
