            int value = dis(gen);
            records.emplace_back(key, value);

            offsets[i] = static_cast<int>(records.size());
        }

        nlohmann::json jsonResponse;
        jsonResponse["refresh"] = true;
        for (const auto& record : records) {
            jsonResponse["updated_records"][std::to_string(record.first)] = record.second;
        }

        return jsonResponse;
    }
};
```']

