            return 0;
    }
    return 1;
}

void manage_dynamic_arrays(int N) {
    pthread_mutex_lock(&pool_lock);

    TX_CELL_CONFIG *tx_cell_configs = (TX_CELL_CONFIG *)malloc(N * sizeof(TX_CELL_CONFIG));
    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!tx_cell_configs || !crc_list) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&pool_lock);
        return;
    }

    for (int i = 0; i < N; ++i) {
