        crc_list[i].crc_indication_rel8_tag.CRCFLAG = generate_random_crcflag();

        if (validate_rnti_uniqueness(rnti, crc_list, i)) {
            crc_list[i].crc_indication_rel8_tag.RNTI = rnti;
            log_message("NFAPI_CRC_INDICATION_PDU_T initialized.");
        } else {
            log_message("Duplicate RNTI detected. Skipping entry.");
            duplicate_rnti_errors++;
            continue;
        }

        crc_count++;
    }

    // Log summary
    log_message("Total CRC indications processed: ");
    printf("%d\n", crc_count);
    log_message("Duplicate RNTI errors encountered: ");
    printf("%d\n", duplicate_rnti_errors);

    free(tx_cell_configs);
    free(crc_list);

    pthread_mutex_unlock(&pool_lock);
}

int main() {
    srand((unsigned int)time(NULL));
    int N = 10; // Example number of structures
    manage_dynamic_arrays(N);
    return 0;
}
