extern void log_error(const char* message);
extern int random_number_generator(void); // Returns a number between 0 and RAND_MAX
extern void sleep_for(int milliseconds);

#define MAX_STRUCTURES 10000

// Mutex for thread-safe operations
pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;
uint32_t last_RNTI = 0;

int log_with_retry(const char* message) {
    int retries = 3, delay = 100; // Initial delay in ms
    while (retries-- > 0) {
        if (log_error(message)) { // Assuming log_error returns a success/failure flag
            return 1;
        }
        sleep_for(delay);
        delay *= 2; // Exponential backoff
    }
    return 0;
}

int calculate_crc_flag() {
    int random_value = random_number_generator();
    return (random_value % 2 == 0) ? 1 : 0; // Example probabilistic function
}

NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_array(size_t num_structures, size_t* actual_count) {
    if (num_structures > MAX_STRUCTURES || num_structures < 1) {
        *actual_count = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    pthread_mutex_lock(&allocation_mutex);
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_with_retry("Memory allocation failed");
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    uint32_t current_RNTI = 1;
    for (size_t i = 0; i < num_structures; ++i) {
        array[i].RNTI = current_RNTI;
        if (array[i].RNTI == last_RNTI) { // Ensure no consecutive RNTIs are the same
            current_RNTI++;
        }
        array[i].crc_tag.CRCFLAG = calculate_crc_flag();
        last_RNTI = array[i].RNTI;
    }

    *actual_count = num_structures;
    pthread_mutex_unlock(&allocation_mutex);

    return array;
}

void free_nfa_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
```

