typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    int max_size;
    int discarded_entries;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list(int max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    list->discarded_entries = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void log_event(const char* event) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        fprintf(file, "%s: %s\n", ctime(&now), event);
        fclose(file);
    }
}

void add_entry(CRCList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->max_size) {
        Node* old_head = list->head;
        list->head = list->head->next;
        free(old_head);
        list->size--;
        list->discarded_entries++;
        log_event("Entry discarded due to overflow");
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_event("Failed to allocate memory for new entry");
        return;
    }
    new_node->data = entry;
    new_node->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    log_event("Entry added");

    pthread_mutex_unlock(&list->lock);
}

void garbage_collect(CRCList* list) {
