#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_PATH 1024
#define VALID_RESOURCE_EXT ".res" // Example extension for valid resource files

typedef struct {
    char **file_paths;
    size_t count;
} ResourceBundle;

// Mutex for thread safety in a multi-threaded environment
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int is_valid_resource_file(const char *filename) {
    const char *ext = strrchr(filename, '.');
    return ext && strcmp(ext, VALID_RESOURCE_EXT) == 0;
}

int traverse_directory(const char *dir_path, size_t *file_count) {
    DIR *dir;
    struct dirent *entry;
    struct stat statbuf;
    int total_files = 0;

    if (!(dir = opendir(dir_path))) return -1;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[MAX_PATH];
        snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, entry->d_name);

        if (stat(full_path, &statbuf) != 0) {
            closedir(dir);
            return -1;
        }

        if (S_ISDIR(statbuf.st_mode)) {
            int result = traverse_directory(full_path, file_count);
            if (result == -1) {
                closedir(dir);
                return -1;
            }
            total_files += result;
        } else if (is_valid_resource_file(entry->d_name)) {
            (*file_count)++;
            total_files++;
        }
    }

    closedir(dir);
    return total_files;
}

ResourceBundle* load_resource_bundle(const char *directory) {
    size_t file_count = 0;

    pthread_mutex_lock(&mutex);

    if (traverse_directory(directory, &file_count) == -1) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    bundle->file_paths = calloc(file_count, sizeof(char *));
    if (!bundle->file_paths) {
        free(bundle);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    bundle->count = file_count;

    // Recursive function to populate file paths would go here (omitted for brevity)

    pthread_mutex_unlock(&mutex);

    return bundle;
}

void free_resource_bundle(ResourceBundle *bundle) {
    if (!bundle) return;
    for (size_t i = 0; i < bundle->count; ++i) {
        free(bundle->file_paths[i]);
    }
    free(bundle->file_paths);
    free(bundle);
}
