#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t SEQUENCE_NUMBER;
    time_t TRANSMISSION_TIMESTAMP;
    int ACKNOWLEDGMENT_FLAG;
    uint8_t RETRY_COUNT;
} MAC_TRANSACTION_RECORD_T;

typedef struct {
    MAC_TRANSACTION_RECORD_T *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // For concurrency management
} TransactionList;

// Initialize the transaction list with specified initial capacity.
TransactionList* init_transaction_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    TransactionList *list = malloc(sizeof(TransactionList));
    if (!list) return NULL;

    list->records = aligned_alloc(16, initial_capacity * sizeof(MAC_TRANSACTION_RECORD_T));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Resize the transaction list to a new capacity.
static int resize_transaction_list(TransactionList *list, size_t new_capacity) {
    MAC_TRANSACTION_RECORD_T *new_records =
        aligned_alloc(16, new_capacity * sizeof(MAC_TRANSACTION_RECORD_T));
    if (!new_records) return -1;

    for (size_t i = 0; i < list->size; ++i) {
        new_records[i] = list->records[i];
    }

    free(list->records);
    list->records = new_records;
    list->capacity = new_capacity;
    return 0;
}

// Insert a transaction record into the list.
int insert_transaction_record(TransactionList *list, MAC_TRANSACTION_RECORD_T record) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        int resize_status = resize_transaction_list(list, new_capacity);
        if (resize_status != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
    }

    list->records[list->size] = record;
    list->size++;
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Free all resources associated with the transaction list.
void free_transaction_list(TransactionList *list) {
    if (list) {
        if (list->records) free(list->records);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

// Function to process transactions in parallel
void* process_transactions(void* arg) {
    TransactionList* list = (TransactionList*)arg;

    for (size_t i = 0; i < list->size; ++i) {
        MAC_TRANSACTION_RECORD_T *record = &list->records[i];

        // Simulate transaction processing with a timestamp and random retry count
        record->TRANSMISSION_TIMESTAMP = time(NULL);
        record->RETRY_COUNT = rand() % 5;
    }

    return NULL;
}

int main() {
    size_t initial_capacity = 1000; // Adjust as needed
    TransactionList *list = init_transaction_list(initial_capacity);
    if (!list) {
        fprintf(stderr, "Failed to initialize transaction list.\n");
        return EXIT_FAILURE;
    }

    // Simulate inserting transactions
    for (size_t i = 0; i < 5000; ++i) {
        MAC_TRANSACTION_RECORD_T record = {
            .SEQUENCE_NUMBER = i,
            .ACKNOWLEDGMENT_FLAG = rand() % 2,
        };

        if (insert_transaction_record(list, record) != 0) {
            fprintf(stderr, "Memory allocation failed during insertion.\n");
            free_transaction_list(list);
            return EXIT_FAILURE;
        }
    }

    // Multithreaded transaction processing
    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, process_transactions, list);
    pthread_create(&thread2, NULL, process_transactions, list);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free_transaction_list(list);
    return EXIT_SUCCESS;
}
