bool load_theme_bitmap(const char *path, ThemeBitmap **bitmap) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        log_event("Error opening file: ");
        return false;
    }

    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        fclose(file);
        log_event("Failed to create PNG read struct.");
        return false;
    }

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, NULL, NULL);
        fclose(file);
        log_event("Failed to create PNG info struct.");
        return false;
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        fclose(file);
        log_event("Error during PNG creation.");
        return false;
    }

    png_init_io(png_ptr, file);
    png_read_info(png_ptr, info_ptr);

    // Perform streaming read or minimal processing to reduce memory footprint
    // ...

    *bitmap = malloc(sizeof(ThemeBitmap));
    if (!*bitmap) {
        png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
        fclose(file);
        log_event("Memory allocation failed for ThemeBitmap.");
        return false;
    }

    // Populate bitmap data
    // ...

    png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
    fclose(file);

    log_event("Theme bitmap loaded successfully.");
    return true;
}

void lazy_load_theme_bitmaps(ThemeCache *cache, const char *directory_path) {
    pthread_mutex_lock(&cache->lock);

    // Implement logic to load bitmaps lazily
    // ...

    pthread_mutex_unlock(&cache->lock);
}

void background_cache_manager_thread(void *arg) {
    ThemeCache *cache = (ThemeCache *)arg;

    while (true) {
        sleep(60);  // Check for updates every minute

        pthread_mutex_lock(&cache->lock);

        if (cache->is_outdated) {
            update_cache(cache);
        }

        pthread_mutex_unlock(&cache->lock);
    }
}

void update_cache(ThemeCache *cache) {
    // Logic to check and update outdated cache entries
    log_event("Updating theme cache.");
    cache->is_outdated = false;
}

void log_event(const char *message) {
    if (log_level == LOG_LEVEL_ERROR && strstr(message, "Error")) {
        fprintf(stderr, "%s\n", message);
    } else if (log_level == LOG_LEVEL_INFO) {
        printf("%s\n", message);
    }
}
