namespace RandomNumberGenerator {

    class MersenneTwister {
    public:
        struct RX_UE_INFORMATION_TAG {};
        struct RNTI {};

        struct CRC_INDICATION_REL8_TAG {
            bool CRCFLAG;
        };

        using NFAPI_CRC_INDICATION_PDU_T = struct {
            RX_UE_INFORMATION_TAG ueTag;
            RNTI rnti;
            CRC_INDICATION_REL8_TAG crcTag;
        };

    private:
        static std::mt19937 generator;
        static std::mutex mtx;

        MersenneTwister(unsigned int seed) {
            std::lock_guard<std::mutex> lock(mtx);
            generator.seed(seed);
        }

        ~MersenneTwister() = default;

    public:
        static void InitializeState(unsigned int seed) {
            std::lock_guard<std::mutex> lock(mtx);
            generator.seed(seed);
        }

        static NFAPI_CRC_INDICATION_PDU_T* GenerateRandomCrcIndication(size_t count, size_t poolSize = 1024) {
            std::vector<NFAPI_CRC_INDICATION_PDU_T*> pool(poolSize);

            for (auto& pdu : pool) {
                pdu = new NFAPI_CRC_INDICATION_PDU_T();
            }

            std::vector<NFAPI_CRC_INDICATION_PDU_T*> result;
            result.reserve(count);
            std::lock_guard<std::mutex> lock(mtx);

            for (size_t i = 0; i < count; ++i) {
                if (i >= poolSize) break;

                auto& pdu = *pool[i % poolSize];
                pdu.crcTag.CRCFLAG = generator() % 2 == 0;
                result.push_back(pool[i % poolSize]);
            }

            return result.data();
        }
    };

    std::mt19937 MersenneTwister::generator{std::random_device{}()};
    std::mutex MersenneTwister::mtx;

} // namespace RandomNumberGenerator

int main() {
    using namespace RandomNumberGenerator;

    MersenneTwister::InitializeState(42);
    auto* pdus = MersenneTwister::GenerateRandomCrcIndication(10);

    for (size_t i = 0; i < 10; ++i) {
        std::cout << "CRCFLAG for PDU " << i << ": " << pdus[i]->crcTag.CRCFLAG << "\n";
    }

    delete[] pdus;
    return 0;
}
