#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>

#define MAX_STRUCTS 1000
#define RNTI_MIN 1
#define RNTI_MAX 65535

typedef struct {
    uint16_t rnti;
    uint8_t rx_ue_info_tag;
} InputData;

typedef struct {
    uint16_t rnti;
    uint8_t rx_ue_info_tag;
    bool crcflag; // Randomly set CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool[MAX_STRUCTS];
    int count;
    pthread_mutex_t lock;
} ResourcePool;

// Function to initialize the resource pool
void init_resource_pool(ResourcePool* rp) {
    rp->count = 0;
    pthread_mutex_init(&rp->lock, NULL);
}

// Function to validate RNTI and RX_UE_INFORMATION_TAG
bool validate_data(uint16_t rnti, uint8_t rx_ue_info_tag) {
    return (rnti >= RNTI_MIN && rnti <= RNTI_MAX); // Add more validation logic if needed
}

// Function to log errors
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to handle CRC indication
bool handle_crc_indication(ResourcePool* rp, const InputData* data_list, size_t list_size) {
    pthread_mutex_lock(&rp->lock);

    for (size_t i = 0; i < list_size; ++i) {
        if (!validate_data(data_list[i].rnti, data_list[i].rx_ue_info_tag)) {
            log_error("Invalid RNTI or RX_UE_INFORMATION_TAG");
            pthread_mutex_unlock(&rp->lock);
            return false;
        }

        if (rp->count >= MAX_STRUCTS) {
            log_error("Resource pool is full");
            pthread_mutex_unlock(&rp->lock);
            return false;
        }

        NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_struct) {
            log_error("Memory allocation failed");
            pthread_mutex_unlock(&rp->lock);
            return false;
        }

        new_struct->rnti = data_list[i].rnti;
        new_struct->rx_ue_info_tag = data_list[i].rx_ue_info_tag;
        new_struct->crcflag = rand() % 2; // Randomly set CRCFLAG

        rp->pool[rp->count++] = new_struct;
    }

    pthread_mutex_unlock(&rp->lock);
    return true;
}

// Function to free the resource pool
void cleanup_resource_pool(ResourcePool* rp) {
    for (int i = 0; i < rp->count; ++i) {
        free(rp->pool[i]);
    }
    pthread_mutex_destroy(&rp->lock);
}
```

