import hashlib
import os
from concurrent.futures import ThreadPoolExecutor, as_completed

def compute_md5(file_path):
    try:
        hasher = hashlib.md5()
        with open(file_path, 'rb') as file:
            for chunk in iter(lambda: file.read(4096), b""):
                hasher.update(chunk)
        return hasher.hexdigest()
    except Exception as e:
        print(f"Error processing {file_path}: {e}")
        return None

def process_files_in_directory(root_dir, extensions):
    results = {}

    def process_file(file_path):
        relative_path = os.path.relpath(file_path, root_dir)
        if any(relative_path.endswith(ext) for ext in extensions):
            md5_hash = compute_md5(file_path)
            if md5_hash:
                results[relative_path] = md5_hash

    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = []
        for dirpath, _, filenames in os.walk(root_dir):
            for filename in filenames:
                file_path = os.path.join(dirpath, filename)
                if not any(file_path.endswith(ext) and os.path.isdir(file_path) for ext in extensions):
                    futures.append(executor.submit(process_file, file_path))

        for future in as_completed(futures):
            future.result()  # To raise exceptions if any occurred

    return results

# Example usage:
if __name__ == "__main__":
    directory = "/path/to/directory"
    extensions = [".txt", ".log"]
    hashes = process_files_in_directory(directory, extensions)
    for relative_path, md5_hash in hashes.items():
        print(f"{relative_path}: {md5_hash}")
```

This code efficiently computes the MD5 hash of files within a specified directory tree using a thread pool to handle concurrency. It processes only the specified file types and reads files in chunks to manage memory usage effectively. Robust error handling ensures that exceptions during file access do not disrupt the overall process.']

