```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

// Define the structure types for demonstration purposes
typedef struct {
    int unique_id;  // Example field for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned long rnti;
} RNTI_T;

typedef struct {
    unsigned char crc_flag;  // CRC flag (1 byte)
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI_T rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the main structure and associated mutex
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    int size;
    pthread_mutex_t mutex;
} PDU_Manager;

// Function prototypes
void initialize_rng();
unsigned char generate_random_crc_flag();
int populate_pdus(PDU_Manager *manager, int n);
void log_pdu_details(const NFAPI_CRC_INDICATION_PDU_T *pdu);
int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu);
PDU_Manager *create_pdu_manager(int n);
void free_pdu_manager(PDU_Manager *manager);

// Function implementations
void initialize_rng() {
    srand(time(NULL));
}

unsigned char generate_random_crc_flag() {
    return rand() % 2;
}

int populate_pdus(PDU_Manager *manager, int n) {
    pthread_mutex_lock(&manager->mutex);

    if (n <= manager->size) {
        for (int i = 0; i < n; ++i) {
            // Populate the RX_UE_INFORMATION_TAG
            manager->pdus[i].rx_ue_information_tag.unique_id = i + 1;

            // Populate the RNTI
            manager->pdus[i].rnti.rnti = (unsigned long)(i + 1) * 100; // Example value

            // Generate and populate CRC_INDICATION_REL8_TAG with random flag
            manager->pdus[i].crc_indication_rel8_tag.crc_flag = generate_random_crc_flag();

            if (!validate_pdu(&manager->pdus[i])) {
                pthread_mutex_unlock(&manager->mutex);
                return -1;  // Validation failed
            }
        }

        pthread_mutex_unlock(&manager->mutex);
        return n;
    } else {
        pthread_mutex_unlock(&manager->mutex);
        return -2;  // Insufficient space in the manager
    }
}

void log_pdu_details(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("RX_UE_INFORMATION_TAG: %d\n", pdu->rx_ue_information_tag.unique_id);
    printf("RNTI: %lu\n", pdu->rnti.rnti);
    printf("CRC_INDICATION_REL8_TAG: %u\n", pdu->crc_indication_rel8_tag.crc_flag);
}

int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Basic validation to ensure data integrity
    return pdu->rx_ue_information_tag.unique_id > 0 &&
           pdu->rnti.rnti != 0 && (pdu->crc_indication_rel8_tag.crc_flag == 0 || pdu->crc_indication_rel8_tag.crc_flag == 1);
}

PDU_Manager *create_pdu_manager(int n) {
    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    if (!manager) return NULL;

    manager->pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->size = n;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void free_pdu_manager(PDU_Manager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->pdus);
        free(manager);
    }
}
```

### Explanation:

- **Data Structures:** We define the necessary structures to represent the data (`NFAPI_CRC_INDICATION_PDU_T`, `RX_UE_INFORMATION_TAG`, etc.).
- **Random Number Generation:** A random seed is initialized, and a function generates CRC flags.
- **Synchronization:** Mutexes ensure that concurrent modifications to the shared `PDU_Manager` structure are thread-safe.
- **Memory Management:** The `create_pdu_manager` allocates memory for the PDU array, and `free_pdu_manager` frees it. This design ensures no memory leaks occur.
- **Validation and Logging:** Each PDU is validated, and there's a function to log details if needed, which can be useful during debugging.
- **Scalability Considerations:** Mutexes provide thread safety but introduce some performance overhead. The solution balances between simplicity and efficiency with the assumption of moderate contention levels.

This implementation provides a robust starting point for managing PDU structures in a multi-threaded environment.']

