import threading
import queue
from concurrent.futures import ThreadPoolExecutor
import requests
import os
import json
import logging
from pathlib import Path

# Setup Logging
logger = logging.getLogger("ThemeManager")
handler = logging.handlers.RotatingFileHandler(
    "theme_manager.log", maxBytes=10*1024*1024, backupCount=3)
formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)
logger.setLevel(logging.INFO)

# Constants
CACHE_DIR = Path("cache_root")
THEME_CACHE = {}
LOCK = threading.Lock()

class ThemeManager:
    def __init__(self):
        self.executor = ThreadPoolExecutor(max_workers=5)
        self.theme_update_interval = 3600 # seconds

    def start_background_service(self):
        while True:
            try:
                self.check_for_updates()
                time.sleep(self.theme_update_interval)
            except Exception as e:
                logger.error(f"Error in background service: {e}")

    def check_for_updates(self):
        themes_directory = Path("theme_repository")
        with LOCK:
            for theme_file in themes_directory.glob('*.json'):
                try:
                    self.update_theme(theme_file.name)
                except Exception as e:
                    logger.warning(f"Failed to update theme {theme_file.name}: {e}")

    def lazy_load_theme(self, theme_name):
        if theme_name not in THEME_CACHE:
            with LOCK:
                if theme_name not in THEME_CACHE:  # Double-checked locking
                    try:
                        theme_data = self.load_theme_from_disk_or_network(theme_name)
                        if theme_data:
                            THEME_CACHE[theme_name] = theme_data
                    except Exception as e:
                        logger.warning(f"Failed to load theme {theme_name}: {e}")
        return THEME_CACHE.get(theme_name)

    def update_theme(self, filename):
        file_path = CACHE_DIR / filename
        try:
            if not self.is_cache_valid(file_path):
                response = requests.get(f"https://example.com/themes/{filename}", timeout=10)
                response.raise_for_status()
                with open(file_path, 'wb') as f:
                    f.write(response.content)

                logger.info(f"Theme {filename} updated successfully")
        except (requests.RequestException, IOError) as e:
            logger.error(f"Failed to update theme {filename}: {e}")

    def is_cache_valid(self, file_path):
        # Implement logic for checking cache validity
        return file_path.exists()

    def load_theme_from_disk_or_network(self, filename):
        file_path = CACHE_DIR / filename
        if self.is_cache_valid(file_path):
            try:
                with open(file_path, 'r') as f:
                    theme_data = json.load(f)
                    logger.info(f"Theme {filename} loaded from cache")
                    return theme_data
            except (json.JSONDecodeError, IOError) as e:
                logger.warning(f"Failed to load theme {filename} from disk: {e}")

        # Fallback to network load if needed or invalid on disk
        response = requests.get(f"https://example.com/themes/{filename}", timeout=10)
        try:
            response.raise_for_status()
            with open(file_path, 'wb') as f:
                f.write(response.content)
            return json.loads(response.text)
        except (requests.RequestException, json.JSONDecodeError) as e:
            logger.error(f"Failed to load theme {filename} from network: {e}")
            return None

    def stream_parse_json(self, file_path):
        with open(file_path, 'r') as f:
            for line in f:
                try:
                    yield json.loads(line)
                except json.JSONDecodeError:
                    logger.warning(f"Incomplete or corrupted data in {file_path}")

# Example Usage
theme_manager = ThemeManager()
threading.Thread(target=theme_manager.start_background_service, daemon=True).start()

# Loading a theme lazily
theme_data = theme_manager.lazy_load_theme("default_theme.json")
print(theme_data)
```

**Explanation:**

- **Thread Safety and Concurrency:** Uses `LOCK` for synchronized access to shared resources like the theme cache.
- **Lazy Loading & Caching:** Themes are loaded on demand, utilizing a local cache to avoid redundant network requests or disk reads.
- **Background Service:** A separate thread periodically checks for theme updates without blocking main application flow. 
- **Network Fallback and Graceful Failure Handling:** In case of network failures, themes are fetched from the cache if valid; errors are logged instead of crashing the app.
- **Streaming Parser:** Implements a JSON streaming parser to handle potentially large files efficiently without loading them entirely into memory.
- **Logging System:** Utilizes `RotatingFileHandler` for efficient logging with log rotation based on file size, ensuring that logs don't consume too much disk space.

This design prioritizes performance and resource management while maintaining flexibility and robustness in handling themes dynamically.']

