using System;
using System.Collections.Generic;
using System.Data.SqlClient;

public static IDataReader CreateParameterizedSqlCommand(SqlConnection connection, string sqlCommandText, List<object> parameters)
{
    try
    {
        using (var cmd = new SqlCommand(sqlCommandText, connection))
        {
            for (int i = 0; i < parameters.Count; i++)
            {
                var parameter = new SqlParameter($"@param{i}", parameters[i] ?? DBNull.Value);
                cmd.Parameters.Add(parameter);
            }

            connection.Open();
            return cmd.ExecuteReader(CommandBehavior.CloseConnection);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error executing SQL command: {ex.Message}");
        throw;
    }
}
