    printf("Generated PDU with RNTI: %d, CRC_FLAG: %u\n", pdu->rnti, pdu->crc_flag);

    free(pdu);
    return NULL;
}

int main() {
    srand(time(NULL));

    const int num_threads = 1000; // Number of PDUs to generate
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, generate_pdu, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    return 0;
}
