<?php
class PasswordDAO {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        try {
            $this->pdo = new PDO($dsn, $username, $password);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            error_log("Connection failed: " . $e->getMessage());
        }
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->validatePasswordStrength($newPassword)) {
            throw new Exception('Password does not meet strength requirements.');
        }

        try {
            $this->pdo->beginTransaction();

            $stmt = $this->pdo->prepare("UPDATE users SET password = :password WHERE id = :id");
            $stmt->execute([':password' => password_hash($newPassword, PASSWORD_DEFAULT), ':id' => $userId]);

            $this->pdo->commit();
        } catch (Exception $e) {
            $this->pdo->rollBack();
            error_log("Failed to update password for user ID {$userId}: " . $e->getMessage());
            throw $e;
        }
    }

    private function validatePasswordStrength($password) {
        // Example strength criteria
        return strlen($password) >= 8 && preg_match('/[A-Z]/', $password) &&
               preg_match('/[a-z]/', $password) && preg_match('/\d/', $password);
    }
}

// Usage example
try {
    $dao = new PasswordDAO('mysql:host=localhost;dbname=testdb', 'username', 'password');
    $userId = 1;
    $newPassword = "StrongPass123";

    $dao->updatePassword($userId, $newPassword);
    echo "Password updated successfully.";
} catch (Exception $e) {
    echo "Error: " . $e->getMessage();
}
?>
