SemaphoreManager* initializeNficSemaphores(size_t num_pdus, unsigned long rnti_min, unsigned long rnti_max) {
    if (rnti_min > rnti_max || rnti_max > MAX_RNTI || rnti_min < MIN_RNTI) {
        handleError("Invalid RNTI range");
    }

    SemaphoreManager *manager = malloc(sizeof(SemaphoreManager));
    if (!manager) {
        handleError("Failed to allocate memory for SemaphoreManager");
    }

    manager->pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_list) {
        free(manager);
        handleError("Failed to allocate memory for pdu list");
    }

    if (sem_init(&manager->semaphore, 0, 1)) {
        free(manager->pdu_list);
        free(manager);
        handleError("Semaphore initialization failed");
    }

    manager->count = 0;
    for (size_t i = 0; i < num_pdus; ++i) {
        sem_wait(&manager->semaphore);

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand(); // Randomly generate a valid tag
        pdu.RNTI = rnti_min + (rand() % (rnti_max - rnti_min + 1));

        int crcflag = rand() & 0x01; // Ensure CRCFLAG is either 0 or 1
        if (crcflag != 0 && crcflag != 1) {
            sem_post(&manager->semaphore);
            free(manager->pdu_list);
            free(manager);
            handleError("Invalid CRCFLAG value");
        }

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        // Validate against external data source here
        // ...

        manager->pdu_list[manager->count++] = pdu;

        sem_post(&manager->semaphore);
    }

    return manager;
}

void cleanupNficSemaphores(SemaphoreManager *manager) {
    if (manager) {
        sem_destroy(&manager->semaphore);
        free(manager->pdu_list);
        free(manager);
    }
}
