struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        bool CRCFLAG;
    } crcIndicationRel8Tag;
};

class DynamicNFAPI_CRC_Indication_Generator {
public:
    DynamicNFAPI_CRC_Indication_Generator(int rxMin, int rxMax, int rntiMin, int rntiMax)
        : rxRange{rxMin, rxMax}, rntiRange{rntiMin, rntiMax} {}

    void setFloatFieldRange(double minVal, double maxVal, bool inclusive) {
        floatRange = {minVal, maxVal, inclusive};
    }

    void setIntegerFieldRange(int minVal, int maxVal, bool inclusive) {
        intRange = {minVal, maxVal, inclusive};
    }

    NFAPI_CRC_INDICATION_PDU_T generateInstance() {
        std::lock_guard<std::mutex> lock(historyMutex);

        auto instance = NFAPI_CRC_INDICATION_PDU_T();
        instance.RX_UE_INFORMATION_TAG = getRandomValue(rxRange.first, rxRange.second);
        instance.RNTI = getRandomValue(rntiRange.first, rntiRange.second);
        instance.crcIndicationRel8Tag.CRCFLAG = getRandomBool();

        history.push_back(instance);

        updateStatistics(instance.RX_UE_INFORMATION_TAG, instance.RNTI);
        return instance;
    }

    void clearHistory() {
        std::lock_guard<std::mutex> lock(historyMutex);
        history.clear();
        statistics = {std::numeric_limits<int>::max(), std::numeric_limits<int>::min(),
                      std::numeric_limits<int>::max(), std::numeric_limits<int>::min(), 0};
    }

    int getTotalCount() const {
        return static_cast<int>(history.size());
    }

    int getMaxRXValue() const {
        return statistics.maxRx;
    }

    int getMinRXValue() const {
        return statistics.minRx;
    }

    int getMaxRNTIValue() const {
        return statistics.maxRnti;
    }

    int getMinRNTIValue() const {
        return statistics.minRnti;
    }

    double getAverageRXValue() const {
        if (statistics.totalRx == 0) return std::numeric_limits<double>::quiet_NaN();
        return static_cast<double>(statistics.sumRx) / statistics.totalRx;
    }

    double getAverageRNTIValue() const {
        if (statistics.totalRnti == 0) return std::numeric_limits<double>::quiet_NaN();
        return static_cast<double>(statistics.sumRnti) / statistics.totalRnti;
    }

    void overrideToString(std::string& str) const {
        str = "RX Range: [" + std::to_string(rxRange.first) + ", " + std::to_string(rxRange.second) +
              "], RNTI Range: [" + std::to_string(rntiRange.first) + ", " + std::to_string(rntiRange.second) + 
              "]\nTotal Generated Values: " + std::to_string(getTotalCount()) +
              "\nRX - Max: " + std::to_string(getMaxRXValue()) + ", Min: " + std::to_string(getMinRXValue()) +
              ", Avg: " + std::to_string(getAverageRXValue()) +
              "\nRNTI - Max: " + std::to_string(getMaxRNTIValue()) + ", Min: " + std::to_string(getMinRNTIValue()) +
              ", Avg: " + std::to_string(getAverageRNTIValue());
    }

private:
    struct Range {
        int min, max;
        bool inclusive;

        Range(int min = 0, int max = 0, bool inclusive = true)
            : min(min), max(max), inclusive(inclusive) {}

        int getRandomValue() const {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(min, max);
            return inclusive ? dis(gen) : (dis(gen) == max) ? --max : dis(gen);
        }
    };

    struct FloatRange {
        double min, max;
        bool inclusive;

        FloatRange(double min = 0.0, double max = 0.0, bool inclusive = true)
            : min(min), max(max), inclusive(inclusive) {}

        double getRandomValue() const {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_real_distribution<> dis(min, max);
            return inclusive ? dis(gen) : (dis(gen) == max) ? --max : dis(gen);
        }
    };

    struct Statistics {
        int minRx, maxRx, sumRx, totalRx;
        int minRnti, maxRnti, sumRnti, totalRnti;

        Statistics()
            : minRx(std::numeric_limits<int>::max()), maxRx(std::numeric_limits<int>::min()),
              sumRx(0), totalRx(0),
              minRnti(std::numeric_limits<int>::max()), maxRnti(std::numeric_limits<int>::min()),
              sumRnti(0), totalRnti(0) {}
    };

    Range rxRange, rntiRange;
    FloatRange floatRange;
    Statistics statistics;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> history;
    mutable std::mutex historyMutex;

    bool getRandomBool() const {
        return std::rand() % 2 == 0;
    }

    void updateStatistics(int rxValue, int rntiValue) {
        statistics.sumRx += rxValue;
        statistics.totalRx++;
        statistics.minRx = std::min(statistics.minRx, rxValue);
        statistics.maxRx = std::max(statistics.maxRx, rxValue);

        statistics.sumRnti += rntiValue;
        statistics.totalRnti++;
        statistics.minRnti = std::min(statistics.minRnti, rntiValue);
        statistics.maxRnti = std::max(statistics.maxRnti, rntiValue);
    }
};
