#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structures
typedef struct {
    int L3_PDU_TYPE;
    size_t payload_size;
    int error_indicator;  // Optional error indicator for out-of-sequence packets
} LAYER3_HEADER_T;

typedef struct {
    LAYER3_HEADER_T header;
} MAC_PDCP_PDU_T;

// Configuration limits (mocked external service)
typedef struct {
    int max_pdus;
    int allowed_pdu_types[256];  // Assuming a limit on L3_PDU_TYPE range
} ConfigService;

ConfigService current_config = { .max_pdus = 100, .allowed_pdu_types = {0} };

// PDCP PDU Manager
typedef struct {
    MAC_PDCP_PDU_T* pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_rwlock_t rw_lock; // Read-write lock for efficient access control
    int successful_insertions;
    int removals;
    int failures;

    pthread_t config_update_thread;
    volatile int update_required;  // Flag to indicate if a config update is needed
} PDCP_PDU_Manager;

// Function prototypes
void* config_updater(void* arg);
int fetch_new_config(ConfigService* new_config);

// Initialize the manager
void init_pdu_manager(PDCP_PDU_Manager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    pthread_rwlock_init(&manager->rw_lock, NULL);

    manager->pdus = malloc(initial_capacity * sizeof(MAC_PDCP_PDU_T));
    manager->capacity = initial_capacity;
    manager->count = 0;

    manager->successful_insertions = 0;
    manager->removals = 0;
    manager->failures = 0;

    manager->update_required = 1; // Start with an update

    pthread_create(&manager->config_update_thread, NULL, config_updater, manager);
}

// Clean up resources
void free_pdu_manager(PDCP_PDU_Manager* manager) {
    pthread_mutex_destroy(&manager->lock);
    pthread_rwlock_destroy(&manager->rw_lock);

    free(manager->pdus);

    // Ensure the update thread is terminated properly
    pthread_cancel(manager->config_update_thread);
    pthread_join(manager->config_update_thread, NULL);
}

// Function to add a PDU
int add_pdu(PDCP_PDU_Manager* manager, MAC_PDCP_PDU_T pdu) {
    if (pthread_rwlock_wrlock(&manager->rw_lock) != 0)
        return -1;

    // Check for duplicate L3_PDU_TYPE and payload_size
    for (size_t i = 0; i < manager->count; ++i) {
        MAC_PDCP_PDU_T* existing_pdu = &manager->pdus[i];
        if (existing_pdu->header.L3_PDU_TYPE == pdu.header.L3_PDU_TYPE &&
            existing_pdu->header.payload_size == pdu.header.payload_size) {
            pthread_rwlock_unlock(&manager->rw_lock);
            printf("Warning: Duplicate PDU not inserted.\n");
            return -1;
        }
    }

    // Check for capacity and allowed types
    if (manager->count >= manager->capacity ||
        !current_config.allowed_pdu_types[pdu.header.L3_PDU_TYPE]) {

        pthread_rwlock_unlock(&manager->rw_lock);
        printf("Error: Unable to add PDU due to configuration limits.\n");
        return -1;
    }

    // Resize array if needed
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        MAC_PDCP_PDU_T* new_pdus = realloc(manager->pdus, new_capacity * sizeof(MAC_PDCP_PDU_T));
        if (!new_pdus) {
            pthread_rwlock_unlock(&manager->rw_lock);
            return -1; // Memory allocation failed
        }
        manager->pdus = new_pdus;
        manager->capacity = new_capacity;
    }

    manager->pdus[manager->count++] = pdu;
    manager->successful_insertions++;
    pthread_rwlock_unlock(&manager->rw_lock);

    return 0;
}

// Function to remove a PDU
int remove_pdu(PDCP_PDU_Manager* manager, int index) {
    if (pthread_rwlock_wrlock(&manager->rw_lock) != 0)
        return -1;

    if (index < 0 || index >= manager->count) {
        pthread_rwlock_unlock(&manager->rw_lock);
        return -1; // Invalid index
    }

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->pdus[i] = manager->pdus[i + 1];
    }
    --manager->count;
    manager->removals++;
    pthread_rwlock_unlock(&manager->rw_lock);

    return 0;
}

// Function to retrieve a PDU
MAC_PDCP_PDU_T* get_pdu(PDCP_PDU_Manager* manager, int index) {
    if (pthread_rwlock_rdlock(&manager->rw_lock) != 0)
        return NULL;

    if (index < 0 || index >= manager->count) {
        pthread_rwlock_unlock(&manager->rw_lock);
        return NULL; // Invalid index
    }

    MAC_PDCP_PDU_T* pdu = &manager->pdus[index];
    pthread_rwlock_unlock(&manager->rw_lock);

    return pdu;
}

// Configuration updater thread function
void* config_updater(void* arg) {
    PDCP_PDU_Manager* manager = (PDCP_PDU_Manager*)arg;

    while (1) {
        if (manager->update_required) {
            ConfigService new_config;
            if (fetch_new_config(&new_config)) {
                pthread_rwlock_wrlock(&manager->rw_lock);
                current_config = new_config;
                pthread_rwlock_unlock(&manager->rw_lock);
                manager->update_required = 0; // Reset update flag
            }
        }

        // Sleep for a short duration before checking again
        usleep(100000); // 100 ms
    }

    return NULL;
}

// Mock implementation of fetching new configuration
int fetch_new_config(ConfigService* new_config) {
    // Simulate fetching new limits from an external service.
    static int counter = 0;

    if (counter % 5 == 0) {  // Update every few calls for demonstration
        new_config->max_pdus = 150;  // Example of dynamic configuration change
        for (int i = 0; i < 256; ++i) {
            new_config->allowed_pdu_types[i] = 1;
        }
        return 1;
    }

    return 0;
}
