import json

typedef struct IntegerArray {
    int *data;
    size_t capacity;
    size_t count;
} IntegerArray;

void initIntegerArray(IntegerArray *array) {
    array->capacity = 10; // Initial capacity
    array->count = 0;
    array->data = (int *)malloc(array->capacity * sizeof(int));
}

void freeIntegerArray(IntegerArray *array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->count = 0;
}

void addInteger(IntegerArray *array, int value) {
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->data = (int *)realloc(array->data, array->capacity * sizeof(int));
    }
    array->data[array->count++] = value;
}

int findLargestInteger(const IntegerArray *array) {
    if (array->count == 0) return INT_MIN; // Edge case: no integers
    int largest = array->data[0];
    for (size_t i = 1; i < array->count; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }
    return largest;
}

