                        int_val = int(part)
                        addInteger(&int_array, int_val)
                    except ValueError:
                        pass

                # Handle JSON parsing and registry update
                json_data = parseJsonStream(data)
                if json_data is not None:
                    addToRegistry(registry, str(json_data.get("id")), data)

                metrics.record("bytes_read", len(data))
                log(f"Processed {len(data)} bytes of data.", log_level)

    largest_int = findLargestInteger(&int_array)
    printf("The largest integer processed is: %d\n", largest_int);

    freeIntegerArray(&int_array);
    freeRegistry(registry);

