// Cache to store precomputed values
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T *cache[CACHE_SIZE];
int cache_index = 0;

// Function to generate random CRC flag
int generate_random_crcflag() {
    return rand() % 2; // Random 0 or 1 for simplicity
}

// Function to allocate memory and initialize NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_pdu_array(size_t count) {
    if (count == 0)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        // Placeholder initialization
        pdus[i].ue_info_tag.dummy_field = rand(); 
        pdus[i].rnti.RNTI = (unsigned short)rand();
        pdus[i].crcflag = generate_random_crcflag();
    }

    return pdus;
}

// Function to handle caching of PDU structures
NFAPI_CRC_INDICATION_PDU_T* get_cached_pdu(size_t count) {
    pthread_mutex_lock(&cache_lock);

    if (count > CACHE_SIZE || cache_index == 0) {
        pthread_mutex_unlock(&cache_lock);
        return NULL; // No suitable cached value found
    }

    NFAPI_CRC_INDICATION_PDU_T *cached_pdu = cache[--cache_index];
    pthread_mutex_unlock(&cache_lock);

    return cached_pdu;
}

// Function to cache PDU structures
void cache_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cache_lock);

    if (cache_index < CACHE_SIZE) {
        cache[cache_index++] = pdu;
    }

    pthread_mutex_unlock(&cache_lock);
}

// Thread-safe function to generate and manage PDU structures
NFAPI_CRC_INDICATION_PDU_T* generate_pdus(size_t count) {
    NFAPI_CRC_INDICATION_PDU_T *cached_pdu = get_cached_pdu(count);

    if (cached_pdu != NULL)
        return cached_pdu;

    NFAPI_CRC_INDICATION_PDU_T *pdus = create_pdu_array(count);

    cache_pdu(pdus); // Cache the newly created PDUs
    return pdus;
}

// Function to deallocate PDU array and clear cache
void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus)
        free(pdus);

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i]) {
            free(cache[i]);
            cache[i] = NULL;
        }
    }
    cache_index = 0;
    pthread_mutex_unlock(&cache_lock);
}

// Example usage
