    if (size <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < size; ++i) {
        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = i * 10;
        array[i].CRC_INDICATION_REL8_TAG = i * 5;

        // Set CRCFLAG based on a pattern derived from the index
        array[i].CRCFLAG = (i % 2 == 0) ? 0xFF : 0x00; 
    }

    pthread_mutex_unlock(&mutex);
    pthread_mutex_destroy(&mutex);

    return array;
}

void free_crc_array(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (!array) return;

    free(array);
}
