import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;
import okhttp3.HttpUrl;
import okhttp3.Request;
import okhttp3.OkHttpClient;

public class RequestBuilder {
    private static final Logger logger = Logger.getLogger(RequestBuilder.class.getName());

    private String url;
    private Map<String, String> headers = new HashMap<>();
    private Map<String, String> queryParams = new HashMap<>();
    private OkHttpClient client;

    public RequestBuilder(String url) {
        this.url = url;
        this.client = new OkHttpClient.Builder().build();
    }

    public void addHeader(String key, String value) {
        headers.put(key, value);
    }

    public void addQueryParam(String key, String value) throws UnsupportedEncodingException {
        queryParams.put(key, URLEncoder.encode(value, "UTF-8"));
    }

    public Request buildRequest(boolean disableCertValidation) {
        if (disableCertValidation) {
            client = new OkHttpClient.Builder()
                    .hostnameVerifier((hostname, session) -> true)
                    .build();
        }

        HttpUrl.Builder urlBuilder = HttpUrl.parse(url).newBuilder();
        for (Map.Entry<String, String> entry : queryParams.entrySet()) {
            urlBuilder.addQueryParameter(entry.getKey(), entry.getValue());
        }

        Request.Builder requestBuilder = new Request.Builder().url(urlBuilder.build());

        headers.forEach(requestBuilder::addHeader);

        logger.info("Building request to URL: " + requestBuilder.url());

        return requestBuilder.build();
    }

    public String generateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();

            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            logger.severe("MD5 algorithm not found: " + e.getMessage());
            return null;
        }
    }
}
