    for (int i = 0; i < sizeof(pdusMemoryPool) / sizeof(pdusMemoryPool[0]); ++i) {
        pdusMemoryPool[i] = malloc(sizeof(PDUSessionRecord));
    }
}

PDUSessionRecord* allocatePDURecord() {
