    manager->count = 0;
}

void populateUEContextManager(UEContextManager* manager, int ueId, const char* rrcState) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_UES) {
        pthread_mutex_unlock(&manager->lock);
        return; // No more space
    }

    LTEUEContext *context = &manager->contexts[manager->count++];
    context->ueId = ueId;
    strncpy(context->rrcState, rrcState, sizeof(context->rrcState));

    context->pduSessions.records = malloc(sizeof(PDUSessionRecord) * MAX_SESSIONS);
    context->pduSessions.count = 0;

    pthread_mutex_unlock(&manager->lock);
}

void cleanupUEContextManager(UEContextManager* manager) {
