import requests
import time
import logging
from sqlalchemy import create_engine, text

logging.basicConfig(level=logging.INFO)

API_URL = "https://example.com/api/user_subscription"
DB_CONNECTION_STRING = "sqlite:///users.db"

def fetch_user_subscriptions():
    retries = 5
    backoff_factor = 1.5

    for attempt in range(retries):
        try:
            response = requests.get(API_URL, timeout=10)
            response.raise_for_status()

            data = response.json()
            process_and_store(data)
            break
        except (requests.exceptions.RequestException, ValueError) as e:
            logging.error(f"Attempt {attempt + 1} failed: {e}")
            if attempt < retries - 1:
                sleep_time = backoff_factor ** attempt
                logging.info(f"Retrying in {sleep_time:.2f} seconds...")
                time.sleep(sleep_time)
            else:
                logging.critical("All retry attempts failed.")
                raise

def process_and_store(data):
    engine = create_engine(DB_CONNECTION_STRING)
    with engine.connect() as connection:
        for user_data in data.get('users', []):
            subscription_id = user_data['subscriptionId']
            # Add more fields as necessary
            query = text("""
                INSERT INTO subscriptions (subscription_id, ...) 
                VALUES (:subscription_id, ...)
                ON CONFLICT(subscription_id) DO UPDATE SET ...
            """)
            connection.execute(query, **user_data)

if __name__ == "__main__":
    fetch_user_subscriptions()
