        if (new_size != list->capacity) {
            config_list_resize(list, new_size, /* MemoryPool */ NULL); // Pass actual memory pool
        }

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

// Example usage
int main() {
    MemoryPool mp;
    mem_pool_init(&mp, sizeof(LTE_ENB_NODE_CFG_S), 10000);

    ConfigList config_list;
    if (config_list_init(&config_list, 100, &mp) != 0) {
