#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_METRICS 1000
#define RANDOM_STRING_LENGTH 64
#define CHAR_SET "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
#define CHAR_SET_LEN (sizeof(CHAR_SET) - 1)

typedef struct {
    int RxUeInfoTag;
    unsigned int Rnti;
    unsigned int CrcIndication;
} MetricPdu;

unsigned int generateRandomSequence() {
    srand(time(NULL) ^ (uintptr_t)pthread_self());
    return rand();
}

void generateNetworkMetrics(MetricPdu metrics[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        unsigned int sequence = generateRandomSequence();
        metrics[i].RxUeInfoTag = rand() % 1000;
        metrics[i].Rnti = rand() % 4294967295;
        metrics[i].CrcIndication = (metrics[i].RxUeInfoTag << 16) | 
                                   (metrics[i].Rnti & 0xFFFF) | 
                                   (sequence & 0xFF);
    }
}

void generateRandomString(char *str, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        str[i] = CHAR_SET[rand() % CHAR_SET_LEN];
    }
    str[length] = '\0';
}

unsigned int calculateChecksum(const MetricPdu metrics[], size_t count, const char *randomString) {
    unsigned int checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum ^= metrics[i].RxUeInfoTag ^ metrics[i].Rnti ^ metrics[i].CrcIndication;
    }
    while (*randomString) {
        checksum ^= *randomString++;
    }
    return checksum;
}

void generateAndHashMetrics(MetricPdu metrics[], size_t count, char *hashOutput, size_t outputLength) {
    if (count > MAX_METRICS) count = MAX_METRICS;

    char randomString[RANDOM_STRING_LENGTH + 1];
    generateRandomString(randomString, RANDOM_STRING_LENGTH);

    unsigned int checksum = calculateChecksum(metrics, count, randomString);
    snprintf(hashOutput, outputLength, "%08X", checksum); // Format as hex string
}

int main() {
    MetricPdu metrics[MAX_METRICS];
    char hashOutput[9]; // 8 digits + null terminator for the checksum

    generateNetworkMetrics(metrics, MAX_METRICS);

    generateAndHashMetrics(metrics, MAX_METRICS, hashOutput, sizeof(hashOutput));

    printf("Checksum: %s\n", hashOutput);

    return 0;
}
```']

