    if (num_pdus <= 0 || rnti_min > rnti_max) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    uint16_t current_rnti;
    size_t valid_count = 0;

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_pdus; ++i) {
        do {
            current_rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        } while (current_rnti < rnti_min || current_rnti > rnti_max);

        pdus[i].crc_tag.RX_UE_INFORMATION_TAG = rand();
        pdus[i].crc_tag.RNTI = current_rnti;
        pdus[i].crc_tag.CRCFLAG = rand() % 2;

        valid_count++;
    }

    pthread_mutex_unlock(&mutex);

    // Shrink the array to only include valid entries
    NFAPI_CRC_INDICATION_PDU_T *shrunk_array = realloc(pdus, valid_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!shrunk_array) {
        free(pdus);
        return NULL;
    }

    return shrunk_array;
}

void deallocate_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        pthread_mutex_lock(&mutex);
        free(pdus);
        pthread_mutex_unlock(&mutex);
    }
}
