// Simple logging mechanism
static char log_buffer[LOG_BUFFER_SIZE];
static size_t log_offset = 0;

void flush_log() {
    if (log_offset > 0) {
        // Asynchronously send to external logging service
        printf("%s", log_buffer);
        memset(log_buffer, 0, LOG_BUFFER_SIZE);
        log_offset = 0;
    }
}

void log_message(const char *message) {
    size_t len = strlen(message);
    if (log_offset + len < LOG_BUFFER_SIZE) {
        strcpy(&log_buffer[log_offset], message);
        log_offset += len;
        log_buffer[log_offset++] = '\n';
    } else {
        flush_log();
        printf("%s", message);
    }
}

int populate_nfa_pi_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t num_rnti_values, unsigned int *rnti_values) {
    if (!pdus || !num_rnti_values || !rnti_values) return -1;

    // Use a hash set to prevent duplicate RNTIs
    unsigned int seen_rntis[MAX_STRUCTURES] = {0};
    size_t count = 0;

    for (size_t i = 0; i < num_rnti_values && count < MAX_STRUCTURES; ++i) {
        unsigned int rnti = rnti_values[i];

        if (!seen_rntis[rnti % MAX_STRUCTURES]) {
            seen_rntis[rnti % MAX_STRUCTURES] = 1;
            (*pdus)[count].ue_info_tag.RNTI = rnti;
            (*pdus)[count].rnti = rnti;
            (*pdus)[count].crc_indication_rel8_tag.CRCFLAG = rand() & 1; // Random CRCFLAG
            count++;
        }
    }

    if (count > 0) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Successfully allocated %zu structures.", count);
        log_message(log_msg);
    } else {
        log_message("No valid RNTI values provided.");
    }

    return count;
}

int main() {
    srand((unsigned int)time(NULL));

    // Simulate external RNTI input
    unsigned int rnti_values[] = {101, 202, 303, 404, 505, 606, 707, 808, 909, 1010};
    size_t num_rnti_values = sizeof(rnti_values) / sizeof(rnti_values[0]);

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        log_message("Memory allocation failed for pdus.");
        return -1;
    }

