} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} NFAPICRCList;

// Function prototypes
NFAPICRCList* init_crc_list();
void destroy_crc_list(NFAPICRCList* list);
int add_pdu(NFAPICRCList* list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti);

// Initialize the list
NFAPICRCList* init_crc_list() {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Destroy the list and free resources
void destroy_crc_list(NFAPICRCList* list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to add a PDU with unique RNTI
int add_pdu(NFAPICRCList* list, RX_UE_INFORMATION_TAG ue_info_tag, uint16_t rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Check for existing RNTI
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2;  // Duplicate RNTI
        }
        current = current->next;
    }

    // Allocate new node
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3;  // Memory allocation failure
    }

    // Populate the new node
    new_node->ue_info_tag = ue_info_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2;  // Random CRCFLAG (0 or 1)
    new_node->next = list->head;

    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

