    RadioResourceParameters radio_resources;
} NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T;

typedef struct Node {
    NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T data;
    struct Node* next;
} Node;

typedef struct {
    Node** pool;
    size_t pool_size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = (Node**)calloc(initial_size, sizeof(Node*));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->pool_size = initial_size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);

    for (size_t i = 0; i < initial_size; ++i) {
        mp->pool[i] = (Node*)malloc(sizeof(Node));
        if (!mp->pool[i]) {
            while (--i >= 0) free(mp->pool[i]);
            free(mp->pool);
            free(mp);
            return NULL;
        }
    }

    return mp;
}

void* pool_allocate(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used == mp->pool_size) {
        size_t new_size = mp->pool_size * 2;
        Node** new_pool = (Node**)realloc(mp->pool, new_size * sizeof(Node*));
        if (!new_pool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        mp->pool = new_pool;

        for (size_t i = mp->pool_size; i < new_size; ++i) {
            mp->pool[i] = (Node*)malloc(sizeof(Node));
            if (!mp->pool[i]) {
                while (--i >= mp->pool_size) free(mp->pool[i]);
                pthread_mutex_unlock(&mp->lock);
                return NULL;
            }
        }

        mp->pool_size = new_size;
    }

    Node* node = mp->pool[mp->used++];
    pthread_mutex_unlock(&mp->lock);

    return node;
}

void pool_free(MemoryPool* mp, void* ptr) {
    if (!ptr) return;

    pthread_mutex_lock(&mp->lock);
    size_t index = --mp->used;
    Node* node = (Node*)ptr;

    // Optionally reset the memory here if needed
    for (size_t i = index; i < mp->pool_size - 1; ++i) {
        mp->pool[i] = mp->pool[i + 1];
    }

    pthread_mutex_unlock(&mp->lock);
}

void serialize_list(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    while (head) {
        fwrite(&(head->data), sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T), 1, file);
        head = head->next;
    }

    fclose(file);
}

Node* deserialize_list(const char* filename, MemoryPool* mp) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    Node* head = NULL;
    Node** tail = &head;

    while (1) {
        NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T data;
        size_t read_items = fread(&data, sizeof(NFAPI_RRC_CONNECTION_RECONFIGURATION_REQUEST_T), 1, file);
        if (read_items == 0) break;

        Node* node = pool_allocate(mp);
        if (!node) {
            // Handle memory exhaustion gracefully
            while (head) {
                Node* temp = head;
                head = head->next;
                pool_free(mp, temp);
            }
            fclose(file);
            return NULL;
        }

        node->data = data;
        node->next = NULL;

        *tail = node;
        tail = &node->next;
    }

    fclose(file);
    return head;
}

void prune_list(Node** head) {
    // Implement pruning logic based on criteria such as idle time or access frequency
    // This is a placeholder for the actual implementation
}

void initialize_network_interface(MemoryPool* mp, const char* filename) {
    Node* list = deserialize_list(filename, mp);

    if (!list) {
        printf("Failed to load existing configurations. Starting with an empty list.\n");
        list = (Node*)pool_allocate(mp);
        if (!list) {
            fprintf(stderr, "Memory allocation failed during initialization.\n");
            return;
        }
        list->next = NULL;
    }

    // Example of adding a new configuration
    Node* new_node = pool_allocate(mp);
    if (new_node) {
        new_node->data.rrc_configuration_update = 1;
        new_node->data.cell_id = 12345;
        new_node->data.radio_resources.transmission_power = 20;
        new_node->data.radio_resources.bandwidth_part_carrier_frequency = 1000;
        new_node->data.radio_resources.cell_specific_reference_signal_power = 30;

        Node* current = list;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    serialize_list(list, filename);

    // Periodically prune the list
    prune_list(&list);
}

void cleanup_memory_pool(MemoryPool* mp) {
    if (!mp) return;

    for (size_t i = 0; i < mp->used; ++i) {
        free(mp->pool[i]);
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

int main() {
    MemoryPool* pool = create_memory_pool(INITIAL_POOL_SIZE);
    if (!pool) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return 1;
    }

    const char* filename = "configurations.dat";
    initialize_network_interface(pool, filename);

    cleanup_memory_pool(pool);
    return 0;
}
