} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t totalSize;
} PowerLevelsManager;

PowerLevelsManager* create_manager() {
    PowerLevelsManager* manager = (PowerLevelsManager*)malloc(sizeof(PowerLevelsManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->totalSize = 0;
    return manager;
}

void destroy_manager(PowerLevelsManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_or_update_entry(PowerLevelsManager* manager, TX_POWER_LEVELS entry) {
    pthread_mutex_lock(&manager->lock);

    Node** tracer = &manager->head;
    while (*tracer && ((*tracer)->data.bandIndex < entry.bandIndex ||
                       ((*tracer)->data.bandIndex == entry.bandIndex &&
                        (*tracer)->data.timeStamp != entry.timeStamp))) {
        tracer = &(*tracer)->next;
    }

    if (*tracer) {
        // Update existing
        (*tracer)->data = entry;
    } else {
        // Add new
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle allocation failure gracefully
        }
        newNode->data = entry;
        newNode->next = *tracer;
        *tracer = newNode;
    }

    manager->totalSize++;
    pthread_mutex_unlock(&manager->lock);
}

int get_max_power_level(PowerLevelsManager* manager, int bandIndex) {
    pthread_mutex_lock(&manager->lock);

    int maxPower = -1;
    Node* current = manager->head;
    while (current) {
        if (current->data.bandIndex == bandIndex && 
            current->data.powerLevel > maxPower) {
            maxPower = current->data.powerLevel;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return maxPower;
}

int serialize_data(PowerLevelsManager* manager, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    Node* current = manager->head;
    while (current) {
        fwrite(&current->data, sizeof(TX_POWER_LEVELS), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    fclose(file);
    return 0;
}

int deserialize_data(PowerLevelsManager* manager, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    // Clear existing data
    destroy_manager(manager);

    TX_POWER_LEVELS entry;
    while (fread(&entry, sizeof(TX_POWER_LEVELS), 1, file)) {
        add_or_update_entry(manager, entry);
    }

    fclose(file);
    return 0;
}

