void find_and_print_largest(int *array, size_t size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }

    int max = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to validate input and manage NFAPI_CRC_INDICATION_PDU_T structures
void process_input_and_manage_structures(int min_range, int max_range) {
    int *array = NULL;
    size_t capacity = 0, size = 0;

    printf("Enter integers (type 'end' to finish):\n");
    char input[100];
    while (1) {
        if (!fgets(input, sizeof(input), stdin)) break;

        if (strncmp(input, "end", 3) == 0) break;

        int value;
        if (sscanf(input, "%d", &value) != 1 || value < min_range || value > max_range) {
            printf("Invalid input. Please enter an integer within range %d to %d.\n", min_range, max_range);
            continue;
        }

        // Check for duplicates
        int is_duplicate = 0;
        for (size_t i = 0; i < size; ++i) {
            if (array[i] == value) {
                is_duplicate = 1;
                break;
            }
        }

        if (is_duplicate) {
            printf("Duplicate detected. Please enter a unique integer.\n");
            continue;
        }

        // Resize array if necessary
        if (size >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            int *new_array = realloc(array, capacity * sizeof(int));
            if (!new_array) {
                fprintf(stderr, "Memory allocation failed\n");
                free(array);
                return;
            }
            array = new_array;
        }

        // Add value to the array
        array[size++] = value;
    }

    find_and_print_largest(array, size);

    // Manage NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    size_t struct_capacity = 0, struct_size = 0;

    for (size_t i = 0; i < size; ++i) {
        if (struct_size >= struct_capacity) {
            struct_capacity = struct_capacity ? struct_capacity * 2 : 4;
            NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(structures, struct_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_structures) {
                fprintf(stderr, "Memory allocation failed\n");
                free(array);
                free(structures);
                return;
            }
            structures = new_structures;
        }

        // Assuming RNTI is the same as the integer value for simplicity
        structures[struct_size].RNTI = array[i];
        structures[struct_size].RX_UE_INFORMATION_TAG = rand() % 1000; // Simulated update from external source
        structures[struct_size].crc_tag.CRCFLAG = rand() % 2;

        struct_size++;
    }

    printf("Managed %zu NFAPI_CRC_INDICATION_PDU_T structures\n", struct_size);

    free(array);
    free(structures);
}

