['Below is a C implementation of a dynamic array management function for `NFAPI_CRC_INDICATION_PDU_T` structures in an embedded system environment. This code includes thread-safe access, error handling, logging of allocation success, and cleanup.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_STRUCTURES 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set flag
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array management structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
} CRC_ArrayManager;

// Function prototypes
int initialize_array_manager(CRC_ArrayManager *manager, size_t initial_capacity);
void destroy_array_manager(CRC_ArrayManager *manager);
int add_structure(CRC_ArrayManager *manager, uint32_t rx_info_tag, uint16_t rnti);
void clear_structures(CRC_ArrayManager *manager);

// Initialize the dynamic array manager
int initialize_array_manager(CRC_ArrayManager *manager, size_t initial_capacity) {
    pthread_mutex_lock(&mutex);
    if (initial_capacity > MAX_STRUCTURES) {
        initial_capacity = MAX_STRUCTURES;
    }

    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return -1; // Allocation failure
    }

    manager->capacity = initial_capacity;
    manager->count = 0;

    pthread_mutex_unlock(&mutex);
    printf("Array initialized with capacity: %zu\n", initial_capacity);
    return 0; // Success
}

// Add a new structure to the dynamic array
int add_structure(CRC_ArrayManager *manager, uint32_t rx_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&mutex);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) {
            new_capacity = MAX_STRUCTURES;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            printf("Reallocation failed.\n");
            pthread_mutex_unlock(&mutex);
            return -1; // Reallocation failure
        }

        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *structure = &manager->array[manager->count++];
    structure->RX_UE_INFORMATION_TAG = rx_info_tag;
    structure->RNTI = rnti;

    // Randomly set the CRCFLAG
    structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pthread_mutex_unlock(&mutex);
    printf("Added structure: RX_UE_INFORMATION_TAG=%u, RNTI=%hu\n", rx_info_tag, rnti);

    return 0; // Success
}

// Clear all allocated structures
void clear_structures(CRC_ArrayManager *manager) {
    pthread_mutex_lock(&mutex);

    if (manager->array) {
        free(manager->array);
        manager->array = NULL;
        manager->capacity = 0;
        manager->count = 0;

        printf("All structures cleared.\n");
    }

    pthread_mutex_unlock(&mutex);
}

// Destroy the dynamic array manager
void destroy_array_manager(CRC_ArrayManager *manager) {
    clear_structures(manager);
    pthread_mutex_destroy(&mutex);
}
