#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRUCTURES 5000

typedef struct {
    int rfchain;
    float rsrq;
    float sinr;
    int nrOfReceivedSymbols;
} LTEPHY_RX_STATS;

typedef struct {
    LTEPHY_RX_STATS *statsArray;
    size_t count;
    pthread_mutex_t lock;
} StatsManager;

void initializeStats(LTEPHY_RX_STATS *stats, int rfchain, float rsrq, float sinr, int symbols) {
    stats->rfchain = rfchain;
    stats->rsrq = rsrq;
    stats->sinr = sinr;
    stats->nrOfReceivedSymbols = symbols;
}

void initializeStatsManager(StatsManager *manager) {
    manager->statsArray = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int allocateStats(StatsManager *manager, size_t numStructures, int rfchain, float rsrq, float sinr, int symbols) {
    pthread_mutex_lock(&manager->lock);

    if (numStructures > MAX_STRUCTURES) {
        fprintf(stderr, "Requested number of structures exceeds maximum limit.\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    LTEPHY_RX_STATS *newArray = realloc(manager->statsArray, numStructures * sizeof(LTEPHY_RX_STATS));
    if (!newArray) {
        fprintf(stderr, "Memory reallocation failed.\n");
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }

    for (size_t i = manager->count; i < numStructures; ++i) {
        initializeStats(&newArray[i], rfchain, rsrq, sinr, symbols);
    }

    manager->statsArray = newArray;
    manager->count = numStructures;

    pthread_mutex_unlock(&manager->lock);
    printf("Successfully allocated %zu structures.\n", numStructures);

    return 0;
}

void clearStats(StatsManager *manager) {
    pthread_mutex_lock(&manager->lock);

    free(manager->statsArray);
    manager->statsArray = NULL;
    manager->count = 0;

    pthread_mutex_unlock(&manager->lock);
}

void iterateAndProcessStats(StatsManager *manager, void (*process)(LTEPHY_RX_STATS *)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        process(&manager->statsArray[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

void reinitializeStats(StatsManager *manager, int rfchain, float rsrq, float sinr, int symbols) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        initializeStats(&manager->statsArray[i], rfchain, rsrq, sinr, symbols);
    }

    pthread_mutex_unlock(&manager->lock);
}

void freeResources(StatsManager *manager) {
    clearStats(manager);
    pthread_mutex_destroy(&manager->lock);
}

// Example usage of the StatsManager
void processExample(LTEPHY_RX_STATS *stats) {
    printf("Processing: rfchain=%d, rsrq=%.2f, sinr=%.2f, symbols=%d\n",
           stats->rfchain, stats->rsrq, stats->sinr, stats->nrOfReceivedSymbols);
}

int main() {
    StatsManager manager;
    initializeStatsManager(&manager);

    if (allocateStats(&manager, 1000, 1, -10.5, 15.2, 200) == 0) {
        iterateAndProcessStats(&manager, processExample);
    }

    reinitializeStats(&manager, 2, -12.3, 18.4, 300);

    freeResources(&manager);
    return 0;
}
