        size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (allocated_count + 1);

        if (total_size > *buffer_size) {
            pthread_mutex_unlock(&mutex);
            return -1; // Error code: insufficient buffer size
