} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* head;
    size_t size;
    void (*validate)(NFAPI_CRC_INDICATION_PDU_T*);
} CRCLinkedList;

CRCLinkedList* create_list(void (*validate_func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
    list->validate = validate_func ? validate_func : NULL;

    return list;
}

void destroy_list(CRCLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_pdu(CRCLinkedList* list, RX_UE_INFORMATION_TAG ue_info, RNTI rnti, CRC_INDICATION_REL8_TAG crc_tag) {
    if (!list || list->size >= MAX_LIST_SIZE) return -1;

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return -1;

    new_node->ue_info = ue_info;
    new_node->rnti = rnti;
    new_node->crc_tag = crc_tag;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    // Trim the oldest entry if size exceeds threshold
    if (list->size > MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void validate_list(CRCLinkedList* list) {
    if (!list || !list->validate) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;

        // Validate current node
        if (!list->validate(current)) {
            NFAPI_CRC_INDICATION_PDU_T* invalid_node = current;
            current = next;

            // Remove the invalid node from list
            if (invalid_node == list->head) {
                list->head = next;
            } else {
                while (current && current->next != invalid_node) {
                    current = current->next;
                }
                if (current) current->next = next;
            }

            free(invalid_node);
            list->size--;
        } else {
            current = next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Example validation function
int example_validate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement your validation logic here
    return 1; // Return 0 if the node is invalid
}
