void init_logging(const char *logfile) {
    pthread_mutex_lock(&log_lock);
    log_file = fopen(logfile, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&log_lock);
}

// Log messages with different levels
void log_message(const char *message, int level) {
    pthread_mutex_lock(&log_lock);
    fprintf(log_file, "Level %d: %s\n", level, message);
    fflush(log_file);
    pthread_mutex_unlock(&log_lock);
}

// Create a custom memory pool
CustomMemoryPool* create_memory_pool(size_t element_size, size_t initial_capacity) {
    CustomMemoryPool *pool = (CustomMemoryPool *)malloc(sizeof(CustomMemoryPool));
    if (!pool) {
        log_message("Failed to allocate memory for memory pool", 1);
        return NULL;
    }

    pool->element_size = element_size;
    pool->capacity = initial_capacity;
    pool->buffer = malloc(element_size * initial_capacity);
    if (!pool->buffer) {
        free(pool);
        log_message("Failed to allocate buffer in memory pool", 1);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

// Allocate structures from the custom memory pool
int allocate_structures(CustomMemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T **structures, size_t num_elements) {
    int success_count = 0;

    if (num_elements > pool->capacity) {
        void *new_buffer = realloc(pool->buffer, pool->element_size * num_elements);
        if (!new_buffer) {
            log_message("Reallocation failed; insufficient memory", 1);
            return 0;
        }
        pool->buffer = new_buffer;
        pool->capacity = num_elements;
    }

    pthread_mutex_lock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T *start_ptr = (NFAPI_CRC_INDICATION_PDU_T *)pool->buffer;

    for (size_t i = 0; i < num_elements; ++i) {
        start_ptr[i].RX_UE_INFORMATION_TAG = rand(); // Assume valid tag generation
        start_ptr[i].RNTI = getenv("DEFAULT_RNTI") ? atoi(getenv("DEFAULT_RNTI")) : 0;
        start_ptr[i].CRC_INDICATION_REL8_TAG = i;    // Example assignment
        start_ptr[i].CRCFLAG = rand() % 2;           // Randomly set CRCFLAG

        if (++success_count == num_elements) break;
    }

    *structures = start_ptr;
    pthread_mutex_unlock(&pool->lock);

    return success_count;
}

