        return NULL;
    }
    return ptr;
}

void thread_safe_free(void *ptr) {
    free(ptr);
}

ErrorCode manage_nfa_crc_indications(NFAPI_CRC_INDICATION_PDU_T **buffer,
                                    size_t *current_size, size_t new_required_size) {

    pthread_mutex_lock(&lock);

    if (new_required_size > *current_size) {
        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(*buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_required_size);

        if (!temp) {
            fprintf(stderr, "Re-allocation failed\n");
            pthread_mutex_unlock(&lock);
            return INSUFFICIENT_MEMORY;
        }

        *buffer = temp;
        *current_size = new_required_size;
    }

    pthread_mutex_unlock(&lock);

    return SUCCESS;
}

void print_rnti_values(NFAPI_CRC_INDICATION_PDU_T *buffer, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("RNTI: %d\n", buffer[i].RNTI);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *crc_buffer = NULL;
    size_t current_size = 0;

    ErrorCode status = manage_nfa_crc_indications(&crc_buffer, &current_size, INITIAL_BUFFER_SIZE);
    if (status != SUCCESS) {
        return EXIT_FAILURE;
    }

    // Simulate adding structures
    for (size_t i = 0; i < current_size; ++i) {
        crc_buffer[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_buffer[i].RNTI = rand() % 1000;
        crc_buffer[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        crc_buffer[i].CRCFLAG = (rand() % 2) == 0 ? 1 : 0; // Simulated CRC check
    }

    print_rnti_values(crc_buffer, current_size);

    // Increase buffer size if needed due to network traffic increase
    status = manage_nfa_crc_indications(&crc_buffer, &current_size, current_size * 2);
    if (status != SUCCESS) {
        thread_safe_free(crc_buffer);
        return EXIT_FAILURE;
    }

    print_rnti_values(crc_buffer, current_size);

    // Cleanup
    thread_safe_free(crc_buffer);

    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
