#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    int RACH_REQUEST;
    double PHY_RX_STATS;
} LTE_DL_FRAMEINFO;

typedef struct {
    LTE_DL_FRAMEINFO* array;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} LTE_DL_FRAMEINFO_ARRAY;

// Initialize the dynamic array
void init_array(LTE_DL_FRAMEINFO_ARRAY* arr, size_t initial_capacity) {
    arr->array = (LTE_DL_FRAMEINFO*)malloc(initial_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (!arr->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initial_capacity;
    arr->count = 0;
    pthread_rwlock_init(&arr->lock, NULL);
}

// Resize the dynamic array
void resize_array(LTE_DL_FRAMEINFO_ARRAY* arr, size_t new_capacity) {
    LTE_DL_FRAMEINFO* temp = (LTE_DL_FRAMEINFO*)realloc(arr->array, new_capacity * sizeof(LTE_DL_FRAMEINFO));
    if (!temp) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    arr->array = temp;
    arr->capacity = new_capacity;
}

// Add a new entry or update an existing one
void add_or_update_entry(LTE_DL_FRAMEINFO_ARRAY* arr, LTE_DL_FRAMEINFO info) {
    pthread_rwlock_wrlock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->array[i].UE_ID == info.UE_ID) {
            arr->array[i] = info;
            pthread_rwlock_unlock(&arr->lock);
            return;
        }
    }

    if (arr->count >= arr->capacity) {
        resize_array(arr, arr->capacity * 2);
    }

    arr->array[arr->count++] = info;
    pthread_rwlock_unlock(&arr->lock);
}

// Calculate aggregate statistics
double calculate_aggregate_stats(const LTE_DL_FRAMEINFO_ARRAY* arr) {
    double sum = 0.0;
    pthread_rwlock_rdlock(&arr->lock);

    for (size_t i = 0; i < arr->count; ++i) {
        sum += arr->array[i].PHY_RX_STATS;
    }

    pthread_rwlock_unlock(&arr->lock);
    return sum / arr->count;
}

// Free resources
void free_array(LTE_DL_FRAMEINFO_ARRAY* arr) {
    pthread_rwlock_destroy(&arr->lock);
    free(arr->array);
}

// Unit tests using CMocka
#include <cmocka.h>

static void test_add_or_update_entry(void** state) {
    LTE_DL_FRAMEINFO_ARRAY array;
    init_array(&array, 2);

    LTE_DL_FRAMEINFO info1 = {1, 0, 10.0};
    add_or_update_entry(&array, info1);
    assert_int_equal(array.count, 1);
    assert_double_equal(array.array[0].PHY_RX_STATS, 10.0);

    LTE_DL_FRAMEINFO info2 = {1, 1, 20.0};
    add_or_update_entry(&array, info2);
    assert_int_equal(array.count, 1);
    assert_double_equal(array.array[0].PHY_RX_STATS, 20.0);

    free_array(&array);
}

static void test_calculate_aggregate_stats(void** state) {
    LTE_DL_FRAMEINFO_ARRAY array;
    init_array(&array, 2);

    add_or_update_entry(&array, (LTE_DL_FRAMEINFO){1, 0, 10.0});
    add_or_update_entry(&array, (LTE_DL_FRAMEINFO){2, 0, 20.0});

    double avg = calculate_aggregate_stats(&array);
    assert_double_equal(avg, 15.0);

    free_array(&array);
}

int main(void) {
    const struct CMUnitTest tests[] = {
        cmocka_unit_test(test_add_or_update_entry),
        cmocka_unit_test(test_calculate_aggregate_stats)
    };

    return cmocka_run_group_tests(tests, NULL, NULL);
}
