    for (int i = 0; i < max_count; ++i) {
        if (!is_data_source_available()) {
            log_message("WARNING", "Data source unavailable, retrying...");
            usleep(100000); // Retry after a short delay
            continue;
        }

        (*pdu_array)[i].tag.RX_UE_INFORMATION_TAG = rand() % 256;
        (*pdu_array)[i].tag.RNTI = rand() % 65536;
        (*pdu_array)[i].CRCFLAG = rand() % 2;

        sleep(rand() % 5 + 1); // Simulate random delay between 1ms to 5ms

        if ((size_t)(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > memory_limit) {
            log_message("ERROR", "Memory limit exceeded");
            pthread_mutex_unlock(&mutex);
            return -2;
        }
    }

    success_count = max_count;
    failure_count = 0;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

void validate_structures(NFAPI_CRC_INDICATION_PDU_T* pdu_array, int count) {
    for (int i = 0; i < count; ++i) {
        if ((pdu_array[i].tag.RX_UE_INFORMATION_TAG == 0 && pdu_array[i].CRCFLAG != 1) ||
            (pdu_array[i].tag.RNTI == 0)) {
            log_message("ERROR", "Checksum validation failed");
        }
    }
}

void generate_report() {
