typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} PduManager;

PduManager* create_pdu_manager(size_t initial_capacity) {
    PduManager* manager = (PduManager*)malloc(sizeof(PduManager));
    if (!manager) {
        log_message("Failed to allocate memory for PDU Manager.");
        return NULL;
    }

    manager->pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdu_array) {
        free(manager);
        log_message("Failed to allocate memory for PDU array.");
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_pdu_manager(PduManager* manager) {
    if (!manager) return;

    free(manager->pdu_array);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_pdu(PduManager* manager, const RX_UE_INFORMATION_TAG* rx_ue_info, int rnti) {
    if (!manager || !rx_ue_info) {
        log_message("Invalid arguments to add_pdu.");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);
    // Reallocate memory if necessary
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->pdu_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            log_message("Failed to reallocate memory for PDU array.");
            return -1;
        }
        manager->pdu_array = new_array;
        manager->capacity = new_capacity;
    }

    // Populate the structure
    memcpy(&(manager->pdu_array[manager->count].rx_ue_info), rx_ue_info, sizeof(RX_UE_INFORMATION_TAG));
    manager->pdu_array[manager->count].rnti = rnti;
    manager->pdu_array[manager->count].crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void process_pdus(PduManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        // Process each PDU as needed
        log_message("Processing PDU with RNTI: ");
        printf("%d\n", manager->pdu_array[i].rnti);
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    srand(time(NULL));  // Seed the random number generator

    PduManager* manager = create_pdu_manager(10); // Initial capacity of 10
    if (!manager) return -1;

    RX_UE_INFORMATION_TAG rx_ue_info;
    for (int i = 0; i < 20; ++i) {
        add_pdu(manager, &rx_ue_info, i);
    }

    process_pdus(manager);

    destroy_pdu_manager(manager);

    return 0;
}
