}

// Serialize structure into file with compression
void serialize_to_file(const char* filename, NFAPI_CRC_INDICATION_PDU_T* pdu_array, size_t count) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    // Compress and write data
    unsigned long compressed_size = compressBound(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    unsigned char *compressed_data = malloc(compressed_size);

    if (compress(compressed_data, &compressed_size, 
                 (unsigned char *)pdu_array, count * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        free(compressed_data);
        fclose(file);
        return;
    }

    fwrite(&count, sizeof(count), 1, file);
    fwrite(compressed_data, compressed_size, 1, file);

    free(compressed_data);
    fclose(file);
}

// Deserialize structure from file with decompression
size_t deserialize_from_file(const char* filename, NFAPI_CRC_INDICATION_PDU_T** pdu_array) {
    FILE *file = fopen(filename, "rb");
    if (!file) return 0;

    size_t count;
    fread(&count, sizeof(count), 1, file);

    unsigned long compressed_size = ftell(file);
    fseek(file, 0, SEEK_END);
    unsigned long decompressed_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    unsigned char *compressed_data = malloc(compressed_size);
    fread(compressed_data, compressed_size, 1, file);
    fclose(file);

    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(decompressed_size);
    if (uncompress((unsigned char *)(*pdu_array), &decompressed_size,
                   compressed_data, compressed_size)) {
        free(compressed_data);
        free(*pdu_array);
        return 0;
    }

    free(compressed_data);
    return count;
}

// Background integrity verification and re-serialization thread
void *integrity_check_thread(void *arg) {
    char *filename = (char *) arg;

    while (1) {
        sleep(10); // Check every 10 seconds

        pthread_mutex_lock(&cache_lock);

        CacheEntry *current = cache_head;
        NFAPI_CRC_INDICATION_PDU_T *pdu_array, *temp_pdu_array;
        size_t count = 0;

        // Collect data from cache
        while (current) {
            pdu_array = realloc(pdu_array, (count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu_array[count++] = current->pdu;
            CacheEntry *to_remove = current;
            current = current->next;
            free(to_remove);
        }

        // Serialize to file
        serialize_to_file(filename, pdu_array, count);

        free(pdu_array);

        pthread_mutex_unlock(&cache_lock);
    }
}

// Function to initialize and manage the list
void initialize_and_manage_nfaapi_list(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (size_t i = 0; i < n; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand();
        pdu_list[i].RNTI = rand();
        set_random_crcflag(&pdu_list[i]);

        // Cache the structure
        pthread_mutex_lock(&cache_lock);
        CacheEntry *new_entry = malloc(sizeof(CacheEntry));
        new_entry->pdu = pdu_list[i];
        new_entry->last_access_time = time(NULL);
        new_entry->next = cache_head;
        cache_head = new_entry;
        pthread_mutex_unlock(&cache_lock);
    }

    // Start integrity check thread
    pthread_t checker_thread;
    char filename[] = "nfaapi_data.bin";
    pthread_create(&checker_thread, NULL, integrity_check_thread, (void *)filename);

    free(pdu_list);  // Free initial list after caching all entries
}

int main() {
    srand(time(NULL));
    initialize_and_manage_nfaapi_list(10);
    return 0;
}
