void init_queue(UserQueue* queue, size_t capacity) {
    pthread_mutex_init(&queue->lock, NULL);
    queue->capacity = capacity;
    queue->count = 0;
    queue->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Destroy a thread-safe queue
