    free(queue->data);
}

// Enqueue user data with synchronization
int enqueue_user(UserQueue* queue, const NFAPI_CRC_INDICATION_PDU_T* user_data) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= queue->capacity) {
        fprintf(stderr, "Queue is full!\n");
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    memcpy(&queue->data[queue->count], user_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->count++;
