    pthread_mutex_lock(&queue->lock);

    if (queue->count == 0) {
        fprintf(stderr, "Queue is empty!\n");
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* user_data = &queue->data[0];
    memmove(queue->data, queue->data + 1, (queue->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->count--;

    pthread_mutex_unlock(&queue->lock);
    return user_data;
