    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} LinkedList;

// External logging mechanism
void log_debug(const char* message) {
    printf("[DEBUG] %s\n", message);
}

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    log_debug("Linked list created");
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
    log_debug("Linked list destroyed");
}

void add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        log_debug("Failed to allocate memory for new node");
        return;
    }
    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    log_debug("Element added to the linked list");
}

void remove_element(LinkedList* list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect && ((*indirect)->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG)) {
        indirect = &(*indirect)->next;
    }
    if (*indirect) {
        Node* to_delete = *indirect;
        *indirect = to_delete->next;
        free(to_delete);
        list->size--;
        log_debug("Element removed from the linked list");
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list(LinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void batch_process(LinkedList* list, void (*process_batch)(NFAPI_CRC_INDICATION_PDU_T*, size_t)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    NFAPI_CRC_INDICATION_PDU_T batch[1000];
    size_t count = 0;

    while (current && count < 1000) {
        batch[count++] = current->data;
        current = current->next;
