#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int valid;
    unsigned int rnti; // Assuming RNTI is an unsigned integer for this example
    unsigned int crc_tag; // CRC_INDICATION_REL8_TAG equivalent
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    int max_queue_size;
} PacketQueue;

void initialize_queue(PacketQueue* queue, int initial_max_size) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->count = 0;
    queue->max_queue_size = initial_max_size;
}

int enqueue_packet(PacketQueue* queue, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation failed

    new_node->pdu = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);

    if (queue->count < queue->max_queue_size) {
        new_node->next = queue->head;
        queue->head = new_node;
        queue->count++;

        // Log success
        printf("Packet enqueued successfully.\n");

        pthread_mutex_unlock(&queue->lock);
        return 0; // Success
    } else {
        free(new_node); // No space, avoid leak

        pthread_mutex_unlock(&queue->lock);

        // Log queue full situation
        printf("Queue is full. Packet dropped.\n");
        return -2; // Queue is full
    }
}

int dequeue_packet(PacketQueue* queue, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue->lock);

    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->lock);

        // Log underflow situation
        printf("Queue is empty. No packet to dequeue.\n");
        return -1; // Queue is empty
    }

    Node* temp = queue->head;
    *pdu = temp->pdu;

    queue->head = queue->head->next;
    free(temp);
    queue->count--;

    pthread_mutex_unlock(&queue->lock);

    // Log dequeue success
    printf("Packet dequeued successfully.\n");

    return 0; // Success
}

void* packet_processing_thread(void* arg) {
    PacketQueue* queue = (PacketQueue*)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (1) {
        if (dequeue_packet(queue, &pdu) == 0) {
            // Process the dequeued packet
            printf("Processing packet with RNTI: %u\n", pdu.rnti);
        }

        // Adaptive sleep to reduce CPU usage
        sched_yield();
    }
}

void start_processing_threads(PacketQueue* queue, int num_threads) {
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, packet_processing_thread, queue)) {
            perror("Failed to create thread");
        }
    }

    // Optionally join threads or implement a graceful shutdown mechanism
}

void cleanup_queue(PacketQueue* queue) {
    while (dequeue_packet(queue, NULL) != -1);

    pthread_mutex_destroy(&queue->lock);
}

int main() {
    PacketQueue queue;
    initialize_queue(&queue, 100); // Initialize with max size of 100

    start_processing_threads(&queue, 4); // Start 4 threads for processing

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 12345, 67890}; // Example packet
    enqueue_packet(&queue, pdu);

    // Simulate some delay to allow thread processing
    sleep(5);

    cleanup_queue(&queue);

    return 0;
}
```

