typedef struct {
    int UE_INDEX;
    int RNTI;
    size_t payload_size;
    unsigned char *payload_data;  // Dynamically allocated buffer for variable-length data payloads
} LTE_PHY_RX_UE_INFO;

typedef struct {
    LTE_PHY_RX_UE_INFO **array;
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
} DynamicArray;

// Initialize the dynamic array structure
int init_dynamic_array(DynamicArray *dyn_arr, size_t initial_capacity) {
    dyn_arr->array = malloc(initial_capacity * sizeof(LTE_PHY_RX_UE_INFO *));
    if (!dyn_arr->array) return -1;  // Memory allocation failure

    pthread_mutex_init(&dyn_arr->lock, NULL);
    dyn_arr->size = 0;
    dyn_arr->capacity = initial_capacity;

    for (size_t i = 0; i < dyn_arr->capacity; ++i)
        dyn_arr->array[i] = NULL;

    return 0;
}

// Resize the dynamic array
int resize_dynamic_array(DynamicArray *dyn_arr, size_t new_capacity) {
    LTE_PHY_RX_UE_INFO **new_array = realloc(dyn_arr->array, new_capacity * sizeof(LTE_PHY_RX_UE_INFO *));
    if (!new_array) return -1;  // Memory allocation failure

    for (size_t i = dyn_arr->capacity; i < new_capacity; ++i)
        new_array[i] = NULL;

    dyn_arr->array = new_array;
    dyn_arr->capacity = new_capacity;

    return 0;
}

// Add a new UE info to the dynamic array
int add_ue_info(DynamicArray *dyn_arr, LTE_PHY_RX_UE_INFO *ue_info) {
    pthread_mutex_lock(&dyn_arr->lock);

    if (dyn_arr->size >= dyn_arr->capacity)
        resize_dynamic_array(dyn_arr, dyn_arr->capacity ? dyn_arr->capacity * 2 : 1);

    dyn_arr->array[dyn_arr->size] = ue_info;
    dyn_arr->size++;

    pthread_mutex_unlock(&dyn_arr->lock);
    return 0;
}

// Remove a UE info from the dynamic array
int remove_ue_info(DynamicArray *dyn_arr, int index) {
    if (index < 0 || index >= (int)dyn_arr->size)
        return -1;  // Invalid index

    pthread_mutex_lock(&dyn_arr->lock);

    free(dyn_arr->array[index]->payload_data);
    free(dyn_arr->array[index]);

    for (size_t i = index; i < dyn_arr->size - 1; ++i)
        dyn_arr->array[i] = dyn_arr->array[i + 1];

    dyn_arr->array[dyn_arr->size - 1] = NULL;
    dyn_arr->size--;

    if (dyn_arr->capacity > 1 && dyn_arr->size <= dyn_arr->capacity / 4)
        resize_dynamic_array(dyn_arr, dyn_arr->capacity / 2);

    pthread_mutex_unlock(&dyn_arr->lock);
    return 0;
}

// Free the dynamic array and its contents
void free_dynamic_array(DynamicArray *dyn_arr) {
    for (size_t i = 0; i < dyn_arr->size; ++i) {
        if (dyn_arr->array[i]) {
            free(dyn_arr->array[i]->payload_data);
            free(dyn_arr->array[i]);
        }
    }

    free(dyn_arr->array);
    pthread_mutex_destroy(&dyn_arr->lock);
}

// Example function to create a new LTE_PHY_RX_UE_INFO structure
LTE_PHY_RX_UE_INFO *create_ue_info(int ue_index, int rnti, size_t payload_size) {
    LTE_PHY_RX_UE_INFO *ue_info = malloc(sizeof(LTE_PHY_RX_UE_INFO));
    if (!ue_info) return NULL;

    ue_info->UE_INDEX = ue_index;
    ue_info->RNTI = rnti;
    ue_info->payload_size = payload_size;
    ue_info->payload_data = malloc(payload_size);
    if (!ue_info->payload_data) {
        free(ue_info);
        return NULL;  // Memory allocation failure
    }

    // Initialize payload data to zero or any default value
    memset(ue_info->payload_data, 0, payload_size);

    return ue_info;
}

// Example function for integration with external systems, demonstrating minimal latency handling
void integrate_with_external_system(DynamicArray *dyn_arr) {
    pthread_mutex_lock(&dyn_arr->lock);

    // Process the array elements in a thread-safe manner
    for (size_t i = 0; i < dyn_arr->size; ++i) {
        LTE_PHY_RX_UE_INFO *ue_info = dyn_arr->array[i];

        if (ue_info) {
            // Example integration logic - e.g., send data to external system
            printf("Processing UE_INDEX: %d, RNTI: %d\n", ue_info->UE_INDEX, ue_info->RNTI);
        }
    }

    pthread_mutex_unlock(&dyn_arr->lock);
}
