    for (size_t i = 0; i < num_packets; ++i) {
        packets[i].subframe_count = 0;

        int traffic_load = get_network_traffic();
        size_t max_subframes = MAX_PACKET_SIZE / MIN_SUBFRAME_BYTES;
        if (traffic_load > 50) { // Assume more load, fewer subframes
            max_subframes /= 2;
