            size_t subframe_size = MIN_SUBFRAME_BYTES + rand() % (MAX_SUBFRAME_BYTES - MIN_SUBFRAME_BYTES + 1);

            unsigned char *subframe_data = malloc(subframe_size);
            if (!subframe_data) break;

            packets[i].subframes[j] = (MAC_SUBFRAME){ .data = subframe_data, .length = subframe_size };
            ++packets[i].subframe_count;
        }

        // Initialize MAC_FRAME and MAC_HEADER with example values
