```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    char *ue_id;
    unsigned char *buffer;
    size_t buffer_size;
} SessionContext;

typedef struct Node {
    SessionContext session;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} SessionList;

// Function to initialize a new session context
SessionContext create_session_context(const char *ue_id) {
    SessionContext ctx;
    ctx.ue_id = strdup(ue_id);
    if (!ctx.ue_id) {
        perror("Failed to allocate memory for UE-ID");
        exit(EXIT_FAILURE);
    }
    ctx.buffer_size = INITIAL_BUFFER_SIZE;
    ctx.buffer = (unsigned char*)malloc(ctx.buffer_size);
    if (!ctx.buffer) {
        free(ctx.ue_id);
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }
    return ctx;
}

// Function to add a session context to the list
void add_session_context(SessionList *list, SessionContext context) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->session = context;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Function to find a session context by UE-ID
SessionContext* find_session_context(SessionList *list, const char *ue_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (strcmp(current->session.ue_id, ue_id) == 0) {
            SessionContext* ctx = &current->session;
            pthread_mutex_unlock(&list->lock);
            return ctx;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Function to resize the buffer of a session context
void resize_session_buffer(SessionContext *ctx, size_t new_size) {
    unsigned char* new_buffer = (unsigned char*)realloc(ctx->buffer, new_size);
    if (!new_buffer) {
        perror("Failed to reallocate buffer");
        exit(EXIT_FAILURE);
    }
    ctx->buffer = new_buffer;
    ctx->buffer_size = new_size;
}

// Function to initialize the session list
void init_session_list(SessionList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

// Function to free all resources in the session list
void destroy_session_list(SessionList *list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->session.buffer);
        free(current->session.ue_id);
        free(current);
        current = next;
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    SessionList list;
    init_session_list(&list);

    // Add a session context
    SessionContext ctx = create_session_context("UE12345");
    add_session_context(&list, ctx);

    // Find and resize the buffer of a session context
    SessionContext* found_ctx = find_session_context(&list, "UE12345");
    if (found_ctx) {
        resize_session_buffer(found_ctx, 2048);
    }

    // Clean up
    destroy_session_list(&list);

    return 0;
}
