#include <openssl/aes.h>
#include <openssl/evp.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generateNFACRCIndications(int num_users, int *num_generated) {
    if (num_users <= 0 || !num_generated) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(time(NULL)); // Seed random number generator

    for (int i = 0; i < num_users; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand(); // Random tag
        list[i].RNTI = rand() % 65536;          // RNTI is a 16-bit value
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2); // Random CRCFLAG (0 or 1)
    }

    *num_generated = num_users;
    return list;
}

// Function to decrypt ciphertext using AES-CBC
unsigned char* aesDecrypt(const unsigned char *ciphertext, size_t len,
                          const unsigned char *key, const unsigned char *iv,
                          int *decrypted_len) {
    if (!ciphertext || !len || !key || !iv || !decrypted_len)
        return NULL;

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char *plaintext = malloc(len); // Allocate memory for plaintext
    if (!plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int outlen1, outlen2;
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Decrypt the ciphertext
    if (!EVP_DecryptUpdate(ctx, plaintext, &outlen1, ciphertext, len)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (!EVP_DecryptFinal_ex(ctx, plaintext + outlen1, &outlen2)) {
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    *decrypted_len = outlen1 + outlen2;

    EVP_CIPHER_CTX_free(ctx);

    // Optional: Remove padding
    unsigned char pad = plaintext[*decrypted_len - 1];
    if (pad > *decrypted_len) {
        free(plaintext);
        return NULL; // Invalid padding
    }
    for (int i = 0; i < pad; ++i) {
        if (plaintext[*decrypted_len - 1 - i] != pad) {
            free(plaintext);
            return NULL; // Invalid padding
        }
    }

    unsigned char *trimmed_plaintext = malloc(*decrypted_len - pad);
    if (!trimmed_plaintext) {
        free(plaintext);
        return NULL;
    }

    memcpy(trimmed_plaintext, plaintext, *decrypted_len - pad);
    free(plaintext);

    return trimmed_plaintext;
}

// Example usage of the functions
int main() {
    int num_users = 10;
    int generated_count;

    // Generate NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = generateNFACRCIndications(num_users, &generated_count);
    if (!nfa_list) {
        fprintf(stderr, "Failed to generate NFA indications\n");
        return 1;
    }

    // Example AES key and IV (must be 16 bytes for AES-128)
    unsigned char aes_key[] = "0123456789abcdef";
    unsigned char aes_iv[] = "1234567890abcdef";

    // Example ciphertext (length should be a multiple of block size plus padding length)
    unsigned char *ciphertext = (unsigned char *)"YourCiphertextWithPadding...";
    size_t ciphertext_len = strlen((char *)ciphertext);

    int decrypted_len;
    unsigned char *plaintext = aesDecrypt(ciphertext, ciphertext_len,
                                          aes_key, aes_iv, &decrypted_len);

    if (!plaintext) {
        fprintf(stderr, "Decryption failed\n");
        free(nfa_list);
        return 1;
    }

    printf("Decrypted text: %s\n", plaintext);

    // Clean up
    free(plaintext);
    free(nfa_list);

    return 0;
}
```

This code defines the `NFAPI_CRC_INDICATION_PDU_T` structure and provides functions to generate a list of these structures with random values, as well as decrypt data using AES-CBC. The decryption function includes handling for potential errors and padding removal.']

