    size_t length;
    unsigned char *data;
} Buffer;

typedef struct {
    int ue_id;
    Buffer uplink_buffer;
    pthread_mutex_t lock;
} SessionContext;

typedef struct {
    SessionContext **contexts;
    size_t count;
    size_t capacity;
    pthread_rwlock_t rwlock;
} SessionManager;

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    // Handle API response data
    return size * nmemb;
}

SessionContext* find_or_create_context(SessionManager *manager, int ue_id) {
    pthread_rwlock_rdlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            pthread_rwlock_unlock(&manager->rwlock);
            return manager->contexts[i];
        }
    }
    pthread_rwlock_unlock(&manager->rwlock);

    pthread_rwlock_wrlock(&manager->rwlock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            pthread_rwlock_unlock(&manager->rwlock);
            return manager->contexts[i];
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        SessionContext **new_contexts = realloc(manager->contexts, new_capacity * sizeof(SessionContext *));
        if (!new_contexts) {
            pthread_rwlock_unlock(&manager->rwlock);
            return NULL; // Handle allocation failure
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    SessionContext *context = malloc(sizeof(SessionContext));
    if (!context) {
        pthread_rwlock_unlock(&manager->rwlock);
        return NULL; // Handle allocation failure
    }

    context->ue_id = ue_id;
    context->uplink_buffer.capacity = INITIAL_BUFFER_SIZE;
    context->uplink_buffer.length = 0;
    context->uplink_buffer.data = malloc(INITIAL_BUFFER_SIZE);
    if (!context->uplink_buffer.data) {
        free(context);
        pthread_rwlock_unlock(&manager->rwlock);
        return NULL; // Handle allocation failure
    }

    pthread_mutex_init(&context->lock, NULL);

    manager->contexts[manager->count++] = context;
    pthread_rwlock_unlock(&manager->rwlock);

    return context;
}

void resize_buffer(SessionContext *context, size_t new_capacity) {
    pthread_mutex_lock(&context->lock);
    if (new_capacity > context->uplink_buffer.capacity) {
        unsigned char *new_data = realloc(context->uplink_buffer.data, new_capacity);
        if (!new_data) {
            pthread_mutex_unlock(&context->lock);
            return; // Handle allocation failure
        }
        context->uplink_buffer.data = new_data;
        context->uplink_buffer.capacity = new_capacity;
    }
    pthread_mutex_unlock(&context->lock);
}

void update_traffic_pattern(SessionManager *manager, int ue_id, size_t traffic_size) {
    SessionContext *context = find_or_create_context(manager, ue_id);
    if (!context) return;

    resize_buffer(context, context->uplink_buffer.length + traffic_size);

    pthread_mutex_lock(&context->lock);
    // Assume some logic to update the buffer based on traffic_size
    context->uplink_buffer.length += traffic_size;
    pthread_mutex_unlock(&context->lock);
}

void fetch_configuration(SessionManager *manager) {
