    if (curl) {
        char url[] = "http://api.example.com/config";
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize cURL\ncurl_global_init() was not called.\n");
    }
}

void init_session_manager(SessionManager *manager) {
    manager->contexts = malloc(10 * sizeof(SessionContext *));
    if (!manager->contexts) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }

    manager->count = 0;
    manager->capacity = 10;
    pthread_rwlock_init(&manager->rwlock, NULL);
}

void destroy_session_manager(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->uplink_buffer.data);
        pthread_mutex_destroy(&manager->contexts[i]->lock);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_rwlock_destroy(&manager->rwlock);
}

int main() {
    SessionManager manager;
    init_session_manager(&manager);

    // Example usage
    update_traffic_pattern(&manager, 12345, 512);
    fetch_configuration(&manager);

    destroy_session_manager(&manager);
    return 0;
}
