            return i;
        }
    }
    return -1;
}

int add_or_update_entry(UE_Info_Array *ueArray, int ueIndex, int rnti, const unsigned char *payload, size_t payloadSize) {
    pthread_mutex_lock(&ueArray->lock);

    int index = find_entry_index(ueArray, ueIndex);
    if (index != -1) {
        // Update existing entry
        free(ueArray->array[index]->payload);
        ueArray->array[index]->UE_INDEX = ueIndex;
        ueArray->array[index]->RNTI = rnti;
        ueArray->array[index]->payload_size = payloadSize;
        ueArray->array[index]->payload = malloc(payloadSize);
        memcpy(ueArray->array[index]->payload, payload, payloadSize);

        // Log update
        printf("Updated entry at index %d\n", index);

    } else {
        // Add new entry
        if (ueArray->count == ueArray->capacity) {
            // Resize array
            size_t new_capacity = ueArray->capacity * 2;
            LTE_PHY_RX_UE_INFO **new_array = realloc(ueArray->array, sizeof(LTE_PHY_RX_UE_INFO *) * new_capacity);
            if (!new_array) {
                pthread_mutex_unlock(&ueArray->lock);
                return -1; // Memory allocation failed
            }
            ueArray->array = new_array;
            ueArray->capacity = new_capacity;
        }

        LTE_PHY_RX_UE_INFO *entry = malloc(sizeof(LTE_PHY_RX_UE_INFO));
        entry->UE_INDEX = ueIndex;
        entry->RNTI = rnti;
        entry->payload_size = payloadSize;
        entry->payload = malloc(payloadSize);
        memcpy(entry->payload, payload, payloadSize);

        ueArray->array[ueArray->count++] = entry;

        // Log addition
        printf("Added new entry at index %zu\n", ueArray->count - 1);
    }

    pthread_mutex_unlock(&ueArray->lock);
    return 0;
}

void remove_inactive_entries(UE_Info_Array *ueArray, time_t current_time, time_t idle_period) {
    pthread_mutex_lock(&ueArray->lock);

