#define MAX_UES 10000

typedef struct {
    int UE_INDEX;
    unsigned int RNTI;
    size_t payload_size;
    unsigned char *payload_data;
} LTE_PHY_RX_UE_INFO;

typedef struct {
    LTE_PHY_RX_UE_INFO *ue_array[MAX_UES];
    pthread_mutex_t locks[MAX_UES];
    size_t pool_size;
    unsigned char *memory_pool;
    pthread_mutex_t memory_pool_lock;
} UE_Manager;

void initialize_memory_pool(UE_Manager *manager, size_t block_size) {
    manager->pool_size = MAX_UES * sizeof(LTE_PHY_RX_UE_INFO);
    manager->memory_pool = malloc(manager->pool_size);

    if (!manager->memory_pool) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->memory_pool_lock, NULL);
}

void initialize_ue_manager(UE_Manager *manager) {
    for (int i = 0; i < MAX_UES; ++i) {
        manager->ue_array[i] = NULL;
        pthread_mutex_init(&manager->locks[i], NULL);
    }
}

LTE_PHY_RX_UE_INFO* allocate_ue_info(UE_Manager *manager, int ue_index, unsigned int rnti, size_t payload_size) {
    pthread_mutex_lock(&manager->memory_pool_lock);

    if (ue_index < 0 || ue_index >= MAX_UES || manager->ue_array[ue_index] != NULL) {
        pthread_mutex_unlock(&manager->memory_pool_lock);
        fprintf(stderr, "Invalid UE index or memory already allocated\n");
        return NULL;
    }

    LTE_PHY_RX_UE_INFO *ue_info = (LTE_PHY_RX_UE_INFO *)malloc(sizeof(LTE_PHY_RX_UE_INFO));
    if (!ue_info) {
        pthread_mutex_unlock(&manager->memory_pool_lock);
        perror("Failed to allocate UE info structure");
        return NULL;
    }

    ue_info->UE_INDEX = ue_index;
    ue_info->RNTI = rnti;
    ue_info->payload_size = payload_size;
    ue_info->payload_data = (unsigned char *)malloc(payload_size);

    if (!ue_info->payload_data) {
        free(ue_info);
        pthread_mutex_unlock(&manager->memory_pool_lock);
        perror("Failed to allocate payload data");
        return NULL;
    }

    manager->ue_array[ue_index] = ue_info;

    pthread_mutex_unlock(&manager->memory_pool_lock);
    return ue_info;
}

void deallocate_ue_info(UE_Manager *manager, int ue_index) {
    pthread_mutex_lock(&manager->locks[ue_index]);

    if (ue_index < 0 || ue_index >= MAX_UES || manager->ue_array[ue_index] == NULL) {
        pthread_mutex_unlock(&manager->locks[ue_index]);
        fprintf(stderr, "Invalid UE index or no memory allocated\n");
        return;
    }

    LTE_PHY_RX_UE_INFO *ue_info = manager->ue_array[ue_index];
    free(ue_info->payload_data);
    free(ue_info);

    manager->ue_array[ue_index] = NULL;

    pthread_mutex_unlock(&manager->locks[ue_index]);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    UE_Manager manager;
    initialize_memory_pool(&manager, sizeof(LTE_PHY_RX_UE_INFO));
    initialize_ue_manager(&manager);

    // Example usage
    LTE_PHY_RX_UE_INFO *ue_info = allocate_ue_info(&manager, 0, 1234, 1024);
    if (ue_info) {
        // Process ue_info...
    }

    deallocate_ue_info(&manager, 0);

    free(manager.memory_pool);
    return 0;
}
