void process_rxueinfos(const LTE_PHY_RXUEINFO_TAG *rxueinfos, size_t size);

// Main function to manage the dynamic array
void manage_dynamic_array() {
    LTE_PHY_RXUEINFO_TAG *rxueinfos = NULL;
    size_t size = 0;

    // Example: Adding a new entry.
    LTE_PHY_RXUEINFO_TAG new_info = { .rach_indication = {1, -50.5}, .pdsch_indication = {2, 75.3} };
    add_or_update_rxueinfo(&rxueinfos, &size, 0, new_info); // Add at index 0

    // Example: Updating an existing entry.
    LTE_PHY_RXUEINFO_TAG updated_info = { .rach_indication = {1, -45.0}, .pdsch_indication = {2, 80.0} };
    add_or_update_rxueinfo(&rxueinfos, &size, 0, updated_info); // Update at index 0

    // Process all entries.
    process_rxueinfos(rxueinfos, size);

    // Free allocated memory
    free(rxueinfos);
}

void add_or_update_rxueinfo(LTE_PHY_RXUEINFO_TAG **rxueinfos, size_t *size, int index, LTE_PHY_RXUEINFO_TAG new_info) {
    if (*rxueinfos == NULL) {
        *rxueinfos = (LTE_PHY_RXUEINFO_TAG *)malloc(sizeof(LTE_PHY_RXUEINFO_TAG));
        if (*rxueinfos == NULL) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
    } else {
        // Reallocate memory if index is out of current bounds
        if ((size_t)index >= *size) {
            size_t new_size = (index + 1) * sizeof(LTE_PHY_RXUEINFO_TAG);
            *rxueinfos = (LTE_PHY_RXUEINFO_TAG *)realloc(*rxueinfos, new_size);
            if (*rxueinfos == NULL) {
                perror("Failed to reallocate memory");
                exit(EXIT_FAILURE);
            }
            memset((*rxueinfos) + *size, 0, (new_size - (*size * sizeof(LTE_PHY_RXUEINFO_TAG))));
            *size = new_size;
        }
    }

    // Add or update the entry
    (*rxueinfos)[index] = new_info;
}

void process_rxueinfos(const LTE_PHY_RXUEINFO_TAG *rxueinfos, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        const LTE_PHY_RXUEINFO_TAG *info = &rxueinfos[i];

        // Example signal quality assessment algorithm
        float quality_metric = info->pdsch_indication.signal_quality - info->rach_indication.power_level;
        printf("Processing UE at index %zu: Signal Quality Metric = %.2f\n", i, quality_metric);
    }
}
