### C Library: `nfapi_crc_lib.c`

```c
#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

typedef struct {
    unsigned int rnti;
    char *rx_ue_info_tag;
    char *crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = new_node;
    } else {
        Node* temp = list->head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T get_pdu(List* list, unsigned int index) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (unsigned int i = 0; current && i < index; ++i) {
        current = current->next;
    }
    NFAPI_CRC_INDICATION_PDU_T pdu = {0};
    if (current) {
        pdu = current->data;
    }
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

void free_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Node* temp;
    while (list->head) {
        temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

