### Python Script: `process_log.py`

```python
import gzip
import bz2
import logging
from pathlib import Path

logging.basicConfig(level=logging.DEBUG, format='%(asctime)s - %(levelname)s - %(message)s')

def open_file(file_path):
    if file_path.endswith('.gz'):
        return gzip.open(file_path, 'rt')
    elif file_path.endswith('.bz2'):
        return bz2.open(file_path, 'rt')
    else:
        return open(file_path, 'r')

def process_log(file_path):
    with open_file(file_path) as f:
        lines = f.readlines()[-10:]

    sequence_numbers = []
    for line in lines:
        try:
            parts = line.strip().split(',')
            if len(parts) > 1:
                seq_num = int(parts[1])
                sequence_numbers.append(seq_num)
        except Exception as e:
            logging.error(f"Error processing line: {line}. Error: {e}")

    report(sequence_numbers)

def report(sequence_numbers):
    with open('report.txt', 'w') as f:
        for num in sequence_numbers:
            f.write(f"{num}\n")
    logging.info("Report generated successfully.")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python process_log.py <log_file_path>")
        sys.exit(1)

    file_path = Path(sys.argv[1])
    if not file_path.exists():
        logging.error(f"File {file_path} does not exist.")
        sys.exit(1)

    process_log(file_path)
```

