import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;

// Define the structure for CRC indication
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and initialize an array of structures
NFAPI_CRC_INDICATION_PDU_T* init_crc_array(int n, char** error) {
    if (n <= 0) {
        *error = "Invalid number of elements";
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        *error = "Memory allocation failed";
        return NULL;
    }

    for (int i = 0; i < n; ++i) {
        arr[i].RX_UE_INFORMATION_TAG = i + 1;
        arr[i].RNTI = i + 10;
        arr[i].CRC_INDICATION_REL8_TAG = i + 100;
        // Example pattern: CRCFLAG is set if index is even
        arr[i].CRCFLAG = (i % 2 == 0) ? 1 : 0;
    }

    return arr;
}

// Function to free allocated memory safely
void free_crc_array(NFAPI_CRC_INDICATION_PDU_T* array, int n) {
    if (array) {
        free(array);
    }
}

// Java component: RequestBuilder class and utility functions
public class RequestBuilder {

    private HttpGet httpGet;
    private ConcurrentHashMap<String, String> headers = new ConcurrentHashMap<>();

    public RequestBuilder(String url) {
        this.httpGet = new HttpGet(url);
    }

    // Add header
    public void addHeader(String key, String value) {
        headers.put(key, value);
    }

    // Build request with optional settings
    public CloseableHttpClient buildRequest(boolean validateCert, boolean logParams)
            throws NoSuchAlgorithmException, UnsupportedEncodingException {

        if (!validateCert) {
            // Disable certificate validation logic here (omitted for brevity)
        }

        for (var entry : headers.entrySet()) {
            httpGet.addHeader(entry.getKey(), entry.getValue());
        }

        if (logParams) {
            System.out.println("Request Headers: " + headers.toString());
        }

        return HttpClients.createDefault();
    }

    // Generate MD5 hash
    public String generateMD5Hash(String input) throws NoSuchAlgorithmException, UnsupportedEncodingException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes("UTF-8"));
        StringBuilder hexString = new StringBuilder();

        for (byte b : messageDigest) {
            hexString.append(Integer.toHexString(0xFF & b));
        }

        return hexString.toString();
    }

    // Example retry logic with backoff
    public CloseableHttpClient executeWithRetry(String url, int retries, long backoffMillis)
            throws Exception {

        CloseableHttpClient client = null;
        boolean success = false;

        for (int attempt = 0; attempt < retries; ++attempt) {
            try {
                RequestBuilder rb = new RequestBuilder(url);
                client = rb.buildRequest(true, true); // Example parameters
                // Execute the request and process response (omitted for brevity)
                success = true;
                break;
            } catch (Exception e) {
                System.out.println("Attempt " + attempt + " failed: " + e.getMessage());
                Thread.sleep(backoffMillis * attempt);
            }
        }

        if (!success && client != null) {
            throw new Exception("All retry attempts failed");
        }

        return client;
    }
}
