<?php

function authenticateUser($clientId, $clientSecret) {
    $url = 'https://api.example.com/oauth/token';
    $data = [
        'grant_type' => 'client_credentials',
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
    ];

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        // Handle errors such as network timeouts
        echo 'Error: ' . curl_error($ch);
        return false;
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    if ($httpCode != 200) {
        // Handle API rate limits or other HTTP errors
        echo "HTTP Error: $httpCode";
        return false;
    }

    curl_close($ch);

    $responseData = json_decode($response, true);
    if (isset($responseData['access_token'])) {
        $_SESSION['access_token'] = $responseData['access_token'];
        return true;
    } else {
        return false;
    }
}

function getUserInformation($rnti) {
    session_start();
    if (!isset($_SESSION['access_token'])) {
        echo "Access token not found. Please authenticate.";
        return;
    }

    $url = 'https://api.example.com/userinfo?rnti=' . urlencode($rnti);
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        "Authorization: Bearer {$_SESSION['access_token']}"
    ]);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        echo 'Error: ' . curl_error($ch);
        return;
    }

    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    if ($httpCode != 200) {
        echo "HTTP Error: $httpCode";
        return;
    }

    curl_close($ch);

    $userInfo = json_decode($response, true);
    print_r($userInfo);
}

