#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

#define MAX_STRUCTURES 100
#define MAX_RNTI 0xFFFF
#define LOG_FILE_SIZE_LIMIT (1024 * 1024) // 1MB

typedef struct {
    uint16_t rnti;
    uint8_t rx_ue_information_tag;
    uint8_t crc_indication_rel8_tag;
    uint8_t crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
uint16_t last_rnti = 0;
FILE *log_file;

void log_message(const char* message) {
    pthread_mutex_lock(&mutex);
    if (ftell(log_file) >= LOG_FILE_SIZE_LIMIT) {
        fclose(log_file);
        remove("nfa_log.txt");
        log_file = fopen("nfa_log.txt", "w");
    }
    fprintf(log_file, "%s: %s\n", time_to_string(), message);
    fflush(log_file);
    pthread_mutex_unlock(&mutex);
}

void* generate_structures(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* structures = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        log_message("Memory allocation failed");
        return NULL;
    }

    uint16_t rnti_set[MAX_STRUCTURES] = {0};
    int count = 0;

    srand(time(NULL) ^ pthread_self());

    while (count < MAX_STRUCTURES) {
        pthread_mutex_lock(&mutex);
        uint16_t rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1);
        } while (rnti_set[rnti % MAX_STRUCTURES] == rnti);

        structures[count].rnti = rnti;
        rnti_set[rnti % MAX_STRUCTURES] = rnti;
        last_rnti = rnti;

        structures[count].rx_ue_information_tag = rand() & 0xFF;
        structures[count].crc_indication_rel8_tag = rand() & 0xFF;
        structures[count].crc_flag = rand() & 1;

        log_message("Generated structure");
        pthread_mutex_unlock(&mutex);

        count++;
    }

    // Validate the list
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if ((structures[i].crc_indication_rel8_tag % 2 == 0) != structures[i].crc_flag) {
            log_message("CRC validation error");
        }
    }

    free(structures);
    return NULL;
}

void oauth_authenticate(uint16_t rnti) {
    int attempt = 0;
    const int max_attempts = 5;

    while (attempt < max_attempts) {
        if (simulate_network_operation(rnti)) {
            log_message("OAuth authentication successful");
            return;
        }

        sleep((1 << attempt));
        attempt++;
    }

    log_message("OAuth authentication failed after retries");
}

int simulate_network_operation(uint16_t rnti) {
    // Simulate a network operation with possible failure
    return rand() % 2; 
}

const char* time_to_string() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    return buf;
}

int main() {
    log_file = fopen("nfa_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[MAX_STRUCTURES];
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (pthread_create(&threads[i], NULL, generate_structures, NULL)) {
            log_message("Thread creation failed");
        }
    }

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        pthread_join(threads[i], NULL);
    }

    oauth_authenticate(last_rnti);

    fclose(log_file);
    return 0;
}
```

