#define MAX_INTERFACES 256

typedef struct {
    char name[32];
    unsigned long received_packets;
    unsigned long transmitted_packets;
    unsigned long error_counts;
} NetworkInterfaceStats;

NetworkInterfaceStats* interfaces = NULL;
size_t interface_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int compare_interfaces(const void* a, const void* b) {
    return strcmp(((NetworkInterfaceStats*)a)->name, ((NetworkInterfaceStats*)b)->name);
}

void read_and_initialize(int config_file_fd) {
    char buffer[256];
    int line_count = 0;
    while (fgets(buffer, sizeof(buffer), config_file_fd)) {
        if (line_count >= interface_count) {
            NetworkInterfaceStats* new_interfaces = realloc(interfaces, (interface_count + 1) * sizeof(NetworkInterfaceStats));
            if (!new_interfaces) break; // Handle reallocation failure
            interfaces = new_interfaces;
        }

        NetworkInterfaceStats* iface = &interfaces[line_count];
        if (sscanf(buffer, "%31s %lu %lu %lu", iface->name,
                   &iface->received_packets, &iface->transmitted_packets, &iface->error_counts) == 4) {
            // Validate data
            if (iface->received_packets >= 0 && iface->transmitted_packets >= 0 && iface->error_counts >= 0) {
                interface_count++;
                line_count++;
            }
        } else {
            fprintf(stderr, "Invalid entry: %s", buffer);
        }
    }

    qsort(interfaces, interface_count, sizeof(NetworkInterfaceStats), compare_interfaces);

    // Ensure no duplicate names
    for (size_t i = 0; i < interface_count - 1; ++i) {
        if (strcmp(interfaces[i].name, interfaces[i + 1].name) == 0) {
            fprintf(stderr, "Duplicate interface found: %s\n", interfaces[i].name);
            --interface_count;
            --line_count;
        }
    }

    // Resize to actual count
    NetworkInterfaceStats* resized_interfaces = realloc(interfaces, interface_count * sizeof(NetworkInterfaceStats));
    if (resized_interfaces) {
        interfaces = resized_interfaces;
    }
}

void update_statistics(const char* name, unsigned long received, unsigned long transmitted, unsigned long errors) {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < interface_count; ++i) {
        if (strcmp(interfaces[i].name, name) == 0) {
            interfaces[i].received_packets += received;
            interfaces[i].transmitted_packets += transmitted;
            interfaces[i].error_counts += errors;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void update_loop() {
    while (1) {
        // Simulated updates from monitoring tools
        char* name = "eth0";  // Example interface name
        unsigned long received = rand() % 100;
        unsigned long transmitted = rand() % 100;
        unsigned long errors = rand() % 10;

        update_statistics(name, received, transmitted, errors);

        usleep(100000); // Sleep for 100ms
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE* config_file = fopen(argv[1], "r");
    if (!config_file) {
        perror("Failed to open configuration file");
        return EXIT_FAILURE;
    }

    interfaces = malloc(sizeof(NetworkInterfaceStats) * MAX_INTERFACES);
    read_and_initialize(config_file);
    fclose(config_file);

    pthread_t update_thread_id;
    if (pthread_create(&update_thread_id, NULL, (void*)update_loop, NULL) != 0) {
        perror("Failed to create update thread");
        free(interfaces);
        return EXIT_FAILURE;
    }

    // Simulated main loop
    while(1) {
        sleep(10); // Main loop does other work or waits for user input/termination.
    }

    pthread_join(update_thread_id, NULL);
    free(interfaces);

    return 0;
}
