#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define constants for maximum list size and retention time in seconds
#define MAX_LIST_SIZE 10000000
#define RETENTION_TIME_SECONDS 3600

typedef struct {
    char *ue_identity;
    time_t timestamp;
    int tci_count;
    int *tc_ids; // Dynamic array of Traffic Channel Identifiers (TCIDs)
} UTRAN_TCH_Message;

// Define the message list structure with dynamic sizing and sorted order
typedef struct {
    UTRAN_TCH_Message *messages;
    size_t count;
    size_t capacity;
} MessageList;

// Function prototypes for managing the message list
void initMessageList(MessageList *list);
void freeMessageList(MessageList *list);
int insertMessage(MessageList *list, const char *ue_identity, int tci_count, int *tc_ids);
int deleteMessage(MessageList *list, const char *ue_identity);
UTRAN_TCH_Message* retrieveMessage(MessageList *list, time_t timestamp);
void pruneMessages(MessageList *list);

// Initialize the message list
void initMessageList(MessageList *list) {
    list->messages = (UTRAN_TCH_Message *)malloc(MAX_LIST_SIZE * sizeof(UTRAN_TCH_Message));
    list->count = 0;
    list->capacity = MAX_LIST_SIZE;
}

// Free the memory allocated for the message list
void freeMessageList(MessageList *list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->messages[i].ue_identity);
        free(list->messages[i].tc_ids);
    }
    free(list->messages);
}

// Insert a new message into the sorted list based on timestamp
int insertMessage(MessageList *list, const char *ue_identity, int tci_count, int *tc_ids) {
    if (list->count >= list->capacity) return -1; // Capacity exceeded

    UTRAN_TCH_Message new_message;
    new_message.ue_identity = strdup(ue_identity);
    new_message.timestamp = time(NULL);
    new_message.tci_count = tci_count;
    new_message.tc_ids = malloc(tci_count * sizeof(int));
    memcpy(new_message.tc_ids, tc_ids, tci_count * sizeof(int));

    // Find the correct position to insert to keep list sorted
    size_t pos = 0;
    while (pos < list->count && list->messages[pos].timestamp <= new_message.timestamp) {
        pos++;
    }

    memmove(&list->messages[pos + 1], &list->messages[pos], (list->count - pos) * sizeof(UTRAN_TCH_Message));
    list->messages[pos] = new_message;
    list->count++;

    return 0; // Success
}

// Delete a message by UE identity
int deleteMessage(MessageList *list, const char *ue_identity) {
    for (size_t i = 0; i < list->count; i++) {
        if (strcmp(list->messages[i].ue_identity, ue_identity) == 0) {
            free(list->messages[i].ue_identity);
            free(list->messages[i].tc_ids);

            memmove(&list->messages[i], &list->messages[i + 1], (list->count - i - 1) * sizeof(UTRAN_TCH_Message));
            list->count--;
            return 0; // Success
        }
    }
    return -1; // Not found
}

// Retrieve a message by timestamp (closest match)
UTRAN_TCH_Message* retrieveMessage(MessageList *list, time_t timestamp) {
    size_t pos = 0;
    while (pos < list->count && list->messages[pos].timestamp <= timestamp) {
        pos++;
    }
    if (pos > 0) return &list->messages[pos - 1];
    return NULL; // Not found
}

// Prune messages older than the retention time
void pruneMessages(MessageList *list) {
    time_t current_time = time(NULL);
    size_t new_count = 0;

    for (size_t i = 0; i < list->count; i++) {
        if ((current_time - list->messages[i].timestamp) <= RETENTION_TIME_SECONDS) {
            list->messages[new_count++] = list->messages[i];
        } else {
            free(list->messages[i].ue_identity);
            free(list->messages[i].tc_ids);
        }
    }

    list->count = new_count;
}

int main() {
    MessageList message_list;
    initMessageList(&message_list);

    int tcids[] = {1, 2, 3};
    insertMessage(&message_list, "UE123", 3, tcids);

    UTRAN_TCH_Message *msg = retrieveMessage(&message_list, time(NULL));
    if (msg) {
        printf("Retrieved UE: %s\n", msg->ue_identity);
    }

    pruneMessages(&message_list);
    freeMessageList(&message_list);

    return 0;
}
```

