#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_INTERFACES 1000
#define MAX_NAME_LENGTH 50

typedef struct {
    char interface_name[MAX_NAME_LENGTH];
    unsigned long received_packets;
    unsigned long transmitted_packets;
    unsigned long error_count;
} InterfaceStats;

typedef struct {
    InterfaceStats *interfaces;
    size_t count;
    pthread_mutex_t lock;
} NetworkProvider;

typedef struct {
    NetworkProvider *providers;
    size_t provider_count;
    pthread_rwlock_t rwlock;
} NetworkSystem;

void init_network_system(NetworkSystem *system) {
    system->providers = NULL;
    system->provider_count = 0;
    pthread_rwlock_init(&system->rwlock, NULL);
}

int add_provider(NetworkSystem *system, const char *provider_name) {
    pthread_rwlock_wrlock(&system->rwlock);

    NetworkProvider new_provider = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    system->providers = realloc(system->providers, (system->provider_count + 1) * sizeof(NetworkProvider));

    if (!system->providers) {
        pthread_rwlock_unlock(&system->rwlock);
        return -1;
    }

    new_provider.interfaces = malloc(MAX_INTERFACES * sizeof(InterfaceStats));
    if (!new_provider.interfaces) {
        free(system->providers[system->provider_count].interfaces);
        system->providers = realloc(system->providers, system->provider_count * sizeof(NetworkProvider));
        pthread_rwlock_unlock(&system->rwlock);
        return -1;
    }

    strcpy(new_provider.interfaces[0].interface_name, provider_name);
    new_provider.count = 1;

    system->providers[system->provider_count++] = new_provider;

    pthread_rwlock_unlock(&system->rwlock);

    return 0;
}

int remove_provider(NetworkSystem *system, const char *provider_name) {
    pthread_rwlock_wrlock(&system->rwlock);

    for (size_t i = 0; i < system->provider_count; ++i) {
        if (!strcmp(system->providers[i].interfaces[0].interface_name, provider_name)) {
            free(system->providers[i].interfaces);
            memmove(&system->providers[i], &system->providers[i + 1],
                    (system->provider_count - i - 1) * sizeof(NetworkProvider));
            system->provider_count--;

            system->providers = realloc(system->providers, system->provider_count * sizeof(NetworkProvider));
            pthread_rwlock_unlock(&system->rwlock);
            return 0;
        }
    }

    pthread_rwlock_unlock(&system->rwlock);

    return -1;
}

int update_interface_stats(NetworkSystem *system, const char *provider_name,
                           const char *interface_name, unsigned long received,
                           unsigned long transmitted, unsigned long errors) {
    pthread_rwlock_rdlock(&system->rwlock);

    for (size_t i = 0; i < system->provider_count; ++i) {
        pthread_mutex_lock(&system->providers[i].lock);

        for (size_t j = 0; j < system->providers[i].count; ++j) {
            if (!strcmp(system->providers[i].interfaces[j].interface_name, interface_name)) {
                system->providers[i].interfaces[j].received_packets = received;
                system->providers[i].interfaces[j].transmitted_packets = transmitted;
                system->providers[i].interfaces[j].error_count = errors;

                pthread_mutex_unlock(&system->providers[i].lock);
                pthread_rwlock_unlock(&system->rwlock);

                return 0;
            }
        }

        pthread_mutex_unlock(&system->providers[i].lock);
    }

    pthread_rwlock_unlock(&system->rwlock);

    return -1;
}

void log_discrepancy(const char *message) {
    // Logging logic here
    printf("LOG: %s\n", message);
}

void garbage_collect(NetworkSystem *system) {
    pthread_rwlock_wrlock(&system->rwlock);

    for (size_t i = 0; i < system->provider_count; ++i) {
        if (system->providers[i].count == 0) {
            free(system->providers[i].interfaces);
            memmove(&system->providers[i], &system->providers[i + 1],
                    (system->provider_count - i - 1) * sizeof(NetworkProvider));
            system->provider_count--;

            system->providers = realloc(system->providers, system->provider_count * sizeof(NetworkProvider));
        }
    }

    pthread_rwlock_unlock(&system->rwlock);
}

void free_network_system(NetworkSystem *system) {
    for (size_t i = 0; i < system->provider_count; ++i) {
        free(system->providers[i].interfaces);
    }
    free(system->providers);
    pthread_rwlock_destroy(&system->rwlock);
}
