    // Validate and set bandwidth
    config->bandwidth = (user_bandwidth > 0 && user_bandwidth <= MAX_BANDWIDTH) ? user_bandwidth : DEFAULT_BANDWIDTH;

    // Validate and set modulation scheme
    if (validate_modulation_scheme(user_mod_scheme)) {
        strncpy(config->modulation_scheme, user_mod_scheme, sizeof(config->modulation_scheme));
    } else {
        strcpy(config->modulation_scheme, VALID_MODULATION_SCHEMES[1]); // Default to "16-QAM"
    }

    // Validate and set error correction level
    config->error_correction_level = (user_error_corr_level >= MIN_ERROR_CORRECTION_LEVEL &&
                                      user_error_corr_level <= MAX_ERROR_CORRECTION_LEVEL) ?
                                     user_error_corr_level : DEFAULT_ERROR_CORRECTION_LEVEL;

    // Set CQI list size and allocate memory
    config->cqi_list_size = (cqi_list_size > 0 && cqi_list_size <= MAX_CQI_LIST_SIZE) ? cqi_list_size : DEFAULT_CQI_LIST_SIZE;
    config->cqi_list = (int *)malloc(config->cqi_list_size * sizeof(int));

    if (!config->cqi_list) {
        fprintf(stderr, "Failed to allocate memory for CQI list\n");
        exit(EXIT_FAILURE);
    }

    // Initialize CQI list
    for (int i = 0; i < config->cqi_list_size; ++i) {
        config->cqi_list[i] = (cqi_values && cqi_values[i]) ? cqi_values[i] : DEFAULT_CQI;
    }
}

void update_parameters_from_external_source(NetworkInterfaceConfig *config) {
    int external_bandwidth;
    char external_mod_scheme[10];
    int external_error_corr_level;

    fetch_external_parameters(&external_bandwidth, external_mod_scheme, &external_error_corr_level);

    if (validate_modulation_scheme(external_mod_scheme)) {
        config->bandwidth = external_bandwidth;
        strncpy(config->modulation_scheme, external_mod_scheme, sizeof(config->modulation_scheme));
        config->error_correction_level = external_error_corr_level;
    }
}

void free_network_interface_config(NetworkInterfaceConfig *config) {
    if (config && config->cqi_list) {
        free(config->cqi_list);
        config->cqi_list = NULL;
    }
}
