#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

// Define a structure to represent a signaling message
typedef struct {
    uint32_t message_type;
    uint64_t timestamp;
    size_t payload_length;
    char *payload;  // Dynamic array for variable-length data
} SignalMessage;

// Function to serialize a signal message into binary format
size_t serialize_message(const SignalMessage* msg, uint8_t** buffer) {
    size_t header_size = sizeof(msg->message_type) + sizeof(msg->timestamp) + sizeof(msg->payload_length);
    *buffer = (uint8_t*)malloc(header_size + msg->payload_length);

    if (*buffer == NULL) return 0;

    memcpy(*buffer, &msg->message_type, sizeof(msg->message_type));
    memcpy((*buffer) + sizeof(msg->message_type), &msg->timestamp, sizeof(msg->timestamp));
    memcpy((*buffer) + sizeof(msg->message_type) + sizeof(msg->timestamp), &msg->payload_length, sizeof(msg->payload_length));

    if (msg->payload_length > 0 && msg->payload != NULL) {
        memcpy(*buffer + header_size, msg->payload, msg->payload_length);
    }

    return header_size + msg->payload_length;
}

// Function to deserialize a binary buffer back into a signal message
int deserialize_message(const uint8_t* buffer, size_t length, SignalMessage** msg) {
    if (length < sizeof(uint32_t) + sizeof(uint64_t) + sizeof(size_t)) {
        return -1; // Invalid data
    }

    *msg = (SignalMessage*)malloc(sizeof(SignalMessage));
    if (*msg == NULL) return -1;

    memcpy(&(*msg)->message_type, buffer, sizeof((*msg)->message_type));
    memcpy(&(*msg)->timestamp, buffer + sizeof(uint32_t), sizeof((*msg)->timestamp));
    memcpy(&(*msg)->payload_length, buffer + sizeof(uint32_t) + sizeof(uint64_t), sizeof(size_t));

    if ((*msg)->payload_length > 0 && length < (*msg)->payload_length + sizeof(uint32_t) + sizeof(uint64_t) + sizeof(size_t)) {
        free(*msg);
        return -1; // Payload too large
    }

    (*msg)->payload = (char*)malloc((*msg)->payload_length);
    if ((*msg)->payload == NULL || (*msg)->payload_length > 0) {
        free(*msg);
        return -1;
    }

    memcpy((*msg)->payload, buffer + sizeof(uint32_t) + sizeof(uint64_t) + sizeof(size_t), (*msg)->payload_length);

    return 0; // Success
}

// Function to simulate processing incoming signals from an external source
void process_incoming_signals(SignalMessage** messages, size_t* count) {
    uint8_t buffer[1024]; // Example buffer for incoming data
    size_t read_size = sizeof(buffer); // Simulated read size

    while (read_size > 0) { // Simulate continuous reading
        SignalMessage* msg;
        int result = deserialize_message(buffer, read_size, &msg);

        if (result == 0) {
            *messages = realloc(*messages, (*count + 1) * sizeof(SignalMessage));
            (*messages)[*count] = *msg;
            (*count)++;
            free(msg); // Free deserialized structure
        } else {
            printf("Error: Malformed message received\n");
        }

        read_size = 0; // Simulate end of data stream for example purposes
    }
}

// Function to clean up allocated memory for messages
void cleanup_messages(SignalMessage* messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(messages[i].payload);
    }
    free(messages);
}
