    RX_UE_INFORMATION_TAG rxUeInformationTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

class RandomValueGenerator {
private:
    int minValue;
    int maxValue;

public:
    RandomValueGenerator(int min, int max) : minValue(min), maxValue(max) {}

    bool getRandomBoolean() {
        if (minValue == maxValue) return minValue; // Handle single value case
        int randomNum = rand() % (maxValue - minValue + 1) + minValue;
        return randomNum > ((maxValue - minValue) / 2);
    }

    char* toString() const {
        static char str[50];
        snprintf(str, sizeof(str), "[%d, %d]", minValue, maxValue);
        return str;
    }
};

NFAPI_CRC_INDICATION_PDU_T* generateNfadlPduList(size_t count) {
    if (count == 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pduArray = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!pduArray) return NULL; // Handle allocation failure

    srand(time(NULL)); // Seed for random number generation
    RandomValueGenerator rng(0, 1);

    for (size_t i = 0; i < count; ++i) {
        pduArray[i].rxUeInformationTag.RNTI = rand() % 256; // Example RNTI generation
        pduArray[i].crcIndicationRel8Tag.CRCFLAG = rng.getRandomBoolean();
    }

    return pduArray;
}

// Example usage:
int main() {
    size_t numPdus = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdus = generateNfadlPduList(numPdus);

    if (pdus) {
        for (size_t i = 0; i < numPdus; ++i) {
            printf("RNTI: %u, CRCFLAG: %d\n", pdus[i].rxUeInformationTag.RNTI, pdus[i].crcIndicationRel8Tag.CRCFLAG);
        }
        free(pdus); // Don't forget to free the allocated memory
    }

    return 0;
}
