using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;

namespace GameWorldConfigurationManager
{
    public class ConfigurationCache<T>
    {
        private readonly ConcurrentDictionary<string, T> _cache = new();
        private readonly TimeSpan _expiryDuration;
        private DateTime _lastUpdate;

        public ConfigurationCache(TimeSpan expiry)
        {
            _expiryDuration = expiry;
            _lastUpdate = DateTime.MinValue;
        }

        public bool TryGetValue(string key, out T value) => _cache.TryGetValue(key, out value);

        public void AddOrUpdate(string key, T value) => _cache[key] = value;

        public void Invalidate() => _cache.Clear();

        public bool IsExpired() => (DateTime.UtcNow - _lastUpdate) > _expiryDuration;
    }

    public class ConfigurationManager
    {
        private readonly string _configFilePath;
        private readonly Uri _remoteConfigUri;
        private readonly ConfigurationCache<T> _cache;

        public ConfigurationManager(string localPath, string remoteUrl, TimeSpan cacheExpiry)
        {
            _configFilePath = localPath;
            _remoteConfigUri = new Uri(remoteUrl);
            _cache = new ConfigurationCache<T>(cacheExpiry);
        }

        public async Task<T> LoadConfigurationAsync()
        {
            T config;

            if (_cache.TryGetValue("Main", out config) && !_cache.IsExpired())
                return config;

            try
            {
                using var stream = await LoadLocalConfigAsync();
                config = JsonSerializer.Deserialize<T>(stream);
                _cache.AddOrUpdate("Main", config);
            }
            catch (Exception)
            {
                using var client = new HttpClient();
                using var response = await client.GetAsync(_remoteConfigUri);

                if (!response.IsSuccessStatusCode)
                    throw;

                using var stream = await response.Content.ReadAsStreamAsync();
                config = JsonSerializer.Deserialize<T>(stream);
                _cache.AddOrUpdate("Main", config);
            }

            _cache._lastUpdate = DateTime.UtcNow;
            return config;
        }

        private async Task<Stream> LoadLocalConfigAsync() => new FileStream(_configFilePath, FileMode.Open);

        public void InvalidateCache()
        {
            _cache.Invalidate();
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class ConfigurationController : ControllerBase
    {
        private readonly ConfigurationManager _manager;

        public ConfigurationController(IConfiguration configuration)
        {
            _manager = new ConfigurationManager(
                configuration["LocalConfigPath"],
                configuration["RemoteConfigUrl"],
                TimeSpan.FromMinutes(5));
        }

        [HttpGet]
        public async Task<IActionResult> GetConfiguration()
        {
            try
            {
                var config = await _manager.LoadConfigurationAsync();
                return Ok(config);
            }
            catch (Exception)
            {
                return StatusCode(500, "Error loading configuration");
            }
        }

        [HttpPost("update")]
        public IActionResult UpdateConfiguration([FromBody] string newConfigContent)
        {
            // Assume validation and deserialization is done
            _manager.InvalidateCache();
            return Ok("Configuration updated successfully");
        }
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }

            app.UseRouting();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }

    class Program
    {
        static Task Main(string[] args) => new WebApplicationFactory<Startup>().CreateHostBuilder(args).Build().RunAsync();
    }
}
