typedef struct {
    uint16_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG[4];
} Identification;

typedef struct {
    uint8_t message_type;
    uint64_t timestamp;
    char *payload; // Variable-length payload
    int value;
    Identification id;
} MobileNetworkMessage;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG[4];
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

typedef struct {
    MobileNetworkMessage **messages;
    size_t count;
    size_t capacity;
} MessageArray;

void init_message_array(MessageArray *array, size_t initial_capacity) {
    array->messages = malloc(initial_capacity * sizeof(MobileNetworkMessage *));
    if (!array->messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
}

void free_message_array(MessageArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i]) {
            free(array->messages[i]->payload);
            free(array->messages[i]);
        }
    }
    free(array->messages);
}

void add_message(MessageArray *array, MobileNetworkMessage *message) {
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MobileNetworkMessage **new_messages = realloc(array->messages, new_capacity * sizeof(MobileNetworkMessage *));
        if (!new_messages) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->count++] = message;
}

void serialize_message(const MobileNetworkMessage *message, uint8_t **buffer, size_t *size) {
    // Calculate required buffer size
    size_t payload_size = strlen(message->payload);
    *size = sizeof(uint8_t) + sizeof(uint64_t) + sizeof(uint16_t) + 4 + payload_size + sizeof(int);

    *buffer = malloc(*size);
    if (!*buffer) {
        perror("Failed to allocate memory for serialization");
        exit(EXIT_FAILURE);
    }

    uint8_t *ptr = *buffer;
    ptr[0] = message->message_type;
    memcpy(ptr + 1, &message->timestamp, sizeof(uint64_t));
    memcpy(ptr + 1 + sizeof(uint64_t), &message->id.RNTI, sizeof(uint16_t));
    memcpy(ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t), message->id.RX_UE_INFORMATION_TAG, 4);
    memcpy(ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t) + 4, message->payload, payload_size);
    memcpy(ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t) + 4 + payload_size, &message->value, sizeof(int));
}

void deserialize_message(const uint8_t *buffer, size_t size, MobileNetworkMessage **out_message) {
    if (size < sizeof(uint8_t) + sizeof(uint64_t) + sizeof(uint16_t) + 4 + sizeof(int)) {
        fprintf(stderr, "Invalid buffer size for deserialization\n");
        return;
    }

    const uint8_t *ptr = buffer;
    MobileNetworkMessage *message = malloc(sizeof(MobileNetworkMessage));
    if (!message) {
        perror("Failed to allocate memory for message structure");
        exit(EXIT_FAILURE);
    }

    message->message_type = ptr[0];
    memcpy(&message->timestamp, ptr + 1, sizeof(uint64_t));
    memcpy(&message->id.RNTI, ptr + 1 + sizeof(uint64_t), sizeof(uint16_t));
    memcpy(message->id.RX_UE_INFORMATION_TAG, ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t), 4);

    size_t payload_size = size - (sizeof(uint8_t) + sizeof(uint64_t) + sizeof(uint16_t) + 4 + sizeof(int));
    message->payload = malloc(payload_size + 1);
    if (!message->payload) {
        perror("Failed to allocate memory for payload");
        exit(EXIT_FAILURE);
    }
    memcpy(message->payload, ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t) + 4, payload_size);
    message->payload[payload_size] = '\0';

    memcpy(&message->value, ptr + 1 + sizeof(uint64_t) + sizeof(uint16_t) + 4 + payload_size, sizeof(int));

    *out_message = message;
}

NFAPI_CRC_INDICATION_PDU* create_crc_pdu(uint8_t *RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) {
        perror("Failed to allocate memory for PDU");
        exit(EXIT_FAILURE);
    }
    memcpy(pdu->RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG, 4);
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = CRCFLAG;
    pdu->next = NULL;

    return pdu;
}

void add_crc_pdu(NFAPI_CRC_INDICATION_PDU **head, NFAPI_CRC_INDICATION_PDU *pdu) {
    if (!*head) {
        *head = pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU *current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = pdu;
    }
}

void free_crc_pdus(NFAPI_CRC_INDICATION_PDU *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU *temp = head;
        head = head->next;
        free(temp);
    }
}
