    size_t payload_size;
    char *payload;
    time_t last_active_time; // For tracking inactivity
} LTE_PHY_RX_UE_INFO;

typedef struct {
    LTE_PHY_RX_UE_INFO **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t max_idle_period;
} UE_Info_Manager;

// Function prototypes
void initialize_manager(UE_Info_Manager *manager, size_t initial_capacity, time_t max_idle_period);
void destroy_manager(UE_Info_Manager *manager);
int add_or_update_entry(UE_Info_Manager *manager, LTE_PHY_RX_UE_INFO *entry);
LTE_PHY_RX_UE_INFO* get_entry_by_rnti(UE_Info_Manager *manager, int rnti);
void remove_inactive_entries(UE_Info_Manager *manager);
void serialize_array_to_disk(const UE_Info_Manager *manager, const char *file_path);
void compact_memory(UE_Info_Manager *manager);
void update_max_size_based_on_load(UE_Info_Manager *manager);
void print_statistics(const UE_Info_Manager *manager);

// Implementations
void initialize_manager(UE_Info_Manager *manager, size_t initial_capacity, time_t max_idle_period) {
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->array = malloc(initial_capacity * sizeof(LTE_PHY_RX_UE_INFO *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->max_idle_period = max_idle_period;
}

void destroy_manager(UE_Info_Manager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->array[i]->payload);
        free(manager->array[i]);
    }
    free(manager->array);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}

int add_or_update_entry(UE_Info_Manager *manager, LTE_PHY_RX_UE_INFO *entry) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->rnti == entry->rnti) {
            free(manager->array[i]->payload);
            manager->array[i]->payload = malloc(entry->payload_size);
            memcpy(manager->array[i]->payload, entry->payload, entry->payload_size);
            manager->array[i]->payload_size = entry->payload_size;
            manager->array[i]->last_active_time = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Updated
        }
    }

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_PHY_RX_UE_INFO **new_array = realloc(manager->array, new_capacity * sizeof(LTE_PHY_RX_UE_INFO *));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->count] = malloc(sizeof(LTE_PHY_RX_UE_INFO));
    *manager->array[manager->count] = *entry;
    manager->array[manager->count]->last_active_time = time(NULL);
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 1; // Added
}

LTE_PHY_RX_UE_INFO* get_entry_by_rnti(UE_Info_Manager *manager, int rnti) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i]->rnti == rnti) {
            pthread_mutex_unlock(&manager->lock);
            return manager->array[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void remove_inactive_entries(UE_Info_Manager *manager) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count;) {
        if ((now - manager->array[i]->last_active_time) > manager->max_idle_period) {
            free(manager->array[i]->payload);
            free(manager->array[i]);
            memmove(&manager->array[i], &manager->array[i + 1], (manager->count - i - 1) * sizeof(LTE_PHY_RX_UE_INFO *));
            manager->count--;
        } else {
            ++i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

