    char* message;
} NASMessage;

// Define a structure to hold a single LTE UE context.
typedef struct UEContext {
    S1UEContext s1_ue_context;
    MMEEConfiguration mme_configuration;
    NASMessage *nas_messages;
    size_t nas_message_count;
    pthread_mutex_t mutex; // Mutex for thread-safe access
} UEContext;

// Define a structure to manage multiple LTE UE contexts dynamically.
typedef struct {
    UEContext **ue_contexts;
    size_t count;
    pthread_mutex_t list_mutex; // Mutex for managing the collection of UE contexts
    pthread_rwlock_t rwlock;    // Read-write lock for optimizing concurrent access
} UEContextManager;

// Function to initialize a new NAS Message
NASMessage* create_nas_message(const char *message) {
    if (!message) return NULL;

    NASMessage *nas_msg = (NASMessage *)malloc(sizeof(NASMessage));
    if (!nas_msg) return NULL;

    nas_msg->message = strdup(message);
    if (!nas_msg->message) {
        free(nas_msg);
        return NULL;
    }

    return nas_msg;
}

// Function to destroy a NAS Message
void destroy_nas_message(NASMessage *nas_msg) {
    if (nas_msg) {
        free(nas_msg->message);
        free(nas_msg);
    }
}

// Function to initialize and configure a new LTE UE context.
UEContext* create_ue_context() {
    UEContext *ue_ctx = (UEContext *)malloc(sizeof(UEContext));
    if (!ue_ctx) return NULL;

    pthread_mutex_init(&ue_ctx->mutex, NULL);

    // Initialize S1 UE Context and MME Configuration
    // Placeholder code for initialization:
    // ue_ctx->s1_ue_context = initialize_s1_ue_context();
    // ue_ctx->mme_configuration = initialize_mme_configuration();

    ue_ctx->nas_messages = NULL;
    ue_ctx->nas_message_count = 0;

    return ue_ctx;
}

// Function to add a NAS Message to a UE context
int add_nas_message(UEContext *ue_ctx, const char *message) {
    if (!ue_ctx || !message) return -1;

    pthread_mutex_lock(&ue_ctx->mutex);

    UEContext *tmp_ue = (UEContext *)malloc(sizeof(UEContext));
    if (!tmp_ue) {
        pthread_mutex_unlock(&ue_ctx->mutex);
        return -1;
    }

    tmp_ue->nas_message_count = ue_ctx->nas_message_count + 1;
    tmp_ue->nas_messages = realloc(ue_ctx->nas_messages, sizeof(NASMessage) * tmp_ue->nas_message_count);

    if (!tmp_ue->nas_messages) {
        free(tmp_ue);
        pthread_mutex_unlock(&ue_ctx->mutex);
        return -1;
    }

    NASMessage *new_msg = create_nas_message(message);
    if (!new_msg) {
        // Clean up on failure
        for (size_t i = 0; i < tmp_ue->nas_message_count - 1; ++i) {
            destroy_nas_message(&tmp_ue->nas_messages[i]);
        }
        free(tmp_ue->nas_messages);
        pthread_mutex_unlock(&ue_ctx->mutex);
        return -1;
    }

    new_msg = &tmp_ue->nas_messages[tmp_ue->nas_message_count - 1];
    ue_ctx->nas_messages = tmp_ue->nas_messages;

    pthread_mutex_unlock(&ue_ctx->mutex);

    // Free the temporary UE context
    free(tmp_ue);

    return 0;
}

// Function to initialize a UE Context Manager
UEContextManager* create_ue_context_manager() {
    UEContextManager *manager = (UEContextManager *)malloc(sizeof(UEContextManager));
    if (!manager) return NULL;

    manager->ue_contexts = NULL;
    manager->count = 0;

    pthread_mutex_init(&manager->list_mutex, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

// Function to add a new UE context to the manager
int add_ue_context(UEContextManager *manager) {
    if (!manager) return -1;

    pthread_rwlock_wrlock(&manager->rwlock);

    UEContext **new_contexts = realloc(manager->ue_contexts, sizeof(UEContext *) * (manager->count + 1));
    if (!new_contexts) {
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    UEContext *new_ue_ctx = create_ue_context();
    if (!new_ue_ctx) {
        free(new_contexts);
        pthread_rwlock_unlock(&manager->rwlock);
        return -1;
    }

    new_contexts[manager->count] = new_ue_ctx;
    manager->ue_contexts = new_contexts;
    manager->count += 1;

    pthread_rwlock_unlock(&manager->rwlock);

    return 0;
}

// Function to clean up and free the resources used by a UE Context Manager
void destroy_ue_context_manager(UEContextManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        for (size_t j = 0; j < manager->ue_contexts[i]->nas_message_count; ++j) {
            destroy_nas_message(&manager->ue_contexts[i]->nas_messages[j]);
        }
        free(manager->ue_contexts[i]->nas_messages);
        pthread_mutex_destroy(&manager->ue_contexts[i]->mutex);
        free(manager->ue_contexts[i]);
    }

    free(manager->ue_contexts);

    pthread_mutex_destroy(&manager->list_mutex);
    pthread_rwlock_destroy(&manager->rwlock);

    free(manager);
