['Below is a C code implementation for managing a dynamic array of network sessions with considerations for efficiency, scalability, and safety.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define INACTIVITY_TIMEOUT 300 // seconds

typedef struct {
    int session_id;
    time_t last_activity;
    char *packet_data;
    size_t packet_size;
} NetworkSession;

typedef struct {
    NetworkSession *sessions;
    size_t capacity;
    size_t count;
} SessionManager;

// Initialize the session manager
void initialize_session_manager(SessionManager *manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->sessions = (NetworkSession *)calloc(manager->capacity, sizeof(NetworkSession));
}

// Resize the dynamic array when needed
static void resize_sessions(SessionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    NetworkSession *new_sessions = (NetworkSession *)realloc(manager->sessions, new_capacity * sizeof(NetworkSession));

    if (new_sessions != NULL) {
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize sessions.\n");
        exit(EXIT_FAILURE);
    }
}

// Add a new session
void add_session(SessionManager *manager, int session_id, const char *data, size_t data_size) {
    if (manager->count == manager->capacity) {
        resize_sessions(manager);
    }

    NetworkSession *session = &manager->sessions[manager->count];
    session->session_id = session_id;
    session->last_activity = time(NULL);
    session->packet_data = (char *)malloc(data_size);

    if (session->packet_data != NULL) {
        memcpy(session->packet_data, data, data_size);
        session->packet_size = data_size;
        manager->count++;
    } else {
        fprintf(stderr, "Failed to allocate memory for packet data.\n");
        exit(EXIT_FAILURE);
    }
}

// Periodically clean up inactive sessions
void cleanup_inactive_sessions(SessionManager *manager) {
    time_t now = time(NULL);

    for (size_t i = 0; i < manager->count; ) {
        NetworkSession *session = &manager->sessions[i];
        if (difftime(now, session->last_activity) > INACTIVITY_TIMEOUT) {
            free(session->packet_data);
            memmove(&manager->sessions[i], &manager->sessions[i + 1],
                    (manager->count - i - 1) * sizeof(NetworkSession));
            manager->count--;
        } else {
            i++;
        }
    }
}

// Deallocate all resources
void deallocate_sessions(SessionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->sessions[i].packet_data);
    }
    free(manager->sessions);
    manager->sessions = NULL;
    manager->capacity = 0;
    manager->count = 0;
}

// Example of how to use the session manager
int main() {
    SessionManager manager;
    initialize_session_manager(&manager);

    // Simulate adding sessions
    add_session(&manager, 1, "Packet data for session 1", 20);
    sleep(2); // simulate time passing

    add_session(&manager, 2, "Packet data for session 2", 30);

    // Cleanup inactive sessions periodically
    cleanup_inactive_sessions(&manager);

    deallocate_sessions(&manager);

    return 0;
}
```

### Key Features:
- **Dynamic Array Management**: The `resize_sessions` function doubles the array size when it reaches capacity.
- **Session Handling**: Each session includes a unique ID, timestamp, and packet data buffer.
- **Memory Safety**: Ensures safe memory allocation/deallocation to prevent leaks.
- **Inactivity Cleanup**: Periodically removes sessions that have been inactive beyond the specified timeout.
- **Adaptability**: The design allows for easy integration of new features or changes in logic.']

