#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* initialize_memory_pool(size_t element_count) {
    if (element_count > MAX_ELEMENTS) {
        fprintf(stderr, "Requested more elements than maximum allowed\n");
        return NULL;
    }

    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) {
        perror("Failed to allocate memory for the pool");
        return NULL;
    }

    mp->pool_size = element_count;
    mp->pool = calloc(mp->pool_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        perror("Failed to allocate memory for the data pool");
        free(mp);
        return NULL;
    }

    pthread_mutex_init(&mp->lock, NULL);

    // Initialize each element with some default values
    for (size_t i = 0; i < mp->pool_size; ++i) {
        mp->pool[i].RX_UE_INFORMATION_TAG = rand();  // Example initialization
        mp->pool[i].RNTI = rand();
        mp->pool[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return mp;
}

void* get_element(MemoryPool *mp, size_t index) {
    if (!mp || index >= mp->pool_size) {
        fprintf(stderr, "Invalid pool or index out of bounds\n");
        return NULL;
    }

    pthread_mutex_lock(&mp->lock);
    void *element = &mp->pool[index];
    pthread_mutex_unlock(&mp->lock);

    return element;
}

void release_memory_pool(MemoryPool *mp) {
    if (mp) {
        pthread_mutex_destroy(&mp->lock);
        free(mp->pool);
        free(mp);
    }
}

int main() {
    size_t desired_elements = 5000; // Example: request half of the maximum capacity
    MemoryPool *mp = initialize_memory_pool(desired_elements);

    if (mp) {
        for (size_t i = 0; i < mp->pool_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *element = get_element(mp, i);
            if (element) {
                // Use the element as needed
                printf("Element %zu: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%d\n",
                       i, element->RX_UE_INFORMATION_TAG, element->RNTI,
                       element->CRC_INDICATION_REL8_TAG.CRCFLAG);
            }
        }

        release_memory_pool(mp);
    }

    return 0;
}
