// Define the SensorData structure
typedef struct {
    double temperature;
    double humidity;
    double pressure;
    time_t timestamp; // Unix timestamp for simplicity
} SensorData;

// Define a structure to manage the dynamically allocated array of SensorData
typedef struct {
    SensorData *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SensorDataManager;

// Function prototypes
SensorDataManager* create_sensor_manager(size_t initial_capacity);
void free_sensor_manager(SensorDataManager *manager);
int add_sensor_data(SensorDataManager *manager, const SensorData *new_data);
int serialize_to_disk(const SensorDataManager *manager, const char *file_path);
int deserialize_from_disk(SensorDataManager *manager, const char *file_path);

// Create a new sensor manager with an initial capacity
SensorDataManager* create_sensor_manager(size_t initial_capacity) {
    SensorDataManager *manager = malloc(sizeof(SensorDataManager));
    if (!manager) return NULL;

    manager->data = malloc(initial_capacity * sizeof(SensorData));
    if (!manager->data) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;

    return manager;
}

// Free the sensor manager and its resources
void free_sensor_manager(SensorDataManager *manager) {
    if (manager) {
        free(manager->data);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

// Add new sensor data to the manager, resizing if necessary
int add_sensor_data(SensorDataManager *manager, const SensorData *new_data) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        SensorData *new_data_array = realloc(manager->data, new_capacity * sizeof(SensorData));
        if (!new_data_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->data = new_data_array;
        manager->capacity = new_capacity;
    }

    memcpy(&manager->data[manager->count], new_data, sizeof(SensorData));
    manager->count++;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

// Serialize the sensor data to disk in a simple binary format
int serialize_to_disk(const SensorDataManager *manager, const char *file_path) {
    FILE *file = fopen(file_path, "wb");
    if (!file) return -1;

    pthread_mutex_lock((pthread_mutex_t*)&manager->lock);

    size_t header_size = sizeof(size_t);
    fwrite(&manager->count, header_size, 1, file);

    fwrite(manager->data, sizeof(SensorData), manager->count, file);

    fclose(file);
    pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);

    return 0; // Success
}

// Deserialize the sensor data from disk
int deserialize_from_disk(SensorDataManager *manager, const char *file_path) {
    FILE *file = fopen(file_path, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&manager->lock);

    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);

    SensorData *temp_data = realloc(manager->data, new_count * sizeof(SensorData));
    if (!temp_data && new_count > 0) {
        fclose(file);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    manager->data = temp_data;
    manager->capacity = new_count;
    fread(manager->data, sizeof(SensorData), new_count, file);

    manager->count = new_count;

    fclose(file);
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

