#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generate_crcflag(int signal_quality) {
    // Simulate a probabilistic function for signal quality
    return (rand() % 100) < (70 + signal_quality); // Bias towards poor conditions
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t n, int (*signal_quality_func)(void)) {
    if (n > MAX_ELEMENTS) {
        fprintf(stderr, "Requested number of elements exceeds maximum limit.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t attempt = 0;
    const size_t max_attempts = 5;

    while (attempt < max_attempts) {
        array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array != NULL) break; // Allocation succeeded

        // Exponential backoff
        usleep((1 << attempt) * 1000);
        attempt++;
    }

    if (array == NULL) {
        fprintf(stderr, "Failed to allocate memory after %zu attempts.\n", max_attempts);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        array[i].RNTI = rand() % 10000; // Example value
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Example value

        int signal_quality = signal_quality_func(); // Get current signal quality
        array[i].CRCFLAG = generate_crcflag(signal_quality);
    }

    return array;
}

int dummy_signal_quality_func(void) {
    // Placeholder for a real signal quality function
    return rand() % 30; // Simulate variable signal quality (0-29)
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array != NULL) {
        free(array);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    size_t n = 100; // Example: Allocate and populate an array of 100 elements
    NFAPI_CRC_INDICATION_PDU_T *data_array = allocate_and_populate_array(n, dummy_signal_quality_func);

    if (data_array != NULL) {
        // Use the data_array for further processing...

        free_array(data_array); // Free allocated memory when done
    }

    return 0;
}
