// Define structure for port configuration
typedef struct PortConfig {
    int protocol; // 1 for TCP, 2 for UDP
    int start_port;
    int end_port;
    unsigned int timeout_ms; // Default timeout in milliseconds
    struct PortConfig* next;
} PortConfig;

// Define structure for Network Interface Management (NIM) object
typedef struct NIM {
    char mac_address[18]; // Format: XX:XX:XX:XX:XX:XX
    char ip_address[16];  // IPv4 or IPv6 format
    PortConfig* ports;
    struct NIM* next;
} NIM;

// Function to create a new PortConfig node
PortConfig* create_port_config(int protocol, int start_port, int end_port, unsigned int timeout_ms) {
    PortConfig* new_port = (PortConfig*)malloc(sizeof(PortConfig));
    if (!new_port) {
        perror("Failed to allocate memory for port configuration");
        exit(EXIT_FAILURE);
    }
    new_port->protocol = protocol;
    new_port->start_port = start_port;
    new_port->end_port = end_port;
    new_port->timeout_ms = timeout_ms;
    new_port->next = NULL;
    return new_port;
}

// Function to create a new NIM node
NIM* create_nim(const char* mac_address, const char* ip_address) {
    NIM* new_nim = (NIM*)malloc(sizeof(NIM));
    if (!new_nim) {
        perror("Failed to allocate memory for NIM object");
        exit(EXIT_FAILURE);
    }
    strncpy(new_nim->mac_address, mac_address, 17);
    new_nim->mac_address[17] = '\0';
    strncpy(new_nim->ip_address, ip_address, 15);
    new_nim->ip_address[15] = '\0';
    new_nim->ports = NULL;
    new_nim->next = NULL;
    return new_nim;
}

// Function to add a port configuration to an NIM object
void add_port_to_nim(NIM* nim, PortConfig* port_config) {
    if (!nim || !port_config) return;

    port_config->next = nim->ports;
    nim->ports = port_config;
}

// Function to initialize and populate the linked list of NIM objects
NIM* initialize_and_populate_nim_list() {
    // Example initialization
    NIM* head = create_nim("00:1A:2B:3C:4D:5E", "192.168.1.1");

    PortConfig* tcp_port = create_port_config(1, 8080, 8090, 1000);
    add_port_to_nim(head, tcp_port);

    PortConfig* udp_port = create_port_config(2, 9000, 9010, 1500);
    add_port_to_nim(head, udp_port);

    // Adding another NIM object
    NIM* second_nim = create_nim("00:1A:2B:3C:4D:5F", "192.168.1.2");
    PortConfig* tcp_port_2 = create_port_config(1, 7070, 7080, 1200);
    add_port_to_nim(second_nim, tcp_port_2);

    second_nim->next = head; // Linking the NIM objects
    return second_nim;
}

// Function to free all allocated memory for the linked list of NIM objects
void free_nim_list(NIM* head) {
    NIM* nim;
    while (head) {
        PortConfig* port_config;
        nim = head;
        head = head->next;

        // Free port configurations
        while (nim->ports) {
            port_config = nim->ports;
            nim->ports = nim->ports->next;
            free(port_config);
        }

        // Free NIM object
        free(nim);
    }
}

// Example usage
int main() {
    NIM* nim_list = initialize_and_populate_nim_list();

    // Use the list...

    free_nim_list(nim_list);

    return 0;
}
