    unsigned long weighted_sum;
} Transaction;

int filter_transactions(NFAPI_CRC_INDICATION_PDU_T *array, size_t num_elements,
                        unsigned int age_threshold, int max_recent_count,
                        double weight_factor, unsigned int *max_weighted_sum,
                        unsigned int *transaction_id) {
    if (!array || !max_weighted_sum || !transaction_id) return -1;

    pthread_mutex_lock(&mtx);

    // Metrics
    unsigned long total_weighted_sum = 0;
    size_t count_recent = 0;
    Transaction max_transaction = { .transaction_id = 0, .weighted_sum = 0 };

    for (size_t i = 0; i < num_elements; ++i) {
        unsigned int age = rand() % 10; // Simulated transaction age
        double weight = array[i].RX_UE_INFORMATION_TAG * weight_factor;

        if (age <= age_threshold) {
            count_recent++;
            total_weighted_sum += weight;

            if (weight > max_transaction.weighted_sum) {
                max_transaction.transaction_id = i;
                max_transaction.weighted_sum = weight;
            }
        }
    }

    if (count_recent > max_recent_count) {
        fprintf(stderr, "Exceeded recent transaction count limit.\n");
    }

    *max_weighted_sum = max_transaction.weighted_sum;
    *transaction_id = max_transaction.transaction_id;

    pthread_mutex_unlock(&mtx);

    return 0;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}

