    unsigned int max_weighted_sum, transaction_id;
    filter_transactions(array, num_elements, age_threshold, max_recent_count,
                        weight_factor, &max_weighted_sum, &transaction_id);

    printf("Max Weighted Sum: %u, Transaction ID: %u\n", max_weighted_sum, transaction_id);

