        if (!crc_validate_function(array[i])) {
            free(array);
            *error_code = VALIDATION_ERROR;
            return NULL;
        }
    }

    *error_code = SUCCESS;
    return array;
}

void free_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    pthread_mutex_lock(&mutex);
    if (array) {
        free(array);
    }
    pthread_mutex_unlock(&mutex);
}
