#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define constants for initial size of dynamic array and maximum size allowed
#define INITIAL_SIZE 10
#define MAX_SIZE 1000

typedef struct {
    char ip[16];      // IPv4 address space is 15 characters + null terminator
    int port;
    int status;       // Status flag (e.g., 1 for healthy, 0 for unhealthy)
} TCPConnection;

// Dynamic array structure to manage connections
typedef struct {
    TCPConnection *connections;
    size_t size;
    size_t capacity;
} ConnectionManager;

// Function declarations
int init_connection_manager(ConnectionManager *manager);
int add_connection(ConnectionManager *manager, const char *ip, int port, int status);
int update_connection(ConnectionManager *manager, const char *ip, int port, int status);
TCPConnection* find_connection(ConnectionManager *manager, const char *ip, int port);
void free_connection_manager(ConnectionManager *manager);

// Initialize the connection manager with an initial capacity
int init_connection_manager(ConnectionManager *manager) {
    if (!manager) return -1;

    manager->connections = malloc(INITIAL_SIZE * sizeof(TCPConnection));
    if (!manager->connections) {
        fprintf(stderr, "Memory allocation failed for connections.\n");
        return -1;
    }

    manager->size = 0;
    manager->capacity = INITIAL_SIZE;
    return 0;
}

// Add a new connection to the dynamic array
int add_connection(ConnectionManager *manager, const char *ip, int port, int status) {
    if (!manager || !ip) return -1;

    TCPConnection *connection = find_connection(manager, ip, port);
    if (connection != NULL) {
        connection->status = status;
        printf("Updated existing connection: %s:%d\n", ip, port);
        return 0;
    }

    // Resize the array if necessary
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_SIZE) {
            fprintf(stderr, "Maximum connection capacity reached.\n");
            return -1;
        }

        TCPConnection *new_connections = realloc(manager->connections, new_capacity * sizeof(TCPConnection));
        if (!new_connections) {
            fprintf(stderr, "Memory reallocation failed for connections.\n");
            return -1;
        }

        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    // Add the new connection
    strcpy(manager->connections[manager->size].ip, ip);
    manager->connections[manager->size].port = port;
    manager->connections[manager->size].status = status;

    printf("Added new connection: %s:%d\n", ip, port);

    ++manager->size;
    return 0;
}

// Update an existing connection
int update_connection(ConnectionManager *manager, const char *ip, int port, int status) {
    if (!manager || !ip) return -1;

    TCPConnection *connection = find_connection(manager, ip, port);
    if (connection != NULL) {
        connection->status = status;
        printf("Updated connection: %s:%d\n", ip, port);
        return 0;
    }

    fprintf(stderr, "Connection not found for update: %s:%d\n", ip, port);
    return -1;
}

// Find a connection by IP and port
TCPConnection* find_connection(ConnectionManager *manager, const char *ip, int port) {
    if (!manager || !ip) return NULL;

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->connections[i].ip, ip) == 0 && 
            manager->connections[i].port == port) {
            return &manager->connections[i];
        }
    }

    return NULL;
}

// Free the memory allocated for connection management
void free_connection_manager(ConnectionManager *manager) {
    if (manager && manager->connections) {
        free(manager->connections);
        manager->connections = NULL;
        manager->size = 0;
        manager->capacity = 0;
    }
}
