    size_t size;
    size_t capacity;
} TcpConnectionsArray;

// Define a linked list node for FSA states
typedef struct FsaStateListNode {
    FsaState* state;
    struct FsaStateListNode* next;
} FsaStateListNode;

// Function prototypes
TcpConnectionsArray* initializeTcpConnections(size_t initialCapacity);
int addOrUpdateTcpConnection(TcpConnectionsArray* array, TcpConnection* connection);
void freeTcpConnectionsArray(TcpConnectionsArray* array);

FsaStateListNode* manageFsaStates(FsaState* fsa, size_t numStates, int lastStateId);
void cleanupFsaStateList(FsaStateListNode* head);

// Helper functions for FSA traversal and memory management
static FsaStateListNode* addStateToList(FsaStateListNode** head, FsaState* state);
static void traverseAndCollect(FsaState* fsa, size_t numStates, int lastStateId, FsaStateListNode** head, int visited[]);
static void freeFsaStateList(FsaStateListNode* head);

// Implementation
TcpConnectionsArray* initializeTcpConnections(size_t initialCapacity) {
    TcpConnectionsArray* array = (TcpConnectionsArray*)malloc(sizeof(TcpConnectionsArray));
    if (!array) return NULL;

    array->connections = (TcpConnection**)calloc(initialCapacity, sizeof(TcpConnection*));
    if (!array->connections) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initialCapacity;
    return array;
}

int addOrUpdateTcpConnection(TcpConnectionsArray* array, TcpConnection* connection) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->connections[i]->id == connection->id) {
            free(array->connections[i]);
            array->connections[i] = connection;
            return 1;
        }
    }

    if (array->size >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        TcpConnection** newConnections = (TcpConnection**)realloc(array->connections, newCapacity * sizeof(TcpConnection*));
        if (!newConnections) return 0;

        array->connections = newConnections;
        array->capacity = newCapacity;
    }

    array->connections[array->size++] = connection;
    return 1;
}

void freeTcpConnectionsArray(TcpConnectionsArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->connections[i]);
    }
    free(array->connections);
    free(array);
}

FsaStateListNode* manageFsaStates(FsaState* fsa, size_t numStates, int lastStateId) {
    if (!fsa || numStates == 0) return NULL;

    FsaStateListNode* head = NULL;
    int visited[numStates];
    for (size_t i = 0; i < numStates; ++i) {
        visited[i] = 0;
    }

    traverseAndCollect(fsa, numStates, lastStateId, &head, visited);
    return head;
}

void cleanupFsaStateList(FsaStateListNode* head) {
    freeFsaStateList(head);
}

// Helper functions
static FsaStateListNode* addStateToList(FsaStateListNode** head, FsaState* state) {
    FsaStateListNode* newNode = (FsaStateListNode*)malloc(sizeof(FsaStateListNode));
    if (!newNode) return NULL;

    newNode->state = state;
    newNode->next = *head;
    *head = newNode;
    return newNode;
}

static void traverseAndCollect(FsaState* fsa, size_t numStates, int lastStateId, FsaStateListNode** head, int visited[]) {
    for (size_t i = 0; i < numStates; ++i) {
        if (fsa[i].stateId == lastStateId && !visited[i]) {
            visited[i] = 1;
            addStateToList(head, &fsa[i]);

            for (size_t j = 0; j < fsa[i].numTransitions; ++j) {
                int nextStateId = *(int*)fsa[i].transitions[j];
                if (!visited[nextStateId]) {
                    traverseAndCollect(fsa, numStates, nextStateId, head, visited);
                }
            }
        }
    }
}

static void freeFsaStateList(FsaStateListNode* head) {
    FsaStateListNode* current = head;
    while (current) {
        FsaStateListNode* next = current->next;
        free(current);
        current = next;
    }
}
