#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_FRAMES_PER_SECOND 10000
#define TIMESTAMP_INVALID ((unsigned long long)-1)

typedef struct {
    unsigned long long timestamp;
    size_t packet_length;
    void *payload;
} FrameBuffer;

typedef struct {
    FrameBuffer *frames;
    size_t count;
    size_t capacity;
} FrameBufferPool;

// Function to initialize the frame buffer pool
bool init_frame_buffer_pool(FrameBufferPool *pool, size_t initial_capacity) {
    if (!pool || initial_capacity == 0) return false;

    pool->frames = (FrameBuffer *)malloc(initial_capacity * sizeof(FrameBuffer));
    if (!pool->frames) return false;

    pool->count = 0;
    pool->capacity = initial_capacity;
    return true;
}

// Function to add a frame to the pool
bool add_frame_to_pool(FrameBufferPool *pool, unsigned long long timestamp, size_t packet_length, const void *data) {
    if (!pool || timestamp == TIMESTAMP_INVALID || packet_length == 0 || !data) return false;

    // Resize the pool if necessary
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        FrameBuffer *new_frames = (FrameBuffer *)realloc(pool->frames, new_capacity * sizeof(FrameBuffer));
        if (!new_frames) return false;

        pool->frames = new_frames;
        pool->capacity = new_capacity;
    }

    // Add the frame
    FrameBuffer *frame = &pool->frames[pool->count++];
    frame->timestamp = timestamp;
    frame->packet_length = packet_length;
    frame->payload = malloc(packet_length);
    if (!frame->payload) {
        // Rollback in case of allocation failure
        pool->count--;
        return false;
    }
    memcpy(frame->payload, data, packet_length);

    return true;
}

// Function to iterate over frames without copying their data
void process_frames(FrameBufferPool *pool, void (*process_frame)(FrameBuffer *)) {
    if (!pool || !process_frame) return;

    for (size_t i = 0; i < pool->count; ++i) {
        process_frame(&pool->frames[i]);
    }
}

// Function to free the frame buffer pool
void free_frame_buffer_pool(FrameBufferPool *pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->frames[i].payload);
    }
    free(pool->frames);

    pool->frames = NULL;
    pool->count = 0;
    pool->capacity = 0;
}

// Example usage
void example_process_frame(FrameBuffer *frame) {
    // Process the frame (e.g., logging, further analysis)
    printf("Timestamp: %llu, Length: %zu\n", frame->timestamp, frame->packet_length);
}

int main() {
    FrameBufferPool pool;
    if (!init_frame_buffer_pool(&pool, 100)) {
        fprintf(stderr, "Failed to initialize frame buffer pool.\n");
        return EXIT_FAILURE;
    }

    // Example data
    unsigned long long timestamp = 1234567890ULL;
    size_t packet_length = 128;
    char data[packet_length];

    // Populate example data
    memset(data, 'A', packet_length);

    if (!add_frame_to_pool(&pool, timestamp, packet_length, data)) {
        fprintf(stderr, "Failed to add frame to pool.\n");
        free_frame_buffer_pool(&pool);
        return EXIT_FAILURE;
    }

    process_frames(&pool, example_process_frame);
    free_frame_buffer_pool(&pool);

    return EXIT_SUCCESS;
}
```

### Trade-offs and Considerations:

- **Time Complexity**: The `add_frame_to_pool` function has an amortized O(1) time complexity due to dynamic resizing. Iterating over frames is O(n).

- **Space Complexity**: Memory usage scales with the number of frames, but reallocates in chunks to balance between frequent allocations and wasted space.

- **Ease of Future Modifications**: The `FrameBuffer` structure can be easily extended by adding new fields. The pool design supports seamless integration with real-time processing pipelines due to efficient memory management.

- **Robustness**: Checks are in place for null pointers, invalid timestamps, and buffer overflows. Memory allocation failures are handled gracefully.

This code provides a robust foundation for handling high-throughput frame data efficiently while allowing future extensions.']

