TcpConnection* find_connection(ConnectionArray *array, const char *ip, uint16_t port);

// Initialize the dynamic array of TCP connections
ConnectionArray* init_connection_array(size_t initial_capacity) {
    ConnectionArray *array = (ConnectionArray*)malloc(sizeof(ConnectionArray));
    if (!array) return NULL;

    array->connections = (TcpConnection*)calloc(initial_capacity, sizeof(TcpConnection));
    if (!array->connections) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Free the memory allocated for the dynamic array
void free_connection_array(ConnectionArray *array) {
    if (array) {
        free(array->connections);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

// Add a new connection or update an existing one
int add_or_update_connection(ConnectionArray *array, const char *ip, uint16_t port, bool is_healthy) {
    if (!array || !ip) return -1;

    pthread_mutex_lock(&array->lock);

    TcpConnection *conn = find_connection(array, ip, port);
    if (conn) {
        conn->is_healthy = is_healthy;
    } else {
        if (array->count == array->capacity) {
            size_t new_capacity = array->capacity * 2;
            TcpConnection *new_connections = (TcpConnection*)realloc(array->connections, new_capacity * sizeof(TcpConnection));
            if (!new_connections) {
                pthread_mutex_unlock(&array->lock);
                return -1;
            }
            array->connections = new_connections;
            array->capacity = new_capacity;
        }

        strcpy(array->connections[array->count].client_ip, ip);
        array->connections[array->count].port = port;
        array->connections[array->count].is_healthy = is_healthy;
        array->count++;
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Find a connection by IP and port
TcpConnection* find_connection(ConnectionArray *array, const char *ip, uint16_t port) {
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->connections[i].client_ip, ip) == 0 && 
            array->connections[i].port == port) {
            return &array->connections[i];
        }
    }
    return NULL;
}

// Example usage
int main() {
    ConnectionArray *conn_array = init_connection_array(10);
    if (!conn_array) {
        fprintf(stderr, "Failed to initialize connection array.\n");
        return 1;
    }

    add_or_update_connection(conn_array, "192.168.1.1", 8080, true);
    TcpConnection *conn = find_connection(conn_array, "192.168.1.1", 8080);
    if (conn) {
