int create_and_populate_nfa_list(NFAPI_CRC_INDICATION_PDU_T **nfa_list, size_t num_entries) {
    if (num_entries == 0 || nfa_list == NULL) return -1;

    *nfa_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfa_list == NULL) return -2;

    for (size_t i = 0; i < num_entries; ++i) {
