        (*nfa_list)[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        (*nfa_list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
    }

    return 0;
}

int resolve_hostnames(const char *hostnames[], size_t num_hostnames, char **ip_addresses) {
    if (num_hostnames > MAX_HOSTNAMES || ip_addresses == NULL) return -3;

    struct addrinfo hints, *res, *p;
    int status;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 addresses

    for (size_t i = 0; i < num_hostnames; ++i) {
        ip_addresses[i] = NULL;

        if ((status = getaddrinfo(hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            return -4;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            char ipstr[INET_ADDRSTRLEN];
            void *ip = &((struct sockaddr_in *)p->ai_addr)->sin_addr;

            if (inet_ntop(p->ai_family, ip, ipstr, sizeof(ipstr)) != NULL) {
                ip_addresses[i] = strdup(ipstr);
                break;
            }
        }

        freeaddrinfo(res);

        if (ip_addresses[i] == NULL) return -5; // Failed to resolve
    }

    return 0;
}

void cleanup(char *ip_addresses[], size_t num_hostnames, NFAPI_CRC_INDICATION_PDU_T *nfa_list) {
    for (size_t i = 0; i < num_hostnames; ++i) {
        if (ip_addresses[i] != NULL) free(ip_addresses[i]);
    }
    if (nfa_list != NULL) free(nfa_list);
}

