    if (nfa_status != 0) {
        fprintf(stderr, "Error creating NFA list\n");
        return EXIT_FAILURE;
    }

    int dns_status = resolve_hostnames(hostnames, num_hostnames, ip_addresses);
    if (dns_status != 0) {
        fprintf(stderr, "Error resolving hostnames\n");
        cleanup(ip_addresses, num_hostnames, nfa_list);
        return EXIT_FAILURE;
    }

    // Use the resolved IP addresses and NFA list as needed...

    cleanup(ip_addresses, num_hostnames, nfa_list);

    return EXIT_SUCCESS;
}
