['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint64_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp; // for cleanup based on age
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    pthread_mutex_t lock;
    size_t max_size; // Maximum list size before LRU eviction
    time_t cleanup_threshold; // Time in seconds to determine old entries
} CRCList;

// Initialize the list
void initialize_list(CRCList *list, size_t max_size, time_t cleanup_threshold) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->max_size = max_size;
    list->cleanup_threshold = cleanup_threshold;
}

// Cleanup old entries
void cleanup_old_entries(CRCList *list) {
    time_t now = time(NULL);
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *prev = NULL;

    while (current != NULL) {
        if ((now - current->timestamp) > list->cleanup_threshold) {
            // Remove the node
            if (prev == NULL) { // Removing head
                list->head = current->next;
                if (list->head) list->head->prev = NULL;
            } else {
                prev->next = current->next;
                if (current->next != NULL) current->next->prev = prev;
            }
            if (current == list->tail) { // Removing tail
                list->tail = prev;
            }

            NFAPI_CRC_INDICATION_PDU_T *temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Insert a node
void insert_node(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);

    // Cleanup old entries before insertion to manage size and age
    cleanup_old_entries(list);

    // Check if the list is full, remove LRU (tail)
    if ((NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    while (get_list_size(list) >= list->max_size && list->tail != NULL) { // Remove LRU
        NFAPI_CRC_INDICATION_PDU_T *lru = list->tail;
        list->tail = lru->prev;
        if (list->tail) {
            list->tail->next = NULL;
        }
        free(lru);
    }

    node->timestamp = time(NULL); // Set current timestamp
    node->next = NULL;

    if (list->head == NULL) { // Empty list case
        list->head = list->tail = node;
        node->prev = NULL;
    } else {
        list->tail->next = node; // Add to the end
        node->prev = list->tail;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove a node by tag and RNTI
void remove_node(CRCList *list, uint64_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG &&
            current->RNTI == RNTI) {

            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next; // Removing head
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev; // Removing tail
            }

            free(current);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Get the size of the list
size_t get_list_size(CRCList *list) {
    size_t count = 0;
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return count;
}

// Destroy the list and free memory
void destroy_list(CRCList *list) {
