        entries[i].number = (double)(rand() % 1000000);
    }

    return entries;
}

transaction* allocate_transactions(size_t count, float min_value, float max_value) {
    transaction* transactions = malloc(count * sizeof(transaction));
    if (!transactions) return NULL;

    for (size_t i = 0; i < count; ++i) {
        transactions[i].value = random_float_range(min_value, max_value);
    }

    return transactions;
}

