    NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->RX_UE_INFORMATION_TAG = rand();
    node->RNTI = rand();
    node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    node->timestamp = time(NULL);
    node->next = NULL;

    return node;
}

void add_crc_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    pthread_mutex_lock(&list->lock);

    if (list->size == MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T** cur = &list->head;
        while (*cur && ((*cur)->timestamp > (time(NULL) - CLEANUP_THRESHOLD_SECONDS))) {
            cur = &(*cur)->next;
        }
        if (*cur) {
            NFAPI_CRC_INDICATION_PDU_T* old_node = *cur;
            *cur = old_node->next;
            free(old_node);
            list->size--;
        }
    }

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    time_t now = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T** cur = &list->head;

