        *cur = old_node->next;
        free(old_node);
        list->size--;
    }

    pthread_mutex_unlock(&list->lock);
}

void calculate_statistics(const Entry* entries, size_t count) {
    double sum = 0.0;
    double mean, stddev = 0.0;

    for (size_t i = 0; i < count; ++i) {
        sum += entries[i].number;
    }
    mean = sum / count;

    for (size_t i = 0; i < count; ++i) {
        stddev += pow(entries[i].number - mean, 2);
    }
    stddev = sqrt(stddev / count);

    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", stddev);
}

void free_resources(Entry* entries, transaction* transactions, LinkedList* list) {
    if (entries) free(entries);
    if (transactions) free(transactions);

    NFAPI_CRC_INDICATION_PDU_T* cur = list->head;
    while (cur) {
        NFAPI_CRC_INDICATION_PDU_T* next = cur->next;
        free(cur);
        cur = next;
    }

    pthread_mutex_destroy(&list->lock);
}

