#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFACRCList;

void init_list(NFACRCList *list) {
    list->capacity = INITIAL_CAPACITY;
    list->size = 0;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(NFACRCList *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

size_t get_size(const NFACRCList *list) {
    return list->size;
}

int append_entries(NFACRCList *list, size_t N, size_t max_entries) {
    if (N > max_entries - list->size) {
        N = max_entries - list->size;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size + N > list->capacity) {
        while (list->size + N > list->capacity) {
            list->capacity *= GROWTH_FACTOR;
        }
        list->entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    for (size_t i = 0; i < N; ++i) {
        list->entries[list->size].RX_UE_INFORMATION_TAG = rand();
        list->entries[list->size].RNTI = rand();
        list->entries[list->size].CRC_INDICATION_REL8_TAG = rand();
        list->entries[list->size].CRCFLAG = rand() & 1; // Randomly set CRCFLAG
        ++list->size;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void dynamic_append(NFACRCList *list, size_t N) {
    append_entries(list, N, list->capacity);
}
