#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned long CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp; // Timestamp for periodic cleanup
} NFAPI_CRC_INDICATION_PDU;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t lock;
    time_t cleanup_threshold; // Time threshold for cleanup
    size_t max_size;          // Maximum allowed size of the list
} DoublyLinkedList;

DoublyLinkedList* create_list(size_t max_size, time_t cleanup_threshold) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;
    list->cleanup_threshold = cleanup_threshold;
    return list;
}

void destroy_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->max_size) {
        // Evict the least recently used node
        Node* lru = list->head;
        if (lru != NULL) {
            list->head = lru->next;
            if (list->head == NULL) {
                list->tail = NULL;
            } else {
                list->head->prev = NULL;
            }
            free(lru);
            list->size--;
        }
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_old_entries(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    time_t current_time = time(NULL);
    Node* current = list->head;

    while (current != NULL) {
        if ((current_time - current->timestamp) > list->cleanup_threshold) {
            Node* to_remove = current;
            current = current->next;

            if (to_remove == list->head) {
                list->head = to_remove->next;
                if (list->head == NULL) {
                    list->tail = NULL;
                } else {
                    list->head->prev = NULL;
                }
            } else {
                to_remove->prev->next = current;
                if (current != NULL) {
                    current->prev = to_remove->prev;
                }
            }

            free(to_remove);
            list->size--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void* cleanup_thread(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        sleep(5); // Cleanup interval
        remove_old_entries(list);
    }
    return NULL;
}

void start_cleanup(DoublyLinkedList* list) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, cleanup_thread, list);
    pthread_detach(thread_id);
}

int main() {
    size_t max_size = 1000;
    time_t cleanup_threshold = 60; // 1 minute
    DoublyLinkedList* list = create_list(max_size, cleanup_threshold);

    start_cleanup(list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU pdu = {12345, 67890, 111213, 1};
    insert_node(list, pdu);

    // Simulate workload
    for (int i = 0; i < 10000; ++i) {
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;
        insert_node(list, pdu);
    }

    sleep(120); // Let the program run for a while

    destroy_list(list);

    return 0;
}
