// Error handling macro
#define HANDLE_ERROR(msg) \
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

UEContextArray* initialize_ue_context_array(size_t num_contexts) {
    if (num_contexts > MAX_UE_CONTEXTS) {
        fprintf(stderr, "Exceeded maximum allowed UE contexts\n");
        return NULL;
    }

    UEContextArray *ueArray = malloc(sizeof(UEContextArray));
    if (!ueArray) HANDLE_ERROR("Failed to allocate UE context array");

    ueArray->contexts = calloc(num_contexts, sizeof(UEContextInfo));
    if (!ueArray->contexts) {
        free(ueArray);
        HANDLE_ERROR("Failed to allocate UE contexts");
    }

    ueArray->size = num_contexts;

    // Populate the array with sample data
    for (size_t i = 0; i < num_contexts; ++i) {
        ueArray->contexts[i].ueId = i + 1;
        for (int j = 0; j < NUM_FREQUENCY_BANDS; ++j) {
            ueArray->contexts[i].measurementResults[j] = (float)(rand() % 100) / 10.0f;
        }
        ueArray->contexts[i].isConnected = rand() % 2;
    }

    return ueArray;
}

void serialize_ue_context_array(const UEContextArray *ueArray, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) HANDLE_ERROR("Failed to open file for writing");

    size_t num_written = fwrite(ueArray, sizeof(UEContextArray), 1, file);
    if (num_written != 1) {
        fclose(file);
        fprintf(stderr, "Failed to write UE context array to file\n");
        return;
    }

    // Write the contexts data
    num_written = fwrite(ueArray->contexts, sizeof(UEContextInfo), ueArray->size, file);
    if (num_written != ueArray->size) {
        fclose(file);
        fprintf(stderr, "Failed to write UE context data to file\n");
        return;
    }

    fclose(file);
}

void deserialize_ue_context_array(const char *filename, UEContextArray *ueArray) {
    FILE *file = fopen(filename, "rb");
    if (!file) HANDLE_ERROR("Failed to open file for reading");

    size_t num_read = fread(ueArray, sizeof(UEContextArray), 1, file);
    if (num_read != 1) {
        fclose(file);
        fprintf(stderr, "Failed to read UE context array from file\n");
        return;
    }

    // Read the contexts data
    ueArray->contexts = realloc(ueArray->contexts, ueArray->size * sizeof(UEContextInfo));
    if (!ueArray->contexts) HANDLE_ERROR("Failed to allocate memory for UE context data");

    num_read = fread(ueArray->contexts, sizeof(UEContextInfo), ueArray->size, file);
    if (num_read != ueArray->size) {
        free(ueArray->contexts);
        fclose(file);
        fprintf(stderr, "Failed to read UE context data from file\n");
        return;
    }

    fclose(file);
}

void update_ue_context_from_external_source(UEContextArray *ueArray, const char *source_data) {
    // Simulated external source processing
    for (size_t i = 0; i < ueArray->size && i < strlen(source_data); ++i) {
        int newConnectedStatus = source_data[i] % 2;
        if (newConnectedStatus != ueArray->contexts[i].isConnected) {
            ueArray->contexts[i].isConnected = newConnectedStatus;
        }
    }
}

void free_ue_context_array(UEContextArray *ueArray) {
    if (ueArray) {
        free(ueArray->contexts);
        free(ueArray);
    }
}

// Example usage
int main() {
    size_t num_contexts = 1000; // Number of UE contexts to manage
    UEContextArray *ueArray = initialize_ue_context_array(num_contexts);

    if (ueArray) {
        serialize_ue_context_array(ueArray, "ue_data.bin");

        UEContextArray newUeArray;
        deserialize_ue_context_array("ue_data.bin", &newUeArray);

        update_ue_context_from_external_source(&newUeArray, "110010101111"); // Simulated external data

        free_ue_context_array(ueArray);
        free_ue_context_array(&newUeArray);
    }

    return 0;
}
