typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void free_list(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

int insert_entry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (!list) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failure

    new_node->data = entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_entry(DynamicList* list, size_t index) {
    if (!list || index >= list->count) return NULL;

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i)
        current = current->next;

    return current ? &current->data : NULL;
}

int validate_crc_flag(DynamicList* list, unsigned char reference_crc) {
    if (!list) return -1;

    size_t valid_count = 0;
    for (Node* current = list->head; current != NULL; current = current->next) {
