    static std::random_device rd;
    static std::mt19937 gen(rd());
    static std::bernoulli_distribution d(0.5);
    return d(gen);
}

void populateNfaapiCrcIndications(std::vector<NFAPI_CRC_INDICATION_PDU_T>* out_pdus, int N) {
    if (out_pdus == nullptr || N <= 0) {
        std::cerr << "Invalid input: N must be positive and output pointer must not be null." << std::endl;
        return; // Handle error gracefully
    }

    static std::mutex mtx; // Mutex for thread-safe logging

    try {
        out_pdus->resize(N);

        std::vector<std::thread> threads;
        const int num_threads = std::thread::hardware_concurrency();
        int chunk_size = (N + num_threads - 1) / num_threads;

        auto worker = [&](int start, int end) {
            for (int i = start; i < end; ++i) {
                NFAPI_CRC_INDICATION_PDU_T& pdu = (*out_pdus)[i];
                // Populate the structure with example values
                pdu.rx_ue_info.some_field = i;
                pdu.rnti.rnti_value = static_cast<uint16_t>(i);
                pdu.crc_indication.CRCFLAG = getRandomBoolean();

                // Log creation of each NFAPI_CRC_INDICATION_PDU_T
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    LOG_MESSAGE("Created NFAPI_CRC_INDICATION_PDU_T at index " + std::to_string(i));
                }
            }
        };

        for (int i = 0; i < num_threads; ++i) {
            int start = i * chunk_size;
            int end = std::min(start + chunk_size, N);
            if (start < end) {
                threads.emplace_back(worker, start, end);
            }
        }

        for (auto& t : threads) {
            t.join();
        }
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << std::endl;
    }
}

