#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SAMPLES 10000

typedef struct {
    int rx_channel_index;
    size_t buffer_size;
} NFAPI_RX_FRAME_INFO_T;

typedef struct {
    NFAPI_RX_FRAME_INFO_T frame_info;
    int *samples;
    size_t num_samples;
} NFAPI_RX_FRAME_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_RX_FRAME_PDU_T* initialize_nfa_rx_frames(size_t num_frames, int rx_channel_index, size_t buffer_size_per_frame) {
    pthread_mutex_lock(&mutex);

    NFAPI_RX_FRAME_PDU_T *frames = (NFAPI_RX_FRAME_PDU_T *)malloc(num_frames * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!frames) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < num_frames; ++i) {
        frames[i].frame_info.rx_channel_index = rx_channel_index;
        frames[i].frame_info.buffer_size = buffer_size_per_frame;
        frames[i].samples = (int *)malloc(buffer_size_per_frame * sizeof(int));
        if (!frames[i].samples) {
            for (size_t j = 0; j < i; ++j) {
                free(frames[j].samples);
            }
            free(frames);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        frames[i].num_samples = 0;
    }

    pthread_mutex_unlock(&mutex);
    return frames;
}

void distribute_samples(NFAPI_RX_FRAME_PDU_T *frames, size_t num_frames, int *incoming_samples, size_t total_samples) {
    pthread_mutex_lock(&mutex);

    size_t samples_per_frame = total_samples / num_frames;
    size_t remaining_samples = total_samples % num_frames;

    for (size_t i = 0; i < num_frames && total_samples > 0; ++i) {
        size_t current_sample_count = (total_samples <= samples_per_frame) ? total_samples : samples_per_frame;

        if (current_sample_count + remaining_samples > frames[i].frame_info.buffer_size) {
            current_sample_count = frames[i].frame_info.buffer_size - frames[i].num_samples;
        }

        memcpy(frames[i].samples + frames[i].num_samples, incoming_samples, current_sample_count * sizeof(int));
        frames[i].num_samples += current_sample_count;

        total_samples -= current_sample_count;
        if (remaining_samples > 0) {
            --remaining_samples;
            ++current_sample_count;
        }

        incoming_samples += current_sample_count;
    }

    pthread_mutex_unlock(&mutex);
}

void free_nfa_rx_frames(NFAPI_RX_FRAME_PDU_T *frames, size_t num_frames) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_frames; ++i) {
        free(frames[i].samples);
    }
    free(frames);

    pthread_mutex_unlock(&mutex);
}
```

### Key Points:
- **Thread Safety:** Mutex is used to ensure that the function can be safely called in a multi-threaded environment.
- **Dynamic Allocation:** Memory for each frame and its samples is allocated dynamically, with checks for allocation failures.
- **Sample Distribution:** Samples are distributed evenly across frames, considering buffer limits. Excess samples are handled gracefully by truncating or buffering until space becomes available.
- **Memory Management:** Proper deallocation of memory is ensured to prevent leaks.

This implementation should provide a robust starting point for handling NF API RX frames in a dynamic and efficient manner.']

