['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 100

typedef struct {
    int id;
    char name[50];
    unsigned long execution_frequency; // in milliseconds
    int priority;
    char metadata[256];
} Task;

typedef struct {
    Task tasks[MAX_TASKS];
    int count;
} TaskScheduler;

// Initialize the task scheduler with default values
void initialize_scheduler(TaskScheduler *scheduler) {
    scheduler->count = 0;
}

// Add a new task to the scheduler
int add_task(TaskScheduler *scheduler, const char *name, unsigned long frequency, int priority, const char *metadata) {
    if (scheduler->count >= MAX_TASKS)
        return -1;

    Task *task = &scheduler->tasks[scheduler->count++];
    task->id = scheduler->count;
    strncpy(task->name, name, sizeof(task->name));
    task->execution_frequency = frequency;
    task->priority = priority;
    strncpy(task->metadata, metadata, sizeof(task->metadata));

    // Sort tasks by priority (higher priority first)
    for (int i = 0; i < scheduler->count - 1; ++i) {
        for (int j = i + 1; j < scheduler->count; ++j) {
            if (scheduler->tasks[i].priority < scheduler->tasks[j].priority) {
                Task temp = scheduler->tasks[i];
                scheduler->tasks[i] = scheduler->tasks[j];
                scheduler->tasks[j] = temp;
            }
        }
    }

    return 0;
}

// Remove a task from the scheduler by ID
int remove_task(TaskScheduler *scheduler, int id) {
    for (int i = 0; i < scheduler->count; ++i) {
        if (scheduler->tasks[i].id == id) {
            for (int j = i; j < scheduler->count - 1; ++j) {
                scheduler->tasks[j] = scheduler->tasks[j + 1];
            }
            scheduler->count--;
            return 0;
        }
    }
