    return -1;
}

// Update task priority
int update_task_priority(TaskScheduler *scheduler, int id, int new_priority) {
    for (int i = 0; i < scheduler->count; ++i) {
        if (scheduler->tasks[i].id == id) {
            scheduler->tasks[i].priority = new_priority;

            // Re-sort tasks by priority
            for (int j = 0; j < scheduler->count - 1; ++j) {
                for (int k = j + 1; k < scheduler->count; ++k) {
                    if (scheduler->tasks[j].priority < scheduler->tasks[k].priority) {
                        Task temp = scheduler->tasks[j];
                        scheduler->tasks[j] = scheduler->tasks[k];
                        scheduler->tasks[k] = temp;
                    }
                }
            }

            return 0;
        }
    }
    return -1;
}

// Log performance metrics
void log_performance_metrics(TaskScheduler *scheduler) {
    printf("Task Scheduler Performance Metrics:\n");
    for (int i = 0; i < scheduler->count; ++i) {
