#define MAX_STRUCTS 10000
#define SAMPLE_LIMIT 100000

typedef struct {
    int sample_count;
    char *samples;
} NFAPI_RX_FRAME_INFO_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG_CRCFLAG;
