char* get_dns_ip(char *hostname, int *ip_length) {
    struct addrinfo hints, *res;
    char ipstr[INET_ADDRSTRLEN];
    void *addr;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        log_error("DNS resolution failed");
        return NULL;
    }

    addr = &((struct sockaddr_in*)res->ai_addr)->sin_addr;
    inet_ntop(res->ai_family, addr, ipstr, sizeof(ipstr));

    *ip_length = strlen(ipstr);
    char* ip_array = malloc(*ip_length + 1);
    if (!ip_array) {
        log_error("Memory allocation for IP address failed");
        freeaddrinfo(res);
        return NULL;
    }

    strcpy(ip_array, ipstr);
    freeaddrinfo(res);

    return ip_array;
}

int create_nfa_rx_frame_pdu_array(NFAPI_RX_FRAME_PDU_T **array, size_t num_frames) {
    if (num_frames > MAX_STRUCTS) {
        log_error("Requested number of frames exceeds maximum allowed");
        return -1;
    }

    srand(time(NULL));

    *array = malloc(num_frames * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!*array) {
        log_error("Memory allocation for frame array failed");
        return -2;
    }

    int total_samples = 0;
    int last_rnti = -1;

    for (size_t i = 0; i < num_frames; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand();
        do {
            (*array)[i].RNTI = rand() % 10000 + 1;
        } while ((*array)[i].RNTI == last_rnti);
        last_rnti = (*array)[i].RNTI;

        int max_samples_per_frame = SAMPLE_LIMIT / num_frames;
        if (total_samples + max_samples_per_frame > SAMPLE_LIMIT) {
            max_samples_per_frame = SAMPLE_LIMIT - total_samples;
        }

        int sample_count = rand() % (max_samples_per_frame + 1);
        total_samples += sample_count;

        (*array)[i].frame_info.sample_count = sample_count;
        if (sample_count > 0) {
            (*array)[i].frame_info.samples = malloc(sample_count * sizeof(char));
            if (!(*array)[i].frame_info.samples) {
                log_error("Memory allocation for samples failed");
                // Cleanup
                for (size_t j = 0; j < i; ++j) {
                    free((*array)[j].frame_info.samples);
                }
                free(*array);
                *array = NULL;
                return -3;
            }

            for (int k = 0; k < sample_count; ++k) {
                (*array)[i].frame_info.samples[k] = rand() % 256;
            }
        } else {
            (*array)[i].frame_info.samples = NULL;
        }

        (*array)[i].CRC_INDICATION_REL8_TAG_CRCFLAG = generate_random_crc_flag();
    }

    return 0;
}

void free_nfa_rx_frame_pdu_array(NFAPI_RX_FRAME_PDU_T *array, size_t num_frames) {
    if (array) {
        for (size_t i = 0; i < num_frames; ++i) {
            free(array[i].frame_info.samples);
        }
        free(array);
    }
}
