['Below is a C implementation of the described function. This code initializes a dynamic array of `NFAPI_RX_FRAME_PDU_T` structures with considerations for thread safety, resource management, and dynamic adjustments:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    float *samples;
    size_t sample_count;
    size_t capacity;
} NFAPI_RX_FRAME_PDU_T;

typedef struct {
    NFAPI_RX_FRAME_PDU_T **frames;
    size_t num_channels;
    pthread_mutex_t lock;
    size_t total_capacity;
    size_t used_capacity;
} DynamicFrameArray;

DynamicFrameArray* initialize_dynamic_frame_array(size_t num_channels) {
    DynamicFrameArray *dfa = (DynamicFrameArray *)malloc(sizeof(DynamicFrameArray));
    if (!dfa) return NULL;

    dfa->num_channels = num_channels;
    dfa->frames = (NFAPI_RX_FRAME_PDU_T **)calloc(num_channels, sizeof(NFAPI_RX_FRAME_PDU_T *));
    if (!dfa->frames) {
        free(dfa);
        return NULL;
    }

    pthread_mutex_init(&dfa->lock, NULL);
    dfa->total_capacity = 0;
    dfa->used_capacity = 0;

    for (size_t i = 0; i < num_channels; ++i) {
        NFAPI_RX_FRAME_PDU_T *frame = (NFAPI_RX_FRAME_PDU_T *)malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
        if (!frame) {
            // Cleanup in case of failure
            for (size_t j = 0; j < i; ++j) free(dfa->frames[j]);
            free(dfa->frames);
            pthread_mutex_destroy(&dfa->lock);
            free(dfa);
            return NULL;
        }

        frame->samples = (float *)malloc(INITIAL_BUFFER_SIZE * sizeof(float));
        if (!frame->samples) {
            free(frame);
            // Cleanup in case of failure
            for (size_t j = 0; j < i; ++j) free(dfa->frames[j]);
            free(dfa->frames);
            pthread_mutex_destroy(&dfa->lock);
            free(dfa);
            return NULL;
        }

        frame->sample_count = 0;
        frame->capacity = INITIAL_BUFFER_SIZE;
        dfa->frames[i] = frame;
        dfa->total_capacity += frame->capacity;
    }

    return dfa;
}

void resize_frame(NFAPI_RX_FRAME_PDU_T *frame, size_t new_capacity) {
    float *new_samples = (float *)realloc(frame->samples, new_capacity * sizeof(float));
    if (!new_samples) {
        fprintf(stderr, "Failed to resize frame buffer\n");
        return; // Handle error appropriately
    }
    frame->samples = new_samples;
    frame->capacity = new_capacity;
}

void distribute_samples(DynamicFrameArray *dfa, const float *incoming_samples, size_t sample_count) {
    pthread_mutex_lock(&dfa->lock);

    for (size_t i = 0; i < dfa->num_channels; ++i) {
        NFAPI_RX_FRAME_PDU_T *frame = dfa->frames[i];

        while (sample_count > 0 && frame->sample_count < frame->capacity) {
            size_t space_left = frame->capacity - frame->sample_count;
            size_t samples_to_add = sample_count < space_left ? sample_count : space_left;

            for (size_t j = 0; j < samples_to_add; ++j) {
                frame->samples[frame->sample_count++] = incoming_samples[j];
            }

            sample_count -= samples_to_add;
        }
    }

    pthread_mutex_unlock(&dfa->lock);
}

void free_dynamic_frame_array(DynamicFrameArray *dfa) {
    if (!dfa) return;

    for (size_t i = 0; i < dfa->num_channels; ++i) {
        NFAPI_RX_FRAME_PDU_T *frame = dfa->frames[i];
        if (frame) {
            free(frame->samples);
            free(frame);
        }
    }

    free(dfa->frames);
    pthread_mutex_destroy(&dfa->lock);
    free(dfa);
}

// Logging interface
void log_memory_usage(DynamicFrameArray *dfa) {
    printf("Total Capacity: %zu, Used Capacity: %zu\n", dfa->total_capacity, dfa->used_capacity);
}

int main() {
    size_t num_channels = 4;
    DynamicFrameArray *dfa = initialize_dynamic_frame_array(num_channels);

    if (!dfa) {
        fprintf(stderr, "Failed to initialize dynamic frame array\n");
        return EXIT_FAILURE;
    }

    float incoming_samples[] = {1.0, 2.0, 3.0, 4.0};
    distribute_samples(dfa, incoming_samples, sizeof(incoming_samples) / sizeof(float));

    log_memory_usage(dfa);

    free_dynamic_frame_array(dfa);
    return EXIT_SUCCESS;
}
```

### Key Features:
- **Dynamic Allocation**: Each channel has its own buffer initialized with a default size.
- **Thread Safety**: Uses `pthread_mutex_t` to ensure safe access in multi-threaded environments.
- **Resizing Mechanism**: Provides a function to resize frames when needed.
- **Sample Distribution**: Distributes incoming samples evenly across available frame buffers.
- **Error Handling**: Handles allocation failures gracefully by cleaning up resources.
- **Logging Interface**: Simple logging for memory usage tracking.

This implementation is modular and can be extended with additional features such as support for different sample rates, dynamic resizing based on runtime conditions, and integration with external systems.']

