void ensure_config_root_directory(ThreadSafeConfigManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    const char* root = get_environment_variable(config_root_env);
    if (!root || strcmp(root, "") == 0) {
        const char* default_root = get_default_config_root();
        set_environment_variable(config_root_env, default_root);
        root = get_environment_variable(config_root_env);
