} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Manager;

#define INITIAL_CAPACITY 16
#define MAX_RNTI UINT16_MAX

CRC_Manager* crc_manager_create(size_t initial_capacity) {
    CRC_Manager* manager = (CRC_MANAGER*)malloc(sizeof(CRC_MANAGER));
    if (!manager) return NULL;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int crc_manager_populate(CRC_Manager* manager, size_t N) {
    if (!manager || N == 0) return -1;

    pthread_mutex_lock(&manager->lock);

    // Resize array if needed
    if (N > manager->capacity) {
        size_t new_capacity = N * 2; // Allow for future growth
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    // Use a hash table to track unique RNTIs
    int rnti_table[MAX_RNTI + 1] = {0};

    for (size_t i = 0; i < N; ++i) {
        uint16_t rnti;
        do {
            rnti = rand() % (MAX_RNTI + 1);
        } while (rnti_table[rnti]);

        RX_UE_INFORMATION_TAG* tag = &manager->array[i].rx_ue_information_tag;
        CRC_INDICATION_REL8_TAG* crc_tag = &manager->array[i].crc_indication_rel8_tag;

        tag->RNTI = rnti;
        crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        rnti_table[rnti] = 1;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void crc_manager_free(CRC_Manager* manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        free(manager->array);
        pthread_mutex_unlock(&manager->lock);

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

