#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <stdbool.h>

#define VALID_RNTI_MIN 1
#define VALID_RNTI_MAX 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int rnti;
    struct Node* next;
} Node;

typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T** array;
    pthread_mutex_t lock;
    Node** hash_table;
} CRCArrayManager;

static const unsigned int HASH_TABLE_SIZE = 1003; // Prime number for better distribution

// Hash function
unsigned int hash_rnti(int rnti) {
    return (rnti * 2654435761u) % HASH_TABLE_SIZE;
}

void initialize_manager(CRCArrayManager* manager, size_t initial_capacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    memset(manager->array, 0, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Initialize hash table
    manager->hash_table = (Node**)calloc(HASH_TABLE_SIZE, sizeof(Node*));
}

void destroy_manager(CRCArrayManager* manager) {
    pthread_mutex_destroy(&manager->lock);

    for(size_t i = 0; i < manager->capacity; ++i) {
        if(manager->array[i]) {
            free(manager->array[i]);
        }
    }
    free(manager->array);

    // Free hash table
    for (unsigned int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = manager->hash_table[i];
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(manager->hash_table);
}

bool is_rnti_valid(int rnti) {
    return rnti >= VALID_RNTI_MIN && rnti <= VALID_RNTI_MAX;
}

void add_pdu(CRCArrayManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!is_rnti_valid(pdu->RNTI)) {
        printf("Invalid RNTI: %d\n", pdu->RNTI);
        return;
    }

    pthread_mutex_lock(&manager->lock);

    unsigned int hash_index = hash_rnti(pdu->RNTI);
    Node* current = manager->hash_table[hash_index];
    while (current) {
        if (current->rnti == pdu->RNTI) {
            // RNTI already exists
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        current = current->next;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        memcpy(new_array, manager->array, manager->count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        memset(new_array + manager->count, 0, (new_capacity - manager->count) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        free(manager->array);
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    Node* node = (Node*)malloc(sizeof(Node));
    node->rnti = pdu->RNTI;
    node->next = manager->hash_table[hash_index];
    manager->hash_table[hash_index] = node;

    manager->array[manager->count++] = pdu;

    pthread_mutex_unlock(&manager->lock);
}

void* generate_random_pdu(void* arg) {
    CRCArrayManager* manager = (CRCArrayManager*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example generation
    pdu->RNTI = rand() % (VALID_RNTI_MAX + 1);
    pdu->CRC_INDICATION_REL8_TAG = rand() % 100;
    pdu->CRCFLAG = rand() % 2 == 0;

    add_pdu(manager, pdu);

    free(pdu); // Free the temporary allocation
    return NULL;
}

int main() {
    CRCArrayManager manager;
    initialize_manager(&manager, 10);

    pthread_t threads[20];
    for (int i = 0; i < 20; ++i) {
        pthread_create(&threads[i], NULL, generate_random_pdu, &manager);
    }

    for (int i = 0; i < 20; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_manager(&manager);

    return 0;
}
```

### Key Features Implemented:

- **Dynamic Array and Hash Table**: Manages a dynamically allocated array of `NFAPI_CRC_INDICATION_PDU_T` structures, with a hash table to ensure unique `RNTI` entries.

- **Thread Safety**: Uses mutexes for synchronizing access to shared resources.

- **Memory Management**: Efficiently reallocates memory when the capacity is exceeded and minimizes fragmentation by doubling the capacity.

- **Validation**: Ensures `RNTI` values are within a valid range, logging invalid ones.

- **Concurrency**: Handles multiple threads generating random PDU entries concurrently.

This implementation provides a foundation for integrating with a signal processing framework, considering memory usage versus performance trade-offs.']

