int create_directory_with_backoff(const char* base_path, const char* dir_name_template) {
    int attempt = 0;
    int delay = 1;

    while (attempt < MAX_RETRIES) {
        pthread_mutex_lock(&dir_creation_lock);

        char dir_path[256];
        snprintf(dir_path, sizeof(dir_path), "%s/%s_%ld", base_path, dir_name_template, time(NULL));

