#include <libxml/parser.h>
#include <libxml/xpath.h>

#define MAX_ELEMENTS 10000
#define INITIAL_POOL_SIZE 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    size_t unitSize;
    size_t count;
    void **pool;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t unitSize, size_t initialCount) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    mp->unitSize = unitSize;
    mp->count = initialCount;
    mp->pool = calloc(mp->count, sizeof(void *));
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void *memory_pool_alloc(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count == 0) {
        size_t newCount = mp->count ? mp->count * 2 : INITIAL_POOL_SIZE;
        void **newPool = realloc(mp->pool, newCount * sizeof(void *));
        if (!newPool) {
            pthread_mutex_unlock(&mp->lock);
            return NULL;
        }
        memset(newPool + mp->count, 0, (newCount - mp->count) * sizeof(void *));
        mp->pool = newPool;
        mp->count = newCount;
    }
    void *allocatedMemory = malloc(mp->unitSize);
    if (allocatedMemory) {
        mp->pool[--mp->count] = allocatedMemory;
    }
    pthread_mutex_unlock(&mp->lock);
    return allocatedMemory;
}

void memory_pool_free(MemoryPool *mp, void *ptr) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count < mp->count) {
        mp->pool[mp->count++] = ptr;
    }
    pthread_mutex_unlock(&mp->lock);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_nfa_pi_list(size_t n, MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (size_t i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand();
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return list;
}

void get_root_directory(char *dir, size_t len) {
    static char envDir[256];
    const int attempts = 3;
    for (int i = 0; i < attempts; ++i) {
        if (getenv("ROOT_DIR") && strncpy(envDir, getenv("ROOT_DIR"), sizeof(envDir)) == envDir) {
            snprintf(dir, len, "%s", envDir);
            return;
        }

        struct utsname unameData;
        uname(&unameData);
        time_t currentTime = time(NULL);
        char defaultDir[256];
        strftime(defaultDir, sizeof(defaultDir), "/default_%Y%m%d_%H%M%S", localtime(&currentTime));
        snprintf(dir, len, "%s/%s_%s", unameData.nodename, defaultDir, "NFAPI");

        sleep((i + 1) << (i % 2)); // Exponential backoff
    }
}

void create_user_directory(const char *rootDir, unsigned int rnti) {
    time_t timestamp = time(NULL);
    char dirPath[256];
    snprintf(dirPath, sizeof(dirPath), "%s/%u_%ld", rootDir, rnti, (long)timestamp);

    if (mkdir(dirPath, 0755) != 0 && errno != EEXIST) {
        perror("Error creating directory");
    }
}

void parse_user_settings(const char *configFile, unsigned int rnti) {
    xmlDocPtr doc;
    xmlXPathContextPtr xpathCtx;
    doc = xmlParseFile(configFile);

    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file\n");
        return;
    }

    xpathCtx = xmlXPathNewContext(doc);
    if (xpathCtx == NULL) {
        fprintf(stderr, "Error creating XPath context\n");
        xmlFreeDoc(doc);
        return;
    }

    xmlChar *expr = xmlXPathCompileExpression((const xmlChar *) "/settings/user[@rnti='%u']", rnti);
    if (expr == NULL) {
        fprintf(stderr, "Failed to compile expression\n");
        xmlXPathFreeContext(xpathCtx);
        xmlFreeDoc(doc);
        return;
    }

    xmlXPathObjectPtr result = xmlXPathEvalExpression(expr, xpathCtx);

    if (result && result->nodesetval && result->nodesetval->nodeNr == 1) {
        // Process the first matching element
        printf("Found settings for RNTI %u\n", rnti);
    }

    xmlXPathFreeObject(result);
    xmlXPathFreeExpression(&expr);
    xmlXPathFreeContext(xpathCtx);
    xmlFreeDoc(doc);
}

int main() {
    MemoryPool *mp = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), INITIAL_POOL_SIZE);

    NFAPI_CRC_INDICATION_PDU_T *nfaPiList = allocate_nfa_pi_list(MAX_ELEMENTS, mp);

    if (!nfaPiList) {
        fprintf(stderr, "Failed to allocate NFAPi list\n");
        return 1;
    }

    char rootDir[256];
    get_root_directory(rootDir, sizeof(rootDir));

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        create_user_directory(rootDir, nfaPiList[i].RNTI);
        parse_user_settings("/path/to/config.xml", nfaPiList[i].RNTI);
    }

    free(nfaPiList);
    memory_pool_free(mp, NULL); // Cleanup any remaining allocations
    pthread_mutex_destroy(&mp->lock);
    free(mp);

    return 0;
}
```

### Key Features:
- **Memory Pooling**: The `MemoryPool` structure manages a pool of preallocated blocks to minimize frequent dynamic allocation and deallocation overhead.

- **Thread Safety**: Uses mutexes within the memory pool operations to ensure thread safety.

- **Configuration Management**: Attempts to retrieve an environment variable for configuration, with exponential backoff retries if unavailable, defaulting to a directory based on hostname and timestamp.

- **User Directory Creation**: Creates unique subdirectories per user RNTI using timestamps.

- **XML Parsing**: Uses libxml2 for parsing XML files with XPath expressions to locate relevant settings, incorporating error handling.

- **Logging and Error Handling**: Logs errors to standard error output, which can be extended or redirected as needed. 

