#define MAX_PROTOCOLS 3

typedef enum {
    PROTOCOL_TCP,
    PROTOCOL_UDP,
    PROTOCOL_ICMP
} ProtocolType;

typedef struct {
    int activeProtocols[MAX_PROTOCOLS];
    size_t count;
} ProtocolList;

typedef struct NetworkConfig {
    char ipAddress[16]; // IPv4 address
    char subnetMask[16];
    char gateway[16];
    ProtocolList protocols;
    struct NetworkConfig* next;
} NetworkConfig;

typedef struct {
    NetworkConfig* head;
    pthread_mutex_t lock;
} NetworkConfigManager;

NetworkConfigManager* createNetworkConfigManager() {
    NetworkConfigManager* manager = (NetworkConfigManager*)malloc(sizeof(NetworkConfigManager));
    if (!manager) return NULL;
    manager->head = NULL;
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager);
        return NULL;
    }
    return manager;
}

int findIndexByIP(const NetworkConfigManager* manager, const char* ipAddress) {
    pthread_mutex_lock(&manager->lock);
    NetworkConfig* current = manager->head;
    while (current) {
        if (strcmp(current->ipAddress, ipAddress) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return current - manager->head; // Return index by pointer arithmetic
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

int addNetworkConfig(NetworkConfigManager* manager, const char* ipAddress, const char* subnetMask, const char* gateway, ProtocolType* protocols, size_t protocolCount) {
    if (findIndexByIP(manager, ipAddress) != -1) {
        return -1; // Duplicate IP
    }

    NetworkConfig* newConfig = (NetworkConfig*)malloc(sizeof(NetworkConfig));
    if (!newConfig) return -2;

    strncpy(newConfig->ipAddress, ipAddress, sizeof(newConfig->ipAddress));
    strncpy(newConfig->subnetMask, subnetMask, sizeof(newConfig->subnetMask));
    strncpy(newConfig->gateway, gateway, sizeof(newConfig->gateway));

    size_t count = 0;
    for (size_t i = 0; i < protocolCount && count < MAX_PROTOCOLS; ++i) {
        newConfig->protocols.activeProtocols[count++] = protocols[i];
    }
    newConfig->protocols.count = count;

    pthread_mutex_lock(&manager->lock);
    newConfig->next = manager->head;
    manager->head = newConfig;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int removeNetworkConfig(NetworkConfigManager* manager, const char* ipAddress) {
    int index = findIndexByIP(manager, ipAddress);
    if (index == -1) return -1;

    pthread_mutex_lock(&manager->lock);
    NetworkConfig** iter = &manager->head;
    while (*iter && *iter - manager->head != index) {
        iter = &(*iter)->next;
    }

    if (*iter) {
        NetworkConfig* toDelete = *iter;
        *iter = (*iter)->next;
        free(toDelete);
    }
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

int updateNetworkConfig(NetworkConfigManager* manager, const char* ipAddress, const char* subnetMask, const char* gateway, ProtocolType* protocols, size_t protocolCount) {
    int index = findIndexByIP(manager, ipAddress);
    if (index == -1) return -1;

    pthread_mutex_lock(&manager->lock);
    NetworkConfig* configToUpdate = manager->head + index;
    strncpy(configToUpdate->subnetMask, subnetMask, sizeof(configToUpdate->subnetMask));
    strncpy(configToUpdate->gateway, gateway, sizeof(configToUpdate->gateway));

    size_t count = 0;
    for (size_t i = 0; i < protocolCount && count < MAX_PROTOCOLS; ++i) {
        configToUpdate->protocols.activeProtocols[count++] = protocols[i];
    }
    configToUpdate->protocols.count = count;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void freeNetworkConfigManager(NetworkConfigManager* manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);
    NetworkConfig* current = manager->head;
    while (current) {
        NetworkConfig* toDelete = current;
        current = current->next;
        free(toDelete);
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Usage
int main() {
    NetworkConfigManager* manager = createNetworkConfigManager();
    if (!manager) {
        fprintf(stderr, "Failed to initialize network config manager.\n");
        return 1;
    }

    ProtocolType protocols[] = {PROTOCOL_TCP, PROTOCOL_UDP};
    addNetworkConfig(manager, "192.168.1.2", "255.255.255.0", "192.168.1.1", protocols, 2);

    updateNetworkConfig(manager, "192.168.1.2", "255.255.254.0", "192.168.1.1", protocols, 2);
    removeNetworkConfig(manager, "192.168.1.2");

    freeNetworkConfigManager(manager);
    return 0;
}
```

This code defines a `NetworkConfigManager` to manage dynamic network configurations with thread safety and memory optimization in mind. It uses mutex locks to ensure safe concurrent access across multiple threads or processes. The implementation includes functions for adding, removing, and updating network configurations while checking for duplicates based on IP addresses. Memory management is handled carefully to prevent leaks.']

