#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[10];
    int CRCFLAG; // Randomly set between 0 and 1
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_POOL_SIZE 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used;
    pthread_mutex_t lock;
} CRCIndicationPool;

// Function prototypes
CRCIndicationPool* initialize_pool(size_t initial_size);
int acquire_pdu(CRCIndicationPool *p, NFAPI_CRC_INDICATION_PDU_T **out_pdu);
void release_pdu(CRCIndicationPool *p, NFAPI_CRC_INDICATION_PDU_T *pdu);
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu);
int resize_pool(CRCIndicationPool *p);

CRCIndicationPool* initialize_pool(size_t initial_size) {
    CRCIndicationPool *p = malloc(sizeof(CRCIndicationPool));
    if (!p) return NULL;

    p->pool = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!p->pool) {
        free(p);
        return NULL;
    }

    p->pool_size = initial_size;
    p->used = 0;
    pthread_mutex_init(&p->lock, NULL);

    return p;
}

int acquire_pdu(CRCIndicationPool *p, NFAPI_CRC_INDICATION_PDU_T **out_pdu) {
    if (!p || !out_pdu) return -1;

    pthread_mutex_lock(&p->lock);

    if (p->used < p->pool_size) {
        *out_pdu = &p->pool[p->used++];
        set_random_crcflag(*out_pdu);
        pthread_mutex_unlock(&p->lock);
        return 0;
    } else if (resize_pool(p) == 0) {
        *out_pdu = &p->pool[p->used++];
        set_random_crcflag(*out_pdu);
        pthread_mutex_unlock(&p->lock);
        return 0;
    }

    pthread_mutex_unlock(&p->lock);
    return -1; // Memory allocation failed
}

void release_pdu(CRCIndicationPool *p, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!p || !pdu) return;

    pthread_mutex_lock(&p->lock);

    size_t index = pdu - p->pool;
    if (index < p->used) {
        memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memmove(&p->pool[index], &p->pool[index + 1], (p->used - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        p->used--;
    }

    pthread_mutex_unlock(&p->lock);
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;

    pdu->CRCFLAG = rand() % 2; // Randomly sets CRCFLAG to either 0 or 1
}

int resize_pool(CRCIndicationPool *p) {
    if (!p) return -1;

    size_t new_size = p->pool_size * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(p->pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) return -1;

    p->pool = new_pool;
    p->pool_size = new_size;

    return 0; // Success
}

void destroy_pool(CRCIndicationPool *p) {
    if (!p) return;

    pthread_mutex_destroy(&p->lock);
    free(p->pool);
    free(p);
}
```

### Notes:
- The `initialize_pool`, `acquire_pdu`, and `release_pdu` functions manage a pool of `NFAPI_CRC_INDICATION_PDU_T` structures.
- A mutex is used to ensure thread safety for concurrent operations on the pool.
- Memory allocation failures are gracefully handled by checking return values from memory management functions.
- The `resize_pool` function doubles the size of the pool when necessary, ensuring efficient reallocation during high traffic periods.']

