#include <pthread.h>

#define INITIAL_ARRAY_SIZE 10

typedef struct {
    uint16_t PDCP_SN;
    uint8_t PDCP_SNI;
    uint8_t *userData; // Dynamically allocated slice of bytes for user data.
    size_t userDataSize; // Size of the dynamically allocated user data.
} LTE_PDCP_PDU_T;

// Structure to hold dynamic array and metadata
typedef struct {
    LTE_PDCP_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock; // Mutex for thread-safe operations
} PDCP_PDUs;

// Function prototypes
void initPDCTArray(PDCP_PDUs *pdcp);
int addPDCPPDUToArray(PDCP_PDUs *pdcp, LTE_PDCP_PDU_T pdu);
void freePDCTArray(PDCP_PDUs *pdcp);

// Initialize the dynamic array of PDCP PDUs
void initPDCTArray(PDCP_PDUs *pdcp) {
    pthread_mutex_init(&pdcp->lock, NULL);
    pdcp->array = (LTE_PDCP_PDU_T *)malloc(INITIAL_ARRAY_SIZE * sizeof(LTE_PDCP_PDU_T));
    if (!pdcp->array) {
        // Log error: Memory allocation failed
        perror("Failed to allocate memory for PDCP PDUs");
        exit(EXIT_FAILURE);
    }
    pdcp->used = 0;
    pdcp->capacity = INITIAL_ARRAY_SIZE;
}

// Add a new PDU to the dynamic array, handling reallocations as needed
int addPDCPPDUToArray(PDCP_PDUs *pdcp, LTE_PDCP_PDU_T pdu) {
    pthread_mutex_lock(&pdcp->lock);

    if (pdcp->used == pdcp->capacity) {
        size_t new_capacity = pdcp->capacity * 2;
        LTE_PDCP_PDU_T *new_array = (LTE_PDCP_PDU_T *)realloc(pdcp->array, new_capacity * sizeof(LTE_PDCP_PDU_T));
        if (!new_array) {
            // Log error: Memory reallocation failed
            perror("Failed to reallocate memory for PDCP PDUs");
            pthread_mutex_unlock(&pdcp->lock);
            return -1;
        }
        pdcp->array = new_array;
        pdcp->capacity = new_capacity;
    }

    pdcp->array[pdcp->used] = pdu; // Copy the structure
    pdcp->used++;

    pthread_mutex_unlock(&pdcp->lock);

    // Log: Added PDU with SN = %u, SNI = %u\n", pdu.PDCP_SN, pdu.PDCP_SNI);
    return 0;
}

// Free the memory associated with the dynamic array
void freePDCTArray(PDCP_PDUs *pdcp) {
    pthread_mutex_lock(&pdcp->lock);

    for (size_t i = 0; i < pdcp->used; ++i) {
        if (pdcp->array[i].userData) {
            free(pdcp->array[i].userData);
        }
    }

    free(pdcp->array);
    pdcp->used = 0;
    pdcp->capacity = 0;

    pthread_mutex_unlock(&pdcp->lock);
    pthread_mutex_destroy(&pdcp->lock);

    // Log: Memory freed for PDCP PDUs
}

int main() {
    PDCP_PDUs pdcpArray;
    initPDCTArray(&pdcpArray);

    LTE_PDCP_PDU_T pdu1 = { .PDCP_SN = 1, .PDCP_SNI = 0, .userDataSize = 20 };
    pdu1.userData = malloc(pdu1.userDataSize);

    if (addPDCPPDUToArray(&pdcpArray, pdu1) != 0) {
        // Handle error
    }

    freePDCTArray(&pdcpArray);

    return 0;
}
```

### Comments on Design Choices:
- **Dynamic Array**: The array doubles its capacity when full. This choice balances the frequency of reallocations with memory overhead.
- **Mutex for Concurrency**: A mutex is used to ensure thread-safe operations, allowing concurrent access without data corruption.
- **Memory Management**: Each PDCP_PDU_T's `userData` field is dynamically allocated and freed individually, minimizing fragmentation and enabling efficient use of memory resources.
- **Error Handling**: The function checks for allocation failures and logs errors appropriately. This ensures robust handling of resource issues under high load conditions.
- **Scalability and Performance**: By using a dynamic array with doubling strategy, the function minimizes performance impacts due to frequent reallocations while maintaining scalability for growing datasets.

These trade-offs prioritize efficient memory management, thread safety, and integration ease within a potentially garbage-collected environment.']

