#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <string.h>

// Define the structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    _Atomic int CRCFLAG; // Use atomic for thread-safe updates without locks
} NFAPI_CRC_INDICATION_PDU_T;

// Node for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic list structure
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for protecting critical sections
    size_t count;
} CRCList;

// Function prototypes
CRCList* create_list();
void destroy_list(CRCList* list);
int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T* find_pdu(CRCList* list, int RNTI);
void update_crcflag(CRCList* list, int RNTI, int crcFlag);

// Create a new list
CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Destroy the list and free memory
void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the list
int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1;
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Find a PDU by RNTI
NFAPI_CRC_INDICATION_PDU_T* find_pdu(CRCList* list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &current->data;
            pthread_mutex_unlock(&list->lock);
            return pdu;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

// Update CRCFLAG for a specific RNTI
void update_crcflag(CRCList* list, int RNTI, int crcFlag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = find_pdu(list, RNTI);
    if (pdu) {
        atomic_store(&pdu->CRCFLAG, crcFlag);
    }
}

// Example usage
int main() {
    CRCList* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1001, 2002, 0};
    add_pdu(list, pdu);

    update_crcflag(list, 1001, 1);

    destroy_list(list);
    return 0;
}
```

