#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList list = {NULL, PTHREAD_MUTEX_INITIALIZER};
Node* memory_pool[INITIAL_POOL_SIZE];
int pool_index = 0;

void init_memory_pool() {
    for (int i = 0; i < INITIAL_POOL_SIZE; ++i) {
        memory_pool[i] = malloc(sizeof(Node));
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to allocate memory.\n");
            exit(EXIT_FAILURE);
        }
    }
}

Node* get_node_from_pool() {
    if (pool_index >= INITIAL_POOL_SIZE) {
        fprintf(stderr, "Memory pool exhausted.\n");
        return NULL;
    }
    return memory_pool[pool_index++];
}

void release_node_to_pool(Node* node) {
    if (node && pool_index > 0) {
        --pool_index;
        *node = *(Node*)memory_pool[pool_index];
    }
}

int find_entry(uint32_t tag, uint16_t rnti) {
    pthread_mutex_lock(&list.lock);

    for (Node* current = list.head; current != NULL; current = current->next) {
        if (current->data.RX_UE_INFORMATION_TAG == tag && current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list.lock);
            return 1;
        }
    }

    pthread_mutex_unlock(&list.lock);
    return 0;
}

void set_crc_flag(uint32_t tag, uint16_t rnti, int crcflag) {
    pthread_mutex_lock(&list.lock);

    for (Node* current = list.head; current != NULL; current = current->next) {
        if (current->data.RX_UE_INFORMATION_TAG == tag && current->data.RNTI == rnti) {
            current->data.CRCFLAG = crcflag;
            break;
        }
    }

    pthread_mutex_unlock(&list.lock);
}

void add_or_update_entry(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list.lock);

    if (find_entry(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI)) {
        set_crc_flag(pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRCFLAG);
    } else {
        Node* new_node = get_node_from_pool();
        if (!new_node) {
            pthread_mutex_unlock(&list.lock);
            fprintf(stderr, "Failed to add entry due to memory constraints.\n");
            return;
        }
        new_node->data = pdu;
        new_node->next = list.head;
        list.head = new_node;
    }

    pthread_mutex_unlock(&list.lock);
}

void log_operation(const char* message) {
    printf("[LOG]: %s\n", message);  // Replace with a more robust logging mechanism if needed
}

int main() {
    init_memory_pool();

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {100, 200, 3, 1};
    add_or_update_entry(pdu1);
    log_operation("Added/Updated entry for RNTI: 200");

    set_crc_flag(100, 200, 0);
    log_operation("CRCFLAG reset for RNTI: 200");

    return 0;
}
