    unsigned long rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    unsigned long rnti;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char *message) {
    FILE *log_file = fopen("error.log", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pdu_list(int count, int rnti_min, int rnti_max, double crc_prob, const char *config_file_path) {
    srand(time(NULL));

    // Load configuration from JSON
    FILE *fp = fopen(config_file_path, "r");
    if (!fp) {
        log_error("Failed to open config file.");
        return NULL;
    }

    struct json_object *parsed_json, *config_rnti_min, *config_rnti_max, *config_crc_prob;
    parsed_json = json_object_from_file(config_file_path);

    if (json_object_object_get_ex(parsed_json, "rnti_min", &config_rnti_min) &&
        json_object_object_get_ex(parsed_json, "rnti_max", &config_rnti_max) &&
        json_object_object_get_ex(parsed_json, "crc_prob", &config_crc_prob)) {

        rnti_min = json_object_get_int(config_rnti_min);
        rnti_max = json_object_get_int(config_rnti_max);
        crc_prob = json_object_get_double(config_crc_prob);
    } else {
        log_error("Failed to parse configuration.");
    }

    fclose(fp);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        log_error("Memory allocation failed.");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        unsigned long rnti = rnti_min + rand() % (rnti_max - rnti_min + 1);

        RX_UE_INFORMATION_TAG rx_ue_info_tag;
        rx_ue_info_tag.rnti = rnti;

        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        crc_indication_rel8_tag.crcflag = (double)rand() / RAND_MAX < crc_prob ? 1 : 0;

        rx_ue_info_tag.crc_indication_rel8_tag = crc_indication_rel8_tag;

        pdu_list[i].rx_ue_information_tag = rx_ue_info_tag;
        pdu_list[i].rnti = rnti;
    }

    return pdu_list;
}

void free_nfa_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    free(pdu_list);
}
