### JavaScript Implementation

```javascript
const fs = require('fs');

function logError(message) {
    fs.appendFileSync('error.log', `${message}\n`);
}

function cumulativeSum(numbers) {
    if (!Array.isArray(numbers)) {
        logError("Invalid input type: Expected an array.");
        throw new Error("Invalid input type: Expected an array.");
    }

    let sum = 0;
    try {
        const result = numbers.reduce((acc, num) => {
            if (typeof num !== 'number') {
                logError(`Invalid element in array: ${num}. Expected a number.`);
                throw new TypeError("Array must contain only numbers.");
            }
            return acc + [sum += num];
        }, []);

        return result;
    } catch (error) {
        logError(error.message);
        throw error;
    }
}

// Example usage:
try {
    const testNumbers = [1, 2, 3, 4];
    console.log(cumulativeSum(testNumbers)); // Output: [1, 3, 6, 10]
} catch (error) {
    console.error("An error occurred:", error.message);
}
```

