#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

#define MAX_USERS 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG; // Assume this contains a flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} PduManager;

bool initializePduManager(PduManager *manager, size_t capacity) {
    if (capacity > MAX_USERS) return false;

    manager->pdus = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) return false;

    manager->capacity = capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return true;
}

void freePduManager(PduManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->pdus) {
        free(manager->pdus);
        manager->pdus = NULL;
    }
    manager->capacity = 0;
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

bool addPdu(PduManager *manager, uint32_t rxTag, uint16_t rnti) {
    if (manager->count >= manager->capacity) return false;

    pthread_mutex_lock(&manager->mutex);

    size_t index = manager->count++;
    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[index];

    pdu->RX_UE_INFORMATION_TAG = rxTag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRC flag

    pthread_mutex_unlock(&manager->mutex);
    return true;
}

bool validatePdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu || pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0) return false;
    // Add more validation logic as needed
    return true;
}

void logDebugInfo(PduManager *manager, bool verbose) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[i];
        if (!validatePdu(pdu)) continue;

        printf("User %zu: RX Tag = %u, RNTI = %u, CRC Flag = %d\n",
               i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&manager->mutex);

    if (verbose) {
        printf("Total PDUs: %zu\n", manager->count);
    }
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    PduManager manager;
    if (!initializePduManager(&manager, MAX_USERS)) {
        fprintf(stderr, "Failed to initialize PDU Manager\n");
        return EXIT_FAILURE;
    }

    addPdu(&manager, 12345, 6789);
    logDebugInfo(&manager, true);

    freePduManager(&manager);
    return EXIT_SUCCESS;
}
