    int RB_ID;
    TCI_STATE state;
    int MCS;
} LTE_MAC_TransportChannelInfo;

#define INITIAL_CAPACITY 10

// Mutex for thread safety and cache management
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to simulate fetching valid RB_IDs from an external source
int fetch_valid_RB_IDS(int *valid_ids, size_t max_size) {
    // Simulate network call with static values for simplicity
    int ids[] = {1, 2, 3, 4, 5}; 
    size_t num_ids = sizeof(ids) / sizeof(ids[0]);
    if (num_ids > max_size) num_ids = max_size;

    memcpy(valid_ids, ids, num_ids * sizeof(int));
    return num_ids; // Number of valid RB_IDs fetched
}

// Cache for valid RB_IDs
int valid_RB_IDS_cache[100];
size_t cache_valid_count = 0;

void update_RB_ID_cache() {
    pthread_mutex_lock(&lock);

    if (cache_valid_count == 0) {
        cache_valid_count = fetch_valid_RB_IDS(valid_RB_IDS_cache, sizeof(valid_RB_IDS_cache)/sizeof(int));
    }

    pthread_mutex_unlock(&lock);
}

// Check for uniqueness and resolve conflicts
int is_unique_and_resolve(LTE_MAC_TransportChannelInfo *array, int count) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (array[i].RB_ID == array[j].RB_ID) {
                pthread_mutex_lock(&lock);

                update_RB_ID_cache();
                for (size_t k = 0; k < cache_valid_count; ++k) {
                    int new_id = valid_RB_IDS_cache[k];
                    int unique = 1;

                    // Check if new ID is unique
                    for (int m = 0; m < count; ++m) {
                        if (array[m].RB_ID == new_id) {
                            unique = 0;
                            break;
                        }
                    }

                    if (unique) {
                        array[j].RB_ID = new_id;
                        pthread_mutex_unlock(&lock);
                        return 1; // Conflict resolved
                    }
                }

                pthread_mutex_unlock(&lock);
            }
        }
    }
    return 0; // No conflict found
}

LTE_MAC_TransportChannelInfo* manage_channels(size_t count) {
    if (count == 0) return NULL;

    LTE_MAC_TransportChannelInfo *array = malloc(count * sizeof(LTE_MAC_TransportChannelInfo));

    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < count; ++i) {
        array[i].state = VALID_STATE;
        array[i].MCS = rand() % 10 + 1; // Random MCS value between 1 and 10

        if (!is_unique_and_resolve(array, i+1)) { 
            pthread_mutex_unlock(&lock);
            free(array);
            perror("Failed to resolve RB_ID conflicts");
            return NULL;
        }
    }

    pthread_mutex_unlock(&lock);

    return array;
}

int main() {
    LTE_MAC_TransportChannelInfo *channel_array = manage_channels(20);

    if (channel_array) {
        printf("Successfully managed channel info.\n");
        free(channel_array); // Clean up after use
    } else {
        fprintf(stderr, "Failed to manage channel info.\n");
    }

    return 0;
}
