["Below is a C implementation of the described task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMENTS 1500

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    bool* rnti_map;
} ListManager;

ListManager* create_list_manager() {
    ListManager* manager = (ListManager*)malloc(sizeof(ListManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->rnti_map = calloc(MAX_ELEMENTS + 1, sizeof(bool));

    return manager;
}

bool is_rnti_unique(ListManager* manager, int rnti) {
    if (rnti < 0 || rnti > MAX_ELEMENTS) return false;
    pthread_mutex_lock(&manager->lock);
    bool unique = !manager->rnti_map[rnti];
    if (unique) manager->rnti_map[rnti] = true;
    pthread_mutex_unlock(&manager->lock);
    return unique;
}

void reset_rnti_flag(ListManager* manager, int rnti) {
    if (rnti >= 0 && rnti <= MAX_ELEMENTS) {
        pthread_mutex_lock(&manager->lock);
        manager->rnti_map[rnti] = false;
        pthread_mutex_unlock(&manager->lock);
    }
}

bool add_pdu_to_list(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(manager, pdu.RNTI)) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;

    new_node->data = pdu;
    new_node->next = manager->head;
    manager->head = new_node;

    return true;
}

void free_list(ListManager* manager) {
    Node* current = manager->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager->rnti_map);
    free(manager);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->valid_RX_UE_INFORMATION_TAG = rand() % 100; // Example random generation
    pdu->RNTI = rand() % MAX_ELEMENTS;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 10;
    pdu->CRCFLAG = rand() % 2 == 0;
}

void populate_list_with_random_pdus(ListManager* manager, int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        add_pdu_to_list(manager, pdu);
    }
}

// Example Usage
/*
int main() {
    ListManager* manager = create_list_manager();
    populate_list_with_random_pdus(manager, 1000); // Populate with random elements

    free_list(manager);
    return 0;
}
*/

```

