extern void log_message(const char *message);

const size_t MAX_MEMORY = 1048576; // 1 MB

// Function to generate random RNTI ensuring no two consecutive values are the same
uint16_t generate_unique_rnti(uint16_t previous_rnti) {
    uint16_t rnti;
    do {
        rnti = rand() % (MAX_RNTI + 1);
    } while (rnti == previous_rnti);
    return rnti;
}

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_pi_array(size_t num_elements) {
    if (num_elements == 0 || MAX_MEMORY / sizeof(NFAPI_CRC_INDICATION_PDU_T) < num_elements) {
        log_message("Invalid number of elements or memory limit exceeded.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        log_message("Memory allocation failed.");
        return NULL;
    }

    uint16_t previous_rnti = 0; // Initialize to an invalid RNTI value
    for (size_t i = 0; i < num_elements; ++i) {
        array[i].rnti = generate_unique_rnti(previous_rnti);
        previous_rnti = array[i].rnti;

        // Populate RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
        memset(&array[i].rx_ue_info_tag, 0, sizeof(RX_UE_INFORMATION_TAG)); // Assume default initialization
        array[i].crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set crcflag to 0 or 1

        // Verify CRC using external library
        int crc_result = compute_crc((uint8_t*)&array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (crc_result != 0) {
            log_message("CRC calculation failed.");
            free(array);
            return NULL;
        }
