// Function to generate a list of structures
NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pdu_list(size_t count, int *status) {
    if (count <= 0 || !status) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_pdu_list = calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_pdu_list) {
        *status = -1; // Memory allocation failure
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        nfa_pdu_list[i].ue_info.ue_id = rand() % 10000;  // Example assignment
        snprintf(nfa_pdu_list[i].ue_info.imsi, sizeof(nfa_pdu_list[i].ue_info.imsi), "IMSI%zu", i);

        nfa_pdu_list[i].rnti = rand();  // Example RNTI

        // Generate a random CRC flag
        unsigned char crcflag_bytes[1];
        if (RAND_bytes(crcflag_bytes, sizeof(crcflag_bytes)) != 1) {
            *status = -2; // Random generation failure
            free(nfa_pdu_list);
            return NULL;
        }
        nfa_pdu_list[i].crc_tag.crcflag = crcflag_bytes[0];
    }

    *status = 0; // Success
    return nfa_pdu_list;
}

// Function to generate footer script section for a webpage
char* generate_footer_section(const char **scripts, size_t script_count) {
    if (!scripts || !script_count) {
        return NULL;
    }

    // Calculate the total length needed for the HTML string
    size_t len = 0;
    for (size_t i = 0; i < script_count; ++i) {
        len += strlen(scripts[i]);
    }
    len += 50 * script_count + 20; // Additional space for tags and separators

    char *html_str = malloc(len);
    if (!html_str) {
        return NULL;
    }

    strcpy(html_str, "<script>");
    for (size_t i = 0; i < script_count; ++i) {
        strcat(html_str, scripts[i]);
        if (i != script_count - 1) {
            strcat(html_str, ";");
        }
    }
    strcat(html_str, "</script>");

    return html_str;
}

// Sample usage
