#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RNTI;
    // Other fields...
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
    // Other fields...
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG information_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPI_List;

NFAPI_List* create_list() {
    NFAPI_List* list = malloc(sizeof(NFAPI_List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

int is_rnti_unique(NFAPI_List* list, int rnti) {
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti)
            return 0;
        current = current->next;
    }
    return 1;
}

void add_pdu(NFAPI_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_ELEMENTS || !is_rnti_unique(list, pdu.rnti)) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    ListNode* new_node = malloc(sizeof(ListNode));
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void free_list(NFAPI_List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_List* merge_lists(NFAPI_List* a, NFAPI_List* b) {
    NFAPI_List* merged_list = create_list();

    ListNode* current_a = a->head;
    while (current_a != NULL) {
        if (is_rnti_unique(merged_list, current_a->data.rnti))
            add_pdu(merged_list, current_a->data);
        current_a = current_a->next;
    }

    ListNode* current_b = b->head;
    while (current_b != NULL) {
        if (is_rnti_unique(merged_list, current_b->data.rnti))
            add_pdu(merged_list, current_b->data);
        current_b = current_b->next;
    }

    return merged_list;
}

void log_operation(const char* operation, NFAPI_List* list) {
    time_t now = time(NULL);
    pthread_mutex_lock(&list->lock);

    printf("[%s] Operation: %s, List Size: %zu\n", 
           ctime(&now), operation, list->count);

    pthread_mutex_unlock(&list->lock);
}

void periodic_merge_and_log(NFAPI_List* lists[], size_t num_lists) {
    while (1) {
        sleep(60);  // Periodic check every minute

        NFAPI_List* merged_list = create_list();
        for (size_t i = 0; i < num_lists; ++i) {
            merge_lists(merged_list, lists[i]);
        }

        log_operation("Merge", merged_list);

        free_list(merged_list);
    }
}

void detect_and_adapt_to_api_changes() {
    // Placeholder for API change detection logic
}

int main() {
    NFAPI_List* list1 = create_list();
    NFAPI_List* list2 = create_list();

    pthread_t merge_thread;
    NFAPI_List* lists[] = {list1, list2};

    if (pthread_create(&merge_thread, NULL, (void*)periodic_merge_and_log, lists) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Simulate adding PDUs...

    pthread_join(merge_thread, NULL);

    free_list(list1);
    free_list(list2);

    return 0;
}
