import pthread.h

// Definitions for LTE_PHY_RX_FRAME_INFO structure.
typedef struct {
    int pdu_session_id;
    unsigned int g5_rnti; // 5G-RNTI should be unique within the list
    struct LERQ_INDICATION_T {
        bool flag; // Randomly set flag
    } lerq_indication;
} LTE_PHY_RX_FRAME_INFO;

// Define a dynamic list structure with synchronization mechanisms.
typedef struct {
    LTE_PHY_RX_FRAME_INFO *elements;   // Pointer to array of elements
    size_t capacity;                   // Current capacity of the list
    size_t size;                       // Current number of valid elements
    pthread_mutex_t lock;              // Mutex for thread-safe operations
} DynamicList;

// Function declarations.
DynamicList* create_dynamic_list(size_t initial_capacity);
bool add_element(DynamicList *list, LTE_PHY_RX_FRAME_INFO element);
LTE_PHY_RX_FRAME_INFO* find_element_by_g5_rnti(DynamicList *list, unsigned int g5_rnti);
void free_dynamic_list(DynamicList *list);

// Implementation of functions.
DynamicList* create_dynamic_list(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->elements = (LTE_PHY_RX_FRAME_INFO*)calloc(initial_capacity, sizeof(LTE_PHY_RX_FRAME_INFO));
    list->capacity = initial_capacity;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool is_unique_g5_rnti(DynamicList *list, unsigned int g5_rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].g5_rnti == g5_rnti) return false;
    }
    return true;
}

bool add_element(DynamicList *list, LTE_PHY_RX_FRAME_INFO element) {
    pthread_mutex_lock(&list->lock);

    if (!is_unique_g5_rnti(list, element.g5_rnti)) {
        pthread_mutex_unlock(&list->lock);
        return false; // 5G-RNTI is not unique
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_RX_FRAME_INFO *new_elements = (LTE_PHY_RX_FRAME_INFO*)realloc(list->elements, new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));

        if (!new_elements) {
            pthread_mutex_unlock(&list->lock);
            return false; // Memory allocation failed
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->size++] = element;

    pthread_mutex_unlock(&list->lock);
    return true;
}

LTE_PHY_RX_FRAME_INFO* find_element_by_g5_rnti(DynamicList *list, unsigned int g5_rnti) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        if (list->elements[i].g5_rnti == g5_rnti) {
            pthread_mutex_unlock(&list->lock);
            return &list->elements[i];
        }
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void free_dynamic_list(DynamicList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->elements);
        free(list);
    }
}
```

### Explanation and Integration:

1. **Dynamic List Structure**: A `DynamicList` structure is created to manage the list of `LTE_PHY_RX_FRAME_INFO`. It includes a mutex for synchronization.

2. **Thread Safety**: The use of `pthread_mutex_t lock` ensures thread-safe operations, preventing race conditions during concurrent access.

3. **Memory Management**: 
   - Initial memory allocation uses `calloc` for zero-initialization.
   - Dynamic reallocation is used to handle growth, doubling the capacity when necessary, which balances between pre-allocation and dynamic resizing efficiency.

4. **Uniqueness Validation**: The `is_unique_g5_rnti()` function checks that each 5G-RNTI is unique before adding an element to avoid collisions.

5. **Integration**:
   - This code can be integrated into systems using APIs compliant with 3GPP standards.
   - Consider testing with mock data to ensure compatibility and performance under various network conditions.

6. **Documentation**: Ensure to document the initialization, addition, search, and deallocation processes in detail within the system documentation for developers.']

