typedef struct {
    CRC_INDICATION_REL8_TAG crcTag;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t pduMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t totalAllocatedSize = 0;
static size_t totalUsedPDUs = 0;
static time_t lastStatisticsTime = 0;

void* allocateNfaPduArray(size_t n, int *status) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *status = -1; // Allocation failure
        fprintf(stderr, "Error: Memory allocation failed for %zu NFAPI_CRC_INDICATION_PDU_T\n", n);
        return NULL;
    }

    pthread_mutex_lock(&pduMutex);

    totalAllocatedSize += n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    totalUsedPDUs += n;

    pthread_mutex_unlock(&pduMutex);

    for (size_t i = 0; i < n; ++i) {
        array[i].crcTag.RX_UE_INFORMATION_TAG = rand() % 100;
        array[i].crcTag.RNTI = rand() % 10000;
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    *status = 0; // Success
    return (void *)array;
}

void logPduStatistics() {
    pthread_mutex_lock(&pduMutex);

    time_t currentTime = time(NULL);
    if (difftime(currentTime, lastStatisticsTime) >= 60) { // Log every minute
        printf("Total Allocated Size: %zu bytes\n", totalAllocatedSize);
        double averagePduSize = totalUsedPDUs > 0 ? (double)totalAllocatedSize / totalUsedPDUs : 0.0;
        printf("Average PDU Size: %.2f bytes\n", averagePduSize);

        lastStatisticsTime = currentTime;
    }

    pthread_mutex_unlock(&pduMutex);
}

// Example usage in a thread-safe system
void* manageNfaPdus(void *arg) {
    size_t numPDUs = *((size_t *)arg);
    int status;

    void *pdus = allocateNfaPduArray(numPDUs, &status);

    if (status == 0 && pdus != NULL) {
        // Process PDUs here
    }

    logPduStatistics();

    free(pdus); // Ensure to free memory
    return NULL;
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t numPDUs = 10; // Example input for N

    pthread_t threadId;
    if (pthread_create(&threadId, NULL, manageNfaPdus, &numPDUs) != 0) {
        fprintf(stderr, "Error: Failed to create thread\n");
        return EXIT_FAILURE;
    }

    pthread_join(threadId, NULL);

    return EXIT_SUCCESS;
}
