        if (system->array[i].RNTI == RNTI) {
            system->array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            system->array[i].CRC_DATA.CRCFLAG = CRCFLAG;
            log_operation(system, "UPDATE", RNTI);
            return;
        }
    }

    if (system->count >= system->capacity) {
        resize_array(system);
    }

    system->array[system->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    system->array[system->count].RNTI = RNTI;
    system->array[system->count].CRC_DATA.CRCFLAG = CRCFLAG;
    log_operation(system, "INSERT", RNTI);
    ++system->count;
}

void remove_entry(DataManagementSystem *system, uint16_t RNTI) {
    for (size_t i = 0; i < system->count; ++i) {
        if (system->array[i].RNTI == RNTI) {
            log_operation(system, "DELETE", RNTI);
            memmove(&system->array[i], &system->array[i + 1], (system->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --system->count;
            return;
        }
    }
}

