    while (current) {
        printf("Operation: %s, RNTI: %d\n", current->operation, current->RNTI);
        current = current->next;
    }
}

void free_system(DataManagementSystem *system) {
    free(system->array);
    LogEntry *current = system->log_head;
    while (current) {
        LogEntry *temp = current;
        current = current->next;
        free(temp);
    }
