typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG; // Example field, implement as needed.
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG crc_tag;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Validation function for NFAPI_CRC_INDICATION_PDU_T
bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement specific validation logic.
    return pdu->crc_tag.CRCFLAG != 0; // Example condition, adjust as needed.
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    size_t count;
    pthread_mutex_t lock;
} PduList;

// Initialize the linked list
void init_pdu_list(PduList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T with random CRCFLAG
NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int rx_ue_tag, unsigned int rnti) {
    if (!rx_ue_tag || !rnti)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu)
        return NULL;

    pdu->crc_tag.CRCFLAG = rand() % 256; // Random CRCFLAG generation
    pdu->crc_tag.RX_UE_INFORMATION_TAG = rx_ue_tag;
    pdu->crc_tag.RNTI = rnti;
    pdu->prev = NULL;
    pdu->next = NULL;

    return pdu;
}

// Add a new PDU to the list if valid
void add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu || !validate_pdu(pdu))
        return;

    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = pdu;
        pdu->prev = list->tail;
        list->tail = pdu;
    } else {
        list->head = list->tail = pdu;
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Remove a PDU from the list
void remove_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu)
        return;

    pthread_mutex_lock(&list->lock);
    if (pdu->prev) {
        pdu->prev->next = pdu->next;
    } else {
        list->head = pdu->next;
    }

    if (pdu->next) {
        pdu->next->prev = pdu->prev;
    } else {
        list->tail = pdu->prev;
    }

    free(pdu);
    list->count--;
    pthread_mutex_unlock(&list->lock);
}

// Iterate over the list and apply a function to each PDU
void iterate_pdu_list(PduList* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!func)
        return;

    pthread_mutex_lock(&list->lock);

    for (NFAPI_CRC_INDICATION_PDU_T* pdu = list->head; pdu != NULL; pdu = pdu->next) {
        func(pdu);
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the entire list
void free_pdu_list(PduList* list) {
    if (!list)
        return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = list->head;
    while (pdu != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_pdu = pdu->next;
        free(pdu);
        pdu = next_pdu;
    }

    list->head = list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example function to process each PDU
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu)
        printf("RNTI: %u, RX_UE_TAG: %u, CRCFLAG: %d\n", 
               pdu->crc_tag.RNTI, 
               pdu->crc_tag.RX_UE_INFORMATION_TAG, 
               pdu->crc_tag.CRCFLAG);
}

// Main function for testing
int main() {
    PduList list;
    init_pdu_list(&list);

    // Create and add PDUs to the list
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(i + 1, i * 100 + 1);
        if (pdu)
            add_pdu(&list, pdu);
    }

    // Iterate and print each PDU
    iterate_pdu_list(&list, print_pdu);

    // Free the list
    free_pdu_list(&list);

    return 0;
}
