        free(manager->array);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

bool add_or_update_element(CRCIndicationManager *manager, unsigned int tag, unsigned short rnti, bool crcflag) {
    if (!manager || manager->size >= MAX_ELEMENTS) return false;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            manager->array[i].RX_UE_INFORMATION_TAG = tag;
            manager->array[i].CRCFLAG = crcflag;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    if (manager->size < MAX_ELEMENTS) {
        manager->array[manager->size++] = (NFAPI_CRC_INDICATION_PDU_T){tag, rnti, crcflag};
    }

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool remove_element(CRCIndicationManager *manager, unsigned short rnti) {
    if (!manager || manager->size == 0) return false;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            memmove(&manager->array[i], &manager->array[i + 1], (manager->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return false;
}

size_t count_unique_rntis(CRCIndicationManager *manager) {
    if (!manager || manager->size == 0) return 0;

    pthread_mutex_lock(&manager->lock);

    bool *seen = (bool *)calloc(MAX_ELEMENTS, sizeof(bool));
    size_t unique_count = 0;

    for (size_t i = 0; i < manager->size; ++i) {
        if (!seen[manager->array[i].RNTI]) {
            seen[manager->array[i].RNTI] = true;
            unique_count++;
        }
    }

    free(seen);
    pthread_mutex_unlock(&manager->lock);

    return unique_count;
}

int main() {
    CRCIndicationManager *manager = create_crc_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create manager\n");
        return 1;
    }

    add_or_update_element(manager, 123, 456, true);
    add_or_update_element(manager, 789, 123, false);

    printf("Unique RNTIs: %zu\n", count_unique_rntis(manager));

    remove_element(manager, 456);
    printf("Unique RNTIs after removal: %zu\n", count_unique_rntis(manager));

    destroy_crc_manager(manager);
    return 0;
}
