    cache->size = 0;
}

// Add a session to the cache
int add_session(SessionCache* cache, const UserSession* session) {
    CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
    if (!new_node) return -1;

    memcpy(&new_node->session, session, sizeof(UserSession));
    new_node->next = NULL;

    pthread_mutex_lock(&cache->lock);

    // Insert at the head for simplicity
    new_node->next = cache->head;
    cache->head = new_node;
    cache->size++;

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

// Retrieve a session from the cache by SESSION_ID
UserSession* get_session(const SessionCache* cache, const char* session_id) {
    pthread_mutex_lock((pthread_mutex_t*)&cache->lock);

    CacheNode* current = cache->head;
    while (current != NULL) {
        if (strcmp(current->session.SESSION_ID, session_id) == 0) {
            // Update last access time
            current->session.LAST_ACCESS_TIME = time(NULL);
            pthread_mutex_unlock((pthread_mutex_t*)&cache->lock);
            return &current->session;
        }
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&cache->lock);
    return NULL;
}

