    void* (*custom_alloc)(size_t);
    void (*custom_free)(void*);
} CRC_LIST;

// Custom memory allocator
static void* custom_alloc(size_t size) {
    return malloc(size); // Simplified; replace with a more sophisticated allocator if needed
}

static void custom_free(void *ptr) {
    free(ptr); // Simplified; replace with custom freeing logic if necessary
}

// Random number generator for CRCFLAG
int random_crc_flag() {
    return rand() % 2;
}

// Initialize the list structure
void crc_list_init(CRC_LIST* list, void* (*allocator)(size_t), void (*freer)(void*)) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        list->data[i] = NULL;
    }
    list->custom_alloc = allocator;
    list->custom_free = freer;
}

// Add an element to the list
void crc_list_add(CRC_LIST* list, uint16_t rx_UE_TAG, uint16_t rnti, int (*log_func)(const char*)) {
    pthread_mutex_lock(&list->lock);

    if (list->count < MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T *element = list->custom_alloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        element->crc_tag.RX_UE_INFORMATION_TAG = rx_UE_TAG;
        element->crc_tag.RNTI = rnti;
        element->CRCFLAG = random_crc_flag();

        list->data[list->count] = element;

        if (log_func) {
            log_func("Added element, Count: ");
            printf("%zu\n", list->count + 1);
        }

        list->count++;
    } else {
        // Handle case when the list is full
        if (log_func) {
            log_func("List is full.\n");
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove an element from the list
void crc_list_remove(CRC_LIST* list, size_t index, int (*log_func)(const char*)) {
    pthread_mutex_lock(&list->lock);

    if (index < list->count) {
        NFAPI_CRC_INDICATION_PDU_T *element = list->data[index];

        list->custom_free(element);
        for (size_t i = index; i < list->count - 1; ++i) {
            list->data[i] = list->data[i + 1];
        }
        list->data[list->count - 1] = NULL;
        list->count--;

        if (log_func) {
            log_func("Removed element, Count: ");
            printf("%zu\n", list->count);
        }
    } else {
        // Handle invalid index
        if (log_func) {
            log_func("Invalid index for removal.\n");
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Free all resources in the list
void crc_list_free(CRC_LIST* list, int (*log_func)(const char*)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i]) {
            list->custom_free(list->data[i]);
            list->data[i] = NULL;
        }
    }

    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);

    if (log_func) {
        log_func("Freed all resources.\n");
    }
}

// Example logging function
int example_log(const char* message) {
    printf("%s", message);
    return 0;
}
```

### Key Features:
- **Thread Safety**: Mutex locks (`pthread_mutex_t`) ensure that the list is accessed safely by multiple threads.
- **Custom Memory Management**: Simplified custom memory functions are placeholders for more sophisticated allocators to minimize fragmentation.
- **Logging Integration**: A logging function interface allows integration with external systems for performance monitoring and debugging.
- **Dynamic List Operations**: Handles up to 10,000 elements, supporting dynamic resizing while avoiding reallocation in place. 

This setup can be extended further based on specific needs such as more advanced memory management or additional list operations.']

