NFAPI_CRC_INDICATION_PDU_T* populate_crc_indications(size_t N, size_t* num_created) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    struct rusage usage_start, usage_end;
    clock_t start_time, end_time;
    int result;

    // Measure and log the start time of the operation
    getrusage(RUSAGE_SELF, &usage_start);
    start_time = clock();

    // Allocate memory for N structures
    array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < N; ++i) {
        array[i].crc_tag.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        array[i].crc_tag.RNTI = rand() % 10000; // Example range

        // Generate a random CRCFLAG without bias
        result = rand();
        array[i].CRCFLAG = (result & 1) ? 1 : 0;
    }

    // Measure and log the end time of the operation
    getrusage(RUSAGE_SELF, &usage_end);
    end_time = clock();

    *num_created = N;

    printf("Start Time: %ld.%06d\n", (long)(start_time / CLOCKS_PER_SEC), (int)(start_time % CLOCKS_PER_SEC));
    printf("End Time: %ld.%06d\n", (long)(end_time / CLOCKS_PER_SEC), (int)(end_time % CLOCKS_PER_SEC));
    printf("Start Rss: %ld\n", usage_start.ru_maxrss);
    printf("End Rss: %ld\n", usage_end.ru_maxrss);

    return array;
}
