    size_t size;
    pthread_mutex_t lock;
    time_t garbage_threshold;
} DynamicList;

// External configuration system placeholders
extern int get_max_size();
extern float get_growth_factor();
extern time_t get_gc_threshold();

// Logging system placeholder
extern void log_error(const char *message);
extern void log_info(const char *message);

bool is_valid_rnti(unsigned int rnti) {
    // Implement validation logic for RNTI
    return true; 
}

void init_dynamic_list(DynamicList *list, size_t initial_capacity) {
    list->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->garbage_threshold = get_gc_threshold();
}

void resize_dynamic_list(DynamicList *list) {
    float growth_factor = get_growth_factor();
    size_t new_capacity = (size_t)(list->capacity * growth_factor);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    } else {
        log_error("Failed to resize dynamic list");
    }
}

void add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    if (!is_valid_rnti(element.RNTI)) {
        log_error("Invalid RNTI value");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == element.RNTI) {
            log_error("Duplicate RNTI detected");
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    if (list->size >= list->capacity) {
        resize_dynamic_list(list);
    }

    element.timestamp = time(NULL);
    list->data[list->size++] = element;

    // Sort the array by RNTI
    for (size_t i = 0; i < list->size - 1; ++i) {
        size_t min_idx = i;
        for (size_t j = i + 1; j < list->size; ++j) {
            if (list->data[j].RNTI < list->data[min_idx].RNTI) {
                min_idx = j;
            }
        }
        NFAPI_CRC_INDICATION_PDU_T temp = list->data[i];
        list->data[i] = list->data[min_idx];
        list->data[min_idx] = temp;
    }

    pthread_mutex_unlock(&list->lock);
}

void garbage_collect(DynamicList *list) {
    time_t current_time = time(NULL);
    int removed_count = 0;

    pthread_mutex_lock(&list->lock);

    size_t write_index = 0;
    for (size_t i = 0; i < list->size; ++i) {
        if ((current_time - list->data[i].timestamp) > list->garbage_threshold) {
            removed_count++;
        } else {
            list->data[write_index++] = list->data[i];
        }
    }

    list->size = write_index;

    log_info("Garbage collection completed. Removed: %d elements", removed_count);

    pthread_mutex_unlock(&list->lock);
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->data);
}

int main() {
    DynamicList list;
    init_dynamic_list(&list, 10); // Initial capacity

    NFAPI_CRC_INDICATION_PDU_T new_element = { .RNTI = rand(), .CRCFLAG = rand() % 2 };
    add_element(&list, new_element);

    garbage_collect(&list);
    free_dynamic_list(&list);

    return 0;
}
```

### Key Features:
- **Thread Safety**: Uses `pthread_mutex_t` for thread-safe operations.
- **Dynamic Resizing**: Resizes when capacity is exceeded using a growth factor from the configuration system.
- **Garbage Collection**: Periodically removes elements older than a threshold, freeing resources.
- **Sorting**: Maintains elements sorted by RNTI after each insertion.
- **Logging and Configuration**: Integrates with external logging and configuration systems for runtime adjustments.

### Note:
- Replace placeholders for external systems (`get_max_size`, `get_growth_factor`, `get_gc_threshold`, and logging functions) with actual implementations or interfaces as required.']

