#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define FILE_NAME_LENGTH 256

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PDUList;

PDUList create_pdu_list(size_t max_size) {
    PDUList list = {NULL, 0, max_size};
    pthread_mutex_init(&list.lock, NULL);
    return list;
}

int add_pdu_to_list(PDUList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Overflow
    }

    if (list->pdu_list == NULL) {
        list->pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    }

    list->pdu_list[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int serialize_pdu_list(const PDUList* list, const char* directory, int overwrite_prompt, size_t serialization_interval) {
    static time_t last_serialization_time = 0;
    pthread_mutex_lock(&list->lock);

    if (difftime(time(NULL), last_serialization_time) < serialization_interval) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Serialization interval not met
    }

    char file_name[FILE_NAME_LENGTH];
    time_t current_time = time(NULL);
    snprintf(file_name, FILE_NAME_LENGTH, "%s/pdu_list_%ld.bin", directory, current_time);

    FILE* file = fopen(file_name, overwrite_prompt ? "wb" : "xb");
    if (file == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // File open error
    }

    fwrite(list->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    fclose(file);

    last_serialization_time = current_time;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);
    free(list->pdu_list);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    PDUList pdu_list = create_pdu_list(MAX_LIST_SIZE);

    for (size_t i = 0; i < MAX_LIST_SIZE; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.crc_tag.CRCFLAG = rand() % 2;

        if (add_pdu_to_list(&pdu_list, pdu) != 0) {
            fprintf(stderr, "Failed to add PDU. List may be full.\n");
            break;
        }
    }

    if (serialize_pdu_list(&pdu_list, ".", 1, 10) == 0) {
        printf("PDU list serialized successfully.\n");
    } else {
        fprintf(stderr, "Serialization failed or interval not met.\n");
    }

    destroy_pdu_list(&pdu_list);
    return 0;
}
