#define MAX_LIST_SIZE 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
    size_t capacity;
    int overwrite;
    time_t last_serialization_time;
    double serialization_interval;
} ListManager;

void init_list_manager(ListManager *manager, size_t initial_capacity, int overwrite, double interval) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->overwrite = overwrite;
    manager->last_serialization_time = time(NULL);
    manager->serialization_interval = interval;
}

void resize_list(ListManager *manager) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity && manager->capacity < MAX_LIST_SIZE) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(manager->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list != NULL) {
            manager->list = new_list;
            manager->capacity = new_capacity;
        } else {
            fprintf(stderr, "Memory allocation failed while resizing list.\n");
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void add_pdu(ListManager *manager) {
    resize_list(manager);

    pthread_mutex_lock(&manager->lock);

    if (manager->size < manager->capacity) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        srand((unsigned int)time(NULL));

        pdu.RX_UE_INFORMATION_TAG = rand() % 10000; // Randomly assign
        pdu.RNTI = rand() % 1000;                   // Randomly assign
        pdu.crc_tag.CRCFLAG = rand() % 2;           // Set CRCFLAG randomly

        manager->list[manager->size++] = pdu;
    }

    pthread_mutex_unlock(&manager->lock);
}

void serialize_list(ListManager *manager, const char *base_filename) {
    time_t current_time = time(NULL);
    if (difftime(current_time, manager->last_serialization_time) < manager->serialization_interval) {
        return;
    }

    pthread_mutex_lock(&manager->lock);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s_%ld.bin", base_filename, current_time);

    FILE *file = fopen(filename, manager->overwrite ? "wb" : "xb");
    if (file != NULL) {
        fwrite(manager->list, sizeof(NFAPI_CRC_INDICATION_PDU_T), manager->size, file);
        fclose(file);
        manager->last_serialization_time = current_time;
    } else {
        fprintf(stderr, "Failed to open file for serialization.\n");
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_list_manager(ListManager *manager) {
    if (manager != NULL) {
        free(manager->list);
        manager->list = NULL;
        pthread_mutex_destroy(&manager->lock);
    }
}
