#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 100000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *tasks[MAX_TASKS];
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    int task_count;
    int high_priority_queue[MAX_TASKS];
    int low_priority_queue[MAX_TASKS];
} TaskManager;

TaskManager manager = {0};

void* worker_function(void* arg) {
    while (1) {
        pthread_mutex_lock(&manager.lock);

        // Process tasks based on priority
        if (manager.task_count > 0) {
            int task_index;

            if (manager.high_priority_queue[0] != -1) {
                task_index = manager.high_priority_queue[0];
                for (int i = 0; i < manager.task_count - 1; ++i)
                    manager.high_priority_queue[i] = manager.high_priority_queue[i + 1];
            } else if (manager.low_priority_queue[0] != -1) {
                task_index = manager.low_priority_queue[0];
                for (int i = 0; i < manager.task_count - 1; ++i)
                    manager.low_priority_queue[i] = manager.low_priority_queue[i + 1];
            } else {
                pthread_cond_wait(&manager.cond_var, &manager.lock);
                continue;
            }

            // Process the task
            printf("Processing task ID: %d\n", task_index);

            for (int i = 0; i < manager.task_count - 1; ++i) {
                if (task_index == manager.high_priority_queue[i]) 
                    manager.high_priority_queue[i] = manager.high_priority_queue[manager.task_count - 1];

                if (task_index == manager.low_priority_queue[i])
                    manager.low_priority_queue[i] = manager.low_priority_queue[manager.task_count - 1];
            }

            free(manager.tasks[task_index]);
            manager.tasks[task_index] = NULL;
            --manager.task_count;
        }

        pthread_mutex_unlock(&manager.lock);
    }
    return NULL;
}

void initialize_manager(int num_workers) {
    pthread_mutex_init(&manager.lock, NULL);
    pthread_cond_init(&manager.cond_var, NULL);
    memset(manager.high_priority_queue, -1, sizeof(manager.high_priority_queue));
    memset(manager.low_priority_queue, -1, sizeof(manager.low_priority_queue));

    for (int i = 0; i < MAX_TASKS; ++i) {
        manager.tasks[i] = NULL;
    }

    pthread_t workers[num_workers];
    for (int i = 0; i < num_workers; ++i) {
        if (pthread_create(&workers[i], NULL, worker_function, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            exit(1);
        }
    }
}

void submit_task(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int priority) {
    pthread_mutex_lock(&manager.lock);

    if (manager.task_count >= MAX_TASKS) {
        printf("Max task limit reached. Dropping new tasks.\n");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_task = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_task) {
        perror("Failed to allocate memory for task");
        pthread_mutex_unlock(&manager.lock);
        return;
    }

    new_task->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_task->RNTI = RNTI;
    new_task->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_task->CRCFLAG = manager.task_count; // Unique based on index

    int task_index = manager.task_count++;

    if (priority) {
        for (int i = MAX_TASKS - 1; i > 0 && manager.high_priority_queue[i-1] != -1; --i)
            manager.high_priority_queue[i] = manager.high_priority_queue[i-1];

        manager.high_priority_queue[0] = task_index;
    } else {
        for (int i = MAX_TASKS - 1; i > 0 && manager.low_priority_queue[i-1] != -1; --i)
            manager.low_priority_queue[i] = manager.low_priority_queue[i-1];

        manager.low_priority_queue[0] = task_index;
    }

    manager.tasks[task_index] = new_task;

    pthread_cond_signal(&manager.cond_var);
    pthread_mutex_unlock(&manager.lock);
}

void cleanup_manager() {
    for (int i = 0; i < MAX_TASKS; ++i) {
        if (manager.tasks[i]) {
            free(manager.tasks[i]);
        }
    }

    pthread_mutex_destroy(&manager.lock);
    pthread_cond_destroy(&manager.cond_var);
}
```

