import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.util.logging.Level;
import java.util.logging.Logger;

public class RequestBuilder {
    private static final Logger LOGGER = Logger.getLogger(RequestBuilder.class.getName());

    public static void sendRequest(String urlString, boolean disableCertificateValidation) throws Exception {
        if (disableCertificateValidation) {
            // Implement SSL context setup for disabling certificate validation
            System.setProperty("https.protocols", "TLSv1.2");
        }

        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        try {
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            LOGGER.log(Level.INFO, "Response Code: {0}", responseCode);

            BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();

            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }
            in.close();

            LOGGER.log(Level.INFO, "Response Content: {0}", content.toString());
        } finally {
            connection.disconnect();
        }
    }

    public static String generateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : messageDigest) {
                String h = Integer.toHexString(0xFF & b);
                if (h.length() == 1) hexString.append('0');
                hexString.append(h);
            }

            return hexString.toString();
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error generating MD5 hash", e);
            return null;
        }
    }

    public static void main(String[] args) {
        try {
            sendRequest("https://example.com/api", false);
            String hash = generateMD5Hash("Hello World");
            System.out.println("MD5 Hash: " + hash);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error executing request or generating MD5", e);
        }
    }
}
