async function processUserProfiles(directory) {
    try {
        const filePattern = path.join(directory, '*.json');
        const filePaths = await glob(filePattern);

        // Process each file concurrently with controlled concurrency
        const maxConcurrency = 10;
        for (let i = 0; i < filePaths.length; i += maxConcurrency) {
            const batch = filePaths.slice(i, i + maxConcurrency);
            await Promise.all(batch.map(processFile));
        }
    } catch (error) {
        console.error('Error processing directory:', error);
    }
}

