#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

#define INITIAL_SIZE 10

typedef struct {
    int socket_fd;
    char local_ip[INET_ADDRSTRLEN];
    uint16_t local_port;
    char remote_ip[INET_ADDRSTRLEN];
    uint16_t remote_port;
    time_t last_active;
} Connection;

typedef struct {
    Connection *connections;
    size_t count;
    size_t capacity;
} ConnectionManager;

ConnectionManager* init_connection_manager() {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    if (!manager) return NULL;

    manager->capacity = INITIAL_SIZE;
    manager->count = 0;
    manager->connections = calloc(manager->capacity, sizeof(Connection));
    if (!manager->connections) {
        free(manager);
        return NULL;
    }

    return manager;
}

int resize_connection_manager(ConnectionManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    Connection *new_connections = realloc(manager->connections, new_capacity * sizeof(Connection));
    if (!new_connections) return -1;

    manager->connections = new_connections;
    manager->capacity = new_capacity;
    return 0;
}

int add_connection(ConnectionManager *manager, int socket_fd, 
                   const char *local_ip, uint16_t local_port,
                   const char *remote_ip, uint16_t remote_port) {

    if (manager->count == manager->capacity && resize_connection_manager(manager)) {
        return -1; // Resize failed
    }

    Connection conn;
    conn.socket_fd = socket_fd;
    strncpy(conn.local_ip, local_ip, INET_ADDRSTRLEN);
    conn.local_port = local_port;
    strncpy(conn.remote_ip, remote_ip, INET_ADDRSTRLEN);
    conn.remote_port = remote_port;
    conn.last_active = time(NULL);

    manager->connections[manager->count++] = conn;

    return 0; // Success
}

void remove_inactive_connections(ConnectionManager *manager, int timeout_seconds) {
    for (size_t i = 0; i < manager->count;) {
        if (difftime(time(NULL), manager->connections[i].last_active) > timeout_seconds) {
            close(manager->connections[i].socket_fd);
            memmove(&manager->connections[i], &manager->connections[i + 1],
                    (manager->count - i - 1) * sizeof(Connection));
            manager->count--;
        } else {
            i++;
        }
    }
}

void iterate_connections(ConnectionManager *manager, void (*callback)(Connection *)) {
    for (size_t i = 0; i < manager->count; ++i) {
        callback(&manager->connections[i]);
    }
}

void free_connection_manager(ConnectionManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        close(manager->connections[i].socket_fd);
    }

    free(manager->connections);
    free(manager);
}
```

This code defines a dynamic array structure to manage TCP connections with efficient memory handling and provides functions for adding, removing (based on timeout), iterating over connections, and freeing resources. It includes error checks for system calls like `malloc`, `realloc`, and `close` and assumes that the function will be integrated into a larger application where additional error handling and synchronization may be required.']

