#include <stdint.h>

#define MAX_PACKET_ID 1000

typedef struct {
    int packet_id;
    uint32_t source_address;
    uint32_t destination_address;
} PacketHeader;

typedef struct {
    // Add fields as required for CRC indication
    uint8_t CRCFLAG;
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
void allocateAndInitializeBuffers(int num_buffers, size_t payload_size, int max_concurrency);
void* monitorPerformance(void* arg);

// Global variables for demonstration purposes
static PacketHeader *packet_headers = NULL;
static sem_t *buffer_semaphores = NULL;
static pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

void allocateAndInitializeBuffers(int num_buffers, size_t payload_size, int max_concurrency) {
    packet_headers = (PacketHeader *)aligned_alloc(64, sizeof(PacketHeader) * num_buffers);
    if (!packet_headers) {
        perror("Failed to allocate packet headers");
        exit(EXIT_FAILURE);
    }

    buffer_semaphores = (sem_t *)malloc(sizeof(sem_t) * num_buffers);
    if (!buffer_semaphores) {
        free(packet_headers);
        perror("Failed to allocate semaphores");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_buffers; ++i) {
        packet_headers[i].packet_id = rand() % MAX_PACKET_ID;
        packet_headers[i].source_address = rand();
        packet_headers[i].destination_address = rand();

        sem_init(&buffer_semaphores[i], 0, max_concurrency);
    }

    // Start performance monitoring thread
    pthread_t monitor_thread;
    if (pthread_create(&monitor_thread, NULL, monitorPerformance, NULL) != 0) {
        perror("Failed to create performance monitoring thread");
        exit(EXIT_FAILURE);
    }
}

void* monitorPerformance(void* arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);

        // Example: Monitor buffer usage
        for (int i = 0; i < MAX_PACKET_ID; ++i) {
            int value;
            sem_getvalue(&buffer_semaphores[i], &value);
            if (value == 0) {
                printf("Buffer %d is fully utilized\n", i);
            }
        }

        pthread_mutex_unlock(&buffer_lock);

        // Sleep for a while to simulate monitoring interval
        sleep(1);
    }
    return NULL;
}

void freeResources(int num_buffers) {
    if (packet_headers) {
        free(packet_headers);
    }
    if (buffer_semaphores) {
        for (int i = 0; i < num_buffers; ++i) {
            sem_destroy(&buffer_semaphores[i]);
        }
        free(buffer_semaphores);
    }
}

// Usage example
int main(int argc, char *argv[]) {
    int num_buffers = 10;
    size_t payload_size = 1024;
    int max_concurrency = 5;

    if (argc > 1) {
        FILE *file = fopen(argv[1], "r");
        if (!file) {
            perror("Failed to open file");
            return EXIT_FAILURE;
        }

        char line[256];
        int line_count = 0;
        while (fgets(line, sizeof(line), file)) {
            ++line_count;
        }
        printf("Number of lines: %d\n", line_count);

        fclose(file);
    } else {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    allocateAndInitializeBuffers(num_buffers, payload_size, max_concurrency);

    // Simulate some work
    sleep(10);

    freeResources(num_buffers);

    return 0;
}
