#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_PDU 1000
#define MAX_THREADS 10

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} UE_INFO;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long timestamp; // For logging purposes, can be extended to more detailed time info
    UE_INFO ue_info;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure for memory pool
typedef struct {
    size_t item_size;
    void *pool;
    size_t num_items;
    pthread_mutex_t lock; // Mutex for thread safety
} MemoryPool;

// Function to initialize the memory pool
int init_memory_pool(MemoryPool *mp, size_t item_size, size_t num_items) {
    mp->item_size = item_size;
    mp->num_items = num_items;

    pthread_mutex_init(&mp->lock, NULL);

    // Allocate a single block of memory for all items
    mp->pool = malloc(item_size * num_items);
    if (mp->pool == NULL) {
        return -1; // Allocation failed
    }
    return 0;
}

// Function to create and populate PDU list in the pool
NFAPI_CRC_INDICATION_PDU_T* allocate_pdus(MemoryPool *mp) {
    if (!mp || mp->pool == NULL) {
        fprintf(stderr, "Memory pool not initialized.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)mp->pool;

    pthread_mutex_lock(&mp->lock); // Ensure thread safety

    for (int i = 0; i < NUM_PDU; ++i) {
        pdus[i].timestamp = time(NULL); // Capture the current timestamp
        pdus[i].ue_info.RX_UE_INFORMATION_TAG = rand(); // Random value for example purposes
        pdus[i].ue_info.RNTI = rand() % 1000; // Random RNTI, constrained to a range
        pdus[i].crc_tag.CRCFLAG = rand() & 1; // Random CRC flag (0 or 1)
    }

    pthread_mutex_unlock(&mp->lock);
    return pdus;
}

// Function to free memory pool resources
void destroy_memory_pool(MemoryPool *mp) {
    if (!mp || mp->pool == NULL) {
        return;
    }
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    MemoryPool mp = {0};
    int init_result = init_memory_pool(&mp, sizeof(NFAPI_CRC_INDICATION_PDU_T), NUM_PDU);

    if (init_result != 0) {
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = allocate_pdus(&mp);
    if (!pdus) {
        fprintf(stderr, "Failed to allocate PDUs.\n");
        destroy_memory_pool(&mp);
        return -1;
    }

    // Use the allocated pdus...

    destroy_memory_pool(&mp);

    return 0;
}
```

### Key Points:
- **Memory Pool**: A single memory allocation is used for all PDU structures, minimizing fragmentation and overhead.
- **Thread Safety**: Mutex locks ensure that concurrent access to the memory pool does not cause data races. This allows multiple threads to use `allocate_pdus` without issues.
- **Error Handling**: Memory allocation failures are handled gracefully by checking return values.
- **Randomness**: Random numbers are used for demonstration, and timestamps are set for logging purposes.

This approach aims to efficiently manage resources in a limited environment while supporting high concurrency.']

