void process_data(size_t num_records, int min_range, int max_range, const char *input_string, size_t size_limit) {
    if (num_records == 0 || min_range > max_range || input_string == NULL) {
        return;
    }

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    record *records_array = malloc(num_records * sizeof(record));

    char *result_string = NULL;

    if (!offsets || !keys || !records_array) {
        free(offsets);
        free(keys);
        free(records_array);
        return;
    }

    srand((unsigned int)time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_records; ++i) {
        if ((long)(rand() % (max_range - min_range + 1)) < LONG_MAX && 
            (int)(min_range + rand() % (max_range - min_range + 1)) <= INT_MAX) {

            records_array[i].value = min_range + rand() % (max_range - min_range + 1);
        } else {
            free(offsets);
            free(keys);
            free(records_array);
            return;
        }
    }

    if (strlen(input_string) < size_limit) {
        result_string = malloc(strlen(input_string) + 2); // +1 for '/' and +1 for '\0'
        if (!result_string) {
            free(offsets);
            free(keys);
            free(records_array);
            return;
        }
        strcpy(result_string, input_string);
        strcat(result_string, "/");
    }

    // Assume processing is done at this point
    // ...

    // Free all allocated resources
    free(offsets);
    free(keys);
    free(records_array);

