} TX_RACH_CQI_REPORT_TAG;

typedef struct {
    TX_RACH_INDICATION_TAG indication_tag;
    TX_RACH_CQI_REPORT_TAG cqi_report_tag;
} MAC_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

bool validate_mac_pdu(const MAC_PDU_T* pdu) {
