            pdu->cqi_report_tag.cqi_value >= 0);
}

MAC_PDU_T* initialize_dynamic_array(size_t num_pdus, int cqi_value, int max_size, size_t* actual_num) {
    pthread_mutex_lock(&lock);

    if (num_pdus > max_size) {
        *actual_num = 0;
        printf("Requested number of PDUs exceeds maximum allowed.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    MAC_PDU_T* array = (MAC_PDU_T*)malloc(num_pdus * sizeof(MAC_PDU_T));
    if (!array) {
        printf("Memory allocation failed for dynamic array.\n");
        *actual_num = 0;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    size_t initialized_count = 0;
    for (size_t i = 0; i < num_pdus; ++i) {
        array[i].indication_tag.rrc_cause = i % 10; // Example unique RRC Cause
        array[i].cqi_report_tag.cqi_value = cqi_value;

