['Below is a C code snippet implementing the `manageTCPConnections` function along with a static MD5 hash calculation function using OpenSSL for cryptographic operations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#include <openssl/md5.h>

#define INITIAL_SIZE 10
#define M 100

typedef struct {
    int socketDescriptor;
    char localIP[INET6_ADDRSTRLEN];
    unsigned short localPort;
    char remoteIP[INET6_ADDRSTRLEN];
    unsigned short remotePort;
    time_t lastActiveTime; // For timeout management
} TCPConnection;

typedef struct {
    TCPConnection *connections;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;  // Mutex for thread safety
} ConnectionManager;

// Function to initialize the connection manager
void initConnectionManager(ConnectionManager *manager) {
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    manager->connections = malloc(sizeof(TCPConnection) * manager->capacity);
    pthread_mutex_init(&manager->lock, NULL);
}

// Function to add a new TCP connection
int addTCPConnection(ConnectionManager *manager, int socketDescriptor,
                     const char *localIP, unsigned short localPort,
                     const char *remoteIP, unsigned short remotePort) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        TCPConnection *newConnections = realloc(manager->connections, sizeof(TCPConnection) * newCapacity);
        if (!newConnections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->connections = newConnections;
        manager->capacity = newCapacity;
    }

    TCPConnection *conn = &manager->connections[manager->count++];
    conn->socketDescriptor = socketDescriptor;
    strncpy(conn->localIP, localIP, INET6_ADDRSTRLEN);
    conn->localPort = localPort;
    strncpy(conn->remoteIP, remoteIP, INET6_ADDRSTRLEN);
    conn->remotePort = remotePort;
    conn->lastActiveTime = time(NULL);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Function to remove timed-out connections
void removeTimedOutConnections(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    size_t newCount = 0;
    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(time(NULL), manager->connections[i].lastActiveTime) < 60) { // 1 minute timeout
            manager->connections[newCount++] = manager->connections[i];
        }
    }

    manager->count = newCount;
    pthread_mutex_unlock(&manager->lock);
}

// Iterator for traversing active connections
void iterateConnections(ConnectionManager *manager, void (*processConnection)(TCPConnection*)) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        processConnection(&manager->connections[i]);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Static method to calculate MD5 hash
void calculateMD5Hash(const char *input, unsigned char output[16]) {
    MD5((unsigned char *)input, strlen(input), output);
}

int main() {
    ConnectionManager manager;
    initConnectionManager(&manager);

    // Example usage of adding connections and iterating over them
    addTCPConnection(&manager, 1, "127.0.0.1", 8080, "192.168.1.2", 9090);

    iterateConnections(&manager, [](TCPConnection *conn) {
        printf("Connection from %s:%d to %s:%d\n", conn->localIP, conn->localPort,
               conn->remoteIP, conn->remotePort);
    });

    unsigned char md5hash[16];
    calculateMD5Hash("Example string", md5hash);

    for (int i = 0; i < 16; ++i) {
        printf("%02x", md5hash[i]);
    }
    printf("\n");

    // Cleanup
    free(manager.connections);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

### Explanation:
- **ConnectionManager**: Manages dynamic array of TCP connections, including resizing and locking mechanisms to handle concurrency.
- **addTCPConnection**: Adds a new connection, reallocating memory if necessary.
- **removeTimedOutConnections**: Removes connections that have timed out based on `lastActiveTime`.
- **iterateConnections**: Provides an iterator pattern to traverse active connections safely.
- **calculateMD5Hash**: Computes the MD5 hash of an input string using OpenSSL's MD5 function.

This implementation ensures thread safety and efficient memory management while maintaining high performance under load.']

