void initTCPManager(TCPManager *manager, size_t initial_capacity) {
    manager->connections = (TCPCConnection *)malloc(initial_capacity * sizeof(TCPCConnection));
    if (!manager->connections) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
}

// Function to resize the dynamic array
void resizeTCPManager(TCPManager *manager, size_t new_capacity) {
    TCPCConnection *new_connections = (TCPCConnection *)realloc(manager->connections, new_capacity * sizeof(TCPCConnection));
    if (!new_connections) {
        perror("Failed to reallocate memory");
        free(manager->connections);
        exit(EXIT_FAILURE);
    }
    manager->connections = new_connections;
    manager->capacity = new_capacity;
}

// Function to add a connection
void addConnection(TCPManager *manager, TCPCConnection conn) {
    if (manager->size == manager->capacity) {
        resizeTCPManager(manager, manager->capacity * 2);
    }
    manager->connections[manager->size++] = conn;
}

// Function to remove a connection by index
void removeConnection(TCPManager *manager, size_t index) {
    if (index >= manager->size) return;
    for (size_t i = index; i < manager->size - 1; ++i) {
        manager->connections[i] = manager->connections[i + 1];
    }
    manager->size--;
}

