#define MAX_STRUCTURES 100 // M is defined here as a constant for simplicity.

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[256];
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG tag;
    unsigned int CRCFLAG; // Set randomly
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    int max_size;
    unsigned long successful_allocations;
    unsigned long rejections_due_to_capacity;
} NFAPI_List;

// Initialize list with memory pool
NFAPI_List* create_nfaapi_list(int max_size) {
    NFAPI_List* list = (NFAPI_List*)malloc(sizeof(NFAPI_List));
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->not_full, NULL);
    list->max_size = max_size;
    list->successful_allocations = 0;
    list->rejections_due_to_capacity = 0;
    return list;
}

// Randomly set CRCFLAG
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simple random number generator for demonstration purposes.
    pdu->tag.CRCFLAG = rand() % 2; 
}

// Add element to the list with thread safety
int add_nfaapi_element(NFAPI_List* list, const NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    pthread_mutex_lock(&list->lock);

    while (list->count >= list->max_size) {
        // Option to block until space becomes available.
        pthread_cond_wait(&list->not_full, &list->lock);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    memcpy(&new_node->data, new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    set_random_crcflag(&new_node->data);

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    list->successful_allocations++;

    pthread_cond_signal(&list->not_full);
    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Serialize the list to a file
int serialize_list(NFAPI_List* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Deserialize the list from a file
int deserialize_list(NFAPI_List* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_nfaapi_element(list, &pdu);
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}

// Clean up list
void destroy_nfaapi_list(NFAPI_List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->not_full);
    free(list);
}

// Function to print the performance statistics
void print_statistics(NFAPI_List* list) {
    printf("Successful Allocations: %lu\n", list->successful_allocations);
    printf("Rejections Due To Capacity: %lu\n", list->rejections_due_to_capacity);
}
```

This code manages a list of `NFAPI_CRC_INDICATION_PDU_T` structures, ensuring thread safety and efficient memory usage with a maximum size constraint. It includes functions for adding elements, serializing/deserializing the list, and maintaining performance statistics. The implementation uses mutexes and condition variables to ensure thread-safe access and can block when the list is full or reject new entries based on specific requirements.']

