#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent a network packet.
typedef struct {
    char source_ip[16];
    char destination_ip[16];
    unsigned short port_number;
    char protocol_type[10];
} NetworkPacket;

// Function prototypes for external data source integration
int validate_ip(const char *ip);
int validate_protocol(const char *protocol);

// Helper function to check if a packet is duplicate.
int is_duplicate(NetworkPacket **packets, int count, NetworkPacket *new_packet) {
    for (int i = 0; i < count; i++) {
        if (!strcmp(packets[i]->source_ip, new_packet->source_ip) &&
            !strcmp(packets[i]->destination_ip, new_packet->destination_ip) &&
            packets[i]->port_number == new_packet->port_number &&
            !strcmp(packets[i]->protocol_type, new_packet->protocol_type)) {
            return 1;
        }
    }
    return 0;
}

// Thread-safe function to initialize and populate an array of network packets.
NetworkPacket **initialize_packets(int *packet_count) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    NetworkPacket **packets = NULL;
    int count = 0;

    pthread_mutex_lock(&mutex);

    if (packet_count && (*packet_count > 0)) {
        // Allocate memory for the array of packet pointers.
        packets = malloc(*packet_count * sizeof(NetworkPacket *));
        if (!packets) {
            perror("Failed to allocate memory for packets");
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        for (int i = 0; i < *packet_count; ++i) {
            NetworkPacket *new_packet = malloc(sizeof(NetworkPacket));
            if (!new_packet) {
                perror("Failed to allocate memory for a new packet");
                // Free previously allocated packets in case of failure
                for (int j = 0; j < count; ++j) free(packets[j]);
                free(packets);
                pthread_mutex_unlock(&mutex);
                return NULL;
            }

            // Populate the packet with example data.
            snprintf(new_packet->source_ip, sizeof(new_packet->source_ip), "192.168.1.%d", i + 1);
            snprintf(new_packet->destination_ip, sizeof(new_packet->destination_ip), "10.0.0.%d", i + 1);
            new_packet->port_number = (unsigned short)(i * 100 + 80); // Example port
            strncpy(new_packet->protocol_type, "TCP", sizeof(new_packet->protocol_type));

            // Validate the packet fields.
            if (!validate_ip(new_packet->source_ip) ||
                !validate_ip(new_packet->destination_ip) ||
                !validate_protocol(new_packet->protocol_type)) {

                free(new_packet);
                continue;
            }

            // Ensure no duplicate packets are added.
            if (!is_duplicate(packets, count, new_packet)) {
                packets[count++] = new_packet;
            } else {
                free(new_packet);
            }
        }
    }

    pthread_mutex_unlock(&mutex);

    *packet_count = count; // Update the actual packet count
    return packets;
}

// Example validation functions for external data source integration.
int validate_ip(const char *ip) {
    // Placeholder for IP address validation logic.
    return 1; // Assume valid for demonstration purposes.
}

int validate_protocol(const char *protocol) {
    // Placeholder for protocol type validation logic.
    return 1; // Assume valid for demonstration purposes.
}
