#define MAX_LOG_SIZE 1048576 // 1MB
#define MAX_RETRY_ATTEMPTS 5
#define INITIAL_BACKOFF_MS 100

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    int port_number;
    char protocol_type[10];
} NetworkPacket;

typedef struct {
    unsigned int rnti;
    int rx_ue_information_tag;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    static FILE *log_file = NULL;
    static size_t current_size = 0;
    pthread_mutex_lock(&lock);

    if (!log_file || current_size >= MAX_LOG_SIZE) {
        if (log_file) fclose(log_file);
        log_file = fopen("network_log.txt", "a");
        current_size = 0;
    }

    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] %s\n", ctime(&now), message);
        current_size += strlen(message) + 1; // +1 for newline
        fflush(log_file);
    }

    pthread_mutex_unlock(&lock);
}

int validate_network_packet(NetworkPacket *packet) {
    if (strlen(packet->source_ip) >= sizeof(packet->source_ip) ||
        strlen(packet->destination_ip) >= sizeof(packet->destination_ip) ||
        packet->port_number <= 0 || packet->port_number > 65535 ||
        strlen(packet->protocol_type) >= sizeof(packet->protocol_type)) {
        return -1;
    }
    return 0;
}

int validate_crc_structure(NFAPI_CRC_INDICATION_PDU_T *structure, unsigned int rnti_set[], size_t count) {
    if (bsearch(&structure->rnti, rnti_set, count, sizeof(unsigned int), 
                (int(*)(const void *, const void *))strcmp)) {
        return -1;
    }
    return 0;
}

void *generate_network_data(void *args) {
    size_t num_packets = *(size_t *)args;
    NetworkPacket **packets = malloc(num_packets * sizeof(NetworkPacket *));
    NFAPI_CRC_INDICATION_PDU_T **cstructures = malloc(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    unsigned int *rnti_set = calloc(num_packets, sizeof(unsigned int));
    size_t rnti_count = 0;

    if (!packets || !cstructures || !rnti_set) {
        log_message("Memory allocation failed");
        free(packets); free(cstructures); free(rnti_set);
        pthread_exit(NULL);
    }

    for (size_t i = 0; i < num_packets; ++i) {
        packets[i] = malloc(sizeof(NetworkPacket));
        cstructures[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!packets[i] || !cstructures[i]) {
            log_message("Memory allocation failed for structures");
            break;
        }

        // Populate network packet
        snprintf(packets[i]->source_ip, sizeof(packets[i]->source_ip), "192.168.1.%zu", i + 1);
        snprintf(packets[i]->destination_ip, sizeof(packets[i]->destination_ip), "10.0.0.%zu", i + 1);
        packets[i]->port_number = 8000 + i;
        strcpy(packets[i]->protocol_type, "TCP");

        if (validate_network_packet(packets[i]) != 0) {
            log_message("Invalid network packet");
            continue;
        }

        // Populate CRC structure
        cstructures[i]->rnti = rand() % 10000 + 1; // Example RNTI generation
        cstructures[i]->rx_ue_information_tag = i;
        cstructures[i]->crc_indication_rel8_tag = rand();
        cstructures[i]->crcflag = rand() & 1;

        if (validate_crc_structure(cstructures[i], rnti_set, rnti_count) != 0) {
            log_message("Duplicate RNTI found");
            continue;
        }

        rnti_set[rnti_count++] = cstructures[i]->rnti;
    }

    for (size_t i = 0; i < num_packets; ++i) {
        free(packets[i]);
        free(cstructures[i]);
    }
    free(rnti_set);

    log_message("Data generation complete");
    pthread_exit(NULL);
}

void perform_oauth_authentication(unsigned int rnti) {
    // Placeholder for OAuth authentication logic
    char auth_message[256];
    snprintf(auth_message, sizeof(auth_message), "Authenticating with RNTI: %u", rnti);
    log_message(auth_message);

    // Simulate network latency and retry mechanism
    int attempts = 0;
    while (attempts < MAX_RETRY_ATTEMPTS) {
        if (rand() % 2 == 0) { // Simulate random success/failure
            char success_message[256];
            snprintf(success_message, sizeof(success_message), "Authentication successful for RNTI: %u", rnti);
            log_message(success_message);
            return;
        } else {
            attempts++;
            int backoff_time = INITIAL_BACKOFF_MS * (1 << attempts); // Exponential backoff
            sleep(backoff_time / 1000);
        }
    }

    char failure_message[256];
    snprintf(failure_message, sizeof(failure_message), "Authentication failed for RNTI: %u after %d attempts", rnti, MAX_RETRY_ATTEMPTS);
    log_message(failure_message);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_packets>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_packets = strtoul(argv[1], NULL, 10);

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, generate_network_data, &num_packets);
    pthread_join(thread_id, NULL);

    // Assume the last RNTI is used for OAuth authentication
    unsigned int last_rnti = rand() % 10000 + 1; // Example RNTI value
    perform_oauth_authentication(last_rnti);

    return EXIT_SUCCESS;
}
