// Define a structure for network packet
typedef struct {
    char source_ip[16];
    char destination_ip[16];
    unsigned short port_number;
    int protocol_type;  // Assume this is an integer representing the protocol type
} NetworkPacket;

// Structure to hold configuration and state information
typedef struct {
    size_t capacity;
    size_t count;
    NetworkPacket **packets;
    pthread_mutex_t lock;  // Mutex for thread safety
    char ip_cache[256][16];  // Simple cache mechanism
    size_t cache_size;
} PacketManager;

// Function to initialize IP address mapping and protocol type validation
int fetch_ip_mapping_and_protocol_type(const char *ip, int *protocol_type) {
    // Simulate fetching from an external source with random success/failure
    if (rand() % 2 == 0) {  // Random failure simulation
        return -1;  // Failure to fetch data
    }
    // Simulated successful fetch
    strcpy(ip, "192.168.1.1");  // Example IP
    *protocol_type = 6;  // Example protocol type (e.g., TCP)
    return 0;
}

// Helper function to check if a packet already exists in the array
int is_duplicate_packet(NetworkPacket **packets, size_t count, const NetworkPacket *new_packet) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(packets[i]->source_ip, new_packet->source_ip) == 0 &&
            strcmp(packets[i]->destination_ip, new_packet->destination_ip) == 0 &&
            packets[i]->port_number == new_packet->port_number &&
            packets[i]->protocol_type == new_packet->protocol_type) {
            return 1;  // Duplicate found
        }
    }
    return 0;
}

// Function to add a network packet to the array
int add_packet(PacketManager *manager, const char *source_ip, const char *destination_ip,
               unsigned short port_number, int protocol_type) {

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        // Resize the packets array
        size_t new_capacity = manager->capacity == 0 ? 10 : manager->capacity * 2;
        NetworkPacket **new_packets = realloc(manager->packets, new_capacity * sizeof(NetworkPacket *));
        if (!new_packets) {
            pthread_mutex_unlock(&manager->lock);
            return -1;  // Memory allocation failure
        }
        manager->packets = new_packets;
        manager->capacity = new_capacity;
    }

    // Validate input parameters and check for duplicates
    NetworkPacket *new_packet = malloc(sizeof(NetworkPacket));
    if (!new_packet) {
        pthread_mutex_unlock(&manager->lock);
        return -1;  // Memory allocation failure
    }

    strncpy(new_packet->source_ip, source_ip, sizeof(new_packet->source_ip) - 1);
    new_packet->source_ip[sizeof(new_packet->source_ip) - 1] = '\0';
    strncpy(new_packet->destination_ip, destination_ip, sizeof(new_packet->destination_ip) - 1);
    new_packet->destination_ip[sizeof(new_packet->destination_ip) - 1] = '\0';

    if (port_number == 0 || port_number > 65535) {
        free(new_packet);
        pthread_mutex_unlock(&manager->lock);
        return -2;  // Invalid port number
    }
    new_packet->port_number = port_number;

    int validated_protocol_type;
    if (fetch_ip_mapping_and_protocol_type(source_ip, &validated_protocol_type) != 0) {
        free(new_packet);
        pthread_mutex_unlock(&manager->lock);
        return -3;  // Failure to fetch external data
    }

    new_packet->protocol_type = protocol_type == validated_protocol_type ? protocol_type : -1;

    if (new_packet->protocol_type < 0 || is_duplicate_packet(manager->packets, manager->count, new_packet)) {
        free(new_packet);
        pthread_mutex_unlock(&manager->lock);
        return -4;  // Invalid protocol type or duplicate packet
    }

    manager->packets[manager->count++] = new_packet;
    pthread_mutex_unlock(&manager->lock);

    return 0;  // Success
}

// Function to initialize the PacketManager structure
PacketManager *initialize_packet_manager(size_t initial_capacity, size_t cache_size) {
    PacketManager *manager = malloc(sizeof(PacketManager));
    if (!manager) {
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->packets = calloc(initial_capacity, sizeof(NetworkPacket *));
    if (!manager->packets) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->cache_size = cache_size;

    return manager;
}

// Function to clean up the PacketManager structure
void cleanup_packet_manager(PacketManager *manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            free(manager->packets[i]);
        }
        free(manager->packets);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

// Example usage
int main() {
    PacketManager *manager = initialize_packet_manager(10, 100);

    if (!manager) {
        fprintf(stderr, "Failed to initialize packet manager\n");
        return EXIT_FAILURE;
    }

    int result = add_packet(manager, "192.168.1.2", "192.168.1.3", 8080, 6);
    if (result != 0) {
        fprintf(stderr, "Failed to add packet: %d\n", result);
    } else {
        printf("Packet added successfully!\n");
    }

    cleanup_packet_manager(manager);

    return EXIT_SUCCESS;
}
