NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int max_entries) {
    pthread_mutex_lock(&lock);

    if (max_entries <= 0) {
        log_message("ERROR", "Invalid number of entries.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message("ERROR", "Memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int unique_crcflags[max_entries];
    memset(unique_crcflags, -1, sizeof(unique_crcflags));

    int num_valid_entries = 0;

    for (int i = 0; i < max_entries; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100 + 1;
        unsigned int rnti = generate_random_rnti();

        if (rnti >= 1 && rnti <= MAX_RNTI) {
            list[i].RNTI = rnti;

            int crcflag_candidate;
            do {
                crcflag_candidate = rand() % max_entries;
            } while (unique_crcflags[crcflag_candidate] != -1);

            unique_crcflags[crcflag_candidate] = i;  // Mark as used
            list[i].CRCFLAG = crcflag_candidate;

            list[i].CRC_INDICATION_REL8_TAG = rand() % 10 + 1;
            num_valid_entries++;

        } else {
            log_message("WARNING", "Invalid RNTI generated, skipping entry.");
        }
    }

    if (num_valid_entries < max_entries) {
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, num_valid_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list) {
            list = new_list;
        } else {
            log_message("ERROR", "Memory reallocation failed.");
        }
    }

    pthread_mutex_unlock(&lock);
    return list;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        free(list);
    }
}

// Example usage
