#include <stdlib.h>
#include <pthread.h>

#define MAX_PDU_COUNT 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDU_COUNT];
    size_t count;
    pthread_mutex_t lock;
} PduList;

void initialize_pdu_list(PduList *list) {
    list->count = 0;
    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        list->pdus[i] = NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return NULL;

    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    return new_pdu;
}

int add_pdu(PduList *list, NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_PDU_COUNT) {
        pthread_mutex_unlock(&list->lock);
        free(new_pdu); // Prevent memory leak
        return -1; // Buffer full
    }

    for (int i = 0; i < MAX_PDU_COUNT; ++i) {
        if (!list->pdus[i]) {
            list->pdus[i] = new_pdu;
            list->count++;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock); // This path should never be reached due to the check above
    free(new_pdu); // Prevent memory leak
    return -1; // Buffer full or other error
}

void reset_pdu_list(PduList *list) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->count; ++i) {
        if (list->pdus[i]) {
            free(list->pdus[i]);
            list->pdus[i] = NULL;
        }
    }

    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

void destroy_pdu_list(PduList *list) {
    reset_pdu_list(list);
    pthread_mutex_destroy(&list->lock);
}
```

