#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_UE_ID 1024
#define MIN_UE_ID 1

typedef struct RRC_COMMANDS {
    // Placeholder for actual command data structure.
} RRC_COMMANDS;

typedef struct LTE_RRC_CU_UP_MESSAGE {
    int UE_ID;
    RRC_COMMANDS commands;
} LTE_RRC_CU_UP_MESSAGE;

typedef struct Node {
    LTE_RRC_CU_UP_MESSAGE message;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
} List;

List* create_list(size_t max_entries) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

int is_ue_id_valid(int ue_id) {
    return (ue_id >= MIN_UE_ID && ue_id <= MAX_UE_ID);
}

void log_message(const char* message, int verbosity_level, int current_verbosity_level) {
    if (current_verbosity_level >= verbosity_level) {
        time_t now = time(NULL);
        printf("[%s] %s\n", ctime(&now), message);
    }
}

int add_entry(List* list, LTE_RRC_CU_UP_MESSAGE new_message, size_t max_entries, int verbosity_level) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= max_entries) {
        log_message("Max entries reached. Cannot add more.", 1, verbosity_level);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (!is_ue_id_valid(new_message.UE_ID)) {
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "Invalid UE_ID: %d", new_message.UE_ID);
        log_message(buffer, 2, verbosity_level);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* current = list->head;
    while (current) {
        if (current->message.UE_ID == new_message.UE_ID) {
            char buffer[100];
            snprintf(buffer, sizeof(buffer), "Duplicate UE_ID: %d", new_message.UE_ID);
            log_message(buffer, 2, verbosity_level);
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for new entry.", 1, verbosity_level);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->message = new_message;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    char buffer[100];
    snprintf(buffer, sizeof(buffer), "Added UE_ID: %d", new_message.UE_ID);
    log_message(buffer, 1, verbosity_level);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Serialization and deserialization functions using Protocol Buffers or MessagePack would go here.
// For brevity, they are omitted.

int main() {
    size_t max_entries = 1000;
    List* list = create_list(max_entries);

    int verbosity_level = 2; // Example verbosity level

    LTE_RRC_CU_UP_MESSAGE message1 = { .UE_ID = 123, /* Populate commands */ };
    add_entry(list, message1, max_entries, verbosity_level);

    // Further processing and cleanup
    free_list(list);

    return 0;
}
