#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_S-TMSI 65535
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2

typedef struct {
    int transaction_id;
    char rrc_message[256];
    unsigned short s_tmsi;
    char nas_pdu[256];
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context *contexts;
    size_t count;
    pthread_mutex_t lock;
} ContextManager;

int log_level = LOG_LEVEL_INFO;

void log_message(int level, const char* message) {
    if (level <= log_level) {
        printf("%s: %s\n", __func__, message);
    }
}

ContextManager* init_context_manager(size_t max_entries) {
    ContextManager *manager = malloc(sizeof(ContextManager));
    manager->contexts = calloc(max_entries, sizeof(LTE_UE_Context));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int is_valid_stmsi(unsigned short s_tmsi) {
    return (s_tmsi >= 0 && s_tmsi <= MAX_S-TMSI);
}

int add_ue_context(ContextManager *manager, int transaction_id, const char *rrc_message, unsigned short s_tmsi, const char *nas_pdu) {
    pthread_mutex_lock(&manager->lock);

    if (transaction_id < 0 || manager->count >= sizeof(manager->contexts) / sizeof(LTE_UE_Context)) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].transaction_id == transaction_id) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Transaction ID must be unique
        }
    }

    if (!is_valid_stmsi(s_tmsi)) {
        log_message(LOG_LEVEL_DEBUG, "Invalid S-TMSI value encountered.");
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    LTE_UE_Context new_context = {transaction_id, "", s_tmsi, ""};
    strncpy(new_context.rrc_message, rrc_message, sizeof(new_context.rrc_message) - 1);
    strncpy(new_context.nas_pdu, nas_pdu, sizeof(new_context.nas_pdu) - 1);

    manager->contexts[manager->count++] = new_context;

    pthread_mutex_unlock(&manager->lock);
    return 1;
}

void free_context_manager(ContextManager *manager) {
    if (manager) {
        free(manager->contexts);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
```

### Design Decisions and Assumptions

- **Concurrency**: The function uses a `pthread_mutex` to ensure thread-safe operations, preventing race conditions when multiple threads access or modify the context list concurrently.

- **Memory Management**: Dynamic memory allocation is used for managing the UE contexts. The `calloc` ensures that all entries are initialized to zero.

- **Logging**: A simple logging mechanism based on log levels allows adjusting verbosity. Performance considerations have been made by ensuring logging only occurs when necessary (i.e., matching the current log level).

- **Error Handling**: Functions return error codes for invalid operations, like exceeding max entries or duplicate transaction IDs.

- **Extensibility**: The function is designed to be extensible with minimal changes, allowing integration with external systems through additional functions or modifying existing structures.

- **Assumptions**: It assumes that the maximum number of contexts (`max_entries`) fits in memory and that S-TMSI values are generated correctly from an external source. Future enhancements may include more sophisticated logging and error handling mechanisms, as well as improved performance optimizations for high-load scenarios.']

