    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->size = 0;
    da->capacity = 10; // Initial capacity
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->mutex, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}

int resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        return -1; // Memory allocation failure
    }
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

int add_element(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity) {
        if (resize_dynamic_array(da) != 0) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Memory allocation failure
        }
    }
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int update_element(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T new_value) {
    pthread_mutex_lock(&da->mutex);
    if (index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Invalid index
    }
    da->array[index] = new_value;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int get_element(DynamicArray *da, size_t index, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&da->mutex);
    if (index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Invalid index
    }
    *element = da->array[index];
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

// Example of updating CRCFLAG from an external data source
