void memory_pool_init(MemoryPool* mp, size_t pool_size) {
    mp->pool_size = pool_size;
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->free_index = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* memory_pool_allocate(MemoryPool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->free_index < mp->pool_size) {
        NFAPI_CRC_INDICATION_PDU_T* block = &mp->pool[mp->free_index++];
        pthread_mutex_unlock(&mp->lock);
        return block;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool exhausted
}

void memory_pool_free(MemoryPool* mp, NFAPI_CRC_INDICATION_PDU_T* block) {
    if (block >= mp->pool && block < (mp->pool + mp->free_index)) {
        size_t index = block - mp->pool;
        pthread_mutex_lock(&mp->lock);
        memmove(&mp->pool[index], &mp->pool[mp->free_index - 1], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        --mp->free_index;
        pthread_mutex_unlock(&mp->lock);
    }
}

