    if (!new_node) return;

    new_node->data = data;
    new_node->next = list->head;

    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    ++list->count;
    pthread_mutex_unlock(&list->lock);
}

void linked_list_free(LinkedList* list, MemoryPool* mp) {
    struct Node* current = list->head;
    while (current) {
        struct Node* next = current->next;
        memory_pool_free(mp, &current->data);
        free(current);
