#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    time_t timestamp;
    int unique_id;
    size_t payload_size;
} DataPacket;

typedef struct {
    DataPacket *packets;
    size_t capacity;
    pthread_mutex_t lock;
} PacketManager;

void initialize_packet_manager(PacketManager *manager, size_t capacity) {
    manager->packets = (DataPacket *)malloc(capacity * sizeof(DataPacket));
    if (!manager->packets) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->capacity = capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_packet_manager(PacketManager *manager) {
    free(manager->packets);
    pthread_mutex_destroy(&manager->lock);
}

int populate_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->packets[i].timestamp = time(NULL);
        manager->packets[i].unique_id = i + 1;
        // Simulate payload size within reasonable limits
        manager->packets[i].payload_size = (rand() % MAX_PAYLOAD_SIZE) + 1;
    }

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int validate_packet(const DataPacket *packet) {
    if (!packet) return -1;
    // Validate timestamp and payload size
    if (difftime(time(NULL), packet->timestamp) > 60 || packet->payload_size == 0)
        return -1;
    return 0;
}

void handle_packets(PacketManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->capacity; ++i) {
        if (validate_packet(&manager->packets[i]) == 0) {
            printf("Packet %d: Timestamp=%ld, PayloadSize=%zu\n", 
                   manager->packets[i].unique_id, 
                   manager->packets[i].timestamp, 
                   manager->packets[i].payload_size);
        } else {
            fprintf(stderr, "Invalid packet detected!\n");
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    PacketManager manager;
    size_t capacity = 100;

    initialize_packet_manager(&manager, capacity);
    populate_packets(&manager);
    handle_packets(&manager);

    free_packet_manager(&manager);
    return 0;
}
```

