            return 0;
        }
    }

    if (pdu_array->size >= pdu_array->capacity) {
        size_t new_capacity = pdu_array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* resized_array = realloc(pdu_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!resized_array) return -1;

        pdu_array->array = resized_array;
        pdu_array->capacity = new_capacity;
    }

    pdu_array->array[pdu_array->size++] = new_pdu;
    fprintf(log_file, "Added PDU with RNTI: %lu\n", new_pdu.RNTI);
    return 0;
