    newNode->data = *pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&buf->lock);

    if (buf->count >= MAX_BUFFER_SIZE) {
        // Remove the oldest entry
        Node* temp = buf->head;
        buf->head = buf->head->next;
        free(temp);
        buf->count--;
    }

    if (!buf->head) {
        buf->head = buf->tail = newNode;
    } else {
        buf->tail->next = newNode;
        buf->tail = newNode;
    }
    buf->count++;

