#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

// Define the structure as specified
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Dynamic array structure
typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t mutex;
} CRCArray;

// Function prototypes
void init_crc_array(CRCArray* array);
void destroy_crc_array(CRCArray* array);
int add_pdu(CRCArray* array, const NFAPI_CRC_INDICATION_PDU_T* pdu);
int update_pdu(CRCArray* array, uint16_t rnti, const NFAPI_CRC_INDICATION_PDU_T* pdu);
void iterate_and_process(CRCArray* array, void (*func)(NFAPI_CRC_INDICATION_PDU_T*));

// Initialize the dynamic array
void init_crc_array(CRCArray* array) {
    array->head = NULL;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

// Destroy the dynamic array and free resources
void destroy_crc_array(CRCArray* array) {
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->mutex);
}

// Add a new PDU to the array
int add_pdu(CRCArray* array, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failure

    memcpy(&newNode->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = NULL;

    pthread_mutex_lock(&array->mutex);
    newNode->next = array->head;
    array->head = newNode;
    array->count++;
    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
}

// Update an existing PDU by RNTI
int update_pdu(CRCArray* array, uint16_t rnti, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return -1;

    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            memcpy(&current->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&array->mutex);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);

    return -1; // PDU not found
}

// Iterate over the array and apply a function to each element
void iterate_and_process(CRCArray* array, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!func) return;

    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    while (current != NULL) {
        func(&current->data);
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

// Example processing function
void example_processing(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    // Randomly set CRCFLAG for demonstration
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    printf("Processing PDU with RNTI: %u, CRCFLAG: %d\n",
           pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

// Main function for demonstration purposes
int main() {
    srand((unsigned)time(NULL)); // Seed the random number generator

    CRCArray array;
    init_crc_array(&array);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100 };
    add_pdu(&array, &pdu1);

    iterate_and_process(&array, example_processing);

    destroy_crc_array(&array);
    return 0;
}
