typedef struct Node {
    PHY_RX_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock;
} Buffer;

void initBuffer(Buffer* buffer) {
    buffer->head = NULL;
    buffer->tail = NULL;
    buffer->count = 0;
    pthread_mutex_init(&buffer->lock, NULL);
}

void destroyBuffer(Buffer* buffer) {
    Node* current = buffer->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&buffer->lock);
}

int addData(Buffer* buffer, PHY_RX_INDICATION_PDU_T data) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->count == MAX_BUFFER_SIZE) {
        Node* temp = buffer->head;
        buffer->head = buffer->head->next;
        free(temp);
        buffer->count--;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&buffer->lock);
        return -1; // Memory allocation failed
    }

    newNode->data = data;
    newNode->next = NULL;

    if (buffer->tail != NULL) {
        buffer->tail->next = newNode;
    } else {
        buffer->head = newNode;
    }

    buffer->tail = newNode;
    buffer->count++;

    pthread_mutex_unlock(&buffer->lock);
    return 0; // Success
}

PHY_RX_INDICATION_PDU_T createPDU() {
    PHY_RX_INDICATION_PDU_T pdu;

    // Simulate fetching LTE information
    pdu.RX_LTE_INFORMATION_TAG = rand() % 1000;

    // Simulate SINR value
    pdu.SINR = (float)(rand() % 100) / 10.0;

    // Randomly set BERFLAG
    pdu.BER_REL8_TAG.BERFLAG = rand() & 1;

    return pdu;
}

void manageDynamicList(Buffer* buffer, size_t M) {
    for (size_t i = 0; i < M; ++i) {
        PHY_RX_INDICATION_PDU_T pdu = createPDU();
        if (addData(buffer, pdu) != 0) {
            fprintf(stderr, "Failed to add data due to memory allocation error.\n");
            break;
        }
    }
}

int main() {
    srand(time(NULL));

    Buffer buffer;
    initBuffer(&buffer);

    size_t M = 2000; // Example large number
    manageDynamicList(&buffer, M);

    destroyBuffer(&buffer);
    return 0;
}
