#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure representing a simplified version of a TCP packet header.
typedef struct {
    char sourceIP[16];  // IPv4 addresses are represented as strings, e.g., "192.168.1.1"
    char destIP[16];
    unsigned short srcPort;
    unsigned short destPort;
    unsigned char protocolType;  // Typically an integer representing the protocol (e.g., TCP = 6)
    unsigned short checksum;     // Checksum for error-checking purposes
} TCPPacketHeader;

// Function to compute the checksum of the packet header.
unsigned short calculateChecksum(TCPPacketHeader *header, size_t headerSize) {
    unsigned long sum = 0;

    // Process each byte pair in the header
    char *ptr = (char *)header;
    for (size_t i = 0; i < headerSize; i += 2) {
        unsigned short word = (i + 1 < headerSize) ? ((unsigned short)(ptr[i]) << 8 | ptr[i + 1]) : (unsigned short)(ptr[i]) << 8;
        sum += word;
    }

    // Wrap around the carry bits
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }

    // One's complement of the sum
    return ~((unsigned short)(sum));
}

// Function to initialize and populate a dynamically allocated array of TCP packet headers.
TCPPacketHeader* initTCPHeaders(size_t count, size_t headerSize, unsigned short protocolType) {
    if (count == 0 || headerSize < sizeof(TCPPacketHeader)) {
        return NULL;  // Invalid input
    }

    TCPPacketHeader *headers = (TCPPacketHeader *)malloc(count * headerSize);
    if (!headers) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    memset(headers, 0, count * headerSize);

    for (size_t i = 0; i < count; ++i) {
        // Simulate IP address retrieval with potential delays or failures
        snprintf(headers[i].sourceIP, sizeof(headers[i].sourceIP), "192.168.%zu.%zu", i / 256 + 1, i % 256);
        snprintf(headers[i].destIP, sizeof(headers[i].destIP), "10.0.%zu.%zu", i / 256, i % 256);

        headers[i].srcPort = rand() % 65536;
        headers[i].destPort = rand() % 65536;
        headers[i].protocolType = protocolType;

        // Calculate and store checksum
        headers[i].checksum = calculateChecksum(&headers[i], sizeof(TCPPacketHeader));
    }

    return headers;
}

// Function to free the dynamically allocated array of TCP packet headers.
void freeTCPHeaders(TCPPacketHeader *headers) {
    if (headers) {
        free(headers);
    }
}

int main() {
    size_t numPackets = 10; // Number of packets
    TCPPacketHeader* packetHeaders = initTCPHeaders(numPackets, sizeof(TCPPacketHeader), 6);

    // Example usage: print the headers
    for (size_t i = 0; i < numPackets; ++i) {
        printf("Packet %zu: SrcIP: %s, DestIP: %s, SrcPort: %hu, DestPort: %hu, Protocol: %hhu, Checksum: %hu\n",
            i, packetHeaders[i].sourceIP, packetHeaders[i].destIP,
            packetHeaders[i].srcPort, packetHeaders[i].destPort,
            packetHeaders[i].protocolType, packetHeaders[i].checksum);
    }

    freeTCPHeaders(packetHeaders);
    return 0;
}
