    if (total_memory_usage > MAX_MEMORY_USAGE) {
        log_message("Memory limit exceeded. Cannot allocate more requests.");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    char *request_copy = strdup(raw_request); // Duplicate request for safer processing
