        strcpy(new_request->query_params, query_pos + 1);
    } else {
        new_request->query_params[0] = '\0';
    }
    strncpy(new_request->headers, request_copy, header_length);
    new_request->body_length = body_start ? strlen(body_start + strlen(delimiter)) : 0;

    free(request_copy);
    (*num_requests)++;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to free allocated memory for requests
void cleanup_http_requests(HttpRequest **requests, int num_requests) {
    if (requests && *requests) {
        free(*requests);
        *requests = NULL;
    }
}

int main() {
    const char *raw_request1 = "GET /index.html?user=123 HTTP/1.1\r\nHost: example.com\r\n\r\n";
    const char *raw_request2 = "POST /submit HTTP/1.1\r\nHost: example.com\r\nContent-Length: 11\r\n\r\nHello World";

    HttpRequest *requests = NULL;
    int num_requests = 0;

    if (parse_http_request(raw_request1, &requests, &num_requests) == 0) {
        printf("Parsed request 1:\nMethod: %s\nURL Path: %s\nQuery Params: %s\nBody Length: %zu\n",
               requests[0].method, requests[0].url_path, requests[0].query_params, requests[0].body_length);
    }

    if (parse_http_request(raw_request2, &requests, &num_requests) == 0) {
        printf("Parsed request 2:\nMethod: %s\nURL Path: %s\nQuery Params: %s\nBody Length: %zu\n",
               requests[1].method, requests[1].url_path, requests[1].query_params, requests[1].body_length);
    }

    cleanup_http_requests(&requests, num_requests);

    return 0;
}
