#include <string.h>

// Define the structure for a simplified TCP packet header.
typedef struct {
    unsigned int src_ip;      // Source IP address (as integer for simplicity)
    unsigned int dest_ip;     // Destination IP address (as integer for simplicity)
    unsigned short src_port;
    unsigned short dest_port;
    unsigned char protocol_type;  // Protocol type
    unsigned short checksum;      // Checksum of the header
} TCP_Packet_Header;

// Function prototypes
unsigned short compute_checksum(TCP_Packet_Header *header, size_t length);
void free_packet_header(TCP_Packet_Header *header);

// Main function to initialize and populate the packet header
TCP_Packet_Header* init_tcp_packet_header(unsigned int src_ip,
                                          unsigned int dest_ip,
                                          unsigned short src_port,
                                          unsigned short dest_port,
                                          unsigned char protocol_type) {
    TCP_Packet_Header *header = (TCP_Packet_Header *)malloc(sizeof(TCP_Packet_Header));
    if (!header) {
        perror("Failed to allocate memory for TCP packet header");
        return NULL;
    }

    // Populate the header
    header->src_ip = src_ip;
    header->dest_ip = dest_ip;
    header->src_port = htons(src_port);
    header->dest_port = htons(dest_port);
    header->protocol_type = protocol_type;

    // Compute checksum and populate it in the header
    size_t length = sizeof(TCP_Packet_Header) - sizeof(header->checksum);  // Excluding checksum field
    header->checksum = compute_checksum(header, length);

    return header;
}

// Function to compute a simple checksum for demonstration purposes.
unsigned short compute_checksum(TCP_Packet_Header *header, size_t length) {
    unsigned long sum = 0;

    // Convert the struct into an array of bytes and calculate the checksum
    unsigned char *byte_array = (unsigned char *)header;

    for (size_t i = 0; i < length; i += 2) {
        if (i + 1 < length) {
            // Combine two adjacent bytes to form a 16-bit word
            unsigned short word = (byte_array[i] << 8) | byte_array[i + 1];
            sum += word;
        } else {
            // In case of odd length, pad the last byte with zero
            sum += byte_array[i] << 8;
        }
    }

    // Add carry if any
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }

    // One's complement of sum
    return ~((unsigned short)(sum & 0xFFFF));
}

// Function to free allocated memory for the packet header
void free_packet_header(TCP_Packet_Header *header) {
    if (header != NULL) {
        free(header);
    }
}
```

### Explanation:
- **Structure Definition**: A `TCP_Packet_Header` structure is defined with fields for source and destination IP addresses, port numbers, protocol type, and checksum.

- **Initialization Function**: `init_tcp_packet_header` initializes a dynamically allocated `TCP_Packet_Header`. It populates the header's fields and computes its checksum using `compute_checksum`.

- **Checksum Calculation**: The checksum is calculated by iterating over the header bytes in 16-bit chunks. If there's an odd number of bytes, the last byte is padded with zero. Overflow is handled by adding carry bits back into the sum.

- **Memory Management**: Memory allocation and deallocation are handled using `malloc` and `free`. Error handling includes checking for successful memory allocation.

This code provides a foundation that can be extended to handle more complex scenarios such as IP address format changes, caching mechanisms, or integration with other network libraries.']

