// Assuming definitions for these types are available elsewhere.
typedef struct {
    uint16_t RNTI;
} RX_UE_INFORMATION_TAG_T;

typedef struct {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    RX_UE_INFORMATION_TAG_T ue_info_tag;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MIN_RNTI 0x0001
#define MAX_RNTI 0xFFFF

// Global variables for dynamic rate limiting.
static volatile int creation_rate_limit = 100; // Default max structures per second
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void adjust_creation_rate(int cpu_usage, int memory_usage) {
    pthread_mutex_lock(&mutex);
    if (cpu_usage > 80 || memory_usage > 80) {
        creation_rate_limit = creation_rate_limit / 2; // Halve the rate under high load
    } else if (creation_rate_limit < 1000) { 
        creation_rate_limit += 10; // Gradually increase under low load, up to a max
    }
    pthread_mutex_unlock(&mutex);
}

bool is_valid_rnti(uint16_t rnti) {
    return (rnti >= MIN_RNTI && rnti <= MAX_RNTI);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_pdu(int count, int cpu_usage, int memory_usage) {
    pthread_mutex_lock(&mutex);
    adjust_creation_rate(cpu_usage, memory_usage);

    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    if (!pdus) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (int i = 0; i < count && creation_rate_limit > 0; ++i) {
        pdus[i].ue_info_tag.RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;

        if (!is_valid_rnti(pdus[i].ue_info_tag.RNTI)) {
            fprintf(stderr, "Invalid RNTI value: %u\n", pdus[i].ue_info_tag.RNTI);
            free(pdus);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }

        pdus[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2 == 0;

        // Simulate creation rate limiting
        if (creation_rate_limit-- <= 0) {
            sleep(1); // Sleep for a second to control the rate
            pthread_cond_wait(&cond_var, &mutex);
            adjust_creation_rate(cpu_usage, memory_usage);
            creation_rate_limit = 100; // Reset rate limit after waiting
        }
    }

    pthread_mutex_unlock(&mutex);
    return pdus;
}

void release_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus) {
        free(pdus);
    }
}
