using System;
using System.Collections.Generic;
using UnityEngine;

public enum DistributionType
{
    Uniform,
    Gaussian
}

public class DynamicValueManager
{
    private float minValue;
    private float maxValue;
    private HashSet<float> uniqueFloatValues = new HashSet<float>();
    private HashSet<int> uniqueIntValues = new HashSet<int>();

    private System.Random random = new System.Random();

    public DistributionType Distribution { get; set; } = DistributionType.Uniform;

    // Constructor to initialize the range
    public DynamicValueManager(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");

        minValue = min;
        maxValue = max;
    }

    // Generate a unique random float within the specified range
    public float GetUniqueRandomFloat()
    {
        float result;
        do
        {
            result = Distribution switch
            {
                DistributionType.Uniform => UnityEngine.Random.Range(minValue, maxValue),
                DistributionType.Gaussian => GaussianDistribution(),
                _ => throw new NotSupportedException("Unsupported distribution type.")
            };
        } while (!uniqueFloatValues.Add(result));

        return result;
    }

    // Generate a unique random integer within the specified range
    public int GetUniqueRandomInt()
    {
        int result;
        do
        {
            result = (int)Distribution switch
            {
                DistributionType.Uniform => UnityEngine.Random.Range((int)minValue, (int)maxValue),
                DistributionType.Gaussian => (int)GaussianDistribution(),
                _ => throw new NotSupportedException("Unsupported distribution type.")
            };
        } while (!uniqueIntValues.Add(result));

        return result;
    }

    // Generate a sequence of n unique random values within the range
    public float[] GetUniqueRandomFloats(int count)
    {
        if (count > (maxValue - minValue) * 10000)
            throw new ArgumentException("The requested number of unique floats is too large.");

        var results = new List<float>();
        while (results.Count < count)
        {
            var value = Distribution switch
            {
                DistributionType.Uniform => UnityEngine.Random.Range(minValue, maxValue),
                DistributionType.Gaussian => GaussianDistribution(),
                _ => throw new NotSupportedException("Unsupported distribution type.")
            };

            if (uniqueFloatValues.Add(value))
                results.Add(value);
        }

        return results.ToArray();
    }

    // Generate a sequence of n unique random integers within the range
    public int[] GetUniqueRandomInts(int count)
    {
        if (count > (maxValue - minValue) * 10000)
            throw new ArgumentException("The requested number of unique ints is too large.");

        var results = new List<int>();
        while (results.Count < count)
        {
            var value = (int)(Distribution switch
            {
                DistributionType.Uniform => UnityEngine.Random.Range((int)minValue, (int)maxValue),
                DistributionType.Gaussian => GaussianDistribution(),
                _ => throw new NotSupportedException("Unsupported distribution type.")
            });

            if (uniqueIntValues.Add(value))
                results.Add(value);
        }

        return results.ToArray();
    }

    // Calculate a value based on Gaussian distribution
    private float GaussianDistribution()
    {
        var u1 = 1f - random.NextDouble(); // Uniform(0,1] random doubles
        var u2 = 1f - random.NextDouble();
        var randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2); // Random normal(0,1)
        float mean = (float)((minValue + maxValue) / 2);
        float stdDeviation = (float)(maxValue - minValue) / 6; // Approximation for 99.7% within the range
        return mean + stdDeviation * randStdNormal;
    }
}
```

This implementation provides a class `DynamicValueManager` that manages numeric ranges, supports unique value generation, and handles different distribution types like uniform and Gaussian. The code is designed to integrate with Unity's systems (using `UnityEngine.Random`) for compatibility within game development environments while minimizing performance impact by efficiently managing uniqueness using hash sets. Additional distribution types can be added by extending the enumeration and adding logic accordingly.']

