// Define constants for connection states
#define CONNECTED 0
#define DISCONNECTED 1

typedef struct {
    char client_ip[16];
    char server_ip[16];
    int state;
    time_t timestamp;
} TCP_CONNECTION_RECORD;

typedef struct Node {
    TCP_CONNECTION_RECORD data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConnectionList;

// Function to initialize the connection list
ConnectionList* init_connection_list() {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Helper function to create a new node
Node* create_node(const char* client_ip, const char* server_ip, int state) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    strncpy(new_node->data.client_ip, client_ip, 15);
    new_node->data.client_ip[15] = '\0';

    strncpy(new_node->data.server_ip, server_ip, 15);
    new_node->data.server_ip[15] = '\0';

    new_node->data.state = state;
    new_node->data.timestamp = time(NULL);

    new_node->next = NULL;
    return new_node;
}

// Function to add a connection record
void add_connection(ConnectionList* list, const char* client_ip, const char* server_ip) {
    if (!list) return;

    Node* new_node = create_node(client_ip, server_ip, CONNECTED);
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new connection record\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    // Insert at the head of the list
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Function to remove a connection by client IP
void remove_connection(ConnectionList* list, const char* client_ip) {
    if (!list || !client_ip) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    Node *previous = NULL;

    while (current != NULL && strcmp(current->data.client_ip, client_ip) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Not found
    }

    if (previous == NULL) {
        list->head = current->next; // Remove head
    } else {
        previous->next = current->next; // Bypass the node to remove
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
}

// Function to clean up the connection list and free memory
void cleanup_connection_list(ConnectionList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example logging function
void log_operation(const char* operation) {
    printf("Operation: %s\n", operation);
}

