#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure as per the given requirement
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // 0 or 1, for simplicity we use an integer
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array structure with mutex for concurrency control
typedef struct {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *array;
    pthread_mutex_t lock;  // Mutex to protect access
} DynamicArray;

// Function to initialize the dynamic array
int init_dynamic_array(DynamicArray *dyn_array, size_t initial_capacity) {
    dyn_array->capacity = initial_capacity;
    dyn_array->count = 0;
    dyn_array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dyn_array->array) return -1; // Memory allocation failure
    pthread_mutex_init(&dyn_array->lock, NULL);
    return 0;
}

// Function to resize the dynamic array
int resize_dynamic_array(DynamicArray *dyn_array, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(dyn_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1; // Memory allocation failure
    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;
    return 0;
}

// Function to free resources associated with the dynamic array
void destroy_dynamic_array(DynamicArray *dyn_array) {
    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array->array);
}

// Thread-safe function to populate the dynamic array with N unique instances
int populate_dynamic_array(DynamicArray *dyn_array, size_t N) {
    if (N == 0 || dyn_array->count != 0) return -1; // Invalid input or already populated

    pthread_mutex_lock(&dyn_array->lock);

    for (size_t i = 0; i < N; ++i) {
        if (dyn_array->count >= dyn_array->capacity) { 
            size_t new_capacity = dyn_array->capacity * 2;
            if (resize_dynamic_array(dyn_array, new_capacity)) {
                pthread_mutex_unlock(&dyn_array->lock);
                return -1; // Memory allocation failure
            }
        }

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 0xFFFF; // Random valid tag
        pdu.RNTI = rand() % 0xFFFF; // Random valid RNTI

        // Ensure CRCFLAG is not same as previous packet's (if exists)
        int crcflag = rand() % 2;
        if (i > 0) {
            while (dyn_array->array[i - 1].CRC_INDICATION_REL8_TAG.CRCFLAG == crcflag) {
                crcflag = rand() % 2;
            }
        }
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag;

        dyn_array->array[dyn_array->count++] = pdu;
    }

    pthread_mutex_unlock(&dyn_array->lock);
    return 0; // Success
}

// Example usage of the dynamic array with NFAPI_CRC_INDICATION_PDU_T structures
int main() {
    size_t initial_capacity = 10;
    DynamicArray dyn_array;

    if (init_dynamic_array(&dyn_array, initial_capacity)) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return -1;
    }

    size_t N = 20; // Number of instances to populate
    if (populate_dynamic_array(&dyn_array, N)) {
        fprintf(stderr, "Failed to populate dynamic array\n");
        destroy_dynamic_array(&dyn_array);
        return -1;
    }

    // Output populated data for verification
    for (size_t i = 0; i < dyn_array.count; ++i) {
        printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n", 
               dyn_array.array[i].RX_UE_INFORMATION_TAG, 
               dyn_array.array[i].RNTI, 
               dyn_array.array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    destroy_dynamic_array(&dyn_array);
    return 0;
}
