static int global_enable_logging = 0;

void set_logging(int enable) {
    global_enable_logging = enable;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_entry(int rnti, int enable_logging) {
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    entry->RX_UE_INFORMATION_TAG = rand() % 1000; // Simulating random RX tag
    entry->RNTI = rnti;
    entry->CRC_INDICATION_REL8_TAG = rand() % 1000; // Simulating random CRC tag
    entry->CRCFLAG = rand() & 1; // Randomly set to 0 or 1

    if (enable_logging) {
        printf("Added Entry - RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG, entry->CRCFLAG);
    }

    return entry;
}

int add_entry(NFAPI_CRC_INDICATION_PDU_T **entries, int *entry_count, int rnti, int enable_logging) {
    if (*entry_count >= MAX_ENTRIES) {
        fprintf(stderr, "Maximum entries reached\n");
        return -1;
    }

    // Check for duplicate RNTI
    for (int i = 0; i < *entry_count; i++) {
        if ((*entries)[i].RNTI == rnti) {
            if (enable_logging) {
                printf("Duplicate RNTI found: %d\n", rnti);
            }
            return -2;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = create_nfaapi_entry(rnti, enable_logging);
    if (!new_entry) {
        return -3; // Memory allocation failed
    }

    *entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(*entries, (*entry_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*entries) {
        free(new_entry);
        fprintf(stderr, "Memory reallocation failed\n");
        return -4;
    }

    (*entries)[*entry_count] = *new_entry;
    (*entry_count)++;
    return 0;
}

void free_entries(NFAPI_CRC_INDICATION_PDU_T *entries) {
    if (entries) {
        free(entries);
    }
}

int validate_crcflags(NFAPI_CRC_INDICATION_PDU_T *entries, int entry_count) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].CRCFLAG != 0 && entries[i].CRCFLAG != 1) {
            fprintf(stderr, "Invalid CRCFLAG value detected at index %d\n", i);
            return -1;
        }
    }
    return 0;
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    NFAPI_CRC_INDICATION_PDU_T *entries = NULL;
    int entry_count = 0;

    set_logging(1); // Enable logging

    // Example usage
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (add_entry(&entries, &entry_count, rand() % 10000, global_enable_logging) != 0) {
            break;
        }
    }

    int validation_status = validate_crcflags(entries, entry_count);
    if (validation_status == 0 && global_enable_logging) {
        printf("All CRCFLAG values are valid.\n");
    } else {
        fprintf(stderr, "CRCFLAG validation failed with status: %d\n", validation_status);
    }

    free_entries(entries);

    return 0;
}
