#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define INITIAL_SIZE 10

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    uint16_t SN;
    CRC_INDICATION_REL8_TAG_T REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* init_dynamic_array() {
    DynamicArray *arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) return NULL;

    arr->size = INITIAL_SIZE;
    arr->used = 0;
    arr->array = malloc(arr->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) {
        free(arr);
        return NULL;
    }
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

bool resize_dynamic_array(DynamicArray *arr) {
    size_t newSize = arr->size * 2;
    NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(arr->array, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) return false;

    arr->array = newArray;
    arr->size = newSize;
    return true;
}

bool append_to_dynamic_array(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&arr->lock);

    if (arr->used == arr->size && !resize_dynamic_array(arr)) {
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    arr->array[arr->used++] = item;
    pthread_mutex_unlock(&arr->lock);
    return true;
}

bool populate_with_unique_instances(DynamicArray *arr, size_t N) {
    if (!arr || N == 0) return false;

    bool lastCRCFLAG = false;
    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.SN = i + 1;
        pdu.REL8_TAG.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.REL8_TAG.RNTI = rand() % 1000000;

        // Ensure no two consecutive CRCFLAGS are the same
        bool currentCRCFLAG = rand() % 2;
        while (currentCRCFLAG == lastCRCFLAG) {
            currentCRCFLAG = rand() % 2;
        }
        pdu.REL8_TAG.CRCFLAG = currentCRCFLAG;
        lastCRCFLAG = currentCRCFLAG;

        if (!append_to_dynamic_array(arr, pdu)) {
            return false;
        }
    }
    return true;
}

bool serialize_to_file(DynamicArray *arr, const char* filename) {
    pthread_mutex_lock(&arr->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    fwrite(&arr->used, sizeof(size_t), 1, file);
    fwrite(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), arr->used, file);

    fclose(file);
    pthread_mutex_unlock(&arr->lock);
    return true;
}

bool deserialize_from_file(DynamicArray *arr, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return false;

    size_t newUsed;
    fread(&newUsed, sizeof(size_t), 1, file);

    pthread_mutex_lock(&arr->lock);
    NFAPI_CRC_INDICATION_PDU_T *newArray = realloc(arr->array, newUsed * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newArray) {
        fclose(file);
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    arr->array = newArray;
    fread(arr->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), newUsed, file);

    if (ferror(file)) {
        free(arr->array);
        arr->array = NULL;
        arr->size = 0;
        arr->used = 0;
        pthread_mutex_unlock(&arr->lock);
        fclose(file);
        fprintf(stderr, "Deserialization error: data inconsistency detected.\n");
        return false;
    }

    arr->used = newUsed;
    arr->size = newUsed; // Adjust size to match used
    pthread_mutex_unlock(&arr->lock);

    fclose(file);
    return true;
}

void free_dynamic_array(DynamicArray *arr) {
    if (arr) {
        pthread_mutex_lock(&arr->lock);
        free(arr->array);
        pthread_mutex_unlock(&arr->lock);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

// Unit tests
#include <assert.h>

void test_dynamic_array() {
    DynamicArray *arr = init_dynamic_array();
    assert(arr != NULL);

    size_t N = 20;
    assert(populate_with_unique_instances(arr, N) == true);
    assert(arr->used == N);

    const char* filename = "test_data.bin";
    assert(serialize_to_file(arr, filename) == true);

    DynamicArray *new_arr = init_dynamic_array();
    assert(deserialize_from_file(new_arr, filename) == true);
    assert(new_arr->used == N);

    // Check for data integrity
    for (size_t i = 0; i < N; ++i) {
        assert(arr->array[i].SN == new_arr->array[i].SN);
        assert(arr->array[i].REL8_TAG.RX_UE_INFORMATION_TAG == new_arr->array[i].REL8_TAG.RX_UE_INFORMATION_TAG);
        assert(arr->array[i].REL8_TAG.RNTI == new_arr->array[i].REL8_TAG.RNTI);
        assert(arr->array[i].REL8_TAG.CRCFLAG == new_arr->array[i].REL8_TAG.CRCFLAG);
    }

    free_dynamic_array(arr);
    free_dynamic_array(new_arr);
}

int main() {
    test_dynamic_array();
    printf("All tests passed.\n");
    return 0;
}
