import React, { useState, useEffect } from 'react';

const fetchValidationRules = async (url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error('Network response was not ok');
    return await response.json();
  } catch (error) {
    console.error('Failed to fetch validation rules:', error);
    return null;
  }
};

const validateField = (fieldValue, rules) => {
  // Implement specific validation logic based on rules
  if (rules.required && !fieldValue.trim()) return 'This field is required';
  if (rules.minLength && fieldValue.length < rules.minLength)
    return `Minimum length is ${rules.minLength}`;
  // Add more validations as needed
  return null;
};

const useFormFields = ({ formId, formUrl }) => {
  const [fields, setFields] = useState({});
  const [validationRules, setValidationRules] = useState({});
  const [errors, setErrors] = useState({});

  useEffect(() => {
    const fetchAndSetRules = async () => {
      const rules = await fetchValidationRules(formUrl);
      if (rules) setValidationRules(rules);
    };
    fetchAndSetRules();
  }, [formUrl]);

  const handleFieldChange = (fieldId, value) => {
    const fieldConfig = validationRules[fieldId] || {};

    // Validate the field
    const error = validateField(value, fieldConfig);

    // Update state for fields and errors
    setFields((prevFields) => ({ ...prevFields, [fieldId]: value }));
    setErrors((prevErrors) => ({ ...prevErrors, [fieldId]: error }));

    // Additional logic can be added here to trigger external services or actions
  };

  const handleSubmit = () => {
    let isValid = true;
    Object.keys(fields).forEach(fieldId => {
      const fieldConfig = validationRules[fieldId] || {};
      const error = validateField(fields[fieldId], fieldConfig);
      if (error) {
        setErrors((prevErrors) => ({ ...prevErrors, [fieldId]: error }));
        isValid = false;
      } else {
        setErrors((prevErrors) => ({
          ...prevErrors,
          [fieldId]: null
        }));
      }
    });

    if (isValid) {
      console.log('Form is valid. Submitting...', fields);
      // Implement form submission logic here
    }
  };

  return { handleFieldChange, handleSubmit, fields, errors };
};

export default useFormFields;
```

### Usage Example in a Component

```javascript
import React from 'react';
import useFormFields from './useFormFields';

const FormComponent = ({ formId, formUrl }) => {
  const { handleFieldChange, handleSubmit, fields, errors } = useFormFields({ formId, formUrl });

  return (
    <form onSubmit={(e) => {
      e.preventDefault();
      handleSubmit();
    }}>
      <input
        type="text"
        value={fields['field1'] || ''}
        onChange={(e) => handleFieldChange('field1', e.target.value)}
        placeholder="Field 1"
      />
      {errors['field1'] && <p>{errors['field1']}</p>}

      <button type="submit">Submit</button>
    </form>
  );
};

export default FormComponent;
```

This implementation provides a modular, reusable `useFormFields` hook that handles form field updates, validation, and submission within a React application. It efficiently integrates with an external data source for fetching dynamic validation rules while ensuring maintainability and scalability.']

