    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(pdu_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array != NULL) {
        pdu_array = new_array;
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&array_mutex);
}

// Function to add an NFAPI_CRC_INDICATION_PDU_T structure
void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array_mutex);

    if (size >= capacity) {
        resize_pdu_array(capacity == 0 ? 1 : capacity * 2);
    }

    // Add the new structure to the array
    pdu_array[size++] = pdu;

    pthread_mutex_unlock(&array_mutex);
}

// Function to populate the dynamic array with at least N unique instances
void populate_pdu_array(size_t N) {
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate random RX_UE_INFORMATION_TAG and RNTI
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
        pdu.RNTI = rand() % 1000 + 1;

        // Ensure alternating CRCFLAG values
        if (i > 0) {
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = !pdu_array[i - 1].CRC_INDICATION_REL8_TAG.CRCFLAG;
        } else {
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }

        add_pdu(pdu);
    }
}

// Function to load cryptographic primitives dynamically
void load_crypto_primitives() {
    const EVP_CIPHER *aes_cipher = EVP_aes_256_cbc();
    const EVP_CIPHER *camellia_cipher = EVP_camellia_256_cbc();
    const EVP_MD *sha256_md = EVP_sha256();
    const EVP_PKEY_METHOD *rsa_method = EVP_pkey_meth_find(EVP_PKEY_RSA);

    if (!aes_cipher || !camellia_cipher || !sha256_md || !rsa_method) {
        fprintf(stderr, "Error loading cryptographic primitives.\n");
        exit(EXIT_FAILURE);
    }

    // Further initialization and configuration can be done here
}

// Main function for testing the implementation
int main() {
    populate_pdu_array(10); // Example usage with N=10

    // Print the populated array for demonstration purposes
    pthread_mutex_lock(&array_mutex);
    for (size_t i = 0; i < size; ++i) {
        printf("TX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               pdu_array[i].RX_UE_INFORMATION_TAG,
               pdu_array[i].RNTI,
               pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
    pthread_mutex_unlock(&array_mutex);

    load_crypto_primitives();

    // Cleanup
    free(pdu_array);
    return 0;
}
```

### Key Points:
- **Concurrency Control**: Mutex is used to ensure thread safety when accessing the dynamic array.
- **Dynamic Array Management**: The array resizes dynamically, doubling its capacity as needed. This minimizes reallocations and manages memory efficiently.
- **Cryptographic Primitives Loading**: Uses OpenSSL's EVP interface to load AES, Camellia, SHA256, and RSA primitives, with error checking for robustness.
- **Memory Management**: Proper allocation (`malloc`) and deallocation (`free`) of the array is handled to prevent leaks.
- **Thread Safety**: The implementation ensures operations on shared data (the dynamic array) are safe in a multi-threaded context using mutex locks.

This code serves as a foundation, and additional error handling or optimizations can be incorporated depending on specific system requirements.']

