bool is_frame_type_supported(FrameType type, const FrameType* types, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (types[i] == type) {
            return true;
        }
    }
    return false;
}

// Dynamic array structure to hold frames
typedef struct {
    FrameHeader* frames;
    size_t capacity;
    size_t count;
} FrameArray;

FrameArray* create_frame_array(size_t initial_capacity) {
    FrameArray* array = malloc(sizeof(FrameArray));
    array->frames = malloc(sizeof(FrameHeader) * initial_capacity);
    array->capacity = initial_capacity;
    array->count = 0;
    return array;
}

void destroy_frame_array(FrameArray* array) {
    free(array->frames);
    free(array);
}

bool add_frame(FrameArray* array, const FrameHeader* frame,
               const MACAddress* allowed_macs, size_t mac_count,
               const FrameType* supported_types, size_t type_count) {

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        FrameHeader* new_frames = realloc(array->frames, sizeof(FrameHeader) * new_capacity);
        if (!new_frames) return false; // Memory allocation failed
        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    // Check for duplicates
    for (size_t i = 0; i < array->count; ++i) {
        if (memcmp(&array->frames[i].SourceMACAddress, &frame->SourceMACAddress, sizeof(MACAddress)) == 0 &&
            array->frames[i].Timestamp == frame->Timestamp &&
            array->frames[i].FrameType == frame->FrameType) {
            return false; // Duplicate found
        }
    }

    if (!validate_mac_address(&frame->SourceMACAddress) ||
        !is_mac_address_allowed(&frame->SourceMACAddress, allowed_macs, mac_count) ||
        !is_frame_type_supported(frame->FrameType, supported_types, type_count)) {
        return false; // Validation failed
    }

    array->frames[array->count++] = *frame;
    return true;
}

void initialize_frames(FrameArray** frame_array,
                       const MACAddress* allowed_macs, size_t mac_count,
                       const FrameType* supported_types, size_t type_count) {

    if (!frame_array || !allowed_macs || !supported_types) {
        fprintf(stderr, "Invalid arguments to initialize_frames\n");
        return;
