class ScriptLoader {
    constructor(apiUrl) {
        this.apiUrl = apiUrl;
        this.scriptCache = new Map();
    }

    async fetchConfiguration() {
        try {
            const response = await fetch(this.apiUrl);
            if (!response.ok) throw new Error('Network response was not ok');
            return response.json();
        } catch (error) {
            console.error('Failed to fetch configuration:', error);
            this.retryWithBackoff(() => this.fetchConfiguration());
        }
    }

    async loadAndExecutePrimaryScript(url) {
        try {
            const scriptContent = await this.loadScriptContent(url);
            if (scriptContent) {
                new Function(scriptContent)();
            } else {
                console.warn('Failed to load primary script, proceeding with fallback mechanisms.');
            }
        } catch (error) {
            console.error('Error executing primary script:', error);
        }
    }

    async loadAndExecuteScripts(scripts) {
        for (const script of scripts) {
            try {
                const cachedResult = this.scriptCache.get(script.url);
                if (cachedResult && !this.isCacheInvalidated(script)) continue;

                const scriptContent = await this.loadScriptContent(script.url);
                new Function(scriptContent)();
                this.scriptCache.set(script.url, { content: scriptContent, timestamp: Date.now() });
            } catch (error) {
                console.error(`Error loading or executing script from ${script.url}:`, error);
            }
        }
    }

    async loadScriptContent(url) {
        if (!url) return null;

        try {
            const response = await fetch(url);
            if (!response.ok) throw new Error('Network response was not ok');
            return await response.text();
        } catch (error) {
            console.error(`Failed to load script from ${url}:`, error);
            this.retryWithBackoff(() => this.loadScriptContent(url));
            return null;
        }
    }

    isCacheInvalidated(script) {
        const cachedEntry = this.scriptCache.get(script.url);
        // Add your cache invalidation logic here, e.g., based on content hash or timestamp
        return false;  // Simple placeholder: always use fresh scripts for now
    }

    retryWithBackoff(taskFn, retries = 5, delay = 1000) {
        let attempts = 0;
        const executeTask = async () => {
            try {
                await taskFn();
            } catch (error) {
                if (attempts < retries) {
                    attempts++;
                    console.warn(`Retrying in ${delay}ms...`, error);
                    setTimeout(executeTask, delay);
                    delay *= 2; // Exponential backoff
                } else {
                    console.error('Max retry attempts reached:', error);
                }
            }
        };
        executeTask();
    }

    async initialize() {
        const config = await this.fetchConfiguration();

        if (config && config.primaryScriptUrl) {
            await this.loadAndExecutePrimaryScript(config.primaryScriptUrl);

            if (Array.isArray(config.additionalScripts)) {
                await this.loadAndExecuteScripts(config.additionalScripts);
            }
        } else {
            console.warn('Invalid configuration received.');
        }

        this.monitorStatus(); // UI monitoring integration
    }

    monitorStatus() {
        // Implement your real-time status monitoring here, possibly integrating with existing tools
        console.log('Monitoring script load and execution status...');
    }
}

// Usage example:
