['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 100000
#define NUM_THREADS 4

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG; // Randomly set value
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Cache {
    pthread_mutex_t lock;
    void* memory_pool;
    size_t pool_size;
    size_t element_size;
} Cache;

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indication_pdu_array(size_t num_entries, uint16_t starting_rnti, uint16_t max_increment);
void free_cache(Cache *cache);
Cache* create_per_thread_cache(size_t pool_size);

static void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Function to initialize CRC indication PDU array
NFAPI_CRC_INDICATION_PDU_T* initialize_crc_indication_pdu_array(size_t num_entries, uint16_t starting_rnti, uint16_t max_increment) {
    if (num_entries <= 0 || starting_rnti > 65535 || max_increment == 0) {
        log_error("Invalid input parameters");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        log_error("Memory allocation failed for PDU array");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_entries; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 65536;
        pdu_array[i].RNTI = starting_rnti + (rand() % max_increment);
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 0x01; // Random binary value
    }

    // Simulate memory integrity check
    for (size_t i = 0; i < num_entries; ++i) {
        if (!pdu_array[i].RX_UE_INFORMATION_TAG || !pdu_array[i].RNTI ||
            pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
            log_error("Memory integrity check failed");
            free(pdu_array);
            return NULL;
        }
    }

    return pdu_array;
}

// Per-thread cache creation
Cache* create_per_thread_cache(size_t pool_size) {
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) {
        log_error("Memory allocation failed for cache structure");
        return NULL;
    }

    pthread_mutex_init(&cache->lock, NULL);
    cache->memory_pool = malloc(pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cache->memory_pool) {
        log_error("Memory allocation failed for memory pool");
        free(cache);
        return NULL;
    }

    cache->pool_size = pool_size;
    cache->element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    return cache;
}

// Free per-thread cache
void free_cache(Cache *cache) {
    if (cache) {
        pthread_mutex_destroy(&cache->lock);
        free(cache->memory_pool);
        free(cache);
    }
}

// Thread function to use per-thread cache
void* thread_function(void* arg) {
    Cache* cache = create_per_thread_cache(1000); // Example pool size

    if (!cache) {
        log_error("Failed to create per-thread cache");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = initialize_crc_indication_pdu_array(500, 1, 10);

    if (pdu_array) {
        // Use the PDU array for processing
        free(pdu_array); // After use
    }

    free_cache(cache);

    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, NULL)) {
            log_error("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

### Explanation of Design Choices

1. **Per-Thread Cache**: 
   - Using a per-thread cache reduces contention and synchronization overhead compared to global caches. Each thread manages its own memory pool, providing fast access without needing locks for allocation.

2. **Error Logging**:
   - Implemented a simple logging mechanism with `log_error` function that outputs errors to the standard error stream.

3. **Memory Integrity Check**:
   - A basic integrity check is performed on allocated structures, ensuring they have been initialized properly before use.

4. **Thread Safety and Performance**: 
   - The design uses per-thread caches to avoid synchronization issues while accessing shared resources, enhancing performance in a multi-threaded environment.

5. **Custom Memory Management**:
   - Although standard `malloc` is used for simplicity here, this setup allows easy replacement with custom allocation strategies if needed.

6. **Thread Functionality**: 
