    if (*current_size + increment > MAX_ELEMENTS) {
        int new_size = resize_array(&array, *current_size);
        if (new_size < 0) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }
        *current_size = new_size;
    }

    log_event("INFO", "Array allocated/expanded successfully.");
    pthread_mutex_unlock(&lock);

    return array;
}

void deallocate_nfa_array(NFAPI_CRC_INDICATION_PDU_T **array) {
    if (array && *array) {
