// Serialization function with optional compression
void serialize_to_disk(const char* filename, int compress_flag) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    pthread_mutex_lock(&array_mutex);

    size_t total_size = current_size * sizeof(NetworkTraffic);
    char* buffer = malloc(total_size);

    memcpy(buffer, network_traffic_array, total_size);

    if (compress_flag) {
        uLongf compressed_size = compressBound(total_size);
        unsigned char* compressed_buffer = malloc(compressed_size);

        int result = compress(compressed_buffer, &compressed_size, (unsigned char*)buffer, total_size);
        if (result == Z_OK) {
            fwrite(&compressed_size, sizeof(uLongf), 1, file);
            fwrite(compressed_buffer, compressed_size, 1, file);
        } else {
            perror("Compression failed");
        }

        free(compressed_buffer);
    } else {
        fwrite(buffer, total_size, 1, file);
    }

    fclose(file);
    free(buffer);

    pthread_mutex_unlock(&array_mutex);
}

// Free resources and clean up
void free_resources() {
    pthread_mutex_lock(&array_mutex);

    for (size_t i = 0; i < current_size; ++i) {
