        if (network_traffic_array[i].pdu_list) {
            free(network_traffic_array[i].pdu_list);
        }
    }

    free(network_traffic_array);
    network_traffic_array = NULL;
    current_size = 0;

    pthread_mutex_unlock(&array_mutex);

    pthread_mutex_destroy(&array_mutex);
}

