void resizeArrayIfNeeded(int** array, int* size, int* capacity) {
    if (*size >= *capacity) {
        *capacity *= 2;
        *array = realloc(*array, *capacity * sizeof(int));
    }
}

void insertIntoList(NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (rnti_count >= MAX_RNTI_COUNT) {
        fprintf(stderr, "Warning: RNTI count limit reached.\n");
        return;
    }

    Node* current = head;
    while (current != NULL && current->data.RNTI < pdu.RNTI) {
        current = current->next;
    }

    if (current == NULL || current->data.RNTI != pdu.RNTI) {
        Node* newNode = malloc(sizeof(Node));
        newNode->data = pdu;

        if (current == NULL || current->data.RNTI > pdu.RNTI) {
            newNode->next = head;
            head = newNode;
        } else {
