['Below is a C implementation for managing a dynamic collection of `NFAPI_CRC_INDICATION_PDU_T` structures in a thread-safe manner, with considerations for efficiency, memory management, and concurrency.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG; // Assuming this is a single byte
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t size;
    pthread_rwlock_t lock; // Read-write lock for concurrency
} CRC_Indication_List;

// Function prototypes
CRC_Indication_List* create_list();
void destroy_list(CRC_Indication_List* list);
int insert_node(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_node(CRC_Indication_List* list, uint16_t RX_UE_INFORMATION_TAG);
int traverse_forward(CRC_Indication_List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T));
int traverse_backward(CRC_Indication_List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T));

CRC_Indication_List* create_list() {
    CRC_Indication_List* list = malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRC_Indication_List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

int insert_node(CRC_Indication_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return -2; // Memory allocation failure

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_rwlock_wrlock(&list->lock);
    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
        new_node->prev = new_node->next = NULL;
    }
    list->size++;
    pthread_rwlock_unlock(&list->lock);

    return 0; // Success
}

int remove_node(CRC_Indication_List* list, uint16_t RX_UE_INFORMATION_TAG) {
    if (!list) return -1;

    pthread_rwlock_wrlock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (current->prev) current->prev->next = current->next;
            else list->head = current->next;

            if (current->next) current->next->prev = current->prev;
            else list->tail = current->prev;

            free(current);
            list->size--;
            pthread_rwlock_unlock(&list->lock);
            return 0; // Success
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);

    return -1; // Node not found
}

int traverse_forward(CRC_Indication_List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !func) return -1;

    pthread_rwlock_rdlock(&list->lock);
    Node* current = list->head;
    while (current) {
        func(current->data);
        current = current->next;
    }
    pthread_rwlock_unlock(&list->lock);

    return 0; // Success
}

int traverse_backward(CRC_Indication_List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!list || !func) return -1;

    pthread_rwlock_rdlock(&list->lock);
    Node* current = list->tail;
    while (current) {
        func(current->data);
        current = current->prev;
    }
    pthread_rwlock_unlock(&list->lock);

    return 0; // Success
}

// Example function to print PDU data
void print_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRC_INDICATION_REL8_TAG: %u\n",
           pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);
}

int main() {
    CRC_Indication_List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 1001, rand() % 256};
    insert_node(list, pdu1);

    traverse_forward(list, print_pdu);
    traverse_backward(list, print_pdu);

    remove_node(list, 1);

    destroy_list(list);
    return EXIT_SUCCESS;
}
```

