    list->capacity = MAX_ENTRIES;
    list->count = 0;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)calloc(list->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    if (new_capacity > MAX_ENTRIES) {
        new_capacity = MAX_ENTRIES;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entries) {
        list->entries = new_entries;
        list->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Memory allocation failed during resize.\n");
        exit(EXIT_FAILURE);
    }
}

void add_entry(DynamicList *list, int ue_info_tag, int rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resize_dynamic_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T new_entry;
    new_entry.RX_UE_INFORMATION_TAG = ue_info_tag;
    new_entry.RNTI = rnti;
    memset(new_entry.CRC_INDICATION_REL8_TAG, 0, sizeof(new_entry.CRC_INDICATION_REL8_TAG));
    new_entry.CRCFLAG = calculate_crcflag(ue_info_tag, rnti);

    list->entries[list->count++] = new_entry;

    pthread_mutex_unlock(&list->lock);
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->entries);
    free(list);
}
