// Initialize the list
void initialize_list(StructureList* list) {
    pthread_rwlock_init(&list->list_lock, NULL);
    list->structures = NULL;
    list->count = 0;
}

// Destroy the list and free resources
void destroy_list(StructureList* list) {
    pthread_rwlock_wrlock(&list->list_lock);
    if (list->structures) {
        free(list->structures);
        list->structures = NULL;
    }
    pthread_rwlock_unlock(&list->list_lock);
    pthread_rwlock_destroy(&list->list_lock);
}

// Function to manage the list
