    if (N > MAX_STRUCTURES) {
        fprintf(stderr, "Exceeded maximum number of structures.\n");
        return -1;
    }

    pthread_mutex_lock(&pool_mutex);
    if (list->count + N > MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool_mutex);
        fprintf(stderr, "Memory pool exhausted.\n");
        return -1;
    }

    PooledStructure* new_structures = realloc(list->structures,
                                              (list->count + N) * sizeof(PooledStructure));
    if (!new_structures) {
        pthread_mutex_unlock(&pool_mutex);
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }
    list->structures = new_structures;

    pthread_mutex_unlock(&pool_mutex);

