        list->structures[list->count].pdu.RNTI = rand() % 1000; // Random RNTI
        list->structures[list->count].crc_rel8_tag.CRCFLAG = rand() & 1; // Random CRCFLAG

        log_creation(&list->structures[list->count], "ExampleSource");

        ++list->count;
        pthread_rwlock_unlock(&list->list_lock);
    }

    return 0;
}

