### C# Console Application: WebPageManager with Background Process

```csharp
using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;

namespace WebServiceSimulator
{
    class Program
    {
        static async Task Main(string[] args)
        {
            var manager = new WebPageManager();

            // Start the background process to randomly start/stop the manager.
            _ = Task.Run(() => BackgroundProcess(manager));

            Console.WriteLine("Press any key to exit...");
            Console.ReadKey();

            await manager.ShutdownAsync();
        }

        static async Task BackgroundProcess(WebPageManager manager)
        {
            Random rand = new Random();

            while (true)
            {
                int sleepTime = rand.Next(5, 16) * 1000; // 5 to 15 seconds
                await Task.Delay(sleepTime);

                lock (manager)
                {
                    if (manager.IsRunning)
                    {
                        manager.StopService();
                        Console.WriteLine($"[{DateTime.Now}] WebPageManager paused.");
                    }
                    else
                    {
                        manager.StartService();
                        Console.WriteLine($"[{DateTime.Now}] WebPageManager resumed.");
                    }
                }

                await Task.Delay(1000); // Delay before next check
            }
        }
    }

    public class WebPageManager
    {
        private readonly ConcurrentQueue<(string sectionId, string elementId, string htmlContent)> _requests = new();
        private bool _isRunning;

        public bool IsRunning => _isRunning;

        public void StartService()
        {
            _isRunning = true;
            Task.Run(ProcessRequests);
        }

        public void StopService()
        {
            _isRunning = false;
        }

        public async Task ShutdownAsync()
        {
            StopService();
            while (!_requests.IsEmpty)
            {
                await Task.Delay(100); // Allow time for processing remaining requests
            }
        }

        public void HandlePostRequest(string sectionId, string elementId, string htmlContent)
        {
            _requests.Enqueue((sectionId, elementId, htmlContent));
        }

        private async Task ProcessRequests()
        {
            while (_isRunning || !_requests.IsEmpty)
            {
                if (_requests.TryDequeue(out var request))
                {
                    await UpdateWebPageAsync(request.sectionId, request.elementId, request.htmlContent);
                    SendNotificationToMessagingService(request.sectionId); // Simulate notification
                }
                else
                {
                    await Task.Delay(50); // Idle wait time to reduce CPU usage when no requests are pending.
                }
