                WHERE id = :clinicID";

        $stmt = $pdo->prepare($sql);

        // Bind parameters
        $stmt->bindParam(':clinicID', $clinicID, \PDO::PARAM_INT);
        $stmt->bindParam(':status', $newStatus, \PDO::PARAM_STR);
        $stmt->bindParam(':lastModifiedIP', $lastModifiedIP, \PDO::PARAM_STR);

