    printf("%s\n", message); // Replace with actual logging framework integration
}

// Error handling macro
#define HANDLE_ERROR(msg) do { log_message(msg); return NULL; } while(0)

typedef struct PduCollection {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    size_t capacity;
} PduCollection;

PduCollection* initialize_pdcollection(size_t initial_capacity) {
    if (initial_capacity == 0) HANDLE_ERROR("Initial capacity must be greater than zero.");

    PduCollection* collection = malloc(sizeof(PduCollection));
    if (!collection) HANDLE_ERROR("Memory allocation failed for PduCollection.");

    collection->pdus = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!collection->pdus) {
        free(collection);
        HANDLE_ERROR("Memory allocation failed for PDUs.");
    }

    collection->count = 0;
    collection->capacity = initial_capacity;

    return collection;
}

void resize_pdcollection(PduCollection* collection, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(collection->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdus) HANDLE_ERROR("Memory reallocation failed for PDUs.");

    collection->pdus = new_pdus;
    collection->capacity = new_capacity;
}

void add_or_update_pdu(PduCollection* collection, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    if (collection->count == collection->capacity)
        resize_pdcollection(collection, collection->capacity * 2);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->pdus[i].rxUeInformationTag.rnti == new_pdu.rxUeInformationTag.rnti) {
            memcpy(&collection->pdus[i], &new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            log_message("Updated existing PDU with matching RNTI.");
            return;
        }
    }

    collection->pdus[collection->count++] = new_pdu;
    log_message("Added new PDU entry.");
}

void iterate_pdus(PduCollection* collection, void (*action)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = 0; i < collection->count; ++i) {
        action(collection->pdus[i]);
    }
}

void free_pdcollection(PduCollection** collection) {
    if (!collection || !*collection) return;

    free((*collection)->pdus);
    *collection = NULL;
}

// Example usage
void example_action(NFAPI_CRC_INDICATION_PDU_T pdu) {
    printf("Processing PDU with RNTI: %u\n", pdu.rxUeInformationTag.rnti);
}

int main() {
    PduCollection* collection = initialize_pdcollection(10);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {{.rnti = 100}, {.crcIndicationRel8Tag = "ValidTag"}, 1};
    add_or_update_pdu(collection, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {{.rnti = 101}, {.crcIndicationRel8Tag = "AnotherTag"}, 1};
    add_or_update_pdu(collection, pdu2);

    iterate_pdus(collection, example_action);

    free_pdcollection(&collection);
    return 0;
}
