#define MAX_MEMORY_USAGE_BYTES 1024 * 1024 // Example maximum memory usage in bytes

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C
} EventType;

typedef struct {
    time_t timestamp;
    EventType event_type;
    int unique_id;
    char *payload_data; // Optional, can be NULL if no payload data
    size_t payload_size;
} NetworkEventLogEntry;

int allocateNetworkEventLogs(NetworkEventLogEntry **entries, size_t N) {
    if (N <= 0) {
        fprintf(stderr, "Error: Number of entries must be positive.\n");
        return -1;
    }

    // Calculate required memory for each entry assuming maximum payload usage
    size_t max_payload_size = MAX_MEMORY_USAGE_BYTES / (sizeof(NetworkEventLogEntry) + sizeof(char));
    size_t total_memory_per_entry = sizeof(NetworkEventLogEntry) + max_payload_size;
    size_t total_required_memory = N * total_memory_per_entry;

    if (total_required_memory > MAX_MEMORY_USAGE_BYTES) {
        fprintf(stderr, "Error: Total memory requirement exceeds maximum allowed usage.\n");
        return -1;
    }

    // Allocate memory for the array of entries
    *entries = (NetworkEventLogEntry *)malloc(N * sizeof(NetworkEventLogEntry));
    if (*entries == NULL) {
        perror("Memory allocation failed for entries");
        return -1;
    }

    // Initialize each entry
    for (size_t i = 0; i < N; ++i) {
        NetworkEventLogEntry *entry = &(*entries)[i];

        entry->timestamp = time(NULL);
        entry->event_type = EVENT_TYPE_A + (rand() % 3); // Random event type
        entry->unique_id = rand(); // Simulate unique ID generation

        // Allocate memory for payload_data with a flexible size, simulate variable load
        size_t payload_size = rand() % max_payload_size;
        entry->payload_data = (char *)malloc(payload_size);

        if (entry->payload_data == NULL) {
            fprintf(stderr, "Memory allocation failed for payload data at index %zu\n", i);

            // Free previously allocated entries and their payloads
            for (size_t j = 0; j < i; ++j) {
                free((*entries)[j].payload_data);
            }
            free(*entries);

            return -1;
        }

        entry->payload_size = payload_size;

        // Simulate some random data in the payload, if any
        if (entry->payload_size > 0) {
            for (size_t j = 0; j < entry->payload_size; ++j) {
                entry->payload_data[j] = rand() % 256;
            }
        } else {
            entry->payload_data = NULL;
        }
    }

    return 0; // Success
}

void freeNetworkEventLogs(NetworkEventLogEntry *entries, size_t N) {
    if (entries == NULL) return;

    for (size_t i = 0; i < N; ++i) {
        free(entries[i].payload_data);
    }
    free(entries);
}
