    if (!list) {
        perror("Failed to allocate memory for DynamicList");
        return NULL;
    }
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->callback = callback;
    memset(list->entries, 0, sizeof(list->entries));
    return list;
}

void free_dynamic_list(DynamicList* list) {
    if (!list) return;
    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(DynamicList* list, int rx_ue_info_tag, int rnti) {
    if (!list || list->count >= MAX_ENTRIES) return -1;

    NFAPI_CRC_INDICATION_PDU_T* new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_entry) return -1;

    pthread_mutex_lock(&list->lock);
    new_entry->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_entry->RNTI = rnti;
    new_entry->CRC_INDICATION_REL8_TAG.CRCFLAG = calculate_checksum(rx_ue_info_tag, rnti);

    list->entries[list->count++] = new_entry;

    if (list->callback) {
        list->callback(*new_entry);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int delete_entry(DynamicList* list, size_t index) {
    if (!list || index >= list->count) return -1;

    pthread_mutex_lock(&list->lock);
    free(list->entries[index]);

    for (size_t i = index; i < list->count - 1; ++i) {
        list->entries[i] = list->entries[i + 1];
    }
    list->entries[--list->count] = NULL;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void compact_list(DynamicList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count;) {
        if (!list->entries[i]) {
            free(list->entries[i]);
            for (size_t j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            list->entries[--list->count] = NULL;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void log_memory_usage(DynamicList* list) {
