#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RNTI 0xFFFFF
#define POOL_SIZE 100

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[4];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_pool;
    pthread_mutex_t lock;
} PDU_POOL;

// Function to initialize the pool
int init_pdu_pool(PDU_POOL *pool) {
    if (pthread_mutex_init(&pool->lock, NULL) != 0) {
        return -1; // Failed to initialize mutex
    }

    pool->pdu_pool = malloc(POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pdu_pool) {
        pthread_mutex_destroy(&pool->lock);
        return -1; // Allocation failed
    }

    for (int i = 0; i < POOL_SIZE; ++i) {
        pool->pdu_pool[i].RX_UE_INFORMATION_TAG = rand();  // Random value or a specific initialization logic
        pool->pdu_pool[i].RNTI = rand() % (MAX_RNTI + 1);
        if (pool->pdu_pool[i].RNTI == 0) {
            continue; // Skip invalid RNTI, find another valid one
        }
        memset(pool->pdu_pool[i].CRC_INDICATION_REL8_TAG, rand(), sizeof(pool->pdu_pool[i].CRC_INDICATION_REL8_TAG));
        pool->pdu_pool[i].CRCFLAG = rand() % 2;
    }

    return 0; // Success
}

// Function to deallocate the pool
void destroy_pdu_pool(PDU_POOL *pool) {
    if (pool->pdu_pool) {
        free(pool->pdu_pool);
        pool->pdu_pool = NULL;
    }
    pthread_mutex_destroy(&pool->lock);
}

// Thread-safe function to get a PDU from the pool
int get_pdu_from_pool(PDU_POOL *pool, NFAPI_CRC_INDICATION_PDU_T **pdu) {
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pool->pdu_pool[i].RNTI != 0) { // Consider RNTI as valid and in use
            *pdu = &pool->pdu_pool[i];
            pool->pdu_pool[i].RNTI = 0; // Mark as used
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&pool->lock);
    return -1; // No available PDU
}

// Thread-safe function to release a PDU back to the pool
void release_pdu_to_pool(PDU_POOL *pool, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool->lock);

    for (int i = 0; i < POOL_SIZE; ++i) {
        if (&pool->pdu_pool[i] == pdu) {
            pool->pdu_pool[i].RNTI = rand() % (MAX_RNTI + 1); // Assign a new valid RNTI
            pthread_mutex_unlock(&pool->lock);
            return;
        }
    }

    pthread_mutex_unlock(&pool->lock);
}

// Example usage
int main() {
    PDU_POOL pool;

    if (init_pdu_pool(&pool) != 0) {
        fprintf(stderr, "Failed to initialize PDU pool.\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    if (get_pdu_from_pool(&pool, &pdu) == 0) {
        // Use pdu...
        release_pdu_to_pool(&pool, pdu);
    } else {
        fprintf(stderr, "No available PDU in pool.\n");
    }

    destroy_pdu_pool(&pool);
    return EXIT_SUCCESS;
}
