    fread(&random_value, sizeof(uint32_t), 1, random_file);
    fclose(random_file);

    return random_value & 0xFFFFFFF; // Ensure it fits in CRCFLAG range
}

int is_crcflag_unique(uint32_t crc_flag) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < unique_crc_count; ++i) {
        if (crc_flags_set[i] == crc_flag) {
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&mutex);
    return 1;
}

void add_crcflag(uint32_t crc_flag) {
    pthread_mutex_lock(&mutex);
    crc_flags_set[unique_crc_count++] = crc_flag;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu_list(size_t count, size_t *pdu_created) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*) malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    for (size_t i = 0; i < count && unique_crc_count < MAX_PDU_COUNT; ++i) {
        pdus[i].RNTI = rand() % 65535;
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 255;

        uint32_t crc_flag;
        do {
            crc_flag = generate_random_crcflag();
        } while (!is_crcflag_unique(crc_flag));

        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;
        add_crcflag(crc_flag);
        log_entry(pdus[i].RNTI, pdus[i].RX_UE_INFORMATION_TAG, crc_flag);
    }

    *pdu_created = unique_crc_count;
    return pdus;
}

void free_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    if (pdus) {
        free(pdus);
    }
}
```

