#include <string.h>

typedef struct ConfigNode {
    char *key;
    char *value;
    struct ConfigNode *next;
} ConfigNode;

typedef struct {
    ConfigNode *head;
    int sorted;
} ConfigList;

ConfigList* init_config_list(const char **keys, const char **values, int count, int sort) {
    ConfigList *list = (ConfigList*)malloc(sizeof(ConfigList));
    if (!list) return NULL;

    list->head = NULL;
    list->sorted = sort;

    for (int i = 0; i < count; ++i) {
        ConfigNode *node = (ConfigNode*)malloc(sizeof(ConfigNode));
        if (!node) {
            // Free previously allocated nodes in case of failure
            while (list->head != NULL) {
                ConfigNode *temp = list->head;
                list->head = list->head->next;
                free(temp->key);
                free(temp->value);
                free(temp);
            }
            free(list);
            return NULL;
        }

        node->key = strdup(keys[i]);
        if (!node->key) {
            free(node->key);
            free(node);
            // Free previously allocated nodes in case of failure
            while (list->head != NULL) {
                ConfigNode *temp = list->head;
                list->head = list->head->next;
                free(temp->key);
                free(temp->value);
                free(temp);
            }
            free(list);
            return NULL;
        }

        node->value = strdup(values[i]);
        if (!node->value) {
            free(node->key);
            free(node);
            // Free previously allocated nodes in case of failure
            while (list->head != NULL) {
                ConfigNode *temp = list->head;
                list->head = list->head->next;
                free(temp->key);
                free(temp->value);
                free(temp);
            }
            free(list);
            return NULL;
        }

        node->next = list->head;
        list->head = node;

        if (sort) {
            // Insert the node in sorted order
            ConfigNode **current = &list->head;
            while (*current && strcmp((*current)->key, keys[i]) < 0) {
                current = &(*current)->next;
            }
            node->next = *current;
            *current = node;
        }
    }

    return list;
}

void insert_config_param(ConfigList *list, const char *key, const char *value, int position) {
    ConfigNode *new_node = (ConfigNode*)malloc(sizeof(ConfigNode));
    if (!new_node) return;

    new_node->key = strdup(key);
    if (!new_node->key) {
        free(new_node);
        return;
    }

    new_node->value = strdup(value);
    if (!new_node->value) {
        free(new_node->key);
        free(new_node);
        return;
    }

    ConfigNode **current = &list->head;
    for (int i = 0; *current && i < position; ++i) {
        current = &(*current)->next;
    }
    new_node->next = *current;
    *current = new_node;

    if (list->sorted) {
        // Re-sort the list
        ConfigNode *prev = NULL, *curr = list->head;
        while (curr && strcmp(curr->key, key) < 0) {
            prev = curr;
            curr = curr->next;
        }
        if (prev) {
            prev->next = new_node;
        } else {
            list->head = new_node;
        }
        new_node->next = curr;

        // Update links
        ConfigNode *temp = list->head;
        while (temp && temp->next != NULL) {
            if (strcmp(temp->key, temp->next->key) > 0) {
                ConfigNode *swap = temp->next;
                temp->next = swap->next;
                swap->next = temp;

                if (list->head == temp) {
                    list->head = swap;
                }
                temp = swap;
            } else {
                temp = temp->next;
            }
        }
    }
}

void remove_config_param(ConfigList *list, const char *key) {
    ConfigNode **current = &list->head;
    while (*current && strcmp((*current)->key, key) != 0) {
        current = &(*current)->next;
    }

    if (*current) {
        ConfigNode *temp = *current;
        *current = temp->next;
        free(temp->key);
        free(temp->value);
        free(temp);
    }
}

void iterate_config_list(ConfigList *list, void (*callback)(const char *, const char *)) {
    ConfigNode *node = list->head;
    while (node) {
        callback(node->key, node->value);
        node = node->next;
    }
}

void iterate_descending_config_list(ConfigList *list, void (*callback)(const char *, const char *)) {
    // Convert to array for reverse iteration
    ConfigNode **nodes = NULL;
    int size = 0;

    ConfigNode *node = list->head;
    while (node) {
        nodes = realloc(nodes, sizeof(ConfigNode*) * (size + 1));
        if (!nodes) return;

        nodes[size++] = node;
        node = node->next;
    }

    for (int i = size - 1; i >= 0; --i) {
        callback(nodes[i]->key, nodes[i]->value);
    }

    free(nodes);
}

void free_config_list(ConfigList *list) {
    ConfigNode *node = list->head;
    while (node) {
        ConfigNode *temp = node;
        node = node->next;
        free(temp->key);
        free(temp->value);
        free(temp);
    }
    free(list);
}
