// Secure random number generation function
int generate_unique_random(int min, int max, int *used_values, size_t count) {
    if (count >= ((max - min + 1))) {
        return -1; // Not enough unique numbers available
    }

    srand(time(NULL) ^ rand()); // Seed with current time and previous random for entropy

    while (1) {
        int num = rand() % (max - min + 1) + min;

        int is_unique = 1;
        for (size_t i = 0; i < count; ++i) {
            if (used_values[i] == num) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            used_values[count] = num;
            return num;
        }
    }
}

