        records[i].RNTI = rand() % 2000 + 1;

        int crcflag_result = generate_unique_random(VALUE_RANGE_START, VALUE_RANGE_END, used_values, i);
        if (crcflag_result == -1) {
            handle_error("Failed to assign unique CRCFLAG", 3);
        }
        records[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcflag_result;
    }

    // Example of multi-threading for parallel execution
    void *thread_function(void *arg) {
        int index = *(int *)arg;
        log_message("Processing record");

        // Simulate processing with sleep (or real operations)
        usleep(1000);

        return NULL;
    }

    int indices[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS / 2; ++i) {
        indices[i] = i;
    }

    thread_result = pthread_create(&threads[0], NULL, thread_function, &indices[0]);
    if (thread_result != 0) {
        handle_error("Failed to create thread", 3);
    }

    for (int i = MAX_RECORDS / 2; i < MAX_RECORDS; ++i) {
        indices[i - MAX_RECORDS / 2] = i;
    }

    thread_result = pthread_create(&threads[1], NULL, thread_function, &indices[MAX_RECORDS / 2]);
    if (thread_result != 0) {
        handle_error("Failed to create thread", 3);
    }

    for (int i = 0; i < 2; ++i) {
        pthread_join(threads[i], NULL);
    }

