#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    // Define RB_GRANT fields
} RB_GRANT;

typedef struct {
    // Define SCHED_INFO fields
} SCHED_INFO;

typedef struct {
    // Define PHY_LAYER_STATUS fields
} PHY_LAYER_STATUS;

typedef struct {
    RB_GRANT rb_grant;
    SCHED_INFO sched_info;
    PHY_LAYER_STATUS phy_layer_status;
} DL_FRAME_HEADER_T;

typedef struct {
    DL_FRAME_HEADER_T *headers;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} HeaderCollection;

HeaderCollection* create_collection() {
    HeaderCollection *collection = (HeaderCollection *)malloc(sizeof(HeaderCollection));
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->headers = (DL_FRAME_HEADER_T *)calloc(collection->capacity, sizeof(DL_FRAME_HEADER_T));
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_collection(HeaderCollection *collection) {
    if (!collection) return;
    free(collection->headers);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_header(HeaderCollection *collection, DL_FRAME_HEADER_T header) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity * LOAD_FACTOR_THRESHOLD) {
        size_t new_capacity = collection->capacity * 2;
        DL_FRAME_HEADER_T *new_headers = (DL_FRAME_HEADER_T *)realloc(collection->headers, new_capacity * sizeof(DL_FRAME_HEADER_T));

        if (!new_headers) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }

        collection->headers = new_headers;
        collection->capacity = new_capacity;
    }

    collection->headers[collection->count++] = header;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

DL_FRAME_HEADER_T* get_header(HeaderCollection *collection, size_t index) {
    if (index >= collection->count) return NULL;

    pthread_mutex_lock(&collection->lock);
    DL_FRAME_HEADER_T *header = &collection->headers[index];
    pthread_mutex_unlock(&collection->lock);

    return header;
}

void update_collection(HeaderCollection *collection, size_t index, DL_FRAME_HEADER_T new_header) {
    if (index >= collection->count) return;

    pthread_mutex_lock(&collection->lock);
    collection->headers[index] = new_header;
    pthread_mutex_unlock(&collection->lock);
}

size_t get_count(const HeaderCollection *collection) {
    pthread_mutex_lock((pthread_mutex_t *)&collection->lock);
    size_t count = collection->count;
    pthread_mutex_unlock((pthread_mutex_t *)&collection->lock);

    return count;
}
```

### Key Points:

- **Thread Safety**: The use of `pthread_mutex_t` ensures that operations on the collection are thread-safe, preventing race conditions.

- **Dynamic Resizing**: The `add_header` function handles dynamic resizing by doubling the capacity when a threshold is reached, minimizing reallocations.

- **Efficient Memory Management**: Uses `calloc` for initial allocation and `realloc` for resizing to manage memory efficiently.

- **Graceful Degradation**: In case of memory allocation failure during resizing, the function returns an error code without crashing.

This implementation balances cache efficiency, memory usage, and processing speed by ensuring that operations are protected with mutexes and that resizing is done in a way that minimizes overhead.']

