public enum DistributionType
{
    Uniform,
    Normal,
    Exponential
}

public class DynamicRandomValueGenerator
{
    private readonly Random _random = new();
    private readonly double _min;
    private readonly double _max;
    private readonly DistributionType _distributionType;

    public DynamicRandomValueGenerator(double min, double max, DistributionType distributionType)
    {
        if (min >= max) throw new ArgumentException("Min must be less than Max.");
        _min = min;
        _max = max;
        _distributionType = distributionType;
    }

    public int GenerateInt()
    {
        switch (_distributionType)
        {
            case DistributionType.Uniform:
                return (int)(_random.NextDouble() * (_max - _min) + _min);
            case DistributionType.Normal:
                double normalValue = GetNormalValue();
                return (int)Math.Clamp(normalValue, _min, _max);
            case DistributionType.Exponential:
                double exponentialValue = GetExponentialValue();
                return (int)Math.Clamp(exponentialValue, _min, _max);
            default:
                throw new InvalidOperationException("Unsupported distribution type.");
        }
    }

    public float GenerateFloat()
    {
        switch (_distributionType)
        {
            case DistributionType.Uniform:
                return (float)(_random.NextDouble() * (_max - _min) + _min);
            case DistributionType.Normal:
                double normalValue = GetNormalValue();
                return (float)Math.Clamp(normalValue, _min, _max);
            case DistributionType.Exponential:
                double exponentialValue = GetExponentialValue();
                return (float)Math.Clamp(exponentialValue, _min, _max);
            default:
                throw new InvalidOperationException("Unsupported distribution type.");
        }
    }

    private double GetNormalValue()
    {
        // Box-Muller transform
        double u1 = 1.0 - _random.NextDouble(); //uniform(0,1] random doubles
        double u2 = 1.0 - _random.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) *
                               Math.Sin(2.0 * Math.PI * u2); //random normal(0,1)
        double mean = (_min + _max) / 2;
        double stdDev = (_max - _min) / 6; //Approximate range for 99.7% of data
        return mean + stdDev * randStdNormal;
    }

    private double GetExponentialValue()
    {
        double lambda = 1.0 / ((_max - _min) / 2);
        return Math.Log(1.0 - _random.NextDouble()) / (-lambda) + (_min + _max) / 2;
    }

    public override string ToString()
    {
        return $"DynamicRandomValueGenerator Settings:\n" +
               $"Range: [{_min}, {_max}]\n" +
               $"Distribution Type: {_distributionType}";
    }
}

