    {
        (float minValue, float maxValue) FetchRange();
    }

    public DynamicValueGenerator(IRangeSource rangeSource)
    {
        UpdateRange(rangeSource);
    }

    private void UpdateRange(IRangeSource source)
    {
        lock (_lock)
        {
            try
            {
                var (min, max) = source.FetchRange();

                if (min >= max)
                    throw new ArgumentException("Minimum value must be less than maximum value.");

                _minValue = min;
                _maxValue = max;
            }
            catch (Exception ex)
