        }
    }

    public float GetRandomFloat()
    {
        lock (_lock)
        {
            return UnityEngine.Random.Range(_minValue, _maxValue);
        }
    }

    public int GetExclusiveRandomInt()
    {
        lock (_lock)
        {
            if (_minValue >= _maxValue - 1) 
