// Function to allocate memory for CRC indications.
NFAPI_CRC_INDICATION_PDU_T** allocate_crc_indications(int N, int sessionId, int priorityLevel, const char* allocationStrategy) {
    if (N <= 0) {
        log_error("Invalid number of allocations requested.");
        return NULL;
    }

    // Determine memory allocation strategy based on external parameters.
    size_t poolSize = N * sizeof(NFAPI_CRC_INDICATION_PDU_T*);
    void* poolMemory = malloc(poolSize);

    if (poolMemory == NULL) {
        log_error("Failed to allocate memory for CRC indications.");
        return NULL;
    }

    // Allocate each structure individually within the pool.
    NFAPI_CRC_INDICATION_PDU_T** crcIndications = (NFAPI_CRC_INDICATION_PDU_T**) poolMemory;

    for (int i = 0; i < N; ++i) {
        crcIndications[i] = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (crcIndications[i] == NULL) {
            log_error("Failed to allocate memory for individual CRC indication.");

            // Free already allocated structures before returning.
            while (--i >= 0) {
                free(crcIndications[i]);
            }
            free(poolMemory);
            return NULL;
        }

        // Initialize the structure with provided parameters.
        crcIndications[i]->sessionId = sessionId;
        crcIndications[i]->priorityLevel = priorityLevel;
    }

    return crcIndications;
}

// Function to deallocate memory for CRC indications.
void deallocate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** crcIndications, int N) {
    if (crcIndications == NULL) {
        return;
    }

    // Free each structure individually.
    for (int i = 0; i < N; ++i) {
        free(crcIndications[i]);
    }

    // Free the pool memory.
    free(crcIndications);
}

