```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 100

typedef struct {
    int port;
} PortConfig;

typedef struct {
    char ipAddress[16];
    char subnetMask[16];
    char gateway[16];
    PortConfig *ports;
    size_t portCount;
} NetworkInterfaceConfig;

int isValidIpAddress(const char* ip) {
    int dots = 0, len = strlen(ip);
    for (int i = 0; i < len; ++i) {
        if (ip[i] == '.') {
            ++dots;
        } else if (ip[i] < '0' || ip[i] > '9') {
            return 0;
        }
    }
    return dots == 3 && strlen(ip) <= 15;
}

int areSubnetsOverlapping(const char* subnet1, const char* subnet2) {
    // Dummy function for demonstration; real implementation required
    return strcmp(subnet1, subnet2) != 0; 
}

void initializeConfig(NetworkInterfaceConfig *config, const char *ipAddr, const char *subnet, const char *gateway, PortConfig ports[], size_t portCount) {
    if (isValidIpAddress(ipAddr)) {
        strncpy(config->ipAddress, ipAddr, sizeof(config->ipAddress));
    } else {
        strcpy(config->ipAddress, "0.0.0.0");
    }
    strncpy(config->subnetMask, subnet ? subnet : "255.255.255.0", sizeof(config->subnetMask));
    strncpy(config->gateway, gateway ? gateway : "0.0.0.0", sizeof(config->gateway));

    config->ports = (PortConfig*)malloc(portCount * sizeof(PortConfig));
    if (!config->ports) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    memcpy(config->ports, ports, portCount * sizeof(PortConfig));
    config->portCount = portCount;
}

NetworkInterfaceConfig* createNetworkConfigs(size_t count, ...) {
    va_list args;
    NetworkInterfaceConfig *configs = (NetworkInterfaceConfig*)calloc(count, sizeof(NetworkInterfaceConfig));
    if (!configs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    for (size_t i = 0; i < count; ++i) {
        const char *ipAddr = va_arg(args, const char*);
        const char *subnet = va_arg(args, const char*);
        const char *gateway = va_arg(args, const char*);

        PortConfig ports[10]; // Example fixed array size for demonstration
        size_t portCount = va_arg(args, size_t);
        memcpy(ports, va_arg(args, PortConfig*), portCount * sizeof(PortConfig));

        pthread_mutex_lock(&lock);
        initializeConfig(&configs[i], ipAddr ? ipAddr : NULL, subnet ? subnet : NULL, gateway ? gateway : NULL, ports, portCount);

        for (size_t j = 0; j < i; ++j) {
            if (areSubnetsOverlapping(configs[j].subnetMask, configs[i].subnetMask)) {
                fprintf(stderr, "Error: Overlapping subnets detected\n");
                exit(1);
            }
        }
        pthread_mutex_unlock(&lock);
    }

    va_end(args);

    pthread_mutex_destroy(&lock);
    return configs;
}

void freeNetworkConfigs(NetworkInterfaceConfig *configs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(configs[i].ports);
    }
    free(configs);
}
```

