using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public sealed class RandomizerAndEncryptor : IDisposable
{
    private static readonly object _lock = new object();
    private readonly RNGCryptoServiceProvider _rng;

    private int _minValue;
    private int _maxValue;

    private Aes _aesCipher;
    private byte[] _iv;
    private byte[] _key;

    public RandomizerAndEncryptor(int minValue, int maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");

        _rng = new RNGCryptoServiceProvider();
        _minValue = minValue;
        _maxValue = maxValue;

        InitializeCipherDefaults();
    }

    private void InitializeCipherDefaults()
    {
        _iv = new byte[16];
        _rng.GetBytes(_iv); // Generate a random IV
    }

    public int GetRandomInteger()
    {
        lock (_lock)
        {
            var range = _maxValue - _minValue + 1;
            byte[] randomNumber = new byte[4];
            _rng.GetBytes(randomNumber);
            return _minValue + (BitConverter.ToInt32(randomNumber, 0) % range);
        }
    }

    public float GetRandomFloat()
    {
        lock (_lock)
        {
            var range = _maxValue - _minValue;
            byte[] randomNumber = new byte[4];
            _rng.GetBytes(randomNumber);
            return _minValue + (float)(BitConverter.ToInt32(randomNumber, 0) % (range * 10000)) / 10000f;
        }
    }

    public void InitializeCipher(string password)
    {
        if (string.IsNullOrEmpty(password))
            throw new ArgumentException("Password cannot be null or empty.");

        var key = DeriveKeyFromPassword(password, 32);

        _aesCipher = Aes.Create();
        _aesCipher.Mode = CipherMode.CBC;
        _aesCipher.Padding = PaddingMode.PKCS7;

        _key = key;
    }

    private byte[] DeriveKeyFromPassword(string password, int length)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(password);
            var hash = sha256.ComputeHash(bytes);

            if (hash.Length < length) throw new ArgumentException("Derived key is shorter than expected.");

            byte[] derivedKey = new byte[length];
            Array.Copy(hash, 0, derivedKey, 0, length);

            return derivedKey;
        }
    }

    public void EncryptData(byte[] data, out byte[] encryptedData)
    {
        if (_aesCipher == null) throw new InvalidOperationException("Cipher is not initialized.");

        _aesCipher.Key = _key;
        _aesCipher.IV = _iv;

        using (var encryptor = _aesCipher.CreateEncryptor())
        {
            encryptedData = encryptor.TransformFinalBlock(data, 0, data.Length);
        }
    }

    public void DecryptData(byte[] encryptedData, out byte[] decryptedData)
    {
        if (_aesCipher == null) throw new InvalidOperationException("Cipher is not initialized.");

        _aesCipher.Key = _key;
        _aesCipher.IV = this._iv;

        using (var decryptor = _aesCipher.CreateDecryptor())
        {
            decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
        }
    }

    public void Dispose()
    {
        _rng?.Dispose();
        _aesCipher?.Clear();
    }

    public override string ToString()
    {
        return $"RandomizerAndEncryptor: MinValue={_minValue}, MaxValue={_maxValue}";
    }
}
```

### Key Points:

- **Thread-Safe Random Generation**: Uses `RNGCryptoServiceProvider` with a lock to ensure thread safety.
- **AES Encryption Initialization**: Utilizes SHA256 for key derivation, balancing security and performance.
- **Error Handling**: Throws exceptions for invalid states such as uninitialised cipher or invalid password.
- **Resource Management**: Implements `IDisposable` to manage cryptographic resources.
- **Extensibility and Modularity**: Designed for easy integration into larger systems.']

