} LTE_PDCP_STATS_T;

// Structure to hold pooled network interface statistics
typedef struct {
    LTE_PDCP_STATS_T *stats_array;
    size_t count;
    pthread_mutex_t mutex;
} NetworkInterfaceStatsPool;

// Function prototypes
LTE_PDCP_STATS_T* allocate_pdc_stats(size_t n);
void free_pdc_stats(LTE_PDCP_STATS_T *stats, size_t n);
int validate_stats(const LTE_PDCP_STATS_T *stats, size_t n);
void aggregate_statistics(NetworkInterfaceStatsPool *pool);

// Allocate memory for an array of LTE_PDCP_STATS_T
LTE_PDCP_STATS_T* allocate_pdc_stats(size_t n) {
    if (n == 0) return NULL;

    LTE_PDCP_STATS_T *stats = malloc(n * sizeof(LTE_PDCP_STATS_T));
    if (!stats) {
        fprintf(stderr, "Memory allocation failed for LTE_PDCP_STATS_T array\n");
        return NULL;
    }

    // Initialize memory to zero
    memset(stats, 0, n * sizeof(LTE_PDCP_STATS_T));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    NetworkInterfaceStatsPool pool = {stats, n, mutex};

    // Simulated periodic aggregation (in a real application, this could be scheduled with a timer)
    aggregate_statistics(&pool);

    return stats;
}

// Free the allocated memory for LTE_PDCP_STATS_T array
void free_pdc_stats(LTE_PDCP_STATS_T *stats, size_t n) {
    if (stats) {
        free(stats);
    }
}

// Validate integrity of statistics
int validate_stats(const LTE_PDCP_STATS_T *stats, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        if (stats[i].SNSSAI < 0 || stats[i].PDU_SESSION_ID < 0 ||
            stats[i].SRB_TYPE < 0 || stats[i].PDCP_RX_SN == 0) {
            fprintf(stderr, "Statistics validation failed at index %zu\n", i);
            return -1;
        }
    }
    return 0;
}

// Aggregate statistics from multiple network interfaces
void aggregate_statistics(NetworkInterfaceStatsPool *pool) {
    pthread_mutex_lock(&pool->mutex);

    // Simulated aggregation logic (e.g., summing PDCP_RX_SN across entries)
    unsigned long total_rx_sn = 0;
    for (size_t i = 0; i < pool->count; ++i) {
        total_rx_sn += pool->stats_array[i].PDCP_RX_SN;
    }

    // Log the aggregated result
    printf("Total PDCP_RX_SN: %lu\n", total_rx_sn);

    pthread_mutex_unlock(&pool->mutex);
}

// Main function demonstrating usage
