    LTE_PDCP_STATS_T *stats = allocate_pdc_stats(num_entries);
    if (stats) {
        if (validate_stats(stats, num_entries) == 0) {
            printf("Statistics are valid.\n");
        }

        free_pdc_stats(stats, num_entries);
