typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    _Atomic(uint8_t) CRC_INDICATION_REL8_TAG; // Atomic for thread-safe read/write
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 16

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    atomic_size_t count;
    pthread_rwlock_t rwlock;
} CRC_Indication_Collection;

// Initialize the collection
void init_collection(CRC_Indication_Collection *collection) {
    collection->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    collection->capacity = INITIAL_CAPACITY;
    atomic_store(&collection->count, 0);
    pthread_rwlock_init(&collection->rwlock, NULL);
}

// Resize the collection when needed
static void resize_collection(CRC_Indication_Collection *collection) {
    size_t new_capacity = collection->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        pthread_rwlock_wrlock(&collection->rwlock);
        collection->data = new_data;
        collection->capacity = new_capacity;
        pthread_rwlock_unlock(&collection->rwlock);
    }
}

// Insert a PDU
void insert_pdu(CRC_Indication_Collection *collection, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_rwlock_wrlock(&collection->rwlock);

    if (atomic_load(&collection->count) >= collection->capacity) {
        resize_collection(collection);
    }

    size_t index = atomic_fetch_add(&collection->count, 1);
    memcpy(&collection->data[index], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_rwlock_unlock(&collection->rwlock);
}

// Bulk insert PDUs
void bulk_insert(CRC_Indication_Collection *collection, NFAPI_CRC_INDICATION_PDU_T* pdus, size_t num_pdus) {
    pthread_rwlock_wrlock(&collection->rwlock);

    while (atomic_load(&collection->count) + num_pdus > collection->capacity) {
        resize_collection(collection);
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        size_t index = atomic_fetch_add(&collection->count, 1);
        memcpy(&collection->data[index], &pdus[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_rwlock_unlock(&collection->rwlock);
}

// Traverse the collection
void traverse_collection(CRC_Indication_Collection *collection, void (*callback)(NFAPI_CRC_INDICATION_PDU_T* pdu)) {
    pthread_rwlock_rdlock(&collection->rwlock);

    for (size_t i = 0; i < atomic_load(&collection->count); ++i) {
        callback(&collection->data[i]);
    }

    pthread_rwlock_unlock(&collection->rwlock);
}

// Clean up the collection
void destroy_collection(CRC_Indication_Collection *collection) {
    free(collection->data);
    pthread_rwlock_destroy(&collection->rwlock);
}

// Error handling example (simplified)
void log_error(const char* message) {
    // Implement logging to a file or console as needed.
    fprintf(stderr, "Error: %s\n", message);
}
