NIC_Stats* nic_stats_array = NULL;
size_t array_size = 0;
pthread_mutex_t stats_mutex = PTHREAD_MUTEX_INITIALIZER;
const size_t FLUSH_INTERVAL_SECONDS = 60; // Example flush interval

// Function to initialize the dynamic array
void init_nic_stats(size_t initial_size) {
    pthread_mutex_lock(&stats_mutex);
    if (nic_stats_array != NULL) {
        free(nic_stats_array);
    }
    array_size = initial_size;
    nic_stats_array = malloc(sizeof(NIC_Stats) * array_size);
    pthread_mutex_unlock(&stats_mutex);

    // Initialize the NIC stats
    for (size_t i = 0; i < array_size; ++i) {
        nic_stats_array[i].interface_id = -1; // Invalid ID initially
        memset(nic_stats_array[i].ip_address, 0, INET_ADDRSTRLEN);
        nic_stats_array[i].packets_sent = 0;
        nic_stats_array[i].packets_received = 0;
    }
}

// Function to update NIC statistics
void update_nic_stats(int interface_id, const char* ip_address, unsigned long packets_sent, unsigned long packets_received) {
    pthread_mutex_lock(&stats_mutex);

    for (size_t i = 0; i < array_size; ++i) {
        if (nic_stats_array[i].interface_id == interface_id) {
            strncpy(nic_stats_array[i].ip_address, ip_address, INET_ADDRSTRLEN - 1);
            nic_stats_array[i].packets_sent += packets_sent;
            nic_stats_array[i].packets_received += packets_received;
            break;
        }
    }

    pthread_mutex_unlock(&stats_mutex);
}

// Function to flush NIC statistics to disk
void* flush_nic_stats_to_disk(void* arg) {
    while (1) {
        sleep(FLUSH_INTERVAL_SECONDS);

        pthread_mutex_lock(&stats_mutex);

        FILE *file = fopen("nic_statistics.log", "a");
        if (file == NULL) {
            perror("Failed to open file for logging");
            pthread_mutex_unlock(&stats_mutex);
            continue;
        }

        time_t current_time = time(NULL);
        fprintf(file, "Flush at %s\n", ctime(&current_time));

        for (size_t i = 0; i < array_size; ++i) {
            if (nic_stats_array[i].interface_id != -1) { // Only log valid entries
                fprintf(file, "Interface ID: %d, IP Address: %s, Packets Sent: %lu, Packets Received: %lu\n",
                        nic_stats_array[i].interface_id,
                        nic_stats_array[i].ip_address,
                        nic_stats_array[i].packets_sent,
                        nic_stats_array[i].packets_received);
            }
        }

        fclose(file);

        pthread_mutex_unlock(&stats_mutex);
    }
    return NULL;
}

// Function to start the periodic flush task
void start_periodic_flush() {
    pthread_t flush_thread;
    if (pthread_create(&flush_thread, NULL, flush_nic_stats_to_disk, NULL) != 0) {
        perror("Failed to create thread for flushing statistics");
    }
}

int main() {
