    init_nic_stats(10); // Assume we start with space for 10 interfaces
    update_nic_stats(1, "192.168.1.2", 100, 150);

    // Start the periodic flush to disk in a separate thread
    start_periodic_flush();

    // Simulate other operations...

    return 0;
}
