    array->size = 0;
    array->allocation_count = 1; // Initial allocation
    array->deallocation_count = 0;

    return array;
}

// Resize the dynamic array if needed
int resize_dynamic_array(DynamicArray *array, size_t new_size) {
    if (new_size > array->capacity && array->capacity < MAX_CAPACITY) {
        NFAPI_CRC_INDICATION_PDU_T *temp_data = realloc(array->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) return 0;

        memset(temp_data + array->capacity, 0, (new_size - array->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        array->data = temp_data;
        array->capacity = new_size;
