    allocations = total_allocations;
    pthread_mutex_unlock(&allocation_counter_lock);
    return allocations;
}

int read_configuration(const char* config_file, int* n) {
    FILE *file = fopen(config_file, "r");
    if (!file) {
        log_event("Error: Configuration file not found.", LOG_DETAILED, LOG_SUMMARY);
        return 0;
    }

    if (fscanf(file, "%d", n) != 1 || *n < 1 || *n > 1000) {
        log_event("Error: Invalid configuration value read. Using default of 10.", LOG_DETAILED, LOG_SUMMARY);
        fclose(file);
        return 0;
    }

