    if (!list) {
        log_event("Memory allocation failed for list pointer.", LOG_DETAILED, logging_level);
        return NULL;
    }

    pthread_mutex_lock(&allocation_counter_lock);
    total_allocations++;
    pthread_mutex_unlock(&allocation_counter_lock);

    log_event("Allocated memory for list of NFAPI_CRC_INDICATION_PDU_T pointers.", LOG_DETAILED, logging_level);

    uint16_t unique_tags[1000] = {0};

    for (int i = 0; i < n; ++i) {
