        pthread_mutex_lock(&allocation_counter_lock);
        total_allocations++;
        pthread_mutex_unlock(&allocation_counter_lock);

        // Generate a unique RX_UE_INFORMATION_TAG
        uint16_t tag = rand() % 1000 + 1; // Assuming tags range from 1 to 1000 for simplicity
        while (unique_tags[tag - 1]) {
            tag = rand() % 1000 + 1;
