#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t max_size_bytes; // Max memory budget
    void (*on_capacity_reached)(void);
    void (*on_success)(void);
} NFAPI_CRC_INDICATION_LIST_T;

size_t calculate_structure_size(size_t count) {
    return sizeof(NFAPI_CRC_INDICATION_PDU_T) * count;
}

bool is_rnti_unique(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return false;
        current = current->next;
    }
    return true;
}

void log_event(const char* message) {
    printf("LOG: %s\n", message);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for new node.");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void append_to_list(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node)
        return;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    size_t current_size_bytes = 0;
    for (Node* node = list->head; node != NULL; node = node->next) {
        current_size_bytes += calculate_structure_size(1);
        if (current_size_bytes > list->max_size_bytes) {
            // Handle memory overflow
            log_event("Memory budget exceeded. Consider optimizing.");
            pthread_mutex_unlock(&list->lock);

            if (list->on_capacity_reached)
                list->on_capacity_reached();

            return;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void populate_list(NFAPI_CRC_INDICATION_LIST_T* list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data;

        // Populate structure with random valid values
        data.RX_UE_INFORMATION_TAG = rand();
        do {
            data.RNTI = (uint16_t)(rand() % 10000); // Generate a pseudo-random RNTI
        } while (!is_rnti_unique(list, data.RNTI));

        data.CRC_INDICATION_REL8_TAG = rand() % 256;
        data.CRCFLAG = rand() & 1;

        append_to_list(list, data);
    }

    if (list->on_success)
        list->on_success();
}

void initialize_list(NFAPI_CRC_INDICATION_LIST_T* list, size_t max_size_bytes,
                     void (*capacity_callback)(void), void (*success_callback)(void)) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size_bytes = max_size_bytes;
    list->on_capacity_reached = capacity_callback;
    list->on_success = success_callback;
}

void cleanup_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

// Callback functions
void capacity_reached_callback() {
    log_event("List has reached its memory capacity.");
}

void success_callback() {
    log_event("List successfully populated.");
}

// Usage example (must be protected with a mutex if used concurrently)
int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_LIST_T list;
    initialize_list(&list, 1024 * 100, // Example memory budget
                    capacity_reached_callback,
                    success_callback);

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        size_t n_values[] = {10, 20, 15, 25, 30};
        pthread_create(&threads[i], NULL, (void*(*)(void*))populate_list, &list);
        pthread_join(threads[i], NULL);
    }

    cleanup_list(&list);

    return 0;
}
```

### Key Points:
- The list is protected by a mutex to ensure thread safety when accessed concurrently.
- A simple linked-list structure stores NFAPI_CRC_INDICATION_PDU_T entries.
- Memory usage checks are performed during each insertion, logging events if the memory budget is exceeded.
- Callbacks notify when the capacity is reached or when population succeeds.']

