using System;
using System.Collections.Generic;
using System.Xml.Linq;
using System.IO;

namespace GameConfigManager
{
    public class ConfigurationManager
    {
        private Dictionary<string, string> _configurations = new();
        private List<Dictionary<string, string>> _history = new();
        private readonly ILogger _logger = new ConsoleLogger();

        public void LoadConfiguration()
        {
            try
            {
                // Load from XML file
                XElement root = XElement.Load("config.xml");
                foreach (XElement element in root.Elements())
                {
                    _configurations[element.Name.LocalName] = element.Value;
                }

                // Load from environment variables
                string tileSize = Environment.GetEnvironmentVariable("TILE_SIZE") ?? "32";
                string worldDimensions = Environment.GetEnvironmentVariable("WORLD_DIMENSIONS") ?? "1024x768";
                string cameraSpeed = Environment.GetEnvironmentVariable("CAMERA_SPEED") ?? "5";

                _configurations["TileSize"] = tileSize;
                _configurations["WorldDimensions"] = worldDimensions;
                _configurations["CameraSpeed"] = cameraSpeed;

                LogConfigurationChange("Loaded initial configuration");
            }
            catch (Exception ex)
            {
                _logger.LogError($"Error loading configuration: {ex.Message}");
            }
        }

        public void ApplyDynamicScaling(int screenWidth, int screenHeight)
        {
            if (!int.TryParse(_configurations["TileSize"], out int tileSize))
            {
                _logger.LogError("Invalid Tile Size");
                return;
            }

            // Example scaling logic
            double aspectRatio = (double)screenWidth / screenHeight;
            _configurations["ScaledTileSize"] = $"{tileSize * aspectRatio}";
            LogConfigurationChange($"Applied dynamic scaling to tile size: {tileSize} -> {_configurations["ScaledTileSize"]}");
        }

        public void AddNewWorldLayer(string layerName, string tileSize, string cameraSpeed)
        {
            _configurations[$"{layerName}_TileSize"] = tileSize;
            _configurations[$"{layerName}_CameraSpeed"] = cameraSpeed;

            LogConfigurationChange($"Added new world layer: {layerName}");
        }

        public void SwitchTileset(string tilesetName)
        {
            // Assuming tilesets are preloaded and managed
            _logger.LogInfo($"Switched to tileset: {tilesetName}");
        }

        private void LogConfigurationChange(string message)
        {
            _history.Add(new Dictionary<string, string>(_configurations));
            _logger.LogInfo(message);
        }

        public void RevertToPreviousConfiguration()
        {
            if (_history.Count > 1)
            {
                _history.RemoveAt(_history.Count - 1); // Remove current
                var previousConfig = _history[^1];    // Get last from history

                _configurations.Clear();
                foreach (var config in previousConfig)
                {
                    _configurations[config.Key] = config.Value;
                }

                LogConfigurationChange("Reverted to previous configuration");
            }
            else
            {
                _logger.LogError("No previous configurations to revert.");
            }
        }
    }

    public interface ILogger
    {
        void LogInfo(string message);
        void LogError(string message);
    }

    public class ConsoleLogger : ILogger
    {
        public void LogInfo(string message)
        {
            Console.WriteLine($"INFO: {message}");
        }

        public void LogError(string message)
        {
            Console.Error.WriteLine($"ERROR: {message}");
        }
    }

    class Program
    {
        static void Main()
        {
            ConfigurationManager configManager = new ConfigurationManager();
            configManager.LoadConfiguration();

            // Example use cases
            configManager.ApplyDynamicScaling(1920, 1080);
            configManager.AddNewWorldLayer("Underwater", "64", "2");
            configManager.SwitchTileset("Desert");

            // Simulate a revert action
            configManager.RevertToPreviousConfiguration();
        }
    }
}
```

### Key Points:
- **Dynamic Loading:** The application loads configurations from both an XML file and environment variables.
- **Aspect Ratio Management:** Scales the tile size dynamically based on screen dimensions to maintain aspect ratio consistency.
- **Layer Management:** Allows adding new world layers with specific settings for tile sizes and camera speeds.
- **Logging Mechanism:** Uses a simple console logger to record configuration changes and errors, aiding debugging and tracking.
- **Reverting Configurations:** Supports reverting to previous configurations using a history mechanism.
- **Error Handling:** Logs errors without crashing when encountering unexpected data or missing configurations.

This architecture provides flexibility for further extension with additional features or configuration sources as needed.']

