#define MAX_MEMORY_USAGE_BYTES 1024 * 1024 // Example maximum memory usage constraint
#define RETRY_LIMIT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Simulated external validation function with random success/failure
bool validate_RNTI(int rnti) {
    return rand() % 2; // Randomly simulate a successful or failed validation
}

// Simulated cache for RNTI validation results
typedef struct {
    int rnti;
    bool isValid;
} RNTI_CacheEntry;

#define CACHE_SIZE 100

RNTI_CacheEntry rnti_cache[CACHE_SIZE];
int cache_index = 0;
bool use_rnti_cache = true; // Control flag to enable or disable caching

void initialize_cache() {
    for (int i = 0; i < CACHE_SIZE; ++i) {
        rnti_cache[i].rnti = -1;
        rnti_cache[i].isValid = false;
    }
}

bool check_and_update_cache(int rnti, bool* cache_result) {
    if (!use_rnti_cache) return false;

    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (rnti_cache[i].rnti == rnti) {
            *cache_result = rnti_cache[i].isValid;
            return true;
        }
    }

    // Cache miss, perform validation
    bool isValid = false;
    int attempts = 0;
    while (!isValid && attempts < RETRY_LIMIT) {
        isValid = validate_RNTI(rnti);
        if (!isValid) {
            attempts++;
            usleep(100000 * (1 << attempts)); // Exponential backoff
        }
    }

    // Update cache with the new result
    rnti_cache[cache_index % CACHE_SIZE].rnti = rnti;
    rnti_cache[cache_index % CACHE_SIZE].isValid = isValid;
    cache_index++;

    *cache_result = isValid;
    return false; // Cache miss occurred
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_pdu_array(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input size: %d\n", N);
        return NULL;
    }

    int element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (element_size * N > MAX_MEMORY_USAGE_BYTES) {
        fprintf(stderr, "Exceeds maximum memory usage constraint.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = malloc(element_size * N);
    if (!pdu_array) {
        perror("Memory allocation failed for PDU array");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    bool cache_result;
    for (int i = 0; i < N; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = rand(); // Random initialization
        int rnti = rand();

        if (!check_and_update_cache(rnti, &cache_result)) {
            fprintf(stderr, "Failed to validate RNTI for element %d after retries.\n", i);
            free(pdu_array);
            return NULL;
        }

        pdu_array[i].RNTI = rnti;
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand(); // Random initialization
        pdu_array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }

    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdu_array) {
    if (pdu_array) {
        free(pdu_array);
    }
}

