#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int event_id;
    long timestamp;
    size_t payload_length;
    void *payload; // Can be a sequence of bytes or a pointer to additional data
} Event;

#define INITIAL_CAPACITY 10

// Node in the doubly linked list
struct EventNode {
    Event event;
    struct EventNode *next;
    struct EventNode *prev;
};

typedef struct {
    struct EventNode *head;
    size_t count;
    pthread_mutex_t lock; // Mutex for concurrency control
} EventManager;

EventManager* create_event_manager() {
    EventManager *manager = (EventManager*)malloc(sizeof(EventManager));
    manager->head = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_event_manager(EventManager *manager) {
    struct EventNode *current = manager->head;
    while (current != NULL) {
        struct EventNode *next = current->next;
        free(current->event.payload); // Free payload
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_event(EventManager *manager, int event_id, long timestamp, void *payload, size_t payload_length) {
    pthread_mutex_lock(&manager->lock);

    struct EventNode *new_node = (struct EventNode*)malloc(sizeof(struct EventNode));
    new_node->event.event_id = event_id;
    new_node->event.timestamp = timestamp;
    new_node->event.payload_length = payload_length;

    // Allocate memory for payload
    new_node->event.payload = malloc(payload_length);
    memcpy(new_node->event.payload, payload, payload_length);

    // Add to the front of the list
    new_node->next = manager->head;
    new_node->prev = NULL;
    if (manager->head != NULL) {
        manager->head->prev = new_node;
    }
    manager->head = new_node;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
}

Event* get_event(EventManager *manager, int event_id) {
    pthread_mutex_lock(&manager->lock);

    struct EventNode *current = manager->head;
    while (current != NULL) {
        if (current->event.event_id == event_id) {
            pthread_mutex_unlock(&manager->lock);
            return &current->event;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL; // Event not found
}

void update_event(EventManager *manager, int event_id, long new_timestamp, void *new_payload, size_t payload_length) {
    pthread_mutex_lock(&manager->lock);

    struct EventNode *current = manager->head;
    while (current != NULL) {
        if (current->event.event_id == event_id) {
            // Update timestamp and payload
            current->event.timestamp = new_timestamp;

            // Free old payload and allocate memory for new one
            free(current->event.payload);
            current->event.payload = malloc(payload_length);
            memcpy(current->event.payload, new_payload, payload_length);

            current->event.payload_length = payload_length;
            break; // Event found and updated
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    EventManager *manager = create_event_manager();

    char data[] = "example_payload";
    add_event(manager, 1, 1234567890L, data, sizeof(data));

    Event *event = get_event(manager, 1);
    if (event) {
        printf("Event ID: %d\n", event->event_id);
        printf("Timestamp: %ld\n", event->timestamp);
        printf("Payload Length: %zu\n", event->payload_length);
    }

    char new_data[] = "new_payload";
    update_event(manager, 1, 1234567899L, new_data, sizeof(new_data));

    destroy_event_manager(manager);

    return 0;
}
```

### Key Features:
- **Memory Management**: Efficient allocation and deallocation of memory for event structures and payloads.
- **Concurrency**: Uses a mutex to protect access to the list, preventing race conditions.
- **Scalability**: The doubly linked list allows efficient insertion and updates. For horizontal scaling, consider distributed systems strategies beyond this simple example.
- **Data Consistency**: Updates are safely managed within the locked section.
- **Performance Optimization**: Minimizes locking time by only locking during critical sections.
- **Error Handling**: Basic error handling for memory allocation failures (not explicitly shown but can be added).
- **Usability**: Simple API with `add_event`, `get_event`, and `update_event` functions.']

