#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure for user profiles.
typedef struct UserProfile {
    int userId;
    char name[100];
    char email[100];
    // Add more attributes as needed.
} UserProfile;

// Define a structure to represent a list of merged profiles.
typedef struct MergedProfileList {
    UserProfile *profiles;   // Array of profiles
    size_t count;            // Number of profiles in the array
} MergedProfileList;

// Function to compare two user profiles based on a merge attribute.
int compare_profiles(const void *a, const void *b, const char *attribute) {
    UserProfile *profileA = (UserProfile *)a;
    UserProfile *profileB = (UserProfile *)b;

    if (strcmp(attribute, "name") == 0) {
        return strcmp(profileA->name, profileB->name);
    } else if (strcmp(attribute, "email") == 0) {
        return strcmp(profileA->email, profileB->email);
    }

    // Add more attribute comparisons as needed.

    return 0; // Default case when attribute is not recognized.
}

// Merging function using qsort and custom comparison
UserProfile* merge_profiles(int *userIds, size_t userCount, UserProfile *profiles, const char *mergeAttribute) {
    if (!userIds || !userCount || !profiles || !mergeAttribute) return NULL;

    // Allocate memory for sorted profiles.
    UserProfile *sortedProfiles = malloc(userCount * sizeof(UserProfile));
    if (!sortedProfiles) return NULL;

    memcpy(sortedProfiles, profiles, userCount * sizeof(UserProfile));

    // Sort profiles based on the merge attribute.
    qsort_r(sortedProfiles, userCount, sizeof(UserProfile), compare_profiles, (const char *)mergeAttribute);

    // Allocate memory for merged profile list.
    MergedProfileList *mergedList = malloc(sizeof(MergedProfileList));
    if (!mergedList) {
        free(sortedProfiles);
        return NULL;
    }

    // Initialize the merged profile list with the first profile.
    mergedList->profiles = malloc(userCount * sizeof(UserProfile));
    if (!mergedList->profiles) {
        free(mergedList);
        free(sortedProfiles);
        return NULL;
    }

    size_t mergedIndex = 0;
    for (size_t i = 1; i < userCount; ++i) {
        // Compare current profile with the last added in the merged list.
        if (compare_profiles(&sortedProfiles[i], &mergedList->profiles[mergedIndex], mergeAttribute)) {
            // If different, add to the merged list.
            memcpy(&mergedList->profiles[++mergedIndex], &sortedProfiles[i], sizeof(UserProfile));
        }
    }

    mergedList->count = mergedIndex + 1;

    free(sortedProfiles);
    return mergedList->profiles;
}

// Example usage
int main() {
    UserProfile profiles[] = {
        {1, "Alice", "alice@example.com"},
        {2, "Bob", "bob@example.com"},
        {3, "Alice", "alice@sample.com"}
    };

    int userIds[] = {1, 2, 3};
    size_t userCount = sizeof(userIds) / sizeof(userIds[0]);

    UserProfile *mergedProfiles = merge_profiles(userIds, userCount, profiles, "name");

    if (mergedProfiles) {
        for (size_t i = 0; i < 2; ++i) { // Expected count is 2 after merging
            printf("Merged Profile: ID=%d, Name=%s, Email=%s\n", mergedProfiles[i].userId, mergedProfiles[i].name, mergedProfiles[i].email);
        }
    } else {
        printf("Memory allocation failed.\n");
    }

    // Free memory for the merged profiles if allocated
    free(mergedProfiles);

    return 0;
}
