#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_RETRY 5
#define INITIAL_BACKOFF_MS 100

typedef struct {
    int valid;
    // Additional fields for RX_UE_INFORMATION_TAG and RNTI as needed.
} RX_UE_INFORMATION_TAG;

typedef struct {
    int rnti;
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct MemoryStruct {
    char *memory;
    size_t size;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    mem->memory = realloc(mem->memory, mem->size + realsize + 1);
    if (mem->memory == NULL) {
        printf("not enough memory\n");
        return 0;
    }

    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

static CURL *create_curl_handle() {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to create CURL handle\n");
    }
    return curl;
}

static void fetch_ue_metadata(CURL *curl, char *url, struct MemoryStruct *chunk) {
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)chunk);

    int retries = 0;
    while (retries < MAX_RETRY) {
        CURLcode res = curl_easy_perform(curl);
        if (res == CURLE_OK) break;

        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
        sleep((1 << retries) * INITIAL_BACKOFF_MS / 1000.0); // Exponential backoff
        retries++;
    }

    if (retries == MAX_RETRY) {
        fprintf(stderr, "Failed to fetch UE metadata after %d attempts\n", MAX_RETRY);
    }
}

static void initialize_curl() {
    curl_global_init(CURL_GLOBAL_DEFAULT);
}

static void cleanup_curl(CURL *curl) {
    curl_easy_cleanup(curl);
    curl_global_cleanup();
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t num_pdus;
    pthread_mutex_t lock;
} PDU_Manager;

PDU_Manager* create_pdu_manager(size_t num_pdus) {
    PDU_Manager *manager = malloc(sizeof(PDU_Manager));
    manager->num_pdus = num_pdus;
    manager->pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void initialize_pdu_manager(PDU_Manager *manager) {
    for (size_t i = 0; i < manager->num_pdus; ++i) {
        manager->pdu_list[i].rnti = rand(); // Simulating RNTI assignment
        // Initialize RX_UE_INFORMATION_TAG and other fields as needed.
        manager->pdu_list[i].CRCFLAG = rand() % 2;
    }
}

void free_pdu_manager(PDU_Manager *manager) {
