#define MAX_API_REQUESTS 10

typedef struct {
    char RX_UE_INFORMATION_TAG[64];
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
    char access_token[256];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t count;
    pthread_mutex_t lock;
    int max_concurrent_requests;
} NFAPI_Manager;

void generate_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

NFAPI_Manager* create_nfa_manager(size_t num_pdus, int max_requests) {
    NFAPI_Manager *manager = malloc(sizeof(NFAPI_Manager));
    if (!manager) return NULL;

    manager->pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->pdus) {
        free(manager);
        return NULL;
    }

    manager->count = num_pdus;
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_concurrent_requests = max_requests;

    for (size_t i = 0; i < num_pdus; ++i) {
        snprintf(manager->pdus[i].RX_UE_INFORMATION_TAG, sizeof(manager->pdus[i].RX_UE_INFORMATION_TAG), "Tag_%zu", i);
        manager->pdus[i].RNTI = rand() % 1000;
        generate_random_crcflag(&manager->pdus[i]);

        if (oauth2_get_access_token(&(manager->pdus[i].access_token)) != 0) {
            log_error("Failed to retrieve access token for PDU index %zu", i);
        }
    }

    return manager;
}

void destroy_nfa_manager(NFAPI_Manager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager->pdus);
    free(manager);
}

void perform_api_request(NFAPI_CRC_INDICATION_PDU_T *pdu, int retry_count) {
    static const int base_delay = 100; // milliseconds

    while (retry_count >= 0) {
        if (api_call(pdu) == 0) { // Simulate an API call
            log_info("API request succeeded for RNTI: %d", pdu->RNTI);
            return;
        } else {
            log_warning("API request failed for RNTI: %d, retries left: %d", pdu->RNTI, retry_count);

            int delay = base_delay * (1 << (MAX_API_REQUESTS - 1 - retry_count));
            sleep_ms(delay); // Simulate exponential backoff

            retry_count--;
        }
    }

    log_error("API request failed for RNTI: %d after all retries", pdu->RNTI);
}

void* process_pdus(void *arg) {
    NFAPI_Manager *manager = (NFAPI_Manager *)arg;
    int requests_in_progress = 0;

    while (requests_in_progress < manager->max_concurrent_requests) {
        pthread_mutex_lock(&manager->lock);

        for (size_t i = 0; i < manager->count && requests_in_progress < manager->max_concurrent_requests; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->pdus[i];
            perform_api_request(pdu, 3); // Retry up to 3 times
            requests_in_progress++;
        }

        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

void process_pdus_concurrently(NFAPI_Manager *manager) {
    pthread_t threads[MAX_API_REQUESTS];
    for (int i = 0; i < MAX_API_REQUESTS; ++i) {
        if (pthread_create(&threads[i], NULL, process_pdus, manager) != 0) {
            log_error("Failed to create thread %d", i);
        }
    }

    for (int i = 0; i < MAX_API_REQUESTS; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    srand(time(NULL));
    int num_pdus = 20;
    int max_requests = 5;

    NFAPI_Manager *manager = create_nfa_manager(num_pdus, max_requests);
    if (!manager) {
        log_error("Failed to initialize NFAPI Manager");
        return 1;
    }

    process_pdus_concurrently(manager);

    destroy_nfa_manager(manager);
    return 0;
}
