    pthread_cond_t cond;   // Condition variable to handle resizing

    // Parameters for dynamic resizing and performance optimization
    size_t capacity;
    size_t initial_capacity;
    size_t resize_factor;
} ResizableList;

// Function prototypes
ResizableList* create_list(size_t initial_capacity, size_t resize_factor);
void destroy_list(ResizableList* list);
bool add_to_list(ResizableList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu);
size_t get_list_size(const ResizableList* list);
void export_to_binary_file(const ResizableList* list, const char* filename);

// Create a new resizable list
ResizableList* create_list(size_t initial_capacity, size_t resize_factor) {
    ResizableList* list = (ResizableList*)malloc(sizeof(ResizableList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);

    list->capacity = initial_capacity;
    list->initial_capacity = initial_capacity;
    list->resize_factor = resize_factor;

    return list;
}

// Destroy a resizable list
void destroy_list(ResizableList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Add a new PDU to the list
