    if (!validate_pdu(&pdu)) return false;

    pthread_mutex_lock(&list->lock);

    // Check if we need to resize
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * list->resize_factor;
        // This is a placeholder for actual resizing logic; it's handled by reallocating nodes
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Validate a PDU before adding to the list
bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
