        // Add more specific validation as needed
        return false;
    }
    return true;
}

// Get the size of the list
size_t get_list_size(const ResizableList* list) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    size_t size = list->size;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return size;
}

// Export the list to a binary file
void export_to_binary_file(const ResizableList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}

