    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void initArray(DynamicArray *a) {
    a->capacity = 10;
    a->used = 0;
    a->array = malloc(a->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!a->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&a->lock, NULL);
}

void destroyArray(DynamicArray *a) {
    free(a->array);
    pthread_mutex_destroy(&a->lock);
}

void ensureCapacity(DynamicArray *a) {
    if (a->used >= a->capacity) {
        size_t new_capacity = a->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;

        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(a->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        a->array = new_array;
        a->capacity = new_capacity;
    }
}

void addElement(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&a->lock);

    ensureCapacity(a);
    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);
}

int removeElement(DynamicArray *a, size_t index) {
    if (index >= a->used) return -1;

    pthread_mutex_lock(&a->lock);

    for (size_t i = index; i < a->used - 1; ++i) {
        a->array[i] = a->array[i + 1];
    }
    --a->used;

    pthread_mutex_unlock(&a->lock);
    return 0;
}

void iterateArray(DynamicArray *a, void (*func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&a->lock);

    for (size_t i = 0; i < a->used; ++i) {
        func(&a->array[i]);
    }

    pthread_mutex_unlock(&a->lock);
}

void randomizeCRCFLAG(NFAPI_CRC_INDICATION_PDU_T *element) {
    srand(time(NULL)); // Seed with current time
    element->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
}

