           element->RX_UE_INFORMATION_TAG,
           element->RNTI,
           element->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    DynamicArray a;
    initArray(&a);

    NFAPI_CRC_INDICATION_PDU_T newElement = {1, 100, {0}};
    randomizeCRCFLAG(&newElement);
    addElement(&a, newElement);

    iterateArray(&a, printElement);

    destroyArray(&a);
    return 0;
}
