#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct Node {
    CRC_INDICATION_REL8_TAG data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
    int log_level; // 0: None, 1: Error, 2: Info, 3: Debug
} List;

List* list_create(int log_level) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->log_level = log_level;
    return list;
}

void log_message(const char* message, int level, List* list) {
    if (level <= list->log_level) {
        printf("%s\n", message); // Replace with more sophisticated logging if needed
    }
}

int list_add(List* list, CRC_INDICATION_REL8_TAG item) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed", 0, list);
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    memcpy(&new_node->data, &item, sizeof(CRC_INDICATION_REL8_TAG));
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    log_message("Item added", 2, list); // Info level
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int list_remove(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node **curr = &list->head;
    while (*curr) {
        if ((*curr)->data.pdu.RNTI == RNTI) {
            Node* to_delete = *curr;
            *curr = (*curr)->next;

            free(to_delete);
            list->count--;
            log_message("Item removed", 2, list); // Info level
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        curr = &(*curr)->next;
    }

    log_message("RNTI not found for removal", 1, list); // Error level
    pthread_mutex_unlock(&list->lock);
    return -1;
}

CRC_INDICATION_REL8_TAG* list_get(List* list, int RNTI) {
    pthread_mutex_lock(&list->lock);

    Node* curr = list->head;
    while (curr) {
        if (curr->data.pdu.RNTI == RNTI) {
            CRC_INDICATION_REL8_TAG* item = malloc(sizeof(CRC_INDICATION_REL8_TAG));
            if (!item) {
                log_message("Memory allocation failed", 0, list);
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }

            memcpy(item, &curr->data, sizeof(CRC_INDICATION_REL8_TAG));
            log_message("Item retrieved", 2, list); // Info level
            pthread_mutex_unlock(&list->lock);
            return item;
        }
        curr = curr->next;
    }

    log_message("RNTI not found for retrieval", 1, list); // Error level
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void list_destroy(List* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example of setting a random CRCFLAG
void set_random_crcflag(CRC_INDICATION_REL8_TAG* tag) {
    if (tag) {
        tag->CRCFLAG = rand() % 256; // Random value between 0 and 255
    }
}
```

This code provides a thread-safe implementation for managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes functions to add, remove, and retrieve items from the list while handling memory allocation/deallocation efficiently. Logging levels are adjustable for performance tracking.']

