const fs = require('fs');
const path = require('path');

async function readFilesFromDirectory(directory) {
  const fileNames = await getFilePaths(directory);
  const concurrencyLimit = 5;

  let result = '';
  const semaphore = new Semaphore(concurrencyLimit);

  for (let fileName of fileNames) {
    await semaphore.acquire();
    processFile(fileName)
      .then((content) => {
        result += content;
        semaphore.release();
      })
      .catch(() => {
        console.error(`Error processing file: ${fileName}`);
        semaphore.release(); // Ensure release even on error
      });
  }

  return result;
}

function* getFilePaths(directory) {
  const entries = await fs.promises.readdir(directory, { withFileTypes: true });

  for (let entry of entries) {
    let fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      yield* getFilePaths(fullPath); // Recurse into subdirectories
    } else {
      yield fullPath;
    }
  }
}

async function processFile(filePath) {
  const content = await readFileWithBackpressure(filePath);
  return processContent(content);
}

async function readFileWithBackpressure(filePath) {
  return new Promise((resolve, reject) => {
    let chunks = [];
    const readStream = fs.createReadStream(filePath);

    readStream.on('data', (chunk) => {
      // Process chunk here if necessary
      chunks.push(chunk);
    });

    readStream.on('error', (err) => {
      console.error(`Error reading file: ${filePath}`, err);
      reject(err);
    });

    readStream.on('end', () => {
      resolve(Buffer.concat(chunks).toString());
    });
  });
}

function processContent(content) {
  // Implement your processing logic here
  return content;
}

class Semaphore {
  constructor(limit) {
    this.limit = limit;
    this.currentCount = limit;
    this.queue = [];
  }

  async acquire() {
    if (this.currentCount > 0) {
      this.currentCount--;
      return Promise.resolve();
    } else {
      return new Promise((resolve) => {
        this.queue.push(resolve);
      });
    }
  }

  release() {
    if (this.queue.length > 0) {
      const resolve = this.queue.shift();
      resolve();
    } else {
      this.currentCount++;
    }
  }
}

// Example usage
(async () => {
  try {
    const directoryPath = './your-directory';
    const concatenatedContent = await readFilesFromDirectory(directoryPath);
    console.log(concatenatedContent);
  } catch (error) {
    console.error('An error occurred:', error);
  }
})();
```

### Key Points:
- **Semaphore**: Manages concurrency to prevent resource exhaustion by limiting concurrent file reads.
- **Stream-based Reading**: Uses streams to handle large files efficiently without consuming excessive memory.
- **Error Handling**: Gracefully handles errors in file reading and processing, logging them while continuing with other files.
- **Recursive Directory Traversal**: Recursively fetches all file paths from the specified directory and its subdirectories."]

