#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define SUCCESS_CODE 0
#define GENERIC_ERROR_CODE -1

typedef enum {
    STATE_INITIALIZING,
    STATE_ACTIVE,
    STATE_IDLE,
    STATE_CLOSED
} ConnectionState;

typedef struct {
    size_t TX_BYTES;
    size_t RX_BYTES;
    time_t LAST_ACTIVITY_TIME;
    ConnectionState CURRENT_STATUS;
    int LAST_ERROR_CODE;
} TCP_CONNECTION_STATS;

typedef struct {
    TCP_CONNECTION_STATS *stats_array;
    size_t capacity;
    pthread_mutex_t array_mutex;
    pthread_rwlock_t rwlock;
} ConnectionStatsManager;

// Mock function to simulate resource management system integration
void report_usage(size_t memory_bytes) {
    // Implementation for reporting resource usage
}

// Log error message
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

ConnectionStatsManager* allocate_connection_stats(size_t M) {
    ConnectionStatsManager *manager = malloc(sizeof(ConnectionStatsManager));
    if (!manager) {
        log_error("Failed to allocate memory for manager.");
        return NULL;
    }

    pthread_mutex_init(&manager->array_mutex, NULL);
    pthread_rwlock_init(&manager->rwlock, NULL);

    // Attempt to allocate memory with a fallback mechanism
    size_t initial_capacity = M;
    while (initial_capacity > 0) {
        manager->stats_array = malloc(initial_capacity * sizeof(TCP_CONNECTION_STATS));
        if (manager->stats_array) {
            break;
        }
        log_error("Memory allocation failed, trying smaller size.");
        initial_capacity /= 2; // Reduce the request size
    }

    if (!manager->stats_array) {
        free(manager);
        pthread_mutex_destroy(&manager->array_mutex);
        pthread_rwlock_destroy(&manager->rwlock);
        log_error("Failed to allocate memory for connection stats after retries.");
        return NULL;
    }

    manager->capacity = initial_capacity;

    // Initialize the structures
    for (size_t i = 0; i < manager->capacity; ++i) {
        manager->stats_array[i].TX_BYTES = 0;
        manager->stats_array[i].RX_BYTES = 0;
        manager->stats_array[i].LAST_ACTIVITY_TIME = time(NULL);
        manager->stats_array[i].CURRENT_STATUS = STATE_INITIALIZING;
        manager->stats_array[i].LAST_ERROR_CODE = SUCCESS_CODE;

        // Validate the initialization
        if (manager->stats_array[i].TX_BYTES < 0 || 
            manager->stats_array[i].RX_BYTES < 0 ||
            manager->stats_array[i].CURRENT_STATUS > STATE_CLOSED) {
            log_error("Invalid state detected during initialization.");
        }
    }

    // Report resource usage to the resource management system
    report_usage(manager->capacity * sizeof(TCP_CONNECTION_STATS));

    return manager;
}

void free_connection_stats(ConnectionStatsManager *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->array_mutex);
        if (manager->stats_array) {
            free(manager->stats_array);
            manager->stats_array = NULL;
        }
        pthread_mutex_unlock(&manager->array_mutex);

        pthread_rwlock_destroy(&manager->rwlock);
        pthread_mutex_destroy(&manager->array_mutex);
        free(manager);
    }
}

// Example usage
int main() {
    size_t M = 1024; // Size determined at runtime
    ConnectionStatsManager *manager = allocate_connection_stats(M);

    if (manager) {
        printf("Connection stats manager allocated successfully.\n");
        free_connection_stats(manager);
    } else {
        printf("Failed to allocate connection stats manager.\n");
    }

    return 0;
}
```

### Key Points:

1. **Dynamic Allocation**: The function attempts to allocate memory for `M` structures and retries with a smaller size if the initial allocation fails.

2. **Thread Safety**: Uses a combination of mutexes and read-write locks to ensure thread-safe access while optimizing performance.

3. **Error Handling**: Logs errors on failure and provides a fallback mechanism by reducing the requested size.

4. **Resource Reporting**: Integrates with a mock resource management system to report memory usage.

5. **Initialization Validation**: Checks for invalid states during initialization.

6. **Extensibility**: The structure is designed to allow easy addition of new fields or structures.

7. **Resilience**: Includes basic retry logic and logging for failures in allocation.']

