#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdatomic.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[3];
    _Atomic int CRCFLAG; // atomic for concurrency safety
    time_t timestamp;    // to track the age of entries
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    unsigned int count;
} CRC_Indication_List;

CRC_Indication_List* create_list() {
    CRC_Indication_List *list = (CRC_Indication_List *)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;
    list->count = 0;
    memset(list->entries, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_ENTRIES);
    return list;
}

void free_list(CRC_Indication_List *list) {
    for (unsigned int i = 0; i < list->count; ++i) {
        if (list->entries[i]) {
            free(list->entries[i]);
        }
    }
    free(list);
}

int add_entry(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (list->count >= MAX_ENTRIES) return -1; // Out of space

    unsigned int idx = __sync_fetch_and_add(&list->count, 1); // atomic increment
    list->entries[idx] = entry;
    entry->timestamp = time(NULL);
    entry->CRCFLAG = rand() % 2; // Set CRCFLAG randomly to 0 or 1

    return 0;
}

int update_entry(CRC_Indication_List *list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T *entry) {
    for (unsigned int i = 0; i < list->count; ++i) {
        if (list->entries[i] && list->entries[i]->RNTI == rnti) {
            memcpy(list->entries[i], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return 0;
        }
    }
    return -1; // Not found
}

int remove_entry(CRC_Indication_List *list, uint16_t rnti) {
    for (unsigned int i = 0; i < list->count; ++i) {
        if (list->entries[i] && list->entries[i]->RNTI == rnti) {
            free(list->entries[i]);
            for (unsigned int j = i; j < list->count - 1; ++j) {
                list->entries[j] = list->entries[j + 1];
            }
            __sync_fetch_and_sub(&list->count, 1); // atomic decrement
            list->entries[list->count] = NULL;
            return 0;
        }
    }
    return -1; // Not found
}

void cleanup_old_entries(CRC_Indication_List *list) {
    time_t now = time(NULL);
    unsigned int idx = 0;

    while (idx < list->count) {
        if (list->entries[idx] && difftime(now, list->entries[idx]->timestamp) > 300) { // older than 5 minutes
            free(list->entries[idx]);
            for (; idx < list->count - 1; ++idx) {
                list->entries[idx] = list->entries[idx + 1];
            }
            __sync_fetch_and_sub(&list->count, 1); // atomic decrement
        } else {
            ++idx;
        }
    }
}

void* garbage_collector_thread(void *arg) {
    CRC_Indication_List *list = (CRC_Indication_List *)arg;
    while (1) {
        sleep(60); // Run every minute
        cleanup_old_entries(list);
    }
    return NULL;
}

int main() {
    CRC_Indication_List *list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to allocate list.\n");
        return EXIT_FAILURE;
    }

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collector_thread, (void*)list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) {
        fprintf(stderr, "Failed to allocate entry.\n");
        free_list(list);
        return EXIT_FAILURE;
    }
    entry->RX_UE_INFORMATION_TAG = 1;
    entry->RNTI = 100;

    add_entry(list, entry);

    // Simulate other operations
    sleep(10); // Wait for some time

    cleanup_old_entries(list);

    free_list(list);
    pthread_cancel(gc_thread);
    return EXIT_SUCCESS;
}
```

### Key Points:

- **Concurrency**: Uses atomic operations (`__sync_fetch_and_add`, `__sync_fetch_and_sub`) to handle concurrent modifications without locks.
- **Memory Management**: Manages a fixed-size array of pointers to entries, minimizing memory overhead and fragmentation.
- **Garbage Collection**: A background thread periodically cleans up old entries to manage memory usage effectively.
- **Error Handling**: Checks for out-of-memory conditions when creating the list or adding new entries.']

