    uint16_t rnti;
    // Add other necessary fields for PHY_RX_STATS
    _Atomic int phy_rx_flag;
} NFAPI_RX_PDU_T;

typedef struct Node {
    NFAPI_RX_PDU_T data;
    struct Node* next;
    time_t timestamp;
} Node;

typedef struct {
    Node* head;
    atomic_size_t size;
    pthread_mutex_t cleanup_lock;
} DynamicList;

DynamicList list = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

Node* create_node(NFAPI_RX_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    node->next = NULL;
    node->timestamp = time(NULL);
    return node;
}

void add_or_update_entry(uint16_t rnti, NFAPI_RX_PDU_T new_data) {
    Node* current = list.head;
    Node* prev = NULL;

    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        Node* node = create_node(new_data);
        if (!node) return;

        atomic_fetch_add_explicit(&list.size, 1, memory_order_relaxed);

        if (prev == NULL) {
            node->next = list.head;
            list.head = node;
        } else {
            prev->next = node;
            node->next = current;
        }
    } else {
        memcpy(&current->data, &new_data, sizeof(NFAPI_RX_PDU_T));
    }
}

void remove_entry(uint16_t rnti) {
    Node* current = list.head;
    Node* prev = NULL;

    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (prev == NULL) {
        list.head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    atomic_fetch_sub_explicit(&list.size, 1, memory_order_relaxed);
}

void* cleanup_task(void* arg) {
    while (1) {
        pthread_mutex_lock(&list.cleanup_lock);

        time_t now = time(NULL);
        Node* current = list.head;
        Node* prev = NULL;

        while (current != NULL) {
            if (difftime(now, current->timestamp) > 600) { // 10 minutes
                if (prev == NULL) {
                    list.head = current->next;
                } else {
                    prev->next = current->next;
                }

                Node* temp = current;
                current = current->next;
                free(temp);
                atomic_fetch_sub_explicit(&list.size, 1, memory_order_relaxed);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list.cleanup_lock);

        sleep(300); // Run cleanup every 5 minutes
    }

    return NULL;
}

void initialize_list() {
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_task, NULL);
}

int main() {
    initialize_list();

    NFAPI_RX_PDU_T pdu = { .rx_ue_information_tag = 1, .rnti = 1234, ._Atomic.int phy_rx_flag = 0 };
    add_or_update_entry(pdu.rnti, pdu);

