import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;

public class CertificateHandler {

    private static final String PEM_HEADER = "-----BEGIN CERTIFICATE-----\n";
    private static final String PEM_FOOTER = "\n-----END CERTIFICATE-----";

    public CompletableFuture<String> generatePemCertificateAsync(String privateKeyPath, String certificatePath) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                String privateKey = new String(Files.readAllBytes(Paths.get(privateKeyPath)));
                String certificate = new String(Files.readAllBytes(Paths.get(certificatePath)));

                StringBuilder pemBuilder = new StringBuilder();
                pemBuilder.append("-----BEGIN PRIVATE KEY-----\n");
                pemBuilder.append(formatBase64Lines(privateKey));
                pemBuilder.append("\n-----END PRIVATE KEY-----\n");

                pemBuilder.append(PEM_HEADER);
                pemBuilder.append(formatBase64Lines(certificate));
                pemBuilder.append(PEM_FOOTER);

                return pemBuilder.toString();
            } catch (IOException e) {
                throw new RuntimeException("Error accessing certificate files", e);
            }
        });
    }

    public String computeMd5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

    private String formatBase64Lines(String data) {
        StringBuilder formatted = new StringBuilder();
        for (int i = 0; i < data.length(); i += 64) {
            if (i + 64 > data.length()) {
                formatted.append(data.substring(i));
            } else {
                formatted.append(data, i, i + 64);
            }
            formatted.append("\n");
        }
        return formatted.toString();
    }

    public static void main(String[] args) throws ExecutionException, InterruptedException {
        CertificateHandler handler = new CertificateHandler();

        // Example usage
        CompletableFuture<String> pemFuture = handler.generatePemCertificateAsync("path/to/privateKey.pem", "path/to/certificate.pem");
        String pemCertificate = pemFuture.get();
        System.out.println(pemCertificate);

        String md5Hash = handler.computeMd5Hash("exampleString");
        System.out.println(md5Hash);
    }
}
