// Function to initialize the dynamic array
int initMeasurementReportArray(MeasurementReportArray *arr, size_t initial_capacity) {
    if (!arr || initial_capacity == 0) return -1;

    arr->array = malloc(initial_capacity * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
    if (arr->array == NULL) return -2;  // Memory allocation failed

    arr->size = 0;
    arr->capacity = initial_capacity;
    pthread_mutex_init(&arr->lock, NULL);

    return 0;
}

// Function to safely resize the array
int resizeMeasurementReportArray(MeasurementReportArray *arr, size_t new_capacity) {
    if (!arr || new_capacity <= arr->capacity) return -1;

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T *new_array = realloc(arr->array, new_capacity * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
    if (new_array == NULL) return -2;  // Memory allocation failed

    arr->array = new_array;
    arr->capacity = new_capacity;

    return 0;
}

// Function to add a report entry
int addMeasurementReport(MeasurementReportArray *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size == arr->capacity) {
        int resize_result = resizeMeasurementReportArray(arr, arr->capacity * 2);
        if (resize_result != 0) {
            pthread_mutex_unlock(&arr->lock);
            return -1;  // Resize failed
        }
    }

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = rand();  // Random value for example purposes
    entry.RNTI = rand();
    entry.PHY_MEASUREMENT_TAG = (float)rand() / RAND_MAX * 100.0;  // Random value in range [0.0, 100.0]

    arr->array[arr->size++] = entry;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to periodically clean up unused entries
void cleanupMeasurementReportArray(MeasurementReportArray *arr) {
    // Implementation for cleanup, e.g., removing stale entries if applicable
}

// Function to export the contents of the array
int exportMeasurementReports(MeasurementReportArray *arr, NFAPI_RRC_MEASUREMENT_REPORT_PDU_T **out_array, size_t *out_size) {
    pthread_mutex_lock(&arr->lock);

    *out_array = malloc(arr->size * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
    if (*out_array == NULL) {
        pthread_mutex_unlock(&arr->lock);
        return -1;  // Memory allocation failed
    }

    memcpy(*out_array, arr->array, arr->size * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
    *out_size = arr->size;

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to free resources associated with the array
void destroyMeasurementReportArray(MeasurementReportArray *arr) {
    if (arr) {
        pthread_mutex_destroy(&arr->lock);
        free(arr->array);
        arr->array = NULL;
        arr->size = 0;
        arr->capacity = 0;
    }
}

// Example main function to demonstrate usage
