        if (addMeasurementReport(&reportArray) != 0) {
            fprintf(stderr, "Failed to add a measurement report\n");
            break;
        }
    }

    cleanupMeasurementReportArray(&reportArray);

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T *exportedReports = NULL;
    size_t exportedSize = 0;
    if (exportMeasurementReports(&reportArray, &exportedReports, &exportedSize) == 0) {
