void destroy_dynamic_array(DynamicArray *dynamic_array) {
    if (dynamic_array) {
        free(dynamic_array->array);
        pthread_mutex_destroy(&dynamic_array->lock);
        free(dynamic_array);
    }
}

int add_measurement(DynamicArray *dynamic_array, int rx_ue_info_tag, int rnti) {
    if (!dynamic_array) return -1;

    pthread_mutex_lock(&dynamic_array->lock);

    if (dynamic_array->count >= dynamic_array->capacity) {
        size_t new_capacity = dynamic_array->capacity * 2;
        if (new_capacity > MAX_ENTRIES) {
            printf("Reached maximum capacity for dynamic array\n");
            pthread_mutex_unlock(&dynamic_array->lock);
            return -1; // Limit exceeded
        }

        NFAPI_RRC_MEASUREMENT_REPORT_PDU_T *temp = realloc(dynamic_array->array, new_capacity * sizeof(NFAPI_RRC_MEASUREMENT_REPORT_PDU_T));
        if (!temp) {
            perror("Failed to reallocate memory for dynamic array");
            pthread_mutex_unlock(&dynamic_array->lock);
            return -1;
        }

        dynamic_array->array = temp;
        dynamic_array->capacity = new_capacity;
    }

    NFAPI_RRC_MEASUREMENT_REPORT_PDU_T *entry = &dynamic_array->array[dynamic_array->count];

    entry->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    entry->RNTI = rnti;

    if (fetch_measurement_value(&entry->PHY_MEASUREMENT_TAG) != 0) {
        perror("Failed to fetch measurement value");
        pthread_mutex_unlock(&dynamic_array->lock);
        return -1; // Error fetching the measurement
    }

    dynamic_array->count++;

    pthread_mutex_unlock(&dynamic_array->lock);

    printf("Added measurement: RX_UE_INFORMATION_TAG=%d, RNTI=%d, PHY_MEASUREMENT_TAG=%.2f\n",
           rx_ue_info_tag, rnti, entry->PHY_MEASUREMENT_TAG);

    return 0;
}

int main() {
    DynamicArray *dynamic_array = create_dynamic_array(10);

    if (!dynamic_array) {
        fprintf(stderr, "Failed to initialize dynamic array\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 15; ++i) { // Attempt to add more than initial capacity
        if (add_measurement(dynamic_array, i + 1, i * 10) != 0) {
            fprintf(stderr, "Error adding measurement for index %d\n", i);
        }
    }

    destroy_dynamic_array(dynamic_array);

    return EXIT_SUCCESS;
}
```

