#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>
#include <openssl/sha.h>
#include <openssl/hmac.h>

#define AES_KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[IV_SIZE];
    int is_initialized;
    pthread_mutex_t mutex;
} CipherContext;

CipherContext* cipher_context_init() {
    CipherContext *ctx = (CipherContext *)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (!ctx->cipher_ctx) {
        free(ctx);
        return NULL;
    }

    pthread_mutex_init(&ctx->mutex, NULL);
    ctx->is_initialized = 0;

    return ctx;
}

int derive_key_and_iv(const char *password, const unsigned char *salt, int salt_len,
                      unsigned char *key, unsigned char *iv, const EVP_MD *md,
                      int iterations) {
    if (!EVP_BytesToKey(md, NULL, salt, (unsigned char *)password, strlen(password),
                        iterations, key, iv)) {
        return 0;
    }
    return 1;
}

int cipher_context_set_key_iv(CipherContext *ctx, const unsigned char *key,
                              const unsigned char *iv) {
    if (!ctx || !ctx->cipher_ctx) return 0;

    pthread_mutex_lock(&ctx->mutex);
    memcpy(ctx->key, key, AES_KEY_SIZE);
    memcpy(ctx->iv, iv, IV_SIZE);

    EVP_CIPHER_CTX_init(ctx->cipher_ctx);
    int success = EVP_EncryptInit_ex(ctx->cipher_ctx, EVP_aes_256_cbc(), NULL,
                                     ctx->key, ctx->iv) == 1;

    pthread_mutex_unlock(&ctx->mutex);
    return success;
}

int cipher_context_encrypt(CipherContext *ctx, const unsigned char *plaintext, int plaintext_len,
                           unsigned char *ciphertext, int *ciphertext_len) {
    if (!ctx || !ctx->cipher_ctx || ctx->is_initialized == 0) return 0;

    pthread_mutex_lock(&ctx->mutex);
    int len;
    int ciphertext_size = *ciphertext_len;

    if (1 != EVP_EncryptInit_ex(ctx->cipher_ctx, NULL, NULL, NULL, NULL)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }

    if (1 != EVP_EncryptUpdate(ctx->cipher_ctx, ciphertext, &len, plaintext,
                               plaintext_len)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }
    *ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx->cipher_ctx, ciphertext + len, &len)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }
    *ciphertext_len += len;

    pthread_mutex_unlock(&ctx->mutex);
    return 1;
}

int cipher_context_decrypt(CipherContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                           unsigned char *plaintext, int *plaintext_len) {
    if (!ctx || !ctx->cipher_ctx || ctx->is_initialized == 0) return 0;

    pthread_mutex_lock(&ctx->mutex);
    int len;
    int plaintext_size = *plaintext_len;

    if (1 != EVP_DecryptInit_ex(ctx->cipher_ctx, NULL, NULL, NULL, NULL)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }

    if (1 != EVP_DecryptUpdate(ctx->cipher_ctx, plaintext, &len, ciphertext,
                               ciphertext_len)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }
    *plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx->cipher_ctx, plaintext + len, &len)) {
        pthread_mutex_unlock(&ctx->mutex);
        return 0;
    }
    *plaintext_len += len;

    pthread_mutex_unlock(&ctx->mutex);
    return 1;
}

int cipher_context_cleanup(CipherContext *ctx) {
    if (!ctx) return 0;

    if (ctx->cipher_ctx) EVP_CIPHER_CTX_free(ctx->cipher_ctx);

    pthread_mutex_destroy(&ctx->mutex);
    free(ctx);

    return 1;
}

int compute_hmac(const unsigned char *key, int key_len,
                 const unsigned char *data, int data_len,
                 unsigned char *hmac_out) {
    unsigned int len = SHA256_DIGEST_LENGTH;
    HMAC_CTX *hmac_ctx = HMAC_CTX_new();
    if (!hmac_ctx) return 0;

    HMAC_Init_ex(hmac_ctx, key, key_len, EVP_sha256(), NULL);
    HMAC_Update(hmac_ctx, data, data_len);
    HMAC_Final(hmac_ctx, hmac_out, &len);

    HMAC_CTX_free(hmac_ctx);
    return 1;
}

int verify_hmac(const unsigned char *key, int key_len,
                const unsigned char *data, int data_len,
                const unsigned char *hmac_in) {
    unsigned char computed_hmac[SHA256_DIGEST_LENGTH];
    if (!compute_hmac(key, key_len, data, data_len, computed_hmac)) return 0;

    return CRYPTO_memcmp(computed_hmac, hmac_in, SHA256_DIGEST_LENGTH) == 0;
}

// Example usage
int main() {
    const char *password = "securepassword";
    unsigned char salt[16];
    RAND_bytes(salt, sizeof(salt));

    CipherContext *ctx = cipher_context_init();
    if (!ctx) return -1;

    if (!derive_key_and_iv(password, salt, sizeof(salt), ctx->key, ctx->iv,
                           EVP_sha256(), 10000)) {
        fprintf(stderr, "Key derivation failed\n");
        goto cleanup;
    }

    int ciphertext_len, plaintext_len;
    unsigned char *ciphertext = malloc(128); // Adjust size as needed
    unsigned char *plaintext = malloc(128); // Adjust size as needed

    if (!cipher_context_set_key_iv(ctx, ctx->key, ctx->iv)) {
        fprintf(stderr, "Cipher context setup failed\n");
        goto cleanup;
    }

    const unsigned char *data = (unsigned char *)"This is a test message.";
    int data_len = strlen((char *)data);

    if (!cipher_context_encrypt(ctx, data, data_len, ciphertext, &ciphertext_len)) {
        fprintf(stderr, "Encryption failed\n");
        goto cleanup;
    }

    if (!cipher_context_decrypt(ctx, ciphertext, ciphertext_len, plaintext,
                                &plaintext_len)) {
        fprintf(stderr, "Decryption failed\n");
        goto cleanup;
    }

    printf("Original: %s\n", data);
    printf("Decrypted: %.*s\n", plaintext_len, plaintext);

cleanup:
    free(ciphertext);
    free(plaintext);
    cipher_context_cleanup(ctx);
    return 0;
}
```

