FrameHeader* create_frame_headers(int count, size_t max_frame_length) {
    if (count <= 0 || max_frame_length == 0) {
        fprintf(stderr, "Invalid frame header count or maximum frame length.\n");
        return NULL;
    }

    // Allocate memory for the array of FrameHeaders
    FrameHeader* frames = malloc(count * sizeof(FrameHeader));
    if (!frames) {
        perror("Failed to allocate memory for frame headers");
        return NULL;
    }

    // Populate each FrameHeader with data
    for (int i = 0; i < count; ++i) {
        FrameHeader *frame = &frames[i];

        frame->timestamp = get_timestamp();
        format_mac_header(frame->macHeader);
        frame->num_segments = 0;

        size_t total_length = sizeof(frame->timestamp) + strlen(frame->macHeader);

        for (int j = 0; j < MAX_PAYLOAD_SEGMENTS && frame->num_segments < MAX_PAYLOAD_SEGMENTS; ++j) {
            // Simulate retrieving data from an external source
            size_t segment_length = rand() % 256 + 1; // Random length between 1 and 256

            if (total_length + sizeof(PayloadSegment) + segment_length > max_frame_length) {
                break; // Exceeds maximum allowed frame length, stop adding segments
            }

            PayloadSegment *segment = &frame->segments[frame->num_segments];
            segment->sequence_number = i * MAX_PAYLOAD_SEGMENTS + j;
            segment->length = segment_length;

            total_length += sizeof(PayloadSegment) + segment_length;
            ++(frame->num_segments);
        }
    }

    return frames;
}

// Function to free the dynamically allocated array of FrameHeaders.
void free_frame_headers(FrameHeader* frames, int count) {
    if (frames) {
        free(frames); // In this example, no additional dynamic memory was used within each frame
    }
}
