#include <pthread.h>
#include <time.h>
#include <math.h>

#define SHA256_DIGEST_LENGTH 32
#define AES_KEYLEN 256
#define IV_LEN 16
#define MAX_LIST_SIZE 1000
#define TIME_THRESHOLD (60 * 60) // One hour in seconds

typedef struct {
    float value;
} Transaction;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
    time_t timestamp; // For LRU mechanism
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NF_API_CRC_NODE;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NF_API_CRC_NODE* head = NULL;

EVP_CIPHER_CTX *init_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = malloc(sizeof(EVP_CIPHER_CTX));
    if (!ctx) return NULL;

    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key);

    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Error initializing encryption context\n");
        free(ctx);
        return NULL;
    }

    unsigned char iv[IV_LEN];
    if (!RAND_bytes(iv, IV_LEN)) {
        fprintf(stderr, "Error generating random bytes for IV\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ctx);
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, (unsigned char*)iv)) {
        fprintf(stderr, "Error initializing encryption with IV\n");
        EVP_CIPHER_CTX_free(ctx);
        free(ctx);
        return NULL;
    }

    printf("AES-256-CBC initialized successfully.\n");
    return ctx;
}

void cleanup_list() {
    pthread_mutex_lock(&list_mutex);

    time_t current_time = time(NULL);
    NF_API_CRC_NODE *prev = NULL, *curr = head;

    while (curr) {
        if ((current_time - curr->timestamp) > TIME_THRESHOLD || 
            (head && list_size > MAX_LIST_SIZE)) { // Assuming we have a global list size counter
            NF_API_CRC_NODE *to_delete = curr;

            if (prev)
                prev->next = curr->next;
            else
                head = curr->next;

            free(to_delete);
        } else {
            prev = curr;
        }

        curr = curr->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void add_crc_node(unsigned int rx_ue_info_tag, unsigned int rnti) {
    NF_API_CRC_NODE *new_node = malloc(sizeof(NF_API_CRC_NODE));

    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        return;
    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->RNTI = rnti;
    new_node->CRCFLAG = rand() % 2; // Random CRC flag
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);

    if (!head) {
        head = new_node;
    } else {
        NF_API_CRC_NODE *curr = head;
        while (curr->next)
            curr = curr->next;

        curr->next = new_node;
    }

    // Increase list size counter
    pthread_mutex_unlock(&list_mutex);
}

void calculate_statistics(double numbers[], size_t count, double *mean, double *std_dev) {
    if (!numbers || !mean || !std_dev) return;

    double sum = 0.0;
    for (size_t i = 0; i < count; ++i)
        sum += numbers[i];

    *mean = sum / count;

    double variance_sum = 0.0;
    for (size_t i = 0; i < count; ++i)
        variance_sum += pow(numbers[i] - *mean, 2);

    *std_dev = sqrt(variance_sum / count);
}

void print_statistics(double numbers[], size_t count) {
    double mean, std_dev;
    calculate_statistics(numbers, count, &mean, &std_dev);

    printf("Mean: %f\n", mean);
    printf("Standard Deviation: %f\n", std_dev);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    const char *password = "secure_password";
    EVP_CIPHER_CTX *cipher_ctx = init_aes_cipher(password);

    if (!cipher_ctx) {
        fprintf(stderr, "Failed to initialize cipher context.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    double numbers[10000];
    for (size_t i = 0; i < 10000; ++i)
        numbers[i] = ((double) rand() / RAND_MAX) * 100.0;

    print_statistics(numbers, 10000);

    cleanup_list();

    // Cleanup
    EVP_CIPHER_CTX_free(cipher_ctx);
    free(cipher_ctx);

    return EXIT_SUCCESS;
}
