    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function prototype
void log_crc_status(const NFAPI_CRC_INDICATION_PDU_T *pdu, int status);

// Mutex for thread-safe operations
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **pdus;
    size_t length;
} CRCIndicationList;

CRCIndicationList* create_crc_indication_list(size_t len) {
    if (len == 0) return NULL;

    // Allocate aligned memory
    NFAPI_CRC_INDICATION_PDU_T **pdus = aligned_alloc(alignof(NFAPI_CRC_INDICATION_PDU_T), len * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!pdus) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize list
    CRCIndicationList *list = malloc(sizeof(CRCIndicationList));
    if (!list) {
        free(pdus);
        perror("Memory allocation failed");
        return NULL;
    }

    memset(list, 0, sizeof(CRCIndicationList));
    list->pdus = pdus;
    list->length = len;

    for (size_t i = 0; i < len; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = aligned_alloc(alignof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            for (size_t j = 0; j < i; ++j) free(list->pdus[j]);
            free(list->pdus);
            free(list);
            perror("Memory allocation failed");
            return NULL;
        }
        list->pdus[i] = pdu;

        // Initialize fields with random CRCFLAG
        pdu->ue_info_tag = (RX_UE_INFORMATION_TAG){};
        pdu->rnti = rand();  // Simplified example
        pdu->crc_indication_rel8_tag.CRCFLAG = rand() % 2;  // Randomly set to 0 or 1
    }

    return list;
}

void destroy_crc_indication_list(CRCIndicationList *list) {
    if (!list) return;

    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < list->length; ++i) {
        free(list->pdus[i]);
    }
    free(list->pdus);
    free(list);
    pthread_mutex_unlock(&list_mutex);
}

void log_crc_status(const NFAPI_CRC_INDICATION_PDU_T *pdu, int status) {
    // Example logging implementation
    printf("RNTI: %u, CRCFLAG: %d, Status: %s\n", pdu->rnti, pdu->crc_indication_rel8_tag.CRCFLAG,
           status ? "Success" : "Failure");
}

void process_crc_list(CRCIndicationList *list) {
    if (!list) return;

    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < list->length; ++i) {
        // Simulate processing and logging
