#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define MAX_CONCURRENT_UPDATES 100

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashNode {
    unsigned int rnti;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned int hash(unsigned int rnti, size_t size) {
    return rnti % size;
}

HashTable* create_hash_table(size_t size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    ht->table = (HashNode**)calloc(size, sizeof(HashNode*));
    if (!ht->table) {
        free(ht);
        perror("Failed to allocate memory for hash table buckets");
        exit(EXIT_FAILURE);
    }
    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        HashNode* node = ht->table[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp->pdu);
            free(temp);
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

void insert_into_hash_table(HashTable* ht, unsigned int rnti, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hash(rnti, ht->size);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    if (!newNode) {
        perror("Failed to allocate memory for hash node");
        pthread_mutex_unlock(&ht->lock);
        exit(EXIT_FAILURE);
    }
    newNode->rnti = rnti;
    newNode->pdu = pdu;
    newNode->next = ht->table[index];
    ht->table[index] = newNode;
    pthread_mutex_unlock(&ht->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_in_hash_table(HashTable* ht, unsigned int rnti) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hash(rnti, ht->size);
    HashNode* node = ht->table[index];
    while (node) {
        if (node->rnti == rnti) {
            pthread_mutex_unlock(&ht->lock);
            return node->pdu;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void update_rnti(HashTable* ht, unsigned int oldRnti, unsigned int newRnti) {
    pthread_mutex_lock(&ht->lock);
    HashNode** bucket = &ht->table[hash(oldRnti, ht->size)];
    while (*bucket) {
        if ((*bucket)->rnti == oldRnti) {
            (*bucket)->rnti = newRnti;
            unsigned int newIndex = hash(newRnti, ht->size);
            if (newIndex != hash(oldRnti, ht->size)) {
                HashNode* nodeToMove = *bucket;
                *bucket = (*bucket)->next;
                nodeToMove->next = ht->table[newIndex];
                ht->table[newIndex] = nodeToMove;
            }
            pthread_mutex_unlock(&ht->lock);
            return;
        }
        bucket = &(*bucket)->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

void initialize_pdu_list(HashTable* ht, size_t num_entries) {
    srand(time(NULL));
    for (size_t i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Failed to allocate memory for PDU");
            exit(EXIT_FAILURE);
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu->RNTI = rand() % 10000;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;
        insert_into_hash_table(ht, pdu->RNTI, pdu);
    }
}

void cleanup_pdu_list(HashTable* ht) {
    destroy_hash_table(ht);
}

int main() {
    HashTable* ht = create_hash_table(1024); // Choose a prime number for better distribution
    initialize_pdu_list(ht, MAX_ENTRIES);

    // Simulate updates
    update_rnti(ht, 1234, 5678);

    // Cleanup
    cleanup_pdu_list(ht);
    return 0;
}
```

### Key Features:
- **Hash Table**: Used for efficient RNTI lookups and insertions.
- **Thread Safety**: Managed with `pthread_mutex_t` to ensure safe concurrent access.
- **Memory Management**: Dynamic allocation with error handling to prevent leaks and overflows.
- **Random Initialization**: CRCFLAG is randomly set, simulating real-world data variability.
- **Scalability**: Designed to handle up to 10,000 entries efficiently.

This code provides a robust foundation for managing NFAPI_CRC_INDICATION_PDU_T structures in high-performance environments. Adjust the hash table size and other parameters based on specific application needs.']

