int generate_unique_string(char *result, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char temp[ALPHANUMERIC_LEN + 1];

    // Generate random string
    for (size_t n = 0; n < length; ++n) {
        int key = rand() % (sizeof(charset) - 1);
        temp[n] = charset[key];
    }
    temp[length] = '\0';

    pthread_mutex_lock(&local_cache.lock);

    // Check uniqueness
    for (int i = 0; i < ALPHANUMERIC_LEN; ++i) {
        if (strcmp(local_cache.unique_strings[i], temp) == 0) {
            pthread_mutex_unlock(&local_cache.lock);
            return -1; // Not unique, retry generation
        }
    }

    strcpy(result, temp);

    // Store the new string in a circular manner
    static int index = 0;
    strncpy(local_cache.unique_strings[index], result, 128);
    index = (index + 1) % ALPHANUMERIC_LEN;

    pthread_mutex_unlock(&local_cache.lock);
    return 0; // Unique
}

void hash_password(const char *password, unsigned char *output_hash) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(output_hash, &sha256);
}

