        result.pdu_list[i].CRC_INDICATION_REL8_TAG[2] = rand() % 256;
        result.pdu_list[i].CRCFLAG = rand() % 2; // Random 0 or 1
    }

    // Step 2: Generate a unique alphanumeric string
    if (generate_unique_string(result.unique_string, ALPHANUMERIC_LEN) != 0) {
        free(result.pdu_list);
        result.pdu_list = NULL;
        return result;
    }

