// Define the PDCP_PDU_TYPE enum as per your protocol specifications.
typedef enum {
    TYPE1,
    TYPE2,
    // Add other types as needed
} PDCP_PDU_TYPE;

// Structure to hold a Protocol Data Unit (PDU)
typedef struct {
    PDCP_PDU_TYPE pdu_type;
    uint16_t pdcp_sn;     // Sequence Number for PDCP
    int mac_sn;           // MAC Sequence Number
} MAC_PDU_T;

// Dynamic array structure with thread safety considerations.
typedef struct {
    MAC_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;  // Mutex for thread safety
    uint16_t next_pdc_sn;  // Incremental PDCP SN
} PDU_Array;

// Function to initialize and configure the dynamic array of PDUs.
int init_pdu_array(PDU_Array *array, size_t initial_capacity) {
    if (!array) return -1;

    pthread_mutex_init(&array->lock, NULL);
    array->pdus = (MAC_PDU_T *)aligned_alloc(64, initial_capacity * sizeof(MAC_PDU_T));
    if (!array->pdus) {
        perror("Failed to allocate memory for PDUs");
        pthread_mutex_destroy(&array->lock);
        return -1;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    array->next_pdc_sn = 0;

    // Initialize MAC_SN field to zero
    for (size_t i = 0; i < initial_capacity; ++i) {
        array->pdus[i].mac_sn = 0;
    }

    return 0;
}

// Function to safely update PDCP_SN upon receipt of each new PDU.
int update_pdu_sn(PDU_Array *array, PDCP_PDU_TYPE pdu_type, int mac_sn) {
    if (!array || array->count >= array->capacity)
        return -1;

    pthread_mutex_lock(&array->lock);

    // Allocate more space if needed
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDU_T *new_pdus = (MAC_PDU_T *)aligned_realloc(array->pdus, 64, new_capacity * sizeof(MAC_PDU_T));
        if (!new_pdus) {
            perror("Failed to reallocate memory for PDUs");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->pdus = new_pdus;
        array->capacity = new_capacity;

        // Initialize new MAC_SN fields
        for (size_t i = array->count; i < new_capacity; ++i) {
            array->pdus[i].mac_sn = 0;
        }
    }

    // Update PDCP_SN and other fields safely.
    size_t index = array->count++;
    array->pdus[index].pdu_type = pdu_type;
    array->pdus[index].pdcp_sn = array->next_pdc_sn++;
    array->pdus[index].mac_sn = mac_sn;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to free the allocated memory for the PDU Array.
void destroy_pdu_array(PDU_Array *array) {
    if (!array) return;

    pthread_mutex_destroy(&array->lock);
    free(array->pdus); // Use aligned_free if using aligned_alloc
}
