    CRC_INDICATION_PDU_T crc_pdu;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
    struct NFAPI_CRC_INDICATION_PDU_T* prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count;
    size_t max_size;
} DynamicLinkedList;

// Helper function to create a new node
NFAPI_CRC_INDICATION_PDU_T* create_node(int rnti, int crc_indication_tag) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return NULL;

    new_node->ue_info_tag.RNTI = rnti;
    new_node->ue_info_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    new_node->crc_pdu.CRC_INDICATION_REL8_TAG = crc_indication_tag;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

// Helper function to check if RNTI exists in the list
int rnti_exists(DynamicLinkedList* list, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        if (current->ue_info_tag.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

// Helper function to remove the least recently used element
void remove_lru(DynamicLinkedList* list) {
    if (!list->head) return;

    NFAPI_CRC_INDICATION_PDU_T* lru_node = list->head;
    if (lru_node == list->tail) { // Only one element in the list
        list->head = NULL;
        list->tail = NULL;
    } else {
        list->head = lru_node->next;
        list->head->prev = NULL;
    }
    free(lru_node);
    list->count--;
}

// Function to add a new node ensuring unique RNTI and handling maximum size
int add_to_list(DynamicLinkedList* list, int rnti, int crc_indication_tag) {
    if (rnti_exists(list, rnti)) {
        printf("Error: Duplicate RNTI detected. Skipping insertion.\n");
        return -1;
    }

    if (list->count >= list->max_size) {
        remove_lru(list);
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(rnti, crc_indication_tag);
    if (!new_node) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    // Insert the new node at the end (most recently used position)
    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
    }
    list->count++;

    return 0; // Success
}

// Function to initialize the linked list
void init_list(DynamicLinkedList* list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
}

// Function to free the linked list resources
void free_list(DynamicLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = current->next;
        free(current);
        current = next_node;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

int main() {
    DynamicLinkedList list;
    init_list(&list, 5); // Example maximum size of 5

    add_to_list(&list, 1001, 123);
    add_to_list(&list, 1002, 456);
    add_to_list(&list, 1003, 789);
    add_to_list(&list, 1004, 101112);
    add_to_list(&list, 1005, 131415);

    // This will trigger LRU removal
    add_to_list(&list, 1006, 161718);

    // Attempt to add a duplicate RNTI
    add_to_list(&list, 1002, 192021);

    free_list(&list);
    return 0;
}
