['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 100
#define EXPIRY_TIME 1800 // 30 minutes in seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Unique identifier for the element
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set flag
    time_t timestamp; // For tracking expiration
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
    unsigned long access_count; // Used for cache eviction policy
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_element(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    // Check for expiry
    time_t now = time(NULL);
    Node* current = list->head;
    while (current) {
        if (now - current->data.timestamp > EXPIRY_TIME) {
            Node* to_remove = current;
            current = current->next;

            if (to_remove == list->head) {
                list->head = to_remove->next;
                if (list->head) list->head->prev = NULL;
            } else {
                to_remove->prev->next = to_remove->next;
            }

            if (to_remove == list->tail) {
                list->tail = to_remove->prev;
                if (list->tail) list->tail->next = NULL;
            } else {
                to_remove->next->prev = to_remove->prev;
            }

            free(to_remove);
            --list->size;
        } else {
            current = current->next;
        }
    }

    // Check for unique RNTI
    Node* current_node = list->head;
    while (current_node) {
        if (current_node->data.RNTI == element.RNTI) {
            printf("Error: Duplicate RNTI detected, skipping insertion.\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current_node = current_node->next;
    }

    // Insert new element
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = element;
    new_node->data.timestamp = time(NULL);
    new_node->prev = list->tail;
    new_node->next = NULL;
    new_node->access_count = 0;

    if (list->size >= MAX_ELEMENTS) {
        Node* oldest = list->head;
        for (Node* node = list->head; node && node->next; node = node->next) {
            if (node->access_count < oldest->access_count) {
                oldest = node;
            }
        }

        if (oldest == list->head) {
            list->head = oldest->next;
            if (list->head) list->head->prev = NULL;
        } else {
            oldest->prev->next = oldest->next;
        }

        if (oldest == list->tail) {
            list->tail = oldest->prev;
            if (list->tail) list->tail->next = NULL;
        } else {
            oldest->next->prev = oldest->prev;
        }

        free(oldest);
    }

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;
    ++list->size;

    pthread_mutex_unlock(&list->lock);
}

void update_access_count(Node* node) {
    pthread_mutex_lock(&node->prev->lock);
    node->access_count++;
    pthread_mutex_unlock(&node->prev->lock);
}

int get_total_elements(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    int total = list->size;
    pthread_mutex_unlock(&list->lock);
    return total;
}

int get_unique_RNTIs(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    unsigned long rnti_set[MAX_ELEMENTS] = {0};
    int unique_count = 0;

    Node* current = list->head;
    while (current) {
        for (int i = 0; i < MAX_ELEMENTS; ++i) {
            if (rnti_set[i] == current->data.RNTI) break;
            if (rnti_set[i] == 0) {
                rnti_set[i] = current->data.RNTI;
                unique_count++;
                break;
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return unique_count;
}

float get_average_CRCFLAG(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    float sum_crcflag = 0.0f;
    int count = 0;

    Node* current = list->head;
    while (current) {
        sum_crcflag += current->data.CRCFLAG;
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return count > 0 ? sum_crcflag / count : 0.0f;
}

// Example usage
void simulate_external_data_source(DoublyLinkedList* list) {
    srand(time(NULL));
    for (int i = 0; i < 200; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 1000 + 1; // Simulating RNTI range
        pdu.CRC_INDICATION_REL8_TAG = rand();
        pdu.CRCFLAG = rand() % 2;

        insert_element(list, pdu);
    }
}

int main() {
    DoublyLinkedList* list = create_list();

    simulate_external_data_source(list);

    printf("Total elements: %d\n", get_total_elements(list));
    printf("Unique RNTIs: %d\n", get_unique_RNTIs(list));
    printf("Average CRCFLAG: %.2f\n", get_average_CRCFLAG(list));

    free_list(list);
    return 0;
}
```

This code implements a thread-safe, dynamically sized doubly linked list with the specified features. It manages uniqueness of `RNTI`, purges expired entries, and handles cache eviction based on access frequency when exceeding the size limit. The list can be integrated with external data sources, handling concurrent modifications without race conditions using mutex locks.']

