    pthread_mutex_unlock(&session_mutex);
}

NetworkSession* create_session(unsigned int session_id, const char* packet_data) {
    NetworkSession* new_session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!new_session) return NULL;

    pthread_mutex_lock(&session_mutex);
    if (session_count >= MAX_SESSIONS) {
        free(new_session);
        pthread_mutex_unlock(&session_mutex);
        return NULL;
    }

    new_session->session_id = session_id;
    strncpy(new_session->packet_data, packet_data, SESSION_BUFFER_SIZE - 1);
    new_session->last_activity = time(NULL);

    sessions[session_count++] = new_session;
    pthread_mutex_unlock(&session_mutex);

    return new_session;
}

void delete_session(unsigned int session_id) {
    pthread_mutex_lock(&session_mutex);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i] && sessions[i]->session_id == session_id) {
            free(sessions[i]);
            sessions[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&session_mutex);
}

void cleanup_inactive_sessions() {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&session_mutex);
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i]) {
            if ((current_time - sessions[i]->last_activity) > INACTIVITY_TIMEOUT_SECONDS) {
                free(sessions[i]);
                sessions[i] = NULL;
            }
        }
    }
    pthread_mutex_unlock(&session_mutex);
}

void initialize_crc_list(CRCList* list) {
    list->head = list->tail = NULL;
    list->count = 0;
    list->discarded_entries_count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1;

    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_CRC_LIST_SIZE) {
        // Discard the oldest entry
        Node* to_delete = list->head;
        list->head = list->head->next;
        free(to_delete);
        list->discarded_entries_count++;
    }

    if (!list->tail) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

