#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1024
#define SESSION_BUFFER_SIZE 4096
#define MAX_LIST_SIZE 2048
#define INACTIVITY_TIMEOUT 300 // in seconds

typedef struct {
    uint32_t session_id;
    time_t last_activity;
    char *packet_buffer;
} NetworkSession;

typedef struct {
    unsigned int valid_RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    void *data;
    struct Node *next;
} ListNode;

typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
    size_t size;
    size_t discarded_count;
} ThreadSafeList;

// Function prototypes
void initialize_sessions(NetworkSession **sessions, int max_sessions);
void cleanup_inactive_sessions(NetworkSession *sessions, int session_count);
ThreadSafeList* create_list();
int add_to_list(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T *item);
NFAPI_CRC_INDICATION_PDU_T* remove_oldest(ThreadSafeList *list);

// Implementation
void initialize_sessions(NetworkSession **sessions, int max_sessions) {
    *sessions = malloc(max_sessions * sizeof(NetworkSession));
    if (*sessions == NULL) return;

    for (int i = 0; i < max_sessions; ++i) {
        NetworkSession *session = &((*sessions)[i]);
        session->session_id = rand(); // Generate a unique ID
        session->last_activity = time(NULL);
        session->packet_buffer = malloc(SESSION_BUFFER_SIZE);
        if (session->packet_buffer == NULL) {
            for (int j = 0; j < i; ++j)
                free((*sessions)[j].packet_buffer);
            free(*sessions);
            *sessions = NULL;
            return;
        }
    }
}

void cleanup_inactive_sessions(NetworkSession *sessions, int session_count) {
    time_t current_time = time(NULL);

    for (int i = 0; i < session_count; ++i) {
        NetworkSession *session = &sessions[i];
        if (difftime(current_time, session->last_activity) > INACTIVITY_TIMEOUT) {
            free(session->packet_buffer);
            memset(session, 0, sizeof(NetworkSession)); // Clear the session
        }
    }
}

ThreadSafeList* create_list() {
    ThreadSafeList *list = malloc(sizeof(ThreadSafeList));
    if (list == NULL) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->discarded_count = 0;

    return list;
}

int add_to_list(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->lock);

    ListNode *new_node = malloc(sizeof(ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error code for memory allocation failure
    }

    new_node->data = item;
    new_node->next = list->head;
    list->head = new_node;

    if (++(list->size) > MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T *discarded = remove_oldest(list);
        free(discarded); // Discard the oldest entry
        list->discarded_count++;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* remove_oldest(ThreadSafeList *list) {
    if (list->head == NULL) return NULL;

    ListNode *old_node = list->head;
    list->head = old_node->next;
    NFAPI_CRC_INDICATION_PDU_T *data = (NFAPI_CRC_INDICATION_PDU_T *)old_node->data;

    free(old_node);
    --(list->size);

    return data;
}

// Example main function to demonstrate usage
int main() {
    NetworkSession *sessions;
    ThreadSafeList *crc_list;

    initialize_sessions(&sessions, MAX_SESSIONS);
    if (sessions == NULL) {
        fprintf(stderr, "Failed to initialize sessions\n");
        return 1;
    }

    crc_list = create_list();
    if (crc_list == NULL) {
        fprintf(stderr, "Failed to create CRC list\n");
        free(sessions); // Cleanup
        return 1;
    }

    // Simulate adding items and cleaning up
    for (int i = 0; i < 100; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!item) break;

        item->valid_RX_UE_INFORMATION_TAG = rand();
        item->RNTI = rand();
        item->CRC_INDICATION_REL8_TAG = rand();
        item->CRCFLAG = rand() % 2; // Randomly set CRC flag

        add_to_list(crc_list, item);
    }

    cleanup_inactive_sessions(sessions, MAX_SESSIONS);

    // Cleanup
    while (crc_list->head) {
        NFAPI_CRC_INDICATION_PDU_T *discarded = remove_oldest(crc_list);
        free(discarded);
    }
    pthread_mutex_destroy(&crc_list->lock);
    free(crc_list);

    for (int i = 0; i < MAX_SESSIONS; ++i) {
        if (sessions[i].packet_buffer) {
            free(sessions[i].packet_buffer);
        }
    }
    free(sessions);

    return 0;
}
