    srand(time(NULL));

    int start_time = clock();
    size_t count = 0;

    while (count < num_packets) {
        if (((clock() - start_time) * 1000 / CLOCKS_PER_SEC) > time_window_ms) {
            log_error("Time window exceeded.");
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T* packet = &packets[count];
        int tag = rand() % 10000;

        if (!validate_RX_UE_INFORMATION_TAG(tag)) {
            log_error("Invalid RX_UE_INFORMATION_TAG detected.");
            continue; // Skip this iteration
        }

        packet->RX_UE_INFORMATION_TAG = tag;
        packet->RNTI = rand() % 65535;
        packet->CRC_INDICATION_REL8_TAG = rand() % 1000;
        packet->CRCFLAG = (rand() % 2) ? true : false;

        count++;
    }

    *actual_num_packets = count;
    return packets;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* packets) {
    if (packets) {
        free(packets);
    }
}

