    NFAPI_CRC_INDICATION_PDU_T* pdu_list = populate_nfaapi_crc_indication_pdu(100, TIME_WINDOW_MS, &actual_packets);

    if (pdu_list) {
        printf("Generated %zu valid packets.\n", actual_packets);
        free_nfaapi_crc_indication_pdu(pdu_list);
    }

