NFAPI_CRC_INDICATION_PDU_T* generate_packet(int id, const char *http_method, int *count) {
    if (*count >= MAX_PACKETS)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T *packet = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!packet) {
