    // Populate CRC_INDICATION_REL8_TAG with random data
    if (RAND_bytes(packet->CRC_INDICATION_REL8_TAG, sizeof(packet->CRC_INDICATION_REL8_TAG)) != 1) {
        free(packet);
        log_failure("Random byte generation failed");
        return NULL;
    }

    // Set a random CRCFLAG
    packet->CRCFLAG = rand() % 2;

    (*count)++;
    return packet;
}

int handle_request(const char *http_method, int id, NFAPI_CRC_INDICATION_PDU_T ***packet_list) {
    if (!http_method || strcmp(http_method, "PUT") != 0 && strcmp(http_method, "DELETE") != 0)
        return 400; // Bad Request

    int packet_count = 0;
    *packet_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_PACKETS);
    if (!*packet_list) {
        log_failure("Memory allocation failed");
        return 500; // Internal Server Error
    }

    clock_t start_time = clock();
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *packet = generate_packet(id, http_method, &packet_count);
        if (!packet || packet_count >= MAX_PACKETS)
            break;

        (*packet_list)[packet_count - 1] = packet;

        // Check for timeout
        double elapsed_time = (double)(clock() - start_time) / CLOCKS_PER_SEC;
        if (elapsed_time > TIMEOUT_SECONDS) {
            log_failure("Packet generation timed out");
            while (packet_count > 0) {
                free((*packet_list)[--packet_count]);
            }
            free(*packet_list);
            *packet_list = NULL;
            return 408; // Request Timeout
        }
    }

    return packet_count > 0 ? 200 : 204; // OK or No Content
}

void cleanup_packets(NFAPI_CRC_INDICATION_PDU_T **packet_list, int count) {
    for (int i = 0; i < count; ++i) {
        free(packet_list[i]);
    }
    free(packet_list);
}
