#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int crcFlag;
} CRC_INDICATION_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int unique_id;
    CRC_INDICATION_T data;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
    int max_unique_id;
} NFAPI_LIST;

NFAPI_LIST* nfa_list_create() {
    NFAPI_LIST *list = (NFAPI_LIST *)malloc(sizeof(NFAPI_LIST));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_rwlock_init(&list->rwlock, NULL);
    list->max_unique_id = 0;
    return list;
}

void nfa_list_destroy(NFAPI_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    pthread_rwlock_destroy(&list->rwlock);
    free(list);
}

void nfa_list_add(NFAPI_LIST *list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Failed to allocate memory");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    list->max_unique_id++;
    new_node->unique_id = list->max_unique_id;

    srand(time(NULL) + list->max_unique_id); // Seed for randomness
    new_node->data.RX_UE_INFORMATION_TAG = rand() % 100;   // Example value
    new_node->data.RNTI = rand() % 10000;                  // Example value
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 10;  // Example value
    new_node->data.crcFlag = rand() % 2;

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->mutex);
}

int nfa_list_get_max_unique_id(NFAPI_LIST *list) {
    pthread_rwlock_rdlock(&list->rwlock);
    int max_id = list->max_unique_id;
    pthread_rwlock_unlock(&list->rwlock);
    return max_id;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_list_find_by_id(NFAPI_LIST *list, int unique_id) {
    pthread_rwlock_rdlock(&list->rwlock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->unique_id == unique_id) {
            pthread_rwlock_unlock(&list->rwlock);
            return current;
        }
        current = current->next;
    }
    pthread_rwlock_unlock(&list->rwlock);
    return NULL;
}

void populate_list(NFAPI_LIST *list, int entries) {
    for (int i = 0; i < entries; ++i) {
        nfa_list_add(list);
    }
}
```']

