        printf("Invalid input or packet limit exceeded\n");
        return;
    }

    srand(time(NULL));
    struct timespec start_time, current_time;

    clock_gettime(CLOCK_MONOTONIC, &start_time);
    for (int i = 0; i < num_packets; ++i) {
