        long elapsed_time_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + 
                               (current_time.tv_nsec - start_time.tv_nsec) / 1e6;

        if (elapsed_time_ms > TIME_WINDOW_MS) {
