    static async Task Main(string[] args)
    {
        var webPageManager = new WebPageManager();
        var managerThread = new Thread(() => StartBackgroundProcess(webPageManager));
        managerThread.Start();

        Console.WriteLine("Press any key to exit...");
        Console.ReadKey();

        managerThread.Abort(); // Cleanly stop the background process
    }

    static void StartBackgroundProcess(WebPageManager manager)
    {
        Random rnd = new Random();
        while (true)
        {
            Thread.Sleep(rnd.Next(5000, 15000));
            if (manager.IsRunning)
            {
                manager.Stop();
                Console.WriteLine($"Service paused at: {DateTime.Now}");
            }
            else
            {
                manager.Start();
                Console.WriteLine($"Service started at: {DateTime.Now}");
            }
        }
