#define MAX_STRUCTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
extern void log_metrics_async(const char* message);
extern int network_conditions_check(void);
extern void handle_service_outage(int attempt);

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_NFAPIS(struct NFAPI_CRC_INDICATION_PDU_T** array, size_t N) {
    if (N < 1 || N > MAX_STRUCTS) {
        log_metrics_async("Invalid number of structures requested");
        return NULL;
    }

    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        log_metrics_async("Memory allocation failed for structures");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        (*array)[i].RNTI = rand();
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        (*array)[i].CRCFLAG = (rand() % 2 == 0) ? 1 : 0;

        if (!network_conditions_check()) {
            log_metrics_async("Network conditions poor, retrying...");
            handle_service_outage(0); // Retry logic
            pthread_mutex_unlock(&mutex);
            free(*array);
            *array = NULL;
            return NULL;
        }
    }
    pthread_mutex_unlock(&mutex);

    // Log successful allocation and initialization
    log_metrics_async("Successfully allocated and populated structures");

    return *array;
}

void free_NFAPIS(struct NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array != NULL) {
        free(array);
        log_metrics_async("Memory freed for structures");
    }
}
