async function loadAndExecuteModules(modulePaths, testFunction, config = {}) {
    const { performanceConstraints = {}, loggingLevel = 'info' } = config;

    const log = (level, message) => {
        if (loggingLevel === 'debug' || (loggingLevel === 'info' && level !== 'debug')) {
            console[level](message);
        }
    };

    const timeout = ms => new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Timeout')), ms)
    );

    async function loadModule(path) {
        log('info', `Loading module: ${path}`);
        try {
            return await Promise.race([
                import(path),
                timeout(performanceConstraints.timeout || 5000) // default to 5 seconds
            ]);
        } catch (error) {
            log('error', `Failed to load module: ${path}, Error: ${error.message}`);
            throw error;
        }
    }

    async function runModuleTests(module, path) {
        log('info', `Running tests for module: ${path}`);
        try {
            blueslip.reset();
            await testFunction(module);
            log('info', `Tests passed for module: ${path}`);
        } catch (error) {
            log('error', `Tests failed for module: ${path}, Error: ${error.message}`);
        }
    }

    async function processModules() {
        for (let path of modulePaths) {
            try {
                const module = await loadModule(path);
                await runModuleTests(module, path);
            } catch (error) {
                log('warn', `Skipping tests due to error in loading module: ${path}`);
            }
        }
    }

    processModules().then(() => log('info', 'All modules processed'));
}

