}

int createNficSemaphores(int num_semaphores, int initial_values[], NFAPI_CRC_INDICATION_PDU_T ***pdu_list, sem_t **semaphores) {
    if (num_semaphores <= 0 || pdu_list == NULL || semaphores == NULL) {
        logError("Invalid number of semaphores or null pointers provided.");
        return -1;
    }

    *pdu_list = malloc(num_semaphores * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (*pdu_list == NULL) {
        logError("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T list.");
        return -1;
