        (*pdu_list)[i]->RNTI = rand() % 1000; // Example value
        (*pdu_list)[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        if (semaphores[i] == NULL || sem_init(semaphores[i], 0, initial_values[i]) != 0) {
            logError("Failed to initialize semaphore.");
            // Free previously allocated memory and destroy semaphores
            for (int j = 0; j <= i; ++j) {
                free((*pdu_list)[j]);
                if (semaphores[j] != NULL) {
                    sem_destroy(semaphores[j]);
                }
            }
            free(*pdu_list);
            return -1;
        }
    }

    srand(time(NULL)); // Seed for random number generation

    return 0; // Success
}

void cleanupResources(NFAPI_CRC_INDICATION_PDU_T *pdu_list[], sem_t **semaphores, int num_semaphores) {
    for (int i = 0; i < num_semaphores; ++i) {
        if (pdu_list[i] != NULL) {
            free(pdu_list[i]);
        }
        if (semaphores[i] != NULL) {
            sem_destroy(semaphores[i]);
        }
    }
    free(pdu_list);
}

