    pthread_mutex_lock(&manager->reconfig_lock);

    sem_t *new_semaphores = calloc(new_semaphore_count, sizeof(sem_t));
    if (!new_semaphores) {
        log_message("ERROR", "Memory allocation failed for reconfiguration.");
        pthread_mutex_unlock(&manager->reconfig_lock);
        return;
    }

