    for (int i = 0; i < new_semaphore_count; ++i) {
        if (sem_init(&new_semaphores[i], 0, init_value) != 0) {
            log_message("ERROR", "Reconfiguration semaphore initialization failed.");
            while (--i >= 0) sem_destroy(&new_semaphores[i]);
            free(new_semaphores);
            pthread_mutex_unlock(&manager->reconfig_lock);
            return;
        }
    }

    // Destroy old semaphores
    for (int i = 0; i < manager->semaphore_count; ++i) {
        sem_destroy(&(manager->semaphores[i]));
    }

    free(manager->semaphores);

    manager->semaphores = new_semaphores;
