NetworkEvent* create_event(EventType type, uint64_t timestamp, const void *payload, size_t payload_size) {
    NetworkEvent *event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    if (!event) return NULL;

    event->type = type;
    event->timestamp = timestamp;
    event->payload_size = payload_size;
    event->payload = malloc(payload_size);
    if (!event->payload) {
        free(event);
        return NULL;
    }
    memcpy(event->payload, payload, payload_size);
    event->next = NULL;

    return event;
}

void add_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL || list->head->timestamp > event->timestamp) {
        event->next = list->head;
        list->head = event;
    } else {
        NetworkEvent *current = list->head;
        while (current->next != NULL && current->next->timestamp <= event->timestamp) {
            current = current->next;
        }
        event->next = current->next;
        current->next = event;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_event(EventList *list, NetworkEvent *event) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NetworkEvent **current = &list->head;
    while (*current != NULL && *current != event) {
        current = &(*current)->next;
    }
    if (*current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    *current = event->next;
    free(event->payload);
    free(event);

    pthread_mutex_unlock(&list->lock);
}

void iterate_events(const EventList *list, void (*callback)(const NetworkEvent *)) {
    pthread_mutex_lock(&list->lock);

    for (NetworkEvent *current = list->head; current != NULL; current = current->next) {
        callback(current);
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_event_list(const EventList *list, unsigned char **out_data, size_t *out_size) {
    // Use third-party library for serialization
    if (!third_party_serialize(list, out_data, out_size)) {
        fprintf(stderr, "Serialization failed\n");
    }
}

int deserialize_event_list(const unsigned char *data, size_t data_size, EventList *list) {
    int result = third_party_deserialize(data, data_size, list);
    if (result != 0) {
        fprintf(stderr, "Deserialization error: %d\n", result);
    }
    return result;
}

void free_event_list(EventList *list) {
    pthread_mutex_lock(&list->lock);

    NetworkEvent *current = list->head;
    while (current != NULL) {
        NetworkEvent *next = current->next;
        free(current->payload);
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void compact_event_list(EventList *list) {
