    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Structure to manage the list of PDUs with thread safety
typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* pdus;
} PDUList;

#define INITIAL_CAPACITY 1024
#define RESIZE_FACTOR 2

// Custom allocator to reduce fragmentation and improve cache locality
void* custom_alloc(size_t size) {
    return aligned_alloc(64, size); // Align to 64 bytes for better cache performance
}

void custom_free(void* ptr) {
    free(ptr);
}

// Function to resize the PDU list
static void resize_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    size_t new_capacity = list->capacity * RESIZE_FACTOR;
    NFAPI_CRC_INDICATION_PDU_T* new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (new_pdus) {
        memcpy(new_pdus, list->pdus, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        custom_free(list->pdus);
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to create and add a PDU
void add_pdu(PDUList* list, uint32_t rx_tag, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        resize_pdu_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Random CRCFLAG

    list->pdus[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);

    // Asynchronous logging to avoid performance degradation
    if (list->count % 1000 == 0) {
        printf("Added PDU: RX_TAG=%u, RNTI=%hu, CRCFLAG=%d\n", rx_tag, rnti, pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
    }
}

// Function to deallocate PDUs
void free_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);

    if (list->pdus) {
        custom_free(list->pdus);
        list->pdus = NULL;
        list->count = 0;
        list->capacity = 0;
    }

    pthread_mutex_unlock(&list->lock);
}

// Initialize the PDU list
void init_pdu_list(PDUList* list) {
    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)custom_alloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Deinitialize the PDU list
void deinit_pdu_list(PDUList* list) {
    free_pdu_list(list);
    pthread_mutex_destroy(&list->lock);
}
