#include <stdio.h>

#define AES_KEY_SIZE 32
#define AES_IV_SIZE 16
#define PBKDF2_ITERATIONS 100000

typedef struct {
    EVP_CIPHER_CTX *ctx;
} EncryptionSession;

// Function prototypes
EncryptionSession* initialize_session(const char *password, const unsigned char *salt);
int encrypt_data(EncryptionSession *session, const unsigned char *plaintext, int plaintext_len,
                 unsigned char **ciphertext, int *ciphertext_len);
void cleanup_session(EncryptionSession *session);

// Initialize an encryption session
EncryptionSession* initialize_session(const char *password, const unsigned char *salt) {
    EncryptionSession *session = malloc(sizeof(EncryptionSession));
    if (!session) return NULL;

    // Derive key and IV using PBKDF2
    unsigned char key[AES_KEY_SIZE];
    unsigned char iv[AES_IV_SIZE];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 8, PBKDF2_ITERATIONS,
                          EVP_sha256(), AES_KEY_SIZE + AES_IV_SIZE, iv) != 1 ||
        PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 8, PBKDF2_ITERATIONS,
                          EVP_sha256(), AES_KEY_SIZE, key) != 1) {
        cleanup_session(session);
        return NULL;
    }

    // Initialize cipher context
    session->ctx = EVP_CIPHER_CTX_new();
    if (!session->ctx) {
        free(session);
        return NULL;
    }

    if (EVP_EncryptInit_ex(session->ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        cleanup_session(session);
        return NULL;
    }

    return session;
}

// Encrypt data
int encrypt_data(EncryptionSession *session, const unsigned char *plaintext, int plaintext_len,
                 unsigned char **ciphertext, int *ciphertext_len) {
    if (!session || !session->ctx) return 0;

    int len;
    int ciphertext_buffer_size = plaintext_len + AES_BLOCK_SIZE;
    *ciphertext = malloc(ciphertext_buffer_size);
    if (!*ciphertext) return 0;

    // Encrypt
    if (EVP_EncryptUpdate(session->ctx, *ciphertext, &len, plaintext, plaintext_len) != 1)
        return 0;

    int ciphertext_len_temp = len;
    if (EVP_EncryptFinal_ex(session->ctx, *ciphertext + len, &len) != 1)
        return 0;

    ciphertext_len_temp += len;
    *ciphertext_len = ciphertext_len_temp;

    return 1;
}

// Clean up resources
void cleanup_session(EncryptionSession *session) {
    if (session) {
        if (session->ctx) EVP_CIPHER_CTX_free(session->ctx);
        free(session);
    }
}
