    time_t timestamp;
    size_t payload_size;
    char *payload;
} NetworkEvent;

typedef struct {
    NetworkEvent **events;
    size_t capacity;
    size_t count;
    pthread_rwlock_t lock;
} EventList;

// Function prototypes
EventList* create_event_list(size_t initial_capacity);
int insert_event(EventList *list, EventType type, const char *payload);
int delete_event(EventList *list, size_t index);
void iterate_events(const EventList *list, void (*callback)(const NetworkEvent *));
int serialize_event(const NetworkEvent *event, unsigned char **buffer, size_t *size);
NetworkEvent* deserialize_event(const unsigned char *buffer, size_t size);
void destroy_event_list(EventList *list);

// Function implementations
EventList* create_event_list(size_t initial_capacity) {
    EventList *list = (EventList *)malloc(sizeof(EventList));
    if (!list) return NULL;

    list->events = (NetworkEvent **)calloc(initial_capacity, sizeof(NetworkEvent *));
    if (!list->events) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    pthread_rwlock_init(&list->lock, NULL);

    return list;
}

int insert_event(EventList *list, EventType type, const char *payload) {
    if (!list || !payload) return -1;

    pthread_rwlock_wrlock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NetworkEvent **new_events = realloc(list->events, new_capacity * sizeof(NetworkEvent *));
        if (!new_events) {
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }
        list->events = new_events;
        list->capacity = new_capacity;
    }

    NetworkEvent *event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    if (!event) {
        pthread_rwlock_unlock(&list->lock);
        return -1;
    }

    event->type = type;
    event->timestamp = time(NULL);
    event->payload_size = strlen(payload) + 1;
    event->payload = strdup(payload);

    list->events[list->count++] = event;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

int delete_event(EventList *list, size_t index) {
    if (!list || index >= list->count) return -1;

    pthread_rwlock_wrlock(&list->lock);
    NetworkEvent *event = list->events[index];
    free(event->payload);
    free(event);

    memmove(&list->events[index], &list->events[index + 1], (list->count - index - 1) * sizeof(NetworkEvent *));
    list->count--;

    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void iterate_events(const EventList *list, void (*callback)(const NetworkEvent *)) {
    if (!list || !callback) return;

    pthread_rwlock_rdlock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        callback(list->events[i]);
    }
    pthread_rwlock_unlock(&list->lock);
}

int serialize_event(const NetworkEvent *event, unsigned char **buffer, size_t *size) {
    if (!event || !buffer || !size) return -1;

    *size = sizeof(EventType) + sizeof(time_t) + sizeof(size_t) + event->payload_size;
    *buffer = (unsigned char *)malloc(*size);
    if (!*buffer) return -1;

    unsigned char *ptr = *buffer;
    memcpy(ptr, &event->type, sizeof(EventType)); ptr += sizeof(EventType);
    memcpy(ptr, &event->timestamp, sizeof(time_t)); ptr += sizeof(time_t);
    memcpy(ptr, &event->payload_size, sizeof(size_t)); ptr += sizeof(size_t);
    memcpy(ptr, event->payload, event->payload_size);

    return 0;
}

NetworkEvent* deserialize_event(const unsigned char *buffer, size_t size) {
    if (!buffer || size < sizeof(EventType) + sizeof(time_t) + sizeof(size_t)) return NULL;

    const unsigned char *ptr = buffer;
    EventType type; memcpy(&type, ptr, sizeof(EventType)); ptr += sizeof(EventType);
    time_t timestamp; memcpy(&timestamp, ptr, sizeof(time_t)); ptr += sizeof(time_t);
    size_t payload_size; memcpy(&payload_size, ptr, sizeof(size_t)); ptr += sizeof(size_t);

    if (size < sizeof(EventType) + sizeof(time_t) + sizeof(size_t) + payload_size) return NULL;

    NetworkEvent *event = (NetworkEvent *)malloc(sizeof(NetworkEvent));
    if (!event) return NULL;

    event->type = type;
    event->timestamp = timestamp;
    event->payload_size = payload_size;
    event->payload = (char *)malloc(payload_size);
    if (!event->payload) {
        free(event);
        return NULL;
    }

    memcpy(event->payload, ptr, payload_size);

    return event;
}

void destroy_event_list(EventList *list) {
    if (!list) return;

    pthread_rwlock_wrlock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->events[i]->payload);
        free(list->events[i]);
    }
    free(list->events);
    pthread_rwlock_unlock(&list->lock);

    pthread_rwlock_destroy(&list->lock);
    free(list);
}

// Example callback function for iteration
void print_event(const NetworkEvent *event) {
    if (!event) return;
    printf("Type: %d, Timestamp: %ld, Payload: %s\n", event->type, event->timestamp, event->payload);
}
