NetworkEvent get_event(EventList* list, int index);

InterfaceStatsArray* create_interface_stats_array(size_t initial_size);
int add_interface_stat(InterfaceStatsArray* array, NetworkInterfaceStats stat);
NetworkInterfaceStats* update_interface_stat(InterfaceStatsArray* array, const char* name, unsigned long recv_packets, unsigned long trans_packets, unsigned long errors);
void read_configuration(const char* config_file, InterfaceStatsArray* array);

// Event List Implementation
EventList* create_event_list() {
    EventList* list = malloc(sizeof(EventList));
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void insert_event(EventList* list, NetworkEvent event) {
    Node* new_node = malloc(sizeof(Node));
    new_node->event = event;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->mutex);
}

void delete_event(EventList* list, int index) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL || index < 0) return;

    Node *current = list->head, *prev = NULL;
    for (int i = 0; current != NULL && i < index; ++i) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return;

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->event.payload);
    free(current);

    pthread_mutex_unlock(&list->mutex);
}

NetworkEvent get_event(EventList* list, int index) {
    pthread_mutex_lock(&list->mutex);

    NetworkEvent event = {0};
    Node* current = list->head;
    for (int i = 0; current != NULL && i < index; ++i) {
        current = current->next;
    }

    if (current != NULL) {
        event.event_type = current->event.event_type;
        event.timestamp = current->event.timestamp;
        event.payload_size = current->event.payload_size;
        event.payload = malloc(event.payload_size + 1);
        memcpy(event.payload, current->event.payload, event.payload_size);
        event.payload[event.payload_size] = '\0';
    }

    pthread_mutex_unlock(&list->mutex);
    return event;
}

// Interface Stats Array Implementation
InterfaceStatsArray* create_interface_stats_array(size_t initial_size) {
    InterfaceStatsArray* array = malloc(sizeof(InterfaceStatsArray));
    array->stats_array = malloc(initial_size * sizeof(NetworkInterfaceStats));
    array->count = 0;
    pthread_rwlock_init(&array->rwlock, NULL);
    return array;
}

int add_interface_stat(InterfaceStatsArray* array, NetworkInterfaceStats stat) {
    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->stats_array[i].interface_name, stat.interface_name) == 0) {
            pthread_rwlock_unlock(&array->rwlock);
            return -1; // Interface already exists
        }
    }

    if (array->count >= sizeof(array->stats_array) / sizeof(NetworkInterfaceStats)) {
        size_t new_size = array->count * 2 + 1;
        NetworkInterfaceStats* new_array = realloc(array->stats_array, new_size * sizeof(NetworkInterfaceStats));
        if (!new_array) {
            pthread_rwlock_unlock(&array->rwlock);
            return -1; // Memory allocation failed
        }
        array->stats_array = new_array;
    }

    strcpy(array->stats_array[array->count].interface_name, stat.interface_name);
    array->stats_array[array->count] = stat;
    ++array->count;

    pthread_rwlock_unlock(&array->rwlock);
    return 0; // Success
}

NetworkInterfaceStats* update_interface_stat(InterfaceStatsArray* array, const char* name, unsigned long recv_packets, unsigned long trans_packets, unsigned long errors) {
    pthread_rwlock_wrlock(&array->rwlock);

    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->stats_array[i].interface_name, name) == 0) {
            array->stats_array[i].received_packets += recv_packets;
            array->stats_array[i].transmitted_packets += trans_packets;
            array->stats_array[i].error_counts += errors;
            pthread_rwlock_unlock(&array->rwlock);
            return &array->stats_array[i];
        }
    }

    pthread_rwlock_unlock(&array->rwlock);
    return NULL; // Interface not found
}

void read_configuration(const char* config_file, InterfaceStatsArray* array) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return;
    }

    NetworkInterfaceStats stat;
    while (fscanf(file, "%255s %lu %lu %lu", stat.interface_name, &stat.received_packets, &stat.transmitted_packets, &stat.error_counts) == 4) {
        add_interface_stat(array, stat);
    }
    fclose(file);
}

// Clean up resources
void free_event_list(EventList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->event.payload);
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

void free_interface_stats_array(InterfaceStatsArray* array) {
    pthread_rwlock_wrlock(&array->rwlock);

    free(array->stats_array);

    pthread_rwlock_unlock(&array->rwlock);
    pthread_rwlock_destroy(&array->rwlock);
    free(array);
}
```

### Key Design Choices and Considerations

1. **Network Events**: 
   - Used a linked list for efficient insertions and deletions, which are common in event-driven systems.
   - Mutexes ensure thread safety during concurrent access.

2. **Interface Statistics**:
   - A dynamically resizable array with read-write locks allows safe concurrent updates and minimizes reallocation overhead.
   - Supports incremental growth to handle an increasing number of interfaces efficiently.

3. **Concurrency**:
   - Used mutexes for exclusive access in the event list and read-write locks for interface statistics to allow multiple readers or a single writer, optimizing concurrency.

4. **Memory Management**:
   - Manual memory management with careful allocation/deallocation to minimize fragmentation.
   - Compact operations are suggested but not implemented here; they would involve periodically merging nodes or compacting arrays in low-traffic periods.

5. **Serialization/Deserialization**:
   - Not explicitly included, but should be implemented using a compatible binary format (e.g., Protocol Buffers) for interoperability.

6. **Error Handling and Configuration**:
   - Basic error handling with file I/O operations.
   - Unique interface names ensured during addition to the stats array.

7. **Documentation and Integration**:
   - Detailed comments in code provide clarity on function usage and constraints.
   - External dependencies like logging or parsing libraries can be integrated as needed, ensuring robust error handling.

This implementation provides a foundation upon which further features and optimizations can be built, such as detailed serialization/deserialization mechanisms, more sophisticated memory management strategies, and advanced configuration options.']

