#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_RETRIES 5

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int rx_UE_info;
    int rnti;
    bool crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
    size_t size;
    size_t max_size;
    int performance_threshold;
    pthread_cond_t cond_var;
} LinkedList;

LinkedList* create_list(size_t max_size, int performance_threshold) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->size = 0;
    list->max_size = max_size;
    list->performance_threshold = performance_threshold;

    return list;
}

bool validate_UE_info(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement validation logic
    return (pdu && pdu->rx_UE_info >= 0 && pdu->rnti >= 0);
}

void add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_UE_info(pdu)) return;

    pthread_mutex_lock(&list->lock);

    while (list->size >= list->max_size) {
        // Wait for space or performance threshold condition
        pthread_cond_wait(&list->cond_var, &list->lock);
    }

    int retries = 0;
    Node* new_node = NULL;
    while (retries < MAX_RETRIES) {
        new_node = (Node*)malloc(sizeof(Node));
        if (new_node) break;
        retries++;
    }

    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return; // Handle allocation failure
    }

    new_node->data = *pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_cond_signal(&list->cond_var);
    pthread_mutex_unlock(&list->lock);
}

void delete_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
    free(list);
}

void get_list_status(const LinkedList* list, size_t* size, int* performance_metric) {
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    *size = list->size;
    *performance_metric = (int)((float)list->size / list->max_size * 100);

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
}
