    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define constants
#define MAX_STRUCTURES 10000

// Thread safety mechanism
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool management
typedef struct {
    size_t element_size;
    void **free_list;
    size_t free_count;
} MemoryPool;

MemoryPool *create_pool(size_t element_size, size_t initial_count) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->element_size = element_size;
    pool->free_list = (void **)calloc(initial_count, sizeof(void *));
    pool->free_count = initial_count;

    for(size_t i = 0; i < initial_count - 1; ++i)
        pool->free_list[i] = &pool->free_list[i + 1];
    pool->free_list[initial_count - 1] = NULL;

    return pool;
}

void *allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&lock);
    if (pool->free_count == 0) {
        size_t new_blocks = 100; // Expand by 100 blocks at a time
        void **new_free_list = (void **)realloc(pool->free_list, 
                                                pool->free_count + new_blocks * sizeof(void *));

        if (!new_free_list) {
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        for(size_t i = 0; i < new_blocks - 1; ++i)
            new_free_list[pool->free_count + i] = &new_free_list[pool->free_count + i + 1];
        new_free_list[pool->free_count + new_blocks - 1] = NULL;

        pool->free_list = new_free_list;
        pool->free_count += new_blocks;
    }

    void *allocated_memory = pool->free_list[--pool->free_count];
    pthread_mutex_unlock(&lock);

    return allocated_memory;
}

void deallocate_to_pool(MemoryPool *pool, void *ptr) {
    pthread_mutex_lock(&lock);
    *(void **)ptr = pool->free_list[pool->free_count++];
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T **create_crc_indication_list(size_t max_elements, int log_enabled) {
    MemoryPool *pool = create_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1000);
    if (!pool)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T **)calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!list) {
        free(pool->free_list);
        free(pool);
        return NULL;
    }

    for(size_t i = 0; i < max_elements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)allocate_from_pool(pool);
        if (!pdu) {
            for(size_t j = 0; j < i; ++j)
                deallocate_to_pool(pool, list[j]);

            free(list);
            free(pool->free_list);
            free(pool);
            return NULL;
        }

        // Simulating population from an external data source
        pdu->rx_ue_info_tag.value = rand() % 256;
        pdu->rnti = rand() % (1 << 14); // Valid range for RNTI: [0, 16383]
        pdu->crc_ind_rel8_tag.CRCFLAG = rand() % 2;

        if (log_enabled)
            printf("Allocated and initialized PDU[%zu]\n", i);

        list[i] = pdu;
    }

    return list;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t count, MemoryPool *pool) {
    for(size_t i = 0; i < count; ++i)
        deallocate_to_pool(pool, list[i]);

    free(list);
}

// Function to update CRCFLAG
void update_crcflag(NFAPI_CRC_INDICATION_PDU_T **list, size_t count) {
    pthread_mutex_lock(&lock);
    for(size_t i = 0; i < count; ++i)
        if (rand() % 10 == 0) // Example criterion: 10% chance to set CRCFLAG to 1
            list[i]->crc_ind_rel8_tag.CRCFLAG = 1;

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    size_t max_elements = MAX_STRUCTURES;
    int log_enabled = 1;

    NFAPI_CRC_INDICATION_PDU_T **list = create_crc_indication_list(max_elements, log_enabled);
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    update_crcflag(list, max_elements);

    free_crc_indication_list(list, max_elements, create_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 1000));
    return EXIT_SUCCESS;
}
