        last_rnti = array[i].RNTI;

        array[i].CRC_INDICATION_REL8_TAG = rand() % 1000;  // Replace with actual data source
        array[i].CRCFLAG = rand() % 2;  // Probabilistic determination of CRCFLAG
    }

    return array;
}

int resolve_hostname(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res, *p;
    int result;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;  // IPv4

    if ((result = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_error("DNS resolution failed.");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip, &(ipv4->sin_addr), sizeof(struct in_addr));
        break;
    }

    freeaddrinfo(res);

    return 0;  // Success
}

void log_error(const char *message) {
