DynamicNFAPIArray* create_dynamic_array(size_t max_elements) {
    DynamicNFAPIArray *dyn_array = (DynamicNFAPIArray*)malloc(sizeof(DynamicNFAPIArray));
    if (!dyn_array) return NULL;

    dyn_array->array = (NFAPI_RX_INDICATION_PDU_T*)calloc(max_elements, sizeof(NFAPI_RX_INDICATION_PDU_T));
    if (!dyn_array->array) {
        free(dyn_array);
        return NULL;
    }

    dyn_array->size = 0;
    dyn_array->capacity = max_elements;
    pthread_mutex_init(&dyn_array->lock, NULL);

    return dyn_array;
}

int resize_dynamic_array(DynamicNFAPIArray *dyn_array, size_t new_capacity) {
    if (new_capacity <= dyn_array->capacity) return -1;

    NFAPI_RX_INDICATION_PDU_T *new_array = (NFAPI_RX_INDICATION_PDU_T*)realloc(dyn_array->array, new_capacity * sizeof(NFAPI_RX_INDICATION_PDU_T));
    if (!new_array) return -1;

    memset(new_array + dyn_array->capacity, 0, (new_capacity - dyn_array->capacity) * sizeof(NFAPI_RX_INDICATION_PDU_T));

    dyn_array->array = new_array;
    dyn_array->capacity = new_capacity;

    return 0;
}

int add_element(DynamicNFAPIArray *dyn_array, NFAPI_RX_INDICATION_PDU_T element) {
    pthread_mutex_lock(&dyn_array->lock);

    if (dyn_array->size >= dyn_array->capacity) {
        size_t new_capacity = dyn_array->capacity * 2;
        if (resize_dynamic_array(dyn_array, new_capacity) != 0) {
            pthread_mutex_unlock(&dyn_array->lock);
            return -1;
        }
    }

    dyn_array->array[dyn_array->size++] = element;

    pthread_mutex_unlock(&dyn_array->lock);

    return 0;
}

