    if (index >= dyn_array->size) return -1;

    pthread_mutex_lock(&dyn_array->lock);
    *element = dyn_array->array[index];
    pthread_mutex_unlock(&dyn_array->lock);

    return 0;
}

void release_dynamic_array(DynamicNFAPIArray *dyn_array) {
    if (!dyn_array) return;

    pthread_mutex_destroy(&dyn_array->lock);
    free(dyn_array->array);
