typedef struct MemoryPool {
    size_t unit_size;
    void* pool;
    size_t pool_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t unit_size, size_t count) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    mp->unit_size = unit_size;
    mp->pool_size = count;
    mp->pool = malloc(unit_size * count);
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void* thread_safe_allocate(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (malloc_usable_size(mp->pool)) { // If there's available space
        void* ptr = mp->pool;
        mp->pool = (char*)mp->pool + mp->unit_size; 
        return ptr;
    }
    pthread_mutex_unlock(&mp->lock);
    return NULL;  // Pool exhausted
}

void thread_safe_deallocate(MemoryPool *mp, void* ptr) {
    pthread_mutex_lock(&mp->lock);
    char* pool = (char*)mp->pool - mp->unit_size;
    if ((size_t)(ptr - pool) < mp->pool_size * mp->unit_size) { 
        memcpy(pool, ptr, mp->unit_size);
        mp->pool = pool;
    }
    pthread_mutex_unlock(&mp->lock);
}

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* insert_into_list(NFAPI_CRC_INDICATION_PDU_T** head, MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)thread_safe_allocate(mp);
    if (!new_node) return NULL;

    new_node->rx_ue_info_tag.RNTI = rand() % 0xFFFF;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() & 1; // Random CRC flag
    new_node->next = *head;

    log_message("Inserted a new NFAPI_CRC_INDICATION_PDU_T node.");

    pthread_mutex_lock(&list_lock);
    *head = new_node;
    pthread_mutex_unlock(&list_lock);

    return new_node;
}

void delete_from_list(NFAPI_CRC_INDICATION_PDU_T** head, MemoryPool *mp) {
    if (!*head) return;

    pthread_mutex_lock(&list_lock);
    NFAPI_CRC_INDICATION_PDU_T *temp = *head;
    *head = (*head)->next;
    thread_safe_deallocate(mp, temp);
    log_message("Deleted an NFAPI_CRC_INDICATION_PDU_T node.");
    pthread_mutex_unlock(&list_lock);
}

void destroy_memory_pool(MemoryPool* mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    MemoryPool *memory_pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), 100);

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    insert_into_list(&head, memory_pool);
    delete_from_list(&head, memory_pool);

    destroy_memory_pool(memory_pool);

    return 0;
}
