// Definitions for the network layer message structure
typedef struct {
    int SequenceNumber;
    char PacketType; // 'D' for Data, 'A' for Acknowledgment, etc.
    unsigned short Checksum;
} DataPacket;

typedef struct {
    unsigned long SourceAddress;
    unsigned long DestinationAddress;
    DataPacket data;
} NetworkLayerMessage;

// Predefined IP range (example: 192.168.0.1 to 192.168.255.255)
#define MIN_IP 3232235521UL
#define MAX_IP 3232301055UL

// Default address if validation fails
#define DEFAULT_IP 0x0100007F // 127.0.0.1 (localhost)

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned short computeChecksum(DataPacket *packet) {
    unsigned long sum = packet->SequenceNumber + ((packet->PacketType & 0xFF) << 16);
    return ~((sum & 0xFFFF) + (sum >> 16));
}

int validateIP(unsigned long ip) {
    return (ip >= MIN_IP && ip <= MAX_IP);
}

void allocateAndPopulateMessages(NetworkLayerMessage **messages, int N, unsigned long *sourceAddresses, unsigned long *destinationAddresses) {
    if (!messages || N <= 0) return;

    // Allocate memory for messages
    *messages = aligned_alloc(64, sizeof(NetworkLayerMessage) * N); // Align to cache line size

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; ++i) {
        (*messages)[i].SourceAddress = validateIP(sourceAddresses[i]) ? sourceAddresses[i] : DEFAULT_IP;
