        (*messages)[i].data.PacketType = 'D';    // Assume all are data packets for simplicity
        (*messages)[i].data.Checksum = computeChecksum(&(*messages)[i].data);

        // Validate checksum (Example validation, in practice it would be more complex)
        unsigned short computedChecksum = computeChecksum(&(*messages)[i].data);
        if ((*messages)[i].data.Checksum != computedChecksum) {
            fprintf(stderr, "Checksum mismatch at index %d\n", i);
            exit(EXIT_FAILURE);
        }
    }
    pthread_mutex_unlock(&mutex);
