#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define SALT_LENGTH 16
#define ITERATIONS 100000

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char salt[SALT_LENGTH];
    int enabled;
} CipherContext;

CipherContext* create_cipher_context(const char *password) {
    CipherContext *cc = malloc(sizeof(CipherContext));
    if (!cc || !RAND_bytes(cc->salt, SALT_LENGTH)) {
        perror("Failed to allocate memory or generate random salt");
        free(cc);
        return NULL;
    }

    cc->ctx = EVP_CIPHER_CTX_new();
    if (!cc->ctx) {
        perror("Cipher context creation failed");
        free(cc->salt);
        free(cc);
        return NULL;
    }

    // Derive key and iv using PBKDF2
    unsigned char key[EVP_MAX_KEY_LENGTH], iv[EVP_MAX_IV_LENGTH];
    if (1 != PKCS5_PBKDF2_HMAC(password, strlen(password), cc->salt, SALT_LENGTH,
                               ITERATIONS, EVP_sha256(), sizeof(key), key) ||
        1 != PKCS5_PBKDF2_HMAC(password, strlen(password), cc->salt, SALT_LENGTH,
                               ITERATIONS, EVP_sha256(), sizeof(iv), iv)) {
        perror("Key derivation failed");
        EVP_CIPHER_CTX_free(cc->ctx);
        free(cc->salt);
        free(cc);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(cc->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        perror("Cipher initialization failed");
        EVP_CIPHER_CTX_free(cc->ctx);
        free(cc->salt);
        free(cc);
        return NULL;
    }

    cc->enabled = 1;
    return cc;
}

void destroy_cipher_context(CipherContext *cc) {
    if (cc && cc->ctx) {
        EVP_CIPHER_CTX_free(cc->ctx);
        free(cc->salt);
        free(cc);
    }
}

int enable_cipher(CipherContext *cc) {
    if (!cc || !cc->ctx || cc->enabled)
        return 0;

    // Re-initialize context for enabling
    EVP_EncryptInit_ex(cc->ctx, EVP_aes_256_cbc(), NULL, cc->salt, cc->salt); // This assumes salt and iv were derived similarly
    cc->enabled = 1;
    return 1;
}

int disable_cipher(CipherContext *cc) {
    if (!cc || !cc->ctx || !cc->enabled)
        return 0;

    EVP_CIPHER_CTX_cleanup(cc->ctx);
    cc->enabled = 0;
    return 1;
}

void encrypt_data(CipherContext *cc, const unsigned char *plaintext, int plaintext_len,
                  unsigned char *ciphertext) {
    if (!cc || !cc->ctx || !cc->enabled)
        return;

    int len;
    int ciphertext_len;

    if (1 != EVP_EncryptUpdate(cc->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        perror("Encryption failed");
        return;
    }
    ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(cc->ctx, ciphertext + len, &len)) {
        perror("Finalizing encryption failed");
        return;
    }
    ciphertext_len += len;
}

void decrypt_data(CipherContext *cc, const unsigned char *ciphertext, int ciphertext_len,
                  unsigned char *plaintext) {
    if (!cc || !cc->ctx || !cc->enabled)
        return;

    int len;
    int plaintext_len;

    if (1 != EVP_DecryptUpdate(cc->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        perror("Decryption failed");
        return;
    }
    plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(cc->ctx, plaintext + len, &len)) {
        perror("Finalizing decryption failed");
        return;
    }
    plaintext_len += len;
}

int main() {
    // Example usage
    const char *password = "strong_password";

    CipherContext *cc = create_cipher_context(password);
    if (!cc) {
        fprintf(stderr, "Failed to create cipher context\n");
        return EXIT_FAILURE;
    }

    unsigned char plaintext[] = "This is a test message.";
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    encrypt_data(cc, plaintext, strlen((char *)plaintext), ciphertext);

    // Switching context
    disable_cipher(cc);
    enable_cipher(cc);

    decrypt_data(cc, ciphertext, sizeof(ciphertext), decryptedtext);

    printf("Decrypted text is: %s\n", decryptedtext);

    destroy_cipher_context(cc);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Initialization**: Uses OpenSSL's EVP library to create and manage AES-256-CBC contexts.
- **PBKDF2**: Derives keys using PBKDF2 with a secure random salt for each context.
- **Enable/Disable**: Dynamically enables or disables cipher operations on demand.
- **Error Handling**: Includes robust error checking after key cryptographic operations.
- **Thread Safety**: Uses individual cipher contexts which can be safely used across multiple threads if managed correctly.

**Note:** This code requires OpenSSL to be linked properly, and it's crucial to ensure that your application is thread-safe when using shared resources.']

