} NFAPI_CRC_INDICATION_PDU_T;

int initializeNfarxIndications(size_t num_pdus, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (!pdus) {
        return FAILURE;
    }

    *pdus = NULL;

    if (num_pdus > MAX_RECORDS) {
        fprintf(stderr, "Requested number of PDUs exceeds the maximum limit.\n");
        return FAILURE;
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        fprintf(stderr, "Memory allocation failed for PDU structures.\n");
        return FAILURE;
    }

    srand(time(NULL));  // Seed random number generator
    for (size_t i = 0; i < num_pdus; ++i) {
        (*pdus)[i].ue_info_tag.RX_UE_INFORMATION_TAG = rand() % 1000;  // Random value within range
        (*pdus)[i].rnti = rand() % 10000;  // Random value within range

