        (*pdus)[i].crc_indication_rel8_tag.CRCFLAG = crcflag;
    }

    printf("Successfully initialized %zu NFAPI_CRC_INDICATION_PDU_T structures.\n", num_pdus);

    return SUCCESS;
}

int main() {
