    free(da);
}

int insert_entry(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&da->lock);

    if (da->count == da->capacity) {
        size_t new_capacity = da->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->count++] = entry;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

int remove_entry(DynamicArray *da, size_t index) {
    if (index >= da->count) {
        return -1; // Index out of bounds
    }

    pthread_mutex_lock(&da->lock);

    for (size_t i = index; i < da->count - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }
    --da->count;

    pthread_mutex_unlock(&da->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_entry() {
    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.RX_UE_INFORMATION_TAG = rand() % 256; // Example value
    entry.RNTI = (uint16_t)(rand() % 65536); // Example value
    entry.CRC_INDICATION_REL8_TAG = rand() % 256; // Example value
    entry.CRCFLAG = rand() % 2;
    return entry;
}

int main() {
    DynamicArray *da = create_dynamic_array(10);

    for (size_t i = 0; i < 50; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry = generate_random_entry();
        insert_entry(da, entry);
    }

    printf("Dynamic array count: %zu\n", da->count);

    remove_entry(da, 5); // Example removal
    printf("After removal, dynamic array count: %zu\n", da->count);

    free_dynamic_array(da);
    return 0;
}
```

### Key Points:
- **Thread Safety**: A mutex (`pthread_mutex_t`) is used to ensure thread safety during insertions and removals.
- **Dynamic Scaling**: The array doubles its capacity when it becomes full, minimizing reallocation overhead.
- **Memory Management**: Efficiently handles memory allocation with `realloc` for dynamic scaling.
- **Random CRCFLAG**: Uses `rand()` to set the `CRCFLAG` randomly. Ensure `srand()` is called if deterministic randomness is required.

This implementation ensures efficient and thread-safe operations on a dynamically resizable array of structures, suitable for large-scale deployments.']

