using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

public class WebsiteManager
{
    private static readonly object _lockObject = new object();
    private static readonly ConcurrentDictionary<string, Process> _runningProcesses = new();

    public static void AddAndStartWebsite(string directoryPath, string siteName)
    {
        try
        {
            var webConfigPath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(webConfigPath))
            {
                Console.WriteLine("Web.config file is missing.");
                return;
            }

            // Load configurations from an external configuration file
            var config = new ConfigurationBuilder()
                .SetBasePath(Directory.GetCurrentDirectory())
                .AddJsonFile("appsettings.json", optional: false, reloadOnChange: true)
                .Build();

            string siteConfigSectionName = $"Site:{siteName}";
            if (!config.GetSection(siteConfigSectionName).Exists())
            {
                Console.WriteLine($"Configuration for {siteName} does not exist.");
                return;
            }

            var section = config.GetSection(siteConfigSectionName);
            int memoryLimitMB = section.GetValue<int>("MemoryLimit");
            double cpuLimitPercent = section.GetValue<double>("CpuLimit");

            lock (_lockObject)
            {
                if (_runningProcesses.ContainsKey(siteName))
                {
                    Console.WriteLine($"Site {siteName} is already running.");
                    return;
                }

                ProcessStartInfo startInfo = new()
                {
                    FileName = "dotnet",
                    Arguments = $"run --project \"{directoryPath}\"",
                    WorkingDirectory = directoryPath,
                };

                using var process = new Process
                {
                    StartInfo = startInfo,
                    EnableRaisingEvents = true,
                };

                process.Exited += (sender, args) =>
                {
                    _runningProcesses.TryRemove(siteName, out _);
                };

                if (!process.Start())
                {
                    Console.WriteLine("Failed to start the website.");
                    return;
                }

                _runningProcesses.TryAdd(siteName, process);

                Task.Run(() => MonitorResourceUsage(process, siteName, memoryLimitMB, cpuLimitPercent));
            }
        }
        catch (Exception ex)
        {
            // Log exception
            Console.WriteLine($"Error: {ex.Message}");
        }
    }

    private static void MonitorResourceUsage(Process process, string siteName, int memoryLimitMB, double cpuLimitPercent)
    {
        try
        {
            using var performanceCounter = new PerformanceCounter("Process", "% Processor Time", process.ProcessName);
            while (!process.HasExited)
            {
                float cpuUsage = performanceCounter.NextValue();
                if (cpuUsage > cpuLimitPercent * 100)
                {
                    Console.WriteLine($"Terminating {siteName} due to high CPU usage: {cpuUsage}%.");
                    process.Kill();
                    break;
                }

                ProcessMemoryInfo memoryInfo = process.GetProcessMemoryInfo();
                if (memoryInfo.WorkingSet64 > memoryLimitMB * 1024 * 1024)
                {
                    Console.WriteLine($"Terminating {siteName} due to high memory usage: {memoryInfo.WorkingSet64 / (1024 * 1024)} MB.");
                    process.Kill();
                    break;
                }

                Task.Delay(5000).Wait(); // Monitor every 5 seconds
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Monitoring error for {siteName}: {ex.Message}");
        }
    }

    [System.Runtime.InteropServices.DllImport("kernel32.dll")]
    private static extern bool GetProcessMemoryInfo(IntPtr hProcess, out PROCESS_MEMORY_COUNTERS_EX pmc, int length);

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESS_MEMORY_COUNTERS_EX
    {
        public uint cb;
        public ulong PageFaultCount;
        public ulong PeakWorkingSetSize;
        public ulong WorkingSetSize;
        public ulong QuotaPeakPagedPoolUsage;
        public ulong QuotaPagedPoolUsage;
        public ulong QuotaPeakNonPagedPoolUsage;
        public ulong QuotaNonPagedPoolUsage;
        public ulong PagefileUsage;
        public ulong PeakPagefileUsage;
        public ulong PrivateUsage;

        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 16)]
        public UInt64[] Counters;
    }

    private static ProcessMemoryInfo GetProcessMemoryInfo(this Process process)
    {
        PROCESS_MEMORY_COUNTERS_EX info = new();
        IntPtr handle = process.Handle;
        bool success = GetProcessMemoryInfo(handle, out info, (int)System.Runtime.InteropServices.Marshal.SizeOf(info));

        if (!success)
            throw new Exception("Error getting memory information for the process.");

        return new ProcessMemoryInfo
        {
            PageFaultCount = info.PageFaultCount,
            PeakWorkingSetSize = info.PeakWorkingSetSize,
            WorkingSetSize = info.WorkingSetSize,
            QuotaPeakPagedPoolUsage = info.QuotaPeakPagedPoolUsage,
            QuotaPagedPoolUsage = info.QuotaPagedPoolUsage,
            QuotaPeakNonPagedPoolUsage = info.QuotaPeakNonPagedPoolUsage,
            QuotaNonPagedPoolUsage = info.QuotaNonPagedPoolUsage,
            PagefileUsage = info.PagefileUsage,
            PeakPagefileUsage = info.PeakPagefileUsage,
            PrivateUsage = info.PrivateUsage
        };
    }

    public class ProcessMemoryInfo
    {
        public ulong PageFaultCount;
        public ulong PeakWorkingSetSize;
        public ulong WorkingSetSize;
        public ulong QuotaPeakPagedPoolUsage;
        public ulong QuotaPagedPoolUsage;
        public ulong QuotaPeakNonPagedPoolUsage;
        public ulong QuotaNonPagedPoolUsage;
        public ulong PagefileUsage;
        public ulong PeakPagefileUsage;
        public ulong PrivateUsage;
    }
}
