        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
// along with a semaphore for resource synchronization.
NFAPI_CRC_INDICATION_PDU_T* createNficSemaphores(size_t num_pdus, int initial_semaphore_value) {
    if (num_pdus == 0 || initial_semaphore_value < 1) {
        fprintf(stderr, "Invalid input: Number of PDUs must be > 0 and semaphore value >= 1.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sem_t* semaphores = malloc(MAX_SEMAPHORES * sizeof(sem_t));

    if (!pdus || !semaphores) {
        perror("Memory allocation failed");
        free(pdus);
        free(semaphores);
        return NULL;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    // Initialize semaphores
    for (size_t i = 0; i < MAX_SEMAPHORES; ++i) {
        if (sem_init(&semaphores[i], 0, initial_semaphore_value) != 0) {
            perror("Semaphore initialization failed");
            free(pdus);
            // Destroy initialized semaphores before returning
            for (size_t j = 0; j < i; ++j) {
                sem_destroy(&semaphores[j]);
            }
            free(semaphores);
            return NULL;
        }
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Populate PDUs with random values and synchronize using semaphore
    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&mutex);

        pdus[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        pdus[i].RNTI = rand() % UINT16_MAX;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Example semaphore usage (could be used for synchronization in concurrent context)
        sem_wait(&semaphores[0]);
        sem_post(&semaphores[0]);

        pthread_mutex_unlock(&mutex);
    }

    printf("NFAPI_CRC_INDICATION_PDU_T structures and semaphores initialized successfully.\n");

    // Clean up mutex
    pthread_mutex_destroy(&mutex);

    return pdus;
}

