// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int validate_jwt(const char *jwt) {
    json_error_t error;
    json_t *root = json_loads(jwt, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return 0;
    }

    // Parse and validate claims
    const char *iss = json_string_value(json_object_get(root, "iss"));
    const char *sub = json_string_value(json_object_get(root, "sub"));
    const char *aud = json_string_value(json_object_get(root, "aud"));
    json_t *exp_json = json_object_get(root, "exp");
    json_t *iat_json = json_object_get(root, "iat");

    if (!iss || !sub || !aud) {
        fprintf(stderr, "JWT must include non-empty 'iss', 'sub', and 'aud' claims.\n");
        goto end;
    }

    if (json_is_integer(exp_json)) {
        time_t exp = json_integer_value(exp_json);
        if (exp <= 0 || exp < time(NULL)) {
            fprintf(stderr, "'exp' must be a positive integer representing valid future time.\n");
            goto end;
        }
    } else {
        fprintf(stderr, "'exp' claim is missing or not an integer.\n");
        goto end;
    }

    if (json_is_integer(iat_json)) {
        time_t iat = json_integer_value(iat_json);
        if (iat <= 0 || iat > time(NULL)) {
            fprintf(stderr, "'iat' must be a positive integer representing valid past or current time.\n");
            goto end;
        }
    } else {
        fprintf(stderr, "'iat' claim is missing or not an integer.\n");
        goto end;
    }

    json_t *jti_json = json_object_get(root, "jti");
    // Optional: Validate 'jti' uniqueness if implemented in your system
    // Example: Check against a data source for uniqueness

    pthread_mutex_lock(&mutex);
    // Perform thread-safe operations here if needed
    pthread_mutex_unlock(&mutex);

end:
    json_decref(root);
    return 1;
}

int main() {
    const char *jwt = "{\"iss\":\"example_issuer\",\"sub\":\"user123\",\"aud\":\"example_audience\",\"exp\":1700000000,\"iat\":1699990000}";
    if (validate_jwt(jwt)) {
        printf("JWT is valid.\n");
    } else {
        printf("JWT is invalid.\n");
    }
    return 0;
}
