DynamicArray* create_dynamic_array() {
    DynamicArray *arr = (DynamicArray *)malloc(sizeof(DynamicArray));
    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    arr->data = (NFAPI_RX_MESSAGE_T *)calloc(arr->capacity, sizeof(NFAPI_RX_MESSAGE_T));
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void resize_dynamic_array(DynamicArray *arr) {
    size_t new_capacity = arr->capacity * 2;
    NFAPI_RX_MESSAGE_T *new_data = (NFAPI_RX_MESSAGE_T *)realloc(arr->data, new_capacity * sizeof(NFAPI_RX_MESSAGE_T));
    if (new_data != NULL) {
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
}

void add_entry(DynamicArray *arr, NFAPI_RX_MESSAGE_T entry) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr);
    }
    arr->data[arr->size++] = entry;
    pthread_mutex_unlock(&arr->lock);
}

int remove_entry(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    int result = 0;
    if (index < arr->size) {
        memmove(&arr->data[index], &arr->data[index + 1], (arr->size - index - 1) * sizeof(NFAPI_RX_MESSAGE_T));
        arr->size--;
        result = 1; // Success
    }
    pthread_mutex_unlock(&arr->lock);
    return result;
}

int update_entry(DynamicArray *arr, size_t index, NFAPI_RX_MESSAGE_T new_data) {
    pthread_mutex_lock(&arr->lock);
    int result = 0;
    if (index < arr->size) {
        arr->data[index] = new_data;
        result = 1; // Success
    }
    pthread_mutex_unlock(&arr->lock);
    return result;
}

void free_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->data);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}

// Logging and error handling mechanisms
