int initializeMessageBuffer(size_t numMessages, LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE **buffer,
                            const BufferConfig *config) {
    if (!numMessages || !buffer || !config || config->alignment < sizeof(void *)) {
        return ERROR_INVALID_INPUT;
    }

    size_t totalSize = numMessages * sizeof(LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE);

    // Calculate the aligned memory requirement
    size_t adjustment = (config->alignment - 1) + (totalSize % config->alignment);
    size_t alignedTotalSize = totalSize + adjustment;

    // Allocate buffer with alignment requirements
    void *rawMemory = NULL;
#if defined(_MSC_VER)
    if (_aligned_malloc(alignedTotalSize, config->alignment)) {
        rawMemory = _aligned_malloc(alignedTotalSize, config->alignment);
    }
#else
    if (posix_memalign(&rawMemory, config->alignment, alignedTotalSize) != 0) {
        return ERROR_MEMORY_ALLOCATION;
    }
#endif

    if (!rawMemory) {
        return ERROR_MEMORY_ALLOCATION;
    }

    // Calculate the start of the aligned buffer within the raw memory block
    LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *alignedBuffer = 
        (LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *)(((size_t)rawMemory + adjustment) & ~(config->alignment - 1));

    // Initialize memory to zero and assign to output parameter
    memset(alignedBuffer, 0, totalSize);
    *buffer = alignedBuffer;

    return SUCCESS;
}

// Example function to deallocate the buffer (consider thread safety)
void freeMessageBuffer(LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *buffer) {
