['```c
#include <stdlib.h>
#include <string.h>
#include <stdalign.h>
#include <pthread.h>

typedef struct {
    size_t bufferSize;
    size_t alignment;
    void (*evictionPolicy)(void *buffer, size_t recordSize, size_t numRecords);
} CacheConfig;

typedef struct {
    // Define fields for your data records here.
    int id;  // Example field
} DataRecord;

#define MEMORY_POOL_SIZE (1024 * 1024)  // Adjust according to needs

static unsigned char memoryPool[MEMORY_POOL_SIZE];
static pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t usedMemory = 0;

void* alignedMalloc(size_t alignment, size_t size);
void alignedFree(void *ptr);

int initializeDataCache(size_t numRecords, DataRecord **records, CacheConfig config) {
    if (!records || !config.evictionPolicy) return -1; // Invalid parameters

    pthread_mutex_lock(&poolMutex);  // Ensure thread safety
    size_t recordSize = sizeof(DataRecord);
    size_t requiredMemory = numRecords * recordSize;

    if (requiredMemory > config.bufferSize || requiredMemory + usedMemory > MEMORY_POOL_SIZE) {
        pthread_mutex_unlock(&poolMutex);
        return -2;  // Not enough memory available
    }

    void* buffer = alignedMalloc(config.alignment, requiredMemory);
    if (!buffer) {
        pthread_mutex_unlock(&poolMutex);
        return -3;  // Allocation failed
    }

    usedMemory += requiredMemory;
    *records = (DataRecord*)buffer;

    config.evictionPolicy(buffer, recordSize, numRecords);  // Apply eviction policy

    pthread_mutex_unlock(&poolMutex);
    return 0;  // Success
}

void* alignedMalloc(size_t alignment, size_t size) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

void alignedFree(void *ptr) {
    free(ptr);
}
```

### Explanation:
- **Memory Management**: The function uses a custom memory pool to manage allocations efficiently under concurrency. It locks the memory pool with a mutex to ensure thread safety.
