['Here's an implementation of the `lte_rrc_configurator` function in C, designed according to your specifications:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 2

typedef struct {
    // Define the structure for LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE
    int message_id;
    char configuration[256];
} LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE;

typedef struct {
    LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *messages;
    size_t count;
    size_t capacity;
    LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE **history_log;
    size_t history_count;
} MessageList;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int resize_message_list(MessageList *list) {
    size_t new_capacity = list->capacity * RESIZE_FACTOR;
    LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *new_messages = realloc(list->messages, new_capacity * sizeof(LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE));
    if (!new_messages) {
        log_error("Failed to resize message list");
        return 0;
    }
    list->messages = new_messages;
    list->capacity = new_capacity;
    return 1;
}

int add_message(MessageList *list, LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE message) {
    if (list->count >= list->capacity && !resize_message_list(list)) {
        log_error("Cannot add more messages: reached capacity limit");
        return -1;
    }

    list->messages[list->count] = message;
    list->count++;

    // Log the history of added messages
    LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE **new_history_log = realloc(list->history_log, (list->history_count + 1) * sizeof(LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *));
    if (!new_history_log) {
        log_error("Failed to log message history");
        return -1;
    }
    list->history_log = new_history_log;
    list->history_log[list->history_count] = &list->messages[list->count - 1];
    list->history_count++;

    return 0;
}

void query_message_history(MessageList *list) {
    for (size_t i = 0; i < list->history_count; i++) {
        LTE_RRC_CU_DOWNLINK_MESSAGE_TYPE *msg = list->history_log[i];
        printf("Message ID: %d, Configuration: %s\n", msg->message_id, msg->configuration);
    }
}

int lte_rrc_configurator(MessageList *list) {
    if (!list) return -1;

