```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int size;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    return list;
}

bool is_rnti_unique(CRCList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) return false;
        current = current->next;
    }
    return true;
}

int add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (!is_rnti_unique(list, pdu.RNTI)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Error: RNTI not unique
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Error: Memory allocation failed
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int populate_list(CRCList* list, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu.RNTI = rand() % 65536; // Example RNTI range
        pdu.CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu.CRCFLAG = rand() % 2;

        int result = add_pdu(list, pdu);
        if (result != 0) {
            free_list(list);
            return result;
        }
    }
    return 0; // Success
}

int main() {
    CRCList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return -1;
    }

    int result = populate_list(list, 1000); // Populate with 1000 entries
    if (result != 0) {
        fprintf(stderr, "Failed to populate list: %d\n", result);
        free_list(list);
        return -1;
    }

    printf("List populated successfully with %u entries.\n", list->size);

    free_list(list);
    return 0;
}
```

