}

void free_packet_metadata(packet_metadata_t **packets, int count) {
    for (int i = 0; i < count; ++i) {
        if (packets[i]) {
            free(packets[i]->data);
            free(packets[i]);
        }
    }
    free(packets);
}

packet_metadata_t** initialize_packets(int num_packets, size_t packet_size, int use_tcp) {
    size_t total_memory = num_packets * sizeof(packet_metadata_t) + num_packets * (packet_size - sizeof(mac_header_t) - sizeof(ip_header_t));

    if (total_memory > SYSTEM_MEMORY_THRESHOLD) {
        printf("Exceeded memory threshold. Adjusting number of packets.\n");
        int adjusted_num_packets = SYSTEM_MEMORY_THRESHOLD / (sizeof(packet_metadata_t) + packet_size - sizeof(mac_header_t) - sizeof(ip_header_t));
        total_memory = adjusted_num_packets * sizeof(packet_metadata_t) + adjusted_num_packets * (packet_size - sizeof(mac_header_t) - sizeof(ip_header_t));

        if (!adjusted_num_packets || !validate_packet_size(packet_size)) {
            printf("Invalid packet configuration. Exiting initialization.\n");
            return NULL;
        }
    }

    packet_metadata_t **packets = malloc(num_packets * sizeof(packet_metadata_t*));
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < num_packets; ++i) {
        packets[i] = malloc(sizeof(packet_metadata_t));
        if (!packets[i]) {
            perror("Memory allocation failed");
            free_packet_metadata(packets, i);
            return NULL;
        }

        // Initialize headers
        memset(&packets[i]->mac, 0xFF, sizeof(mac_header_t)); // Broadcast MAC for simplicity
        packets[i]->ip.version = 4;
        packets[i]->ip.ihl = 5; // Header length in 32-bit words
        packets[i]->ip.total_length = htons(packet_size);
        packets[i]->ip.protocol = use_tcp ? IPPROTO_TCP : IPPROTO_UDP;

        if (!validate_checksum(&packets[i]->ip)) {
            printf("Invalid checksum for packet %d. Skipping initialization.\n", i + 1);
            free(packets[i]);
            packets[i] = NULL;
            continue;
        }

        // Allocate data space
        packets[i]->data = malloc(packet_size - sizeof(mac_header_t) - sizeof(ip_header_t));
        if (!packets[i]->data) {
            perror("Memory allocation failed");
            free(packets[i]);
            packets[i] = NULL;
            continue;
        }

        memset(packets[i]->data, 0, packet_size - sizeof(mac_header_t) - sizeof(ip_header_t)); // Clear data

        if (use_tcp) {
            packets[i]->payload.tcp.src_port = htons(12345);
            packets[i]->payload.tcp.dst_port = htons(80);
            packets[i]->payload.tcp.seq_num = htonl(i + 1); // Sequence number
        } else {
            packets[i]->payload.udp.src_port = htons(12346);
            packets[i]->payload.udp.dst_port = htons(53);
        }
    }

    return packets;
}

