PduArray* createPduArray(size_t initialCapacity) {
    PduArray* array = malloc(sizeof(PduArray));
    if (!array) return NULL;
    array->pdus = calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->pdus) {
        free(array);
        return NULL;
    }
    array->size = 0;
    array->capacity = initialCapacity;
    return array;
}

void resizePduArray(PduArray* array, size_t newCapacity) {
    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(array->pdus, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (temp) {
        array->pdus = temp;
        array->capacity = newCapacity;
    }
}

int addPdu(PduArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validateRNTI(pdu.RNTI)) return 0;

    if (array->size == array->capacity) {
        resizePduArray(array, array->capacity * 2);
    }

    array->pdus[array->size++] = pdu;
    return 1;
}

void serializePdus(const PduArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&array->size, sizeof(size_t), 1, file);
    fwrite(array->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->size, file);

    fclose(file);
}

int deserializePdus(PduArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return 0;

    size_t newSize;
    fread(&newSize, sizeof(size_t), 1, file);

    resizePduArray(array, newSize);
    fread(array->pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), newSize, file);
    array->size = newSize;

    fclose(file);
    return 1;
}

void freePduArray(PduArray* array) {
    if (array) {
        free(array->pdus);
        free(array);
    }
}

