typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = pdu;
    node->next = NULL;
    return node;
}

void free_list(Node** head_ref) {
    Node* current = *head_ref;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head_ref = NULL;
}

int check_rnti_distance(Node* list, uint16_t rnti, int min_distance) {
    int count = 0;
    Node* node = list;

    while (node != NULL && count < min_distance) {
        if (node->data.rnti == rnti)
            return 0;
        node = node->next;
        count++;
    }
    return 1;
}

void* generate_nfa_pds(void* arg) {
    int num_elements = *((int*)arg);
    Node* head = NULL, *tail = NULL;

    for (int i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&lock);

        // Create and initialize a new NFAPI_CRC_INDICATION_PDU_T
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_info_tag = ...; // Initialize as required
