        pdu.crc_indication_rel8_tag = ...; // Initialize as required
        pdu.crcflag = rand() % 2;

        // Ensure no two consecutive structures share the same `RNTI` and maintain distance
        if (tail != NULL && tail->data.rnti == pdu.rnti) {
            --i;
            pthread_mutex_unlock(&lock);
            continue;
        }

        if (!check_rnti_distance(head, pdu.rnti, MIN_DISTANCE_BETWEEN_RNTI)) {
            --i;
            pthread_mutex_unlock(&lock);
            continue;
        }

        // Manage the list and memory efficiently
        Node* new_node = create_node(pdu);
        if (new_node == NULL) {
            free_list(&head);
            pthread_mutex_unlock(&lock);
            return NULL; // Out of memory, handle appropriately in real use
        }

        if (!tail) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }

        pthread_mutex_unlock(&lock);

        // Simulate high load processing
