['Below is a C code snippet implementing the required functionality using POSIX threads (pthreads) for concurrency management. It includes a dynamic array of `LTE_RRC_NAS_Message` structures, thread-safe operations using mutexes, and atomic counters for tracking processed messages.

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <stdatomic.h>

typedef enum {
    NAS_MESSAGE_TYPE_A,
    NAS_MESSAGE_TYPE_B,
    // Add more message types as needed
} NAS_Message_Type;

typedef struct {
    NAS_Message_Type type;
    uint16_t id;
    char *payload;  // Dynamic payload content
} LTE_RRC_NAS_Message;

typedef struct {
    LTE_RRC_NAS_Message **messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    atomic_uint processed_messages;
} MessageManager;

MessageManager* init_message_manager(size_t initial_capacity) {
    MessageManager *manager = (MessageManager *)malloc(sizeof(MessageManager));
    if (!manager) return NULL;

    manager->messages = (LTE_RRC_NAS_Message **)calloc(initial_capacity, sizeof(LTE_RRC_NAS_Message *));
    if (!manager->messages) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    atomic_init(&manager->processed_messages, 0);

    return manager;
}

void resize_message_array(MessageManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_RRC_NAS_Message **new_messages = (LTE_RRC_NAS_Message **)realloc(manager->messages, new_capacity * sizeof(LTE_RRC_NAS_Message *));
    if (!new_messages) return; // Handle memory allocation failure gracefully

    for (size_t i = manager->capacity; i < new_capacity; ++i) {
        new_messages[i] = NULL;
    }

    pthread_mutex_lock(&manager->mutex);
    manager->messages = new_messages;
    manager->capacity = new_capacity;
    pthread_mutex_unlock(&manager->mutex);
}

int add_message(MessageManager *manager, NAS_Message_Type type, uint16_t id, const char *payload_content) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count == manager->capacity) {
        resize_message_array(manager);
        if (!manager->messages) { // Ensure resizing was successful
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    LTE_RRC_NAS_Message *message = (LTE_RRC_NAS_Message *)malloc(sizeof(LTE_RRC_NAS_Message));
    if (!message) {
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    message->type = type;
    message->id = id;
    size_t payload_length = strlen(payload_content) + 1; // Include null terminator
    message->payload = (char *)malloc(payload_length);
    if (!message->payload) {
        free(message);
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    snprintf(message->payload, payload_length, "%u", atomic_fetch_add(&manager->processed_messages, 1));

    manager->messages[manager->count++] = message;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void free_message_manager(MessageManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        LTE_RRC_NAS_Message *msg = manager->messages[i];
        if (msg) {
            free(msg->payload);
            free(msg);
        }
    }

    free(manager->messages);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int main() {
    MessageManager *manager = init_message_manager(10);

    // Example usage with threads
    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, (void *(*)(void *))add_message, manager) != 0) {
        fprintf(stderr, "Failed to create thread\n");
    }
    if (pthread_create(&thread2, NULL, (void *(*)(void *))add_message, manager) != 0) {
        fprintf(stderr, "Failed to create thread\n");
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    free_message_manager(manager);
    return 0;
}
```

### Explanation:

- **Dynamic Array Management**: The code initializes a dynamic array of pointers to `LTE_RRC_NAS_Message` structures. It resizes the array when needed.

- **Thread Safety**: Mutexes are used to protect access to shared resources (`messages`, `capacity`, and `count`) ensuring thread safety.

- **Concurrency Handling**: Atomic operations on `processed_messages` ensure that counting is thread-safe without requiring mutex locks, optimizing performance.

- **Memory Management**: Proper memory allocation and deallocation are handled with checks for allocation failures. 

- **Error Handling**: Graceful error handling is provided by checking the results of memory allocations and using return codes to indicate success or failure.

This code can be extended further based on specific application needs, such as adding more message types or additional thread management features.']

