void update_crcflag(NFAPI_CRC_INDICATION_PDU_T *entry);
int calculate_checksum(uint32_t ue_info, uint16_t rnti);

// Initialize the dynamic list
void initialize_list(DynamicList *dynamicList) {
    dynamicList->size = 0;
    dynamicList->capacity = 256; // Initial capacity
    dynamicList->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(dynamicList->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamicList->list) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    threading.Lock_Init(&dynamicList->lock);
}

// Resize the list if needed
void resize_list_if_needed(DynamicList *dynamicList) {
    if (dynamicList->size >= dynamicList->capacity && dynamicList->capacity < 1024) {
        size_t new_capacity = dynamicList->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(dynamicList->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            perror("Failed to reallocate memory");
            exit(EXIT_FAILURE);
        }
        dynamicList->list = new_list;
        dynamicList->capacity = new_capacity;
