    entry->CRCFLAG = (checksum % 2 == 0); // Example condition for updating CRCFLAG
}

// Calculate a simple checksum
int calculate_checksum(uint32_t ue_info, uint16_t rnti) {
    return (ue_info ^ rnti) & 0xFF; // Simple XOR-based checksum
}

// Add an entry to the list
void add_entry(DynamicList *dynamicList, NFAPI_CRC_INDICATION_PDU_T entry) {
    threading.Lock_Acquire(&dynamicList->lock);

    resize_list_if_needed(dynamicList);

    dynamicList->list[dynamicList->size] = entry;
    update_crcflag(&dynamicList->list[dynamicList->size]);

    dynamicList->size++;

    threading.Lock_Release(&dynamicList->lock);
}

// Periodically update the list
void periodically_update_list(DynamicList *dynamicList) {
    while (1) { // Replace with a suitable condition for your real-time system
        for (size_t i = 0; i < dynamicList->size; ++i) {
            update_crcflag(&dynamicList->list[i]);
        }
        // Sleep or yield to simulate periodic updates, e.g., threading.sleep(1)
    }
}

// Clean up resources
void cleanup_list(DynamicList *dynamicList) {
    threading.Lock_Acquire(&dynamicList->lock);

    free(dynamicList->list);
    dynamicList->list = NULL;
    dynamicList->size = 0;
    dynamicList->capacity = 0;

    threading.Lock_Release(&dynamicList->lock);
}
