    pthread_mutex_lock(&array->lock);

    resize_array_if_needed(array);

    array->array[array->size++] = element;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_element(DynamicArray* array, size_t index) {
    if (!array || index >= array->size) return -1;

    pthread_mutex_lock(&array->lock);

    for (size_t i = index; i < array->size - 1; ++i) {
        array->array[i] = array->array[i + 1];
    }

    --array->size;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int update_element(DynamicArray* array, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!array || index >= array->size) return -1;

