json_t* handle_user_request(const char *json_input) {
    json_error_t error;
    json_t *root = json_loads(json_input, 0, &error);
    if (!root) {
        printf("Error parsing JSON: %s\n", error.text);
        return json_pack("{s:s}", "status", "failure");
    }

    json_t *name = json_object_get(root, "name");
    json_t *email = json_object_get(root, "email");
    json_t *password = json_object_get(root, "password");
    json_t *id_json = json_object_get(root, "id");
    json_t *sub_action = json_object_get(root, "sub_action");

    if (!json_is_string(name) || !json_is_string(email) || !json_is_string(password)) {
        return json_pack("{s:s}", "status", "failure");
    }

    pthread_mutex_lock(&user_mutex);

    int id = -1;
    if (id_json && json_is_integer(id_json)) {
        id = json_integer_value(id_json);
    }

    int idx = -1;
    for (int i = 0; i < user_count; ++i) {
        if ((id == -1 || users[i].id == id) &&
            strcmp(json_string_value(name), users[i].name) == 0 &&
            strcmp(json_string_value(email), users[i].email) == 0) {
            idx = i;
            break;
        }
    }

    int status_success = 1;
    if (sub_action && json_is_string(sub_action) && strcmp(json_string_value(sub_action), "delete") == 0) {
        if (idx != -1) {
            for (int i = idx; i < user_count - 1; ++i) {
                users[i] = users[i + 1];
            }
            --user_count;
        } else {
            status_success = 0;
        }
    } else {
        if (idx == -1) { // Create new account
            if (user_count < MAX_USERS) {
                idx = user_count++;
                users[idx].id = id == -1 ? rand() % 100000 : id;  // Assign random ID or given one
            } else {
                status_success = 0;
            }
        }

        if (status_success && idx != -1) {
            strncpy(users[idx].name, json_string_value(name), sizeof(users[idx].name));
            strncpy(users[idx].email, json_string_value(email), sizeof(users[idx].email));
            strncpy(users[idx].password, json_string_value(password), sizeof(users[idx].password));
        }
    }

    pthread_mutex_unlock(&user_mutex);

    return json_pack("{s:s}", "status", status_success ? "success" : "failure");
}

int main() {
    // Example JSON request
    const char *json_input = "{\"name\":\"John Doe\", \"email\":\"john@example.com\", \"password\":\"securepass\"}";

    json_t* response = handle_user_request(json_input);
    printf("%s\n", json_dumps(response, JSON_COMPACT));
    json_decref(response);

    return 0;
}
