#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include "thread_safe_queue.h"  // Assuming a thread-safe queue library is available
#include "logging_framework.h"  // Assuming an existing logging framework

#define MAX_BATCH_SIZE 1000

typedef struct {
    uint8_t data[1024];  // Example packet data size; adjust as needed
    size_t length;
} UDP_PACKET;

// Thread-safe structure to manage the dynamic list of UDP packets
typedef struct {
    ThreadSafeQueue *packet_queue;
    pthread_mutex_t batch_lock;
    int shutdown_flag;
} PacketManager;

void process_packet_batch(UDP_PACKET **batch, size_t count) {
    // Process the packet batch (dummy processing function)
    for (size_t i = 0; i < count; ++i) {
        logging_framework_log(LOG_INFO, "Processing packet %zu", i);
        // Actual packet processing logic
    }
}

void *packet_processing_thread(void *arg) {
    PacketManager *manager = (PacketManager *)arg;
    UDP_PACKET *batch[MAX_BATCH_SIZE];
    size_t count;

    while (!manager->shutdown_flag || !ThreadSafeQueueIsEmpty(manager->packet_queue)) {
        count = ThreadSafeQueueDequeueMultiple(manager->packet_queue, batch, MAX_BATCH_SIZE);
        if (count > 0) {
            pthread_mutex_lock(&manager->batch_lock);
            process_packet_batch(batch, count);
            pthread_mutex_unlock(&manager->batch_lock);
        }
    }

    return NULL;
}

PacketManager *initialize_packet_manager() {
    PacketManager *manager = malloc(sizeof(PacketManager));
    if (!manager) {
        logging_framework_log(LOG_ERROR, "Failed to allocate memory for PacketManager");
        return NULL;
    }

    manager->packet_queue = ThreadSafeQueueCreate();
    pthread_mutex_init(&manager->batch_lock, NULL);
    manager->shutdown_flag = 0;

    return manager;
}

void shutdown_packet_manager(PacketManager *manager) {
    if (manager) {
        manager->shutdown_flag = 1;
        ThreadSafeQueueFlush(manager->packet_queue); // Ensure all packets are processed
        pthread_mutex_destroy(&manager->batch_lock);
        ThreadSafeQueueDestroy(manager->packet_queue);
        free(manager);
    }
}

void enqueue_packet(PacketManager *manager, UDP_PACKET *packet) {
    if (ThreadSafeQueueEnqueue(manager->packet_queue, packet)) {
        logging_framework_log(LOG_DEBUG, "Packet enqueued successfully");
    } else {
        logging_framework_log(LOG_ERROR, "Failed to enqueue packet");
    }
}
