    int memory_available;
} NFAPI_CRC_INDICATION_LIST;

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int is_power_of_two(size_t n) {
    return (n && !(n & (n - 1)));
}

size_t next_power_of_two(size_t n) {
    --n;
    for (size_t i = 1; i < sizeof(n) * 8; ++i)
        n |= n >> i;
    return ++n;
}

void resize_list(NFAPI_CRC_INDICATION_LIST* list, size_t new_capacity) {
    if (!is_power_of_two(new_capacity)) {
        new_capacity = next_power_of_two(new_capacity);
    }
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) {
        log_error("Memory allocation failed during resizing.");
        pthread_cond_broadcast(&list->cond_var); // Wake up any waiting threads
        return;
    }
    list->capacity = new_capacity;
    list->data = new_data;
}

void init_list(NFAPI_CRC_INDICATION_LIST* list) {
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->data = malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->data == NULL) {
        log_error("Initial memory allocation failed.");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond_var, NULL);
    list->memory_available = 1;
}

void free_list(NFAPI_CRC_INDICATION_LIST* list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    pthread_cond_destroy(&list->cond_var);
}

int add_pdu_to_list(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    while (list->size == list->capacity && !list->memory_available) {
        pthread_cond_wait(&list->cond_var, &list->lock);
    }

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_REALLOC_SIZE)
            return -1; // Out of memory handling
        resize_list(list, new_capacity);
    }

    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);

    pthread_cond_broadcast(&list->cond_var); // Notify any waiting threads about the change
    return 0;
}

void process_batch(NFAPI_CRC_INDICATION_LIST* list, size_t max_per_batch) {
    static NFAPI_CRC_INDICATION_PDU_T buffer[100];
    static int buffer_count = 0;

    pthread_mutex_lock(&list->lock);

    while (buffer_count > 0 && list->size < max_per_batch) {
        memcpy(&list->data[list->size++], &buffer[--buffer_count], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    if (buffer_count == 100)
        pthread_cond_signal(&list->cond_var);

    pthread_mutex_unlock(&list->lock);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL)); // Normally, you would seed once in your main program
    pdu->rx_ue_info_tag.valid = 1;
    pdu->rnti = rand() % UINT32_MAX;
    pdu->crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void* nfaapi_feed_thread(void* arg) {
    NFAPI_CRC_INDICATION_LIST* list = (NFAPI_CRC_INDICATION_LIST*)arg;

    while (1) { // Simulated feed; replace with actual data source
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);

        if (add_pdu_to_list(list, pdu)) {
            pthread_mutex_lock(&list->lock);
            buffer[buffer_count++] = pdu;
            pthread_mutex_unlock(&list->lock);

            if (buffer_count == 100) { // Buffer full
                pthread_cond_signal(&list->cond_var); 
            }
        }
    }

    return NULL;
}

int main() {
    NFAPI_CRC_INDICATION_LIST list;
    init_list(&list);

    pthread_t thread_id;
