    for (int i = 0; i < MAX_PACKETS; ++i) {
        LTE_DL_Data_Packet *packet = malloc(sizeof(LTE_DL_Data_Packet));
        if (!packet) return;
        memset(packet, 0, sizeof(LTE_DL_Data_Packet));
