    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (pool->packets[i]) {
            LTE_DL_Data_Packet *packet = pool->packets[i];
            pool->packets[i] = NULL;
            --pool->pool_size;
            pthread_mutex_unlock(&pool->mutex);
