#define CRCFLAG_MAX 15

typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

PduList* create_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) {
        fprintf(stderr, "Memory allocation error: Unable to allocate memory for PDU List\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(PduList* list) {
    Node *current, *next;
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu, uint16_t rnti_min, uint16_t rnti_max) {
    if (!list || pdu.crcflag > CRCFLAG_MAX || pdu.rnti < rnti_min || pdu.rnti > rnti_max) {
        fprintf(stderr, "Validation error: Invalid PDU or RNTI range\n");
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation error: Unable to allocate memory for new node\n");
        return -1;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int filter_pdus(PduList* list, uint16_t rnti_min, uint16_t rnti_max, NFAPI_CRC_INDICATION_PDU_T** filtered_list) {
    if (!list || !filtered_list) {
        fprintf(stderr, "Error: Invalid arguments to filter function\n");
        return -1;
    }

    Node* current = list->head;
    int count = 0;

    pthread_mutex_lock(&list->lock);

    while (current != NULL) {
        if (current->data.rnti >= rnti_min && current->data.rnti <= rnti_max) {
            count++;
        }
        current = current->next;
    }

    *filtered_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*filtered_list) {
        fprintf(stderr, "Memory allocation error: Unable to allocate memory for filtered list\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    current = list->head;
    int index = 0;

    while (current != NULL) {
        if (current->data.rnti >= rnti_min && current->data.rnti <= rnti_max) {
            (*filtered_list)[index++] = current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void log_operation_details(const char* message) {
    // Placeholder for logging mechanism
    printf("LOG: %s\n", message);
}

int main() {
    PduList* pdu_list = create_list();
    if (!pdu_list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_information_tag = 1234; // Example tag
    pdu.rnti = 5678; // Example RNTI
