#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_STREAMS 1024
#define DEFAULT_BUFFER_SIZE 4096

typedef struct {
    int stream_id;
    char *buffer;
    size_t buffer_size;
    size_t data_size;
} Stream;

typedef struct {
    Stream streams[MAX_STREAMS];
    int active_streams;
    void (*error_handler)(const char *);
} NetworkInterface;

void default_error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

NetworkInterface* initialize_network_interface(void (*err_handler)(const char *)) {
    if (!err_handler)
        err_handler = default_error_handler;

    NetworkInterface *interface = (NetworkInterface*)calloc(1, sizeof(NetworkInterface));
    if (!interface) {
        err_handler("Failed to allocate memory for network interface");
        return NULL;
    }

    memset(interface->streams, 0, sizeof(interface->streams));
    interface->active_streams = 0;
    interface->error_handler = err_handler;

    // Initialize each stream with default configuration
    for (int i = 0; i < MAX_STREAMS; ++i) {
        Stream *stream = &interface->streams[i];
        stream->buffer_size = DEFAULT_BUFFER_SIZE;
        if (!(stream->buffer = malloc(stream->buffer_size))) {
            err_handler("Failed to allocate buffer for a stream");
            // Cleanup previously allocated streams
            while (--i >= 0)
                free(interface->streams[i].buffer);
            free(interface);
            return NULL;
        }
    }

    return interface;
}

int configure_stream(NetworkInterface *interface, int stream_id, size_t buffer_size) {
    if (!interface || stream_id < 0 || stream_id >= MAX_STREAMS) {
        if (interface && interface->error_handler)
            interface->error_handler("Invalid stream ID");
        return -1;
    }

    Stream *stream = &interface->streams[stream_id];

    // Reallocate buffer with new size, keeping data intact if possible
    char *new_buffer = realloc(stream->buffer, buffer_size);
    if (!new_buffer) {
        interface->error_handler("Failed to reallocate buffer for a stream");
        return -1;
    }

    stream->buffer = new_buffer;
    stream->buffer_size = buffer_size;
    stream->data_size = 0; // Reset data size on reconfiguration

    return 0;
}

void free_network_interface(NetworkInterface *interface) {
    if (!interface)
        return;

    for (int i = 0; i < MAX_STREAMS; ++i) {
        if (interface->streams[i].buffer)
            free(interface->streams[i].buffer);
    }

    free(interface);
}

// Example usage
int main() {
    NetworkInterface *network_interface = initialize_network_interface(NULL);

    if (!network_interface) return 1;

    configure_stream(network_interface, 0, 8192); // Configure stream 0 with a larger buffer

    free_network_interface(network_interface);

    return 0;
}
```

