#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_RNTI 65535
#define MIN_CRCFLAG 0x00
#define MAX_CRCFLAG 0xFF
#define MAX_UPDATES_PER_SECOND 100

typedef struct {
    uint16_t RNTI;
    bool RX_UE_INFORMATION_TAG;
    unsigned char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PDULIST;

// Database integration placeholder
void store_in_database(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Implement database storage logic here
}

void log_operation(const char* message) {
    printf("%s\n", message);
}

bool is_crcflag_valid(unsigned char crcflag) {
    return (crcflag >= MIN_CRCFLAG && crcflag <= MAX_CRCFLAG);
}

PDULIST* create_list() {
    PDULIST* list = (PDULIST*)malloc(sizeof(PDULIST));
    if (!list) {
        log_operation("Memory allocation failed for PDULIST");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(PDULIST* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_pdu_to_list(PDULIST* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_crcflag_valid(pdu.CRC_INDICATION_REL8_TAG)) {
        log_operation("CRCFLAG value out of bounds");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_operation("Memory allocation failed for Node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    store_in_database(pdu);

    pthread_mutex_unlock(&list->lock);
}

bool filter_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, uint16_t min_rnti, uint16_t max_rnti) {
    return (pdu->RNTI >= min_rnti && pdu->RNTI <= max_rnti);
}

void process_pdus(PDULIST* list, NFAPI_CRC_INDICATION_PDU_T* pdus, size_t count, 
                  uint16_t min_rnti, uint16_t max_rnti) {
    time_t last_time = 0;
    size_t processed_count = 0;

    for (size_t i = 0; i < count; ++i) {
        if (!filter_pdu(&pdus[i], min_rnti, max_rnti)) continue;

        time_t current_time = time(NULL);
        if (difftime(current_time, last_time) < 1.0 / MAX_UPDATES_PER_SECOND) {
            log_operation("Rate limit exceeded");
            continue;
        }
        last_time = current_time;
        ++processed_count;

        add_pdu_to_list(list, pdus[i]);
    }

    log_operation("Processed PDUs count: %zu", processed_count);
}

void* async_process(void* args) {
    PDULIST* list = (PDULIST*)args;
    // Simulate receiving and processing incoming PDUs
    NFAPI_CRC_INDICATION_PDU_T pdus[1000];
    for (int i = 0; i < 1000; ++i) {
        pdus[i].RNTI = rand() % MAX_RNTI;
        pdus[i].RX_UE_INFORMATION_TAG = rand() % 2 == 1;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % (MAX_CRCFLAG - MIN_CRCFLAG + 1) + MIN_CRCFLAG;
    }
    process_pdus(list, pdus, 1000, 1000, 2000);
    return NULL;
}

int main() {
    PDULIST* list = create_list();
    if (!list) return EXIT_FAILURE;

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, async_process, (void*)list);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_list(list);
    return EXIT_SUCCESS;
}
