#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Array_Manager;

void log_error(const char* message, FILE* log_file) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
    }
}

CRC_Array_Manager* create_crc_array_manager(size_t initial_capacity, FILE* log_file) {
    CRC_Array_Manager *manager = malloc(sizeof(CRC_Array_Manager));
    if (!manager) {
        log_error("Memory allocation failed for manager.", log_file);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        log_error("Memory allocation failed for array.", log_file);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;

    return manager;
}

void destroy_crc_array_manager(CRC_Array_Manager *manager, FILE* log_file) {
    if (manager != NULL) {
        pthread_mutex_lock(&manager->lock);

        free(manager->array);
        pthread_mutex_unlock(&manager->lock);

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_crc_pdu(CRC_Array_Manager *manager, NFAPI_CRC_INDICATION_PDU_T pdu, FILE* log_file) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) {
            pthread_mutex_unlock(&manager->lock);
            log_error("Exceeded maximum allowed elements.", log_file);
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            pthread_mutex_unlock(&manager->lock);
            log_error("Reallocation failed for array.", log_file);
            return -1;
        }

        manager->array = temp_array;
        manager->capacity = new_capacity;
    }

    memcpy(&(manager->array[manager->size]), &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_pdu(CRC_Array_Manager *manager, size_t index) {
    if (!manager || index >= manager->size) return NULL;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &(manager->array[index]);

    pthread_mutex_unlock(&manager->lock);
    return pdu;
}

int modify_crc_pdu(CRC_Array_Manager *manager, size_t index, int new_cflag, FILE* log_file) {
    if (!manager || index >= manager->size) return -1;

    pthread_mutex_lock(&manager->lock);

    NFAPI_CRC_INDICATION_PDU_T* pdu = &(manager->array[index]);
    pdu->tag.CRCFLAG = new_cflag;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void initialize_random_crc(CRC_Array_Manager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_crc_pdu(manager, i);
        if (pdu) {
            pdu->tag.CRCFLAG = rand() % 2;
        }
    }
}

int main() {
    FILE *log_file = fopen("errors.log", "w");
    CRC_Array_Manager *manager = create_crc_array_manager(10, log_file);

    for (size_t i = 0; i < 20; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100;
        pdu.RNTI = rand() % 50;

        if (add_crc_pdu(manager, pdu, log_file) != 0) break;
    }

    initialize_random_crc(manager);

    for (size_t i = 0; i < manager->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = get_crc_pdu(manager, i);
        if (pdu) {
            printf("PDU %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
                   i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->tag.CRCFLAG);
        }
    }

    destroy_crc_array_manager(manager, log_file);
    fclose(log_file);

    return 0;
}
