// Mutex for thread safety during allocation
pthread_mutex_t alloc_mutex = PTHREAD_MUTEX_INITIALIZER;

// Logging configuration structure
typedef struct {
    int verbosity;
    FILE *log_file;
} LogConfig;

LogConfig log_config = {1, stdout}; // Default logging to stdout with default verbosity

