void set_log_config(int verbosity, const char* file_path);
void log_message(const char* message);

NFAPI_CRC_INDICATION_PDU_T* allocate_crc_pdu_array(size_t N) {
    pthread_mutex_lock(&alloc_mutex); // Ensure thread-safe allocation

    // Calculate required memory size for N structures
    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Dynamically allocate memory
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(total_size);
    if (!array) {
        log_message("Memory allocation failed");
        pthread_mutex_unlock(&alloc_mutex);
        return NULL;
    }

    // Initialize the allocated structures
    for (size_t i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 65536;  // Example initialization
        array[i].RNTI = rand() % 4294967296;
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2); // Random CRCFLAG
    }

    log_message("Successfully allocated and initialized CRC PDU array");
    pthread_mutex_unlock(&alloc_mutex);
    return array;
}

void set_log_config(int verbosity, const char* file_path) {
    log_config.verbosity = verbosity;
    if (file_path != NULL) {
        log_config.log_file = fopen(file_path, "a");
        if (!log_config.log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    } else {
        log_config.log_file = stdout; // Default
    }
}

void log_message(const char* message) {
    if (log_config.verbosity > 0) { 
        fprintf(log_config.log_file, "%s\n", message);
        fflush(log_config.log_file); // Ensure the message is written immediately
    }
}

// Example unit tests for validation
void test_crc_pdu_allocation() {
    const size_t test_size = 100000;  // Large N value for stress testing

    // Test successful allocation with large input
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_crc_pdu_array(test_size);
    if (array) {
        log_message("Test passed: Successful allocation with large input");
        free(array); // Clean up after test
    } else {
        log_message("Test failed: Allocation failure with large input");
    }

    // Test edge case of zero size
    array = allocate_crc_pdu_array(0);
    if (array == NULL) {  // Expecting a NULL pointer for N=0
        log_message("Test passed: Correctly handled zero-size allocation");
    } else {
        free(array); // Clean up after test
        log_message("Test failed: Incorrect handling of zero-size allocation");
    }

    // Test under constrained memory conditions by setting limit
    set_log_config(2, "error.log");  // Increase verbosity for more logs in error case
    array = allocate_crc_pdu_array(test_size * 10); // Attempt to exceed typical limits
    if (array == NULL) {
        log_message("Test passed: Proper handling of constrained memory conditions");
    } else {
        free(array);
        log_message("Test failed: Allocation succeeded unexpectedly under constrained memory");
    }
}

int main() {
    srand(time(NULL));  // Seed random number generator

    set_log_config(1, "system.log");  // Set logging configuration
    test_crc_pdu_allocation();

    return 0;
}
