#define DEFAULT_PLACEHOLDER_VALUE 0xAA

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_RX_PDU_T *pdu_list;
    size_t count;
} DynamicList;

void init_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list_mutex);
    list->pdu_list = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list_mutex);
}

int add_pdu_to_list(DynamicList *list, NFAPI_RX_PDU_T pdu) {
    size_t new_count = list->count + 1;
    NFAPI_RX_PDU_T *new_pdu_list;

    // Allocate memory for the new list
    pthread_mutex_lock(&list_mutex);
    new_pdu_list = (NFAPI_RX_PDU_T *)realloc(list->pdu_list, new_count * sizeof(NFAPI_RX_PDU_T));
    if (!new_pdu_list) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list_mutex);
        return -1;
    }

    // Copy existing data and add the new pdu
    memcpy(new_pdu_list, list->pdu_list, list->count * sizeof(NFAPI_RX_PDU_T));
    new_pdu_list[list->count] = pdu;

    // Free old list memory if any, set new list pointer and count
    free(list->pdu_list);
    list->pdu_list = new_pdu_list;
    list->count = new_count;

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

int manage_nfa_list(DynamicList *nfa_list) {
    int status;
    NFAPI_RX_PDU_T pdu;

    // Get message size from the external data source
    status = get_message_size();
    if (status < 0) {
        fprintf(stderr, "Failed to retrieve message size\n");
        return -1;
    }

    // Initialize PDU with message size and allocate buffer
    pdu.message_size = status;

    // Allocate buffer for payload
    pdu.payload_buffer = malloc(pdu.message_size);
    if (!pdu.payload_buffer) {
        fprintf(stderr, "Failed to allocate memory for payload\n");
        return -1;
    }

    // Initialize the buffer with a default placeholder value
    memset(pdu.payload_buffer, DEFAULT_PLACEHOLDER_VALUE, pdu.message_size);

    // Add PDU to dynamic list
    if (add_pdu_to_list(nfa_list, pdu) != 0) {
        free(pdu.payload_buffer);  // Clean up on failure
        return -1;
    }

    return 0;
}

void cleanup_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list_mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->pdu_list[i].payload_buffer);  // Free each buffer
    }
    free(list->pdu_list);  // Free the list itself
    list->pdu_list = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list_mutex);
}

