typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t timestamp;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for list\n");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_to_list(CRCList* list, int N, int M) {
    if (!list || N > M) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&list->lock);

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Failed to allocate memory for node\n");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }

        // Set structure fields with random values
        new_node->data.RX_UE_INFORMATION_TAG = rand() % 256; // Example range
        new_node->data.RNTI = rand() % 65536;                // Example range
        new_node->data.CRC_INDICATION_REL8_TAG = rand() & 0xFF;

        // Set timestamp
        time(&new_node->timestamp);

        // Insert at the head of the list for O(1) insertion
        new_node->next = list->head;
        list->head = new_node;

        pthread_mutex_unlock(&list->lock);
    }

    return 0;
}

void free_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    int N = 5; // Number of structures to manage
    int M = 10; // Maximum allowed structures at any time

    CRCList* list = create_list();
    if (!list) return -1;

    add_to_list(list, N, M);

    free_list(list);

    return 0;
}
