#include <pthread.h>
#include <time.h>

typedef struct {
    int eventID;
    time_t timestamp;
    int statusFlag; // 0: pending, 1: processed, etc.
} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TrafficEventManager;

TrafficEventManager* initTrafficEventManager(size_t initialCapacity) {
    TrafficEventManager *manager = (TrafficEventManager*)malloc(sizeof(TrafficEventManager));
    if (!manager) return NULL;

    manager->events = (TrafficEvent*)malloc(initialCapacity * sizeof(TrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int addTrafficEvent(TrafficEventManager *manager, int eventID, int statusFlag) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        TrafficEvent *newEvents = (TrafficEvent*)realloc(manager->events, newCapacity * sizeof(TrafficEvent));
        if (!newEvents) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }

    TrafficEvent event;
    event.eventID = eventID;
    event.timestamp = time(NULL);
    event.statusFlag = statusFlag;

    manager->events[manager->count++] = event;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int updateTrafficEventStatus(TrafficEventManager *manager, int eventID, int newStatus) {
    if (!manager) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].eventID == eventID) {
            manager->events[i].statusFlag = newStatus;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return -1;
}

void freeTrafficEventManager(TrafficEventManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->events);
        free(manager);
    }
}
