#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <stdbool.h>

#define INITIAL_POOL_SIZE 10

typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_flag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
} PoolNode;

typedef struct {
    PoolNode* head;
    PoolNode* tail;
    size_t current_size;
    pthread_mutex_t lock;
    pthread_key_t thread_local_data;
} NFAPICRCPool;

NFAPICRCPool* create_pool(size_t initial_size) {
    NFAPICRCPool* pool = malloc(sizeof(NFAPICRCPool));
    if (!pool) return NULL;

    pool->head = NULL;
    pool->tail = NULL;
    pool->current_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_key_create(&pool->thread_local_data, free);

    for (size_t i = 0; i < initial_size; ++i) {
        add_to_pool(pool);
    }

    return pool;
}

void destroy_pool(NFAPICRCPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    PoolNode* current = pool->head;
    while (current) {
        PoolNode* next = current->next;
        free(current);
        current = next;
    }
    pool->head = NULL;
    pool->tail = NULL;
    pool->current_size = 0;
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    pthread_key_delete(pool->thread_local_data);
    free(pool);
}

void add_to_pool(NFAPICRCPool* pool) {
    if (!pool) return;

    PoolNode* node = malloc(sizeof(PoolNode));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for new pool node\n");
        return;
    }

    node->data.rx_ue_information_tag = rand(); // Randomly set
    node->data.rnti = rand() & 0xFFFF;         // Randomly set RNTI
    node->data.crc_flag = rand() % 2;          // Randomly set CRCFLAG (0 or 1)
    node->data.timestamp = time(NULL);         // Current timestamp

    pthread_mutex_lock(&pool->lock);
    if (!pool->head) {
        pool->head = node;
        pool->tail = node;
    } else {
        pool->tail->next = node;
        pool->tail = node;
    }
    pool->current_size++;
    pthread_mutex_unlock(&pool->lock);
}

bool remove_from_pool(NFAPICRCPool* pool) {
    if (!pool || !pool->head) return false;

    pthread_mutex_lock(&pool->lock);
    PoolNode* temp = pool->head;
    pool->head = pool->head->next;

    if (!pool->head) {
        pool->tail = NULL;
    }

    free(temp);
    pool->current_size--;
    pthread_mutex_unlock(&pool->lock);

    return true;
}

void adjust_pool_size(NFAPICRCPool* pool, size_t new_size) {
    if (!pool) return;

    while (pool->current_size > new_size && remove_from_pool(pool)) {}

    for (size_t i = 0; i < new_size - pool->current_size; ++i) {
        add_to_pool(pool);
    }
}

void* thread_safe_access(void* arg) {
    NFAPICRCPool* pool = (NFAPICRCPool*)arg;

    pthread_mutex_lock(&pool->lock);
    if (!pool->head) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // No data available
    }

    PoolNode* node = pool->head;
    pool->head = pool->head->next;

    if (!pool->head) {
        pool->tail = NULL;
    }

    pthread_mutex_unlock(&pool->lock);

    NFAPI_CRC_INDICATION_PDU_T data = node->data;
    free(node);

    // Use thread-local storage for any temporary operations
    void* tls_data = pthread_getspecific(pool->thread_local_data);
    if (!tls_data) {
        tls_data = malloc(128);  // Example size
        pthread_setspecific(pool->thread_local_data, tls_data);
    }

    // Simulate processing data...
    printf("Processing data with timestamp: %ld\n", data.timestamp);

    return NULL;
}

int main() {
    NFAPICRCPool* pool = create_pool(INITIAL_POOL_SIZE);
    if (!pool) {
        fprintf(stderr, "Failed to create pool\n");
        return EXIT_FAILURE;
    }

    // Simulate concurrent access
    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        pthread_create(&threads[i], NULL, thread_safe_access, pool);
    }
    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_pool(pool);

    return EXIT_SUCCESS;
}
```

