// Define the structure for CRC indication PDU
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list management structure
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread safety
} CRCList;

// Function prototypes
CRCList* create_crc_list();
void free_crc_list(CRCList* list);
int add_pdu_to_list(CRCList* list, int rx_ue_info_tag, int rnti);
Node* find_node_by_tags(Node* head, int rx_ue_info_tag, int rnti);
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu);

// Create a new CRC list
CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free the entire CRC list
void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the CRC list
int add_pdu_to_list(CRCList* list, int rx_ue_info_tag, int rnti) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    // Check for existing node with same tags
    Node* existing_node = find_node_by_tags(list->head, rx_ue_info_tag, rnti);
    if (existing_node) {
        // Update CRCFLAG in the existing node
        set_random_crcflag(&(existing_node->data));
        pthread_mutex_unlock(&list->lock);
        return 0;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {rx_ue_info_tag, rnti, 0x01, 0}; // Example tag value
    set_random_crcflag(&pdu);

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Find node by RX_UE_INFORMATION_TAG and RNTI
Node* find_node_by_tags(Node* head, int rx_ue_info_tag, int rnti) {
    Node* current = head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == rx_ue_info_tag &&
            current->data.RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Set a random value for CRCFLAG
void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        pdu->CRCFLAG = rand() % 2; // Randomly 0 or 1
    }
}
