    } else if (strcmp(cipher_mode, "CFB") == 0) {
        cipher = EVP_des_cfb64(); // Assuming DES CFB mode
        if (key_len != 8 && key_len != 16 && key_len != 24) goto error; 
        unsigned char iv[EVP_MAX_IV_LENGTH];
        if (!RAND_bytes(iv, sizeof(iv))) goto error;
        EVP_CIPHER_CTX_set_padding(ctx, 0);
        if (1 != EVP_CipherInit_ex(ctx, cipher, NULL, key, iv, 1)) goto error;
    } else {
        fprintf(stderr, "Unsupported cipher mode.\n");
        return NULL; // Null encryption
    }

    if (!EVP_CIPHER_CTX_set_key_length(ctx, key_len) || !EVP_CIPHER_CTX_set_num_rounds(ctx, rounds)) {
        fprintf(stderr, "Failed to set key length or number of rounds.\n");
        goto error;
    }

    if (strcmp(cipher_mode, "CFB") != 0 && 1 != EVP_CipherInit_ex(ctx, cipher, NULL, key, NULL, 1)) {
        goto error; // For non-CFB modes
    }

    EVP_CIPHER_CTX_free(ctx);
    return cipher;

error:
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    fprintf(stderr, "Error occurred while initializing cipher.\n");
    return NULL;
}

void populateNFAPIList(NFAPI_CRC_INDICATION_PDU_T *list, size_t count) {
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count && i < MAX_NFAPI_ENTRIES; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 256;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2 == 0);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T nfa_list[MAX_NFAPI_ENTRIES];
    unsigned char key[24]; // Maximum for Triple DES
    if (!RAND_bytes(key, sizeof(key))) {
        fprintf(stderr, "Failed to generate random key.\n");
        return 1;
    }

    size_t num_entries = MAX_NFAPI_ENTRIES;
    populateNFAPIList(nfa_list, num_entries);

    EVP_CIPHER *cipher = generateNfareEncryptor("DES-EDE3", key, sizeof(key), 16);
    if (!cipher) {
        fprintf(stderr, "Failed to create cipher.\n");
        return 1;
    }

    // Use the cipher and NFAPI list as needed...

    EVP_CIPHER_free(cipher);
    return 0;
}
