#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev; // For backward traversal
} Node;

// Linked list management structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    size_t allocation_count;
    size_t deallocation_count;
} CRCList;

// Function prototypes
CRCList* create_list();
Node* allocate_node(NFAPI_CRC_INDICATION_PDU_T data);
void insert_node(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data);
void remove_node(CRCList* list, Node* node);
NFAPI_CRC_INDICATION_PDU_T get_next(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* current);
NFAPI_CRC_INDICATION_PDU_T get_previous(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* current);
void destroy_list(CRCList* list);

// Function implementations
CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->allocation_count = 0;
    list->deallocation_count = 0;
    return list;
}

Node* allocate_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = node->prev = NULL;
    pthread_mutex_lock(&global_list.lock);
    global_list.allocation_count++;
    pthread_mutex_unlock(&global_list.lock);
    return node;
}

void insert_node(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = allocate_node(data);
    if (!node) return;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(CRCList* list, Node* node) {
    if (!node) return;

    pthread_mutex_lock(&list->lock);

    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;

    if (list->head == node) list->head = node->next;
    if (list->tail == node) list->tail = node->prev;

    free(node);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_lock(&global_list.lock);
    global_list.deallocation_count++;
    pthread_mutex_unlock(&global_list.lock);
}

NFAPI_CRC_INDICATION_PDU_T get_next(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* current) {
    Node* node = find_node_by_data(list, *current);
    if (node && node->next) return node->next->data;
    return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return an empty structure
}

NFAPI_CRC_INDICATION_PDU_T get_previous(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* current) {
    Node* node = find_node_by_data(list, *current);
    if (node && node->prev) return node->prev->data;
    return (NFAPI_CRC_INDICATION_PDU_T){0}; // Return an empty structure
}

void destroy_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Find node by data
Node* find_node_by_data(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        if (current->data.RX_UE_INFORMATION_TAG == data.RX_UE_INFORMATION_TAG &&
            current->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Global list for performance monitoring
CRCList global_list;

int main() {
    // Initialize the global list
    CRCList* my_list = create_list();

    if (!my_list) {
        fprintf(stderr, "Failed to initialize the list.\n");
        return 1;
    }

    // Example usage: Insert some data
    NFAPI_CRC_INDICATION_PDU_T sample_data = {12345, 6789, {.CRCFLAG = 0}};
    insert_node(my_list, sample_data);

    // Retrieve next node (in this case, there is no next)
    NFAPI_CRC_INDICATION_PDU_T next_data = get_next(my_list, &sample_data);
    printf("Next data CRCFLAG: %d\n", next_data.CRC_INDICATION_REL8_TAG.CRCFLAG);

    // Clean up
    destroy_list(my_list);

    return 0;
}
