// Initialize and configure the network interface
void initialize_network_interface() {
    int sockfd, newsockfd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;

    // Create a TCP socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        exit(1);
    }

    // Initialize server address structure
    bzero((char *) &serv_addr, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(PORT);

    // Bind the socket to the local address
    if (bind(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR on binding");
        close(sockfd);
        exit(1);
    }

    // Listen for incoming connections
    listen(sockfd, MAX_CONNECTIONS);

    clilen = sizeof(cli_addr);
    while (1) {
        newsockfd = accept(sockfd, (struct sockaddr *) &cli_addr, &clilen);
        if (newsockfd < 0) {
            perror("ERROR on accept");
            continue;
        }

        // Allocate and initialize a connection structure
        pthread_mutex_lock(&lock);
        int conn_index = num_connections++;
        connections[conn_index].conn_id = conn_index;
        inet_ntop(AF_INET, &cli_addr.sin_addr, connections[conn_index].remote_ip, INET_ADDRSTRLEN);
        connections[conn_index].remote_port = ntohs(cli_addr.sin_port);
        inet_ntop(AF_INET, &(serv_addr.sin_addr), connections[conn_index].local_ip, INET_ADDRSTRLEN);
        connections[conn_index].local_port = ntohs(serv_addr.sin_port);

        pthread_mutex_unlock(&lock);

        // Log the new connection
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "New connection %d from %s:%d", conn_index,
                 connections[conn_index].remote_ip, connections[conn_index].remote_port);
        log_event(log_message);

        // Create a thread to handle the new connection asynchronously
        pthread_t thread_id;
        if (pthread_create(&thread_id, NULL, handle_connection, &connections[conn_index]) != 0) {
            perror("Failed to create thread");
        }
    }

    close(sockfd);
}

// Function to handle each TCP connection
