        snprintf(log_message, sizeof(log_message), "Data received on connection %d", conn->conn_id);
        log_event(log_message);

        // Echo the data back to the client (for demonstration purposes)
        write(conn->socket_fd, conn->buffer, n);
    }

    if (n < 0) {
        perror("ERROR reading from socket");
    }

    // Log connection closure
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "Connection %d closed", conn->conn_id);
    log_event(log_message);

    close(conn->socket_fd);
    pthread_exit(NULL);
