    if (!net_if) return NULL;

    memset(net_if->connections, 0, sizeof(net_if->connections));
    pthread_mutex_init(&net_if->lock, NULL);

    log_event("Initialized network interface");
    return net_if;
}

int add_connection(NetworkInterface *net_if, int connection_id, 
                   struct sockaddr_in local_addr, struct sockaddr_in remote_addr) {
    if (!net_if || connection_id < 0 || connection_id >= MAX_CONNECTIONS)
        return -1;

    pthread_mutex_lock(&net_if->lock);

    Connection *conn = (Connection*)malloc(sizeof(Connection));
    if (!conn) {
        pthread_mutex_unlock(&net_if->lock);
        return -2;
    }

    conn->connection_id = connection_id;
    memcpy(&conn->local_addr, &local_addr, sizeof(struct sockaddr_in));
    memcpy(&conn->remote_addr, &remote_addr, sizeof(struct sockaddr_in));

    memset(conn->buffer, 0, BUFFER_SIZE);

    net_if->connections[connection_id] = conn;

    pthread_mutex_unlock(&net_if->lock);
    log_event("Added new connection");
    return 0;
