    pthread_mutex_lock(&net_if->lock);

    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection *conn = net_if->connections[i];
        if (conn) {
            free(conn);
            net_if->connections[i] = NULL;
        }
    }

    pthread_mutex_unlock(&net_if->lock);
    pthread_mutex_destroy(&net_if->lock);

    free(net_if);
