#include <pthread.h>
#include <string.h>
#include <stdint.h>

// Define types for structures
typedef struct {
    uint32_t RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfoTag;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node and List structure for managing elements
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} CRCLIST;

CRCLIST* crclist_init() {
    CRCLIST* list = malloc(sizeof(CRCLIST));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int crclist_add(CRCLIST* list, RX_UE_INFORMATION_TAG ueInfoTag) {
    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI
    Node* current = list->head;
    while (current) {
        if (current->data.ueInfoTag.RNTI == ueInfoTag.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate found
        }
        current = current->next;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }

    newNode->data.ueInfoTag = ueInfoTag;
    newNode->data.crcIndicationRel8Tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully added
}

int crclist_remove(CRCLIST* list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current && current->data.ueInfoTag.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Not found
    }

    if (prev == NULL) { 
        list->head = current->next; 
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully removed
}

int crclist_update_crcflag(CRCLIST* list, uint32_t rnti, int crcFlag) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current && current->data.ueInfoTag.RNTI != rnti) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return 0; // Not found
    }

    current->data.crcIndicationRel8Tag.CRCFLAG = crcFlag;

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully updated
}

size_t crclist_size(const CRCLIST* list) {
    size_t size;
    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    size = list->size;
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);
    return size;
}

void crclist_destroy(CRCLIST* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *nextNode;
    while (current) {
        nextNode = current->next;
        free(current);
        current = nextNode;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    CRCLIST* list = crclist_init();

    RX_UE_INFORMATION_TAG ueInfoTag1 = {.RNTI = 1234};
    RX_UE_INFORMATION_TAG ueInfoTag2 = {.RNTI = 5678};

    crclist_add(list, ueInfoTag1);
    crclist_add(list, ueInfoTag2);

    printf("List size: %zu\n", crclist_size(list));

    crclist_update_crcflag(list, 1234, 1);
    crclist_remove(list, 5678);

    printf("Updated List size: %zu\n", crclist_size(list));

    crclist_destroy(list);
    return 0;
}
