        ssize_t bytes_received = recv(conn->thread_id, buffer, BUFFER_SIZE, 0);

        if (bytes_received > 0) {
            // Process data here
        } else {
            break; // Connection closed or error
        }
    }

    close(conn->thread_id);
    return NULL;
}

void setup_connection(int socket_fd, const char *local_ip, uint16_t local_port,
                      const char *remote_ip, uint16_t remote_port) {
