### Python Code: File Processing Utility

```python
import os
import hashlib
import sqlite3
from concurrent.futures import ThreadPoolExecutor
import requests

DB_NAME = 'file_hashes.db'
CHUNK_SIZE = 8192
API_URL = "https://api.example.com/log_error"

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()

    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(CHUNK_SIZE), b""):
            hash_md5.update(chunk)

    return hash_md5.hexdigest()

def store_hash_in_db(file_name, md5_hash):
    conn = sqlite3.connect(DB_NAME)
    cursor = conn.cursor()

    cursor.execute('''CREATE TABLE IF NOT EXISTS file_hashes
                      (filename TEXT PRIMARY KEY, hash TEXT)''')

    try:
        cursor.execute("INSERT INTO file_hashes (filename, hash) VALUES (?, ?)",
                       (file_name, md5_hash))
        conn.commit()
    except sqlite3.IntegrityError as e:
        print(f"Duplicate entry for {file_name}: {e}")
    finally:
        conn.close()

def log_error(message):
    try:
        response = requests.post(API_URL, json={"error": message})
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Failed to log error: {e}")

def process_file(file_path):
    try:
        md5_hash = calculate_md5(file_path)
        store_hash_in_db(os.path.basename(file_path), md5_hash)
    except Exception as e:
        log_error(str(e))

def process_directory(directory_path):
    with ThreadPoolExecutor() as executor:
        for root, _, files in os.walk(directory_path):
            for file in files:
                executor.submit(process_file, os.path.join(root, file))

if __name__ == "__main__":
    directory_to_process = "/path/to/directory"
    process_directory(directory_to_process)
```

