#define MAX_RADIOS 10

typedef struct {
    int id;
    int frequency; // in MHz
    int powerLevel; // in dBm
} RadioInterface;

typedef struct {
    float temperature; // in Celsius
    float interferenceLevel; // arbitrary unit
} EnvironmentalData;

bool frequenciesOverlap(int freq1, int freq2) {
    return (freq1 >= freq2 - 10 && freq1 <= freq2 + 10);
}

int calculatePowerAdjustment(float temperature, float interference) {
    int adjustment = 0;

    if (temperature > 30) {
        adjustment += 5; // Increase power by 5 dBm for high temperatures
    } else if (temperature < 0) {
        adjustment -= 5; // Decrease power by 5 dBm for low temperatures
    }

    if (interference > 50) { 
        adjustment += 10; // Increase power by 10 dBm for high interference
    } else if (interference < 20) {
        adjustment -= 5; // Decrease power by 5 dBm for low interference
    }

    return adjustment;
}

bool validateConfiguration(RadioInterface radios[], int numRadios, EnvironmentalData envData) {
    for (int i = 0; i < numRadios; ++i) {
        if (radios[i].powerLevel > 30 || radios[i].powerLevel < -50) { // Safety standards
            return false;
        }

        for (int j = i + 1; j < numRadios; ++j) {
            if (frequenciesOverlap(radios[i].frequency, radios[j].frequency)) {
                return false;
            }
        }
    }

    return true;
}

void adjustPowerLevels(RadioInterface radios[], int numRadios, EnvironmentalData envData) {
    int powerAdjustment = calculatePowerAdjustment(envData.temperature, envData.interferenceLevel);

    for (int i = 0; i < numRadios; ++i) {
        radios[i].powerLevel += powerAdjustment;

        // Ensure adjusted power levels remain within operational safety standards
        if (radios[i].powerLevel > 30) {
            radios[i].powerLevel = 30;
        } else if (radios[i].powerLevel < -50) {
            radios[i].powerLevel = -50;
        }
    }
}

void configureRadios(RadioInterface radios[], int numRadios, EnvironmentalData envData) {
    if (!validateConfiguration(radios, numRadios, envData)) {
        printf("Invalid initial configuration.\n");
        return;
    }

    adjustPowerLevels(radios, numRadios, envData);

    for (int i = 0; i < numRadios; ++i) {
        printf("Radio %d: Frequency = %d MHz, Power Level = %d dBm\n", radios[i].id, radios[i].frequency, radios[i].powerLevel);
    }
}

int main() {
    RadioInterface radios[MAX_RADIOS] = {
        {1, 2400, 20}, // Example radio configurations
        {2, 2410, 15},
        {3, 2420, 10}
    };

    int numRadios = 3;
