pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array structure
typedef struct {
    MacEntity *entities;
    size_t size;
    size_t capacity;
} DynamicArray;

// Function to initialize the dynamic array
void init_dynamic_array(DynamicArray *array, size_t initial_capacity) {
    pthread_mutex_lock(&mutex);
    array->capacity = initial_capacity;
    array->size = 0;
    array->entities = malloc(array->capacity * sizeof(MacEntity));
    if (!array->entities) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_unlock(&mutex);
}

// Function to resize the dynamic array
void resize_dynamic_array(DynamicArray *array) {
    size_t new_capacity = array->capacity * 2;
    MacEntity *new_entities = realloc(array->entities, new_capacity * sizeof(MacEntity));
    if (!new_entities) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&mutex);
    array->entities = new_entities;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&mutex);
}

// Function to add a MAC entity
int add_mac_entity(DynamicArray *array, const char *meid) {
    pthread_mutex_lock(&mutex);

    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }

    strncpy(array->entities[array->size].meid, meid, sizeof(array->entities[array->size].meid));
    array->entities[array->size].sequence_number = array->size + 1;
    array->size++;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

// Function to free the dynamic array
void free_dynamic_array(DynamicArray *array) {
    pthread_mutex_lock(&mutex);
    free(array->entities);
    pthread_mutex_unlock(&mutex);
