    dyn_arr->size = 0;
    dyn_arr->capacity = 10; // Initial capacity
    dyn_arr->array = (LTE_DL_FRAME_MSG **)malloc(dyn_arr->capacity * sizeof(LTE_DL_FRAME_MSG *));
    if (!dyn_arr->array) return -1;

    pthread_mutex_init(&dyn_arr->lock, NULL);
    return 0;
}

// Resize the dynamic array.
int resize_dynamic_array(DynamicArray *dyn_arr) {
    size_t new_capacity = dyn_arr->capacity * 2;
    LTE_DL_FRAME_MSG **new_array = (LTE_DL_FRAME_MSG **)realloc(dyn_arr->array, new_capacity * sizeof(LTE_DL_FRAME_MSG *));
    if (!new_array) return -1;

    dyn_arr->array = new_array;
    dyn_arr->capacity = new_capacity;
    return 0;
}

// Add an element to the dynamic array.
int add_element(DynamicArray *dyn_arr, LTE_DL_FRAME_MSG *element) {
    pthread_mutex_lock(&dyn_arr->lock);

    if (dyn_arr->size == dyn_arr->capacity) {
        pthread_mutex_unlock(&dyn_arr->lock);
        if (resize_dynamic_array(dyn_arr) != 0) return -1;
        pthread_mutex_lock(&dyn_arr->lock);
    }

    dyn_arr->array[dyn_arr->size++] = element;

    pthread_mutex_unlock(&dyn_arr->lock);
    return 0;
}

// Remove an element from the dynamic array by index.
int remove_element(DynamicArray *dyn_arr, size_t index) {
    if (index >= dyn_arr->size) return -1;

    pthread_mutex_lock(&dyn_arr->lock);

    free(dyn_arr->array[index]);
    for (size_t i = index; i < dyn_arr->size - 1; ++i) {
        dyn_arr->array[i] = dyn_arr->array[i + 1];
    }
    --dyn_arr->size;

    pthread_mutex_unlock(&dyn_arr->lock);
    return 0;
}

