        sleep(1);
    }

    return NULL;
}

// Clean up the dynamic array.
void cleanup_dynamic_array(DynamicArray *dyn_arr) {
    pthread_mutex_lock(&dyn_arr->lock);

    for (size_t i = 0; i < dyn_arr->size; ++i) {
        free(dyn_arr->array[i]);
    }
