#define MAX_MEID_LENGTH 32
#define MAX_ARRAY_SIZE 1024

typedef struct {
    char meid[MAX_MEID_LENGTH];
    int sequence_number;
} MACEntity;

typedef struct {
    MACEntity *entities;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Error handling function
void handle_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

// Secure random number generator initialization
void secure_rng_init() {
    if (!RAND_load_file("/dev/urandom", 32)) {
        handle_error("Failed to initialize RNG");
    }
}

// Initialize the dynamic array with given capacity
DynamicArray* init_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) handle_error("Memory allocation failed for DynamicArray");

    array->entities = (MACEntity *)calloc(initial_capacity, sizeof(MACEntity));
    if (!array->entities) handle_error("Memory allocation failed for MAC entities");

    array->count = 0;
    array->capacity = initial_capacity;

    pthread_mutex_init(&array->lock, NULL);

    return array;
}

// Add a new MEID to the dynamic array
int add_mac_entity(DynamicArray *array, const char *meid) {
    if (pthread_mutex_lock(&array->lock)) handle_error("Mutex lock failed");

    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }

    if (snprintf(array->entities[array->count].meid, MAX_MEID_LENGTH, "%s", meid) < 0) {
        pthread_mutex_unlock(&array->lock);
        handle_error("MEID formatting failed");
    }

    array->entities[array->count].sequence_number = array->count;
    array->count++;

    if (pthread_mutex_unlock(&array->lock)) handle_error("Mutex unlock failed");

    return 0; // Success
}

// Resize the dynamic array
void resize_dynamic_array(DynamicArray *array, size_t new_capacity) {
    MACEntity *new_entities = (MACEntity *)realloc(array->entities, new_capacity * sizeof(MACEntity));
    if (!new_entities) handle_error("Memory reallocation failed for MAC entities");

    array->capacity = new_capacity;
    array->entities = new_entities;

    // Initialize new entries
    memset(&array->entities[array->count], 0, (new_capacity - array->count) * sizeof(MACEntity));
}

// Integrate cryptographic functions using OpenSSL's EVP_add_cipher and EVP_add_digest
void integrate_cryptographic_functions() {
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    if (!EVP_add_cipher(cipher)) handle_error("Failed to add AES cipher");

    const EVP_MD *digest = EVP_sha256();
    if (!EVP_add_digest(digest)) handle_error("Failed to add SHA-256 digest");
}

// Main function demonstrating usage
int main() {
    secure_rng_init();

    DynamicArray *mac_array = init_dynamic_array(10);

    // Add some entities
    for (int i = 0; i < 15; ++i) {
        char meid[MAX_MEID_LENGTH];
        if (!RAND_bytes((unsigned char *)meid, MAX_MEID_LENGTH - 1)) handle_error("Failed to generate random MEID");
        meid[MAX_MEID_LENGTH - 1] = '\0'; // Ensure null-termination

        if (add_mac_entity(mac_array, meid) != 0 && mac_array->count >= mac_array->capacity) {
            resize_dynamic_array(mac_array, mac_array->capacity * 2);
            add_mac_entity(mac_array, meid); // Retry addition
        }
    }

    integrate_cryptographic_functions();

    for (size_t i = 0; i < mac_array->count; ++i) {
        printf("MEID: %s, SeqNo: %d\n", mac_array->entities[i].meid, mac_array->entities[i].sequence_number);
    }

    free(mac_array->entities);
    pthread_mutex_destroy(&mac_array->lock);
    free(mac_array);

    return 0;
}
```

### Key Points:
- **Thread Safety**: The dynamic array operations are protected by a mutex to ensure thread safety.
- **Error Handling**: Comprehensive error handling for memory allocation and cryptographic function integration.
- **Dynamic Resizing**: Supports dynamic resizing of the MAC entity array when capacity is exceeded.
- **Secure Randomization**: Uses OpenSSL's RNG to generate unique MEIDs.
- **OpenSSL Integration**: Demonstrates adding AES and SHA256 algorithms using `EVP_add_cipher` and `EVP_add_digest`.
- **Resource Management**: Ensures proper cleanup of allocated resources. 

This implementation ensures efficient management of MAC entities with consideration for concurrency, error handling, and cryptographic integration.']

