    char ip_address[16];
    int port;
    ConnectionStatus status;
    time_t last_checked;
} NetworkConnection;

typedef struct Node {
    NetworkConnection connection;
    struct Node *next;
} Node;

typedef struct {
    Node *head[MAX_CONNECTIONS];
    pthread_mutex_t lock;
    int interval_seconds;
} ConnectionManager;

// Hash function to map IP address and port to an index
unsigned int hash_connection(const NetworkConnection *conn) {
    return (hashlib_fnv1a_32((const unsigned char *) conn->ip_address, 15) ^ conn->port) % MAX_CONNECTIONS;
}

void init_manager(ConnectionManager *manager, int interval_seconds) {
    memset(manager->head, 0, sizeof(Node*) * MAX_CONNECTIONS);
    pthread_mutex_init(&manager->lock, NULL);
    manager->interval_seconds = interval_seconds;
}

void destroy_manager(ConnectionManager *manager) {
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        Node *node = manager->head[i];
        while (node != NULL) {
            Node *temp = node;
            node = node->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&manager->lock);
}

void add_connection(ConnectionManager *manager, const NetworkConnection *conn) {
    unsigned int index = hash_connection(conn);
    pthread_mutex_lock(&manager->lock);

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new connection");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    memcpy(&new_node->connection, conn, sizeof(NetworkConnection));
    new_node->next = manager->head[index];
    manager->head[index] = new_node;

    pthread_mutex_unlock(&manager->lock);
}

void update_connection(ConnectionManager *manager, const NetworkConnection *conn) {
    unsigned int index = hash_connection(conn);
    pthread_mutex_lock(&manager->lock);

    Node *node = manager->head[index];
    while (node != NULL) {
        if (strcmp(node->connection.ip_address, conn->ip_address) == 0 &&
            node->connection.port == conn->port) {
            memcpy(&(node->connection), conn, sizeof(NetworkConnection));
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

NetworkConnection* get_connection(ConnectionManager *manager, const char *ip_address, int port) {
    unsigned int index = hash_connection((const NetworkConnection *) { .port = port });
    pthread_mutex_lock(&manager->lock);

    Node *node = manager->head[index];
    while (node != NULL) {
        if (strcmp(node->connection.ip_address, ip_address) == 0 &&
            node->connection.port == port) {
            pthread_mutex_unlock(&manager->lock);
            return &(node->connection);
        }
        node = node->next;
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void check_connections(ConnectionManager *manager) {
    time_t current_time;
    while (1) {
        sleep(manager->interval_seconds);

        for (int i = 0; i < MAX_CONNECTIONS; ++i) {
            pthread_mutex_lock(&manager->lock);

            Node *node = manager->head[i];
            while (node != NULL) {
                time_t now;
                time(&now);
