                if (seconds_since_last_check >= manager->interval_seconds) {
                    // Simulate a connectivity check
                    int is_connected = simulate_network_check(&(node->connection));
                    node->connection.status = (is_connected) ? CONNECTED : DISCONNECTED;
                    node->connection.last_checked = now;

                    // Log status update (integration with external logging tool)
                }

                node = node->next;
            }

            pthread_mutex_unlock(&manager->lock);
        }
    }
}

int simulate_network_check(NetworkConnection *conn) {
