NFAPI_CRC_INDICATION_PDU_T* manage_crc_array(size_t n, FILE *data_source) {
    const size_t initial_capacity = 10; // Initial capacity
    NFAPI_CRC_INDICATION_PDU_T *crc_array = allocate_dynamic_array(initial_capacity);

    if (!crc_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    populate_structures(crc_array, n, data_source);

    // Resize logic
    size_t current_capacity = initial_capacity;
    while (n > current_capacity) {
        resize_dynamic_array(&crc_array, &current_capacity, current_capacity * 2);
    }

    return crc_array;
}

// Allocate memory for the dynamic array
NFAPI_CRC_INDICATION_PDU_T* allocate_dynamic_array(size_t capacity) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
    }
    return array;
}

// Populate structures with data from an external source
void populate_structures(NFAPI_CRC_INDICATION_PDU_T *array, size_t n, FILE *data_source) {
    for (size_t i = 0; i < n; ++i) {
        int RX_UE_TAG, RNTI;

        // Load or derive data from the external source
        if (fscanf(data_source, "%d %d", &RX_UE_TAG, &RNTI) != 2 || 
            !validate_tag(RX_UE_TAG) || !validate_rnti(RNTI)) {
            fprintf(stderr, "Data validation failed for index %zu.\n", i);
            continue;
        }

        array[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = RX_UE_TAG;
        array[i].CRC_INDICATION_REL8_TAG.RNTI = RNTI;

        // Randomly set CRCFLAG
        array[i].CRCFLAG = rand() % 2;
    }
}

// Validate the RX_UE_INFORMATION_TAG value
int validate_tag(int tag_value) {
    return tag_value >= 0 && tag_value <= 100000; // Example range check
}

// Validate RNTI value
int validate_rnti(int rnti_value) {
    return rnti_value > 0 && rnti_value < (1 << 16); // Example range check for a 16-bit integer
}

// Resize the dynamic array to a new capacity
void resize_dynamic_array(NFAPI_CRC_INDICATION_PDU_T **array, size_t *current_capacity, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory reallocation failed.\n");
        return;
    }
    *array = new_array;
    *current_capacity = new_capacity;
}

// Free the memory allocated for the dynamic array
void free_dynamic_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
