#define MAX_ELEMENTS 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

uint16_t generatePseudoRandomRNTI() {
    return (rand() % 0x7FFF) + 1; // Ensure RNTI is within the range [0x0001, 0x7FFF]
}

void populateNFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % (UINT16_MAX + 1);
    pdu->RNTI = generatePseudoRandomRNTI();
    memset(pdu->CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    pdu->CRCFLAG = rand() & 1; // Ensure CRCFLAG is either 0 or 1
}

int createAndSerializeNFAPDUList(NFAPI_CRC_INDICATION_PDU_T **pduList) {
    *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduList) return -1;

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        populateNFAPI_CRC_INDICATION_PDU(&(*pduList)[i]);
    }

    // Serialization logic
    FILE *file = fopen("serialized_data.bin", "wb");
    if (!file) {
        free(*pduList);
        return -1;
    }

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        fwrite(&(*pduList)[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    // No need to free here as memory is managed externally
    return 0;
}

void cleanupNFAPDUList(NFAPI_CRC_INDICATION_PDU_T *pduList) {
    if (pduList) {
        free(pduList);
    }
}
