DynamicArray* initialize_dynamic_array(size_t initial_size) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->contexts = (LTE_RRC_UECONTEXT_T *)calloc(initial_size, sizeof(LTE_RRC_UECONTEXT_T));
    if (!array->contexts) {
        free(array);
        return NULL;
    }

    array->size = initial_size;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void free_dynamic_array(DynamicArray *array) {
    if (array) {
        pthread_mutex_destroy(&array->lock);
        free(array->contexts);
        free(array);
    }
}

int load_configuration_from_file(const char *filename, DynamicArray *array) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    // Read configuration from file
    for (size_t i = 0; i < array->size; ++i) {
        fscanf(file, "%d %d %d %d %d %d",
               &array->contexts[i].ue_identity.ue_id,
               &array->contexts[i].cell_identity.cell_id,
               &array->contexts[i].phy_layer_config.bandwidth,
               &array->contexts[i].phy_layer_config.subcarrier_spacing,
               &array->contexts[i].phy_layer_config.cyclic_prefix_length);
    }

    fclose(file);
    return 0;
}

int save_configuration_to_file(const char *filename, const DynamicArray *array) {
    FILE *file = fopen(filename, "w");
    if (!file) return -1;

    // Write configuration to file
    for (size_t i = 0; i < array->size; ++i) {
        fprintf(file, "%d %d %d %d %d\n",
                array->contexts[i].ue_identity.ue_id,
                array->contexts[i].cell_identity.cell_id,
                array->contexts[i].phy_layer_config.bandwidth,
                array->contexts[i].phy_layer_config.subcarrier_spacing,
                array->contexts[i].phy_layer_config.cyclic_prefix_length);
    }

    fclose(file);
    return 0;
}

int update_context_with_unique_identity(DynamicArray *array, LTE_RRC_UECONTEXT_T *context) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->contexts[i].ue_identity.ue_id == context->ue_identity.ue_id) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Identity already exists
        }
    }

    // Find an empty slot or reallocate for more contexts
    size_t index = 0;
    while (index < array->size && array->contexts[index].ue_identity.ue_id != 0) {
        ++index;
    }

    if (index == array->size) { // Need to expand the array
        size_t new_size = array->size * 2;
        LTE_RRC_UECONTEXT_T *new_contexts = realloc(array->contexts, new_size * sizeof(LTE_RRC_UECONTEXT_T));
        if (!new_contexts) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }

        memset(new_contexts + array->size, 0, (new_size - array->size) * sizeof(LTE_RRC_UECONTEXT_T));
        array->contexts = new_contexts;
        array->size = new_size;
    }

    array->contexts[index] = *context;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

int integrate_with_nms(const DynamicArray *array) {
