#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Assuming these types are defined elsewhere as per the system specifications
typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set to true or false
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototype
NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t max_size, size_t required_count, size_t *actual_count);

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(size_t max_size, size_t required_count, size_t *actual_count) {
    if (max_size <= 0 || required_count > max_size) {
        actual_count = 0;
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        actual_count = 0;
        return NULL; // Memory allocation failure
    }

    bool rnti_set[max_size];
    for (size_t i = 0; i < max_size; ++i)
        rnti_set[i] = false;

    size_t current_index = 0;
    unsigned int last_rnti = 0xFFFFFFFF; // Initialize to an invalid value
    bool success = true;

    while (current_index < required_count) {
        if (current_index >= max_size) {
            success = false;
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T* current_pdu = &list[current_index];

        do {
            // Randomly generate RNTI
            current_pdu->RNTI = rand() % max_size;

            if (current_pdu->RNTI == last_rnti || rnti_set[current_pdu->RNTI]) {
                continue;  // Ensure no consecutive same RNTIs and uniqueness
            }
        } while (true);

        // Set other fields with valid information (placeholders)
        current_pdu->RX_UE_INFORMATION_TAG = rand();
        current_pdu->CRC_INDICATION_REL8_TAG = rand();

        // Randomly set CRCFLAG to true or false
        current_pdu->CRCFLAG = rand() % 2;

        // Mark this RNTI as used in the current allocation
        rnti_set[current_pdu->RNTI] = true;
        last_rnti = current_pdu->RNTI;

        ++current_index; // Move to next index for further processing
    }

    if (!success) {
        free(list);
        list = NULL;
    }

    *actual_count = success ? current_index : 0;
    return list;
}

// Example usage
int main() {
    size_t actual_count = 0;
    size_t max_size = 10;
    size_t required_count = 5;

    NFAPI_CRC_INDICATION_PDU_T* nfa_list = create_nfa_list(max_size, required_count, &actual_count);

    if (nfa_list) {
        printf("Successfully created list of %zu NFAs.\n", actual_count);

        for (size_t i = 0; i < actual_count; ++i) {
            printf("NFA[%zu]: RNTI=%u, CRCFLAG=%d\n", i, nfa_list[i].RNTI, nfa_list[i].CRCFLAG);
        }

        free(nfa_list); // Don't forget to free the allocated memory
    } else {
        printf("Failed to create NFA list.\n");
    }

    return 0;
}
