void destroy_dynamic_array(DynamicArray *array);

DynamicArray* create_dynamic_array() {
    DynamicArray *arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) {
        fprintf(stderr, "Memory allocation error for array structure\n");
        return NULL;
    }

    arr->capacity = 1; // Initial capacity
    arr->current_size = 0;

    arr->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        fprintf(stderr, "Memory allocation error for array data\n");
