        return NULL;
    }

    return arr;
}

int resize_array(DynamicArray *array, size_t new_capacity) {
    if (new_capacity > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Requested capacity exceeds maximum limit\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
