#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI; // Range: 0x0001 to 0x7FFF
    uint8_t CRC_INDICATION_REL8_TAG;
