} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int validate_rnti(unsigned short rnti) {
    return rnti >= 0x0001 && rnti <= 0x7FFF;
}

int insert_pdu(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_rnti(pdu.RNTI)) return -1;

    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu(List* list, size_t index) {
    if (index >= list->size) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (current) {
        pdu = &current->data;
    }

    pthread_mutex_unlock(&list->lock);
    return pdu;
}

int serialize_list(const List* list, uint8_t** buffer, size_t* length) {
    *buffer = (uint8_t*)malloc(list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*buffer)) return -1;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < list->size && current != NULL; ++i) {
        memcpy((*buffer) + i * sizeof(NFAPI_CRC_INDICATION_PDU_T), &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        current = current->next;
    }

    *length = list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example usage
int main() {
    List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 0x1234, 2, rand()};
    if (insert_pdu(list, pdu) != 0) {
        fprintf(stderr, "Failed to insert PDU\n");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    uint8_t* buffer = NULL;
    size_t length = 0;
    if (serialize_list(list, &buffer, &length) == 0) {
        printf("Serialized list with %zu bytes.\n", length);
        free(buffer);
    } else {
        fprintf(stderr, "Failed to serialize list\n");
    }

    destroy_list(list);
    return EXIT_SUCCESS;
}
