    struct FrameNode *next;
} FrameNode;

typedef struct {
    FrameNode *head;
    pthread_mutex_t lock;
    size_t count;
} FrameBufferManager;

FrameBufferManager* create_frame_buffer_manager() {
    FrameBufferManager *manager = (FrameBufferManager*)malloc(sizeof(FrameBufferManager));
    if (!manager) return NULL;

    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    return manager;
}

void destroy_frame_buffer_manager(FrameBufferManager *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    FrameNode *current = manager->head;
    while (current != NULL) {
        FrameNode *temp = current;
        current = current->next;
        free(temp->frame.payload);
        free(temp);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_frame(FrameBufferManager *manager, long timestamp, int packet_id, void *payload, size_t payload_size) {
    if (!manager || !payload) return -1;

    pthread_mutex_lock(&manager->lock);

    FrameNode **current = &(manager->head);
    while (*current != NULL) {
        FrameNode *node = *current;
        if (node->frame.packet_id == packet_id) {
            free(node->frame.payload);
            node->frame.timestamp = timestamp;
            node->frame.payload_size = payload_size;
            node->frame.payload = malloc(payload_size);
            if (!node->frame.payload) {
                pthread_mutex_unlock(&manager->lock);
                return -1; // Memory allocation failure
            }
            memcpy(node->frame.payload, payload, payload_size);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        current = &node->next;
    }

    FrameNode *new_node = (FrameNode*)malloc(sizeof(FrameNode));
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }

    new_node->frame.timestamp = timestamp;
    new_node->frame.packet_id = packet_id;
    new_node->frame.payload_size = payload_size;
    new_node->frame.payload = malloc(payload_size);

    if (!new_node->frame.payload) {
        free(new_node);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }

    memcpy(new_node->frame.payload, payload, payload_size);
    new_node->next = NULL;
    *current = new_node;

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

FrameBuffer* get_frame_by_timestamp(FrameBufferManager *manager, long timestamp) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    FrameNode *current = manager->head;
    while (current != NULL) {
        if (current->frame.timestamp == timestamp) {
            FrameBuffer *result = malloc(sizeof(FrameBuffer));
            if (!result) {
                pthread_mutex_unlock(&manager->lock);
                return NULL; // Memory allocation failure
            }
            *result = current->frame;
            result->payload = malloc(result->payload_size);
