    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

// Linked List structure with mutex for thread safety
typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Function prototypes
LinkedList* create_list();
void free_list(LinkedList* list);
int add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T generate_random_pdu();
int is_rnti_unique(LinkedList* list, uint16_t rnti);

// Create a new linked list with initialized mutex
LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free the entire linked list and destroy mutex
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new PDU to the linked list
int add_pdu(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.rnti)) {
        fprintf(stderr, "Error: Duplicate RNTI detected.\n");
        free_list(list);
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free_list(list);
        return -1;
    }

    new_node->pdu = pdu;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Generate a random PDU
NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_information_tag.rx_ue_information_tag.tag_rel8.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    do {
        pdu.rnti = (uint16_t)(rand() % MAX_RNTI);
    } while (!is_rnti_unique(NULL, pdu.rnti)); // Ensure RNTI is unique

    return pdu;
}

// Check if an RNTI is unique in the list
int is_rnti_unique(LinkedList* list, uint16_t rnti) {
    Node* current = list ? list->head : NULL;
    while (current) {
        if (current->pdu.rnti == rnti)
            return 0; // RNTI is not unique
        current = current->next;
    }
    return 1; // RNTI is unique
}

// Function to initialize and populate the list
LinkedList* init_nfaapi_crc_indication_list(int N) {
    if (N <= 0) return create_list();

    LinkedList* list = create_list();
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for linked list.\n");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        if (add_pdu(list, pdu) != 0) { // Handle error in adding PDU
            fprintf(stderr, "Error: Failed to add PDU. Memory might be exhausted.\n");
            free_list(list);
            return NULL;
        }
    }

    return list;
}

int main() {
