    LinkedList* nfaapi_list = init_nfaapi_crc_indication_list(N);

    if (nfaapi_list) {
        printf("List initialized with %d elements.\n", N);
        free_list(nfaapi_list);
    } else {
        fprintf(stderr, "Failed to initialize list.\n");
    }

    return 0;
}
