```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SIZE 1000 // Maximum size of the frame buffer

typedef struct {
    time_t timestamp;
    int packet_id;
    void *payload;
    size_t payload_size;
} FrameBuffer;

typedef struct {
    FrameBuffer *frames;
    int count;
    int max_size;
    int discarded_count;
    pthread_mutex_t mutex;
} FrameBufferManager;

int add_frame(FrameBufferManager *manager, time_t timestamp, int packet_id, void *payload, size_t payload_size) {
    pthread_mutex_lock(&manager->mutex);

    // Discard oldest entry if at maximum capacity
    if (manager->count >= manager->max_size) {
        free(manager->frames[0].payload);
        memmove(&manager->frames[0], &manager->frames[1], sizeof(FrameBuffer) * (manager->count - 1));
        manager->count--;
        manager->discarded_count++;
    }

    // Add or update the frame
    for (int i = 0; i < manager->count; i++) {
        if (manager->frames[i].packet_id == packet_id) {
            free(manager->frames[i].payload);
            manager->frames[i].timestamp = timestamp;
            manager->frames[i].payload_size = payload_size;
            manager->frames[i].payload = malloc(payload_size);
            if (!manager->frames[i].payload) {
                pthread_mutex_unlock(&manager->mutex);
                return -1; // Error code for memory allocation failure
            }
            memcpy(manager->frames[i].payload, payload, payload_size);
            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    manager->frames[manager->count].timestamp = timestamp;
    manager->frames[manager->count].packet_id = packet_id;
    manager->frames[manager->count].payload_size = payload_size;
    manager->frames[manager->count].payload = malloc(payload_size);
    if (!manager->frames[manager->count].payload) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Error code for memory allocation failure
    }
    memcpy(manager->frames[manager->count].payload, payload, payload_size);

    manager->count++;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

FrameBuffer *get_frame_by_timestamp(FrameBufferManager *manager, time_t timestamp) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->count; i++) {
        if (manager->frames[i].timestamp == timestamp) {
            FrameBuffer *frame = &manager->frames[i];
            pthread_mutex_unlock(&manager->mutex);
            return frame;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

int init_frame_buffer_manager(FrameBufferManager *manager, int max_size) {
    manager->max_size = max_size;
    manager->count = 0;
    manager->discarded_count = 0;
    manager->frames = malloc(sizeof(FrameBuffer) * max_size);
    if (!manager->frames) {
        return -1; // Error code for memory allocation failure
    }
    pthread_mutex_init(&manager->mutex, NULL);
    return 0;
}

void destroy_frame_buffer_manager(FrameBufferManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (int i = 0; i < manager->count; i++) {
        free(manager->frames[i].payload);
    }
    free(manager->frames);
    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

// Example usage
/*
