} FrameManager;

typedef struct {
    FrameBuffer *buffers[MAX_POOL_SIZE];
    size_t used;
    pthread_mutex_t pool_lock;
} BufferPool;

FrameManager* create_frame_manager(size_t initial_capacity) {
    FrameManager *manager = (FrameManager*) malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = (FrameBuffer**) calloc(initial_capacity, sizeof(FrameBuffer*));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_frame_manager(FrameManager *manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->frames[i]->payload);
        free(manager->frames[i]);
    }
    free(manager->frames);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

bool add_frame(FrameManager *manager, FrameBuffer *frame) {
    if (!manager) return false;

    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        FrameBuffer **new_frames = (FrameBuffer**) realloc(manager->frames, new_capacity * sizeof(FrameBuffer*));
        if (!new_frames) {
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        manager->frames = new_frames;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->packet_id == frame->packet_id) {
            free(manager->frames[i]->payload);
            free(manager->frames[i]);
            manager->frames[i] = frame;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    manager->frames[manager->count++] = frame;

    pthread_mutex_unlock(&manager->lock);

    if (LOGGING_ENABLED) {
        printf("Frame added: packet_id=%d\n", frame->packet_id);
    }

    return true;
}

bool update_frame(FrameManager *manager, int packet_id, FrameBuffer *frame) {
    if (!manager || !frame) return false;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->packet_id == packet_id) {
            free(manager->frames[i]->payload);
            *manager->frames[i] = *frame;
            pthread_mutex_unlock(&manager->lock);
            return true;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return add_frame(manager, frame);
}

FrameBuffer* get_frame_by_timestamp(FrameManager *manager, uint64_t timestamp) {
    if (!manager) return NULL;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i]->timestamp == timestamp) {
            FrameBuffer* result = malloc(sizeof(FrameBuffer));
            *result = *manager->frames[i];
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return NULL;
}

FrameBuffer* allocate_frame_buffer(size_t payload_size) {
    static BufferPool buffer_pool = {0};
    static bool pool_initialized = false;

    if (!pool_initialized) {
        pthread_mutex_init(&buffer_pool.pool_lock, NULL);
        pool_initialized = true;
    }

    pthread_mutex_lock(&buffer_pool.pool_lock);

    FrameBuffer *frame = (buffer_pool.used > 0)
                        ? buffer_pool.buffers[--buffer_pool.used]
                        : malloc(sizeof(FrameBuffer));

    if (!frame) {
        pthread_mutex_unlock(&buffer_pool.pool_lock);
        return NULL;
    }

    frame->payload = malloc(payload_size);
    if (!frame->payload) {
        if (buffer_pool.used < MAX_POOL_SIZE) {
            buffer_pool.buffers[buffer_pool.used++] = frame;
        } else {
            free(frame);
        }
        pthread_mutex_unlock(&buffer_pool.pool_lock);
        return NULL;
    }

    frame->payload_size = payload_size;

    pthread_mutex_unlock(&buffer_pool.pool_lock);

    return frame;
}

void deallocate_frame_buffer(FrameBuffer *frame) {
    if (!frame) return;

    pthread_mutex_lock(&buffer_pool.pool_lock);

    free(frame->payload);

    if (buffer_pool.used < MAX_POOL_SIZE) {
        buffer_pool.buffers[buffer_pool.used++] = frame;
    } else {
        free(frame);
    }

    pthread_mutex_unlock(&buffer_pool.pool_lock);
}

// Example usage in a larger network processing pipeline
void process_network_frames() {
    FrameManager *manager = create_frame_manager(10);

    // Simulate adding frames
    FrameBuffer *frame1 = allocate_frame_buffer(100);
    frame1->timestamp = 123456789;
    frame1->packet_id = 1;
    strcpy(frame1->payload, "Example payload");

    add_frame(manager, frame1);

    // Simulate retrieving a frame by timestamp
    FrameBuffer *retrieved_frame = get_frame_by_timestamp(manager, 123456789);
    if (retrieved_frame) {
        printf("Retrieved frame: %s\n", retrieved_frame->payload);
        free(retrieved_frame->payload);
        free(retrieved_frame);
    }

    destroy_frame_manager(manager);
}
