} RequestManager;

// Function prototypes
void init_request_manager(RequestManager *manager);
void add_request(RequestManager *manager, const char *session_id, const char *user_agent);
ConnectionRequest* get_request(RequestManager *manager, const char *session_id);
void remove_request(RequestManager *manager, const char *session_id);
void cleanup_request_manager(RequestManager *manager);

// Function implementations
void init_request_manager(RequestManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void add_request(RequestManager *manager, const char *session_id, const char *user_agent) {
    if (manager->count >= MAX_REQUESTS) return;

    pthread_mutex_lock(&manager->lock);

    ConnectionRequest *req = malloc(sizeof(ConnectionRequest));
    if (!req) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    strncpy(req->session_id, session_id, sizeof(req->session_id));
    strncpy(req->user_agent, user_agent, sizeof(req->user_agent));
    req->request_timestamp = time(NULL);

    manager->requests[manager->count++] = req;

    pthread_mutex_unlock(&manager->lock);
}

ConnectionRequest* get_request(RequestManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(manager->requests[i]->session_id, session_id) == 0) {
            ConnectionRequest* req = manager->requests[i];
            pthread_mutex_unlock(&manager->lock);
            return req;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void remove_request(RequestManager *manager, const char *session_id) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(manager->requests[i]->session_id, session_id) == 0) {
            free(manager->requests[i]);
            memmove(&manager->requests[i], &manager->requests[i + 1],
                    sizeof(ConnectionRequest*) * (manager->count - i - 1));
            manager->count--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_request_manager(RequestManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < manager->count; ++i) {
        free(manager->requests[i]);
    }

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

// Main function to demonstrate usage
int main() {
    RequestManager manager;
    init_request_manager(&manager);

    add_request(&manager, "session1", "Mozilla/5.0");
    add_request(&manager, "session2", "Chrome/91.0");

    ConnectionRequest *req = get_request(&manager, "session1");
    if (req) {
        printf("Session ID: %s\n", req->session_id);
    }

    remove_request(&manager, "session1");
    cleanup_request_manager(&manager);

    return 0;
}
