#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define constants
#define MAX_PDP_CONTEXTS 10
#define INACTIVITY_THRESHOLD_SECONDS 300 // Example threshold

typedef struct {
    int s1_ue_context_id;
    int pdp_contexts[MAX_PDP_CONTEXTS];
    unsigned int active_pdp_count;
    time_t last_activity_time;
} UEContext;

// Define the dynamic collection structure
typedef struct {
    UEContext *contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} UEContextCollection;

// Function prototypes
void initialize_ue_context_collection(UEContextCollection *collection, size_t initial_capacity);
void add_or_update_ue_context(UEContextCollection *collection, int s1_ue_context_id, const int *pdp_contexts, unsigned int pdp_count);
void remove_inactive_ue_contexts(UEContextCollection *collection);
void cleanup_ue_context_collection(UEContextCollection *collection);

// Initialize the UE context collection
void initialize_ue_context_collection(UEContextCollection *collection, size_t initial_capacity) {
    pthread_mutex_init(&collection->lock, NULL);
    collection->contexts = (UEContext *)malloc(initial_capacity * sizeof(UEContext));
    collection->capacity = initial_capacity;
    collection->count = 0;
}

// Add or update a UE context
void add_or_update_ue_context(UEContextCollection *collection, int s1_ue_context_id, const int *pdp_contexts, unsigned int pdp_count) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->contexts[i].s1_ue_context_id == s1_ue_context_id) {
            // Update existing context
            memcpy(collection->contexts[i].pdp_contexts, pdp_contexts, pdp_count * sizeof(int));
            collection->contexts[i].active_pdp_count = pdp_count;
            collection->contexts[i].last_activity_time = time(NULL);
            break;
        }
    }

    // If not found, add new context
    if (collection->count == i) {
        if (collection->count >= collection->capacity) {
            size_t new_capacity = collection->capacity * 2;
            UEContext *new_contexts = (UEContext *)realloc(collection->contexts, new_capacity * sizeof(UEContext));
            if (new_contexts) {
                collection->contexts = new_contexts;
                collection->capacity = new_capacity;
            } else {
                // Handle memory allocation failure
                printf("Failed to allocate memory for UE contexts.\n");
                pthread_mutex_unlock(&collection->lock);
                return;
            }
        }

        UEContext *new_context = &collection->contexts[collection->count++];
        new_context->s1_ue_context_id = s1_ue_context_id;
        memcpy(new_context->pdp_contexts, pdp_contexts, pdp_count * sizeof(int));
        new_context->active_pdp_count = pdp_count;
        new_context->last_activity_time = time(NULL);
    }

    pthread_mutex_unlock(&collection->lock);
}

// Remove inactive UE contexts
void remove_inactive_ue_contexts(UEContextCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    time_t current_time = time(NULL);
    size_t write_index = 0;

    for (size_t i = 0; i < collection->count; ++i) {
        if (difftime(current_time, collection->contexts[i].last_activity_time) <= INACTIVITY_THRESHOLD_SECONDS) {
            collection->contexts[write_index++] = collection->contexts[i];
        }
    }

    collection->count = write_index;
    pthread_mutex_unlock(&collection->lock);
}

// Cleanup the UE context collection
void cleanup_ue_context_collection(UEContextCollection *collection) {
    pthread_mutex_lock(&collection->lock);

    free(collection->contexts);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}
```

### Key Considerations:

1. **Thread Safety**: The use of `pthread_mutex_t` ensures that the collection is accessed in a thread-safe manner, preventing race conditions.

2. **Dynamic Resizing**: The collection can grow dynamically as new contexts are added, using `realloc` to adjust capacity when needed.

3. **Inactivity Management**: Contexts are periodically checked for inactivity and removed if they exceed the threshold.

4. **Graceful Degradation**: In case of memory allocation failure, the function handles it gracefully by printing an error message and exiting early.

5. **Scalability**: The design supports scalability through dynamic resizing and efficient locking mechanisms.']

