#define MAX_ARRAY_SIZE 1024

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[3];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CRCArrayManager;

void initialize_crc_array(CRCArrayManager *manager, size_t initial_size) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

void cleanup_crc_array(CRCArrayManager *manager) {
    free(manager->array);
    pthread_mutex_destroy(&manager->mutex);
    pthread_cond_destroy(&manager->cond);
}

uint8_t generate_random_byte() {
    return rand() % 256;
}

int add_crc_indication_pdu(CRCArrayManager *manager, uint16_t rx_UE_info_tag, uint16_t rnti) {
    pthread_mutex_lock(&manager->mutex);

    while (manager->count >= MAX_ARRAY_SIZE) {
        // Wait for space to become available
        pthread_cond_wait(&manager->cond, &manager->mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rx_UE_info_tag;
    pdu->RNTI = rnti;
    for (int i = 0; i < 3; ++i) {
        pdu->CRC_INDICATION_REL8_TAG[i] = generate_random_byte();
    }

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->mutex);

    return 0; // Success
}

void remove_crc_indication_pdu(CRCArrayManager *manager, size_t index) {
    if (index >= manager->count) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->array[i] = manager->array[i + 1];
    }
    manager->count--;

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->mutex);
}

