['Below is a C implementation that addresses the requirements outlined in your task. The implementation includes functions for managing UE context data structures, using threading for periodic checks, and ensuring efficient memory management.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_UE_CONTEXTS 10000
#define MAX_PDP_CONTEXTS 5
#define TIMEOUT_SECONDS 30

typedef struct PdpContext {
    int id;
    time_t lastActivityTime;
} PdpContext;

typedef struct UeContext {
    int s1UeContextId;
    PdpContext pdpContexts[MAX_PDP_CONTEXTS];
    int activePdpCount;
    time_t lastActivityTime;
    pthread_mutex_t lock;
} UeContext;

typedef struct UeContextManager {
    UeContext ueContexts[MAX_UE_CONTEXTS];
    int totalUeCount;
    int activeUeCount;
    pthread_mutex_t lock;
    pthread_t cleanupThread;
    int running;
} UeContextManager;

// Function prototypes
void *cleanupInactiveContexts(void *arg);
int addOrUpdateUeContext(UeContextManager *manager, int s1UeContextId, PdpContext *pdpUpdates, int pdpCount);
int removeInactiveContexts(UeContextManager *manager, time_t timeout);
void reportContextStatistics(UeContextManager *manager);

// Initialize the UE context manager
UeContextManager* initUeContextManager() {
    UeContextManager *manager = (UeContextManager*)malloc(sizeof(UeContextManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);
    manager->totalUeCount = 0;
    manager->activeUeCount = 0;
    manager->running = 1;

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        manager->ueContexts[i].s1UeContextId = -1;
        pthread_mutex_init(&manager->ueContexts[i].lock, NULL);
    }

    if (pthread_create(&manager->cleanupThread, NULL, cleanupInactiveContexts, manager)) {
        fprintf(stderr, "Failed to create cleanup thread\n");
        return NULL;
    }

    return manager;
}

// Cleanup function for inactive contexts
void *cleanupInactiveContexts(void *arg) {
    UeContextManager *manager = (UeContextManager*)arg;

    while (manager->running) {
        sleep(TIMEOUT_SECONDS);

        pthread_mutex_lock(&manager->lock);
        removeInactiveContexts(manager, time(NULL));
        reportContextStatistics(manager);
        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

// Add or update a UE context
int addOrUpdateUeContext(UeContextManager *manager, int s1UeContextId, PdpContext *pdpUpdates, int pdpCount) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        UeContext *context = &manager->ueContexts[i];
        pthread_mutex_lock(&context->lock);

        if (context->s1UeContextId == s1UeContextId || context->s1UeContextId == -1) {
            context->s1UeContextId = s1UeContextId;
            manager->totalUeCount++;

            for (int j = 0; j < pdpCount && j < MAX_PDP_CONTEXTS; ++j) {
                context->pdpContexts[j] = pdpUpdates[j];
                if (j == context->activePdpCount) {
                    context->activePdpCount++;
                }
            }

            context->lastActivityTime = time(NULL);
            manager->activeUeCount++;

            pthread_mutex_unlock(&context->lock);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }

        pthread_mutex_unlock(&context->lock);
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Context array full or not found
}

// Remove inactive contexts based on timeout
int removeInactiveContexts(UeContextManager *manager, time_t currentTime) {
    int removedCount = 0;

    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        UeContext *context = &manager->ueContexts[i];
        pthread_mutex_lock(&context->lock);

        if (context->s1UeContextId != -1 && 
            difftime(currentTime, context->lastActivityTime) > TIMEOUT_SECONDS) {

            context->s1UeContextId = -1;
            manager->activeUeCount--;
            removedCount++;
        }

        pthread_mutex_unlock(&context->lock);
    }

    return removedCount;
}

// Report current number of active and total contexts
void reportContextStatistics(UeContextManager *manager) {
    printf("Active UE Contexts: %d, Total UE Contexts Managed: %d\n",
           manager->activeUeCount, manager->totalUeCount);
}

// Shutdown the context manager
void shutdownUeContextManager(UeContextManager *manager) {
    if (manager) {
        pthread_mutex_lock(&manager->lock);
        manager->running = 0;
        pthread_mutex_unlock(&manager->lock);

        pthread_join(manager->cleanupThread, NULL);

        for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
            pthread_mutex_destroy(&manager->ueContexts[i].lock);
        }

        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

// Example usage
int main() {
    UeContextManager *manager = initUeContextManager();

    if (manager) {
        PdpContext pdpUpdates[MAX_PDP_CONTEXTS] = {{1, time(NULL)}, {2, time(NULL)}};
        addOrUpdateUeContext(manager, 1001, pdpUpdates, 2);

        sleep(5);

        shutdownUeContextManager(manager);
    }

    return 0;
}
```

