```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONTEXTS 1000
#define INACTIVITY_TIMEOUT 300 // seconds

typedef struct {
    int s1_ue_context_id;
    char* pdp_contexts; // Comma-separated list for simplicity
    time_t last_activity_time;
} UEContext;

typedef struct Node {
    UEContext context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ContextList;

ContextList ue_context_list = {NULL, PTHREAD_MUTEX_INITIALIZER};

void initialize_context(UEContext* ctx, int s1_ue_context_id) {
    ctx->s1_ue_context_id = s1_ue_context_id;
    ctx->pdp_contexts = strdup("");
    time(&ctx->last_activity_time);
}

int add_or_update_context(int s1_ue_context_id, const char* pdp_contexts) {
    pthread_mutex_lock(&ue_context_list.lock);

    Node** current = &ue_context_list.head;
    while (*current) {
        if ((*current)->context.s1_ue_context_id == s1_ue_context_id) {
            free((*current)->context.pdp_contexts);
            (*current)->context.pdp_contexts = strdup(pdp_contexts);
            time(&(*current)->context.last_activity_time);
            pthread_mutex_unlock(&ue_context_list.lock);
            return 0; // Updated
        }
        current = &(*current)->next;
    }

    if (current) {
        Node* new_node = malloc(sizeof(Node));
        initialize_context(&new_node->context, s1_ue_context_id);
        strncpy(new_node->context.pdp_contexts, pdp_contexts, 1024); // Assuming max length
        time(&new_node->context.last_activity_time);
        new_node->next = NULL;
        *current = new_node;
    }

    pthread_mutex_unlock(&ue_context_list.lock);
    return 1; // Added
}

void remove_inactive_contexts() {
    pthread_mutex_lock(&ue_context_list.lock);

    Node **current = &ue_context_list.head, *temp;
    time_t now;
    time(&now);

    while (*current) {
        if (difftime(now, (*current)->context.last_activity_time) > INACTIVITY_TIMEOUT) {
            temp = *current;
            *current = (*current)->next;
            free(temp->context.pdp_contexts);
            free(temp);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&ue_context_list.lock);
}

void periodic_cleanup() {
    while (1) {
        remove_inactive_contexts();
        sleep(60); // Run cleanup every minute
    }
}

int main() {
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, (void*)periodic_cleanup, NULL);

    // Simulate adding/updating contexts and system operation

    pthread_join(cleanup_thread, NULL);
    return 0;
}
