typedef struct MemoryPool {
    size_t pool_size;
    char *memory;
    pthread_mutex_t lock;
    size_t allocation_count;
    size_t deallocation_count;
} MemoryPool;

MemoryPool *create_memory_pool(size_t pool_size) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->pool_size = pool_size;
    pool->memory = (char *)aligned_alloc(ALIGNMENT, pool_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pool->allocation_count = 0;
    pool->deallocation_count = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        pthread_mutex_destroy(&pool->lock);
        free(pool->memory);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T *allocate_from_pool(MemoryPool *pool, size_t count) {
    pthread_mutex_lock(&pool->lock);

    char *mem_ptr = pool->memory;
    if (pool->allocation_count + count > pool->pool_size) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    pool->allocation_count += count;
    pthread_mutex_unlock(&pool->lock);

    void *aligned_mem = memalign(ALIGNMENT, count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!aligned_mem) return NULL;

    return (NFAPI_CRC_INDICATION_PDU_T *)aligned_mem;
}

void deallocate_from_pool(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *ptr, size_t count) {
    pthread_mutex_lock(&pool->lock);
    pool->deallocation_count += count;
    free(ptr);
    pthread_mutex_unlock(&pool->lock);
}

int createAndPopulateNFapiCrcIndications(size_t N, MemoryPool *pool) {
    if (!pool || N == 0) return -1;

    NFAPI_CRC_INDICATION_PDU_T *indication_array = allocate_from_pool(pool, N);
    if (!indication_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        indication_array[i].RNTI = rand() % UINT64_MAX;
        indication_array[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;

        // Simulate concurrency with optimistic locking
        do {
            volatile uint32_t *crcflag_ptr = &indication_array[i].CRC_INDICATION.CRCFLAG;
            uint32_t old_crcflag = *crcflag_ptr;
            uint32_t new_crcflag = old_crcflag ^ (rand() % 2);
            if (__sync_bool_compare_and_swap(crcflag_ptr, old_crcflag, new_crcflag)) {
                break;
