#define MAX_MEMORY_USAGE 1024 * 100 // 100KB
#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crcIndication;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

