    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRCList;

// Function to verify checksum
int verifyChecksum(CRC_INDICATION_REL8_TAG *tag) {
    // Placeholder for checksum verification logic
    return (tag->RX_UE_INFORMATION_TAG + tag->RNTI) % 2 == 0; // Dummy check
}

CRCList* createCRCList() {
    CRCList* list = malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate memory for CRCList");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    list->data = malloc(list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("Failed to allocate memory for CRCList data");
        free(list);
        exit(EXIT_FAILURE);
    }
    return list;
}

void resizeCRCList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    size_t newCapacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newData) {
        perror("Failed to resize CRCList data");
        pthread_mutex_unlock(&list->lock);
        exit(EXIT_FAILURE);
    }
    list->capacity = newCapacity;
    list->data = newData;

    pthread_mutex_unlock(&list->lock);
}

void addCRCIndication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        resizeCRCList(list);
    }

    if (verifyChecksum(&pdu.crcIndication)) {
        list->data[list->size++] = pdu;
    } else {
        fprintf(stderr, "Data integrity check failed\n");
    }

    pthread_mutex_unlock(&list->lock);
}

void freeCRCList(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    free(list->data);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    CRCList *crcList = createCRCList();

    for (int i = 0; i < 50; ++i) { // Example workload
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.crcIndication.RX_UE_INFORMATION_TAG = rand();
        pdu.crcIndication.RNTI = rand();
        pdu.CRCFLAG = rand() % 2;

        addCRCIndication(crcList, pdu);
    }

    freeCRCList(crcList);

    return 0;
}
