#define MAX_RETRIES 5
#define INITIAL_BACKOFF_MS 100

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_TAG;
} NR_PDU_T;

typedef struct {
    int success;      // Flag to indicate data retrieval success
    NR_PDU_T* pdu_list; // Pointer to list of PDUs
    size_t count;     // Number of PDUs successfully initialized
} DataProcessingResult;

