```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define FRAME_TYPE 1 // Example frame type

typedef struct {
    uint8_t FRAME_TYPE;
    uint16_t SEQUENCE_NUMBER;
    char* PAYLOAD_DATA;
} DATA_FRAME_T;

int initializeAndProcessDataFrames(DATA_FRAME_T** frames, size_t M, unsigned int seed) {
    if (M == 0 || !frames) return -1;

    // Thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    *frames = malloc(M * sizeof(DATA_FRAME_T));
    if (*frames == NULL) return -1;

    srand(seed);

    for (size_t i = 0; i < M; ++i) {
        DATA_FRAME_T* frame = &(*frames)[i];

        // Assigning fields
        frame->FRAME_TYPE = FRAME_TYPE;
        frame->SEQUENCE_NUMBER = (uint16_t)i;

        size_t payloadSize = rand() % 256 + 1; // Example variability in payload size

        // Allocate and populate PAYLOAD_DATA
        pthread_mutex_lock(&mutex);
        frame->PAYLOAD_DATA = malloc(payloadSize * sizeof(char));
        if (frame->PAYLOAD_DATA == NULL) {
            // Cleanup on failure
            for (size_t j = 0; j < i; ++j) {
                free((*frames)[j].PAYLOAD_DATA);
            }
            free(*frames);
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Populate PAYLOAD_DATA with dummy data
        for (size_t k = 0; k < payloadSize; ++k) {
            frame->PAYLOAD_DATA[k] = rand() % 256;
        }
        pthread_mutex_unlock(&mutex);

        // Integrity verification placeholder: ensure allocated memory is valid.
        if (frame->PAYLOAD_DATA == NULL || frame->SEQUENCE_NUMBER != i) {
            for (size_t j = 0; j <= i; ++j) {
                free((*frames)[j].PAYLOAD_DATA);
            }
            free(*frames);
            return -1;
        }
    }

    // Cleanup mutex
    pthread_mutex_destroy(&mutex);

    return 0; // Success
}

// Example usage:
int main() {
    DATA_FRAME_T* frames = NULL;
    size_t M = 10;
    unsigned int seed = 42;

    if (initializeAndProcessDataFrames(&frames, M, seed) == 0) {
        for (size_t i = 0; i < M; ++i) {
            printf("Frame %zu: Type=%d, SeqNo=%u\n", i, frames[i].FRAME_TYPE, frames[i].SEQUENCE_NUMBER);
            free(frames[i].PAYLOAD_DATA); // Free payload data
        }
    } else {
        fprintf(stderr, "Failed to initialize and process data frames.\n");
    }

    free(frames); // Free frame array

    return 0;
}
```

