#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int id;
} SIB;

typedef struct {
    int ue_id;
    SIB* sibs;
    size_t num_sibs;
    int is_attached; // 0 for detached, 1 for attached
} LTE_UE_Context;

typedef struct {
    LTE_UE_Context** contexts;
    size_t capacity;
    size_t count;
} UE_Context_Manager;

// Function prototypes
UE_Context_Manager* init_ue_context_manager();
int add_ue_context(UE_Context_Manager* manager, int ue_id);
int remove_ue_context(UE_Context_Manager* manager, int ue_id);
LTE_UE_Context* get_ue_context(const UE_Context_Manager* manager, int ue_id);
int update_sib_list(UE_Context_Manager* manager, int ue_id, SIB* new_sibs, size_t num_sibs);
int check_attachment_status(const UE_Context_Manager* manager, int ue_id);
void free_ue_context_manager(UE_Context_Manager* manager);

// Helper functions
static void resize_context_array(UE_Context_Manager* manager);
static LTE_UE_Context* find_ue_context(LTE_UE_Context** contexts, size_t count, int ue_id);

// Implementations

UE_Context_Manager* init_ue_context_manager() {
    UE_Context_Manager* manager = malloc(sizeof(UE_Context_Manager));
    if (!manager) return NULL;

    manager->contexts = calloc(INITIAL_CAPACITY, sizeof(LTE_UE_Context*));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    return manager;
}

int add_ue_context(UE_Context_Manager* manager, int ue_id) {
    if (manager->count == manager->capacity) {
        resize_context_array(manager);
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            return -1; // UE ID already exists
        }
    }

    LTE_UE_Context* context = malloc(sizeof(LTE_UE_Context));
    if (!context) return -2;

    context->ue_id = ue_id;
    context->sibs = NULL;
    context->num_sibs = 0;
    context->is_attached = 0; // Default to detached

    manager->contexts[manager->count++] = context;
    return 0;
}

int remove_ue_context(UE_Context_Manager* manager, int ue_id) {
    LTE_UE_Context** contexts = manager->contexts;

    for (size_t i = 0; i < manager->count; ++i) {
        if (contexts[i]->ue_id == ue_id) {
            free(contexts[i]->sibs);
            free(contexts[i]);
            memmove(&contexts[i], &contexts[i + 1], sizeof(LTE_UE_Context*) * (manager->count - i - 1));
            --manager->count;
            return 0;
        }
    }

    return -1; // UE ID not found
}

LTE_UE_Context* get_ue_context(const UE_Context_Manager* manager, int ue_id) {
    return find_ue_context(manager->contexts, manager->count, ue_id);
}

int update_sib_list(UE_Context_Manager* manager, int ue_id, SIB* new_sibs, size_t num_sibs) {
    LTE_UE_Context* context = get_ue_context(manager, ue_id);

    if (!context) return -1;

    free(context->sibs); // Free existing SIB list

    context->sibs = malloc(num_sibs * sizeof(SIB));
    if (!context->sibs) return -2;

    memcpy(context->sibs, new_sibs, num_sibs * sizeof(SIB));
    context->num_sibs = num_sibs;
    return 0;
}

int check_attachment_status(const UE_Context_Manager* manager, int ue_id) {
    LTE_UE_Context* context = get_ue_context(manager, ue_id);
    if (!context) return -1;

    return context->is_attached;
}

void free_ue_context_manager(UE_Context_Manager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->sibs);
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    free(manager);
}

static void resize_context_array(UE_Context_Manager* manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_UE_Context** new_contexts = realloc(manager->contexts, new_capacity * sizeof(LTE_UE_Context*));
    if (!new_contexts) return;

    memset(new_contexts + manager->capacity, 0, (new_capacity - manager->capacity) * sizeof(LTE_UE_Context*));
    manager->contexts = new_contexts;
    manager->capacity = new_capacity;
}

static LTE_UE_Context* find_ue_context(LTE_UE_Context** contexts, size_t count, int ue_id) {
    for (size_t i = 0; i < count; ++i) {
        if (contexts[i]->ue_id == ue_id) {
            return contexts[i];
        }
    }

    return NULL;
}
