#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RESOURCES 1000
#define RETRY_LIMIT 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint32_t CRC_INDICATION_TAG;
} NR_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    printf("%s\n", message);
}

int calculate_crc(const NR_PDU_T *pdu) {
    unsigned int hash[2] = {0};
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, &pdu->RX_UE_INFORMATION_TAG, sizeof(pdu->RX_UE_INFORMATION_TAG));
    SHA256_Update(&sha256, &pdu->RNTI, sizeof(pdu->RNTI));
    SHA256_Final((unsigned char*)&hash, &sha256);
    return (int)hash[0] ^ (int)hash[1];
}

void* handle_request(void *arg) {
    int retries = 0;
    while (retries < RETRY_LIMIT) {
        // Simulate external data source access
        if (rand() % 2 == 0) {  // Random success or failure
            break;
        }
        sleep((1 << retries)); // Exponential backoff
        retries++;
    }

    if (retries == RETRY_LIMIT) {
        log_message("Failed to retrieve data after multiple attempts.");
        return NULL;
    }

    NR_PDU_T *resource_list = malloc(MAX_RESOURCES * sizeof(NR_PDU_T));
    if (!resource_list) {
        log_message("Memory allocation failed for resource list.");
        return NULL;
    }

    for (int i = 0; i < MAX_RESOURCES; i++) {
        pthread_mutex_lock(&mutex);
        resource_list[i].RX_UE_INFORMATION_TAG = rand();
        resource_list[i].RNTI = rand();
        resource_list[i].CRC_INDICATION_TAG = calculate_crc(&resource_list[i]);
        pthread_mutex_unlock(&mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_list = malloc(MAX_RESOURCES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list) {
        log_message("Memory allocation failed for CRC list.");
        free(resource_list);
        return NULL;
    }

    for (int i = 0; i < MAX_RESOURCES; i++) {
        pthread_mutex_lock(&mutex);
        crc_list[i].RX_UE_INFORMATION_TAG = resource_list[i].RX_UE_INFORMATION_TAG;
        crc_list[i].RNTI = resource_list[i].RNTI;
        crc_list[i].CRCFLAG = rand() & 1; // Random CRC flag
        crc_list[i].CRC_INDICATION_REL8_TAG = calculate_crc(&resource_list[i]);
        pthread_mutex_unlock(&mutex);
    }

    free(resource_list);

    log_message("Successfully processed and validated resources.");
    free(crc_list);
    return NULL;
}

void initialize_web_api() {
    srand(time(NULL));
    pthread_t thread;

    for (int i = 0; i < 10; ++i) { // Simulate handling multiple requests concurrently
        if (pthread_create(&thread, NULL, handle_request, NULL)) {
            log_message("Error creating thread");
        }
        pthread_detach(thread);
    }

    while (1);  // Keep the main function running to allow threads to process
}

int main() {
    initialize_web_api();
    return 0;
}
