#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define INITIAL_POOL_SIZE 1000
#define MAX_POOL_SIZE 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pool;
    size_t current_size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_rwlock_t rwlock;
    bool* rnti_in_use;
} NFAPIDPUPool;

// Logging function (dummy implementation for illustration)
void log_event(const char* event) {
    printf("%s\n", event);
}

// Generate a random RNTI
uint16_t generate_unique_rnti(bool* rnti_in_use, size_t capacity) {
    srand(time(NULL));
    uint16_t rnti;
    do {
        rnti = rand() % 0xFFFF;
    } while (rnti_in_use[rnti]);
    return rnti;
}

// Initialize the pool
NFAPIDPUPool* initialize_pool(size_t initial_size) {
    NFAPIDPUPool* pool = malloc(sizeof(NFAPIDPUPool));
    if (!pool) return NULL;

    pool->pool = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->current_size = 0;
    pool->capacity = initial_size;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_rwlock_init(&pool->rwlock, NULL);
    pool->rnti_in_use = calloc(0xFFFF, sizeof(bool));

    if (!pool->rnti_in_use) {
        free(pool->pool);
        free(pool);
        return NULL;
    }

    log_event("Pool initialized");
    return pool;
}

// Resize the pool
bool resize_pool(NFAPIDPUPool* pool, size_t new_capacity) {
    pthread_mutex_lock(&pool->mutex);

    if (new_capacity > MAX_POOL_SIZE) {
        pthread_mutex_unlock(&pool->mutex);
        log_event("Resize request exceeds maximum capacity");
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(pool->pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pool) {
        pthread_mutex_unlock(&pool->mutex);
        log_event("Failed to resize pool due to memory allocation error");
        return false;
    }

    pool->pool = new_pool;
    pool->capacity = new_capacity;
    pthread_mutex_unlock(&pool->mutex);

    log_event("Pool resized");
    return true;
}

// Populate the pool with a valid structure
bool populate_structure(NFAPIDPUPool* pool) {
    pthread_rwlock_wrlock(&pool->rwlock);

    if (pool->current_size >= pool->capacity && !resize_pool(pool, pool->capacity * 2)) {
        pthread_rwlock_unlock(&pool->rwlock);
        log_event("Failed to allocate due to maximum capacity");
        return false;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pool[pool->current_size];

    // Populate fields with sample data
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = generate_unique_rnti(pool->rnti_in_use, 0xFFFF);
    pool->rnti_in_use[pdu->RNTI] = true;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    pool->current_size++;

    pthread_rwlock_unlock(&pool->rwlock);

    log_event("Structure populated");
    return true;
}

// Cleanup function to free resources
void cleanup_pool(NFAPIDPUPool* pool) {
    if (pool) {
        if (pool->rnti_in_use) {
            free(pool->rnti_in_use);
        }
        if (pool->pool) {
            free(pool->pool);
        }
        pthread_mutex_destroy(&pool->mutex);
        pthread_rwlock_destroy(&pool->rwlock);
        free(pool);

        log_event("Pool cleaned up");
    }
}

// Example usage
int main() {
    NFAPIDPUPool* pool = initialize_pool(INITIAL_POOL_SIZE);
    if (!pool) return -1;

    for (size_t i = 0; i < MAX_POOL_SIZE; ++i) {
        if (!populate_structure(pool)) break;
    }

    cleanup_pool(pool);
    return 0;
}
