int isValidStatus(const char* status) {
    const char* validStatuses[] = {"active", "inactive", "maintenance"};
    for (size_t i = 0; i < sizeof(validStatuses) / sizeof(char*); ++i) {
        if (strcmp(status, validStatuses[i]) == 0) {
            return 1;
        }
    }
    logInvalidUpdate("Invalid status encountered.");
    return 0;
}

void initializeNetworkElementStatusArray(NetworkElementStatus** array, int count) {
    if (count > MAX_NETWORK_ELEMENTS || count <= 0) {
        logInvalidUpdate("Request out of range for network element count.");
        *array = NULL;
        return;
    }

    *array = malloc(count * sizeof(NetworkElementStatus));
    if (*array == NULL) {
        logInvalidUpdate("Memory allocation failed.");
        return;
    }

    for (int i = 0; i < count; ++i) {
        (*array)[i].elementId = i + 1;

        char status[10] = "active"; // Default status
        if (!isValidStatus(status)) {
            strcpy(status, "inactive"); // Fallback to a default valid status
        }
        strncpy((*array)[i].status, status, sizeof((*array)[i].status) - 1);

        (*array)[i].performanceMetrics.throughput = (double)(rand() % 1000 + 1);
        (*array)[i].performanceMetrics.latency = (double)(rand() % 200 + 1);
    }
}

void freeNetworkElementStatusArray(NetworkElementStatus* array) {
    if (array != NULL) {
        free(array);
    }
}

int main() {
    NetworkElementStatus* elements;
    initializeNetworkElementStatusArray(&elements, 1000);

    // Example usage
    for (int i = 0; i < 10 && elements != NULL; ++i) {
        printf("Element ID: %d, Status: %s, Throughput: %.2f, Latency: %.2f\n",
               elements[i].elementId, elements[i].status,
               elements[i].performanceMetrics.throughput,
               elements[i].performanceMetrics.latency);
    }

    freeNetworkElementStatusArray(elements);

    return 0;
}
