} log_level_t;

// External logging function prototype (assume it's implemented elsewhere)
void external_log(log_level_t level, const char *message);

// Function to simulate random delay between 1ms and 5ms
void simulate_random_delay() {
    int delay_ms = rand() % 5 + 1;
    usleep(delay_ms * 1000);
}

// Function to allocate memory for NFAPI_CRC_INDICATION_PDU_T structures with error checking
NFAPI_CRC_INDICATION_PDU_T* allocate_memory_for_pdus(size_t count, size_t size_per_pdu) {
    void *ptr = malloc(count * size_per_pdu);
    if (!ptr) {
        external_log(LOG_LEVEL_ERROR, "Memory allocation failed");
        return NULL;
    }
    return (NFAPI_CRC_INDICATION_PDU_T *)ptr;
