        pdus[i].rnti = rand() % 65536;
        pdus[i].rx_ue_information_tag.crc_indication_rel8_tag.crc_flag = rand() % 2;

        // Simulate network delay
        simulate_random_delay();
    }
    return count; // Return the number of successfully populated structures
}

