unsigned int calculate_checksum(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    unsigned int checksum = pdu->rx_ue_information_tag.rnti + pdu->rnti +
                            pdu->rx_ue_information_tag.crc_indication_rel8_tag.crc_flag;
    return checksum % 256; // Simplified checksum
}

// Asynchronous validation function (dummy implementation)
void* validate_structures(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    size_t count = *((size_t*)arg);
    for (size_t i = 0; i < count; ++i) {
        unsigned int checksum = calculate_checksum(&pdus[i]);
        if (checksum != pdus[i].rx_ue_information_tag.rnti % 256) {
            external_log(LOG_LEVEL_WARNING, "Checksum validation failed");
        }
    }
    return NULL;
}

// Main function to generate and populate NFAPI_CRC_INDICATION_PDU_T structures
void* generate_and_populate_pdus(void *args) {
    size_t max_pdu_count = *((size_t*)args);
    size_t memory_limit_in_bytes = *((size_t*)((char*)args + sizeof(size_t)));
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond_var, NULL);

    size_t size_per_pdu = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int pdu_count = 0;

    while (pdu_count < max_pdu_count) {
        size_t available_memory = memory_limit_in_bytes - (pdu_count * size_per_pdu);
        if (available_memory < size_per_pdu) break;

        NFAPI_CRC_INDICATION_PDU_T *pdus = allocate_memory_for_pdus(1, size_per_pdu);
        if (!pdus) continue;

        int created = populate_pdus(pdus + pdu_count, 1);
        if (created > 0) {
            pdu_count += created;
            external_log(LOG_LEVEL_INFO, "Successfully created PDUs");

            // Start asynchronous validation
            pthread_t validation_thread;
            pthread_create(&validation_thread, NULL, validate_structures, &pdus[pdu_count - 1]);
            pthread_detach(validation_thread);
        } else {
            free(pdus);
        }
    }

    external_log(LOG_LEVEL_INFO, "Total PDUs created: %d", pdu_count);

    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond_var);

    return NULL;
}

int main() {
    srand(time(NULL));

    size_t max_pdu_count = 1000; // Example value
    size_t memory_limit_in_bytes = 1048576; // Example value: 1MB

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, generate_and_populate_pdus, &max_pdu_count);
    pthread_join(thread_id, NULL);

    return 0;
}
