    if (!tm) return NULL;

    pthread_mutex_init(&tm->lock, NULL);
    tm->traffic_array = (NetworkTraffic**)malloc(max_size * sizeof(NetworkTraffic*));
    tm->current_size = 0;
    tm->max_size = max_size;
    tm->memory_threshold = 100.0; // Example threshold
    tm->bandwidth_threshold = 500.0; // Example threshold
    tm->cpu_threshold = 75.0; // Example CPU usage percentage

    return tm;
}

void free_traffic_manager(TrafficManager *tm) {
    if (!tm) return;
    for (size_t i = 0; i < tm->current_size; ++i) {
        free_traffic_structures(&tm->traffic_array[i], 1);
    }
    free(tm->traffic_array);
    pthread_mutex_destroy(&tm->lock);
    free(tm);
}

void add_traffic_data(TrafficManager *tm, const char *data_packet, int session_id, size_t pdu_count) {
    if (!tm || tm->current_size >= tm->max_size) return;

    NetworkTraffic *new_entry = allocate_traffic_structure(pdu_count);

    // Initialize new entry
    strncpy(new_entry->DataPacket, data_packet, sizeof(new_entry->DataPacket));
    new_entry->SessionID = session_id;
    new_entry->pdu_count = pdu_count;
    new_entry->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate PDU structures
    for (size_t i = 0; i < pdu_count; ++i) {
        new_entry->pdus[i].RX_UE_INFORMATION_TAG = rand();
        do {
            new_entry->pdus[i].RNTI = rand() % 1000;
        } while ((i > 0 && new_entry->pdus[i].RNTI == new_entry->pdus[i - 1].RNTI) || new_entry->pdus[i].RNTI == 0);

        new_entry->pdus[i].CRC_INDICATION_REL8_TAG = rand();
        new_entry->pdus[i].CRCFLAG = (rand() % 2); // Probabilistic determination
    }

    pthread_mutex_lock(&tm->lock);
    tm->traffic_array[tm->current_size++] = new_entry;
    pthread_mutex_unlock(&tm->lock);

    monitor_resources(tm);
}

void *allocate_traffic_structure(size_t count) {
    NetworkTraffic *nt = (NetworkTraffic*)malloc(sizeof(NetworkTraffic));
    if (!nt) return NULL;

    nt->pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nt->pdus) {
        free(nt);
        return NULL;
    }

    return nt;
}

void free_traffic_structures(NetworkTraffic **array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if ((*array)->pdus) free((*array)->pdus);
        free(*array);
        *array = NULL;
    }
}

int serialize_traffic_to_disk(const NetworkTraffic *traffic, const char *filename, int compress_flag) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t data_size = strlen(traffic->DataPacket) + 1; // Include null terminator
    fwrite(&data_size, sizeof(size_t), 1, file);
    fwrite(traffic->DataPacket, sizeof(char), data_size, file);

    int session_id;
    fwrite(&session_id, sizeof(int), 1, file);

    size_t pdu_count = traffic->pdu_count;
    fwrite(&pdu_count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < pdu_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = traffic->pdus[i];
        fwrite(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }

    fclose(file);

    if (compress_flag) {
        // Compress the serialized data using zlib
        char *input_filename = "temp_serialized_data.bin";
        char *output_filename = "compressed_data.gz";

        FILE *fin = fopen(input_filename, "rb");
        gzFile fout = gzopen(output_filename, "wb9");

        if (!fin || !fout) {
            if (fin) fclose(fin);
            if (fout) gzclose(fout);
            return -1;
        }

        int ret;
        char buffer[8192];
        size_t n;

        do {
            n = fread(buffer, 1, sizeof(buffer), fin);
            ret = gzwrite(fout, buffer, n);
        } while (n > 0 && ret == n);

        fclose(fin);
        gzclose(fout);

        // Optionally replace original file with compressed one
        remove(input_filename);
    }

    return 0;
}

void monitor_resources(TrafficManager *tm) {
    // Implement resource monitoring and alerting here

    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    double memory_usage = (double)(usage.ru_maxrss) / (1024.0 * 1024.0); // Convert to MB
    if (memory_usage > tm->memory_threshold) {
        printf("Memory usage exceeded threshold: %.2f MB\n", memory_usage);
    }

    // Placeholder for bandwidth and CPU monitoring; implement as needed

    double cpu_usage = (double)(usage.ru_utime.tv_sec + usage.ru_stime.tv_sec);
    if (cpu_usage > tm->cpu_threshold) {
        printf("CPU usage exceeded threshold: %.2f%%\n", cpu_usage);
    }
}

// Example DNS resolution function
int resolve_hostname(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int ret;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4

    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(ret));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *) res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), sizeof(struct in_addr));

    freeaddrinfo(res);
    return 0;
}

int main() {
    TrafficManager *tm = initialize_traffic_manager(MAX_TRAFFIC_STRUCTS);

    // Example usage
    add_traffic_data(tm, "Example Data Packet", 1, 10);

    // Serialize to disk with compression enabled
    if (tm->current_size > 0) {
        serialize_traffic_to_disk(tm->traffic_array[0], "traffic_data.bin", 1);
    }

    free_traffic_manager(tm);

    return 0;
}
