// Mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_structure(const NFAPI_CRC_INDICATION_PDU_T *structure) {
    // Integration with existing logging framework
    printf("Structure created: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRCFLAG=%u\n",
           structure->RX_UE_INFORMATION_TAG,
           structure->RNTI,
           structure->CRC_INDICATION_REL8_TAG.CRCFLAG);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    size_t num_structures = 0;

    // Seed random number generator
    srand((unsigned int)time(NULL));

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + 
                          (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        if (elapsed_ms > TIME_BUDGET_MS || num_structures >= MAX_STRUCTURES) {
            break;
        }

        // Allocate memory for new structure
        NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_structure) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        pthread_mutex_lock(&mutex);

        // Generate unique identifiers and CRCFLAG
        do {
            new_structure->RX_UE_INFORMATION_TAG = rand() % 65536;
            new_structure->RNTI = rand() % 4294967295;
            new_structure->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 256;

            // Ensure uniqueness of CRCFLAG
            int unique = 1;
            for (size_t i = 0; i < num_structures && unique; ++i) {
                if (structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG == new_structure->CRC_INDICATION_REL8_TAG.CRCFLAG) {
                    unique = 0;
                }
            }

        } while (!unique);

        // Resize structures array and add the new structure
        NFAPI_CRC_INDICATION_PDU_T *temp_structures = realloc(structures, (num_structures + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_structures) {
            fprintf(stderr, "Memory reallocation failed\n");
            free(new_structure);
            pthread_mutex_unlock(&mutex);
            break;
        }
        structures = temp_structures;
        structures[num_structures++] = *new_structure;

        // Log the new structure
        log_structure(structures + num_structures - 1);

        pthread_mutex_unlock(&mutex);
    }

    // Cleanup
    for (size_t i = 0; i < num_structures; ++i) {
        free(&structures[i]);
    }
    free(structures);

    return 0;
}
