char* renderScripts(ScriptObject *scripts, size_t num_scripts);

// Global variables for unique CRCFLAG tracking
static uint8_t crcflag_set[256] = {0};
static pthread_mutex_t crcflag_lock;

// Initialize the mutex
void initialize_crcflag_lock() {
    pthread_mutex_init(&crcflag_lock, NULL);
}

// Function to generate a unique CRCFLAG
uint8_t generate_unique_crcflag() {
    static int initialized = 0;
    if (!initialized) {
        srand((unsigned int)time(NULL));
        initialized = 1;
    }

    uint8_t crcflag;
    do {
        pthread_mutex_lock(&crcflag_lock);
        crcflag = rand() % 256; // Generate a random number between 0 and 255
        if (crcflag_set[crcflag]) {
            pthread_mutex_unlock(&crcflag_lock);
            continue;
        }
        crcflag_set[crcflag] = 1;
        pthread_mutex_unlock(&crcflag_lock);
    } while (crcflag_set[crcflag]);

    return crcflag;
}

// Function to reset CRCFLAG tracking
void reset_crcflag_tracking() {
    memset(crcflag_set, 0, sizeof(crcflag_set));
}

// Main function to render NFACRC indications
void renderNFACRCIndications(NFAPI_CRC_INDICATION_PDU_T **output, size_t *count) {
