    if (*output == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    initialize_crcflag_lock();
    reset_crcflag_tracking();

    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*output)[i];
        pdu->RX_UE_INFORMATION_TAG = rand(); // Simulate a valid RX_UE_INFORMATION_TAG
        pdu->RNTI = (uint16_t)(rand() % 65536); // Simulate a valid RNTI
        pdu->CRC_INDICATION_REL8_TAG = (uint8_t)(i % 256); // Example tag value

        pdu->CRCFLAG = generate_unique_crcflag();

        // Log the creation of each structure
        printf("Created PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n",
               pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG, pdu->CRCFLAG);
    }

    *count = MAX_ENTRIES;
}

// Function to render scripts into an HTML string
char* renderScripts(ScriptObject *scripts, size_t num_scripts) {
    size_t total_length = 100; // Start with a base length for the resulting HTML string

    // Calculate the required buffer size
    for (size_t i = 0; i < num_scripts; ++i) {
        total_length += strlen(scripts[i].key) + strlen(scripts[i].innerHTML) + 50;
    }

    char *html = (char *)malloc(total_length);
    if (!html) {
        fprintf(stderr, "Memory allocation failed for HTML string\n");
        return NULL;
    }

    strcpy(html, "<div id='footer-scripts'>\n");

    for (size_t i = 0; i < num_scripts; ++i) {
        strcat(html, "<script ");
        strcat(html, scripts[i].key);
        strcat(html, ">");
        strcat(html, scripts[i].innerHTML);
        strcat(html, "</script>\n");
    }

    strcat(html, "</div>");

    return html;
}
