pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

// Simple rotating log file implementation
FILE *log_file = NULL;
long current_log_size = 0;

void rotate_log_file() {
    if (current_log_size >= LOG_FILE_MAX_SIZE) {
        fclose(log_file);
        char new_name[256];
        time_t now = time(NULL);
        sprintf(new_name, "crc_log_%ld.txt", now);
        log_file = fopen(new_name, "w");
        current_log_size = 0;
    }
}

void log_message(const char *message) {
    pthread_mutex_lock(&lock);
    rotate_log_file();
    fprintf(log_file, "%s\n", message);
    fflush(log_file);
    current_log_size += strlen(message) + 1;
    pthread_mutex_unlock(&lock);
}

int generate_unique_rnti(int *rntis, int size) {
    static const char charset[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    char rnti_str[10];
    int len = sizeof(charset) - 1;

    while (1) {
        for (int i = 0; i < 8; i++) {
            rnti_str[i] = charset[rand() % len];
        }
        rnti_str[8] = '\0';

        int unique = 1;
        for (int j = 0; j < size; j++) {
            if (strcmp(rnti_str, itoa(rntis[j], NULL)) == 0) {
                unique = 0;
                break;
            }
        }

        if (unique) {
            int rnti_value = atoi(rnti_str);
            return rnti_value;
        }
    }
}

int generate_crc_flag() {
    static const char flags[] = {"01", "10"};
    int len = sizeof(flags) - 1;
    return rand() % len;
}

NFAPI_CRC_INDICATION_PDU_T* create_structures(int *count) {
    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        log_message("Memory allocation failed");
        return NULL;
    }

    int rntis[MAX_STRUCTURES] = {0};
    int unique_crc_flags[2] = {-1, -1};

    for (int i = 0; i < MAX_STRUCTURES && i < *count; i++) {
        pthread_mutex_lock(&lock);

        while (!pthread_cond_timedwait(&cond_var, &lock, &(struct timespec){time(NULL) + 5, 0})) {
            // Retry logic with exponential backoff
            if (errno == EINTR) break;
        }

        int rnti = generate_unique_rnti(rntis, i);
        rntis[i] = rnti;

        int crc_flag_index = generate_crc_flag();
        while (unique_crc_flags[crc_flag_index] != -1) {
            crc_flag_index = 1 - crc_flag_index;
        }
        unique_crc_flags[crc_flag_index] = i;

        structures[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        structures[i].RNTI = rnti;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 1000;
        strncpy(structures[i].CRCFLAG, flags[crc_flag_index], sizeof(flags[0]));

        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "Structure created: %d, RNTI: %d, CRCFLAG: %s", i, rnti, structures[i].CRCFLAG);
        log_message(log_entry);

        pthread_mutex_unlock(&lock);
    }

    *count = MAX_STRUCTURES;
    return structures;
}

void* validate_structures(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *structures = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    int count = 0;

    for (int i = 0; i < MAX_STRUCTURES; i++) {
        if (!strcmp(structures[i].CRCFLAG, "01") || !strcmp(structures[i].CRCFLAG, "10")) {
            log_message("Structure validated: CRCFLAG is consistent");
        } else {
            log_message("Anomaly detected in structure CRCFLAG");
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    int count = 0;
    NFAPI_CRC_INDICATION_PDU_T *structures = create_structures(&count);

    if (structures) {
        pthread_t validate_thread;
        pthread_create(&validate_thread, NULL, validate_structures, structures);
        pthread_join(validate_thread, NULL);

        free(structures);
    }

    fclose(log_file);
    return 0;
}
```

