    time_t timestamp;
    EventType event_type;
    struct EventRecord* next;
} EventRecord;

typedef struct {
    EventRecord* head;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} EventList;

// Initialize the dynamic list of events
EventList* init_event_list() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a new event record
void insert_event_record(EventList* list, unsigned int rnti, time_t timestamp, EventType event_type) {
    EventRecord* new_record = (EventRecord*)malloc(sizeof(EventRecord));
    if (!new_record) return;

    new_record->rnti = rnti;
    new_record->timestamp = timestamp;
    new_record->event_type = event_type;
    new_record->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_record->next = list->head;
    list->head = new_record;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    // Try to save to database
    if (!save_to_database(new_record)) {
        // Fallback: Save to a local file or retry later
        fallback_save(new_record);
    }
}

// Delete an event record by RNTI
void delete_event_record(EventList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    EventRecord *current = list->head, *prev = NULL;
    while (current && current->rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current) {  // Record found
        if (prev)
            prev->next = current->next;
        else
            list->head = current->next;

        free(current);
        list->count--;
    }

    pthread_mutex_unlock(&list->lock);
}

// Retrieve an event record by RNTI
EventRecord* get_event_record(EventList* list, unsigned int rnti) {
    EventRecord *current = list->head;
    while (current && current->rnti != rnti) {
        current = current->next;
    }
    return current;  // Return NULL if not found
}

// Prune old events to maintain memory efficiency
void prune_old_events(EventList* list, time_t cutoff_time) {
    pthread_mutex_lock(&list->lock);

    EventRecord *current = list->head, *prev = NULL;

    while (current && current->timestamp < cutoff_time) {
        if (prev)
            prev->next = current->next;
        else
            list->head = current->next;

        free(current);
        list->count--;
        current = prev ? prev->next : list->head;
