    pthread_mutex_unlock(&list->lock);

    // Attempt to sync pruned events with the database.
    if (!sync_with_database()) {
        // Fallback: Log failure or retry
        log_prune_failure();
    }
}

// Periodic pruning strategy (FIFO)
void periodic_pruning(EventList* list) {
    time_t current_time = time(NULL);
    time_t cutoff_time = current_time - (24 * 60 * 60); // Keep events from the last day

    while (list->count > MAX_EVENTS) {
