    list->size = 0;
    list->capacity = initial_capacity;
}

// Resize the dynamic list
void resize_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        list->data = new_data;
        list->capacity = new_capacity;
    } else {
        fprintf(stderr, "Memory allocation failed during resize\n");
        exit(EXIT_FAILURE);
    }
}

// Check if RNTI is unique in the list
int rnti_exists(DynamicList *list, int rnti) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

// Add an element to the dynamic list
int add_element(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (rnti_exists(list, element.RNTI)) {
        fprintf(stderr, "RNTI %d already exists\n", element.RNTI);
        return 0;
    }
    if (list->size >= list->capacity) {
        resize_list(list);
    }
    list->data[list->size++] = element;
    return 1;
}

// Serialize the dynamic list into a binary format
int serialize_list(const DynamicList *list, unsigned char **output, size_t *output_size) {
    if (!list || !output || !output_size) return -1;

    *output_size = list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *output = (unsigned char *)malloc(*output_size);

    if (*output == NULL) {
        fprintf(stderr, "Memory allocation failed during serialization\n");
        return -1;
    }

    memcpy(*output, list->data, *output_size);
    return 0;
}

// Deserialize binary data back into a dynamic list
int deserialize_list(const unsigned char *input, size_t input_size, DynamicList *list) {
    if (!input || !list) return -1;

    NFAPI_CRC_INDICATION_PDU_T element;
    size_t num_elements = input_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);

    init_list(list, num_elements);
    list->size = num_elements;

    for (size_t i = 0; i < num_elements; ++i) {
        memcpy(&element, &input[i * sizeof(NFAPI_CRC_INDICATION_PDU_T)], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!add_element(list, element)) {
            fprintf(stderr, "Deserialization failed due to duplicate RNTI\n");
            return -1;
        }
    }

    return 0;
}

// Example of using the dynamic list
int main() {
