} UE_SESSION_RECORD;

// Function prototypes for logging and resizing
void log_event(const char *event);
UE_SESSION_RECORD* resize_array(UE_SESSION_RECORD *array, size_t current_capacity, size_t new_capacity);

// Dynamic array management function
UE_SESSION_RECORD* manage_ue_sessions(size_t initial_size) {
    static const double RESIZE_FACTOR = 1.5;
    UE_SESSION_RECORD *sessions = NULL;
    size_t capacity = 0;

    // Allocate initial memory
    sessions = (UE_SESSION_RECORD *)malloc(initial_size * sizeof(UE_SESSION_RECORD));
    if (!sessions) {
        log_event("Memory allocation failed");
        return NULL;
    }
    capacity = initial_size;
    log_event("Initial allocation");

    return sessions;
}

// Function to add a user session record
int add_ue_session(UE_SESSION_RECORD **sessions, size_t *capacity, const UE_SESSION_RECORD *new_record) {
    if (!*sessions || !new_record) return -1;

    // Check if resizing is needed
    if (0 == *sessions[(*capacity)-1].UE_IDENTIFIER) {  // Simplified check assuming last slot is empty marker
        size_t new_capacity = (*capacity) + 1;
        UE_SESSION_RECORD *temp_sessions = resize_array(*sessions, *capacity, new_capacity);
        if (!temp_sessions) {
            log_event("Resizing failed");
            return -1;
        }
        *sessions = temp_sessions;
        (*capacity) = new_capacity;
    }

    // Copy the new record into the array
    for (size_t i = 0; i < *capacity; ++i) {
        if (0 == (*sessions)[i].UE_IDENTIFIER) {  // Find an empty slot
            memcpy(&(*sessions)[i], new_record, sizeof(UE_SESSION_RECORD));
            log_event("User session added");
            return 0;
        }
    }

    return -1;  // Should never reach here if logic is correct
}

// Function to remove a user session record by identifier
int remove_ue_session(UE_SESSION_RECORD **sessions, size_t *capacity, int ue_identifier) {
    if (!*sessions || !capacity) return -1;

    for (size_t i = 0; i < *capacity; ++i) {
        if ((*sessions)[i].UE_IDENTIFIER == ue_identifier) {
            (*sessions)[i].UE_IDENTIFIER = 0; // Mark as empty
            log_event("User session removed");
            return 0;
        }
    }

    return -1; // Identifier not found
}

// Function to free memory of the sessions array
void free_ue_sessions(UE_SESSION_RECORD **sessions) {
    if (sessions && *sessions) {
        free(*sessions);
        *sessions = NULL;
        log_event("Memory deallocated");
    }
}

// Resize array function with logging
UE_SESSION_RECORD* resize_array(UE_SESSION_RECORD *array, size_t current_capacity, size_t new_capacity) {
    UE_SESSION_RECORD *new_array = (UE_SESSION_RECORD *)realloc(array, new_capacity * sizeof(UE_SESSION_RECORD));
    if (!new_array) {
        log_event("Reallocation failed");
        return NULL;
    }

    // Initialize new slots to empty state
    for (size_t i = current_capacity; i < new_capacity; ++i) {
        new_array[i].UE_IDENTIFIER = 0;
    }

    log_event("Array resized");
    return new_array;
}

// Logging function implementation
void log_event(const char *event) {
    printf("[LOG] %s\n", event);
}
