#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000
#define MAX_CONCURRENT_REQUESTS 50

typedef struct {
    int CRCFLAG; // Assuming CRCFLAG is an integer for simplicity.
} CRC_INDICATION_REL8_TAG;

typedef uint16_t RNTI;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t queueMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t requestCondition = PTHREAD_COND_INITIALIZER;
int activeRequests = 0;
NFAPI_CRC_INDICATION_PDU_T* pduArray[MAX_ELEMENTS] = {NULL};

void logError(const char *message) {
    fprintf(stderr, "%s\n", message);
}

bool initializePduArray(NFAPI_CRC_INDICATION_PDU_T** pduArray, int N) {
    if (N <= 0 || N > MAX_ELEMENTS) return false;

    pthread_mutex_lock(&queueMutex);

    for (int i = 0; i < N; ++i) {
        pduArray[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pduArray[i]) {
            logError("Memory allocation failed");
            // Free previously allocated memory
            while (--i >= 0) free(pduArray[i]);
            pthread_mutex_unlock(&queueMutex);
            return false;
        }
    }

    pthread_mutex_unlock(&queueMutex);
    return true;
}

void* allocatePduArray(void* arg) {
    int N = *(int*)arg;

    if (N <= 0 || N > MAX_ELEMENTS) {
        logError("Invalid input parameter");
        return NULL;
    }

    pthread_mutex_lock(&queueMutex);

    while (activeRequests >= MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&requestCondition, &queueMutex);
    }

    activeRequests++;

    pthread_mutex_unlock(&queueMutex);

    if (!initializePduArray(pduArray, N)) {
        pthread_mutex_lock(&queueMutex);
        activeRequests--;
        pthread_cond_signal(&requestCondition);
        pthread_mutex_unlock(&queueMutex);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        pduArray[i]->RX_UE_INFORMATION_TAG = rand(); // Randomized initialization example
        pduArray[i]->rnti = rand();
        pduArray[i]->crcTag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    pthread_mutex_lock(&queueMutex);
    activeRequests--;
    pthread_cond_signal(&requestCondition);
    pthread_mutex_unlock(&queueMutex);

    return (void*)pduArray;
}

int main() {
    int N = 100; // Example size

    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        int* n = malloc(sizeof(int));
        *n = N;
        if (pthread_create(&threads[i], NULL, allocatePduArray, (void*)n)) {
            logError("Failed to create thread");
            free(n);
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup
    for (int i = 0; i < N && pduArray[i]; ++i) {
        free(pduArray[i]);
    }

    return 0;
}
