// Structure to hold a list of NF API Indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t count;
    size_t capacity;
} NFAPI_LIST_T;

// Hash function for strings using djb2 algorithm
unsigned long hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    }
    return hash;
}

// Function to initialize the list
void init_list(NFAPI_LIST_T* list) {
    list->items = NULL;
    list->count = 0;
    list->capacity = 0;
}

// Function to resize the list when needed
int resize_list(NFAPI_LIST_T* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_items = realloc(list->items, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_items == NULL) {
        return -1; // Memory allocation failed
    }
    list->items = new_items;
    list->capacity = new_capacity;
    return 0;
}

// Function to add an item to the list and recalculate hash for data integrity check
int add_to_list(NFAPI_LIST_T* list, RX_UE_INFORMATION_TAG rx_ue_info, RNTI rnti, const char *data_str) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 4 : list->capacity * 2;
        int resize_status = resize_list(list, new_capacity);
        if (resize_status != 0) {
            return -1; // Failed to allocate more memory
        }
    }

    unsigned long data_hash = hash_string(data_str);

    NFAPI_CRC_INDICATION_PDU_T* item = &list->items[list->count];

    item->rx_ue_info.valid = rx_ue_info.valid;
    item->rnti = rnti;
    item->crc_indication.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    printf("Data Hash: %lu\n", data_hash);

    list->count++;
    return 0;
}

