        pool_size = size;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool() {
    static size_t index = 0;
    if (index < pool_size) {
        return &memory_pool[index++];
    } else {
        // Reinitialize the pool when exhausted
        index = 0;
        return &memory_pool[index++];
    }
}

void free_memory_pool() {
