        Node* new_node = malloc(sizeof(Node));
        new_node->data = *new_data;
        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
        } else {
            tail->next = new_node;
        }
        tail = new_node;
    }

    free_memory_pool();
    return head;
}

void free_linked_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
