unsigned int generate_random_number(unsigned int max) {
    return rand() % max + 1;
}

// Function to validate structure
int validate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Example validation criteria: RNTI should not be zero
    if (pdu->RNTI == 0) {
        return 0;
    }
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* create_nfa_list(int N) {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = NULL;
    int i;

    nfa_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_list) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand((unsigned int)time(NULL));

    for (i = 0; i < N; ++i) {
        nfa_list[i].RX_UE_INFORMATION_TAG = generate_random_number(100);
        nfa_list[i].RNTI = generate_random_number(1000);
        nfa_list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!validate_structure(&nfa_list[i])) {
            fprintf(stderr, "Invalid structure at index %d\n", i);
            free(nfa_list);
            return NULL;
        }
    }

    return nfa_list;
}

int main(int argc, char *argv[]) {
    int N = 10; // Example value for demonstration

    if (argc > 1) {
        N = atoi(argv[1]);
    }

    NFAPI_CRC_INDICATION_PDU_T *nfa_list = create_nfa_list(N);
    if (!nfa_list) {
        return EXIT_FAILURE;
    }

    printf("NFA List created successfully with %d elements.\n", N);

    // Call the PHP script here (e.g., using system call)
    system("php authenticate_user.php");

    free(nfa_list);
    return EXIT_SUCCESS;
}
