<?php
session_start();

function authenticate_user() {
    $client_id = 'your_client_id';
    $client_secret = 'your_client_secret';
    $token_url = 'https://example.com/oauth/token';

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $token_url);
    curl_setopt($ch, CURLOPT_POST, 1);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query([
        'grant_type' => 'client_credentials',
        'client_id' => $client_id,
        'client_secret' => $client_secret
    ]));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

    $response = curl_exec($ch);
    if ($response === false) {
        // Handle network error
        echo "Network error: " . curl_error($ch);
        return;
    }

    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    if ($http_code != 200) {
        // Handle non-200 response
        echo "Error: HTTP code " . $http_code;
        return;
    }

    $data = json_decode($response, true);
    if (isset($data['access_token'])) {
        $_SESSION['access_token'] = $data['access_token'];
    } else {
        // Handle error in response
        echo "Error: Invalid access token";
    }

    curl_close($ch);

    // Assume RNTI is passed as an argument or retrieved from another source
    $rnti = $argv[1] ?? 'default_rnti';
    retrieve_user_info($rnti);
}

function retrieve_user_info($rnti) {
    $user_url = "https://example.com/api/userinfo?rnti=" . urlencode($rnti);

    if (!isset($_SESSION['access_token'])) {
        echo "No access token found";
        return;
    }

    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $user_url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ]);

    $response = curl_exec($ch);
    if ($response === false) {
        // Handle network error
        echo "Network error: " . curl_error($ch);
        return;
    }

    $http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    if ($http_code == 429 || $http_code >= 500) { // Rate limit or server errors
        sleep(1); // Simple retry logic; use exponential backoff in production
        retrieve_user_info($rnti);
        return;
    }

    if ($http_code != 200) {
        echo "Error: HTTP code " . $http_code;
        return;
    }

    $data = json_decode($response, true);
    print_r($data);

