    int crc_flag; // Calculated CRC value
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_Array;

#define INITIAL_CAPACITY 16

// Function prototypes
int init_crc_indication_array(CRC_Indication_Array *arr);
int insert_pdu(CRC_Indication_Array *arr, NFAPI_CRC_INDICATION_PDU_T pdu);
int delete_pdu_by_rnti(CRC_Indication_Array *arr, RNTI rnti);
NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu_by_rnti(const CRC_Indication_Array *arr, RNTI rnti);
uint32_t compute_crc(RX_UE_INFORMATION_TAG *ue_info);

// Initialize the dynamic array
int init_crc_indication_array(CRC_Indication_Array *arr) {
    arr->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->array) return -1; // Memory allocation failed
    arr->size = 0;
    arr->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&arr->lock, NULL);
    return 0;
}

// Insert a new PDU into the array
int insert_pdu(CRC_Indication_Array *arr, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(arr->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&arr->lock);
            return -1; // Memory allocation failed
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    pdu.crc_flag = compute_crc(&pdu.ue_info_tag);
    arr->array[arr->size++] = pdu;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

// Delete a PDU by RNTI
int delete_pdu_by_rnti(CRC_Indication_Array *arr, RNTI rnti) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].rnti == rnti) {
            memmove(&arr->array[i], &arr->array[i + 1], (arr->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            arr->size--;
            pthread_mutex_unlock(&arr->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // RNTI not found
}

// Retrieve a PDU by RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieve_pdu_by_rnti(const CRC_Indication_Array *arr, RNTI rnti) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &arr->array[i];
            pthread_mutex_unlock(&arr->lock);
            return pdu;
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return NULL; // RNTI not found
}

// Compute CRC for the given UE information
uint32_t compute_crc(RX_UE_INFORMATION_TAG *ue_info) {
    uint32_t crc = 0;
    const size_t len = sizeof(ue_info->data);

    for (size_t i = 0; i < len; ++i) {
        crc ^= (uint32_t)(ue_info->data[i]) << (8 * i);
        // Example CRC computation logic
        for (int j = 0; j < 8; ++j) {
            if (crc & 1)
                crc = (crc >> 1) ^ 0xEDB88320;
            else
                crc >>= 1;
        }
    }

    return ~crc; // Final CRC value
}

// Free the dynamic array resources
void free_crc_indication_array(CRC_Indication_Array *arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->array);
    arr->array = NULL;
    arr->size = 0;
    arr->capacity = 0;
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}
