NFAPI_CRC_INDICATION_PDU_T* generateNfadPduListWithCRC(const char *inputString, size_t sizeLimit, size_t *numElements) {
    if (inputString == NULL || numElements == NULL) {
        return NULL; // Error handling for null pointers
    }

    size_t inputSize = strlen(inputString);

    // Handle string exceeding size limit by creating an empty structure.
    if (inputSize > sizeLimit) {
        *numElements = 0;
        return NULL; // Returning NULL to indicate no elements due to the size limit issue.
    }

    // Calculate required payload size: original + slash + null terminator
    size_t requiredPayloadSize = inputSize + 2;

    if (requiredPayloadSize > sizeof(NFAPI_CRC_INDICATION_PDU_T->payload)) {
        *numElements = 0;
        return NULL; // Error handling for payload overflow.
    }

    // Determine the number of PDU structures to create based on size limits and efficiency
    const size_t maxEntries = (sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(char) - 1) / sizeof(char);
    size_t elementsCount = requiredPayloadSize <= maxEntries ? 1 : (requiredPayloadSize + maxEntries - 1) / maxEntries;

    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(elementsCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduList) {
        return NULL; // Memory allocation failure
    }

    size_t index = 0;
    for (size_t i = 0; i < elementsCount; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &pduList[i];

        pdu->RX_UE_INFORMATION_TAG = rand(); // Assume this is set appropriately
        pdu->RNTI = rand();                  // Assume this is set appropriately

        pdu->crcIndicationTagRel8.CRCFLAG = getRandomBool() ? 1 : 0;

        size_t copySize = (i == elementsCount - 1) ? requiredPayloadSize % maxEntries : maxEntries;
        if (index + copySize <= inputSize) {
            memcpy(pdu->payload, inputString + index, copySize);
        } else {
            // Last chunk or the only part of the string
            size_t remaining = requiredPayloadSize - index;
            memcpy(pdu->payload, inputString + index, remaining);

            if (index == inputSize) { // If this is the last portion, append slash and null terminator.
                pdu->payload[remaining] = '/';
                pdu->payload[requiredPayloadSize - 1] = '\0';
            }
        }

        index += copySize;
    }

    *numElements = elementsCount;

    return pduList; // Return the created list
}

// Example usage function (for demonstration only)
