['```c
#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_STALE_DURATION 300 // Example in seconds
typedef struct {
    int ue_id;
    float signal_strength;
    time_t last_report_timestamp;
} UeStats;

typedef struct Node {
    UeStats data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    time_t current_time; // for simulation
} UeStatsList;

UeStatsList* create_list() {
    UeStatsList* list = (UeStatsList*)malloc(sizeof(UeStatsList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    time(&list->current_time);
    return list;
}

void destroy_list(UeStatsList* list) {
    Node *curr, *next;
    pthread_mutex_lock(&list->lock);

    for (curr = list->head; curr != NULL;) {
        next = curr->next;
        free(curr);
        curr = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void log_change(int ue_id, float new_signal) {
    // Simple logging mechanism
    printf("UE %d signal updated to %.2f\n", ue_id, new_signal);
}

int update_or_add_ue_stats(UeStatsList* list, UeStats new_data) {
    pthread_mutex_lock(&list->lock);

    Node *curr = list->head, *prev = NULL;
    while (curr != NULL && curr->data.ue_id != new_data.ue_id) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) { // Add new entry
        curr = (Node*)malloc(sizeof(Node));
        if (!curr) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
        curr->data = new_data;
        curr->next = list->head;
        list->head = curr;

    } else { // Update existing entry
        curr->data.signal_strength = new_data.signal_strength;
        time(&curr->data.last_report_timestamp);
        log_change(new_data.ue_id, new_data.signal_strength);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void purge_stale_entries(UeStatsList* list, int max_duration) {
    pthread_mutex_lock(&list->lock);

    Node *curr = list->head, *prev = NULL, *next;
    time_t current_time = list->current_time;

    while (curr != NULL) {
        next = curr->next;
        if ((current_time - curr->data.last_report_timestamp) > max_duration) {
            if (prev == NULL) {
                list->head = curr->next; // Removing head
            } else {
                prev->next = curr->next;
            }
            free(curr);
        } else {
            prev = curr;
        }
        curr = next;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    UeStatsList* ue_stats_list = create_list();

    // Example update
    UeStats new_data = {1, -70.5f, 0}; // Example UE data with current time as 0
    time(&new_data.last_report_timestamp); // Set to the current time

    if (update_or_add_ue_stats(ue_stats_list, new_data) == 0) {
        printf("UE stats updated successfully\n");
    } else {
        printf("Failed to update UE stats due to memory allocation error\n");
    }

    // Simulate some time passing
    sleep(1);

    purge_stale_entries(ue_stats_list, MAX_STALE_DURATION);
    destroy_list(ue_stats_list);

    return 0;
}
```

