void processRxDataWithCRCIndication(
        const RX_DATA_RECORD* records,
        size_t num_records,
        int max_pdus_per_record,
        bool enforce_buffer_limits) {

    for (size_t i = 0; i < num_records; ++i) {
        const RX_DATA_RECORD* record = &records[i];

        if (record->rnti > MAX_RNTI || record->rnti == 0) {
            continue; // Skip invalid RNTI
        }

        size_t pdus_to_generate = (max_pdus_per_record < 1) ? 1 : max_pdus_per_record;
        NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(pdus_to_generate * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdus) {
            continue; // Memory allocation failed, proceed to next record
        }

        for (size_t j = 0; j < pdus_to_generate; ++j) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdus[j];
            CRC_INDICATION_REL8_TAG* tag = &pdu->tag;

            // Set CRC_FLAG randomly
            tag->crcFlag = rand() % 2;

            const char* payload = record->ue_info_tag->payload;
            size_t payload_len = record->ue_info_tag->payload_len;

            if (enforce_buffer_limits && payload_len < 256) { // Example buffer limit condition
                payload_len += 1; // Add space for the slash
            }

            tag->payload = malloc(payload_len + 1);

            if (!tag->payload) {
                break; // Memory allocation failed, clean up and proceed to next PDU generation
            }

            strncpy(tag->payload, payload, payload_len);

            if (enforce_buffer_limits && payload_len < 256) { // Example buffer limit condition
                tag->payload[payload_len] = '/';
                payload_len += 1;
            }

            tag->payload[payload_len] = '\0'; // Ensure null-termination

            tag->payload_len = payload_len;
        }

        // Free allocated PDU structures if needed by the system
        for (size_t j = 0; j < pdus_to_generate; ++j) {
            free(pdus[j].tag.payload);
        }

        free(pdus); // Free the list of PDUs
    }
}
