// PHP Code

<?php
session_start();

function authenticate_user() {
    $url = 'https://api.example.com/oauth/token';
    $timeout = 10;

    try {
        $response = file_get_contents($url, false, stream_context_create([
            'http' => [
                'method' => "POST",
                'header' => "Content-Type: application/x-www-form-urlencoded\r\n",
                'content' => http_build_query(['grant_type' => 'client_credentials']),
                'timeout' => $timeout
            ]
        ]));

        if ($response === FALSE) {
            throw new Exception("API request failed.");
        }

        $data = json_decode($response, true);
        $_SESSION['access_token'] = $data['access_token'];
    } catch (Exception $e) {
        error_log('Error: ' . $e->getMessage());
        // Handle retries or fallbacks here
    }
}

function get_user_info($rnti) {
    if (!isset($_SESSION['access_token'])) {
        authenticate_user();
    }

    $url = "https://api.example.com/user?rnti=$rnti";

    try {
        $context = stream_context_create([
            'http' => [
                'method' => "GET",
                'header' => "Authorization: Bearer " . $_SESSION['access_token'] . "\r\n"
            ]
        ]);

        $response = file_get_contents($url, false, $context);
        if ($response === FALSE) {
            throw new Exception("Failed to fetch user information.");
        }

        return json_decode($response, true);

    } catch (Exception $e) {
        error_log('Error: ' . $e->getMessage());
        // Handle retries or fallbacks here
    }
}

