LogTracker log_tracker;

void init_log_tracker(const char* log_path, const char* archive_dir) {
    pthread_mutex_init(&log_tracker.log_lock, NULL);
    log_tracker.archive_dir = archive_dir;
    log_tracker.current_size = 0;

    // Open or create the log file
    log_tracker.log_file = fopen(log_path, "a+");
    if (!log_tracker.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_log_tracker() {
    fclose(log_tracker.log_file);
    pthread_mutex_destroy(&log_tracker.log_lock);
}

void rotate_logs_if_needed() {
    pthread_mutex_lock(&log_tracker.log_lock);

    fseek(log_tracker.log_file, 0, SEEK_END);
    log_tracker.current_size = ftell(log_tracker.log_file);

    if (log_tracker.current_size >= MAX_LOG_SIZE) {
        fclose(log_tracker.log_file);

        char new_log_path[256];
        snprintf(new_log_path, sizeof(new_log_path), "%s/log_%ld.txt", log_tracker.archive_dir, time(NULL));
        rename("current.log", new_log_path);

        log_tracker.log_file = fopen("current.log", "a+");
    }

    pthread_mutex_unlock(&log_tracker.log_lock);
}

void log_message(const char* message) {
    rotate_logs_if_needed();

    pthread_mutex_lock(&log_tracker.log_lock);
    fprintf(log_tracker.log_file, "%s\n", message);
    fflush(log_tracker.log_file);
    pthread_mutex_unlock(&log_tracker.log_lock);
}

int resolve_dns(const char* hostname, u_char* ip_addr) {
    struct hostent *he;
    int ret = -1;

    if (gethostbyname_r(hostname, &he, NULL, 0, NULL, ERRENOF(0), ERRENOF(1)) == ERRENOF(0)) {
        memcpy(ip_addr, he->h_addr_list[0], he->h_length);
        ret = 0; // Success
    } else {
        log_message("DNS resolution failed for hostname: ");
        log_message(hostname);
    }

    return ret;
}

void* dns_resolver_thread(void* arg) {
    DNSRequest* requests = (DNSRequest*)arg;
    size_t num_requests = *(size_t*)arg;

    u_char* ip_buffer[100];
    for (size_t i = 0; i < num_requests; ++i) {
        pthread_mutex_lock(&dns_lock);

        // Wait if request limit reached
        while (__sync_fetch_and_add(&(requests[i].ip_addr), 1)) {
            pthread_cond_wait(&dns_cond, &dns_lock);
        }

        ip_buffer[i] = malloc(16); // Enough for IPv6

        int result = resolve_dns(requests[i].hostname, ip_buffer[i]);
        requests[i].ip_addr = (result == 0) ? ip_buffer[i] : NULL;

        pthread_mutex_unlock(&dns_lock);

        if (requests[i].ip_addr != NULL) {
            log_message("DNS resolution succeeded for hostname: ");
            log_message(requests[i].hostname);
        }
    }

    return NULL;
}

void generate_nfa_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t n, const char** hostnames, size_t num_hostnames) {
    pthread_t threads[100];
    DNSRequest requests[num_hostnames];

    for (size_t i = 0; i < num_hostnames; ++i) {
        strncpy(requests[i].hostname, hostnames[i], sizeof(requests[i].hostname));
        requests[i].ip_addr = NULL;
    }

    size_t num_threads = num_hostnames > 100 ? 100 : num_hostnames;

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, dns_resolver_thread, &requests);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand() % ((1 << 32) - 1); // Ensure it's a valid RNTI
        for (int j = 0; j < 10; ++j) {
            list[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        list[i].CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
    }
}

int main(int argc, char* argv[]) {
    const char *hostnames[] = {"example.com", "google.com"};
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    init_log_tracker("current.log", "./archive");

    generate_nfa_list(pdu_list, 10, hostnames, 2);

    close_log_tracker();
    free(pdu_list);
    return 0;
}
