void initDynamicArray(DynamicArray *array) {
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(array->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void freeDynamicArray(DynamicArray *array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->count = 0;
}

bool addOrUpdateElement(DynamicArray *array, int rnti, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!resizeIfNeeded(array)) return false;

    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].crcTag.RNTI == rnti) {
            array->data[i] = element;
            return true;
        }
    }

    array->data[array->count++] = element;
    return true;
}

bool removeElementByRNTI(DynamicArray *array, int rnti) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->data[i].crcTag.RNTI == rnti) {
            memmove(&array->data[i], &array->data[i + 1],
                    (array->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            array->count--;
            return true;
        }
    }
    return false;
}

void iterateOverElements(const DynamicArray *array, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T *)) {
    for (size_t i = 0; i < array->count; ++i) {
        callback(&array->data[i]);
    }
}

static bool resizeIfNeeded(DynamicArray *array) {
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *newData = realloc(array->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            fprintf(stderr, "Memory reallocation failed\n");
            return false;
        }
        array->data = newData;
        array->capacity = newCapacity;
    }
    return true;
}

// Example callback function
