uint32_t calculate_checksum(const CRCArray *arr) {
    uint32_t checksum = 0;
    for (size_t i = 0; i < arr->size; ++i) {
        checksum += arr->array[i].RX_UE_INFORMATION_TAG + arr->array[i].RNTI + arr->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG;
    }
    return checksum;
}

void serialize_crc_array(const CRCArray *arr, char **output, size_t *output_size) {
    *output_size = sizeof(size_t) + arr->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
