    CRCArray *arr = create_crc_array(*size_ptr);
    if (!arr) return NULL;

    memcpy(arr->array, input + sizeof(size_t), *size_ptr * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->size = *size_ptr;

    return arr;
}

