#include <pthread.h>

#define RNTI_MIN 1
#define RNTI_MAX 1000
#define CRCFLAG_SIZE 256

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint8_t CRCFLAG;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

uint16_t generate_unique_tag(uint16_t seed, int *used_tags) {
    uint16_t tag;
    do {
        tag = (seed * 2654435761u) % 4294967296u; // Linear congruential generator
        if (!used_tags[tag % RNTI_MAX]) break;
    } while (1);
    used_tags[tag % RNTI_MAX] = 1;
    return tag;
}

NFAPI_CRC_INDICATION_PDU_T *initialize_crc_array(int N, uint32_t seed) {
    pthread_mutex_lock(&lock);

    int used_tags[RNTI_MAX] = {0};
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        array[i].tag.RX_UE_INFORMATION_TAG = generate_unique_tag(seed + i, used_tags);
        array[i].tag.RNTI = (uint16_t)((rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN);

        // Secure random generation for CRCFLAG
        if (!srandomdev()) { // Fallback if secure RNG not available
            fprintf(stderr, "Warning: Secure random number generator unavailable.\n");
        }
        array[i].CRCFLAG = (uint8_t)(rand() % CRCFLAG_SIZE);
    }

    pthread_mutex_unlock(&lock);
    return array;
}

void cleanup_crc_array(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (!array) return;

    pthread_mutex_lock(&lock);
    free(array);
    pthread_mutex_unlock(&lock);
}

