}

NFAPI_CRC_INDICATION_PDU_T** processAndDecryptNfadecrypt(size_t num_pdus, unsigned char *ciphertext, size_t ciphertext_len,
                                                          const unsigned char *key, const unsigned char *iv, 
                                                          size_t key_len, size_t iv_len, size_t *plaintext_len) {
    if (num_pdus <= 0 || !ciphertext || !key || !iv || plaintext_len == NULL) {
        log_message("Invalid input parameters.");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdus) {
        log_message("Memory allocation failed for PDU structures.");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus[i]) {
            log_message("Memory allocation failed for a PDU structure.");

            // Free previously allocated structures
            while (i > 0) {
                free(pdus[--i]);
            }
            free(pdus);
            return NULL;
        }

        pdus[i]->RX_UE_INFORMATION_TAG = rand() % 65536; // Generate random tag
        pdus[i]->RNTI = rand() % 65536;                  // Generate random RNTI
        pdus[i]->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
    }

    log_message("Successfully created PDU structures.");

    // Prepare decryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Failed to create cipher context.");

        for (size_t i = 0; i < num_pdus; ++i) {
            free(pdus[i]);
        }
        free(pdus);
        return NULL;
    }

    // Initialize decryption
    if (EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv) != 1) {
        log_message("Decryption initialization failed.");

        EVP_CIPHER_CTX_free(ctx);
        for (size_t i = 0; i < num_pdus; ++i) {
            free(pdus[i]);
        }
        free(pdus);
        return NULL;
    }

    // Determine buffer size
    *plaintext_len = ciphertext_len + EVP_CIPHER_block_size(EVP_aes_128_cbc());
    unsigned char *plaintext = malloc(*plaintext_len);
    if (!plaintext) {
        log_message("Memory allocation failed for plaintext.");

        EVP_CIPHER_CTX_free(ctx);
        for (size_t i = 0; i < num_pdus; ++i) {
            free(pdus[i]);
        }
        free(pdus);
        return NULL;
    }

    int len, decrypted_len;

    // Perform decryption
    if (EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len) != 1) {
        log_message("Decryption update failed.");

        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        for (size_t i = 0; i < num_pdus; ++i) {
            free(pdus[i]);
        }
        free(pdus);
        return NULL;
    }
    *plaintext_len = len;

    // Finalize decryption
    if (EVP_DecryptFinal_ex(ctx, plaintext + len, &decrypted_len) != 1) {
        log_message("Decryption finalization failed.");

        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);
        for (size_t i = 0; i < num_pdus; ++i) {
            free(pdus[i]);
        }
        free(pdus);
        return NULL;
    }

    *plaintext_len += decrypted_len;

    log_message("Decryption completed successfully.");

    // Clean up
    EVP_CIPHER_CTX_free(ctx);

    return pdus;
}

void freeNFAPI_CRC_INDICATION_PDU_Ts(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        if (pdus[i]) {
            free(pdus[i]);
        }
    }
    free(pdus);
}
