        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    }

    *error_flag = 0;
    return pdus;
}

void process_pdu_batch(size_t num_pdus) {
    int error_flag = 0;

    pthread_mutex_lock(&batch_mutex);

    NFAPI_CRC_INDICATION_PDU_T* pdus = allocate_pdu_array(num_pdus, &error_flag);

    if (!pdus) {
        error_count++;
        pthread_mutex_unlock(&batch_mutex);
        return;
    }

    successful_pdu_count += num_pdus;

    free(pdus);
    pthread_mutex_unlock(&batch_mutex);

    log_message("Batch processed successfully");
}

void* batch_processor_thread(void* arg) {
    size_t batch_size = *(size_t*)arg;

    // Simulate processing delay
    clock_t start_time = clock();
    while ((double)(clock() - start_time) / CLOCKS_PER_SEC < 1.0) {
        process_pdu_batch(batch_size);
    }

    return NULL;
}

void simulate_batches(size_t batch_sizes[], size_t num_batches) {
    pthread_t threads[MAX_BATCHES];

    for (size_t i = 0; i < num_batches; ++i) {
        pthread_create(&threads[i], NULL, batch_processor_thread, &batch_sizes[i]);
    }

    for (size_t i = 0; i < num_batches; ++i) {
        pthread_join(threads[i], NULL);
    }

