```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *payload;
    size_t length;
    time_t timestamp;
} DataPacket;

typedef struct Node {
    DataPacket packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int packet_count;
} PacketList;

// Initialize the dynamic array of DataPackets
PacketList* create_packet_list() {
    PacketList* list = (PacketList*)malloc(sizeof(PacketList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->packet_count = 0;

    // External logging initialization
    printf("Logging service initialized.\n");

    return list;
}

// Clean up the PacketList and free resources
void destroy_packet_list(PacketList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *tmp;

    while (current != NULL) {
        tmp = current;
        current = current->next;
        free(tmp->packet.payload);
        free(tmp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);

    // External logging for cleanup
    printf("Packet list destroyed.\n");
}

// Add or update a DataPacket in the list
void add_or_update_packet(PacketList* list, const char *payload, size_t length, time_t timestamp) {
    if (!list || !payload || length == 0) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->packet.timestamp == timestamp) {
            free(current->packet.payload);
            current->packet.payload = malloc(length);
            if (!current->packet.payload) {
                pthread_mutex_unlock(&list->lock);
                printf("Memory allocation failed.\n");
                return;
            }
            memcpy(current->packet.payload, payload, length);
            current->packet.length = length;
            // Log update
            printf("Packet updated at timestamp %ld.\n", timestamp);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        printf("Memory allocation failed for new node.\n");
        return;
    }

    new_node->packet.payload = malloc(length);
    if (!new_node->packet.payload) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        printf("Memory allocation failed for payload.\n");
        return;
    }

    memcpy(new_node->packet.payload, payload, length);
    new_node->packet.length = length;
    new_node->packet.timestamp = timestamp;
    new_node->next = list->head;
    list->head = new_node;

    // Log addition
    printf("Packet added with timestamp %ld.\n", timestamp);

    pthread_mutex_unlock(&list->lock);
}

// Retrieve a DataPacket by timestamp
DataPacket* get_packet_by_timestamp(PacketList* list, time_t timestamp) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->packet.timestamp == timestamp) {
            DataPacket* packet = &current->packet;
            pthread_mutex_unlock(&list->lock);
            return packet;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    // Log retrieval failure
    printf("No packet found for timestamp %ld.\n", timestamp);
    return NULL;
}

int main() {
    PacketList* list = create_packet_list();

    if (!list) {
        fprintf(stderr, "Failed to initialize packet list.\n");
        return EXIT_FAILURE;
    }

    add_or_update_packet(list, "Data1", 5, time(NULL));
    DataPacket* packet = get_packet_by_timestamp(list, time(NULL));

    if (packet != NULL) {
        printf("Retrieved Packet: %.*s\n", (int)packet->length, packet->payload);
    }

    destroy_packet_list(list);

    return EXIT_SUCCESS;
}
```

