        free(pool->blocks);
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->used_blocks < pool->total_blocks) {
        void *block = ((char*)pool->blocks) + (pool->used_blocks++ * pool->block_size);
        pthread_mutex_unlock(&pool->mutex);
        return (NFAPI_CRC_INDICATION_PDU_T*)block;
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL;  // Pool exhausted
}

void generate_pdus(int N, int M, MemoryPool* pool) {
    if (N <= 0 || N > MAX_USERS || M <= 0 || M > MAX_PDUS_PER_USER) {
        log_message("Warning: Invalid input parameters for users or PDUs per user.");
        return;
    }

