    for (int i = 0; i < N; ++i) {
        int current_m = M;
        while (current_m > 0) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu_from_pool(pool);
            if (!pdu) {
                log_message("Warning: Memory pool exhausted, reducing PDU instances.");
                --current_m; // Try to generate fewer PDUs until memory is available
                continue;
            }

            pdu->RX_UE_INFORMATION_TAG = rand() % 65536;
            pdu->RNTI = rand() % 65536;
            pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

            log_message("Success: PDU allocated and populated.");
            --current_m;
        }
    }

    // Regularly log memory pool status
    pthread_mutex_lock(&pool->mutex);
    log_message("Info: Memory pool status - Used blocks:");
    printf("%zu/%zu\n", pool->used_blocks, pool->total_blocks);  // Print to a log if needed.
    pthread_mutex_unlock(&pool->mutex);
}

int main() {
    const size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    const size_t total_blocks = MAX_USERS * MAX_PDUS_PER_USER;

    MemoryPool* pool = create_memory_pool(block_size, total_blocks);

    // Example usage
    generate_pdus(10, 20, pool);  // Adjust N and M as necessary

    free_memory_pool(pool);
    return 0;
}
