// Simulate a memory pool with global allocation
static NFAPI_RX_FRAME_PDU_T *memory_pool[POOL_SIZE];
static pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
static int pool_index = 0;

