// Function to allocate a block from the memory pool safely
ErrorCode allocate_memory(NFAPI_RX_FRAME_PDU_T **pdu, size_t count) {
    pthread_mutex_lock(&pool_lock);

    if (pool_index + count > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        log_message("Memory pool exhausted");
        return ERROR_MEMORY_ALLOCATION;
    }

    *pdu = &memory_pool[pool_index];
    memset(*pdu, 0, sizeof(NFAPI_RX_FRAME_PDU_T) * count);
    memcpy(memory_pool + pool_index, *pdu, sizeof(NFAPI_RX_FRAME_PDU_T) * count);
    pool_index += count;

    pthread_mutex_unlock(&pool_lock);
    return SUCCESS;
}

ErrorCode generate_pdus(int N, int M) {
