                    memory_pool[pool_index + pdu].phy_rx_frame_info.signal_quality_metric =
                        rand() % 100; // Example dynamic assignment
                }

                break;
            } else {
                log_message("Fallback: Memory pool exhausted, retrying...");
                size_t fallback_count = M / 2 > 0 ? M / 2 : 1;

                if (allocate_memory(&memory_pool[pool_index], fallback_count) != SUCCESS) {
                    log_message("Critical error: Unable to allocate even minimal memory");
                    return ERROR_MEMORY_ALLOCATION;
                }

                // Assign values to the structures, example assignments:
                for (int pdu = 0; pdu < fallback_count; ++pdu) {
                    snprintf(memory_pool[pool_index + pdu].RX_UE_INFORMATION_TAG,
                             sizeof(memory_pool[pool_index + pdu].RX_UE_INFORMATION_TAG),
                             "User%d_PDU%d", user, pdu);

