                    memory_pool[pool_index + pdu].phy_rx_frame_info.signal_quality_metric =
                        rand() % 100; // Example dynamic assignment
                }

                M -= fallback_count; // Reduce the number of required PDUs for this user
            }
        }

        pool_index += M;
    }

    return SUCCESS;
}

