bool insert_at_position(List* list, NFAPI_CRC_INDICATION_PDU_T* pdu_data, size_t position) {
    if (position > list->size || list->size >= MAX_LIST_SIZE) return false;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return false;
    new_node->pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node->pdu) {
        free(new_node);
        return false;
    }
    *new_node->pdu = *pdu_data;

    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    for (size_t i = 0; i < position && current != NULL; i++) {
        current = current->next;
    }

    if (!current) { // Insert at end
        new_node->prev = list->tail;
        if (list->tail) {
            list->tail->next = new_node;
        } else {
            list->head = new_node;
        }
        list->tail = new_node;
    } else { // Insert before current
        new_node->next = current;
        new_node->prev = current->prev;
        if (current->prev) {
            current->prev->next = new_node;
        } else {
            list->head = new_node;
        }
        current->prev = new_node;
    }

    list->size++;
    pthread_rwlock_unlock(&list->lock);
    return true;
}

// Forward iteration
void iterate_forward(List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current) {
        func(current->pdu);
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Reverse iteration
void iterate_reverse(List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->tail;
    while (current) {
        func(current->pdu);
        current = current->prev;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Update CRC flags
void update_crc_flags(List* list, bool (*condition)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (condition(current->pdu)) {
            // Update CRC flag here
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Clean up the list
void free_list(List* list) {
    pthread_rwlock_wrlock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->pdu);
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    pthread_rwlock_unlock(&list->lock);
    pthread_rwlock_destroy(&list->lock);
}
