// Define the network event log entry structure
typedef struct LogEntry {
    time_t timestamp;
    char eventType[16];
    int sourceID;
    size_t messageSize;
    char *message;
    struct LogEntry *next;
} LogEntry;

// Define a linked list to manage dynamic entries
typedef struct {
    LogEntry *head;
    pthread_mutex_t lock;
} LogManager;

LogManager logManager = {NULL, PTHREAD_MUTEX_INITIALIZER};

// Function to allocate memory with error handling
void* safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Add a new log entry
void addLogEntry(time_t timestamp, const char *eventType, int sourceID, const char *message) {
    pthread_mutex_lock(&logManager.lock);

    LogEntry *newEntry = safeMalloc(sizeof(LogEntry));
    newEntry->timestamp = timestamp;
    strncpy(newEntry->eventType, eventType, sizeof(newEntry->eventType) - 1);
    newEntry->sourceID = sourceID;
    newEntry->messageSize = strlen(message) + 1;
    newEntry->message = safeMalloc(newEntry->messageSize);
    strcpy(newEntry->message, message);

    // Insert at the head for O(1) insertion time
    newEntry->next = logManager.head;
    logManager.head = newEntry;

    pthread_mutex_unlock(&logManager.lock);
}

// Remove a log entry by timestamp and sourceID
void removeLogEntry(time_t timestamp, int sourceID) {
    pthread_mutex_lock(&logManager.lock);

    LogEntry *current = logManager.head;
    LogEntry *prev = NULL;

    while (current != NULL) {
        if (current->timestamp == timestamp && current->sourceID == sourceID) {
            if (prev == NULL) {
                logManager.head = current->next;
            } else {
                prev->next = current->next;
            }

            free(current->message);
            free(current);
            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&logManager.lock);
}

// Retrieve a log entry by index
LogEntry* getLogEntryByIndex(int index) {
    pthread_mutex_lock(&logManager.lock);

    LogEntry *current = logManager.head;
    int currentIndex = 0;

    while (current != NULL && currentIndex < index) {
        current = current->next;
        currentIndex++;
    }

    pthread_mutex_unlock(&logManager.lock);
    return current;
}

// Compress old entries older than a specified duration
void compressOldEntries(time_t compressionThreshold) {
    pthread_mutex_lock(&logManager.lock);

    LogEntry *current = logManager.head;
    while (current != NULL) {
        if (difftime(current->timestamp, time(NULL)) > compressionThreshold) {
            // Simple example: just mark as compressed by truncating the message
            char *compressedMessage = safeMalloc(10);  // Compressed to "COMPRESSED"
            strcpy(compressedMessage, "COMPRESSED");
            free(current->message);
            current->message = compressedMessage;
            current->messageSize = strlen("COMPRESSED") + 1;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&logManager.lock);
}

// Function to clear all entries (for simplicity)
void clearLogEntries() {
    pthread_mutex_lock(&logManager.lock);

    LogEntry *current = logManager.head;
    while (current != NULL) {
        LogEntry *temp = current;
        current = current->next;

        free(temp->message);
        free(temp);
    }

    logManager.head = NULL;

    pthread_mutex_unlock(&logManager.lock);
}

// Example main function to demonstrate usage
int main() {
    addLogEntry(time(NULL), "INFO", 1, "This is a test message.");

    // Retrieve the first entry and print it
    LogEntry *entry = getLogEntryByIndex(0);
    if (entry) {
        printf("Retrieved Entry: %s\n", entry->message);
    }

    compressOldEntries(3600);  // Compress entries older than an hour

    clearLogEntries();  // Clean up all log entries
    return 0;
}
