NFAPI_CRC_INDICATION_PDU_T** createNficSemaphores(int num_semaphores, int init_values[], sem_t **semaphores, int default_num_semaphores = 10) {
    if (num_semaphores <= 0) {
        num_semaphores = default_num_semaphores;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T** pdu_list = malloc(num_semaphores * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pdu_list) {
        log_message("Memory allocation for NFAPI_CRC_INDICATION_PDU_T pointers failed.");
        return NULL;
    }

    semaphores = malloc(num_semaphores * sizeof(sem_t*));
    if (!semaphores) {
        free(pdu_list);
        log_message("Memory allocation for semaphore pointers failed.");
        return NULL;
    }

    // Seed random number generator
