    for (int i = 0; i < num_semaphores; ++i) {
        semaphores[i] = malloc(sizeof(sem_t));
        if (!semaphores[i]) {
            log_message("Memory allocation for semaphore failed.");
            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(pdu_list[j]);
                sem_destroy(semaphores[j]);
                free(semaphores[j]);
            }
            free(pdu_list);
            free(semaphores);
            return NULL;
        }

        if (sem_init(semaphores[i], 0, init_values[i % num_semaphores]) != 0) {
            log_message("Semaphore initialization failed.");
            // Clean up previously allocated resources
            for (int j = 0; j <= i; ++j) {
                free(pdu_list[j]);
                sem_destroy(semaphores[j]);
                free(semaphores[j]);
            }
            free(pdu_list);
            free(semaphores);
            return NULL;
        }

        pdu_list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu_list[i]) {
            log_message("Memory allocation for NFAPI_CRC_INDICATION_PDU_T structure failed.");
            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(pdu_list[j]);
                sem_destroy(semaphores[j]);
                free(semaphores[j]);
            }
            sem_destroy(semaphores[i]);
            free(semaphores[i]);
            free(pdu_list);
            free(semaphores);
            return NULL;
        }

        // Initialize structure with random values
        pthread_mutex_lock(&mutex);
        pdu_list[i]->crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand() % 65536;
        pdu_list[i]->crc_indication_rel8_tag.RNTI = rand() % 65536;
        pdu_list[i]->CRCFLAG = rand() & 0x01; // Randomly set CRCFLAG
        pthread_mutex_unlock(&mutex);
    }

