    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    INSERTION,
    DELETION,
    UPDATE
} OperationType;

typedef struct {
    time_t timestamp;
    OperationType operation;
    int index;
} OperationLogEntry;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    OperationLogEntry* log;
    size_t log_size;
    size_t log_capacity;
} CRCArrayManager;

void init_crc_array_manager(CRCArrayManager* manager, size_t initial_capacity) {
    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
    manager->log = (OperationLogEntry*)malloc(10 * sizeof(OperationLogEntry)); // Initial log capacity
    manager->log_size = 0;
    manager->log_capacity = 10;
}

void free_crc_array_manager(CRCArrayManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->array);
    free(manager->log);
}

int resize_array_if_needed(CRCArrayManager* manager, size_t new_size) {
    if (new_size > manager->capacity) {
        size_t new_capacity = (new_size > manager->capacity * 2) ? manager->capacity * 2 : manager->capacity + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) return -1; // Allocation failed
        manager->array = new_array;
        manager->capacity = new_capacity;
    }
    return 0;
}

int log_operation(CRCArrayManager* manager, OperationType operation, int index) {
    if (manager->log_size >= manager->log_capacity) {
        size_t new_log_capacity = manager->log_capacity * 2;
        OperationLogEntry* new_log = realloc(manager->log, new_log_capacity * sizeof(OperationLogEntry));
        if (!new_log) return -1; // Allocation failed
        manager->log = new_log;
        manager->log_capacity = new_log_capacity;
    }
    time_t now = time(NULL);
    OperationLogEntry entry = {now, operation, index};
    manager->log[manager->log_size++] = entry;
