// Resize the dynamic array when needed
void resizeConfigManager(ConfigManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_Uplink_NRCFG_T *new_configs = (LTE_Uplink_NRCFG_T *)realloc(manager->configs, new_capacity * sizeof(LTE_Uplink_NRCFG_T));
