#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <unistd.h>

#define MAX_DNS_REQUESTS_PER_MINUTE 60
#define LOG_MAX_SIZE 1048576 // 1 MB
#define MAX_HOSTNAMES 100

typedef struct {
    char rnti[16];
    uint8_t rx_ue_information_tag;
    uint8_t crc_indication_rel8_tag;
    int crcflag; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    u_char ip_address[4];
    char hostname[256];
} DNSResolutionResult;

pthread_mutex_t dns_cache_lock = PTHREAD_MUTEX_INITIALIZER;
DNSResolutionResult dns_cache[MAX_HOSTNAMES];
int cache_count = 0;

void rotate_log(const char *log_path) {
    static char archive_dir[] = "archive_logs";
    if (access(archive_dir, F_OK) != 0) mkdir(archive_dir, 0777);

    char current_time[20];
    time_t now = time(NULL);
    strftime(current_time, sizeof(current_time), "%Y%m%d%H%M%S", localtime(&now));

    char archived_log_path[512];
    sprintf(archived_log_path, "%s/%s.log", archive_dir, current_time);

    rename(log_path, archived_log_path);
}

void log_dns_result(const char *log_path, const char *hostname, int success) {
    FILE *log_file = fopen(log_path, "a");
    if (!log_file) return;

    pthread_mutex_lock(&dns_cache_lock); // Lock the file for thread safety
    fseek(log_file, 0, SEEK_END);
    long fsize = ftell(log_file);

    if (fsize >= LOG_MAX_SIZE) {
        rotate_log(log_path);
        log_file = fopen(log_path, "a");
        fseek(log_file, 0, SEEK_END); // Reset to end after rotation
    }

    fprintf(log_file, "DNS Resolution for %s: %s\n", hostname, success ? "Success" : "Failure");
    fflush(log_file);

    if (fsize + strlen(hostname) * 2 > LOG_MAX_SIZE) {
        rotate_log(log_path);
        log_file = fopen(log_path, "a");
    }

    fclose(log_file);
    pthread_mutex_unlock(&dns_cache_lock); // Unlock the file
}

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct sockaddr_in sa;
    struct hostent *host;

    host = gethostbyname(hostname);
    if (host == NULL || host->h_addrtype != AF_INET || host->h_length != sizeof(sa.sin_addr)) {
        return 0; // Resolution failed
    }

    memcpy(ip_address, host->h_addr_list[0], sizeof(sa.sin_addr));
    return 1; // Success
}

int check_cache(const char *hostname, u_char *ip_address) {
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            memcpy(ip_address, dns_cache[i].ip_address, sizeof(u_char) * 4);
            return 1;
        }
    }
    return 0;
}

void add_to_cache(const char *hostname, u_char *ip_address) {
    if (cache_count < MAX_HOSTNAMES) {
        strcpy(dns_cache[cache_count].hostname, hostname);
        memcpy(dns_cache[cache_count].ip_address, ip_address, sizeof(u_char) * 4);
        cache_count++;
    }
}

void generate_nfa_list(NFAPI_CRC_INDICATION_PDU_T **nfa_list, size_t n, const char **hostnames, int host_count, const char *log_path) {
    if (!nfa_list || !hostnames || host_count <= 0 || !log_path) return;

    *nfa_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfa_list) return;

    for (size_t i = 0; i < n; ++i) {
        snprintf((*nfa_list)[i].rnti, sizeof((*nfa_list)[i].rnti), "RNTI_%zu", i);
        (*nfa_list)[i].rx_ue_information_tag = rand() % 256;
        (*nfa_list)[i].crc_indication_rel8_tag = rand() % 256;
        (*nfa_list)[i].crcflag = rand() % 2; // Randomly set to 0 or 1
    }

    time_t last_request_time = 0;

    for (int i = 0; i < host_count; ++i) {
        u_char ip_address[4];

        pthread_mutex_lock(&dns_cache_lock);
        if (!check_cache(hostnames[i], ip_address)) {
            pthread_mutex_unlock(&dns_cache_lock);

            time_t current_time = time(NULL);
            if (difftime(current_time, last_request_time) < 60.0 / MAX_DNS_REQUESTS_PER_MINUTE) {
                usleep(100000); // Wait for sufficient time between requests
            }

            last_request_time = time(NULL);

            int success = resolve_hostname(hostnames[i], ip_address);
            pthread_mutex_lock(&dns_cache_lock); // Lock again to update cache after checking

            log_dns_result(log_path, hostnames[i], success);
            if (success) {
                add_to_cache(hostnames[i], ip_address);
            }
        } else {
            pthread_mutex_unlock(&dns_cache_lock);
        }

        usleep(1000000 / MAX_DNS_REQUESTS_PER_MINUTE); // Enforce a minimal rate limit
    }

    pthread_mutex_unlock(&dns_cache_lock);
}
