#define SUCCESS 0
#define ERROR_MEMORY_ALLOCATION -1
#define ERROR_ID_NOT_FOUND -2
#define ERROR_DUPLICATE_ID -3

static void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

ConfigManager* create_config_manager(size_t initial_capacity) {
    ConfigManager* manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    pthread_mutex_init(&manager->lock, NULL);

    manager->array = (LTE_Uplink_NRCFG_T*)calloc(initial_capacity, sizeof(LTE_Uplink_NRCFG_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;

    return manager;
}

void destroy_config_manager(ConfigManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
    }
}

int add_or_update_configuration(ConfigManager* manager, int id, LTE_UL_CONFIG_T config) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].id == id) {
            if (manager->array[i].finalized) {
                log_error("Cannot update finalized configuration.");
                pthread_mutex_unlock(&manager->lock);
                return ERROR_ID_NOT_FOUND;
            }

            if (++manager->array[i].version > 1) { // Increment version number
                manager->array[i].config = config;
            }

            pthread_mutex_unlock(&manager->lock);
            return SUCCESS;
        }
    }

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        LTE_Uplink_NRCFG_T* new_array = (LTE_Uplink_NRCFG_T*)realloc(manager->array, new_capacity * sizeof(LTE_Uplink_NRCFG_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->lock);
            return ERROR_MEMORY_ALLOCATION;
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    LTE_Uplink_NRCFG_T new_config = { .id = id, .version = 1, .finalized = 0, .config = config };
    manager->array[manager->size++] = new_config;

    pthread_mutex_unlock(&manager->lock);
    return SUCCESS;
}

int remove_configuration(ConfigManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].id == id) {
            memmove(&manager->array[i], &manager->array[i + 1], (manager->size - i - 1) * sizeof(LTE_Uplink_NRCFG_T));
            manager->size--;
            pthread_mutex_unlock(&manager->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    log_error("Configuration ID not found.");
    return ERROR_ID_NOT_FOUND;
}

int finalize_configuration(ConfigManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].id == id && !manager->array[i].finalized) {
            manager->array[i].finalized = 1;
            // Handle dependencies here
            pthread_mutex_unlock(&manager->lock);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    log_error("Configuration ID not found or already finalized.");
    return ERROR_ID_NOT_FOUND;
}

