    int id;
    time_t last_access_time;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    pthread_mutex_t lock;
    size_t current_size;
} LRUCache;

LRUCache cache = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

LTE_Uplink_NRCFG_T* fetch_from_external_system(int id);
void log_event(const char *event);

// Function to initialize the configuration array
LTE_Uplink_NRCFG_T** init_config_array(size_t initial_capacity) {
