}

// Function to resize the dynamic array
LTE_Uplink_NRCFG_T** resize_config_array(LTE_Uplink_NRCFG_T **array, size_t new_capacity, size_t current_size) {
    LTE_Uplink_NRCFG_T **new_array = realloc(array, new_capacity * sizeof(LTE_Uplink_NRCFG_T*));
    if (!new_array) return array; // Handle reallocation failure
    for (size_t i = current_size; i < new_capacity; ++i) {
        new_array[i] = NULL;
    }
    return new_array;
}

// Function to add a new configuration
void add_config(LTE_Uplink_NRCFG_T **array, size_t *capacity, size_t *count, LTE_Uplink_NRCFG_T *config) {
    if (*count >= *capacity) {
        *capacity *= 2;
        array = resize_config_array(array, *capacity, *count);
    }
    array[*count] = malloc(sizeof(LTE_Uplink_NRCFG_T));
    memcpy(array[*count], config, sizeof(LTE_Uplink_NRCFG_T));
    (*count)++;
}

// Function to update a configuration
void update_config(LTE_Uplink_NRCFG_T **array, size_t count, int id, LTE_Uplink_NRCFG_T *new_config) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i] && array[i]->cc_config.id == id) {
            memcpy(array[i], new_config, sizeof(LTE_Uplink_NRCFG_T));
            log_event("Configuration updated.");
            return;
        }
    }
}

// Function to remove a configuration
void remove_config(LTE_Uplink_NRCFG_T **array, size_t *count, int id) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i] && array[i]->cc_config.id == id) {
            free(array[i]);
            memmove(&array[i], &array[i + 1], (*count - i - 1) * sizeof(LTE_Uplink_NRCFG_T*));
            (*count)--;
            log_event("Configuration removed.");
            return;
        }
    }
}

// Cache management functions
void cache_init() {
    pthread_mutex_lock(&cache.lock);
    cache.head = NULL;
    cache.current_size = 0;
    pthread_mutex_unlock(&cache.lock);
}

LTE_Uplink_NRCFG_T* cache_get(int id) {
    pthread_mutex_lock(&cache.lock);

    CacheNode *current = cache.head;
    while (current) {
        if (current->id == id) {
            current->last_access_time = time(NULL);
            pthread_mutex_unlock(&cache.lock);
            return &current->config;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache.lock);
    return NULL;
}

void cache_put(LTE_Uplink_NRCFG_T *config) {
    pthread_mutex_lock(&cache.lock);

    if (cache.current_size >= MAX_CACHE_SIZE) {
        // Evict the least recently used item
        CacheNode *lru = cache.head;
        CacheNode *prev = NULL;

        for (CacheNode *current = cache.head; current && current->next; current = current->next) {
            if (current->last_access_time < lru->last_access_time) {
                lru = current;
                prev = current;
            }
        }

        if (lru == cache.head) {
            cache.head = cache.head->next;
        } else if (prev) {
            prev->next = lru->next;
        }

        free(lru);
        cache.current_size--;
    }

    CacheNode *new_node = malloc(sizeof(CacheNode));
    new_node->config = *config;
    new_node->id = config->cc_config.id;
    new_node->last_access_time = time(NULL);
    new_node->next = cache.head;
    cache.head = new_node;
    cache.current_size++;

    pthread_mutex_unlock(&cache.lock);
}

void log_event(const char *event) {
