    pthread_rwlock_wrlock(&list->lock);

    if (position == 0) {
        new_node->next = list->head;
        new_node->prev = NULL;
        if (list->head) list->head->prev = new_node;
        else list->tail = new_node;
        list->head = new_node;
    } else if (position == list->size + 1) {
        new_node->next = NULL;
        new_node->prev = list->tail;
        if (list->tail) list->tail->next = new_node;
        else list->head = new_node;
        list->tail = new_node;
    } else {
        Node* current = list->head;
        for (size_t i = 0; i < position - 1; ++i) {
            current = current->next;
        }
        new_node->next = current->next;
        new_node->prev = current;
        if (current->next) current->next->prev = new_node;
        current->next = new_node;
    }

    list->size++;
    pthread_rwlock_unlock(&list->lock);
    return true;
}

void update_crc_flags(List* list, bool condition) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (condition) {
            current->data.CRCFLAG = rand() % 2 == 0; // Randomly set CRCFLAG
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

void iterate_forward(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(&(current->data));
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

void iterate_reverse(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list) return;

    pthread_rwlock_rdlock(&list->lock);

    Node* current = list->tail;
    while (current) {
        callback(&(current->data));
        current = current->prev;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Example usage
void print_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
}

int main() {
    List* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create list.\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() };
        if (!insert_at_position(list, list->size, pdu)) {
            fprintf(stderr, "Failed to insert element at position %zu.\n", i);
        }
    }

    update_crc_flags(list, true);

    printf("Iterating forward:\n");
    iterate_forward(list, print_pdu);

    printf("\nIterating reverse:\n");
    iterate_reverse(list, print_pdu);

    destroy_list(list);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_rwlock_t` for read-write locking to ensure thread-safe operations.
- **Memory Management**: Handles memory allocation failures gracefully and ensures no memory leaks.
- **Insertion and Iteration**: Supports insertion at arbitrary positions and iteration in both forward and reverse orders.
- **Concurrency**: Minimizes lock granularity by using read locks for iteration and write locks for modifications.
- **Error Handling**: Provides error handling for invalid operations and memory allocation failures.']

