    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;

int allocate_nfaapi_pdu_array(int N, NFAPI_CRC_INDICATION_PDU_T** out_array) {
    if (N <= 0 || N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Invalid number of elements. Must be between 1 and %d.\n", MAX_ELEMENTS);
        return -1;
    }

    pthread_mutex_lock(&lock);

    // Clean up existing resources
    free(pdu_array);
    pdu_array = NULL;

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return -2;
    }

    // Initialize the array
    for (int i = 0; i < N; ++i) {
        new_array[i].rx_ue_information_tag.RNTI = rand() % 65536;

        // Ensure unique RNTIs
        for (int j = 0; j < i; ++j) {
            if (new_array[j].rx_ue_information_tag.RNTI == new_array[i].rx_ue_information_tag.RNTI) {
                fprintf(stderr, "Error: Duplicate RNTI detected.\n");
                free(new_array);
                pdu_array = NULL;
                pthread_mutex_unlock(&lock);
                return -3;
            }
        }

        // Set a random CRCFLAG
        new_array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set to 0 or 1
    }

    pdu_array = new_array;
    *out_array = pdu_array;

    pthread_mutex_unlock(&lock);
    return 0;
}

void deallocate_nfaapi_pdu_array() {
    pthread_mutex_lock(&lock);

    if (pdu_array) {
        free(pdu_array);
        pdu_array = NULL;
    }

    pthread_mutex_unlock(&lock);
}
