["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MAC_ADDRESSES 128

typedef struct {
    char mac_address[18]; // MAC addresses are typically in the format XX:XX:XX:XX:XX:XX
} MacAddress;

typedef struct NIMObject {
    int interface_id;
    time_t config_timestamp;
    MacAddress mac_addresses[MAX_MAC_ADDRESSES];
    size_t mac_count;
    pthread_mutex_t lock;
} NIMObject;

typedef struct {
    NIMObject* nim_objects;
    size_t count;
    pthread_rwlock_t rwlock;
} NimManager;

// Function to find a MAC address within an object
int find_mac_address(NIMObject* nim, const char* mac) {
    for (size_t i = 0; i < nim->mac_count; ++i) {
        if (strcmp(nim->mac_addresses[i].mac_address, mac) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to add a MAC address
int add_mac_address(NIMManager* manager, int interface_id, const char* mac) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        NIMObject* nim = &manager->nim_objects[i];

        if (nim->interface_id == interface_id) {
            pthread_mutex_lock(&nim->lock);

            if (!find_mac_address(nim, mac)) {
                if (nim->mac_count < MAX_MAC_ADDRESSES) {
                    strncpy(nim->mac_addresses[nim->mac_count].mac_address, mac, 17);
                    nim->mac_addresses[nim->mac_count].mac_address[17] = '\0';
                    ++nim->mac_count;
                    nim->config_timestamp = time(NULL); // Update timestamp
                }
                pthread_mutex_unlock(&nim->lock);
                pthread_rwlock_unlock(&manager->rwlock);
                return 1; // Success
            }

            pthread_mutex_unlock(&nim->lock);
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Interface ID not found or MAC already exists
}

// Function to remove a MAC address
int remove_mac_address(NIMManager* manager, int interface_id, const char* mac) {
    pthread_rwlock_wrlock(&manager->rwlock);

    for (size_t i = 0; i < manager->count; ++i) {
        NIMObject* nim = &manager->nim_objects[i];

        if (nim->interface_id == interface_id) {
            pthread_mutex_lock(&nim->lock);

            for (size_t j = 0; j < nim->mac_count; ++j) {
                if (strcmp(nim->mac_addresses[j].mac_address, mac) == 0) {
                    memmove(&nim->mac_addresses[j], &nim->mac_addresses[j + 1],
                            (nim->mac_count - j - 1) * sizeof(MacAddress));
                    --nim->mac_count;
                    pthread_mutex_unlock(&nim->lock);
                    pthread_rwlock_unlock(&manager->rwlock);
                    return 1; // Success
                }
            }

            pthread_mutex_unlock(&nim->lock);
        }
    }

    pthread_rwlock_unlock(&manager->rwlock);
    return 0; // Interface ID not found or MAC not found
}

// Function to validate timestamps
int validate_timestamps(NIMManager* manager) {
    pthread_rwlock_rdlock(&manager->rwlock);

    time_t first_timestamp = -1;
    int valid = 1;

    for (size_t i = 0; i < manager->count && valid; ++i) {
        NIMObject* nim = &manager->nim_objects[i];

        if (first_timestamp == -1) {
            first_timestamp = nim->config_timestamp;
        } else if (first_timestamp != nim->config_timestamp) {
