    }

    manager->count = initial_capacity;
    pthread_rwlock_init(&manager->rwlock, NULL);

    return manager;
}

// Function to free the NIM manager
void free_nim_manager(NimManager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->count; ++i) {
            pthread_mutex_destroy(&manager->nim_objects[i].lock);
        }

        pthread_rwlock_destroy(&manager->rwlock);
        free(manager->nim_objects);
        free(manager);
    }
}
