    size_t successful_allocations;
    size_t failed_memory_allocations;
    size_t rnti_conflicts;
} AllocationResult;

bool is_unique_rnti(int rnti, NFAPI_CRC_INDICATION_PDU_T* pdu_list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pdu_list[i].RNTI == rnti) {
            return false;
        }
    }
    return true;
}

AllocationResult allocate_pdu_list(size_t M) {
    AllocationResult result = {NULL, 0, 0, 0};
    result.pdu_list = malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!result.pdu_list) {
        result.failed_memory_allocations = M;
        return result;
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < M; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &result.pdu_list[i];

        int rnti;
        bool valid_rnti = false;

        while (!valid_rnti) {
            rnti = rand() % (MAX_RNTI + 1);
            if (is_unique_rnti(rnti, result.pdu_list, i)) {
