#define MAX_MAC_ADDRESSES 256

typedef struct {
    char mac_address[18]; // MAC addresses are 17 characters + null terminator
} MacAddress;

typedef struct NIMObject {
    int id;
    time_t config_timestamp;
    atomic_uint num_macs; // Number of associated MAC addresses
    MacAddress *mac_addresses; // Dynamic array of MAC addresses
    pthread_mutex_t lock; // Mutex for fine-grained locking
} NIMObject;

// Function prototypes
int add_mac_address(NIMObject *nim, const char *mac);
void remove_mac_address(NIMObject *nim, const char *mac);
int validate_mac_address(const char *mac);
time_t get_current_timestamp();
void update_config_timestamp(NIMObject *nim);

// Initialize a NIM object
NIMObject* create_nim_object(int id) {
    NIMObject *nim = (NIMObject *)malloc(sizeof(NIMObject));
    if (!nim) return NULL;

    nim->id = id;
    nim->config_timestamp = get_current_timestamp();
    atomic_store(&nim->num_macs, 0);
    nim->mac_addresses = (MacAddress*)calloc(MAX_MAC_ADDRESSES, sizeof(MacAddress));
    pthread_mutex_init(&nim->lock, NULL);

    return nim;
}

// Validate a MAC address format
int validate_mac_address(const char *mac) {
    // Basic validation for MAC address format (e.g., XX:XX:XX:XX:XX:XX)
    if (strlen(mac) != 17) return 0;
    for (int i = 0; i < 17; ++i) {
        if ((i % 3 == 2 && mac[i] != ':') ||
            (i % 3 != 2 && !isxdigit(mac[i]))) {
            return 0;
        }
    }
    return 1;
}

// Get the current timestamp
time_t get_current_timestamp() {
    return time(NULL);
}

// Update config timestamp if necessary
void update_config_timestamp(NIMObject *nim) {
    time_t new_timestamp = get_current_timestamp();
    pthread_mutex_lock(&nim->lock);
    if (new_timestamp > nim->config_timestamp) {
        nim->config_timestamp = new_timestamp;
    }
    pthread_mutex_unlock(&nim->lock);
}

// Add a MAC address to the NIM object
int add_mac_address(NIMObject *nim, const char *mac) {
    if (!validate_mac_address(mac)) return -1;

    pthread_mutex_lock(&nim->lock);

    for (uint32_t i = 0; i < atomic_load(&nim->num_macs); ++i) {
        if (strcmp(nim->mac_addresses[i].mac_address, mac) == 0) {
            pthread_mutex_unlock(&nim->lock);
            return -2; // Duplicate MAC address
        }
    }

    if (atomic_load(&nim->num_macs) >= MAX_MAC_ADDRESSES) {
        pthread_mutex_unlock(&nim->lock);
        return -3; // Overflow
    }

    strncpy(nim->mac_addresses[atomic_fetch_add(&nim->num_macs, 1)].mac_address, mac, sizeof(MacAddress));
    update_config_timestamp(nim);

    pthread_mutex_unlock(&nim->lock);
    return 0;
}

// Remove a MAC address from the NIM object
void remove_mac_address(NIMObject *nim, const char *mac) {
    pthread_mutex_lock(&nim->lock);

    for (uint32_t i = 0; i < atomic_load(&nim->num_macs); ++i) {
        if (strcmp(nim->mac_addresses[i].mac_address, mac) == 0) {
            memmove(&nim->mac_addresses[i], &nim->mac_addresses[i + 1],
                    sizeof(MacAddress) * (atomic_fetch_sub(&nim->num_macs, 1) - i));
            break;
        }
    }

    pthread_mutex_unlock(&nim->lock);
}

// Example logging function
void log_event(const char *message) {
    printf("[LOG] %s\n", message);
}

int main() {
    NIMObject *nim = create_nim_object(1);

    add_mac_address(nim, "00:11:22:33:44:55");
    add_mac_address(nim, "66:77:88:99:AA:BB");

    log_event("MAC addresses added successfully.");

    remove_mac_address(nim, "00:11:22:33:44:55");

    free(nim->mac_addresses);
    pthread_mutex_destroy(&nim->lock);
    free(nim);

    return 0;
}
