#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MAC_ADDRESSES 128

typedef struct {
    char mac_address[18]; // Format: XX:XX:XX:XX:XX:XX
} MACAddress;

typedef struct NIMObject {
    int interface_id;
    time_t configuration_timestamp;
    MACAddress *mac_addresses;
    size_t num_mac_addresses;
    pthread_mutex_t lock; // Mutex for thread safety
} NIMObject;

// Function to create a new NIM Object
NIMObject* nim_object_create(int id) {
    NIMObject *nim = (NIMObject*)malloc(sizeof(NIMObject));
    if (!nim) return NULL;

    nim->interface_id = id;
    time(&nim->configuration_timestamp);
    nim->num_mac_addresses = 0;
    nim->mac_addresses = (MACAddress*)calloc(MAX_MAC_ADDRESSES, sizeof(MACAddress));
    pthread_mutex_init(&nim->lock, NULL);

    return nim;
}

// Function to add a MAC address
int nim_object_add_mac_address(NIMObject *nim, const char *mac) {
    if (!nim || !mac) return -1;

    pthread_mutex_lock(&nim->lock);

    for (size_t i = 0; i < nim->num_mac_addresses; ++i) {
        if (strcmp(nim->mac_addresses[i].mac_address, mac) == 0) {
            pthread_mutex_unlock(&nim->lock);
            return -1; // Duplicate MAC address
        }
    }

    if (nim->num_mac_addresses >= MAX_MAC_ADDRESSES) {
        pthread_mutex_unlock(&nim->lock);
        return -2; // No space for more MAC addresses
    }

    strncpy(nim->mac_addresses[nim->num_mac_addresses].mac_address, mac, 17);
    nim->mac_addresses[nim->num_mac_addresses].mac_address[17] = '\0';
    time(&nim->configuration_timestamp); // Update timestamp

    ++nim->num_mac_addresses;

    pthread_mutex_unlock(&nim->lock);
    return 0;
}

// Function to remove a MAC address
int nim_object_remove_mac_address(NIMObject *nim, const char *mac) {
    if (!nim || !mac) return -1;

    pthread_mutex_lock(&nim->lock);

    for (size_t i = 0; i < nim->num_mac_addresses; ++i) {
        if (strcmp(nim->mac_addresses[i].mac_address, mac) == 0) {
            memmove(&nim->mac_addresses[i], &nim->mac_addresses[i + 1],
                    (--nim->num_mac_addresses - i) * sizeof(MACAddress));
            time(&nim->configuration_timestamp); // Update timestamp
            pthread_mutex_unlock(&nim->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&nim->lock);
    return -1; // MAC address not found
}

// Function to validate consistency of timestamps across NIM objects
int validate_nim_object_timestamps(NIMObject **nims, size_t num_nims) {
    if (!nims || !num_nims) return -1;

    time_t reference_time = nims[0]->configuration_timestamp;

    for (size_t i = 1; i < num_nims; ++i) {
        if (abs((long)(reference_time - nims[i]->configuration_timestamp)) > 60) { // e.g., 60 seconds tolerance
            return -2; // Inconsistent timestamps found
        }
    }

    return 0;
}

// Function to clean up a NIM Object
void nim_object_destroy(NIMObject *nim) {
    if (nim) {
        pthread_mutex_lock(&nim->lock);
        free(nim->mac_addresses);
        pthread_mutex_unlock(&nim->lock);

        pthread_mutex_destroy(&nim->lock);
        free(nim);
    }
}

// Example function to handle logging
void log_message(const char *message) {
    // Implement logging functionality here, ensuring it doesn't interfere with performance.
    printf("%s\n", message);  // Simple console logging for illustration purposes
}

int main() {
    NIMObject *nim1 = nim_object_create(1);
    if (nim1) {
        nim_object_add_mac_address(nim1, "00:11:22:33:44:55");
        log_message("MAC address added successfully.");
    }

    // Continue with other operations...

    nim_object_destroy(nim1);

    return 0;
}
```

This code provides a basic structure for managing Network Interface Management (NIM) objects with concurrent access considerations, allowing adding and removing MAC addresses while ensuring thread safety. The validation function checks the consistency of timestamps across NIM objects within a specified tolerance. Additionally, logging is integrated to facilitate debugging without compromising performance.']

