#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INTERFACES 10000

typedef struct {
    char interface_id[32];
    time_t timestamp;
    int status; // 1 for operational, 0 for down
} InterfaceStatus;

typedef struct Node {
    InterfaceStatus data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
} StatusList;

void init_status_list(StatusList* list) {
    list->head = NULL;
    list->count = 0;
}

Node* create_node(const char* id, time_t ts, int status) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    strncpy(new_node->data.interface_id, id, sizeof(new_node->data.interface_id) - 1);
    new_node->data.timestamp = ts;
    new_node->data.status = status;
    new_node->next = NULL;

    return new_node;
}

void add_interface(StatusList* list, const char* id, int status) {
    time_t current_time = time(NULL);
    Node* new_node = create_node(id, current_time, status);

    if (!new_node) return;

    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

void remove_interface(StatusList* list, const char* id) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->data.interface_id, id) == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->count--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

InterfaceStatus* query_interface(StatusList* list, const char* id) {
    Node* current = list->head;

    while (current != NULL) {
        if (strcmp(current->data.interface_id, id) == 0) {
            return &(current->data);
        }
        current = current->next;
    }

    return NULL;
}

void update_interface_status(StatusList* list, const char* id, int status) {
    InterfaceStatus* interface = query_interface(list, id);

    if (interface) {
        interface->status = status;
        interface->timestamp = time(NULL);
    }
}

void clear_log_files() {
    // Implement log file clearing logic here
}

int execute_command(const char* command) {
    clear_log_files();

    FILE *fp = popen(command, "r");
    if (!fp) return -1;

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        printf("%s", buffer);
    }

    int status = pclose(fp);
    return WEXITSTATUS(status);
}

void free_status_list(StatusList* list) {
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int main() {
    StatusList status_list;
    init_status_list(&status_list);

    // Example usage
    add_interface(&status_list, "eth0", 1);
    InterfaceStatus* status = query_interface(&status_list, "eth0");
    if (status) {
        printf("Interface: %s, Status: %d\n", status->interface_id, status->status);
    }

    update_interface_status(&status_list, "eth0", 0);

    execute_command("echo 'Executing command...'");

    free_status_list(&status_list);
    return 0;
}
