```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_INTERFACES 10000
#define MIN_INTERFACES 1

typedef struct {
    char interface_id[32];
    time_t timestamp;
    int status; // 0 for down, 1 for up
} InterfaceStatus;

typedef struct {
    InterfaceStatus *pool;
    size_t capacity;
    pthread_mutex_t lock;
} InterfaceList;

InterfaceList* init_interface_list(size_t initial_capacity) {
    if (initial_capacity < MIN_INTERFACES || initial_capacity > MAX_INTERFACES) {
        fprintf(stderr, "Invalid initial capacity\n");
        return NULL;
    }

    InterfaceList *list = malloc(sizeof(InterfaceList));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }

    list->pool = calloc(initial_capacity, sizeof(InterfaceStatus));
    if (!list->pool) {
        perror("Failed to allocate memory for interface pool");
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_interface_list(InterfaceList *list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->pool);
        free(list);
    }
}

int resize_interface_list(InterfaceList *list, size_t new_capacity) {
    if (new_capacity < MIN_INTERFACES || new_capacity > MAX_INTERFACES) {
        fprintf(stderr, "Invalid new capacity\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    InterfaceStatus *new_pool = realloc(list->pool, new_capacity * sizeof(InterfaceStatus));
    if (!new_pool) {
        perror("Failed to resize interface pool");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->capacity = new_capacity;
    list->pool = new_pool;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int populate_interface_list(InterfaceList *list, size_t count) {
    if (count > list->capacity) {
        fprintf(stderr, "Not enough capacity to populate\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < count; ++i) {
        snprintf(list->pool[i].interface_id, sizeof(list->pool[i].interface_id), "Interface_%zu", i);
        list->pool[i].timestamp = time(NULL);
        list->pool[i].status = (i % 2 == 0); // Alternating status for demonstration
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void update_interface_status(InterfaceList *list, const char *interface_id, int new_status) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->capacity; ++i) {
        if (strcmp(list->pool[i].interface_id, interface_id) == 0) {
            list->pool[i].status = new_status;
            list->pool[i].timestamp = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void get_latest_updates(InterfaceList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->capacity; ++i) {
        printf("ID: %s, Timestamp: %ld, Status: %d\n",
               list->pool[i].interface_id,
               list->pool[i].timestamp,
               list->pool[i].status);
    }

    pthread_mutex_unlock(&list->lock);
}

// Example usage
int main() {
    InterfaceList *list = init_interface_list(10);
    if (!list) return EXIT_FAILURE;

    populate_interface_list(list, 10);

    update_interface_status(list, "Interface_0", 1);

    get_latest_updates(list);

    resize_interface_list(list, 20);

    destroy_interface_list(list);

    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Management:** Uses a memory pool for efficient allocation and resizing.
- **Thread Safety:** Utilizes `pthread_mutex_t` to ensure thread safety.
- **Error Handling:** Checks and handles errors during initialization, resizing, and population.
- **Dynamic Scaling:** Supports dynamic resizing of the list within specified limits.
- **Initialization:** Initializes all structures with default values.

This code provides a robust foundation for managing network interface status updates in a concurrent environment.']

