    } crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t pool_size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks);
void *allocate_from_pool(MemoryPool *pool);
void deallocate_to_pool(MemoryPool *pool, void *block);

MemoryPool packet_pool;
MemoryPool crc_indication_pool;

void fetch_base_station_config();
int validate_packet(const LTE_DL_DATA_PACKET *packet);
void log_event(const char *event);

void process_lte_packets(void *arg) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    while (1) { // Simulate continuous processing
        pthread_mutex_lock(&lock);

        // Fetch base station config dynamically
        fetch_base_station_config();

        // Allocate a new packet from the pool
        LTE_DL_DATA_PACKET *packet = allocate_from_pool(&packet_pool);

        if (!packet) {
            log_event("Memory allocation failed for packet");
            continue;
        }

        // Simulate fetching data into the packet
        packet->ue_id = rand() % 1000;
        packet->timestamp = time(NULL);
        packet->seq_num = rand();

        if (validate_packet(packet)) {
            NFAPI_CRC_INDICATION_PDU_T *crc_pdu = allocate_from_pool(&crc_indication_pool);

            if (!crc_pdu) {
                log_event("Memory allocation failed for CRC PDU");
                deallocate_to_pool(&packet_pool, packet);
                continue;
            }

            crc_pdu->rx_ue_info_tag = rand() % 1000;
            crc_pdu->rnti = rand() % 1000;
            crc_pdu->crc_indication_rel8_tag.crc_flag = (rand() % 2);

            // Process the CRC PDU
            deallocate_to_pool(&packet_pool, packet);
            deallocate_to_pool(&crc_indication_pool, crc_pdu);
        } else {
            log_event("Invalid packet detected");
            deallocate_to_pool(&packet_pool, packet);
        }

        pthread_mutex_unlock(&lock);

        // Simulate handling load and adjusting processing rates
        usleep(1000); // Adjust sleep time based on real-time conditions
    }
}

int main() {
    pthread_t threads[10];

    // Initialize memory pools
    packet_pool = *create_memory_pool(sizeof(LTE_DL_DATA_PACKET), POOL_SIZE);
    crc_indication_pool = *create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), POOL_SIZE);

    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, process_lte_packets, NULL);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->head = NULL;
    pool->pool_size = block_size * num_blocks;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < num_blocks; ++i) {
        void *block = malloc(block_size);
        Node *node = malloc(sizeof(Node));
        node->data = block;
        node->next = pool->head;
        pool->head = node;
    }

    return pool;
}

void *allocate_from_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (!pool->head) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    Node *node = pool->head;
    void *block = node->data;
    pool->head = node->next;
    free(node);
    pool->used += sizeof(block);

    pthread_mutex_unlock(&pool->lock);
    return block;
}

void deallocate_to_pool(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);

    Node *node = malloc(sizeof(Node));
    node->data = block;
    node->next = pool->head;
    pool->head = node;
    pool->used -= sizeof(block);

    pthread_mutex_unlock(&pool->lock);
}

void fetch_base_station_config() {
    // Simulate fetching configuration
}

int validate_packet(const LTE_DL_DATA_PACKET *packet) {
    // Placeholder validation logic
    return packet->seq_num % 2 == 0; // Example condition
}

void log_event(const char *event) {
    printf("Log: %s\n", event);
}
