            (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;

    // Optional: shrink the capacity to save memory if the size is less than a quarter of capacity
    if (list->size < list->capacity / 4 && list->capacity > 16) {
