#include <pthread.h>
#include <time.h>

typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_POOL_SIZE 1024

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool global_memory_pool = { .pool = NULL, .pool_size = 0, .used_count = 0, 
                                  .lock = PTHREAD_MUTEX_INITIALIZER };

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(size_t N, unsigned int seed) {
    pthread_mutex_lock(&global_memory_pool.lock);

    if (global_memory_pool.pool == NULL || global_memory_pool.used_count + N > global_memory_pool.pool_size) {
        size_t new_size = global_memory_pool.pool_size ? 2 * global_memory_pool.pool_size : INITIAL_POOL_SIZE;
        while (new_size < global_memory_pool.used_count + N) {
            new_size *= 2;
        }

        if (global_memory_pool.pool != NULL) {
            free(global_memory_pool.pool);
        }

        global_memory_pool.pool = malloc(new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!global_memory_pool.pool) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&global_memory_pool.lock);
            return NULL;
        }

        global_memory_pool.pool_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = &global_memory_pool.pool[global_memory_pool.used_count];
    global_memory_pool.used_count += N;

    srand(seed); // Seed the random number generator for deterministic CRCFLAG values
    for (size_t i = 0; i < N; ++i) {
        result[i].RNTI = rand() % 65536; // Example RNTI assignment
        result[i].tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    pthread_mutex_unlock(&global_memory_pool.lock);
    return result;
}

void free_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t N) {
    if (pdu == NULL) return;

    pthread_mutex_lock(&global_memory_pool.lock);

    global_memory_pool.used_count -= N;
    // Note: We don't actually free individual PDUs; instead, we rely on the larger pool management.

    pthread_mutex_unlock(&global_memory_pool.lock);
}

int main() {
    unsigned int seed = 42;
    size_t N = 10;

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = allocate_pdu(N, seed);
    if (pdu_array != NULL) {
        // Use the pdu_array for processing...

        free_pdu(pdu_array, N);
    }

    return 0;
}
