#define MAX_UNIQUE_RNTI 100

typedef struct {
    int CRCFLAG;
} LTE_UL_BWP_CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
