    LTE_UL_BWP_CRC_INDICATION_REL8_TAG BWP;
    NFAPI_CRC_INDICATION_PDU_T *indication_list;
    size_t indication_count;
} LTE_Uplink_NRCFG_T;

typedef struct {
    LTE_Uplink_NRCFG_T *configs;
    size_t config_count;
    int unique_rnti[MAX_UNIQUE_RNTI];
    size_t unique_rnti_count;
} UplinkConfigManager;

void initialize_manager(UplinkConfigManager *manager) {
    manager->configs = NULL;
    manager->config_count = 0;
    memset(manager->unique_rnti, -1, sizeof(manager->unique_rnti));
    manager->unique_rnti_count = 0;
}

int is_unique_rnti(int rnti, UplinkConfigManager *manager) {
    for (size_t i = 0; i < manager->unique_rnti_count; ++i) {
        if (manager->unique_rnti[i] == rnti) return 0;
    }
    if (manager->unique_rnti_count >= MAX_UNIQUE_RNTI) return 0;
    manager->unique_rnti[manager->unique_rnti_count++] = rnti;
    return 1;
}

void validate_constraints(UplinkConfigManager *manager, NFAPI_CRC_INDICATION_PDU_T *list, size_t count) {
    for (size_t i = 0; i < count - 1; ++i) {
        if (list[i].RNTI == list[i + 1].RNTI) {
            fprintf(stderr, "Error: Consecutive elements with same RNTI\n");
            exit(EXIT_FAILURE);
        }
    }
    for (size_t i = 0; i < count; ++i) {
        if (!is_unique_rnti(list[i].RNTI, manager)) {
            fprintf(stderr, "Error: Exceeded unique RNTI limit\n");
            exit(EXIT_FAILURE);
        }
    }
}

void add_configuration(UplinkConfigManager *manager, LTE_Uplink_NRCFG_T config) {
    validate_constraints(manager, config.indication_list, config.indication_count);

    manager->configs = realloc(manager->configs, sizeof(LTE_Uplink_NRCFG_T) * (manager->config_count + 1));
    if (!manager->configs) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    manager->configs[manager->config_count++] = config;
}

void update_configuration(UplinkConfigManager *manager, size_t index, LTE_Uplink_NRCFG_T new_config) {
    if (index >= manager->config_count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return;
    }
    validate_constraints(manager, new_config.indication_list, new_config.indication_count);
    manager->configs[index] = new_config;
}

void remove_configuration(UplinkConfigManager *manager, size_t index) {
    if (index >= manager->config_count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return;
    }
    free(manager->configs[index].indication_list);
    memmove(&manager->configs[index], &manager->configs[index + 1],
            sizeof(LTE_Uplink_NRCFG_T) * (manager->config_count - index - 1));
    manager->config_count--;
}

void cleanup_manager(UplinkConfigManager *manager) {
    for (size_t i = 0; i < manager->config_count; ++i) {
        free(manager->configs[i].indication_list);
    }
    free(manager->configs);
    manager->configs = NULL;
    manager->config_count = 0;
}

void generate_random_crcflag(LTE_UL_BWP_CRC_INDICATION_REL8_TAG *tag) {
    srand((unsigned int)time(NULL));
    tag->CRCFLAG = rand() % 2;
}

int main() {
    UplinkConfigManager manager;
    initialize_manager(&manager);

    // Example usage
    LTE_Uplink_NRCFG_T config;
    config.indication_count = 3;
    config.indication_list = malloc(config.indication_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < config.indication_count; ++i) {
        config.indication_list[i].RX_UE_INFORMATION_TAG = rand();
        config.indication_list[i].RNTI = rand() % MAX_UNIQUE_RNTI;
        generate_random_crcflag(&config.indication_list[i].CRC_INDICATION_REL8_TAG);
    }

    add_configuration(&manager, config);

    // Cleanup
    cleanup_manager(&manager);

    return 0;
}
