        int crc_flag = rand() % 2;  // Random CRCFLAG (0 or 1)
        if (crc_flag != 0 && crc_flag != 1) {
            free(*array);
            *array = NULL;
            return -1;  // Invalid CRCFLAG
        }

        (*array)[i].crc_tag.CRCFLAG = crc_flag;
    }

    return 0;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure
int add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **array, size_t *size) {
    if (!array || !size) return -1;

    // Reallocate memory in chunks
    *array = realloc(*array, (*size + REALLOC_CHUNK) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) return -1;  // Memory allocation failure

    for (size_t i = *size; i < *size + REALLOC_CHUNK; ++i) {
        (*array)[i].rx_ue_info_tag.RX_UE_INFORMATION_TAG = rand() % 1000;
        (*array)[i].rnti = rand() % 65535;

        int crc_flag = rand() % 2;
        if (crc_flag != 0 && crc_flag != 1) {
            free(*array);
            *array = NULL;
            return -1;  // Invalid CRCFLAG
        }

        (*array)[i].crc_tag.CRCFLAG = crc_flag;
    }

    *size += REALLOC_CHUNK;

    return 0;
}

