int parse_png_file(const char* filepath) {
    FILE *file = fopen(filepath, "rb");
    if (!file) return -1;

    unsigned char header[8];
    fread(header, 1, 8, file);
    fclose(file);

    // Verify PNG signature
    const unsigned char png_signature[] = {0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A};
    if (memcmp(header, png_signature, sizeof(png_signature)) != 0) return -1;

    return 0;
}

void handle_interruptions(PopulationContext* ctx) {
    pthread_mutex_lock(&ctx->lock);
    // Save state to a temporary file or database if necessary
    pthread_mutex_unlock(&ctx->lock);
}

PopulationContext create_population_context() {
    PopulationContext ctx = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
    ctx.list = malloc(LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return ctx;
}

void free_population_context(PopulationContext* ctx) {
