int is_valid_rnti(int rnti, const NFAPI_CRC_INDICATION_PDU_T *prev_pdu) {
    return (rnti != prev_pdu->RNTI && rnti < MAX_RNTI);
}

void populate_list(PopulationContext* ctx) {
    srand(time(NULL));
    int unique_rntis[MAX_RNTI] = {0};
    int unique_count = 0;

    for (size_t i = 0; i < LIST_SIZE; ++i) {
        handle_interruptions(ctx);

        pthread_mutex_lock(&ctx->lock);
        NFAPI_CRC_INDICATION_PDU_T *pdu = &ctx->list[ctx->count];
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000;

        int rnti;
        do {
            rnti = rand() % MAX_RNTI;
        } while (!is_valid_rnti(rnti, i > 0 ? &ctx->list[ctx->count - 1] : NULL));

        if (unique_count < MAX_RNTI && unique_rntis[rnti] == 0) {
            unique_rntis[rnti] = 1;
            ++unique_count;
        }

        pdu->crc_tag.RNTI = rnti;
        pdu->crc_tag.CRCFLAG = rand() % 2;

        ctx->count++;
        pthread_mutex_unlock(&ctx->lock);
    }
}

