typedef struct {
    uint8_t PREAMBLE;  // Example field for preamble
    uint8_t SF;        // Spreading Factor
    uint8_t NCI;       // Network Channel Indicator
    int CRC_FLAG;      // CRC flag, valid or invalid
} PHY_RX_PDU_T;

typedef struct {
    PHY_RX_PDU_T *data;
    size_t capacity;
    size_t count;
} DynamicArray;

#define INITIAL_CAPACITY 10
#define REALLOC_CHUNK_SIZE 5

int validate_pdu(const PHY_RX_PDU_T *pdu) {
    if (pdu->PREAMBLE != expected_preamble_value || pdu->CRC_FLAG == 0)
        return 0; // Invalid PDU
    return 1;     // Valid PDU
}

DynamicArray* create_dynamic_array() {
    DynamicArray *arr = malloc(sizeof(DynamicArray));
    if (!arr) {
        perror("Failed to allocate memory for array structure");
        return NULL;
    }
    arr->capacity = INITIAL_CAPACITY;
    arr->count = 0;
    arr->data = malloc(arr->capacity * sizeof(PHY_RX_PDU_T));
    if (!arr->data) {
        free(arr);
        perror("Failed to allocate memory for data elements");
        return NULL;
    }
    return arr;
}

void destroy_dynamic_array(DynamicArray *arr) {
    if (arr) {
        free(arr->data);
        free(arr);
    }
}

int insert_pdu(DynamicArray *arr, const PHY_RX_PDU_T *pdu) {
    if (!validate_pdu(pdu)) {
        fprintf(stderr, "Invalid PDU insertion attempt\n");
        return 0; // Invalid PDU
    }

    if (arr->count == arr->capacity) {
        size_t new_capacity = arr->capacity + REALLOC_CHUNK_SIZE;
        PHY_RX_PDU_T *new_data = realloc(arr->data, new_capacity * sizeof(PHY_RX_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory for data elements");
            return 0; // Memory allocation failure
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }

    memcpy(&arr->data[arr->count], pdu, sizeof(PHY_RX_PDU_T));
    arr->count++;
    return 1; // Success
}

// Sample expected preamble value for validation
const uint8_t expected_preamble_value = 0xA5;

int main() {
    DynamicArray *array = create_dynamic_array();
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return EXIT_FAILURE;
    }

    PHY_RX_PDU_T pdu1 = {expected_preamble_value, 7, 0x12, 1};
    PHY_RX_PDU_T pdu2 = {0xB5, 7, 0x13, 1}; // Invalid preamble

    if (!insert_pdu(array, &pdu1)) {
        fprintf(stderr, "Failed to insert PDU\n");
    }

    if (insert_pdu(array, &pdu2)) {
        fprintf(stdout, "Inserted invalid PDU by mistake!\n");
    }

    printf("Successfully inserted %zu PDUs.\n", array->count);

    destroy_dynamic_array(array);
    return EXIT_SUCCESS;
}
