#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Value determined by a pattern related to the index.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* items;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST;

void initialize_nfa_crc_list(NFAPI_CRC_LIST* list) {
    list->items = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_nfa_crc_indication(NFAPI_CRC_LIST* list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T new_item = {RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, 0}; // Example pattern: set based on index
    list->items = realloc(list->items, (list->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->items) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failed.
    }

    list->items[list->count] = new_item;
    list->items[list->count].CRCFLAG = (list->count % 2 == 0) ? 1 : 0; // Example pattern
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void remove_nfa_crc_indication(NFAPI_CRC_LIST* list, size_t index) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->mutex);

    memmove(&list->items[index], &list->items[index + 1], 
            (list->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count--;
    list->items = realloc(list->items, list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&list->mutex);
}

void free_nfa_crc_list(NFAPI_CRC_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    free(list->items);
    list->items = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
