```java
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;

public class RequestBuilder {

    public static HttpURLConnection buildRequest(String urlString, boolean disableCertificateValidation) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        if (disableCertificateValidation && url.getProtocol().equals("https")) {
            SSLContext sc;
            try {
                sc = SSLContext.getInstance("TLS");
                sc.init(null, new TrustManager[]{new TrustAllCertificates()}, java.security.SecureRandom.getInstanceStrong());
                connection = (HttpsURLConnection) ((HttpsURLConnection) connection).getSSLSocketFactory(sc.getSocketFactory()).openConnection(url);
            } catch (Exception e) {
                throw new IOException("Failed to disable certificate validation", e);
            }
        }

        // Set headers, timeouts, etc. as needed.
        connection.setRequestMethod("GET");

        return connection;
    }

    public static String generateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte b : messageDigest) {
                String h = Integer.toHexString(0xFF & b);
                if (h.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(h);
            }
            return hexString.toString();

        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static class TrustAllCertificates implements javax.net.ssl.X509TrustManager {
        public void checkClientTrusted(java.security.cert.X509Certificate[] chain, String authType) {}

        public void checkServerTrusted(java.security.cert.X509Certificate[] chain, String authType) {}

        public java.security.cert.X509Certificate[] getAcceptedIssuers() { return null; }
    }

    // Example usage
    public static void main(String[] args) {
        try {
            HttpURLConnection connection = buildRequest("https://example.com", true);
            System.out.println(generateMD5Hash("input string"));

            // Perform further operations on the connection...

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

