void initDynamicList(DynamicList *list, size_t initialCapacity) {
    list->capacity = (initialCapacity > MAX_ENTRIES / 0.9) ? MAX_ENTRIES : (size_t)(initialCapacity / 0.9);
    list->entries = malloc(sizeof(LTE_EUTRA_BER_INFO_T) * list->capacity);
