void resizeDynamicList(DynamicList *list) {
    if (list->count >= list->capacity) {
        size_t newCapacity = (list->capacity < MAX_ENTRIES) ? list->capacity * 2 : MAX_ENTRIES;
        LTE_EUTRA_BER_INFO_T *newEntries = realloc(list->entries, sizeof(LTE_EUTRA_BER_INFO_T) * newCapacity);
        if (newEntries) {
            list->entries = newEntries;
            list->capacity = newCapacity;
        }
    }
}

void compactDynamicList(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    size_t newCount = 0;
    for (size_t i = 0; i < list->count; ++i) {
        if (verifyDataIntegrity(&list->entries[i])) {
            list->entries[newCount++] = list->entries[i];
        }
    }
    list->count = newCount;
    size_t compactedCapacity = (newCount > MAX_ENTRIES / 0.9) ? MAX_ENTRIES : (size_t)(newCount * 1.1);
    if (compactedCapacity < list->capacity) {
        LTE_EUTRA_BER_INFO_T *newEntries = realloc(list->entries, sizeof(LTE_EUTRA_BER_INFO_T) * compactedCapacity);
        if (newEntries) {
            list->entries = newEntries;
            list->capacity = compactedCapacity;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void addEntry(DynamicList *list, const LTE_EUTRA_BER_INFO_T *entry) {
