#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RNTI;
    uint8_t CRCFLAG;
    struct {
        time_t start_timestamp;
        time_t end_timestamp;
    } validity_window;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

void log_operation(const char* operation, int success, const char* message) {
    printf("[%s] Operation: %s, Success: %d, Message: %s\n",
           time(NULL), operation, success, message);
}

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    log_operation("CREATE_LIST", 1, "List created.");
    return list;
}

int add_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_operation("ADD_ELEMENT", 0, "Memory allocation failed.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;

    log_operation("ADD_ELEMENT", 1, "Element added successfully.");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element_by_RNTI(CRCList* list, uint32_t RNTI) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != RNTI) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        log_operation("REMOVE_ELEMENT", 0, "Element not found.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    log_operation("REMOVE_ELEMENT", 1, "Element removed successfully.");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_CRCFLAG(CRCList* list, uint32_t RNTI, uint8_t new_CRCFLAG) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL && current->data.RNTI != RNTI) {
        current = current->next;
    }

    if (current == NULL) {
        log_operation("UPDATE_CRCFLAG", 0, "Element not found.");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    current->data.CRCFLAG = new_CRCFLAG;

    log_operation("UPDATE_CRCFLAG", 1, "CRCFLAG updated successfully.");
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void validate_entries(CRCList* list) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL) {
        if (current_time < current->data.validity_window.start_timestamp ||
            current_time > current->data.validity_window.end_timestamp) {
            log_operation("VALIDATION", 0, "Invalid CRC_INDICATION_REL8_TAG detected.");
        } else {
            log_operation("VALIDATION", 1, "CRC_INDICATION_REL8_TAG is valid.");
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_destroy(&list->lock);
    log_operation("FREE_LIST", 1, "List freed successfully.");
    free(list);
}
