    // Create the directory efficiently and safely
    if (mkdir(directoryName, 0777) != 0 && errno != EEXIST) {
        return -2; // Failed to create directory
    }

    // Set environment variable in a thread-safe manner
    char fullPath[DIRECTORY_MAX_LEN + 20];
    snprintf(fullPath, sizeof(fullPath), "%s/%s", getenv("PWD"), directoryName);

    pthread_mutex_lock(&envVarMutex);
    if (getenv(ENV_VAR_NAME) == NULL) {
        setenv(ENV_VAR_NAME, fullPath, 1);
    }
    pthread_mutex_unlock(&envVarMutex);

    // Allocate memory for the list
    *pduList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
