BER_LIST_T* initialize_ber_list(size_t max_size) {
    if (max_size == 0 || max_size > UINT32_MAX / sizeof(LTE_EUTRA_BER_INFO_T)) {
        log_event("Invalid list size");
        return NULL;
    }

    BER_LIST_T* ber_list = malloc(sizeof(BER_LIST_T));
    if (!ber_list) {
        log_event("Failed to allocate memory for BER list structure");
        return NULL;
    }

    ber_list->entries = calloc(max_size, sizeof(LTE_EUTRA_BER_INFO_T));
    if (!ber_list->entries) {
        free(ber_list);
        log_event("Failed to allocate memory for entries array");
        return NULL;
    }

    pthread_mutex_init(&ber_list->lock, NULL);

    ber_list->count = 0;
    ber_list->capacity = max_size;
    ber_list->successful_allocations = 0;
    ber_list->failed_allocations = 0;
    ber_list->total_memory_consumed = sizeof(BER_LIST_T) + max_size * sizeof(LTE_EUTRA_BER_INFO_T);

    return ber_list;
}

int add_ber_entry(BER_LIST_T* ber_list, PUSCH_GRANT_T pusch_grant, RLC_AM_PDU_T rlc_am_pdu) {
    if (!ber_list || ber_list->count >= ber_list->capacity) {
        log_event("BER list overflow or invalid pointer");
        return -1;
    }

    pthread_mutex_lock(&ber_list->lock);

    LTE_EUTRA_BER_INFO_T* entry = &ber_list->entries[ber_list->count];

    // Verify integrity of data
    if (pusch_grant.grant_id < 0 || rlc_am_pdu.data == NULL) {
        pthread_mutex_unlock(&ber_list->lock);
        log_event("Invalid PUSCH grant or RLC AM PDU");
        return -1;
    }

    entry->pusch_grant = pusch_grant;
    entry->rlc_am_pdu.data = malloc(rlc_am_pdu.length);
    if (!entry->rlc_am_pdu.data) {
        pthread_mutex_unlock(&ber_list->lock);
        ber_list->failed_allocations++;
        log_event("Failed to allocate memory for RLC AM PDU data");
        return -1;
    }

    memcpy(entry->rlc_am_pdu.data, rlc_am_pdu.data, rlc_am_pdu.length);

    entry->rlc_am_pdu.length = rlc_am_pdu.length;

    ber_list->count++;
    ber_list->successful_allocations++;

    pthread_mutex_unlock(&ber_list->lock);
    return 0;
}

void compact_ber_list(BER_LIST_T* ber_list) {
    if (!ber_list) return;

    pthread_mutex_lock(&ber_list->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < ber_list->count; ++i) {
        if (ber_list->entries[i].rlc_am_pdu.data != NULL) { // Example condition
