        } else {
            free(ber_list->entries[i].rlc_am_pdu.data);
        }
    }

    ber_list->count = new_count;

    pthread_mutex_unlock(&ber_list->lock);
}

void report_memory_leaks(BER_LIST_T* ber_list) {
