#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 // Define memory budget in bytes (e.g., 1MB)
#define START_TIMESTAMP 0
#define END_TIMESTAMP 3600 // Example: validity window of 1 hour

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t node_count;
    size_t memory_used;
    FILE* log_file;
} CRCListManager;

CRCListManager* create_list_manager(FILE* log) {
    CRCListManager* manager = (CRCListManager*)malloc(sizeof(CRCListManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->node_count = 0;
    manager->memory_used = sizeof(CRCListManager);
    manager->log_file = log;

    fprintf(log, "List Manager created.\n");
    return manager;
}

void log_message(CRCListManager* manager, const char* message) {
    if (manager && manager->log_file) {
        fprintf(manager->log_file, "%s\n", message);
    }
}

int memory_budget_exceeded(CRCListManager* manager) {
    return manager->memory_used > MAX_MEMORY_BUDGET;
}

void add_element(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T element) {
    if (manager == NULL || memory_budget_exceeded(manager)) {
        log_message(manager, "Memory budget exceeded or invalid manager.");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message(manager, "Failed to allocate memory for a new node.");
        return;
    }

    *new_node = (Node){.data = element, .next = NULL};
    manager->memory_used += sizeof(Node);

    if (manager->head == NULL || manager->node_count == 0) {
        manager->head = new_node;
    } else {
        Node* current = manager->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    manager->node_count++;
    log_message(manager, "Element added successfully.");
}

void remove_element_by_RNTI(CRCListManager* manager, uint16_t RNTI) {
    if (manager == NULL || manager->head == NULL) return;

    Node *current = manager->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (prev == NULL) { // Remove head
                manager->head = current->next;
            } else { 
                prev->next = current->next;
            }

            free(current);
            manager->memory_used -= sizeof(Node);
            manager->node_count--;

            log_message(manager, "Element removed successfully.");
            return;
        }
        prev = current;
        current = current->next;
    }

    log_message(manager, "Element with specified RNTI not found.");
}

void update_CRCFLAG(CRCListManager* manager, uint16_t RNTI, int new_CRCFLAG) {
    if (manager == NULL || manager->head == NULL) return;

    Node *current = manager->head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            current->data.CRCFLAG = new_CRCFLAG;
            log_message(manager, "CRCFLAG updated successfully.");
            return;
        }
        current = current->next;
    }

    log_message(manager, "Element with specified RNTI not found for CRCFLAG update.");
}

void validate_entries(CRCListManager* manager) {
    time_t current_time = time(NULL);
    if (current_time < START_TIMESTAMP || current_time > END_TIMESTAMP) {
        log_message(manager, "Validation skipped: Current time out of validity window.");
        return;
    }

    Node *current = manager->head;
    while (current != NULL) {
        // Example validation logic
        int valid_within_window = 1; // Placeholder for actual validation criteria

        if (!valid_within_window) {
            log_message(manager, "Invalid CRC_INDICATION_REL8_TAG found.");
            remove_element_by_RNTI(manager, current->data.RNTI);
        }
        current = current->next;
    }

    log_message(manager, "Validation completed.");
}

void destroy_list_manager(CRCListManager* manager) {
    if (manager == NULL) return;

    Node *current = manager->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
        manager->memory_used -= sizeof(Node);
    }

    log_message(manager, "List Manager destroyed.");
    free(manager);
}
