    // Implement validation logic for the structure
    return (pdu->RX_UE_INFORMATION_TAG > 0 && pdu->RNTI > 0);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

CRCList* create_crc_list(int capacity) {
    CRCList *list = malloc(sizeof(CRCList));
    if (!list) {
        log_error("Failed to allocate memory for CRCList");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = (capacity > 0 && capacity <= MAX_CAPACITY) ? capacity : MAX_CAPACITY;
    list->size = 0;
    return list;
}

void free_crc_list(CRCList *list) {
    if (!list) return;

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data.payload_info);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_pdu(CRCList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate_structure(pdu)) {
        log_error("Invalid CRC structure");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = *pdu;
    new_node->next = NULL;

    if (list->size < list->capacity) {
        // Add to the front of the list
        new_node->next = list->head;
        list->head = new_node;
    } else {
        // Overwrite the least recently used entry (tail)
        Node *current = list->head;
        Node *prev = NULL;
        while (current->next) {
            prev = current;
            current = current->next;
        }

        if (prev) {
            free(prev->data.payload_info);
            prev->data = new_node->data;
            free(new_node);
        } else {
            // List has only one element
            free(list->head->data.payload_info);
            list->head->data = new_node->data;
            free(new_node);
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Example usage
int main() {
    CRCList *crc_list = create_crc_list(10);

    if (crc_list) {
        NFAPI_CRC_INDICATION_PDU_T pdu_example = {1, 2, 3, malloc(4), 4};

        add_crc_pdu(crc_list, &pdu_example);

        free(pdu_example.payload_info); // Normally handled within the list
        free_crc_list(crc_list);
    }

    return 0;
}
```

