        list->head = new_node;
    }
    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;  // Success
}

// Retrieve an element by RNTI
NFAPI_CRC_INDICATION_PDU_T* get_element(DoublyLinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;  // Not found
}

// Delete an element by RNTI
int delete_element(DoublyLinkedList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (current->prev) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }

            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0;  // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1;  // Error: Not found
}

// Free the list and its elements
void free_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    DoublyLinkedList nfa_list;
    init_list(&nfa_list);

    NFAPI_CRC_INDICATION_PDU_T pdu1 = {100, 1, 200};
    add_element(&nfa_list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T* retrieved_pdu = get_element(&nfa_list, 1);
    if (retrieved_pdu) {
        printf("RNTI: %d, CRCFLAG: %d\n", retrieved_pdu->RNTI, retrieved_pdu->CRCFLAG);
    }

    delete_element(&nfa_list, 1);

    free_list(&nfa_list);
    return 0;
}
```

This implementation includes thread safety through mutexes to ensure data integrity in a concurrent environment. It checks for unique RNTI values before adding new elements and provides basic error handling. The code also uses dynamic memory allocation for nodes, which is crucial for resource management.']

