        exit(EXIT_FAILURE);
    }
    log_message(2, "Dynamic array initialized successfully.");
}

void free_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->lock);
        free(array->array);
        pthread_mutex_unlock(&array->lock);
        pthread_mutex_destroy(&array->lock);
        log_message(1, "Memory deallocated for dynamic array.");
    }
}

int resize_dynamic_array(DynamicArray* array, size_t new_capacity) {
