from collections import deque
import pickle

class NetworkBufferManager:
    def __init__(self):
        self.lock = threading.Lock()
        self.buffer = deque(maxlen=100)
        self.default_theme_dir = "/path/to/default/theme"
        self.fallback_dir = "/path/to/fallback/theme"
        self.network_traffic_log = []
        self.cache_service = {}  # Simulated external cache service
        logging.basicConfig(level=logging.INFO)

    def get_theme_resources(self, theme_name):
        """Fetch theme resources with fallback mechanism."""
        try:
            resources = self._fetch_from_cache(theme_name)
            if not resources:
                raise FileNotFoundError
        except (FileNotFoundError, KeyError) as e:
            logging.error(f"Resources for {theme_name} not found in cache: {e}")
            resources = self._load_fallback_resources(theme_name)

        return resources

    def _fetch_from_cache(self, theme_name):
        """Fetch from local or external cache."""
        with self.lock:
            # Try external cache service first
            if theme_name in self.cache_service:
                return self.cache_service[theme_name]

            # Fallback to local directory
            try:
                file_path = os.path.join(self.default_theme_dir, f"{theme_name}.png")
                with open(file_path, 'rb') as img_file:
                    resources = pickle.load(img_file)
                return resources
            except FileNotFoundError:
                logging.warning(f"Default theme directory unavailable for {theme_name}")
                return None

    def _load_fallback_resources(self, theme_name):
        """Load resources from fallback directory."""
        try:
            file_path = os.path.join(self.fallback_dir, f"{theme_name}.png")
            with open(file_path, 'rb') as img_file:
                resources = pickle.load(img_file)
            logging.info(f"Fetched fallback resources for {theme_name}")
            return resources
        except Exception as e:
            logging.error(f"Error loading fallback resources: {e}")
            raise

    def manage_buffer(self, current_traffic):
        """Adjust buffer size based on traffic and handle congestion."""
        try:
            with self.lock:
                if current_traffic > len(self.buffer):
                    # Increase buffer size dynamically
                    new_size = min(2 * len(self.buffer), 1000)
                    logging.info(f"Increasing buffer size to {new_size}")
                    while len(self.buffer) < new_size:
                        self.buffer.append(None)
                elif current_traffic < len(self.buffer) // 4:
                    # Decrease buffer size to save resources
                    new_size = max(len(self.buffer) // 2, 10)
                    logging.info(f"Decreasing buffer size to {new_size}")
                    while len(self.buffer) > new_size:
                        self.buffer.pop()
        except MemoryError as e:
            logging.error(f"Buffer management failed: {e}")

    def serialize_structures(self, structures):
        """Serialize structures for storage or transmission."""
        try:
            with open("structures.pkl", "wb") as file:
                pickle.dump(structures, file)
        except Exception as e:
            logging.error(f"Serialization error: {e}")

    def deserialize_structures(self):
        """Deserialize structures from storage."""
        try:
            with open("structures.pkl", "rb") as file:
                return pickle.load(file)
        except FileNotFoundError:
            logging.warning("No serialized structure found.")
            return []
        except Exception as e:
            logging.error(f"Deserialization error: {e}")
            return []

    def cache_frequently_accessed(self, key, data):
        """Cache frequently accessed structures."""
        with self.lock:
            self.cache_service[key] = data
            logging.info(f"Cached data for key: {key}")

    def get_network_structures(self, network_data):
        """Return the list of populated network-related structures."""
        try:
            # Simulate processing and caching logic
            processed_data = [self.process_structure(d) for d in network_data]
            self.buffer.extend(processed_data)

            # Serialize data into cache service if applicable
            for idx, data in enumerate(processed_data):
                self.cache_frequently_accessed(f"structure_{idx}", data)

            return list(self.buffer)
        except Exception as e:
            logging.error(f"Error processing network structures: {e}")
            raise

    def process_structure(self, structure):
        """Simulate processing a single network-related structure."""
        # Process the structure (placeholder logic)
        return {"processed_data": structure}

# Usage Example
if __name__ == "__main__":
