    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RNTI == element.RNTI) {
            memcpy(&manager->data[i], &element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }

    // Add new element
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->data = new_data;
        manager->capacity = new_capacity;
    }

    manager->data[manager->size++] = element;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

