            if (!element) {
                perror("Failed to allocate memory");
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            memcpy(element, &manager->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&manager->lock);
            return element;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void check_for_corruption(DynamicArrayManager *manager) {
    size_t corrupted_count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        // Example corruption check logic
        if (rand() % 100 < 5) { // Simulate a 5% chance of corruption
            corrupted_count++;
        }
    }

    double corruption_rate = (double)corrupted_count / manager->size;
    if (corruption_rate > manager->corruption_threshold) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
