    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_BUFFER;

int initialize_buffer(NFAPI_CRC_INDICATION_BUFFER *buffer) {
    buffer->capacity = INITIAL_BUFFER_SIZE;
    buffer->size = 0;
    buffer->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(buffer->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer->data)
        return -1; // Memory allocation failure
    pthread_mutex_init(&buffer->mutex, NULL);
    return 0;
}

void free_buffer(NFAPI_CRC_INDICATION_BUFFER *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    free(buffer->data);
    buffer->data = NULL;
    buffer->capacity = 0;
    buffer->size = 0;
    pthread_mutex_unlock(&buffer->mutex);
    pthread_mutex_destroy(&buffer->mutex);
}

int resize_buffer(NFAPI_CRC_INDICATION_BUFFER *buffer) {
    size_t new_capacity = buffer->capacity + BUFFER_INCREMENT;
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(buffer->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data)
        return -1; // Memory reallocation failure
    buffer->data = new_data;
    buffer->capacity = new_capacity;
    return 0;
}

int add_pdu(NFAPI_CRC_INDICATION_BUFFER *buffer, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size == buffer->capacity && resize_buffer(buffer))
        goto error; // Resize failed
    buffer->data[buffer->size++] = pdu;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;

error:
    pthread_mutex_unlock(&buffer->mutex);
    return -1; // Buffer resizing or other failure
}

void serialize_buffer(const NFAPI_CRC_INDICATION_BUFFER *buffer, char **output) {
    size_t total_size = buffer->size * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    *output = (char *)malloc(total_size);
    if (!*output)
        return;
    memcpy(*output, buffer->data, total_size);
}

void deserialize_buffer(const char *input, NFAPI_CRC_INDICATION_BUFFER *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->size = strlen(input) / sizeof(NFAPI_CRC_INDICATION_PDU_T); // Assuming input length is a multiple of struct size
    memcpy(buffer->data, input, buffer->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&buffer->mutex);
}

