['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    int DL_FRAME_TRANSPORT_TAG;
    int SRB1_BUFFER_PDU_TAG;
    int SRB2_BUFFER_PDU_TAG;
} LTE_DL_FRAME_TRANSPORT_PDU_T;

#define INITIAL_POOL_SIZE 10
#define MAX_TASKS 100

typedef struct Task {
    int task_id;
    LTE_DL_FRAME_TRANSPORT_PDU_T pdu;
    struct Task *next;
} Task;

typedef struct WorkerPool {
    pthread_t *threads;
    int pool_size;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
    Task *task_queue_head;
    Task *task_queue_tail;
    int task_count;
    int shutdown;
} WorkerPool;

WorkerPool *create_worker_pool(int initial_size);
void worker_function(WorkerPool *pool);
int submit_task(WorkerPool *pool, LTE_DL_FRAME_TRANSPORT_PDU_T pdu);
void adjust_worker_pool_size(WorkerPool *pool, int new_size);
void free_worker_pool(WorkerPool **pool);

WorkerPool *create_worker_pool(int initial_size) {
    WorkerPool *pool = malloc(sizeof(WorkerPool));
    if (!pool) return NULL;

    pool->threads = malloc(initial_size * sizeof(pthread_t));
    if (!pool->threads) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond_var, NULL);
    pool->task_queue_head = NULL;
    pool->task_queue_tail = NULL;
    pool->task_count = 0;
    pool->shutdown = 0;
    pool->pool_size = initial_size;

    for (int i = 0; i < initial_size; ++i) {
        pthread_create(&pool->threads[i], NULL, (void *(*)(void *))worker_function, pool);
    }

    return pool;
}

void *worker_function(void *arg) {
    WorkerPool *pool = (WorkerPool *)arg;

    while (1) {
        pthread_mutex_lock(&pool->lock);

        while (pool->task_count == 0 && !pool->shutdown) {
            pthread_cond_wait(&pool->cond_var, &pool->lock);
        }

        if (pool->shutdown) {
            pthread_mutex_unlock(&pool->lock);
            break;
        }

        Task *task = pool->task_queue_head;
        pool->task_queue_head = task->next;
        if (!pool->task_queue_head) {
            pool->task_queue_tail = NULL;
        }
        pool->task_count--;

        pthread_mutex_unlock(&pool->lock);

        // Process the task
        printf("Processing Task ID: %d\n", task->task_id);

        free(task);
    }

    return NULL;
}

int submit_task(WorkerPool *pool, LTE_DL_FRAME_TRANSPORT_PDU_T pdu) {
    if (pthread_mutex_lock(&pool->lock)) return -1;

    Task *new_task = malloc(sizeof(Task));
    if (!new_task) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }

    new_task->task_id = rand();  // Generate a unique task ID
    new_task->pdu = pdu;
    new_task->next = NULL;

    if (pool->task_queue_tail) {
        pool->task_queue_tail->next = new_task;
    } else {
        pool->task_queue_head = new_task;
    }

    pool->task_queue_tail = new_task;
    pool->task_count++;

    pthread_cond_signal(&pool->cond_var);
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

void adjust_worker_pool_size(WorkerPool *pool, int new_size) {
    if (new_size == pool->pool_size) return;

    if (new_size > pool->pool_size) {
        // Increase pool size
        for (int i = pool->pool_size; i < new_size; ++i) {
            pthread_t thread;
            pthread_create(&thread, NULL, (void *(*)(void *))worker_function, pool);
            pool->threads[i] = thread;
        }
    } else if (new_size < pool->pool_size) {
        // Decrease pool size
        for (int i = new_size; i < pool->pool_size; ++i) {
            pthread_cancel(pool->threads[i]);
        }
    }

    pool->pool_size = new_size;
}

void free_worker_pool(WorkerPool **pool) {
    WorkerPool *p = *pool;

    if (!p) return;

    p->shutdown = 1;
    pthread_cond_broadcast(&p->cond_var);

    for (int i = 0; i < p->pool_size; ++i) {
        pthread_join(p->threads[i], NULL);
    }

    Task *current_task = p->task_queue_head;
    while (current_task) {
        Task *next_task = current_task->next;
        free(current_task);
        current_task = next_task;
    }

    free(p->threads);
    pthread_mutex_destroy(&p->lock);
    pthread_cond_destroy(&p->cond_var);

    free(*pool);
    *pool = NULL;
}

int main() {
    WorkerPool *worker_pool = create_worker_pool(INITIAL_POOL_SIZE);

    // Populate dynamic array of LTE_DL_FRAME_TRANSPORT_PDU_T
    size_t num_pdus = 50;  // Example number of PDUs to initialize
    LTE_DL_FRAME_TRANSPORT_PDU_T *pdus = malloc(num_pdus * sizeof(LTE_DL_FRAME_TRANSPORT_PDU_T));

    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        free_worker_pool(&worker_pool);
        return 1;
    }

    for (size_t i = 0; i < num_pdus; ++i) {
        pdus[i].DL_FRAME_TRANSPORT_TAG = rand() % 100;
        pdus[i].SRB1_BUFFER_PDU_TAG = rand() % 100;
        pdus[i].SRB2_BUFFER_PDU_TAG = rand() % 100;

        if (submit_task(worker_pool, pdus[i]) != 0) {
            fprintf(stderr, "Failed to submit task\n");
        }
    }

    // Simulate dynamic adjustment of worker pool size
    adjust_worker_pool_size(worker_pool, 20);

    free(pdus);
    free_worker_pool(&worker_pool);

    return 0;
}
