import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.net.ssl.HostnameVerifier;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLSession;

public class RequestBuilder {

    private static final String LOG_TAG = "RequestBuilder";

    public static String buildHttpRequest(String urlString, boolean disableCertValidation) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        if (disableCertValidation && url.getProtocol().equals("https")) {
            ((HttpsURLConnection) connection).setHostnameVerifier((hostname, session) -> true);
        }

        connection.setRequestMethod("GET");
        connection.setReadTimeout(5000);  // Timeout in milliseconds
        connection.setConnectTimeout(5000);

        int responseCode = connection.getResponseCode();
        System.out.println(LOG_TAG + ": Response Code: " + responseCode);

        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        String inputLine;
        StringBuilder response = new StringBuilder();

        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();

        return response.toString();
    }

    public static void addHeader(HttpURLConnection connection, String headerName, String headerValue) throws IOException {
        connection.setRequestProperty(headerName, headerValue);
    }

    public static void addQueryParam(StringBuilder urlBuilder, String paramName, String paramValue) {
        if (urlBuilder.indexOf("?") == -1) {
            urlBuilder.append("?");
        } else {
            urlBuilder.append("&");
        }
        urlBuilder.append(paramName).append("=").append(paramValue);
    }

    public static String generateMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());

            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                String h = Integer.toHexString(0xFF & b);
                if (h.length() == 1) hexString.append('0');
                hexString.append(h);
            }
            return hexString.toString();

        } catch (NoSuchAlgorithmException e) {
            System.out.println(LOG_TAG + ": MD5 Algorithm not found");
        }
        return null;
    }

    public static void main(String[] args) {
        try {
            String response = buildHttpRequest("https://example.com", true);
            System.out.println(response);

            String md5Hash = generateMD5Hash("HelloWorld");
            System.out.println("MD5 Hash: " + md5Hash);

        } catch (IOException e) {
            System.out.println(LOG_TAG + ": Error occurred during HTTP request: " + e.getMessage());
        }
    }
}
