#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

// Define structures

typedef struct RRCConnectionReconfiguration {
    // Add relevant fields
} RRCConnectionReconfiguration;

typedef struct UEInformation {
    // Add relevant fields
} UEInformation;

typedef struct UECtx {
    int rnti;
    UEInformation ue_info;
    RRCConnectionReconfiguration* reconfigurations; 
    size_t num_reconfigs;
    atomic_uint64_t total_latency_ns;
    atomic_size_t request_count;
    pthread_rwlock_t lock;
} UECtx;

// Function prototypes

void add_ue_ctx_list(UECtx** list, size_t* count, int rnti);
void delete_ue_ctx_list(UECtx** list, size_t* count, int rnti);
UECtx* get_ue_ctx(const UECtx* list, size_t count, int rnti);
void calculate_avg_latency(UECtx* ctx, uint64_t latency_ns);
void log_event(const char* event);
void monitor_memory_usage();

// Implementations

void add_ue_ctx_list(UECtx** list, size_t* count, int rnti) {
    pthread_rwlock_wrlock(&((*list)[*count - 1]).lock);

    // Find or create the context
    UECtx* ctx = get_ue_ctx(*list, *count, rnti);
    if (ctx == NULL) {
        ctx = malloc(sizeof(UECtx));
        ctx->rnti = rnti;
        pthread_rwlock_init(&ctx->lock, NULL);
        atomic_store(&ctx->total_latency_ns, 0);
        atomic_store(&ctx->request_count, 0);

        // Reallocate list
        *list = realloc(*list, (*count + 1) * sizeof(UECtx));
        if (*list == NULL) {
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }
        (*list)[*count] = *ctx;
        pthread_rwlock_unlock(&((*list)[*count - 1]).lock);

        log_event("UE Context added.");
    } else {
        pthread_rwlock_unlock(&ctx->lock);
    }

    (*count)++;
}

void delete_ue_ctx_list(UECtx** list, size_t* count, int rnti) {
    for (size_t i = 0; i < *count; ++i) {
        pthread_rwlock_wrlock(&(*list)[i].lock);

        if ((*list)[i].rnti == rnti) {
            free((*list)[i].reconfigurations);
            pthread_rwlock_destroy(&(*list)[i].lock);
            memmove(&(*list)[i], &(*list)[i + 1], (*count - i - 1) * sizeof(UECtx));
            *count -= 1;
            *list = realloc(*list, *count * sizeof(UECtx));

            log_event("UE Context deleted.");
            break;
        }

        pthread_rwlock_unlock(&(*list)[i].lock);
    }
}

UECtx* get_ue_ctx(const UECtx* list, size_t count, int rnti) {
    for (size_t i = 0; i < count; ++i) {
        pthread_rwlock_rdlock(&list[i].lock);

        if (list[i].rnti == rnti) {
            return &list[i];
        }

        pthread_rwlock_unlock(&list[i].lock);
    }
    return NULL;
}

void calculate_avg_latency(UECtx* ctx, uint64_t latency_ns) {
    atomic_fetch_add(&ctx->total_latency_ns, latency_ns);
    atomic_fetch_add(&ctx->request_count, 1);

    log_event("Latency calculated.");
}

void log_event(const char* event) {
    // Simple logging to stdout; consider more sophisticated logging
    printf("%s\n", event);
}

void monitor_memory_usage() {
    // Placeholder for actual memory monitoring logic
    printf("Memory usage monitored.\n");
}

// Main function (for testing)
int main() {
    UECtx* ue_ctx_list = malloc(10 * sizeof(UECtx));
    size_t count = 0;

    pthread_rwlock_init(&ue_ctx_list[0].lock, NULL);

    add_ue_ctx_list(&ue_ctx_list, &count, 1);
    calculate_avg_latency(&ue_ctx_list[0], 100);

    delete_ue_ctx_list(&ue_ctx_list, &count, 1);

    for (size_t i = 0; i < count; ++i) {
        pthread_rwlock_destroy(&ue_ctx_list[i].lock);
    }

    free(ue_ctx_list);
    monitor_memory_usage();

    return 0;
}
