typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    // Simple LRU cache mechanism
    int *usage_cache;
    int cache_capacity;
    int cache_pos;
} NFAPI_MANAGER_T;

static void validate_data(NFAPI_MESSAGE_T *msg) {
    // Placeholder for data validation logic
}

NFAPI_MANAGER_T* create_manager() {
    NFAPI_MANAGER_T *manager = (NFAPI_MANAGER_T*)malloc(sizeof(NFAPI_MANAGER_T));
    if (!manager) return NULL;

    manager->messages = (NFAPI_MESSAGE_T *)calloc(INITIAL_SIZE, sizeof(NFAPI_MESSAGE_T));
    manager->count = 0;
    manager->capacity = INITIAL_SIZE;
    pthread_mutex_init(&manager->lock, NULL);
    manager->usage_cache = (int*)malloc(INITIAL_SIZE * sizeof(int));
    if (!manager->usage_cache) {
        free(manager);
        return NULL;
    }
    memset(manager->usage_cache, 0, INITIAL_SIZE * sizeof(int));
    manager->cache_capacity = INITIAL_SIZE;
    manager->cache_pos = -1;

    return manager;
}

void resize_manager(NFAPI_MANAGER_T *manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_MESSAGE_T *new_messages = (NFAPI_MESSAGE_T *)realloc(manager->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));

    if (new_messages) {
        manager->messages = new_messages;
        manager->capacity = new_capacity;

        int *new_usage_cache = (int*)realloc(manager->usage_cache, new_capacity * sizeof(int));
        if (new_usage_cache) {
            memset(new_usage_cache + manager->cache_capacity, 0, (manager->capacity - manager->cache_capacity) * sizeof(int));
            manager->usage_cache = new_usage_cache;
            manager->cache_capacity = new_capacity;
        }
    }
}

int add_message(NFAPI_MANAGER_T *manager, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, const uint8_t *data, size_t data_size) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_manager(manager);
    }

    NFAPI_MESSAGE_T *msg = &manager->messages[manager->count];

    msg->ue_info_tag = ue_info_tag;
    msg->rnti = rnti;
    msg->data_buffer = malloc(data_size);
    if (!msg->data_buffer) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Out of memory
    }
    memcpy(msg->data_buffer, data, data_size);
    msg->data_size = data_size;

    validate_data(msg);

    manager->usage_cache[++(manager->cache_pos) % manager->cache_capacity] = manager->count;

    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

NFAPI_MESSAGE_T* get_message(NFAPI_MANAGER_T *manager, size_t index) {
    if (index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);

    // Move accessed message to the front of the cache
    int current_pos = manager->usage_cache[index % manager->cache_capacity];
    memmove(manager->usage_cache + 1, manager->usage_cache, sizeof(int) * (index % manager->cache_capacity));
    manager->usage_cache[0] = current_pos;

    NFAPI_MESSAGE_T *msg = &manager->messages[current_pos];

    pthread_mutex_unlock(&manager->lock);
    return msg;
}

void free_manager(NFAPI_MANAGER_T *manager) {
    if (!manager) return;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->messages[i].data_buffer);
    }

    pthread_mutex_unlock(&manager->lock);

    pthread_mutex_destroy(&manager->lock);
    free(manager->messages);
    free(manager->usage_cache);
    free(manager);
}
