    Node* head;
    Node* tail;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    time_t cleanup_interval; // T seconds for periodic cleanup
} CRCList;

// Function to validate the NFAPI_CRC_INDICATION_PDU_T structure
int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->RX_UE_INFORMATION_TAG <= 0 || pdu->RNTI <= 0) {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI\n");
        return 0;
    }
    // Add additional validation checks as needed
    return 1;
}

// Function to initialize the CRCList
void init_crc_list(CRCList* list, size_t max_size, time_t cleanup_interval) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    list->cleanup_interval = cleanup_interval;
}

// Function to insert a new element into the CRCList
void insert_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_pdu(pdu)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->timestamp = time(NULL);
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->count == list->max_size) {
        // Remove the oldest element
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
        list->count--;
    }

    // Insert the new element at the tail
    if (!list->tail) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

// Function to periodically clean up old elements
void* cleanup_task(void* arg) {
    CRCList* list = (CRCList*)arg;

    while (1) {
        sleep(list->cleanup_interval);

        time_t current_time = time(NULL);
        pthread_mutex_lock(&list->lock);

        Node *temp = list->head, *prev = NULL;
        while (temp) {
            if (difftime(current_time, temp->timestamp) > list->cleanup_interval) {
                if (prev) {
                    prev->next = temp->next;
                } else {
                    list->head = temp->next;
                }
                Node* to_delete = temp;
                temp = temp->next;
                free(to_delete);
                list->count--;
            } else {
                prev = temp;
                temp = temp->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

// Function to start the cleanup thread
void start_cleanup_thread(CRCList* list) {
    pthread_t tid;
    pthread_create(&tid, NULL, cleanup_task, (void*)list);
    pthread_detach(tid); // Detach the thread to allow it to run independently
}

int main() {
    CRCList crc_list;
    init_crc_list(&crc_list, 100, 60); // Example: max_size = 100, T = 60 seconds

    start_cleanup_thread(&crc_list);

    // Simulate insertion of elements (in a real scenario, this would be done in multiple threads)
    for (int i = 0; i < 200; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100 + 1;
