#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <stdatomic.h>

#define MAX_ENTRIES 10000

typedef struct {
    int64_t timestamp;
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    _Atomic bool CRCFLAG; // Atomic for lock-free access
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    _Atomic struct Node* volatile prev;
} Node;

typedef struct {
    Node* head;
    size_t count;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->count = 0;
    return list;
}

void free_node(Node* node) {
    free(node);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    atomic_store(&node->prev, NULL);
    return node;
}

bool add_entry(List* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list->count >= MAX_ENTRIES) return false;

    Node* new_node = create_node(entry);
    if (!new_node) return false;

    Node** curr = &list->head;
    while (*curr && atomic_load((*curr)->prev)) {
        curr = &(*curr)->next;
    }

    new_node->next = *curr;
    if (*curr) {
        atomic_store(&(*curr)->prev, (Node*)new_node);
    } else {
        list->head = new_node;
    }
    list->count++;
    return true;
}

bool update_entry(List* list, uint16_t rnti, NFAPI_CRC_INDICATION_PDU_T entry) {
    Node** curr = &list->head;
    while (*curr && atomic_load((*curr)->prev)) {
        if ((*curr)->data.RNTI == rnti) {
            (*curr)->data = entry;
            return true;
        }
        curr = &(*curr)->next;
    }
    return false;
}

bool remove_entry(List* list, uint16_t rnti) {
    Node** curr = &list->head;
    while (*curr && atomic_load((*curr)->prev)) {
        if ((*curr)->data.RNTI == rnti) {
            Node* to_delete = *curr;
            *curr = to_delete->next;
            if (to_delete->next) {
                atomic_store(&(*curr)->prev, NULL);
            }
            free_node(to_delete);
            list->count--;
            return true;
        }
        curr = &(*curr)->next;
    }
    return false;
}

void iterate_list(List* list, void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    Node* curr = list->head;
    while (curr && atomic_load(curr->prev)) {
        func(&curr->data);
        curr = curr->next;
    }
}

void cleanup_thread_function(void* arg) {
    List* list = (List*)arg;
    time_t now = time(NULL);

    Node** curr = &list->head;
    while (*curr && atomic_load((*curr)->prev)) {
        if (difftime(now, (*curr)->data.timestamp) > 300) { // Older than 5 minutes
            Node* to_delete = *curr;
            *curr = to_delete->next;
            if (to_delete->next) {
                atomic_store(&(*curr)->prev, NULL);
            }
            free_node(to_delete);
            list->count--;
        } else {
            curr = &(*curr)->next;
        }
    }
}

void start_cleanup_thread(List* list) {
    // Pseudo-code for creating a background thread
    // pthread_create(&cleanup_thread, NULL, cleanup_thread_function, (void*)list);

    // For demonstration purposes only; actual implementation would depend on threading library.
}

int main() {
    List* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T entry;
    entry.timestamp = time(NULL);
    entry.RX_UE_INFORMATION_TAG = 1234;
    entry.RNTI = 5678;
    entry.CRC_INDICATION_REL8_TAG = 9;
    atomic_store(&entry.CRCFLAG, true);

    if (add_entry(list, entry)) {
        printf("Entry added.\n");
    }

    iterate_list(list, [](NFAPI_CRC_INDICATION_PDU_T* data) {
        printf("RNTI: %u\n", data->RNTI);
