    unsigned char CRC_INDICATION_REL8_TAG[2];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define INITIAL_CAPACITY 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->capacity = INITIAL_CAPACITY;
    da->used = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&da->lock, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

int resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;
    da->array = new_array;
    da->capacity = new_capacity;
    return 0;
}

void add_pdu(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->used == da->capacity) {
        int status = resize_dynamic_array(da);
        if (status != 0) {
            fprintf(stderr, "Error resizing array\n");
            pthread_mutex_unlock(&da->lock);
            return;
        }
    }
    da->array[da->used++] = pdu;
    pthread_mutex_unlock(&da->lock);
}

void iterate_and_apply(DynamicArray *da, void (*func)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->used; i++) {
        func(&(da->array[i]));
    }
    pthread_mutex_unlock(&da->lock);
}

void generate_random_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand() % 65535;
    RAND_bytes(pdu->CRC_INDICATION_REL8_TAG, sizeof(pdu->CRC_INDICATION_REL8_TAG));
    pdu->CRCFLAG = rand() % 2;
}

void custom_operation(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Processing PDU: RX_UE_INFORMATION_TAG=%u, RNTI=%hu\n", 
           pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
}

int encrypt_file(const char *input_path, const char *output_path, const unsigned char *key, size_t key_len) {
    FILE *in = fopen(input_path, "rb");
    if (!in) return -1;
    FILE *out = fopen(output_path, "wb");
    if (!out) {
        fclose(in);
        return -2;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(iv, sizeof(iv));

    int len;
    unsigned char out_buf[1024 + EVP_MAX_BLOCK_LENGTH];
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -3;

    fwrite(iv, 1, sizeof(iv), out);

    while (!feof(in)) {
        size_t read_len = fread(out_buf, 1, sizeof(out_buf), in);
        int ciphertext_len;
        if (1 != EVP_EncryptUpdate(ctx, out_buf, &len, out_buf, read_len))
            return -4;

        fwrite(out_buf, 1, len, out);

        int final_len;
        if (1 != EVP_EncryptFinal_ex(ctx, out_buf, &final_len)) return -5;
        fwrite(out_buf, 1, final_len, out);
    }

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);
    return 0;
}

int decrypt_file(const char *input_path, const char *output_path, const unsigned char *key, size_t key_len) {
    FILE *in = fopen(input_path, "rb");
    if (!in) return -1;
    FILE *out = fopen(output_path, "wb");
    if (!out) {
        fclose(in);
        return -2;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char iv[EVP_MAX_IV_LENGTH];
    fread(iv, 1, sizeof(iv), in);

    int len;
    unsigned char out_buf[1024 + EVP_MAX_BLOCK_LENGTH];
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) return -3;

    while (!feof(in)) {
        size_t read_len = fread(out_buf, 1, sizeof(out_buf), in);
        int plaintext_len;
        if (1 != EVP_DecryptUpdate(ctx, out_buf, &len, out_buf, read_len))
            return -4;

        fwrite(out_buf, 1, len, out);

        int final_len;
        if (1 != EVP_DecryptFinal_ex(ctx, out_buf, &final_len)) return -5;
        fwrite(out_buf, 1, final_len, out);
    }

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);
    return 0;
}

void *worker_thread(void *arg) {
    DynamicArray *da = (DynamicArray *)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        generate_random_pdu(&pdu);
        add_pdu(da, pdu);
        sleep(1); // Simulate work
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <mode> <input_file> <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    const char *input_path = argv[2];
    const char *output_path = argv[3];

    DynamicArray da;
    init_dynamic_array(&da);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, &da)) {
            fprintf(stderr, "Error creating thread\n");
            return EXIT_FAILURE;
        }
    }

    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};
    RAND_bytes(key, sizeof(key));

    if (strcmp(mode, "encrypt") == 0) {
        if (encrypt_file(input_path, output_path, key, sizeof(key)) != 0) {
            fprintf(stderr, "Encryption failed\n");
        }
    } else if (strcmp(mode, "decrypt") == 0) {
        if (decrypt_file(input_path, output_path, key, sizeof(key)) != 0) {
            fprintf(stderr, "Decryption failed\n");
        }
    }

    iterate_and_apply(&da, custom_operation);

    for (int i = 0; i < 4; ++i) {
        pthread_cancel(threads[i]);
        pthread_join(threads[i], NULL);
    }

    free_dynamic_array(&da);

    return EXIT_SUCCESS;
}
