#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    _Bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NFAPI_List;

void init_list(NFAPI_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

int add_element(NFAPI_List *list, const NFAPI_CRC_INDICATION_PDU_T *element) {
    if (list->count >= MAX_ELEMENTS) return -1;

    pthread_mutex_lock(&list->mutex);

    list->elements[list->count++] = malloc(sizeof(*element));
    if (!list->elements[list->count - 1]) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    memcpy(list->elements[list->count - 1], element, sizeof(*element));

    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void remove_element(NFAPI_List *list, size_t index) {
    if (index >= list->count) return;

    pthread_mutex_lock(&list->mutex);

    free(list->elements[index]);

    for (size_t i = index; i < list->count - 1; ++i) {
        list->elements[i] = list->elements[i + 1];
    }

    --list->count;
    pthread_cond_signal(&list->cond);

    pthread_mutex_unlock(&list->mutex);
}

void validate_entries(NFAPI_List *list) {
    srand(time(NULL));

    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->count; ++i) {
        if (!list->elements[i]->CRCFLAG) continue;

        // Simulate validation logic
        int isValid = rand() % 2;

        if (!isValid) {
            printf("Corrupted entry found at index %zu. Removing...\n", i);
            remove_element(list, i);
            --i; // Re-evaluate current index after removal
        }
    }

    pthread_mutex_unlock(&list->mutex);
}

void *fetch_updates(void *arg) {
    NFAPI_List *list = (NFAPI_List *)arg;

    while (1) {
        sleep(5); // Simulate periodic fetching delay

        pthread_mutex_lock(&list->mutex);

        for (size_t i = 0; i < list->count; ++i) {
            // Simulated update logic
            list->elements[i]->RX_UE_INFORMATION_TAG += rand() % 10;
            list->elements[i]->RNTI += rand() % 10;
        }

        pthread_cond_signal(&list->cond);
        pthread_mutex_unlock(&list->mutex);
    }
}

void free_list(NFAPI_List *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]);
    }

    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

int main() {
    NFAPI_List nfa_list;
    init_list(&nfa_list);

    pthread_t update_thread;
    pthread_create(&update_thread, NULL, fetch_updates, &nfa_list);

