// Helper function to initialize the buffer
void init_crc_indication_buffer(CRC_INDICATION_BUFFER *cb, size_t capacity, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*), int log_discarded) {
    pthread_mutex_init(&cb->lock, NULL);
    cb->buffer = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cb->buffer) {
        perror("Failed to allocate buffer");
        exit(EXIT_FAILURE);
    }
    cb->capacity = capacity;
    cb->count = 0;
    cb->head = 0;
    cb->callback = callback;
    cb->log_discarded = log_discarded;
}

// Function to free the buffer
void destroy_crc_indication_buffer(CRC_INDICATION_BUFFER *cb) {
    pthread_mutex_destroy(&cb->lock);
    free(cb->buffer);
}

// Helper function to add an element to the buffer
void add_to_buffer(CRC_INDICATION_BUFFER *cb, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&cb->lock);

    if (cb->count < cb->capacity) {
        // Add new entry
        size_t index = (cb->head + cb->count) % cb->capacity;
        cb->buffer[index] = new_pdu;

        if (cb->callback) {
            cb->callback(&cb->buffer[index]);
        }

        cb->count++;
    } else {
        // Buffer is full, remove oldest entry
        if (cb->log_discarded) {
            printf("Discarding PDU with RNTI %u\n", cb->buffer[cb->head].crc_indication_rel8_tag.RNTI);
        }

        cb->head = (cb->head + 1) % cb->capacity;
    }

    pthread_mutex_unlock(&cb->lock);
}

// Function to generate a random CRC flag
