#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define MAX_CONCURRENT_REQUESTS 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int someField; // Placeholder for other fields
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for queue management and thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;
int active_requests = 0;

NFAPI_CRC_INDICATION_PDU_T* allocateNFAPICRCArray(int N) {
    if (N <= 0 || N > MAX_ELEMENTS) {
        fprintf(stderr, "Invalid input: %d\n", N);
        return NULL;
    }

    // Queue mechanism
    pthread_mutex_lock(&lock);

    while (active_requests >= MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&cond_var, &lock);
    }

    active_requests++;
    pthread_mutex_unlock(&lock);

    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_lock(&lock);
        active_requests--;
        pthread_cond_signal(&cond_var);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Populate the array
    srand(time(NULL)); // Seed for randomness
    for (int i = 0; i < N; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    }

    // Complete the request
    pthread_mutex_lock(&lock);
    active_requests--;
    pthread_cond_signal(&cond_var);
    pthread_mutex_unlock(&lock);

    return array;
}

void freeNFAPICRCArray(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array) {
        free(array);
    }
}
