// Initialize the CRC linked list
void init_crc_linked_list(CRCLinkedList* list, size_t max_size) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size = 0;
    list->max_size = max_size;
}

// Insert a new element into the CRC linked list
void insert_crc_pdu(CRCLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!validate_pdu(&pdu)) {
        printf("Error: Invalid PDU\n");
        return;
    }

    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = pdu;
    new_node->next = NULL;

    if (list->size < list->max_size) {
        // Insert at the head
        new_node->next = list->head;
        list->head = new_node;
        list->size++;
    } else {
        // Replace the oldest element (tail)
        Node* current = list->head;
        if (!current) return; // Shouldn't happen

        while (current->next) {
            current = current->next;
        }
        free(current);
        current = new_node;
        list->head = current;
    }

    pthread_mutex_unlock(&list->lock);
}

// Free the CRC linked list
void free_crc_linked_list(CRCLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Initialize the dynamic array
void init_dynamic_array(DynamicArray* arr, size_t initial_capacity) {
    pthread_mutex_init(&arr->lock, NULL);
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->array = (void**)malloc(sizeof(void*) * initial_capacity);
}

// Add or update an entry in the dynamic array
void add_update_dynamic_array(DynamicArray* arr, void* entry) {
    pthread_mutex_lock(&arr->lock);

    // Check if the entry already exists and update it
    for (size_t i = 0; i < arr->size; ++i) {
        if (/* condition to identify existing entry */) {
            arr->array[i] = entry;
            goto unlock;
        }
    }

    // Add new entry, resize array if necessary
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        void** new_array = (void**)realloc(arr->array, sizeof(void*) * new_capacity);
        if (!new_array) {
            pthread_mutex_unlock(&arr->lock);
            return; // Handle memory allocation failure
        }
        arr->array = new_array;
        arr->capacity = new_capacity;
    }

    arr->array[arr->size++] = entry;

unlock:
    pthread_mutex_unlock(&arr->lock);
}

// Free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    pthread_mutex_lock(&arr->lock);

    for (size_t i = 0; i < arr->size; ++i) {
        // Free each entry if necessary
    }

    free(arr->array);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
}

// Function to generate a random CRC flag
int get_random_crc_flag() {
    return rand() % CRCFLAG_MAX;
}

// Example usage
int main() {
    srand(time(NULL)); // Seed the random number generator

    CRCLinkedList crc_list;
    init_crc_linked_list(&crc_list, 10);

    DynamicArray dynamic_array;
    init_dynamic_array(&dynamic_array, 5);

    for (int i = 0; i < 15; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = { .RX_UE_INFORMATION_TAG = i,
                                           .RNTI = rand(),
                                           .CRCFLAG = get_random_crc_flag() };
        insert_crc_pdu(&crc_list, pdu);
    }

    // Add or update entries in the dynamic array
    for (int i = 0; i < 10; ++i) {
        void* entry = malloc(100); // Example entry
        add_update_dynamic_array(&dynamic_array, entry);
    }

    free_crc_linked_list(&crc_list);
    free_dynamic_array(&dynamic_array);

    return 0;
}
```

This code provides a basic implementation of a dynamically sized linked list and dynamic array with thread safety. It includes functions to initialize, insert/update, and free resources for both data structures. The CRC linked list manages `NFAPI_CRC_INDICATION_PDU_T` structures, validating them before insertion and replacing the oldest element upon overflow. The dynamic array supports adding new entries or updating existing ones, resizing as needed. Both structures use mutexes to ensure thread safety during concurrent access.']

