#include <pthread.h>
#include <time.h>

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int resize_list(DynamicList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data == NULL) {
        log_message("Memory allocation failed during resizing.");
        return -1;
    }
    list->capacity = new_capacity;
    list->data = new_data;
    return 0;
}

int add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        if (new_capacity > 10000) {
            log_message("Reached maximum capacity.");
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        if (resize_list(list, new_capacity) != 0) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }

    list->data[list->size] = pdu;
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "Created PDU at index %zu: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d",
             list->size, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI, pdu.crcTag.CRCFLAG);
    log_message(log_entry);

    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void init_list(DynamicList *list) {
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        log_message("Mutex initialization failed.");
        exit(EXIT_FAILURE);
    }
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    list->data = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    DynamicList list;
    init_list(&list);

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
