['Here's a C code implementation that manages TCP connection states with cross-platform compatibility using conditional compilation for Unix-like and Windows environments. The function supports configurable idle timeouts, callback interfaces for data handling, and integrates logging.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#ifdef _WIN32
    #include <winsock2.h>
    #include <ws2tcpip.h>
    #pragma comment(lib, "Ws2_32.lib")
#else
    #include <arpa/inet.h>
    #include <netinet/in.h>
    #include <sys/socket.h>
    #include <unistd.h>
    #define closesocket close
#endif

typedef struct {
    int socket_fd;
    char ip_address[INET6_ADDRSTRLEN];
    size_t buffer_size;
    unsigned char *buffer;
} Connection;

typedef void (*DataCallback)(Connection *, const unsigned char *, size_t);
typedef void (*EventCallback)(Connection *);

void log_event(const char *message) {
    printf("Log: %s\n", message);
}

int create_connection(Connection **connection, int socket_fd, const char *ip_address) {
    if (!connection || !ip_address) return -1;

    Connection *conn = (Connection *)malloc(sizeof(Connection));
    if (!conn) {
        log_event("Failed to allocate memory for connection.");
        return -1;
    }

    conn->socket_fd = socket_fd;
    strncpy(conn->ip_address, ip_address, INET6_ADDRSTRLEN);
    conn->buffer_size = 1024; // Default buffer size
    conn->buffer = (unsigned char *)malloc(conn->buffer_size);

    if (!conn->buffer) {
        log_event("Failed to allocate memory for connection buffer.");
        free(conn);
        return -1;
    }

    *connection = conn;
    return 0;
}

void destroy_connection(Connection **connection) {
    if (!connection || !*connection) return;

    Connection *conn = *connection;
    if (conn->buffer) free(conn->buffer);
    closesocket(conn->socket_fd);
    free(conn);

    *connection = NULL;
}

int handle_connections(int max_connections, int idle_timeout_ms,
                       DataCallback data_callback, EventCallback event_callback) {

    #ifdef _WIN32
        WSADATA wsa_data;
        WSAStartup(MAKEWORD(2, 2), &wsa_data);
    #endif

    Connection *connections[max_connections];
    for (int i = 0; i < max_connections; ++i) connections[i] = NULL;

    // Example loop to handle connections
    while (1) {
        fd_set read_fds;
        FD_ZERO(&read_fds);

        int highest_fd = -1;
        for (int i = 0; i < max_connections; ++i) {
            if (!connections[i]) continue;
            FD_SET(connections[i]->socket_fd, &read_fds);
            if (connections[i]->socket_fd > highest_fd) 
                highest_fd = connections[i]->socket_fd;
        }

        struct timeval timeout;
        timeout.tv_sec = idle_timeout_ms / 1000;
        timeout.tv_usec = (idle_timeout_ms % 1000) * 1000;

        int activity = select(highest_fd + 1, &read_fds, NULL, NULL, &timeout);
        if ((activity < 0) && (errno != EINTR)) {
            log_event("Select error");
            break;
        }

        for (int i = 0; i < max_connections; ++i) {
            Connection *conn = connections[i];
            if (!conn || !FD_ISSET(conn->socket_fd, &read_fds)) continue;

            ssize_t len = recv(conn->socket_fd, conn->buffer, conn->buffer_size, 0);
            if (len > 0) {
                if (data_callback) data_callback(conn, conn->buffer, len);
            } else if (len == 0 || (len < 0 && errno != EWOULDBLOCK)) {
                log_event("Connection closed or error occurred");
                destroy_connection(&connections[i]);
                event_callback ? event_callback(conn) : NULL;
            }
        }

        // Handle new connections, etc. - Placeholder for integration
    }

    #ifdef _WIN32
        WSACleanup();
    #endif

    return 0;
}
```

### Key Features:
- **Cross-platform Compatibility**: Uses conditional compilation to support Unix-like and Windows platforms.
- **Dynamic Memory Management**: Allocates and frees memory for connection buffers dynamically.
- **Callback Interface**: Provides `DataCallback` and `EventCallback` for handling data reception and connection events, respectively.
- **Idle Timeout Handling**: Configurable idle timeouts using the `select` function with a timeout structure.
- **Logging**: Basic logging functionality to record events and errors.
- **Graceful Shutdown**: Properly closes sockets and frees memory on disconnections or errors.

This code serves as a starting point for managing TCP connections. You can extend it by adding more sophisticated connection handling, error recovery mechanisms, and integration with external services.']

