typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    unsigned char CRCFLAG;  // Assume it's a single byte for simplicity
} NFAPI_CRC_INDICATION_PDU_T;

void log_creation(const NFAPI_CRC_INDICATION_PDU_T* pdu, int index) {
    printf("Created PDU %d with RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
           index, pdu->crc_tag.RX_UE_INFORMATION_TAG, pdu->crc_tag.RNTI, pdu->CRCFLAG);
}

NFAPI_CRC_INDICATION_PDU_T* initialize_nfa_pi_crc_indications(int n) {
    if (n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));  // Seed the random number generator

    pthread_t threads[4];
    int num_threads = (n > 4) ? 4 : n;  // Simple load balancing
    int pdu_per_thread = n / num_threads;
    int remainder = n % num_threads;

    for (int i = 0; i < num_threads; ++i) {
        int start_index = i * pdu_per_thread + ((i < remainder) ? i : remainder);
        int count = pdu_per_thread + ((i < remainder) ? 1 : 0);

        pthread_create(&threads[i], NULL, (void*) [](void* arg) -> void* {
            auto args = *(int*)arg;
            for (int j = 0; j < args.count; ++j) {
                int idx = args.start_index + j;
                NFAPI_CRC_INDICATION_PDU_T *pdu = &args.pdu_list[idx];

                pdu->crc_tag.RX_UE_INFORMATION_TAG = rand() % 10000; // Example value
                pdu->crc_tag.RNTI = rand() % 4096;                    // Example RNTI range
                pdu->CRCFLAG = (rand() % 2);                          // Randomly set to 0 or 1

                log_creation(pdu, idx);
            }
            return NULL;
        }, new int{.pdu_list = pdu_list, .start_index = start_index, .count = count});
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return pdu_list;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int n) {
    free(pdu_list);
}
```

