}

// Pool manager structure
typedef struct {
    NFAPI_UL_AZTX_PDU_T* pool;
    int capacity;
    int count;
} PoolManager;

// Initialize the pool manager
int initialize_pool(PoolManager* manager, int max_structures) {
    pthread_mutex_lock(&pool_mutex);

    if (max_structures <= 0) {
        log_message("Error: Invalid number of structures requested");
        pthread_mutex_unlock(&pool_mutex);
        return -1;
    }

    manager->capacity = max_structures;
    manager->count = 0;

    // Allocate memory for the pool
    manager->pool = (NFAPI_UL_AZTX_PDU_T*)malloc(max_structures * sizeof(NFAPI_UL_AZTX_PDU_T));
    if (manager->pool == NULL) {
        log_message("Error: Memory allocation failed");
        pthread_mutex_unlock(&pool_mutex);
        return -1;
    }

    // Initialize each structure
    for (int i = 0; i < max_structures; ++i) {
        manager->pool[i].ue_info_tag.RX_UE_INFORMATION_TAG = rand() % 100;
        manager->pool[i].ue_info_tag.RNTI = rand() % 256;
        manager->pool[i].aztx_pdu_tag.UL_AZTX_PDU_TAG = i + 1;
        manager->pool[i].aztx_pdu_tag.TX_POWER_LEVEL = set_tx_power_level();
    }

    pthread_mutex_unlock(&pool_mutex);
    return 0; // Success
}

// Free the pool resources
void free_pool(PoolManager* manager) {
    pthread_mutex_lock(&pool_mutex);

    if (manager->pool != NULL) {
        free(manager->pool);
        manager->pool = NULL;
        manager->capacity = 0;
        manager->count = 0;
    }

    pthread_mutex_unlock(&pool_mutex);
}

// Thread-safe function to get a PDU from the pool
int get_pdu_from_pool(PoolManager* manager, NFAPI_UL_AZTX_PDU_T* pdu) {
    pthread_mutex_lock(&pool_mutex);

    if (manager->count == 0) {
        log_message("Error: Pool is empty");
        pthread_mutex_unlock(&pool_mutex);
        return -1;
    }

    *pdu = manager->pool[0]; // Retrieve the first PDU
    for (int i = 0; i < manager->capacity - 1; ++i) {
        manager->pool[i] = manager->pool[i + 1];
    }
    --manager->count;

    pthread_mutex_unlock(&pool_mutex);
    return 0;
}

// Example unit test function
void run_unit_tests() {
    PoolManager manager;

    // Test initialization with valid input
    if (initialize_pool(&manager, 10) == 0) {
        log_message("Test passed: Initialization successful");
    } else {
        log_message("Test failed: Initialization unsuccessful");
    }

    // Test getting a PDU from the pool
    NFAPI_UL_AZTX_PDU_T pdu;
    if (get_pdu_from_pool(&manager, &pdu) == 0) {
        log_message("Test passed: Retrieved PDU successfully");
    } else {
        log_message("Test failed: Failed to retrieve PDU");
    }

    // Test freeing the pool
    free_pool(&manager);
    if (manager.pool == NULL) {
        log_message("Test passed: Pool freed successfully");
    } else {
        log_message("Test failed: Pool not freed correctly");
    }
}

int main() {
    run_unit_tests();
    return 0;
}
