#define MAX_RETRIES 3

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_crc_list(int M) {
    if (M <= 0) return NULL;

    // Memory allocation with alignment to a 4-byte boundary
    NFAPI_CRC_INDICATION_PDU_T* list = 
        (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(4, M * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < M; ++i) {
        list[i].RNTI = rand() % 256;

        // Check against reserved RNTI values
        if (list[i].RNTI == RESERVED_RNTI) {
            fprintf(stderr, "Invalid RNTI encountered\n");
            free(list);
            return NULL;
        }

        RX_UE_INFORMATION_TAG ue_info;
        int success = fetch_ue_information(&ue_info, MAX_RETRIES);

        // Retry logic for fetching UE information
        while (!success && MAX_RETRIES > 0) {
            success = fetch_ue_information(&ue_info, --MAX_RETRIES);
            if (!success) fprintf(stderr, "Transient error during data retrieval. Retrying...\n");
        }

        if (!success) {
            fprintf(stderr, "Failed to retrieve UE information after retries\n");
            free(list);
            return NULL;
        }

        // Assign random CRCFLAG
        list[i].CRC_INDICATION_REL8_TAG = rand() % 256; 
        list[i].CRCFLAG = (rand() % 2) == 0 ? 1 : 0;
    }

    return list;
}
