```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000000

typedef struct Payload {
    // Define payload data structure as needed
} Payload;

typedef struct SessionContext {
    int sessionID;
    char peerAddress[64];
    time_t timeout;
    Payload *payload;
    time_t lastUpdated;
} SessionContext;

typedef struct Node {
    SessionContext context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_rwlock_t lock;
    int activeSessions;
    int expiredSessions;
} SessionList;

SessionList sessionList = {NULL, PTHREAD_RWLOCK_INITIALIZER, 0, 0};

// Helper function to create a new node
Node* createNode(int sessionID, const char* peerAddress, time_t timeout, Payload* payload) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->context.sessionID = sessionID;
    strncpy(newNode->context.peerAddress, peerAddress, sizeof(newNode->context.peerAddress) - 1);
    newNode->context.timeout = time(NULL) + timeout;
    newNode->context.payload = payload ? malloc(sizeof(Payload)) : NULL;
    if (payload && newNode->context.payload) {
        memcpy(newNode->context.payload, payload, sizeof(Payload));
    }
    newNode->context.lastUpdated = time(NULL);
    newNode->next = NULL;

    return newNode;
}

// Function to add a new session
int addSession(int sessionID, const char* peerAddress, time_t timeout, Payload* payload) {
    pthread_rwlock_wrlock(&sessionList.lock);

    // Check for existing session with the same peer address
    Node *current = sessionList.head, *prev = NULL;
    while (current != NULL) {
        if (strcmp(current->context.peerAddress, peerAddress) == 0) {
            // Merge sessions by updating timeout and payload
            current->context.timeout = time(NULL) + timeout;
            if (payload && current->context.payload) {
                memcpy(current->context.payload, payload, sizeof(Payload));
            }
            pthread_rwlock_unlock(&sessionList.lock);
            return 1; // Session merged
        }
        prev = current;
        current = current->next;
    }

    Node* newNode = createNode(sessionID, peerAddress, timeout, payload);
    if (!newNode) {
        pthread_rwlock_unlock(&sessionList.lock);
        return -1; // Memory allocation failed
    }

    if (prev == NULL) {
        sessionList.head = newNode;
    } else {
        prev->next = newNode;
    }
    sessionList.activeSessions++;

    pthread_rwlock_unlock(&sessionList.lock);
    return 0; // New session added
}

// Function to remove expired sessions
void removeExpiredSessions() {
    time_t now = time(NULL);

    pthread_rwlock_wrlock(&sessionList.lock);

    Node *current = sessionList.head, *prev = NULL;
    while (current != NULL) {
        if (now > current->context.timeout) {
            Node* toDelete = current;
            if (prev == NULL) {
                sessionList.head = current->next;
            } else {
                prev->next = current->next;
            }
            free(toDelete->context.payload);
            free(toDelete);
            sessionList.expiredSessions++;
            sessionList.activeSessions--;
            current = prev ? prev->next : sessionList.head;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_rwlock_unlock(&sessionList.lock);
}

// Function to retrieve a session by its ID
SessionContext* getSession(int sessionID) {
    pthread_rwlock_rdlock(&sessionList.lock);

    Node *current = sessionList.head;
    while (current != NULL) {
        if (current->context.sessionID == sessionID) {
            pthread_rwlock_unlock(&sessionList.lock);
            return &current->context;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&sessionList.lock);
    return NULL;
}

// Function to update the payload data of an existing session
int updatePayload(int sessionID, Payload* newPayload) {
    pthread_rwlock_wrlock(&sessionList.lock);

    Node *current = sessionList.head;
    while (current != NULL) {
        if (current->context.sessionID == sessionID) {
            if (current->context.payload) {
                memcpy(current->context.payload, newPayload, sizeof(Payload));
            } else {
                current->context.payload = malloc(sizeof(Payload));
                if (!current->context.payload) {
                    pthread_rwlock_unlock(&sessionList.lock);
                    return -1; // Memory allocation failed
                }
                memcpy(current->context.payload, newPayload, sizeof(Payload));
            }
            current->context.lastUpdated = time(NULL);
            pthread_rwlock_unlock(&sessionList.lock);
            return 0;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&sessionList.lock);
    return -1; // Session not found
}

// Function to get statistics on active and expired sessions
void getSessionStatistics(int* active, int* expired) {
    pthread_rwlock_rdlock(&sessionList.lock);

    *active = sessionList.activeSessions;
    *expired = sessionList.expiredSessions;

    pthread_rwlock_unlock(&sessionList.lock);
}
```

### Key Features:
- **Concurrency Management**: Uses `pthread_rwlock_t` for read-write locking to ensure thread safety.
- **Efficient Data Structure**: Utilizes a linked list for session management, allowing O(1) insertion and O(n) search/merge. Consider replacing with a hash table for faster lookups if necessary.
- **Memory Management**: Allocates memory dynamically for each session and its payload, ensuring efficient use of resources.
- **Session Merging**: Automatically merges sessions based on peer address to prevent duplicates.
- **Timeout Handling**: Periodically removes expired sessions to maintain system performance.

### Considerations:
- **Scalability**: The current implementation uses a linked list. For better scalability with millions of sessions, consider using a hash table or other data structures optimized for fast lookups and insertions.
- **External Data Sources**: This code does not handle external data source queries; additional mechanisms would be needed to integrate such functionality robustly.
- **Integration**: Ensure compatibility with legacy systems by defining clear interfaces and session data formats.']

