// Function to resize the PDU array when needed
void resize_pdu_array(MAC_PDU_ARRAY *array) {
    size_t new_capacity = array->capacity * 2;
    MAC_PDU_T **new_pdus = (MAC_PDU_T **)realloc(array->pdus, new_capacity * sizeof(MAC_PDU_T *));
    if (!new_pdus) {
        fprintf(stderr, "Memory reallocation failed for PDU array\n");
        exit(EXIT_FAILURE);
    }
    array->pdus = new_pdus;
    array->capacity = new_capacity;
}

// Function to add a new PDU
void add_pdu(MAC_PDU_ARRAY *array, int sequence_number, size_t payload_length, const char *data) {
    if (array->count >= array->capacity) {
        resize_pdu_array(array);
    }

    MAC_PDU_T *pdu = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for PDU\n");
        exit(EXIT_FAILURE);
    }

    pdu->header.sequence_number = sequence_number;
    pdu->payload.length = payload_length;
    pdu->payload.data = (char *)malloc(payload_length * sizeof(char));
    if (!pdu->payload.data) {
        fprintf(stderr, "Memory allocation failed for PDU payload\n");
        free(pdu);
        exit(EXIT_FAILURE);
    }

    memcpy(pdu->payload.data, data, payload_length);

    array->pdus[array->count++] = pdu;
}

// Function to update an existing PDU by sequence number
void update_pdu(MAC_PDU_ARRAY *array, int sequence_number, const char *new_data) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i]->header.sequence_number == sequence_number) {
            free(array->pdus[i]->payload.data);
            array->pdus[i]->payload.length = strlen(new_data);
            array->pdus[i]->payload.data = (char *)malloc(array->pdus[i]->payload.length * sizeof(char));
            if (!array->pdus[i]->payload.data) {
                fprintf(stderr, "Memory allocation failed for PDU payload update\n");
                exit(EXIT_FAILURE);
            }
            memcpy(array->pdus[i]->payload.data, new_data, array->pdus[i]->payload.length);
            return;
        }
    }
}

// Function to retrieve a PDU by sequence number
MAC_PDU_T *get_pdu_by_sequence(MAC_PDU_ARRAY *array, int sequence_number) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->pdus[i]->header.sequence_number == sequence_number) {
            return array->pdus[i];
        }
    }
    return NULL;
}

// Function to free the PDU array
void free_pdu_array(MAC_PDU_ARRAY *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i]->payload.data);
        free(array->pdus[i]);
    }
    free(array->pdus);
}

int main() {
    MAC_PDU_ARRAY pdu_array;
    init_pdu_array(&pdu_array);

    add_pdu(&pdu_array, 1, 5, "Hello");
    update_pdu(&pdu_array, 1, "World");

    MAC_PDU_T *retrieved_pdu = get_pdu_by_sequence(&pdu_array, 1);
    if (retrieved_pdu) {
        printf("Sequence: %d, Payload: %s\n", retrieved_pdu->header.sequence_number, retrieved_pdu->payload.data);
    }

    free_pdu_array(&pdu_array);

    return 0;
}
