// Function to dynamically allocate memory for a linked list of states
StateNode* createStateLinkedList(int* stateArray, int numStates, FSA* fsa, int lastState) {
    // Check if input is valid
    if (stateArray == NULL || fsa == NULL || numStates <= 0) return NULL;

    StateNode* head = NULL;
    StateNode* current = NULL;

    for (int i = 0; i < numStates; ++i) {
        int state = stateArray[i];

        // Validate the state
        int isValid = 0;
        for (int j = 0; j < fsa->numValidStates; ++j) {
            if (state == fsa->validStates[j]) {
                isValid = 1;
                break;
            }
        }

        if (!isValid) continue;

        // Allocate memory for a new node
        StateNode* newNode = (StateNode*)malloc(sizeof(StateNode));
        if (newNode == NULL) {
            // Free allocated nodes on failure
            while (head != NULL) {
                StateNode* temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        // Initialize the new node
        newNode->state = state;
        newNode->next = NULL;

        // Append to the linked list
        if (head == NULL) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

// Example usage and cleanup function (not part of the task)
void freeStateLinkedList(StateNode* head) {
    while (head != NULL) {
        StateNode* temp = head;
        head = head->next;
        free(temp);
    }
}
