NFAPI_CRC_INDICATION_PDU_T* manage_crc_pdu_array(size_t N) {
    pthread_t threads[10]; // Example thread count for concurrency
    size_t num_threads = sizeof(threads) / sizeof(pthread_t);

    if (N == 0) return NULL;

    srand((unsigned int)time(NULL)); // Seed the random number generator

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    size_t elements_per_thread = N / num_threads;

    for (size_t i = 0; i < num_threads; ++i) {
        // Calculate the start index and count of elements each thread will process
        size_t start_index = i * elements_per_thread;
        size_t count = (i == num_threads - 1) ? N - start_index : elements_per_thread;

        pthread_create(&threads[i], NULL, populate_crc_pdu_array, 
                       malloc(sizeof(size_t) * 2));
        *((size_t*)malloc(sizeof(size_t) * 2))[0] = start_index;
        *((size_t*)malloc(sizeof(size_t) * 2))[1] = count;
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return array;
}

void* populate_crc_pdu_array(void *arg) {
    size_t start_index = ((size_t*)arg)[0];
    size_t count = ((size_t*)arg)[1];

