void initialize_and_populate_frames(int total_frames, int num_threads) {
    if (external_network_config_api(total_frames)) {
        fprintf(stderr, "Network configuration failed\n");
        exit(EXIT_FAILURE);
    }

    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for all frames
    frames = calloc(total_frames, sizeof(NFAPI_UL_FRAME_INFO));
    if (!frames) {
        perror("Failed to allocate memory for frame array");
        exit(EXIT_FAILURE);
    }

    pthread_t threads[num_threads];
    int batch_size = (total_frames + num_threads - 1) / num_threads;

    // Create and start threads
    for (int i = 0; i < num_threads; ++i) {
        int start_index = i * batch_size;
        int *arg = malloc(sizeof(*arg));
        if (!arg) {
            perror("Failed to allocate memory for thread argument");
            continue;
        }
        *arg = start_index;

        if (pthread_create(&threads[i], NULL, initialize_frames, arg)) {
            perror("Thread creation failed");
            free(arg);
        }
    }

    // Join threads
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

