#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <stdint.h>

// Define structure types
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Memory pool node
struct PoolNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct PoolNode* next;
};

// Global memory pool and mutex for thread safety
static struct PoolNode* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Logging function prototype
void log_operation(const char *message);

// CRCFLAG calculation function prototype
int calculate_crcflag(int signal_strength, int timing_info);

// Function to initialize the memory pool
void init_pool(size_t initial_size) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < initial_size; ++i) {
        struct PoolNode* node = (struct PoolNode*)malloc(sizeof(struct PoolNode));
        if (!node) {
            log_operation("Memory allocation failed");
            break;
        }
        node->next = head;
        head = node;
    }
    pthread_mutex_unlock(&lock);
