typedef struct {
    Node* head;
    pthread_mutex_t lock;
} EventList;

// Function Declarations
EventList* initEventList();
void addEvent(EventList* list, time_t timestamp, const char* eventType, int* userIds, size_t userCount);
int removeEventByUserAndType(EventList* list, int userId, const char* eventType);
void iterateEventsAndReport(EventList* list);
void freeEventList(EventList* list);

// Function Implementations
EventList* initEventList() {
    EventList* list = (EventList*)malloc(sizeof(EventList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void addEvent(EventList* list, time_t timestamp, const char* eventType, int* userIds, size_t userCount) {
    if (!list || !eventType || !userIds) return;

    User* users = (User*)malloc(userCount * sizeof(User));
    if (!users) return;

    for (size_t i = 0; i < userCount; ++i) {
        users[i].userId = userIds[i];
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        free(users);
        return;
    }

    newNode->event.timestamp = timestamp;
    strncpy(newNode->event.eventType, eventType, sizeof(newNode->event.eventType) - 1);
    newNode->event.users = users;
    newNode->event.userCount = userCount;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->lock);
}

int removeEventByUserAndType(EventList* list, int userId, const char* eventType) {
    if (!list || !eventType) return 0;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    int removed = 0;

    while (current) {
        int match = 1;
        for (size_t i = 0; i < current->event.userCount && match; ++i) {
            if (current->event.users[i].userId != userId) {
                match = 0;
            }
        }

        if (match && strcmp(current->event.eventType, eventType) == 0) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            removed = 1;

            free(current->event.users);
            free(current);

            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return removed;
}

void iterateEventsAndReport(EventList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    int totalEvents = 0;
    double totalDuration = 0.0;
    time_t lastTimestamp = 0;

    while (current) {
        totalEvents++;
        if (lastTimestamp != 0) {
            totalDuration += difftime(current->event.timestamp, lastTimestamp);
        }
        lastTimestamp = current->event.timestamp;

        // Report user-specific stats here as needed

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    printf("Total Events: %d\n", totalEvents);
    if (totalEvents > 1) {
        printf("Average Duration Between Events: %.2f seconds\n", totalDuration / (totalEvents - 1));
    } else {
        printf("Average Duration Between Events: N/A\n");
    }
}

void freeEventList(EventList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        Node *toFree = current;
        current = current->next;
        free(toFree->event.users);
        free(toFree);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example Usage
int main() {
    EventList* eventList = initEventList();

    int userIds[] = {1, 2, 3};
    addEvent(eventList, time(NULL), "TrafficJam", userIds, 3);

    iterateEventsAndReport(eventList);

    removeEventByUserAndType(eventList, 1, "TrafficJam");
    iterateEventsAndReport(eventList);

    freeEventList(eventList);

    return 0;
}
