#define MAX_PDU_TYPE 256

typedef struct {
    int L3_PDU_TYPE;
    size_t payload_size;
    bool error_indicator;
} LAYER3_HEADER_T;

typedef struct {
    LAYER3_HEADER_T header;
    // Additional PDCP fields
} MAC_PDCP_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // RX_UE_INFORMATION_TAG definition
    // RNTI definition
    int CRCFLAG;  // Assume a simple integer for CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    MAC_PDCP_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    int insertions;
    int removals;
    int failures;
} DynamicPduArray;

// Function to initialize the dynamic array
DynamicPduArray* init_dynamic_pdu_array(size_t initial_capacity) {
    DynamicPduArray *array = malloc(sizeof(DynamicPduArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->array = calloc(initial_capacity, sizeof(MAC_PDCP_PDU_T));
    array->capacity = initial_capacity;
    array->count = 0;
    array->insertions = 0;
    array->removals = 0;
    array->failures = 0;

    return array;
}

// Function to check if the PDU already exists
bool pdu_exists(DynamicPduArray *array, LAYER3_HEADER_T header) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].header.L3_PDU_TYPE == header.L3_PDU_TYPE &&
            array->array[i].header.payload_size == header.payload_size) {
            return true;
        }
    }
    return false;
}

// Function to add a PDCP PDU
bool add_pdu(DynamicPduArray *array, MAC_PDCP_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);

    if (pdu_exists(array, pdu.header)) {
        printf("Warning: Duplicate PDU detected.\n");
        array->failures++;
        pthread_mutex_unlock(&array->lock);
        return false;
    }

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        MAC_PDCP_PDU_T *new_array = realloc(array->array, new_capacity * sizeof(MAC_PDCP_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return false; // Memory allocation failure
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    array->array[array->count++] = pdu;
    array->insertions++;

    pthread_mutex_unlock(&array->lock);
    return true;
}

// Function to remove a PDCP PDU by index
bool remove_pdu(DynamicPduArray *array, size_t index) {
    if (index >= array->count) return false;

    pthread_mutex_lock(&array->lock);

    memmove(&array->array[index], &array->array[index + 1],
            (array->count - index - 1) * sizeof(MAC_PDCP_PDU_T));
    array->count--;
    array->removals++;

    pthread_mutex_unlock(&array->lock);
    return true;
}

// Function to retrieve a PDCP PDU by index
MAC_PDCP_PDU_T* get_pdu(DynamicPduArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->lock);
    MAC_PDCP_PDU_T *pdu = &array->array[index];
    pthread_mutex_unlock(&array->lock);

    return pdu;
}

// Function to create CRC indication PDUs
void create_crc_indications(NFAPI_CRC_INDICATION_PDU_T **cpcs, size_t count) {
    *cpcs = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < count; ++i) {
        (*cpcs)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
        // Populate other fields as needed
    }
}

// Cleanup function
void cleanup_dynamic_pdu_array(DynamicPduArray *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}
