    char *payload;
    size_t payload_size;
    char *metadata;
    size_t metadata_size;
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
} NetworkPacket;

typedef struct PacketNode {
    NetworkPacket packet;
    int priority; // Higher value means higher priority
    struct PacketNode* next;
} PacketNode;

typedef struct {
    PacketNode* head;
    pthread_mutex_t lock;
} PacketQueue;

// Function prototypes
void initialize_packet_queue(PacketQueue *queue);
void enqueue_packet(PacketQueue *queue, NetworkPacket packet, int priority);
NetworkPacket dequeue_packet(PacketQueue *queue);
void adjust_max_packet_size(size_t current_load);
int is_valid_packet(const NetworkPacket* packet);

// Initialize the packet queue with a mutex lock for thread safety
void initialize_packet_queue(PacketQueue *queue) {
    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
}

// Enqueue a packet into the queue based on priority
void enqueue_packet(PacketQueue *queue, NetworkPacket packet, int priority) {
    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) {
        perror("Failed to allocate memory for packet node");
        return;
    }

    new_node->packet = packet;
    new_node->priority = priority;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    PacketNode **tracer = &(queue->head);

    while (*tracer && (*tracer)->priority >= priority) {
        tracer = &((*tracer)->next);
    }

    new_node->next = *tracer;
    *tracer = new_node;
    pthread_mutex_unlock(&queue->lock);
}

// Dequeue the highest priority packet
NetworkPacket dequeue_packet(PacketQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        NetworkPacket empty_packet = {0};
        return empty_packet;
    }

    PacketNode* node_to_remove = queue->head;
    NetworkPacket packet = node_to_remove->packet;

    queue->head = node_to_remove->next;
    free(node_to_remove);

    pthread_mutex_unlock(&queue->lock);
    return packet;
}

// Adjust maximum packet size based on current load
void adjust_max_packet_size(size_t current_load) {
    // Logic to adaptively set max packet size; placeholder example:
    const size_t base_size = 1500; // Default MTU
    size_t adaptive_size = base_size + (current_load * 10); // Simplified logic

    printf("Adjusting max packet size to: %zu bytes\n", adaptive_size);
}

// Validate a network packet's structure
int is_valid_packet(const NetworkPacket* packet) {
    if (!packet || !packet->payload || !packet->crc_pdu.RX_UE_INFORMATION_TAG) {
        return 0; // Invalid packet
    }

    // Additional validation checks can be added here

    return 1; // Valid packet
}

// Main function for testing and demonstration purposes
int main() {
    PacketQueue queue;
    initialize_packet_queue(&queue);

    NetworkPacket sample_packet = {
        .header = "Header",
        .header_size = strlen("Header"),
        .payload = (char*)"Payload",
        .payload_size = strlen("Payload"),
        .metadata = "Metadata",
        .metadata_size = strlen("Metadata"),
        .crc_pdu = {12345, 67890, {rand() % 2}}
    };

    enqueue_packet(&queue, sample_packet, 5);

    NetworkPacket dequeued_packet = dequeue_packet(&queue);

    if (is_valid_packet(&dequeued_packet)) {
        printf("Processed valid packet with CRCFLAG: %d\n", dequeued_packet.crc_pdu.CRC_INDICATION_REL8_TAG.CRCFLAG);
    } else {
        fprintf(stderr, "Encountered invalid packet structure.\n");
    }

    return 0;
}
