#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define CACHE_LINE_SIZE 64

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_entries;
} NFAPI_List;

int initialize_list(NFAPI_List* list, size_t max_entries) {
    if (!list) return -1;

    list->head = NULL;
    list->count = 0;
    list->max_entries = max_entries;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void destroy_list(NFAPI_List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

static inline void* aligned_alloc(size_t size, size_t alignment) {
    void* ptr = NULL;
    if (posix_memalign(&ptr, alignment, size)) return NULL;
    return ptr;
}

int insert_pdu(NFAPI_List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= list->max_entries) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return -2; // RNTI already exists
        }
        current = &(*current)->next;
    }

    Node* new_node = aligned_alloc(sizeof(Node), CACHE_LINE_SIZE);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Memory allocation failed for new node\n");
        return -3; // Allocation failure
    }

    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
    list->count++;
    return 0;
}

int remove_pdu(NFAPI_List* list, uint16_t rnti) {
    if (!list || !list->head) return -1;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.RNTI == rnti) {
            Node* to_free = *current;
            *current = (*current)->next;
            free(to_free);
            pthread_mutex_unlock(&list->lock);
            list->count--;
            return 0; // Successfully removed
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // RNTI not found
}

void log_operation(const char* operation, int result) {
    fprintf(stdout, "%s: %s\n", operation, (result == 0) ? "Success" : "Failure");
}

