int add_to_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t *size, size_t capacity, unsigned int new_rnti, unsigned int new_rx_ue_information_tag) {
    if (*size >= capacity || (!is_unique(*list, *size, new_rnti, new_rx_ue_information_tag))) {
        log_error("Duplicate RNTI or RX_UE_INFORMATION_TAG detected");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (*size + 1));
    if (!new_list) {
        log_error("Memory allocation failed");
        return -1;
    }

    *list = new_list;
    NFAPI_CRC_INDICATION_PDU_T *entry = &((*list)[*size]);

    entry->RX_UE_INFORMATION_TAG = new_rx_ue_information_tag;
    entry->RNTI = new_rnti;
    entry->CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();

    if (*size > 0 && ((*list)[*size - 1]).RNTI == new_rnti) {
        log_error("Consecutive RNTIs are the same");
        return -1;
    }

    (*size)++;
    return 0;
}

