    if (initial_capacity == 0 || initial_capacity > MAX_LIST_SIZE) {
        *error_code = -1;
        log_error("Invalid initial capacity");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (!list) {
        *error_code = -1;
        log_error("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed random number generator
    *error_code = 0;

    return list;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    if (*list) {
        free(*list);
        *list = NULL;
    }
