                pthread_mutex_unlock(&lock);
                free(*nfa_list);
                free(rnti_pool);
                return -1;
            }
        }

        // Ensure non-consecutive RNTI
        while (used_rntis[rnti_index] || 
               (i > 0 && (*nfa_list)[i].RNTI == (*nfa_list)[i-1].RNTI)) {
            if (++rnti_index >= rnti_pool_size) {
                if (expand_rnti_pool(&rnti_pool, &rnti_pool_size) != 0) {
                    fprintf(stderr, "Failed to expand RNTI pool\n");
                    pthread_mutex_unlock(&lock);
                    free(*nfa_list);
                    free(rnti_pool);
                    return -1;
                }
            }
        }

        (*nfa_list)[i].RNTI = rnti_pool[rnti_index];
        used_rntis[rnti_index] = 1;

        // Randomly set CRCFLAG
        (*nfa_list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&lock);
    free(rnti_pool);

    return 0;
}

// Unit tests
void test_create_nfa_list() {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list;

    if (create_nfa_list(&nfa_list, MAX_ELEMENTS) != 0) {
        printf("Test failed: Error creating NFA list\n");
        return;
    }

    // Check uniqueness of RX_UE_INFORMATION_TAG
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
