            }
        }
    }

    // Check non-consecutive RNTI
    for (size_t i = 1; i < MAX_ELEMENTS; ++i) {
        if (nfa_list[i].RNTI == nfa_list[i-1].RNTI) {
            printf("Test failed: Consecutive RNTI found\n");
            free(nfa_list);
            return;
        }
    }

    printf("All tests passed successfully.\n");
    free(nfa_list);
}

int main() {
    test_create_nfa_list();
    return 0;
}
