    if (request_count >= MAX_AUTH_REQUESTS_PER_SECOND) {
        printf("Rate limit exceeded for user: %s\n", user_id);
        pthread_mutex_unlock(&auth_lock);
        return;
    }

    request_count++;
    if (difftime(current_time, *(time_t *)pthread_getspecific(auth_key)) > 1.0) {
        request_count = 1;
        pthread_setspecific(auth_key, &current_time);
